pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Medium gaps (10..20) are risky: only next items <= gap can use them.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // If lookahead item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 80.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }
    // Lookahead cannot use this bin's leftover: penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage scattering across many bins, but keep
    // pressure mild so dead-space penalty dominates.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // it is a good "garbage collector" bin.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.3 * diff.min(50.0);
    } else {
        score += 0.15 * (-diff).min(50.0);
    }

    // New-bin candidate: make empty bin attractive only when the item is
    // huge (poor fit anywhere) or many bins are open with low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let huge_item = item_size > 70;
        if huge_item || (open_bins_count > 6 && mean_residual < item_size as f64) {
            score -= 55.0 + 20.0 * progress;
        } else {
            // Default: discourage opening new bins.
            score += 45.0 + 10.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap below the minimum plausible item size (1..100 stream => treat <20 as near-dead).
    if post_residual > 0 {
        let dead = (20u32).saturating_sub(post_residual) as f64;
        score += 6.0 * dead * dead; // quadratic wall on tiny residuals
        // If the gap cannot fit the known next item, it is likely dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
            // Extra penalty if it cannot fit even the smallest typical item.
            if post_residual < 10 {
                score += 25.0;
            }
        }
        // Perfect fit: zero waste, reward strongly.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin content.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 0.15 * open_bins_count as f64 + 10.0 * progress;
        // But if no open bin fits well, allow opening: soften when mean residual is high.
        score -= 0.05 * mean_residual;
    } else {
        // Mild preference to use already-open bins when many are open.
        score -= 0.02 * open_bins_count as f64;
    }

    // Lookahead: if placing here leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Even better: leaves room for next item AND next item's likely follow-up.
        if post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items (1..=12) are effectively wasted capacity.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual > 12 && post_residual <= 20 {
        score += 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score -= 6.0;
    }

    // Perfect / near-perfect fits are extremely valuable.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Reward tight relative fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to available residuals or fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64) < 15.0;
        let huge_item = item_size as f64 > 0.75 * bin_capacity as f64;
        if poor_fit || huge_item {
            score -= 55.0;
        } else {
            score += 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual <= 12 {
        score += 10.0; // would strand a dead gap the next item can't use
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (consolidating small leftovers into tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // tiny unusable slivers
        } else if post_residual <= 20 {
            score += 8.0; // hard-to-fill zone
        } else {
            // larger residuals are reusable; mild reward scaled by usability
            score -= (post_residual.min(50) as f64) * 0.15;
        }
    } else {
        score -= 40.0; // perfect fit: strongly favored
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += open_bins_count as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 100.0);
        } else if post_residual > 0 {
            score += 6.0; // next item can't use this bin's remainder
        }
    }

    // New-bin candidate: only attractive when current bins would leave bad
    // dead space and the next item is small enough to join this item later.
    if bin_residual == bin_capacity {
        score = 30.0
            + (mean_residual - post_residual as f64).max(0.0) * 0.5
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 };
        // early in the stream, opening fresh bins is cheaper
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to be
    // useful are heavily penalized. A gap is "dead" if it cannot hold even the
    // smallest plausible follow-up item (or the known next item).
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 30 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 * (min_useful - post_residual) as f64;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if next item can no longer fit in this bin but fit elsewhere before.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward large residual bins being filled (consolidate fullness).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than opening new bins.
    score += 2.0 * open_bins_count as f64;

    // Mean-residual coupling: if the fleet of open bins is already slack,
    // penalize adding more slack to an already loose bin.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // unattractive unless the current fit is truly terrible (large dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if placing here would waste most of a partially-filled bin,
        // the fresh bin becomes relatively attractive.
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 70.0;
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // tight fits since fewer future opportunities remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (or below a typical minimum item size) are nearly worthless.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 30.0 * (min_useful as f64 - post_residual as f64);
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is a good multiple match for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 8.0 * pressure;
        // Early in the stream, opening a new bin is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 3.0 * pressure;
    }

    // Prefer bins with residual below the mean (denser bins) slightly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
