        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / 10.0;
        score += 25.0 - crowding * 10.0;
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Early stream: slightly more willing to open bins; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

