    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tight fit relative to residual: prefer bins where item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is close to the item (avoid wasting large residual bins on small items).
    score += 0.25 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        if big_item || poor_fit {
            score -= 10.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item barely misses, slight penalty for stranding space.
    if next_item_size > post_residual && next_item_size - post_residual <= 3 && post_residual > 0 {
        score += 5.0;
    }

    // Mild attraction to bins below mean residual (consolidate emptier bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
