    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // near-dead sliver: bad fragmentation
        } else {
            // Usable gap: reward it, more so if it can host the lookahead item.
            let gap_util = post_residual as f64 / bin_capacity as f64;
            score -= 15.0 * gap_util;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0; // gap chains with next item: excellent
            } else if next_item_size > 0 {
                score += 5.0; // next item won't fit here
            }
