    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many candidate bins
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // Extra reward for near-exact pairing
        if post_residual == next_item_size {
            score -= 120.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here anyway; neutral
        score += 10.0;
    }

    // Global state: if mean residual is high, prefer consolidating into bins with large residuals
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 20.0 * (rel - 1.0);
        } else {
            score += 20.0 * (1.0 - rel);
        }
    }

    // Time horizon: early in the stream, be more open to new bins; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * fill;

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when open bins have poor fits
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0;
        // Late in the stream, opening new bins is cheaper than wasting residual space
        score -= 30.0 * progress;
        // Don't open a new bin if the next item is huge and current item is small
        if next_item_size > 60 && item_size < 30 {
            score += 40.0;
        }
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly fits the next item,
    // penalize leftovers that are just barely too small for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 500.0; // perfect 2-step chain
        } else if post_residual < next_item_size {
            // dead space relative to next item: the smaller the gap to next item,
            // the more painful (just missed a chain).
            let gap = next - post_residual as f64;
            score += gap * (1.0 + 20.0 / gap.max(1.0));
        } else {
            // leftover can host next item: mild reward scaled by tightness
            score -= (next / (post_residual as f64)) * 30.0;
        }
    }

    // Penalize small unusable residuals (< typical min item size) unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Reward placing into bins with residual below mean (tightening large gaps),
    // penalize draining bins that are already tight (waste of a good small bin).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // unless the fit is terrible; also makes new-bin fallback less attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it competitive only when current bin fit is bad.
    if bin_residual == bin_capacity {
        // neutral-ish base for an empty bin; slight preference to consolidate early.
        score += 20.0;
        if post_residual as f64 > mean_residual + 40.0 {
            score -= 60.0; // opening a fresh bin is fine if nothing fits well
        }
    }

    // Late in the stream, prefer closing bins tightly (reduce bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post_residual gaps are almost unusable.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 18.0 } else if post_residual < 30 { 6.0 } else { 0.0 };
        score += dead;
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Tightness bonus: fraction of bin used by this placement
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill;

    // Reward when this bin's residual exactly matches the next item (lookahead synergy)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / cap;
        }
    }

    // Open-bin pressure: prefer consolidating when many bins are open
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only if it avoids bad fits
    if bin_residual == bin_capacity {
        // fresh bin: baseline cost of opening a new bin, softened when stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.5 * cap + 20.0 * (1.0 - progress) - 15.0 * (1.0 - fill);
        // if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // penalize existing bins whose residual deviates badly from mean
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit: near-free placement.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Strict dead-space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 90.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Penalize residuals that no plausible item (>= ~10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Bonus if the next item exactly fits the post residual (chaining fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; small penalty for leaving large leftovers.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, be more tolerant.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    score += pressure * (post_residual as f64) * 0.08;

    // Prefer bins with below-average residual (fill emptier-of-space bins first,
    // keeping large residuals consolidated).
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: default moderate score; becomes attractive only when
    // this item would leave a large awkward gap in every existing bin.
    if bin_residual == bin_capacity {
        let awkward_elsewhere = if fitting_bins_count > 0 {
            // would any open bin give a good fit?
            0.0
        } else {
            -60.0
        };
        let base = 55.0 + 0.35 * (item_size as f64) + 4.0 * (open_bins_count as f64).min(20.0) as f64;
        score = base + awkward_elsewhere;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Tight fit reward: the smaller the gap relative to the item, the better.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 40.0 * fit_ratio;

    // Penalize mid-range unusable gaps that few item sizes can fill.
    if post_residual > 0 && post_residual < 35 {
        score += 0.9 * (35.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bins fit poorly or mean residual is low.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (fit_ratio < 0.6 && mean_residual < item_size as f64 * 1.3);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Slight preference for bins below mean residual (balancing across bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small unusable gaps (1..10) are heavily penalized,
    // moderately small gaps (11..20) mildly penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer closing out bins rather than
    // spreading items thinly; scale with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }
    // Penalize placements that leave a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open or
        // mean residual is low (existing bins are nearly full).
        score = 45.0 + open_bins_count as f64 * 1.5 - mean_residual * 0.3;
        // Cheaper to open a new bin late in the stream.
        score -= 20.0 * progress;
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive targets
    // when mean is low (avoid fragmenting), more attractive when mean is high.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * (if mean_residual < 25.0 { 0.4 } else { -0.2 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        // gap only usable for very small future items: partially dead
        score += 18.0;
    }

    // Reward tight fits (small waste relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // next item would leave a dead sliver: mild penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by open-bin pressure.
        score += 30.0 + 3.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is fine (builds diversity of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the item fits poorly everywhere else (few fitting bins), new bin is attractive.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If next item is large and this item is small, prefer existing bins to keep big gaps.
        if next_item_size > 60 && item_size < 30 {
            score += 25.0;
        }
    } else {
        // Pressure from too many open bins: favor consolidating into existing bins.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to the item (best-fit flavor) via mean residual anchoring.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 60.0;

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else {
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot use the leftover (dead space risk)
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating very small unusable residuals when many bins are open
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Time horizon: early in stream, prefer consolidating into existing bins;
    // late in stream, allow opening new bins when fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current bins have poor fit
        let poor_fit_penalty = (post_residual as f64) * 0.5;
        score += 120.0 - 80.0 * progress;
        score -= poor_fit_penalty * 0.0; // new bin residual is full capacity, keep base
        // Discourage opening new bins when mean residual across open bins is large
        score += mean_residual * 0.6;
        // Fewer open bins -> cheaper to open a new one
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins with residual close to mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // Prefer fuller bins (smaller residual) slightly more as stream progresses
        score -= (bin_capacity - bin_residual) as f64 * 0.2 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: quadratic penalty on wasted space, slightly softened by progress
    // (later in the stream, tight fills matter more, so weight grows).
    let mut score = post * post / cap * (0.5 + 1.5 * progress) + post;

    // Reward perfect/near-perfect fits super-linearly.
    if post == 0 {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize residuals that are unusable relative to the lookahead item:
    // if next item cannot fit here, residual is dead space.
    if next > 0.0 && post < next {
        let deadness = (next - post) / cap;
        score += 30.0 * deadness * deadness * cap + 10.0 * progress;
    } else if next > 0.0 && post >= next {
        // Reward leaving exactly enough room for the next item (chaining).
        let tightness = 1.0 - (post - next) / cap;
        score -= 8.0 * tightness * tightness;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        score += 0.15 * post as f64;
    }

    // Mildly discourage scattering across many bins when this bin is roomy.
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Deviation from mean residual: prefer bins whose fill differs from average
    // (keeps a diversity of residual sizes for future items).
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate (empty bin): neutral-ish baseline so it wins only
    // when all open bins give bad fits.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 0.05 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Next item fits into the post residual: strong reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.15 * slack;
    }

    // Post residual is dead space: next item cannot use it.
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual).min(bin_capacity) as f64;
        score += 0.35 * waste;
    }

    // Penalize very small unusable remnants (dead space < typical min item).
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins that are already relatively full (small residual).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New empty bin candidate: penalize unless current open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        let poor_fit = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 12.0 * crowded - 10.0 * (1.0 - poor_fit);
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
