            score -= 40.0 / (1.0 + lookahead_gap / 10.0);
        }
        // If next item cannot fit in post_residual, mild penalty for wasted slot
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual) which base score does
        score -= 5.0;
    }

    // Compare post_residual relative to mean residual across open bins
    let mean_gap = post_residual as f64 - mean_residual;
    // Leaving less than average residual is good (denser packing)
    score += 0.5 * mean_gap;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when plenty of open bins exist with room
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of opening a bin
        score += 55.0;
        // If next item could pair with current item in this fresh bin, soften the cost
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // Fewer open bins -> opening a new one is more acceptable
        score -= 4.0 * open_bins_count as f64;
    } else {
        // Reward using already-open bins, more so when many are open
        score -= 2.0 * open_bins_count as f64;
    }

    // Small penalty for creating awkward dead space (residual too small to be useful)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that become exactly full.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the next item exactly matches the post residual.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 400.0; // chain fit: this bin then perfectly holds next item
        } else if diff > 0.0 {
            // next item fits in the leftover; the smaller the leftover slack, the better
            score -= 200.0 / (1.0 + diff / 20.0);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += (-diff) * 0.8;
        }
    }

    // Compare post_residual against the mean residual across open bins.
    // Leaving a residual well below mean wastes capacity; being close to mean is neutral.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    } else {
        score += mean_gap * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large unusable dead space (item nearly fills a new bin).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual as f64 <= next_item_size as f64 {
            score -= 150.0 * tightness; // new bin pairs well with next item
        }
        // Penalize opening a new bin when it is not a near-perfect fill
        score += (1.0 - tightness) * 60.0;
        // As the stream progresses, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference for filling larger-residual bins first (best-fit style),
    // scaled by how many bins are open (avoid fragmentation when many bins exist).
    score -= (bin_residual as f64 / bin_capacity as f64) * (5.0 + open_bins_count as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // dead space relative to next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize tight-but-wasteful fits (small post_residual that isn't 0)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin fits are poor
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 60.0;
        // open it if existing bins would leave lots of dead space
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 >= 0 {
            // a fresh bin fits both current and next item nicely
            score -= 40.0;
        }
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early in stream, be slightly more willing to open bins (spread risk)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly damped by progress
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of post-residual with stream progress
    let t = progress;
    let poly = t * t - 2.0 * t + 1.0; // (1-t)^2
    score -= 8.0 * poly * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 4.0 * (nx - pr) * (1.0 + t);
        } else {
            score -= 2.0 * (1.0 - nx / cap) * t;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Penalize spreading across many open bins when residuals are fragmented
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2);

    // New-bin candidate: keep it slightly unattractive unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize wasted residual more as stream progresses
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Dead-space penalty: residual too small for lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let dead = (nxt - pr).max(0.0);
        if dead > 0.0 {
            // unusable gap; penalize smoothly, stronger later in stream
            score += dead * (1.0 + progress) * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * item_size as f64 * 0.5;

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // New-bin candidate: neutral baseline, mildly discouraged early, encouraged when
    // open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        score = cap * 0.5;
        score -= open_bins_count as f64 * 0.5;
        score += mean_residual * 0.3;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0; // fragmentation suggests fresh bin is useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fractions (quarters) and modulo structure.
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4; // 25 with C=100
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals that are too small to hold any
    // plausible future item (below the smallest common class) are waste.
    if post_residual < 10 {
        score += 60.0 - pr * 3.0;
    }

    // Harmonic class rewards: residual exactly matching a capacity fraction
    // or a modulo-friendly value is more reusable.
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Residuals just above a "harmonic threshold" (e.g. 50, 25) are awkward:
    // too big to waste but barely below common item classes.
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.5;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainable placement: reward proportional to tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize if the leftover becomes dead space.
            score += (next_item_size as f64 - pr) * 0.4;
        }
        // Harmonic class match between next item and post-residual modulo class.
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (consolidation pressure) and early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 - 10.0 * progress - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Empty bin is great for very large items (poor fits elsewhere).
        if item_size > half {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item completes a fresh bin perfectly
        }
    }

    // Mild consolidation: prefer bins whose residual is below the mean
    // (filling the emptier-feeling bins keeps many tight bins around).
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr;
        score += dev * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 interface).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // tiny dead space: strong penalty, quadratic in tightness
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor tighter bins
    // (small residual) when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild preference for bins tighter than the mean residual (good fits).
    score += (post_residual as f64 - mean_residual) * 0.3 * (0.5 + progress);

    // New-bin candidate handling: make a fresh bin mildly unattractive by default,
    // but attractive when no open bin fits well (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        let base = 45.0 + pressure * 3.0;
        // If the only alternative would leave big dead space, allow opening.
        if fitting_bins_count == 0 {
            score = base - 100.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // If the next item exactly fills this bin's post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after two items
        } else if next_item_size < post_residual {
            // Next item fits too: reward proportional to how tightly it nests,
            // and extra reward if the pair leaves a "nice" residual (small or large).
            let two_step = post_residual - next_item_size;
            let tight = 1.0 - (two_step as f64 / bin_capacity as f64);
            score -= 12.0 + 25.0 * tight;
            // Bonus if the two-step leftover is a commonly usable size (>= 10)
            if two_step >= 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how isolated this bin is among fitting options.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully.
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r {
        // Tighter than average bin: placing here consolidates fullness.
        score -= 6.0 * (mean_r - bin_residual as f64).min(30.0) / 30.0;
    } else {
        // Looser than average: mild penalty to avoid fragmenting many bins.
        score += 3.0 * ((bin_residual as f64) - mean_r).min(30.0) / 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // the item is huge relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (1.0 + total_items as f64));
        // Large items prefer fresh bins (near-perfect packing); small items prefer reuse.
        score += 55.0 * (1.0 - frac) - 10.0 * pressure.min(5.0);
        // If the next item is small and would pair well in a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight stream-position adaptation: early on, be more willing to open bins
    // (keep flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it when existing residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 - 10.0 * progress - 0.05 * fragmentation - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (fill the emptier-feeling bins less,
    // keep balanced residuals): slight pull toward mean.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space class penalty: residual in "unusable" bands (e.g. > 50% wasted is fine, tiny slivers are bad)
    // Tiny slivers (1..10) are nearly dead: penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: harmonic classes mod 10
    // Residuals that are multiples of 10 are "harmonic" — likely to host future items (sizes 10..80)
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Coupling with next_item_size: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let after = post_residual - next_item_size;
            // reward smooth chaining, penalize creating another sliver
            if after == 0 {
                score -= 30.0;
            } else if after < 10 {
                score += 10.0;
            } else {
                score -= (after / 10) as f64 * 2.0;
            }
        } else {
            // next item won't fit here: this bin becomes dead after placement
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad,
    // but relax when many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 20.0;
        // If open bins are fragmented (high mean residual but none fit well), opening is OK
        new_bin_score -= (mean_residual / cap) * 10.0;
        // Late in stream, slightly prefer consolidating
        new_bin_score += progress * 5.0;
        // Many open bins: encourage opening fresh ones to keep options
        new_bin_score -= (open_bins_count.min(20) as f64) * 0.5;
        score = score.min(new_bin_score) + if bin_residual == bin_capacity { new_bin_score * 0.0 } else { 0.0 };
        score = new_bin_score;
    }

    // Global waste pressure: bins far below mean residual usage get slight penalty
    score += ((pr - mean_residual) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else {
        // Small but potentially usable gaps: mild penalty scaled by how tight the fit is.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * tightness;
    }

    // Penalize large leftover gaps that are likely to strand space (fragmentation risk),
    // but less harshly than dead space.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.35;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when mean residual is already low.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.4;
        // Prefer bins whose residual deviates from the mean toward tighter fits.
        score += (mean_residual - bin_residual as f64).abs() * 0.1;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Late in the stream, prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near match: next item still fits after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64; // tighter leftover preferred
        score -= 50.0; // bonus for keeping chain alive
    } else if next_item_size > 0 {
        // next item won't fit here afterwards: penalize proportionally to wasted lookahead
        let gap = next_item_size - post_residual;
        score += gap as f64 * 2.0;
    }

    // Penalize small unusable dead space relative to typical item sizes
    if post_residual > 0 {
        score += 30.0 * (1.0 - post_residual as f64 / 100.0).powi(3);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer bins tighter than average (good fits), discourage very loose bins
    score -= (mean_residual - post_residual as f64) * 1.5;

    // New-bin candidate: only attractive when it enables a good future chain
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 80.0 * (1.0 - progress); // early on, fresh bins with chain potential are fine
        } else {
            score += 150.0; // avoid new bins late or when no chain possible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would not fit here: penalize wasted space relative to next item
            score += 50.0 + diff * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Compare residual to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize large dead space (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // small but likely unusable gap -> fine, nearly perfect fit
    }
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.8; // large gap wasted
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only prefer it when item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening a new bin is attractive for big items or when no open bin fits well
        score += 60.0 - 80.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better, with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to hold the next item (or typical items).
    let min_useful = if next_item_size > 0 { next_item_size.min(100) } else { 20 };
    if post_residual > 0 && (post_residual as u64) < (min_useful as u64) {
        score += 12.0 * (min_useful as f64 - post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if next item fits snugly too.
        let post2 = post_residual - next_item_size;
        score -= 3.0 * (1.0 - post2 as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize blocking the next item slightly.
        score += 2.0 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild penalty to prefer best-fit elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins that are already relatively empty of capacity
    // (avoid spreading load across many lightly-filled bins).
    score += 2.0 * ((bin_residual as f64) / (bin_capacity as f64) - (mean_residual / bin_capacity as f64)).abs();

    // Early in stream: be more willing to open new bins (exploration);
    // late in stream: consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins as stream matures,
        // and more when many bins are already open.
        score += 10.0 * progress + 0.4 * open_bins_count as f64;
        // Allow opening new bin early or when fit would be terrible.
        if post_residual < 10 && progress < 0.7 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward consolidation late in the stream.
        score -= 4.0 * progress;
    }

    // Mild penalty proportional to overall open-bin count to encourage packing density.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
