    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // New-bin candidate: baseline cost, cheaper only when mean residual across open bins is low
    // (open bins are nearly full, so a fresh bin is justified).
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.6;
    } else {
        // Slight preference for bins whose residual is close to the item (best-fit flavor).
        score -= (bin_residual as f64 - item_size as f64).abs() * -0.0;
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
