    score += 0.035 * pr * pr / cap;

    // Cubic coupling with stream progress: late in the stream, waste is costlier.
    let g = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += (0.02 + 0.05 * progress) * pr * pr * pr / (cap * cap);
    score -= 1.5 * g * pr; // mid-stream smoothing term

    // Reward tight fits relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let tight = 1.0 - (pr / mean_residual).min(2.0);
        score -= 3.0 * tight * (item_size as f64 / cap);
    }

    // Lookahead: bonus if the next item fits the post-residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 2.5 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across many bins when residuals are already large.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Slight preference for filling existing bins over opening new ones late.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
