        } else {
            // Next item cannot fit in post_residual: penalize leaving that gap.
            score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: keep residuals homogeneous,
    // penalize creating outliers (large residual = wasted space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.8 * dev;
    }

    // Penalize large residual gaps that no plausible item (>=1) can exploit well.
    score += 0.3 * pr;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in stream: be frugal, prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless current bins are fragmented
        // (mean residual high relative to item) or stream is late.
        score += 300.0;
        score -= 250.0 * progress;
        if mean_residual > item_size as f64 * 1.5 {
            score -= 100.0;
        }
    } else {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks (non-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: favor bins whose post_residual can still host the next item,
    // but only if the next item is large (waste of capacity matters more).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 4.0 * (nxt / 100.0);
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += 3.0 * (1.0 - nxt / 100.0);
        }
        // Perfect chain: post_residual exactly matches next item size
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual low) or stream is early and many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Fresh bin: base penalty so it loses to reasonable fits...
        score += 18.0;
        // ...but discount when open bins have little room left or many bins open.
        let crowding = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 25.0 * crowding * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative at all
        }
    }

    // Prefer spreading load across many open bins slightly (keeps residuals usable).
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild time-horizon coupling: late in the stream, tighten packing more aggressively.
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Penalize large dead space more aggressively late in the stream (cubic term)
    score += cap * norm_post * norm_post * norm_post * (2.0 + 3.0 * progress);

    // Reward tight fits (small post_residual) especially when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 4.0 * progress;
    }

    // Prefer fuller bins relative to the mean residual of open bins
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

    // Mild penalty for spreading across many open bins early in the stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // New-bin candidate: make it mildly attractive only when fits are poor
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        score = pr - 10.0 * (1.0 - tightness) * (1.0 - progress) + 15.0 * progress * norm_post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Class 0: post_residual divisible by 10 (ideal slots for 10..80 range items)
    // Class 1: divisible by 5, Class 2: even, Class 3: odd (worst)
    let harmonic_class = match (post_residual % 10, post_residual % 5, post_residual % 2) {
        (0, _, _) => 0,
        (_, 0, _) => 1,
        (_, _, 0) => 2,
        _ => 3,
    };
    score += harmonic_class as f64 * 2.5;

    // Integer-division thresholds: dead-space buckets of post_residual
    let dead = post_residual / 10; // number of complete 10-slots wasted
    score += (dead * dead) as f64 * 0.8;

    // Reward tight fits (small post_residual)
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Lookahead coupling: does post_residual leave a slot for next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving exactly a harmonic-compatible slot for next item
            let slot_gap = post_residual - next_item_size;
            if slot_gap % 10 == 0 {
                score -= 8.0;
            } else if slot_gap % 5 == 0 {
                score -= 4.0;
            }
            if slot_gap == 0 {
                score -= 10.0; // perfect two-item chain
            }
        } else {
            // Post-residual smaller than next item: penalize by dead-space ratio
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer opening a fresh bin when the
    // current fit is poor (large odd dead space) or bin is nearly full anyway.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual % 2 == 1 && post_residual > 20;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if poor_fit || post_residual > 40 {
            score -= 10.0 + 5.0 * progress;
        } else {
            // Prefer reusing existing bins early/mid stream
            score += 25.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Mild pressure toward consolidating into fewer bins
    score += mean_residual * 0.05 - open_bins_count as f64 * 0.2;

    // Progress-scaled tightness bonus: later in stream, be greedier
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in the "unusable" band
    // (too small for the smallest plausible future item) is pure waste.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, favor it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // post_residual can't host the next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins fragment capacity; penalize spreading.
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already fragmented; slight penalty for making it worse.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1;
    }

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large or the current bin would leave a big awkward gap.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if waste < 20.0 {
            score -= 10.0; // large item into fresh bin is fine
        } else {
            score += 5.0; // discourage opening bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly fits the next item,
    // penalize leftovers that are just barely too small for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 500.0; // perfect 2-step chain
        } else if post_residual < next_item_size {
            // dead space relative to next item: the smaller the gap to next item,
            // the more painful (just missed a chain).
            let gap = next - post_residual as f64;
            score += gap * (1.0 + 20.0 / gap.max(1.0));
        } else {
            // leftover can host next item: mild reward scaled by tightness
            score -= (next / (post_residual as f64)) * 30.0;
        }
    }

    // Penalize small unusable residuals (< typical min item size) unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 10.0;
    }

    // Reward placing into bins with residual below mean (tightening large gaps),
    // penalize draining bins that are already tight (waste of a good small bin).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // unless the fit is terrible; also makes new-bin fallback less attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it competitive only when current bin fit is bad.
    if bin_residual == bin_capacity {
        // neutral-ish base for an empty bin; slight preference to consolidate early.
        score += 20.0;
        if post_residual as f64 > mean_residual + 40.0 {
            score -= 60.0; // opening a fresh bin is fine if nothing fits well
        }
    }

    // Late in the stream, prefer closing bins tightly (reduce bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;  // hard-to-fill zone
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 18.0 / (1.0 + gap as f64);
            if gap == 0 {
                score -= 30.0; // perfect chaining
            }
        } else {
            // post_residual cannot host next item; slight penalty unless it's near zero.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, prioritize exact packing since future value of space is low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into bins below average residual (fill the emptiest-feeling useful bins).
    if open_bins_count > 0 {
        let residual_dev = bin_residual as f64 - mean_residual;
        score += 0.05 * residual_dev; // prefer bins with residual below mean
        if open_bins_count > 8 && bin_residual as f64 > mean_residual {
            score += 3.0; // extra consolidation pressure when many bins open
        }
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    // (i.e., this call is the fresh bin) or item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Fresh bin starts with full residual; make it costly unless item is large
        // or all open bins are poor options.
        score += 45.0 * desperation;
        if item_size > 70 {
            score -= 20.0; // big items deserve a clean bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin can chain the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap_f;

    // Base: prefer small post_residual (tight fit), with quadratic sharpening
    let mut score = post + 40.0 * post_norm * post_norm;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate larger post_residual; late, penalize it more (bins close out)
    let progress_weight = 0.5 + 3.0 * progress * progress;
    score += progress_weight * post_norm * cap_f * 0.15;

    // Interaction: residual diversity from mean residual — bins far from mean
    // are either hoarders or near-full; smooth quadratic deviation penalty
    let dev = post - mean_residual;
    score += 0.08 * dev * dev / (1.0 + post_norm);

    // Lookahead coupling: reward if next item fits in post_residual, smoothly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap_f;
        score -= 6.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // smooth penalty growing with how much next item misses
        let miss = (next_item_size as f64 - post) / cap_f;
        score += 4.0 * miss * miss * cap_f;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - post_norm);
    }

    // Mild penalty for proliferation of open bins early (encourage consolidation)
    score += 0.3 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when item is large
    // relative to capacity or no good fits exist; smooth ramp on item size
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap_f;
        score = post + 30.0 - 20.0 * size_frac * size_frac - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on capacity fractions.
    // Residuals that are "harmonically useful" (multiples of small divisors of 100)
    // are less dead than others. Penalize non-divisible residuals.
    let post = post_residual as i64;
    let divisible_10 = post % 10 == 0;
    let divisible_25 = post % 25 == 0;
    let divisible_50 = post % 50 == 0;
    if divisible_50 {
        score -= 6.0;
    } else if divisible_25 {
        score -= 3.0;
    } else if divisible_10 {
        score -= 1.0;
    } else {
        score += 4.0; // awkward residue class -> dead space penalty
    }

    // Integer-division threshold classes on post_residual.
    let class = post / 10; // 0..10 coarse class
    match class {
        0 => score += 8.0,   // nearly full bin: excellent, but tiny residual is fine
        1 => score -= 5.0,   // residual 10-19: usable for small items
        2 | 3 => score += 1.5, // mid residuals: mediocre
        4 | 5 => score -= 2.0, // residual 40-59: flexible
        _ => score += 0.5,   // large residual: bin barely touched
    }

    // Lookahead coupling: does post_residual exactly fit next_item_size?
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if post == nxt {
            score -= 12.0; // perfect two-step chain
        } else if post >= nxt && post - nxt <= 10 {
            score -= 5.0;  // next item leaves near-harmonic residual
        } else if post < nxt && post > 0 {
            score += 3.0;  // next item won't fit here; residual likely wasted
        }
        // harmonic gcd bonus
        let g = gcd(post.max(1) as u64, nxt as u64) as f64;
        score -= (g - 1.0) * 0.7;
    } else {
        // last item: just close bins tightly
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: an empty bin has neutral-to-high score unless
    // open bins are crowded or the fit here is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits -> must open
        }
    }

    // Prefer bins tighter than the mean (good packing direction).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 4.0 * progress;
    }

    score
}

fn gcd(a: u64, b: u64) -> u64 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold any plausible item are toxic.
    // Treat post_residual in (0, 10) as near-wasted; also lightly penalize gaps < 20.
    let gap = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // risky small gap
    } else {
        // Larger gaps: mild quadratic penalty to prefer spreading fill evenly.
        score += 0.05 * (gap - 20.0);
    }

    // If this bin's gap can exactly host the next item, reward the lookahead fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap that will strand the next item: penalize proportionally.
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: baseline so it's chosen only when all open fits look bad.
    if bin_residual == bin_capacity && item_size > 0 {
        // New empty bin leaves residual = capacity - item_size; make it a middling choice.
        score = (bin_capacity - item_size) as f64 + 40.0 + 2.0 * open_bins_count as f64;
        // But if it's a perfect-ish start for a big item, allow it.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin completely.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5; // exact next-fit is best, decays with slack
        } else {
            // next item won't fit here: penalize dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize small unusable residuals (dead space below minimum item size ~1..100 unknown, use 10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it neutral-high so it's chosen only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if next item is large and this item is small, opening fresh may be good.
        if next_item_size > 0 && next_item_size > post_residual + item_size as u32 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins that end up nearly full.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 1.6 * tightness * tightness * (bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well next item uses leftover
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * use_ratio;
        } else {
            // next item cannot use leftover: penalize large dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.35 * dead;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good alternatives exist or many bins are already open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 14.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 8.0 * (fitting_bins_count as f64).min(4.0);
        }
        // early in the stream, opening bins is cheaper (few open bins)
        new_bin_penalty -= 3.0 * (open_bins_count as f64).min(6.0);
        // late in the stream, consolidation matters more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Global state coupling: prefer bins whose residual is close to the mean
    // (keeps residuals uniform, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // Mild preference for using already-open bins vs accumulating open bins.
    if bin_residual != bin_capacity {
        score -= 2.0 + 0.05 * open_bins_count as f64;
    }

    // Penalize leaving awkward residual slivers (unusable for min item ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual, compressed non-linearly (dead space hurts superlinearly).
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth coupling of residual waste with stream progress: waste matters more later.
    score *= 1.0 + 0.6 * progress * (pr / cap);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits perfectly in the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            // Penalize leaving a residual that barely fails the next item.
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Penalize spreading residual mass when many bins are already open.
    score += 0.05 * (open_bins_count as f64) * (pr / cap);

    // New-bin candidate: make empty bin mildly unattractive unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in "small" residue
    // classes represent tight, efficient fills -> reward them.
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    let decade = pr / 10;

    // Reward small post-residual strongly (near-perfect packing).
    score -= (10.0 - residue) * 1.7;

    // Penalize post_residuals that are too small to ever be useful
    // (dead space below typical item sizes 10..80 => residual < 10 is dead).
    if pr < 10 {
        score += 60.0;
    }

    // Harmonic decade coupling: residuals in [20,30), [40,50), [60,70) etc.
    // are "harmonic" slots that pair well with common item sizes; odd decades
    // (10-19, 30-39) are awkward. Reward even decades, penalize odd ones.
    if decade % 2 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr > 0 {
        score += 4.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 25.0;
        // Extra reward if next item harmonizes: (pr - next_item_size) leaves
        // a small dead space again.
        let after2 = pr - next_item_size;
        if after2 < 10 {
            score -= 15.0;
        }
        score -= (after2 % 10) as f64 * 0.5;
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here; mildly penalize wasting a good harmonic slot.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when residuals
    // across open bins are tight or the fit is poor.
    if bin_residual == bin_capacity {
        score = 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin always fits the next item too
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 2.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        if mean_residual > item_size as f64 {
            score += 25.0;
        }
    }

    // Global tightness term: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Small harmonic jitter based on item/bin size classes to break ties
    // deterministically toward complementary size pairs.
    let cls = (item_size / 10) + (bin_residual / 10);
    score -= (cls % 3) as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead); // tiny gap = wasted space forever
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - dead);
        } else {
            score -= 15.0 * dead; // larger residual is reusable, reward
        }
    } else {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward using bins that are already fairly full (tight packing).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * fill * fill;

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
        }
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes the remainder.
            let chain_tightness = next_item_size as f64 / (post_residual.max(1) as f64);
            score -= 45.0 * chain_tightness;
            if post_residual == next_item_size {
                score -= 50.0; // perfect 2-item packing
            }
        } else {
            // Next item won't fit here: penalize leftover dead space, but
            // soften if the leftover is small (unusable anyway).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score -= 5.0; // tiny sliver, harmless
            } else {
                score += 0.35 * dead;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // placing here when it's a wasteful fit is penalized.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above good fits,
    // but attractive when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.2 * item_size as f64;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can also chain the next item
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
    }

    // Late-stream urgency: consolidate as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - fit_ratio.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Heavily penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly-perfect fill
    } else if post_residual < 30 {
        score -= 3.0 * (1.0 - post_residual as f64 / 30.0);
    } else {
        score += (post_residual as f64 - 30.0) * 0.15;
    }

    // Last chance: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, big reward (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // extra reward for chain with small leftover after next item
        let chain_left = post_residual as f64 - next_item_size as f64;
        score -= 4.0 * (chain_left / bin_capacity as f64);
    }
    // If next item would fit this bin better than the current item alone, discourage bad interleaving.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 2.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open a new bin when existing mean residuals are small (fragmented) or many bins are open.
        let open_bonus = fragmentation * 20.0 + (open_bins_count as f64).ln().max(0.0) * 3.0 + progress * 5.0;
        // Base penalty so that a decent existing fit usually wins.
        score = 55.0 - open_bonus + (bin_capacity as f64 - item_size as f64) * 0.2;
    }

    // Mild preference to consolidate into bins with low mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, with non-linear curvature
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, prefer tighter packing more strongly
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * (0.5 + 0.5 * progress) * (1.0 - norm_pr * norm_pr).max(0.0);

    // Last-chance bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalty if this placement leaves residual too small for the next item
    if next_item_size > 0 {
        let gap = (next_item_size as f64) - pr;
        if gap > 0.0 {
            score += 10.0 + gap * (0.3 + 0.4 * progress);
        } else {
            // smooth reward when next item still fits
            score -= 5.0 * (1.0 - (-gap / cap).exp());
        }
    }

    // Deviation from mean residual: smooth quadratic coupling
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (0.5 + progress);

    // New-bin candidate: mildly penalize early, allow late when open bins are scarce fits
    let new_bin = (bin_residual == bin_capacity) as i32 == 1;
    if new_bin {
        score += 25.0 - 30.0 * progress - 2.0 * (fitting_bins_count as f64);
    }

    // Mild penalty for bin proliferation early on
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity quarters:
    // dead-space classes (1..=5 residual) are heavily penalized.
    let q = post_residual / (bin_capacity / 4);
    let r = post_residual % (bin_capacity / 4);
    match q {
        0 => {
            // post_residual < 25: nearly dead space unless 0.
            score += 40.0 * (1.0 - r as f64 / 25.0);
        }
        1 => {
            // 25..49: useful for small items.
            score -= 10.0;
        }
        2 => {
            // 50..74: prime territory for medium items.
            score -= 20.0;
        }
        _ => {
            // 75+: roomy bin, mildly favored.
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let chain = post_residual - next_item_size;
            score -= 30.0 * (1.0 - chain as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize tight leftovers that waste capacity.
            if post_residual < next_item_size && post_residual > 0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, few fitting bins) — otherwise keep it expensive.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 60.0 * (fitting_bins_count as f64).min(3.0);
        } else {
            score += 25.0 + 3.0 * open_bins_count as f64;
        }
    }

    // Mild pressure toward consolidating into fewer bins when residuals are large.
    score -= 0.05 * mean_residual;

    // Slight late-stream bias toward filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a meaningful item are wasted. Penalize small nonzero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 12.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Moderately risky gap: still likely to become dead space.
        score += 25.0 + (30 - post_residual) as f64 * 1.5;
    }

    // If the lookahead item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host the next item: likely dead space unless small enough
        // to be filled by arbitrary later items.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins,
    // but bias toward keeping bins tight (low residual relative to mean).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 2.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // which compacts packing and frees near-empty bins for consolidation.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.4;

    // New-bin candidate: make it attractive only when the fit into open bins
    // would be poor (large post_residual). Empty-bin post_residual = capacity
    // - item_size, so the base term already scales; add a mild stabilizer so
    // a new bin wins only against genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual == next_item_size {
            score -= 1000.0; // exact 2-step match, take it
        } else {
            score += diff * 2.0; // penalize mismatch with lookahead
        }
        // If next item fits the post-residual exactly, reward proportionally
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 10.0; // next item cannot follow into this bin
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Reward bins tighter than the mean (good fits), penalize loose bins
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Penalize creating unusable dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 100.0; // tiny dead space is worthless
    }

    // Slight preference to fill existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 25.0; // discourage opening a new bin unless clearly better
    }

    // Late in the stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post-residual non-linearly (dead space hurts more as it grows).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; otherwise penalize
    // leaving awkward gaps that neither the next item nor small items can fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0 + 0.3 * post_residual as f64;
        }
    }

    // Global pressure: many open bins with small mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let avg_frac = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score += (open_bins_count as f64 - 2.0) * (1.0 - avg_frac) * 5.0;
    }

    // Time horizon: late in the stream, avoid new bins; early, allow exploration.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, less so early in the stream
        // or when the item is large and fits badly everywhere.
        let mut new_bin_penalty = 30.0 + 70.0 * progress;
        if item_size > bin_capacity / 2 {
            new_bin_penalty *= 0.6;
        }
        if next_item_size > 0 && next_item_size > item_size {
            new_bin_penalty *= 0.7; // next item may need fresh space anyway
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: small bonus for filling larger residual bins (balance residuals).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Slight preference for bins whose residual is close to a multiple pattern
    // (complementary fit): residual close to 100 - item_size is already post_residual.
    // Penalize leaving residuals in the "dead zone" (1..10) unless perfect.
    if post_residual >= 1 && post_residual <= 5 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: post residual, mildly sub-linear via polynomial shaping
    let mut score = pr * (1.0 - 0.25 * norm_pr * norm_pr);

    // Smooth progress coupling: later in stream, tolerate residual less (pack tight)
    let tightness = 0.5 + 0.5 * progress;
    score *= tightness;

    // Quadratic interaction: penalize mid-range residual dead space, reward near-full packing
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead coupling: reward residuals that can host the next item (smooth kernel)
    if next > 0.0 {
        let diff = (pr - next) / cap;
        let kernel = (-diff * diff * 40.0).exp();
        score -= 15.0 * kernel * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mean residual attraction: prefer bins near the mean (keeps bin set homogeneous)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Congestion: many open bins -> discourage spreading, favor filling existing bins
    let congestion = (open_bins_count as f64).ln() + 1.0;
    score += 3.0 * norm_pr * congestion;

    // Smooth quadratic term in item size to break ties toward larger items in emptier bins
    score -= (item / cap) * (1.0 - norm_pr) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post; // best-fit core: smaller leftover wins

    // --- Harmonic class of post_residual (integer division thresholds) ---
    // Coarse dead-space class: each 10-unit band of leftover adds penalty,
    // so a leftover of 35 is penalized more than 25 even before fine tuning.
    let dead_class = (post_residual / 10) as f64;
    score += dead_class * 2.0;

    // Tight-fit rewards (perfect and near-perfect packing are gold)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Modulo arithmetic: residuals that are multiples of 10 remain
    // "harmonically reusable" by the common small-item sizes; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    // Odd leftover classes (mod 5 != 0) tend to become dead space.
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 3.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item chains perfectly into this bin
            score -= 8.0;
            if (post - nxt) < 10.0 {
                score -= 6.0; // double-tight chain
            }
        } else if post > 0 {
            // leftover too small for next item: proportional dead-space penalty
            score += (nxt - post) * 0.3;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // base hesitation: prefer filling existing bins when fits are decent
        score += 15.0;
        let prog = step_index as f64 / (total_items.max(1) as f64);
        // early stream: open bins cheaply to build a good residual portfolio
        score -= (1.0 - prog) * 10.0;
        // if lookahead item can't use this bin's post residual anyway,
        // a fresh bin with harmonic (mod-10) leftover is attractive
        if next_item_size > 0 && (next_item_size as f64) > post {
            score -= 5.0;
        }
        // if post residual is a "nice" class (multiple of 10), new bin is fine
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // --- Global pressure terms ---
    // Many open bins: push toward consolidating into existing bins.
    score += open_bins_count as f64 * 0.3;
    // Mean-residual coupling: if this bin's leftover sits far below the mean,
    // it is the most fragmented bin -> filling it is valuable.
    score += (mean_residual - post) * 0.1;
    // Mild capacity-scale normalization guard
    let _ = cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (size 1..=9 here,
    // but conservative threshold tied to item_size stream) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing bins
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits the post-residual, reward leaving a usable gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item almost fits but not quite, penalize leaving a near-miss gap
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(3) && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        score -= (open_bins_count as f64) * 2.0 - 10.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean residual coupling: when mean residual is high, bins are loose; prefer tight placement
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
