pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: dead-space ratio penalty (quadratic).
    let waste_ratio = post / cap;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item can exactly use post_residual, strongly favor.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < f64::EPSILON * 100.0 {
            score -= 25.0;
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            // next item can't fit here; small penalty proportional to wasted opportunity
            score += 5.0 * (nxt / cap);
        }
    }

    // Global state: many open bins with high mean residual -> discourage fragmenting further,
    // prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > post {
        score -= 8.0 * (1.0 - progress);
    }

    // New-bin candidate handling: an empty bin is penalized unless open bins are all bad fits.
    if bin_residual == bin_capacity {
        let mut base = cap + 20.0;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            base -= 60.0;
        } else if fitting_bins_count == 1 {
            base -= 15.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        base += 15.0 * progress;
        score = base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, slightly discounted early (waste matters more later)
    let mut score = r * (0.7 + 0.6 * progress);

    // Non-linear polynomial coupling with progress:
    // mid-stream, prefer tight fits more aggressively (quartic shaping)
    let tight = 1.0 - rn; // 1 = perfect fit
    score -= (tight * tight * tight * tight) * 12.0 * (0.4 + 0.8 * progress);

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r < nx {
            score += (nx - r) * (0.5 + 1.5 * progress);
        } else {
            score -= 2.0 * (1.0 - (nx / r));
        }
    }

    // Dead-space penalty: residuals too small for typical future items
    if rn > 0.0 && rn < 0.1 {
        score += 8.0 * (0.1 - rn) * 10.0 * (0.3 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins when residuals are high
    score += open_bins_count as f64 * mean_residual * 0.01 * progress;

    // New-bin candidate handling: keep empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = r * (0.75 + 0.5 * progress) - 3.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit and small dead-space classes rewarded
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit gets massive reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual in {0, C/2, C/3, C/4} are "usable" residuals
    let harmonics: [f64; 4] = [cap, cap / 2.0, cap / 3.0, cap / 4.0];
    for h in harmonics.iter() {
        if (post - h).abs() < 0.5 && post > 0.5 {
            score -= 60.0;
        }
    }

    // Integer division thresholds: reward residuals that can hold common item sizes
    // next item can fit exactly into post residual -> strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // exact match of next item into residual
        if next_item_size == post_residual {
            score -= 40.0;
        }
        // harmonic pairing: item + next divides capacity evenly
        if (item_size + next_item_size) * 2 == bin_capacity
            || (item_size + next_item_size) * 3 == bin_capacity
            || (item_size + next_item_size) * 4 == bin_capacity {
            score -= 35.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit in this residual: penalize dead space more
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals with small remainder vs typical sizes
    if post_residual > 0 {
        let m10 = post_residual % 10;
        if m10 == 0 {
            score -= 10.0; // multiple of 10, likely reusable
        }
        // penalize awkward residuals (1..9 dead space)
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish, penalize slightly unless current bins are crowded
    if bin_residual == bin_capacity {
        // opening a new bin: base penalty, reduced if existing bins are fragmented
        let fragmentation = (mean_residual - post).abs();
        score = 55.0 - fragmentation.min(30.0);
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Tight fits are good: reward small post_residual relative to item
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Waste penalty scaled by how full the bin already is (encourage filling near capacity)
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score *= 1.0 - 0.25 * fill;

    // Many open bins: discourage spreading, favor consolidation into fuller bins
    score += 0.5 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    // A post residual that cannot fit even the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-nonzero residuals that can't fit the lookahead item are risky.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward tight fits: post_residual near zero (but not dead) is good.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Perfect fit bonus scaled by item size (big items closing bins are valuable).
    if post_residual == 0 {
        score -= item_size as f64 * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make empty bins less attractive unless residuals elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if this bin would be the only fitting one, allow opening.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Mean residual coupling: avoid bins deviating wildly from the mean residual
    // (keeps residual distribution balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference to place larger items into fuller bins.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step chain: fill bin completely after next item
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: reward proportional to tightness
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
            // extra bonus if the chain leaves a small reusable remainder
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow into this bin: penalize dead space relative to mean residual
            score += 15.0 + diff / 10.0;
            if (post_residual as f64) < mean_residual * 0.5 {
                score += 10.0; // creating below-average residual is wasteful
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 5.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // a fresh bin can host a full 2-step chain
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin
        }
    }

    // Mild preference for bins with larger residuals when many bins are open (consolidation).
    score -= 0.05 * open_bins_count as f64 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small leftover space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight * (bin_capacity as f64);

    // Penalize awkward dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead (k=2): reward if next item fits in the post-residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Exact chain fit: post_residual equals next item -> perfect packing.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with open bins count (fragmentation).
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If mean residual across open bins is large, no need for a new bin.
        score += 0.3 * mean_residual;
        // But if this item nearly fills a fresh bin, a new bin is fine.
        if item_size as f64 > 0.9 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor) via mean residual contrast.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0; // tighter-than-average bin: good
    } else {
        score += 1.5; // looser-than-average bin: mild penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.6 * prn * prn);

    // Stream-progress coupling: penalize large residuals more later in the stream
    score += 18.0 * prn * prn * progress;

    // Reward tight fits (small post_residual) with smooth quadratic bonus
    score -= 14.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - 0.5 * progress);

    // Dead-space penalty: residual that is small but likely unusable
    let next_fits = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        // reward leaving room exactly for the next item
        let gap = (pr - next_fits) / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Many open bins: prefer filling existing ones over spreading
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Mean residual coupling: bins far below mean residual waste space
    score += 3.0 * (mean_residual - pr).max(0.0) / cap;

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Integer-division classes: residuals that are multiples of common item
    // sizes (10, 20, 25, 50) are reusable; odd residues are penalized.
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 8.0;
    } else if post_residual % 5 != 0 {
        score += 4.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
            if gap % 10 == 0 { score -= 5.0; }
        } else {
            // next item cannot fit here: penalize leaving large stranded space.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current fit
    // is very poor (large stranded residual) and other bins exist.
    if bin_residual == bin_capacity {
        // Fresh empty bin baseline: attractive when item is large or stream is early.
        score = item_size as f64 + 15.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    } else {
        // Prefer tight fits among open bins: score relative to residual tightness.
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 15.0 * tightness;
        // Penalize spreading across too many bins when mean residual is high.
        if mean_residual > (bin_capacity as f64) * 0.5 && post_residual < 20 {
            score += 10.0;
        }
    }

    // Mild exploration pressure late in the stream: consolidate.
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
        score += post_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0; // smaller gap = worse
    }
    // Perfect fit is heavily rewarded
    if post_residual == 0 {
        score -= 50.0;
    }
    // Reward residuals that could still fit a typical next item
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
    }
    // If next item does NOT fit in post_residual, dead space relative to next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> prefer consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Mean residual coupling: penalize bins far below mean residual (fragmented bins)
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so new bins are opened only when justified
        score += 25.0 + open_bins_count as f64 * 5.0;
        // if nothing else fits (fitting_bins_count==0 means only new bin candidate exists)
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // early stream: opening bins is cheap
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        // Perfect match: next item exactly consumes remaining space.
        if diff == 0.0 {
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits: reward proportional to tightness of the 2-step fill.
            let fill_ratio = nxt / post;
            score -= 40.0 * fill_ratio;
            // Extra bonus if combined 2-step chain nearly fills the bin.
            if post - nxt <= 5.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here: penalize, worse the more space is wasted.
            let waste = nxt - post;
            score += 10.0 + 0.3 * waste;
        }
        // Coupling with mean residual: bins whose post residual diverges from mean
        // are less flexible for future items.
        score += 0.15 * (post - mean_residual).abs();
    }

    // Dead-space penalty: tiny post residuals are fine (near-full bin),
    // mid-size residuals (unusable pockets) are penalized.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score -= 20.0; // nearly perfect closure
    } else if post >= 10.0 && post < 20.0 {
        score += 8.0; // awkward pocket
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with less residual before placement (tighter fit).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post_residual is small.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * item_size as f64 * 0.8;

    // Exact/near-exact fill bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let slack = post_residual as f64 - next;
            score -= (1.0 - slack / cap) * 60.0;
            if slack == 0.0 {
                score -= 120.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large dead space.
            score += (post_residual as f64 - (cap - next)) * 0.3;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // (avoid opening a new bin unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0 + (item_size as f64 / cap) * 50.0;
    }

    // New-bin candidate handling: baseline preference so a fresh bin is chosen
    // only when existing fits are poor. Its post_residual = cap - item_size.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheap; later, discourage it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        // If many bins are open and mean residual is high, prefer reusing.
        score += (mean_residual / cap) * 30.0;
    } else {
        // Reuse reward grows with stream progress and number of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 + progress * 40.0 + open_bins_count as f64 * 1.5;
        // Penalize bins far from the mean residual (fragmentation avoidance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize post_residual relative to capacity
    let pr = post_residual as f64 / bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial penalty on wasted space, sharpening as stream progresses
    let tightness = 1.0 + 2.0 * progress * progress;
    score += tightness * (pr * pr) * bin_capacity as f64;

    // Smooth coupling: reward near-perfect fits more strongly over time
    let fit_ideal = 1.0 - (item_size as f64 / bin_capacity as f64);
    score -= 30.0 * progress * (1.0 - (pr - fit_ideal).abs()).max(0.0) * (1.0 - pr);

    // Penalize bins whose residual diverges from mean residual (fragmentation signal)
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr * pr);
    }

    // Lookahead coupling: penalize if post_residual cannot hold next item but almost could
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = ni - post_residual as f64;
        if gap > 0.0 && gap <= 20.0 {
            score += 15.0 * (1.0 - gap / 20.0) * (1.0 - progress);
        } else if gap <= 0.0 {
            score -= 10.0 * progress * (1.0 - pr);
        }
    }

    // Mild penalty for opening new bins when many bins already exist
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64 * (1.0 + progress);
        // But favor a fresh bin late in stream if residual waste would be large
        score += 40.0 * progress * pr * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: prefer tight fits.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        // Harmonic-class dead space: residual classes that few item sizes can fill are bad.
        // Items in 1..=100; residual r is "fillable" if some plausible size <= r exists.
        // Penalize residuals in dead zones via modular structure on capacity fractions.
        let cap_frac = (post_residual as f64) / (bin_capacity as f64);
        // Class of residual by eighths of capacity (harmonic subdivision).
        let class = (cap_frac * 8.0).floor() as i64; // 0..7
        // Small classes (0,1) are nearly unusable dead space; large classes are flexible.
        let class_penalty = match class {
            0 => 60.0,
            1 => 40.0,
            2 => 20.0,
            3 => 8.0,
            4 => 0.0,
            5 => -3.0,
            6 => -6.0,
            _ => -8.0,
        };
        score += class_penalty;

        // Modulo-10 structure: residuals that are multiples of 10 align with typical
        // size granularity and are easier to fill later.
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 5 == 0 {
            score -= 2.5;
        } else {
            score += 3.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 300.0;
        } else {
            score -= 30.0 * (next_item_size as f64) / (post_residual as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement: this bin becomes dead space
        // unless residual is large. Penalize proportionally to wasted capacity.
        let waste = post_residual as f64;
        score += 0.15 * waste;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer dense bins (relative to mean residual) to consolidate fragmentation.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference for using existing bins over opening new ones, scaled by
    // stream progress (early on, spreading is cheaper; later, consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost so it's chosen only when open bins fit poorly.
        score += 25.0 + 40.0 * progress;
        // Opening a new bin is more attractive early when many items remain.
        score -= 30.0 * (1.0 - progress);
    }

    // Tie-break toward bins with more slack when residuals are equivalent classes.
    score += 0.05 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A residual below the minimum item size is truly dead; a small-but-usable
    // residual is a "danger zone" that likely becomes dead too.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual >= 10 && post_residual <= 25 {
        score += 25.0; // likely dead space given typical item sizes
    } else if post_residual > 60 {
        score -= 15.0; // large residual stays flexible
    }

    // Reward tight fits (low waste ratio).
    score += 40.0 * (post_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: with many bins open, avoid spreading; prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 20.0 * pressure * (1.0 - progress);

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 8.0; // next item won't fit here; residual likely wasted
        }
    }

    // Slight preference for bins below mean residual (keeps large bins free).
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual < 10 || post_residual > 80;
        if poor_fit && fitting_bins_count >= 1 {
            score -= 45.0; // open a fresh bin rather than wrecking one
        } else {
            score += 30.0; // prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match if next item fills the residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-step chain: item then next item exactly fills bin
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally, penalize leftover dead space
            let next_post = post_residual - next_item_size;
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
            score += 0.5 * next_post as f64;
        } else {
            // next item won't fit here: penalize if residual is small (dead space)
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += (1.0 - progress) * 8.0;
        }
    }

    // Prefer bins with residual below mean (denser bins absorb waste better)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 3.0;
        score += 60.0 - crowded.min(55.0);
    }

    // Mild preference for tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Penalize large dead space quadratically, normalized by capacity.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 40.0;
    }

    // Exact-fill of residual (item equals residual) is perfect.
    if item_size == bin_residual {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more if it leaves big gap.
            let gap = post_residual as f64;
            score += gap * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: late in the stream, consolidate; early, be freer.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (mean_residual / bin_capacity as f64);

    // Many open bins: prefer filling existing ones over spreading.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins aren't chosen casually.
        score += 45.0;
        // But if mean residual is small (open bins are full-ish), opening is fine.
        score -= mean_residual * 0.3;
        // If this is the last chance / no alternatives, soften.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in stream, prefer closing out existing bins.
        score += progress * 20.0;
    } else {
        // Existing bin: small bonus scaled by how full it already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste left behind, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are tolerable; late in the stream, waste is penalized quadratically.
    let pr_n = pr / cap;
    let coupling = pr_n * pr_n * (0.5 + 2.5 * progress) - pr_n * (0.3 + 1.2 * progress);
    score += coupling;

    // Perfect fit reward (smooth, no hard cutoff)
    score -= (1.0 - pr_n) * (1.0 - pr_n) * 0.8;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: reward leaving space the next item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).abs();
        score += (slack / cap) * 0.6;
        if pr >= nx {
            score -= 0.25;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    let mean_r = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
    score += (pr_n - mean_r) * 0.15;

    // New-bin candidate: keep it attractive only when fit is poor
    if bin_residual == bin_capacity {
        score += 0.4 + 0.8 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo-10 classes
    let pr = post_residual;
    let class = pr % 10; // harmonic residue class
    let decade = pr / 10; // integer division threshold

    // Reward small post-residuals that still fall into "usable" classes.
    // Classes 0 and 5 are the most reusable (items often multiples of 5/10).
    let class_bonus: f64 = match class {
        0 => 6.0,
        5 => 4.0,
        1 | 9 => 1.0,
        2 | 8 => 0.5,
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize dead space: post_residual too small for the minimum item (1..100 unknown,
    // but assume ~10 typical): leftovers in (0, 10) are nearly dead.
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Perfect harmonic match: next item exactly fills the bin
        if next_item_size == pr {
            score -= 12.0;
        } else {
            // Fractional fit quality of the next placement
            let fill = next_item_size as f64 / pr as f64;
            score -= 4.0 + 4.0 * fill;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to wasted capacity
        let waste = pr as f64 / bin_capacity as f64;
        score += 3.0 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor residuals relative to the item, or stream is early.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its future residual is capacity - item_size
        let fresh_score = (bin_capacity - item_size) as f64;
        // Prefer fresh bin when existing mean residual is small (bad fits everywhere)
        // or when this bin's post_residual would be worse than a fresh bin's.
        score = fresh_score + 2.0;
        if mean_residual < item_size as f64 {
            score -= 1.5; // open bins are nearly full anyway -> new bin reasonable
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 && open_bins_count < 4 {
            score -= 2.0; // early stream: allow spreading
        }
    }

    // Tight fit reward: item nearly fills the bin
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.9 {
        score -= 5.0 * (tightness - 0.9);
    }

    // Decade threshold: post_residual in [10,20) is a comfortable pocket for small items
    if decade == 1 {
        score -= 1.0;
    }
    // Very large residuals wasted on tiny items are poor
    if pr > 60 && item_size < 20 {
        score += 2.0;
    }

    // Mild open-bin consolidation pressure: fewer open bins is better
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Prefer bins whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * 15.0 * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residual is large
    // relative to mean residual (i.e. existing bins are poor fits).
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size as f64 > mean_residual {
            score -= 20.0; // lookahead item won't fit open bins anyway
        }
    }

    // Lookahead synergy: reward leaving space for the next item.
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead matching ----
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            // Perfect 2-step match: this bin's residual exactly fits the next item.
            score -= 45.0 + 25.0 * (1.0 - progress);
        } else if (post_residual as u32) >= next_item_size {
            // Next item still fits here: mild reward scaled by slack tightness.
            let tight = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 12.0 * tight;
        } else {
            // Next item will NOT fit: residual becomes dead space for the lookahead.
            // Penalize proportionally to how wasted the leftover is.
            let waste = (next - post_residual as f64) / next;
            score += 20.0 * waste;
        }
    }

    // ---- Relative-to-mean-residual shaping ----
    // Prefer bins whose residual is tighter than average (concentrate waste).
    let resid = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (resid - mean_residual) / mean_residual;
        score += 8.0 * rel.max(-1.5).min(1.5);
    }

    // ---- Last-chance bonus ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin.
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: attractive only if no open bin gives a tight fit,
        // or the item is huge and fragmentation risk is high.
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score = (bin_capacity as f64) * 0.55 + 25.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin leaves room for the lookahead item too
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the sole fitting open bin
        }
    }

    // ---- Large-item urgency: pack big items early into any fitting bin ----
    if item_size > bin_capacity / 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional stream progression
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current open bins are crowded
        // and this item fits none of them well. Base cost of a fresh bin.
        let mut new_bin_score = bin_capacity as f64 * 0.85;
        // Crowding pressure: more open bins with low mean residual -> prefer reusing
        let crowd = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        new_bin_score -= crowd * 6.0;
        // Early in the stream, opening bins is cheap (future items can fill them);
        // late in the stream, prefer squeezing into existing bins.
        new_bin_score += (1.0 - t) * 12.0 - t * 18.0;
        // If many bins fit the item, a new bin is wasteful.
        if fitting_bins_count > 1 {
            new_bin_score += 25.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Last-chance bin: strongly prefer using it over opening a new one.
        if fitting_bins_count == 1 {
            new_bin_score += 40.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            new_bin_score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
        }
        return new_bin_score;
    }

    // ---- Existing-bin scoring: best-fit core ----
    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 15.0;

    // Dead-space penalty: leftover space too small to be useful later.
    // With unknown distribution, treat residual < ~10 as near-dead, < 25 as risky.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 20.0; // perfectly sealed bin is great
        } else if post_residual < 25 {
            score += 8.0; // awkward sliver
        }
    }

    // Lookahead coupling: bonus if post_residual exactly accommodates next item,
    // penalty if post_residual barely misses it.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let gap = post_residual as f64 - next;
            if gap < 5.0 {
                score -= 18.0; // sets up a perfect follow-up fit
            } else {
                score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            let miss = next - post_residual as f64;
            if miss < 10.0 {
                score += 10.0; // teases but wastes next item
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: can afford to be picky, penalize mediocre fits.
        score += (fitting_bins_count as f64 - 2.0) * 2.5;
    }

    // Global residual balance: prefer bins whose residual is below mean
    // (concentrate filling, keep large residual bins for big future items).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Slight preference late in stream to fully deplete bins.
    score += t * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap (favor flexibility); late, waste is costly.
    let pn = pr / cap;
    let time_weight = 0.4 + 1.6 * progress * progress;
    score += 30.0 * pn * pn * time_weight;

    // Smooth cubic penalty on fill fraction (encourage high occupancy bins)
    let fill = 1.0 - pn;
    score -= 8.0 * fill * fill * fill;

    // Dead-space penalty: residual that no future item (10..80) can use well
    let dead = ((pr - 20.0).max(0.0) / cap).powi(3);
    score += 40.0 * dead;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 12.0 * (1.0 - gap * gap);
        } else {
            score += 6.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.05 * open_bins_count as f64 * pn;

    // Prefer bins near mean residual for balanced packing (smooth coupling)
    score += 0.5 * (br - mean_residual) * pn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic classes: reward post_residuals that lie in "reusable" residue classes
    let pr = post_residual as i64;
    // Residuals divisible by 10 or 20 are highly reusable for typical item sizes
    if pr % 20 == 0 && pr > 0 {
        score -= 12.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else {
        // odd/prime residues are dead-space prone
        score += 4.0;
    }

    // Perfect fit: zero waste is always best
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the residual accommodate the next item (or a class of it)?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if pr >= ni {
            // bin remains useful for the known next item
            score -= 10.0;
            // extra reward if residual is an exact multiple class matching next item
            if pr % ni == 0 {
                score -= 5.0;
            }
        } else {
            // creating a residual too small for the known next item -> dead space risk
            score += 8.0;
            // harmonic penalty scaled by how "useless" the leftover is
            let frac = pr as f64 / cap;
            if frac < 0.1 {
                score += 10.0 * (0.1 - frac) * 10.0;
            }
        }
    }

    // Integer-division thresholds on post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        let class = post_residual / quarter; // 0..3 harmonic band
        match class {
            0 => score += 6.0,          // tiny sliver: nearly dead space
            1 => score -= 4.0,          // quarter-sized pocket: useful
            2 => score -= 8.0,          // half-sized pocket: very useful
            _ => score -= 2.0,          // large residual: fine but wasteful
        }
        if post_residual == half {
            score -= 6.0; // exactly half residual is a premium state
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = cap - 20.0 + congestion * 2.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.6 {
            score -= 8.0; // big next item: fresh bin is valuable
        }
    }

    // Mild preference for tighter bins overall (below mean residual = tighter)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave a gap large enough for typical future items.
    if post_residual >= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item can't use this bin's leftover: mild penalty for large leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage proliferating bins; encourage filling existing ones.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when open bins are mostly full or too many.
    if bin_residual == bin_capacity {
        score = 45.0 + 1.5 * open_bins_count as f64 - 0.2 * mean_residual;
        // Late in the stream, keep bins closed more aggressively.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
        // If next item is large and no bin will hold both, opening a new bin may help.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual already encoded).

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fits into the leftover
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in the leftover: leftover is likely dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 12.0 * (dead / 100.0);
        }
    }

    // Compare post_residual against mean residual: creating below-average residual
    // space is good (tight packing), above-average residual is wasteful.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // Penalize opening a new bin when open bins can already fit the item well.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 30.0;
        // but if next item is huge and current item leaves awkward space, opening
        // a fresh bin becomes more attractive
        if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for leaving tiny unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else if post_residual < 20 {
        score -= 100.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio;

    // Lookahead coupling: penalize if the next item could have used this residual better.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here anyway; keeping residual usable is fine
            score -= 10.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // we consumed space the next item could have used
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward saving residual exactly for the next item
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // fits poorly everywhere or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Cheaper to open when few bins are open (early stream) or when mean residual is low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * (1.0 - progress);
        score += mean_residual * 1.5;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 400.0; // no alternative
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual deviates below the mean (consolidating fuller bins).
    if bin_residual != bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * progress;

    // Prefer placing large items early (they are hard to place later).
    score -= 0.2 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with smooth polynomial shaping of residual.
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Stream-progress coupling: early on, tolerate residual (keep bins flexible);
    // late in stream, strongly punish leftover space.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * pr_norm * cap * 0.35;

    // Dead-space penalty: residuals too small to be useful later (below min item size).
    let dead = (pr < 1.0) as i32;
    if dead == 1 {
        score += 5.0;
    } else {
        let small = (pr as f64).min(10.0);
        score -= 0.4 * (small / 10.0) * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 1.5 * tightness * (1.0 + progress);
        } else {
            score += 0.8 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - pr_norm);
    }

    // Mild pressure against spreading across too many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: neutral-ish baseline, penalized when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress) + 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 4.
    // Residuals that are "harmonically awkward" (small, non-divisible leftovers)
    // are penalized; clean large residuals are rewarded.
    let class = post_residual % 4;
    let class_penalty = match class {
        0 => -2.0, // perfectly divisible residual -> clean
        1 => 1.5,  // worst leftover class: 1 unit of dead space risk
        2 => -0.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: split residuals into harmonic bands.
    let band = post_residual / 25; // quarters of capacity
    match band {
        0 => score += 12.0,           // post_residual < 25: nearly dead space
        1 => score += 4.0,            // 25..50: awkward
        2 => score -= 2.0,            // 50..75: good
        _ => score -= 4.0,            // >= 75: excellent
    }

    // If the leftover cannot fit the lookahead item, it risks becoming dead space.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 0.5 * gap.sqrt();
        } else {
            // Leftover can host the next item: reward proportional fit quality.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 5.0 * tightness;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits more aggressively.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Progress-aware pressure: late in the stream, keep residuals usable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean residual
    // (consolidating space into few bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: neutral baseline, slightly high so we only open a new
    // bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 unknown,
    // so treat sub-threshold gaps as waste) are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 50.0 * (dead_threshold - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 15.0 + 20.0 * progress + open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base score is post_residual == capacity.
        // Penalize it so it's chosen only when open bins look bad.
        score += new_bin_bonus;
        // But if the next item would perfectly fill this bin after current placement,
        // a fresh bin is attractive.
        if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
        // This bin becomes perfect for the lookahead item.
        score -= 35.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use: penalize proportionally.
        score += 5.0 * (next_item_size - post_residual) as f64;
    }

    // Mild preference for bins below mean residual (consolidating waste).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let nis = next_item_size as f64;

    // Stream progression: lookahead is most valuable early, dead-space caution grows late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let lookahead_strength = 1.0 - 0.4 * progress;

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-step match: this bin's leftover exactly absorbs the next item.
            score -= 1000.0 * lookahead_strength;
        } else if post_residual > next_item_size {
            // Next item still fits here: reward tightness of the two-step fit.
            let slack = pr - nis;
            let tightness = (1.0 - slack / cap).max(0.0);
            score -= 60.0 * tightness * lookahead_strength;
        } else {
            // Next item will NOT fit in the leftover: penalize proportional dead gap.
            let gap = nis - pr;
            score += gap * (0.4 + 0.4 * progress);
        }
    }

    // ---- Coupling with mean residual across open bins ----
    // Leftover below the mean => tighter-than-average fit, reward it.
    score -= 0.25 * (mean_residual - pr);

    // ---- Tiny unusable leftovers (dead space nothing can fill) ----
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // ---- New-bin candidate vs. last-chance existing bin ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Discourage opening a new bin, more strongly when many bins are already open.
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if the new bin's leftover exactly matches the next item, allow the opening.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 900.0 * lookahead_strength;
        }
    } else if fitting_bins_count == 1 {
        // This is the only open bin that fits: strongly avoid spawning a new bin.
        score -= 250.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear coupling.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if (bin_residual as i64) >= (next_item_size as i64) {
            // This bin could host next item but current item kills that chance.
            score += 10.0;
        }
        // If next item fits exactly in post residual, strong reward.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early in the stream, prefer opening new bins to keep flexibility;
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score -= 20.0 * (1.0 - progress);          // early: new bins cheap
        score += 15.0 * progress * (open_bins_count as f64 / 10.0).min(3.0); // late: discourage
    } else {
        // Favor bins below mean residual (relatively emptier) early on.
        score += 3.0 * (mean_residual - bin_residual as f64) * (1.0 - progress);
    }

    // Many open bins: prefer consolidation into emptier bins.
    if open_bins_count > 4 {
        score += 0.5 * (bin_residual as f64 - mean_residual);
    }

    // Exact fill is always excellent.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual); later, tolerate
    // larger residuals slightly less via amplified curvature.
    let curvature = 0.6 + 1.4 * progress;
    let mut score = post + curvature * post * post_norm;

    // Smooth cubic interaction: residual vs mean residual deviation.
    let mean_norm = mean_residual / cap;
    let dev = post_norm - mean_norm;
    score += 12.0 * dev * dev * dev_norm(dev);

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - post_norm;
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: smooth sigmoid-like reward when this bin is the
    // only fitting bin, scaled by how well the item fills it.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 10.0 * last_chance * fit_quality;

    // Lookahead coupling: penalize leaving residual close to (but smaller
    // than) the next item size — dead space that neither fits nor stays useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        // smooth penalty peaked near gap = 0, decaying quadratically
        score += 15.0 * (-gap * gap * 400.0).exp() * (1.0 - fit_quality);
        // reward if next item could fit in post residual
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (post - nxt) / cap;
    }

    // Mild pressure against bin proliferation early in the stream.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 5.0 * open_pressure * (1.0 - progress) * post_norm;

    // New-bin candidate: make empty bins attractive only when residuals
    // across open bins are large (poor fits elsewhere).
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new * (18.0 + 20.0 * mean_norm);

    score
}

fn dev_norm(dev: f64) -> f64 {
    // soft clip via tanh to keep cubic term bounded
    dev.tanh()
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit is unbeatable.
    if post_residual == 0 {
        return -1000.0;
    }

    // Harmonic class of the leftover: classify post_residual by division into
    // capacity bands. Small leftovers (< 20) are near-dead space; large ones
    // are still usable. Reward large, penalize small non-linearly.
    let pr = post_residual as f64;
    let usable_band = (post_residual / 20) as f64; // 0..=4 integer division band
    score -= usable_band * 6.0;

    // Modulo-10 class: leftovers that are multiples of 10 pair well with
    // typical item granularities.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead harmony: can the next item also land here?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chained perfect fit
        } else if next_item_size < post_residual {
            let chain = post_residual - next_item_size;
            score -= 15.0 + (chain as f64).min(30.0);
            if chain % 10 == 0 { score -= 10.0; }
        } else {
            // Next item cannot follow here; leftover is final dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { (post_residual as f64) };
        score = cap - pressure * 0.0 + 60.0
            + if fitting_bins_count <= 1 { -80.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= post_residual { 0.0 } else { 25.0 };
        // Fresh bin residual = capacity, so re-evaluate: opening a new bin is
        // good when current leftovers are fragmented.
        if mean_residual < 25.0 { score -= 30.0; }
    }

    // Mean-residual coupling: placing into a bin far below the mean residual
    // concentrates waste; prefer bins whose residual is near/below mean.
    let dev = pr - mean_residual;
    score += dev * 0.15;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item size (1) are already handled by post_residual, but residuals in
    // a "dead zone" — too small for a meaningful future item — are heavily penalized.
    // Treat residual <= 10 as unusable dead space (below typical minimum item sizes
    // in most streams); if post_residual lands there, penalize strongly.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Reward near-perfect fits: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing bins rather
    // than spreading items out. This counterbalances the new-bin candidate (which
    // has maximal residual and thus naturally low post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure * 0.5;

    // New-bin candidate: bin_residual == bin_capacity. Only allow opening a new bin
    // when the current item is large or fits are scarce; otherwise penalize so we
    // prefer existing bins.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        let big_item_bonus = if item_size >= bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 12.0 + pressure - scarcity - big_item_bonus;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item would exactly fit the post_residual, reward this
    // placement (chain fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // If next item cannot fit into post_residual but would fit a fuller bin usage,
    // slight penalty for leaving a gap that wastes capacity.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 20 {
        score += 6.0;
    }

    // Mean residual coupling: if this bin's post_residual is far below the mean,
    // it is consolidating space — good. If far above mean, it's spreading waste.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-step chain
        }
        // Penalize residuals too small for the next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize small unusable leftovers relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still good for chaining
        }
    }

    // Coupling with mean residual: prefer bins whose post-residual tracks the mean
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit), but reward exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on dead space; very small residuals are wasteful.
        let pr = post_residual as f64;
        score += (100.0 / pr) * 3.0;
        if pr < 10.0 {
            score += 60.0 - pr * 2.0; // tiny dead space nearly unusable
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / 100.0);
        } else {
            // next item can't use this bin's leftover; mild penalty scaled by mismatch
            let over = (next_item_size - post_residual) as f64;
            score += 20.0 * (over / 100.0);
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many fitting bins: this choice is less critical; slight penalty toward
    // consolidating into fullest bins (small post_residual already handles it).
    if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(10.0);
    }

    // Global state coupling: prefer using bins when many are open and mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    score += 10.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);

    // New-bin candidate handling: an empty bin gets a baseline; only choose it
    // when no open bin offers a decent fit (i.e. when its score is lowest).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin early / when open bins exist with room.
        score += 80.0;
        if open_bins_count > 0 {
            score += 60.0 * (1.0 - progress);
        }
        // But late in the stream with fragmented bins, allow new bins more readily.
        if progress > 0.7 && mean_residual < 30.0 {
            score -= 50.0;
        }
        // Large items relative to capacity favor a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 2.0 * t * t + 3.0 * t * t * t * t;
    score += 12.0 * norm_pr * norm_pr * poly * cap * 0.05;

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Lookahead coupling: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 15.0 * (1.0 - (pr - n) / cap) * (1.0 - t);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for spreading across many bins early
    score += 1.5 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into modulo buckets.
    // Residuals divisible by large chunk sizes are more "usable" by future items.
    let pr = post_residual;
    if pr > 0 {
        // Class 0: perfectly divisible residuals (pr % 25 == 0) are friendlier.
        if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            // Odd, non-round residuals are dead space; penalize proportionally.
            score += (pr % 5) as f64 * 1.5;
        }
        // Integer-division thresholds: small leftovers are wasted.
        if pr < 10 {
            score += 12.0; // dead space below minimum item size
        } else if pr < 20 {
            score += 5.0;
        }
        // Fraction of capacity wasted, squared for non-linearity.
        let waste_frac = pr as f64 / cap;
        score += waste_frac * waste_frac * 30.0;
    } else {
        // Perfect fill: strongly reward.
        score -= 25.0;
    }

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            // Next item fits in the leftover: reward, especially on harmonic boundaries.
            score -= 10.0;
            if pr % next_item_size == 0 {
                score -= 6.0; // exact division: perfect future fill
            }
        } else {
            // Next item cannot use the leftover; penalize if leftover is small.
            if pr < next_item_size {
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if pr >= 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large and mean residual across bins is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        // Penalize new bins mildly, less so when open bins are congested.
        score += 20.0 - mean_residual / cap * 15.0 - item_frac * 10.0 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 30.0; // must open a bin at start
        }
    }

    // Slight preference for tighter bins when many bins are open.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: bonus if the residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize residual that is just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: prefer bins whose residual deviates favorably (tighter than mean).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    // New-bin candidate handling: neutral baseline, penalized slightly more when many bins open,
    // but attractive when the fit into open bins would be terrible.
    if bin_residual == bin_capacity {
        score = 45.0 + open_bins_count as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear emphasis.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // 2-step lookahead: reward if the next item exactly or nearly fits the post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let slack = post_residual as f64 - next;
            // Reward chains where the next item consumes the leftover.
            score -= (1.0 - slack / bin_capacity as f64) * 60.0;
            if slack == 0.0 {
                score -= 30.0; // perfect 2-item completion bonus
            }
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            score += (post_residual as f64 - next).min(next as f64) * 0.5;
        }
    } else {
        // Last item: just minimize leftover.
        score += post_residual as f64 * 0.3;
    }

    // Compare against mean residual: filling a below-average-residual bin is good.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        // Spread load when many bins fit.
        score += fitting_bins_count as f64 * 1.5;
    }

    // Late in the stream, be more conservative: avoid leaving many tiny open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.2;

    // Penalize opening a new bin when decent open bins exist, unless residual is tiny.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { (bin_capacity - next_item_size.min(bin_capacity)) as f64 } else { 0.0 };
        score += 25.0 - best_possible * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Very small dead space is nearly useless; reward it strongly.
        score -= 30.0;
    } else if post_residual > 50 {
        // Large leftover is still reusable; slight penalty vs mid leftovers.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / 100.0);
        } else {
            // Next item won't fit here; penalize wasting a good bin.
            score += 10.0;
        }
    }

    // Global state: when many bins are open, prefer consolidating into
    // bins whose residual is below the mean (fill the emptier ones less).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.3 * dev * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early in the stream, be more liberal about opening
    // new bins (keep residuals large for future flexibility); late in the
    // stream, squeeze everything into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late.
        score += 70.0 * (1.0 - t);
        // Never open a new bin when an open bin gives an exact or near fit.
        if post_residual < 10 && bin_residual != bin_capacity { score -= 100.0; }
    } else {
        score -= 25.0 * t;
    }

    // Mild penalty for using very full bins on tiny items (waste of tight space).
    if item_size < 20 && bin_residual < 40 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    let t = progress;
    score += prn * prn * (1.0 - t) * 20.0;
    score -= prn * (1.0 - prn) * t * 15.0;

    // Tight fit reward (quadratic in fill fraction)
    let fill = (r - pr) / cap;
    score -= fill * fill * 12.0;

    // Penalize residuals that can't fit the lookahead item (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 25.0;
        // Reward residual that exactly accommodates the next item
        let match_q = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        if match_q > 0.0 {
            score -= match_q * match_q * 8.0;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual context: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Slight pressure against hoarding many open bins late in stream
    score += (open_bins_count as f64).ln() * t * 2.0;

    // New-bin candidate: make it attractive only for large items / tiny post-fit
    if bin_residual == bin_capacity {
        score = cap - item_size as f64;
        score += prn * prn * 30.0;
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small
    // unusable" classes get penalized, "large reusable" classes get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional capacity classes (harmonics 1/2, 1/3, 1/4 of capacity)
    let half = cap / 2.0;
    let third = cap / 3.0;
    let quarter = cap / 4.0;

    // Reward residuals near harmonic fractions (reusable slots)
    if (pr - half).abs() < 5.0 {
        score -= 6.0;
    } else if (pr - third).abs() < 4.0 {
        score -= 4.0;
    } else if (pr - quarter).abs() < 3.0 {
        score -= 2.5;
    }

    // Penalize tiny dead space (unusable leftovers)
    if pr < 10.0 && pr > 0.0 {
        score += 15.0;
    } else if pr < 20.0 {
        score += 4.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo classes on post_residual: multiples of 10 pair well with
    // common item sizes (items often cluster in 10s).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    } else if post_residual % 10 != 0 && post_residual > 0 {
        score += (post_residual % 10) as f64 * 0.4;
    }

    // Lookahead coupling: does next item fit the post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact harmonic match with next item
            if post_residual == next_item_size {
                score -= 10.0;
            } else {
                score -= 3.0 + (post_residual - next_item_size) as f64 * 0.1;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // residual and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - pr).abs() / cap;
        score = cap * 0.55 + fragmentation * 30.0 - progress * 10.0;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        // discourage new bins when several bins fit the item
        score += fitting_bins_count as f64 * 2.0;
    }

    // Slight preference for tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any plausible future item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderately awkward gap: mild penalty.
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are
    // badly fragmented (high mean residual relative to capacity) or crowded.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If open bins have large wasted residuals, opening fresh space is ok.
        let fragmentation = mean_residual / bin_capacity as f64;
        new_bin_penalty -= fragmentation * 40.0;
        // Many open bins: discourage adding more.
        new_bin_penalty += open_bins_count as f64 * 1.5;
        // If next item is large and no bin can host both, new bin may help.
        if next_item_size > 0 && next_item_size + item_size > bin_residual && next_item_size > 50 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(-5.0);
    }

    // Prefer bins whose residual exceeds the next item's size (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Early in stream, be a bit more conservative with tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0);
    }
    // Next item cannot fit here: penalize wasted lookahead opportunity
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize dead space: residuals too small for the minimum plausible item
    if post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins: placing into a bin
    // whose residual is far above mean tends to consolidate space poorly
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Base threshold: opening a bin is penalized unless item nearly fills it
        score += 20.0;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 55.0 * fill_ratio;
        // If very few bins fit, opening fresh is reasonable
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, prefer keeping many bins open with usable residuals
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter fits overall
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 18.0 * (1.0 - tight * 4.0).max(0.0);

    // Perfect fill jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that can never hold even the smallest item (<=10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in post residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward when the lookahead leaves a still-reasonable residual.
            let post2 = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (post2 as f64 / bin_capacity as f64)).min(1.0);
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many fitting bins => we can afford to be picky; penalize loose fits harder.
    if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Global residual pressure: if mean residual is low, conserve space (penalize waste).
    let mean_pressure = 1.0 - (mean_residual / bin_capacity as f64);
    score += 10.0 * mean_pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins balanced (penalize very low residuals
    // relative to mean); late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let residual_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= (1.0 - progress) * 6.0 * residual_gap;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Open-bin count pressure: with many open bins, prefer filling existing ones
    // over opening new ones; with few bins, new-bin option stays competitive.
    let open_pressure = (open_bins_count as f64 / 8.0).min(1.5);
    score *= 1.0 + 0.05 * open_pressure;

    // New-bin candidate handling: empty bin gets a mild default penalty that
    // shrinks when the item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 14.0 - 10.0 * item_frac;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - item_size as f64).abs() < 0.5 && bin_residual == bin_capacity;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Reward tight fits: quadratic coupling between post_residual and item size
    let tightness = 1.0 - (pr / cap);
    let fit_reward = tightness * (item_size as f64 / cap);
    score -= 0.9 * fit_reward;

    // Non-linear progress coupling: late in the stream, waste is penalized harder
    let progress_coupling = progress * progress * (1.0 - progress);
    score += 1.7 * (pr / cap) * (0.5 + progress_coupling * 4.0);

    // Lookahead: penalize residuals that cannot fit the next item (quadratic in gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap < 0.0 {
            score += 0.6 * gap * gap * cap * 0.01 * (1.0 + progress);
        } else {
            // residual comfortably fits next item: mild reward
            score -= 0.25 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.2 + 0.8 * tightness;
    }

    // New-bin candidate: penalize mildly early, more when many bins already open
    if is_new_bin {
        score += 0.5 + 0.05 * open_bins_count as f64 - 0.6 * progress;
    }

    // Mean residual context: prefer bins close to the mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space (decile classes over capacity).
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };
    let item_class = item_size / 10;

    // Exact-fit classes: leftover divisible into common harmonic slots (10/20/25/50)
    // are reusable; odd leftovers are dead space.
    let harmonic_fit = (post_residual % 10 == 0) || (post_residual % 20 == 0)
        || (post_residual % 25 == 0) || (post_residual % 50 == 0);
    if harmonic_fit {
        score -= 6.0;
    } else {
        score += 4.0 + (post_residual % 10) as f64 * 0.6;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // Reward proportional to how tightly the next item nests.
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
            // Class-match bonus: next item lands in the same decile as leftover.
            if next_class == post_class {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize leftover magnitude.
            score += (post_residual as f64) * 0.35;
        }
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is huge
    // (large item class) or no meaningful reuse is possible.
    if bin_residual == bin_capacity {
        if item_class >= 7 || (next_item_size > 0 && next_item_size + item_size > bin_capacity) {
            score -= 5.0;
        } else {
            score += 20.0;
        }
    }

    // Late in the stream: consolidate; avoid spreading leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Prefer bins whose residual is far from the mean (tight packing diversity).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Many open bins: encourage closing them out (small post_residual favored).
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (post_residual as f64) * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals smaller than the minimum item size
    // (1 here, but gaps below ~10 are statistically near-unusable) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // heavy penalty for creating an unusable sliver
    }
    // Medium dead space (10..30) is only usable by small items; penalize mildly.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0;
    }

    // Reward tight fits: post_residual close to 0 but still usable.
    if post_residual == 0 {
        score -= 80.0; // perfect fit: bin closed exactly
    } else if post_residual <= 15 {
        score -= 25.0; // very tight, likely to be filled by a small item
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer fewer open bins, but only mildly, so tight fits dominate.
    score += 0.6 * open_bins_count as f64;

    // Early in the stream, be more willing to spread items (keep options open);
    // late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already below average (they are "nearly full").
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If this bin is the only fitting option, opening a new bin is cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the item leaves a dead sliver in any existing bin, new bin is fine.
        // If the item would fit perfectly elsewhere we already rewarded that.
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: next item exactly fills the residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still accommodate the next item (soft reward,
    // stronger the tighter the fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space: post-residual is nonzero but cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (prefer balanced or intentionally tight bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: heavily penalize when other bins can fit,
    // reward it (relatively) when nothing else fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 1 {
            score -= 45.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // better long-run packing structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that nothing can use (min item size 1)
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted residual
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: later in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    // Global residual state: if mean residual is low, keep tight fits
    let tightness = 1.0 - mean_residual / bin_capacity as f64;
    score -= 12.0 * tightness * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling fuller bins (smaller residual before placement)
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when no open bin is a decent fit
    if bin_residual == bin_capacity {
        let decent_fits = if bin_residual >= item_size { fitting_bins_count } else { 0 };
        if decent_fits > 1 {
            score += 60.0; // discourage opening new bin when alternatives exist
        } else {
            score -= 5.0; // slight nudge when this is the only option
        }
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized by smooth polynomial in normalized post-residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress coupling: as stream advances, dead space becomes more costly
    score += 12.0 * progress * norm_pr * norm_pr;

    // Smooth interaction: large residual gap relative to mean residual is bad
    score += 3.0 * (norm_pr - (mean_residual / cap)) * (norm_pr - (mean_residual / cap));

    // Perfect fit reward (smooth, no piecewise)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin bonus: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let waste = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64 / cap;
        score += fits_next * (-4.0 + 6.0 * waste);
        score += (1.0 - fits_next) * 2.0 * norm_pr;
    }

    // Slight preference for consolidating into fewer bins when many open
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress - 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Dead-space penalty: leftovers that can never hold typical small items.
    // Classes: (0,10] near-perfect; (10,25] good; (25,50] mediocre; >50 wasteful for big items.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 12.0;
    } else if post_residual <= 50 {
        score += 5.0 * (frac - 0.25);
    } else {
        score += 10.0 * (frac - 0.5);
    }

    // Modulo classes on post_residual: leftovers in harmonic residue classes
    // (multiples of 10 minus small epsilon) are more reusable.
    let r = post_residual % 10;
    if post_residual > 0 {
        match r {
            0 => score -= 6.0,          // clean multiple of 10
            1..=3 => score -= 2.0,      // near-multiple, still friendly
            8..=9 => score += 4.0,      // awkward sliver class
            _ => {}
        }
    }

    // Lookahead: does next item fit harmonically into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // reward if next item leaves a further clean residual
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 18.0;
        } else if next_post % 10 <= 3 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here: leftover becomes dead space unless tiny
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        } else if post_residual >= 10 {
            score += 3.0 * (post_f / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild competition scaling
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the current residual (classic best-fit sharpening).
    if bin_residual > 0 {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill;
    }

    // Prefer fuller bins overall relative to mean residual of open bins.
    score += 0.15 * (mean_residual - post_f);

    // Stream progression: early on, be conservative (keep bins flexible);
    // later, allow aggressive packing into tight spots.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - frac);

    // New-bin candidate guard: make empty bins moderately attractive only
    // when the fit here is poor (large post residual with awkward class).
    if bin_residual == bin_capacity {
        // base neutral score for fresh bin
        score = cap_f - (cap_f - post_f); // = item_size, neutral
        score += 5.0; // slight default penalty; overridden when open bins fit well
        if post_residual <= 10 {
            score += 60.0; // never open new bin if a near-perfect fit exists
        }
        if next_item_size > 0 && next_item_size > item_size && item_size >= 60 {
            score -= 10.0; // big item with bigger successor: fresh bin sensible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item (<= 10)
    // are pure waste; penalize them steeply.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small gap zone: risky dead space, mild penalty scaled by gap size.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Large residual space is reusable: reward it.
        score -= (post_residual - 20) as f64 * 0.35;
    }

    // Tight fit bonus: item consumes most of the bin.
    let fill_ratio = item_size as f64 / cap;
    if fill_ratio > 0.7 {
        score -= 12.0 * fill_ratio;
    }

    // Perfect-ish fit: post_residual near a typical item size (10-20) is valuable.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // next item won't fit here; residual likely becomes waste
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless the fit is good.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded or fit is bad.
        let crowding = open_bins_count as f64 * 3.0 + mean_residual.max(0.0) * 0.2;
        score += 45.0 - crowding.min(40.0);
        // New bin is fine if current item is large and leaves a usable residual.
        if fill_ratio > 0.6 && post_residual >= 30 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin relieves bin-count pressure.
        score -= open_bins_count.min(8) as f64 * 0.5;
    }

    // Stream progression: early on, be more tolerant of spreading items (keep residuals
    // flexible); late in the stream, prioritize consolidation (tight fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - fill_ratio);

    // Mean-residual coupling: if open bins already hold lots of space, avoid adding
    // another low-utility placement.
    if bin_residual != bin_capacity && (mean_residual - post_residual as f64) > 25.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits perfectly here: strong reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // Bonus if it's a near-exact match.
            if slack < 5.0 {
                score -= 15.0;
            }
        } else {
            // Post residual is dead space for the next item: penalize proportionally.
            let waste = next - post_residual as f64;
            score += 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals near the mean
    // (keeps bin population homogeneous), but reward tighter-than-mean fits.
    let mean = mean_residual.max(1.0);
    let pr = post_residual as f64;
    if pr < mean {
        score -= 0.3 * (mean - pr);
    } else {
        score += 0.4 * (pr - mean);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Spread load when many bins fit: mild penalty for over-concentrating.
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Penalize very small dead space that is likely unusable (typical item granularity).
    if pr > 0.0 && pr < 10.0 {
        score += 8.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Slight bias against opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin guarantees a perfect 2-step chain for large items.
            if item_size + next_item_size >= bin_capacity {
                score -= 10.0;
            }
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Reward using nearly-full bins (small residual = good packing).
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize leaving residuals that are too small for the next item (dead space).
            let waste = post_residual as f64 - (post_residual as f64).min(next_item_size as f64);
            score += 0.15 * post_residual as f64;
            let _ = waste;
        }
        // If next item is large and this bin is fresh, mildly discourage wasting a fresh bin.
        if next_item_size >= 70 && post_residual < next_item_size as u32 && post_residual < 20 {
            score += 8.0;
        }
    }

    // Dead-space penalty: residuals that are unlikely to fit future items (small residual).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Time horizon: early in the stream, be conservative and favor new bins for
    // poor fits; late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 0 {
        score -= 0.05 * mean_residual;
    }
    // Few open bins -> opening a new bin is cheaper, mildly favor new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline preference, adjusted by context.
        score += 5.0;
        if fitting_bins_count <= 1 {
            score += 40.0; // discourage new bin when an existing bin is the last chance
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for a large follow-up item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (small post_residual) with non-linear polynomial coupling
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes large residuals super-linearly
    score = score * cap;

    // Stream-progress coupling: dead space matters more late in the stream
    let late = progress * progress;
    score += 40.0 * late * x * x;

    // Exact fit bonus (post_residual == 0 handled by smoothstep already, sharpen it)
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 8.0 * (1.0 - (nxt / cap));
        } else {
            // residual too small for next item: penalize proportional to waste
            score += 5.0 * (x - nxt / cap).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mean residual divergence: avoid bins far from the fleet mean (keeps flexibility)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: neutral baseline with slight early-stream preference for opening
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score = cap * 0.75 - 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Medium gaps (10..20) are risky: only next items <= gap can use them.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // If lookahead item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 80.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }
    // Lookahead cannot use this bin's leftover: penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage scattering across many bins, but keep
    // pressure mild so dead-space penalty dominates.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual,
    // it is a good "garbage collector" bin.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.3 * diff.min(50.0);
    } else {
        score += 0.15 * (-diff).min(50.0);
    }

    // New-bin candidate: make empty bin attractive only when the item is
    // huge (poor fit anywhere) or many bins are open with low mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let huge_item = item_size > 70;
        if huge_item || (open_bins_count > 6 && mean_residual < item_size as f64) {
            score -= 55.0 + 20.0 * progress;
        } else {
            // Default: discourage opening new bins.
            score += 45.0 + 10.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item fits into the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // dead space penalty scaled by how badly next item misses
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // pair-fit: item + next exactly filling bin is ideal
        if post_residual == next_item_size {
            score -= 300.0;
        }
    }

    // Tightness reward relative to bin capacity
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 40.0;

    // Penalize bins whose residual is far below mean (avoid fragmenting good bins)
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.4;
    } else {
        score -= (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 180.0;
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 80.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 50.0; // fresh bin good for pairing
        }
        if progress < 0.15 {
            new_bin_penalty -= 60.0; // early stream: opening bins is cheap
        }
        score += new_bin_penalty;
    }

    // Slight preference to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Perfect fit gets an extra large bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize if next item is large and this bin would be left with dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus, stronger for tight chains
            score -= 12.0 + 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead-space penalty scaled by how unusable the leftover is
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
            if next_item_size > post_residual && next_item_size > 60 {
                score += 6.0; // next item will need a roomy bin anyway
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 0.5 * (post_residual.min(30) as f64);
    }

    // Many open bins: discourage spreading items into fresh-ish bins,
    // encourage consolidation into bins with small residuals relative to mean.
    if open_bins_count > 1 {
        let rel = bin_residual as f64 / mean_residual.max(1.0);
        // bin residual below mean => already committed; reward using it
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0).min(3.0);
        }
    }

    // Early stream: allow slight preference for opening new bins to build
    // a diverse portfolio; late stream: consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0;
    score -= progress * 6.0;

    // New-bin candidate handling: opening a new bin is justified only for
    // large items or when the item barely fits elsewhere / no good fit.
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
        // if few fitting bins exist, opening a bin is less bad
        score += base_penalty - 8.0 * (fitting_bins_count.saturating_sub(1) as f64).min(3.0);
        // large items justify a fresh bin
        if item_size >= 70 { score -= 20.0; }
        else if item_size >= 50 { score -= 8.0; }
        // if the resulting residual is huge but item small, strongly penalize
        if item_size < 30 { score += 15.0; }
    }

    // Mild penalty for leaving residuals in the awkward 20-40 range
    // (hard to fill later with typical items).
    if post_residual >= 20 && post_residual <= 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: dead-space cost, amplified non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth coupling: small post-residuals are extra valuable later in the stream
    let tightness = (1.0 - pr_norm).clamp(0.0, 1.0);
    score -= 25.0 * tightness.powi(3) * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * (gap * gap) / cap;
        // Reward residuals that fit the next item proportionally well
        if pr >= next_item_size as f64 {
            score -= 4.0 * (next_item_size as f64 / pr.max(1.0)) * (1.0 - pr_norm);
        }
    } else {
        // Last item: prefer filling bins as fully as possible
        score -= 30.0 * tightness;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * item_norm;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when existing residuals are all large/wasted
    if bin_residual == bin_capacity {
        let waste = (mean_residual - item_size as f64).max(0.0);
        score += 18.0 * (1.0 - progress) - 0.15 * waste - 8.0 * item_norm;
    }

    // Mild penalty for spreading across many open bins with large residuals
    score += 0.02 * (open_bins_count as f64).ln() * pr_norm * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post_residual).
    score -= (item_size as f64 / cap) * 20.0;

    // Harmonic class of post_residual: dead space in (0,10] is worst.
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else {
        // class of post_residual mod 10: multiples of 10 align with min item size 1..100 grid
        let cls = (post_residual % 10) as f64;
        score += cls * 0.8;
        // large residuals are fine (bin stays reusable)
        if post_residual >= 50 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fill_after = (post_residual - next_item_size) as f64;
        score -= 12.0 + (next_item_size as f64 / cap) * 10.0 - fill_after * 0.1;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to how close it was
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score = cap * 0.9 + desperation
            - (mean_residual / cap) * 10.0
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Late stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 6.0;
    }

    // Many open bins: prefer filling existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // unusable sliver -> strong penalty
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 80.0;

    // If the next item exactly fills the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // Penalize if post_residual can't fit the lookahead item but is large enough to be wasted.
    if next_item_size > post_residual && post_residual > 0 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening a new bin
    // (residual == capacity) should be penalized when open bins exist.
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64 * -2.0).max(-100.0);
        // But if open bins are fragmented (low mean residual), new bin is fine.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 120.0;
        }
    }

    // Early in the stream, allow more new bins (exploration); late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.7 {
        score += open_bins_count as f64 * 3.0;
    }

    // Mild tie-breaker: prefer bins whose residual is close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual), with slight non-linear pressure.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            // Next item fits exactly or nearly: strong reward.
            if diff == 0.0 {
                score -= 30.0;
            } else {
                score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item won't fit in the leftover: penalize leftover that is
            // small enough to be dead space but larger than useful.
            score += (-diff / bin_capacity as f64) * 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual is below mean
    // (concentrating fill), penalize bins already much emptier than average.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.15;
        if pr > mean_residual * 1.5 {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate (empty bin): make it attractive only when it's genuinely
    // the best option. Empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Neutral baseline; lookahead terms above dominate. Add small penalty so
        // open bins with decent fits win, but keep it competitive for large items.
        score += 3.0;
        if item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize residual that cannot host the next item (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else {
            // Reward residual that leaves room for the lookahead item.
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64).powi(3));
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer tighter fits.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Base penalty for opening a new bin.
        score += 35.0 + 15.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.4 * mean_residual;
        // If no open bin can fit the item, remove the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress * crowding;
    }

    // Mild preference for bins whose residual is far below the mean (nearly full bins).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let norm_post = post / cap;
    // Later in the stream: dead space matters more -> amplify post_residual.
    let amp = 1.0 + 2.0 * p2 + 3.0 * p3;
    score += norm_post * norm_post * cap * 0.8 * (amp - 1.0);

    // Reward near-perfect fits (small post_residual) with a smooth quadratic bonus.
    let tight = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= tight * tight * 12.0;

    // Penalize leaving residuals slightly larger than typical next item (wasted space),
    // smoothly via gap to lookahead size.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += (gap / cap) * (gap / cap) * 15.0 * (0.5 + p2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize proportionally to how much usable space it wastes,
    // but relax the penalty late in the stream when consolidation gains are exhausted.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress) + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && (item_size as f64) + (next_item_size as f64) <= cap {
            score += 10.0; // pair fits elsewhere; don't open a bin for this item alone
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins' usage).
    score += ((mean_residual - post) / cap).clamp(-1.0, 1.0) * 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions /10 classes
    let item_class = item_size / 10;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 10 };

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead-space penalty: residual that few future items can use
    // Usable residual classes: sizes 1..100; residual r is "usable" by items of class <= r/10
    let residual_class = post_residual / 10;
    if residual_class > 0 && residual_class < 3 {
        score += (3 - residual_class) as f64 * 6.0; // tiny unusable slivers
    }

    // Harmonic coupling: reward bins whose post_residual matches the next item class
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size { post_residual - next_item_size } else { 100 };
        score += diff as f64 * 0.15;
        // exact harmonic match: next item fills bin completely
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // modulo affinity: next item class close to residual class
        let class_gap = ((residual_class as i32 - next_class as i32).abs()) as f64;
        score += class_gap * 2.0;
    } else {
        // last item: strongly prefer zero waste
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost
    if bin_residual == bin_capacity {
        // Prefer new bin only if all open bins would leave large waste
        let best_alternative_waste = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            0.0
        };
        score += 22.0 - best_alternative_waste.min(22.0);
        // Early stream: opening bins is cheap; late stream: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // Many open bins: discourage opening more
        score += open_bins_count as f64 * 1.5;
    } else {
        // Prefer filling bins with lower residual (tighter bins) slightly
        score += (bin_residual as f64 - mean_residual) * 0.05;
        // Few fitting bins: this bin is scarce, favor it
        if fitting_bins_count <= 2 {
            score -= 8.0;
        }
    }

    // Mild preference for larger post_residual modularity: residual divisible by common class sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // leaves clean harmonic slot
    } else if post_residual % 10 != 0 && post_residual < 20 {
        score += 3.0; // awkward sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item (min size 1..100 unknown,
    // but historically >=10) can use are pure waste. Penalize gaps in the "dead zone".
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 6.0; // near-zero gap = maximally unusable
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this gap: penalize proportionally to wasted space
            score += (next_item_size as f64 - pr).max(0.0) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are plentiful;
    // encourage consolidating into existing bins as open_bins_count grows.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is attractive only if no open bin fits well
    // (i.e., poor fit here). Penalize opening a new bin when this placement is already tight.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.3;
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score += 60.0; // large item: prefer existing bin over fresh one
        }
    }

    // Late in the stream, be more conservative about dead space (less time to recover it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post residual).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 40.0; // perfect chain placement
        } else if post >= nxt {
            // how well the next item fits afterwards
            let slack = post - nxt;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; dead space penalty scaled by gap
            let gap = nxt - post;
            score += 8.0 + 0.3 * gap.min(50.0) as f64;
        }
    }

    // Reward using bins with residuals below mean (consolidate waste).
    score -= 5.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    // Penalize dipping far below mean (over-consuming large residual bins for small items).
    if (bin_residual as f64) < mean_residual - 0.5 * item_size as f64 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make fresh bin attractive only when item is large
    // relative to residual or no good chain exists.
    if bin_residual == bin_capacity {
        let openness = if next_item_size == 0 { 0.0 } else { (item_size as f64 / bin_residual as f64).max(0.0) };
        // fresh bin starts at post_residual = 0 base; add a moderate offset so it's
        // chosen only when open bins score poorly (poor fits / chain mismatch).
        score += 20.0 - 10.0 * openness;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: be greedy, avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, but normalize by capacity scale.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus: post_residual exactly 0 (or unusably small) is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let fit_bonus = 30.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual >= next_item_size {
            score -= fit_bonus;
        } else {
            // Next item won't fit here; small residual is fine, large is wasteful.
            score += 0.15 * gap;
        }
        // Chain potential: post_residual can hold next item with small slack.
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 25.0;
        }
    } else {
        // Last item: only the immediate fit matters; reward zero residual hard.
        score -= 20.0 * (1.0 - tightness);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize dumping into a large-residual bin when many alternatives exist
    // (save big-residual bins for big items).
    if fitting_bins_count > 2 && post_residual > 50 {
        score += 10.0;
    }

    // Global state coupling: when mean residual is low, conserve capacity;
    // when mean residual is high, consolidate into existing bins.
    let residual_pressure = (mean_residual / (bin_capacity as f64)) - (item_size as f64) / (bin_capacity as f64);
    score += 5.0 * residual_pressure;

    // Time horizon: early in the stream, be conservative (mild); late, be aggressive
    // about closing bins tightly since fewer items remain to fill leftovers.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; opening is justified when post_residual
        // of alternatives would be large. Score it mildly above a good fit
        // but below a wasteful one.
        score = (bin_capacity as f64) * 0.55
            - 10.0 * (1.0 - (item_size as f64) / (bin_capacity as f64))
            - (fitting_bins_count as f64) * 4.0;
        // Late in the stream, prefer closing existing bins over opening new ones.
        score += 40.0 * progress;
        // If next item is large and nothing fits well, a fresh bin is attractive.
        if next_item_size >= item_size && fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Slight preference for bins with residual close to item size (fragmentation control).
    let overhang = if bin_residual > item_size { (bin_residual - item_size) as f64 } else { 0.0 };
    score += 0.05 * overhang;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2) + norm_pr * (1.5 - p3);
    score += 20.0 * coupling * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + p2);

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr as f64 {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 6.0 * (1.0 - (nxt - pr).abs() / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Penalize spreading when many bins open relative to mean residual
    let mr = mean_residual / cap;
    score += 3.0 * open_bins_count as f64 * mr * (0.3 + p3);

    // Mild penalty for opening a brand-new bin when fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: absolute reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer residuals that are small
    // and that divide the capacity into useful fractions (mod-based classes).
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Penalize dead space non-linearly (quadratic waste)
    score += 2.0 * frac * frac * cap;

    // Modulo classes: residuals that are multiples of common item sizes
    // (10..80 range => multiples of 10 are reusable) are less "dead".
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 5.0 + 0.1 * pr;
    } else {
        score += 3.0 + rem10 as f64;
    }

    // Residual classes via integer division thresholds
    let class = post_residual / 10; // 0..=10 harmonic bucket
    match class {
        0 => score -= 20.0,          // near-perfect fill
        1 => score -= 10.0,          // small gap, likely reusable
        2 | 3 => score -= 3.0,       // medium gap
        8 | 9 | 10 => score += 10.0, // nearly empty bin chosen wastefully
        _ => {}
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward residuals that leave room for the next item tightly
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: slight penalty for hoarding space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let baseline = cap + 2.0 * 0.0 + 3.0; // approx score of empty-bin call for itself
        // Default: new bin is worse than any reasonable existing fit
        score = cap + 25.0;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 40) {
            // no fit or terrible fits exist elsewhere; allow opening
            score = cap - 5.0;
        }
        let _ = baseline;
    }

    // Mild progression term: later in the stream, prefer tighter packing
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * (1.0 - frac);

    // Prefer bins below mean residual (balance load)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for the smallest item are unusable.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 50.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit: post_residual small but usable.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item would leave a dead gap in an existing bin, opening new is fine.
        if dead {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the mean (balanced usage).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post_residual relative to typical next item size (dead space).
    if next_item_size > 0 {
        let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
        score += 0.35 * waste;
        // Reward if next item fits snugly into post_residual.
        if post_residual >= next_item_size {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * snug;
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness;

    // Penalize when this bin is one of many fitting options but fit is mediocre.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0) * (1.0 - tightness);
    }
    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global state: if mean residual is high and many bins open, prefer filling
    // existing bins aggressively (avoid bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        let spread = (post_residual as f64 - mean_residual).abs();
        score += 0.1 * spread;
        score -= (open_bins_count as f64).ln() * (1.0 + progress) * (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    // New-bin candidate handling: only attractive if item is large and no open bin
    // fits well; otherwise discourage opening fresh bins.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * poor_fit_elsewhere * big_item;
        score += 3.0 * (1.0 - big_item);
    }

    // Early stream: slight preference for compacting into few bins.
    if progress < 0.3 {
        score += 2.0 * (1.0 - progress / 0.3) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 8.0 * poly * (1.0 + 0.5 * progress);

    // Penalize near-tight fits that leave awkward residuals relative to mean residual.
    let mean_gap = pr - mean_residual;
    score -= 0.35 * mean_gap * (1.0 - progress);
    score += 0.15 * mean_gap * progress;

    // Reward perfect / small residuals more strongly later in the stream.
    let tightness = (cap - pr) / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 5.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure against excessive open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless residual is genuinely large.
    if bin_residual == bin_capacity {
        score += 4.0 - 3.0 * progress;
        if pr < 25.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual: capacity fractions (C=100)
    // Residuals in {0, 10, 20, 25, 50} are "harmonic" — likely reusable.
    let harmonic = match post_residual {
        0 => 1.0,
        10 => 0.9,
        20 => 0.8,
        25 => 0.7,
        50 => 0.6,
        _ => {
            let q = post_residual / 10;
            if q * 10 == post_residual { 0.3 } else { 0.0 }
        }
    };
    score -= 12.0 * harmonic;

    // Modulo arithmetic: residual divisible by small classes is more reusable
    if post_residual > 0 {
        if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 10 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chaining is the ideal outcome
            score -= 25.0;
            // Integer-division threshold: near-exact chain (residual within one class)
            let diff = post_residual - next_item_size;
            if diff <= 5 { score -= 10.0; }
            if diff % 10 == 0 && diff > 0 { score -= 4.0; }
        } else {
            // Next item won't chain here; penalize by gap size class
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 6.0; // tantalizingly close, wasted
            } else {
                score += 2.0 + gap as f64 / 20.0;
            }
        }
    } else {
        // Last item: zero residual is king
        if post_residual == 0 { score -= 60.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    if open_bins_count > 3 {
        score -= 2.0 + (open_bins_count as f64).ln() * 1.5;
    }

    // Mean residual context: bin far below mean residual is a poor host
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // NEW-BIN CANDIDATE (bin_residual == bin_capacity): only open a new bin
    // when the item is large relative to capacity or no good chain exists.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 * 0.72; // post_residual would be 100-item
        score = new_bin_base;
        // Large items: opening fresh is fine
        if item_size >= 60 { score -= 20.0; }
        if item_size >= 80 { score -= 15.0; }
        // If next item chains into the new bin's residual, opening is attractive
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        // If this bin is the only fit among open bins, never prefer new bin
        if fitting_bins_count >= 1 {
            score += 30.0;
        }
        // Late in stream: consolidate, avoid opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Small tie-breaker: exact fill beats everything
    if post_residual == 0 { score -= 15.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize mid-range residuals that few item sizes can still use.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += pressure * 3.0;
    } else {
        score -= pressure * 0.05;
    }

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Prefer bins whose residual is below the mean (tighter packing).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it packs
            score -= 100.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 50.0 + 0.2 * item_size as f64;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Early in stream: be slightly greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.2 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to capacity).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Penalize large dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual > 0 && post_residual < item_size.min(100) {
        score -= 3.0; // dead space smaller than next plausible item
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 4.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 1.5; // next item won't fit here
        }
    }

    // Last chance: this is the only bin that fits -> strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are bad.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit = (post_residual as f64) > mean_residual * 0.5;
        if bad_fit && open_bins_count > 0 {
            score -= 5.0 + 8.0 * (1.0 - progress);
        } else {
            score += 10.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Prefer bins whose residual deviates below mean (consolidate space).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Late stream: be more frugal, avoid opening bins; reward reuse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let pr_n = pr / bin_capacity as f64;
    // Smooth non-linear coupling: penalize residual quadratically as stream progresses
    score += 12.0 * pr_n * pr_n * (0.5 + progress);
    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 8.0 * (1.0 - pr_n) * (1.0 - pr_n) * progress;
    // Dead-space penalty: residual too small to be useful for typical items
    if pr < 10.0 {
        score -= 15.0 * (1.0 - pr / 10.0);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }
    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }
    // Cubic interaction of progress with normalized residual
    score += 5.0 * pr_n * pr_n * pr_n * (1.0 - progress);
    // Mild penalty for scattering across many open bins
    score += 0.3 * open_bins_count as f64 * pr_n;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo classes: residuals that are multiples of common small item
    // sizes (10, 20, 25, 50) remain "harmonically usable" later.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 15.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 10.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 8.0;
    }
    if r % 50 == 0 && r > 0 {
        score -= 10.0;
    }

    // Dead-zone: residuals in awkward middle ranges (e.g. 11..=19, 21..=24,
    // 26..=39) are hard to fill for typical item sizes.
    if (11..=19).contains(&r) {
        score += 12.0;
    } else if (21..=24).contains(&r) {
        score += 8.0;
    } else if (26..=39).contains(&r) {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 60.0;
        } else if r >= next_item_size && r - next_item_size <= 5 {
            score -= 25.0;
        } else if next_item_size > r {
            // Next item cannot go here; mild penalty proportional to overflow.
            score += ((next_item_size - r) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // bad fit unless the fit is actually good.
    if fitting_bins_count == 1 && post_residual > 20 && next_item_size > post_residual {
        score += 15.0;
    }

    // New-bin candidate handling: an empty bin has high raw post_residual,
    // which is naturally unattractive; but if no open bin fits well, allow
    // opening a new bin. Reward new-bin option when current bins are crowded.
    if bin_residual == bin_capacity {
        // Fresh bin: post_residual = capacity - item_size.
        // Score it relative to mean residual of open bins: prefer opening
        // a new bin when open bins are already fragmented.
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        // Penalize new bin slightly when many bins are open (prefer consolidation).
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Reward if item is large (fills fresh bin well).
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Progress-aware tie-breaking: early in stream, mildly prefer tight
    // packing into existing bins; late in stream, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    // Small preference for bins with residual close to item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += snug * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the next item
    // (or below a typical minimum item size) are nearly worthless.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 1 };
    if post_residual > 0 && post_residual < min_useful {
        score += 30.0 * (min_useful as f64 - post_residual as f64);
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is a good multiple match for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64).min(10.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 8.0 * pressure;
        // Early in the stream, opening a new bin is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 3.0 * pressure;
    }

    // Prefer bins with residual below the mean (denser bins) slightly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mut score = post;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next <= post {
            score -= 12.0 + 0.5 * (post - next); // tight lookahead match is best
        } else {
            // penalize post_residual that is just barely too small (dead space)
            let overshoot = next - post;
            if overshoot < 15.0 {
                score += 0.8 * overshoot;
            }
        }
    }

    // Prefer post_residual close to mean residual band edges: avoid stranding mid-size gaps
    let gap = post - mean_residual;
    score += 0.15 * gap.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage tightening existing bins rather than spreading
    if open_bins_count > 4 {
        score -= 0.05 * (open_bins_count as f64) * (1.0 - post / capacity);
    }

    // Late in the stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post / capacity);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize dead space quadratically when post-residual is small but nonzero
    // (a small leftover is often unusable, but a perfect fit is best).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * dead * (1.0 - dead);
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_eff = (item_size + next_item_size) as f64 / bin_residual.max(1) as f64;
            score -= 35.0 * pair_eff.min(1.0);
        } else {
            score += 8.0; // leftover too small for lookahead: wasted space risk
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0 + 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // fits poorly everywhere else or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - bin_capacity as f64).abs() / bin_capacity as f64;
        let poor_fit = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * (1.0 - poor_fit) - 20.0 * fragmentation;
        if fitting_bins_count == 1 {
            score += 45.0; // keep using the last-chance bin instead of opening
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Mild preference for bins below-average residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, be greedier: close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill_ratio;

    // Slight penalty per open bin to discourage spreading items thin.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_frac = pr / cap;

    let mut score = pr;

    // Reward tight fits: smooth non-linear decay of residual
    score -= 40.0 * (1.0 - fit_frac).powi(3);

    // Penalize large dead space quadratically (wasted capacity)
    score += 0.5 * fit_frac * fit_frac * cap;

    // Stream-progress coupling: early on, keep bins flexible (favor larger residuals slightly);
    // late in stream, strongly prefer filling bins tightly.
    score += (1.0 - progress) * 15.0 * fit_frac;
    score -= progress * 30.0 * (1.0 - fit_frac).powi(2);

    // Lookahead: if next item fits in the post-residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - nxt / cap);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - fit_frac);
    }

    // New-bin candidate: penalize opening a new bin, especially when other bins fit
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
        }
        // Early stream: opening bins is fine (score reduced); late stream: discourage
        score -= 20.0 * (1.0 - progress);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 / capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Reward tight fits: exact fill is best
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else if post_residual <= 20 {
        score -= 80.0;
    }

    // Dead-space penalty: residual in awkward zone (just above half) is hard to fill
    if pr > cap * 0.5 && pr < cap * 0.8 {
        score += 30.0;
    }

    // Harmonic class: post_residual divisible by 10 pairs well with typical item grids
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Odd tiny residues are dead space
    if post_residual % 10 != 0 && post_residual < 15 {
        score += 15.0;
    }

    // Integer-division thresholds: how many small items (<=10) fit in post_residual
    let small_slots = post_residual / 10;
    score -= 8.0 * small_slots as f64;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward leaving room exactly usable by next item
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.4 * slack;
            if slack == 0.0 {
                score -= 120.0; // perfect chain
            }
        } else {
            score += 20.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // packing big items into fresh bins is fine
        }
    }

    // Stream progression: early on, be greedy about consolidation; late, prefer balance
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr - mean_residual).abs() * 0.3;

    // Many open bins: discourage leaving large residuals scattered
    if open_bins_count > 5 {
        score += 0.2 * (open_bins_count as f64) * (1.0 - frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item (size 1
    // here, but tiny gaps are still hard to use) are heavily penalized nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }

    // Reward tight fits: small post_residual relative to item size is excellent.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 * (-tightness).exp();

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If the leftover gap could exactly fit the next lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize a gap that is slightly larger than the next item (wasted potential).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 5 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate: opening a bin is cheap when few bins are open, expensive
    // when many are open. Add open-bins pressure to the fresh-bin candidate.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
        // But if the current item is large and no open bin fits well, allow opening.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= 1.0 * open_bins_count as f64;
    }

    // Progress-based calibration: later in the stream, consolidation matters more,
    // so penalize leaving medium-sized residuals that fragment capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score += 10.0 * progress;
    }

    // Slight preference for bins whose residual is below the mean (compact bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item leaves a tiny remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
    }
    // Next item cannot fit here at all: mild penalty relative to gap.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize unusable dead space (post_residual below min item size 1 is fine,
    // but tiny residuals under ~10 are dead weight on unknown distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - post_residual as f64;
    }

    // Reward bins whose residual is far below mean (tight packing), penalize loose bins.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with the upcoming big item
        }
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(2) as f64);
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score;

    if is_new_bin {
        // Candidate for opening a fresh bin.
        score = 95.0 - 0.35 * item - 8.0 * progress;
        // If no open bin fits, opening is nearly mandatory.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items early benefit from a dedicated fresh bin.
        if item > 0.6 * cap && progress < 0.5 {
            score -= 10.0;
        }
        // If the next item would perfectly stack on the remainder, fresh bin is attractive.
        if next_item_size > 0 && (item + next_item_size as f64) <= cap {
            score -= 6.0;
        }
    } else {
        // Base: prefer minimal leftover space.
        score = post;

        // Reward tight fits (large fill ratio of the used space).
        score -= 0.15 * item;

        // Dead-space penalty: tiny unusable remainders are worse than exact fills.
        if post > 0.0 && post < 10.0 {
            score += (10.0 - post) * 0.6;
        }

        // Lookahead: if the next item still fits here, this bin stays productive.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if nxt <= post {
                score -= 5.0 + 0.1 * (cap - post - nxt).min(50.0);
            } else if post > 0.0 && nxt > post {
                // This placement likely strands the bin; penalize proportionally.
                score += 0.15 * post;
            }
        }

        // Last chance: if this is the only bin that fits, strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else if fitting_bins_count > 1 {
            // Many options: be pickier about wasteful placements.
            score += 0.05 * post;
        }

        // Global context: if mean residual is high, prefer consolidating into emptier bins.
        if post > mean_residual {
            score += 0.1 * (post - mean_residual);
        } else {
            score -= 0.05 * (mean_residual - post);
        }

        // Late in the stream, avoid spreading residual capacity across many bins.
        if progress > 0.7 && post < 20.0 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Quadratic penalty on wasted space, amplified late in the stream.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction: small residuals are fine early, heavily penalized late.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Perfect fit reward, stronger as stream progresses.
    if pr == 0 {
        score -= 30.0 * (0.5 + progress);
    } else {
        // Smooth reward for near-perfect fits (small post_residual relative to capacity).
        score -= 20.0 * (1.0 - norm_pr).powi(6) * (0.3 + progress);
    }

    // Lookahead: reward if next item fits into post_residual (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - fits / cap;
        score -= 10.0 * fit_quality * fit_quality * (1.0 - progress);
        // Penalize leaving residual that almost-but-not-quite fits next item.
        if nxt > pr {
            score += 5.0 * (1.0 - pr / nxt) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.4 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // and early in the stream; relax late when consolidation may be exhausted.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 6.0 * open_pressure * (1.0 - progress) + 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening new bin is more acceptable.
        score -= 0.05 * mean_residual;
    }

    // Mild penalty for bins whose residual is far from mean residual (fragmentation).
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // capacity fractions (quarters) and modulo structure.
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4; // 25 with C=100
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals that are too small to hold any
    // plausible future item (below the smallest common class) are waste.
    if post_residual < 10 {
        score += 60.0 - pr * 3.0;
    }

    // Harmonic class rewards: residual exactly matching a capacity fraction
    // or a modulo-friendly value is more reusable.
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Residuals just above a "harmonic threshold" (e.g. 50, 25) are awkward:
    // too big to waste but barely below common item classes.
    if post_residual > 0 && post_residual < quarter {
        score += (quarter - post_residual) as f64 * 1.5;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chainable placement: reward proportional to tightness of the chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 + 15.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize if the leftover becomes dead space.
            score += (next_item_size as f64 - pr) * 0.4;
        }
        // Harmonic class match between next item and post-residual modulo class.
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no open bin offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (consolidation pressure) and early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 - 10.0 * progress - 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Empty bin is great for very large items (poor fits elsewhere).
        if item_size > half {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0; // next item completes a fresh bin perfectly
        }
    }

    // Mild consolidation: prefer bins whose residual is below the mean
    // (filling the emptier-feeling bins keeps many tight bins around).
    if bin_residual != bin_capacity {
        let dev = mean_residual - pr;
        score += dev * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    // (gaps that cannot fit even the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large leftover space that is still "wasted" relative to
    // typical item sizes (dead space that no item will likely fill).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 15.0 + 20.0 * progress;
    if post_residual as f64 > dead_threshold && post_residual < item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 6.0;
        // But if this bin is the only fitting bin, opening a new bin is
        // less attractive (last-chance pressure against new bins).
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // If next item is large and mean residual is small, opening a
        // fresh bin may be wise: soften the penalty.
        if next_item_size as f64 > mean_residual + 20.0 {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is close to being consumed.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;

        // Last-chance bin: strongly favor filling it rather than opening new.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Lookahead: if the next item fits exactly in the post residual,
        // reward this placement (good chaining).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
        // If next item cannot fit into post residual and post residual is
        // small-but-usable, mild penalty for fragmenting.
        if next_item_size > post_residual && post_residual < item_size {
            score += 5.0;
        }

        // Mean residual coupling: prefer bins below mean residual
        // (consume the tightest bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap * gap);
        // Slight extra reward for exact match
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that can't fit the next item at all
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 40.0;
    }

    // Penalize bins with residual far below the mean residual (waste-prone bins)
    score += 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when item is large or no good fits exist
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 20.0 * tightness;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Slight preference for opening fewer bins early in the stream
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    let min_item = 1.0;
    if post_residual > 0 {
        let unusable = ((post_residual as f64) - min_item) / (bin_capacity as f64);
        score += 3.0 * unusable * unusable * (1.0 - tightness);
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 5.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            let gap = (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
            score += 4.0 * gap;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be conservative about filling bins poorly;
    // late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.4;
    score -= progress * 2.0 * tightness;

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // penalize opening new ones.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        score -= 0.02 * mean_residual * tightness;
        score += 0.1 * open_bins_count as f64 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, quadratically, modulated by stream progress
    let mut score = x * (1.0 + 2.0 * x * x) * (1.0 + 0.8 * progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 8.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Coupling with mean residual: prefer bins whose post-residual is close to mean
    // (keeps residuals homogeneous, preserving combinability of future items)
    let spread = (x * cap - mean_residual).abs() / cap;
    score += 3.0 * spread * spread;

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 4.0 * (1.0 - pr / nxt.max(1.0)) * (0.6 + 0.4 * progress);
        } else {
            // reward leaving room exactly for next item
            score -= 3.0 * (1.0 - ((pr - nxt) / cap).powi(2));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - x);
    }

    // New-bin candidate: make it attractive only when current bin would leave bad residue
    if bin_residual == bin_capacity {
        let badness = (x * (1.0 - x) * 4.0); // 0 at x=0/1, high mid — no-op shape
        score = 2.0 + 10.0 * (1.0 - x) * (1.0 - x) - 2.0 * badness * progress;
        if fitting_bins_count <= 1 {
            score += 5.0;
        }
    }

    // Mild penalty for bin proliferation
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of common
    // item sizes are more reusable. Reward post_residuals divisible by small
    // divisors (2,4,5,10,20,25) which align with typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [2u32, 4, 5, 10, 20, 25] {
            if pr % d == 0 {
                harmony += 6.0;
            }
        }
        // Exact multiples of likely item sizes are ideal landing zones.
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr == m {
                harmony += 15.0;
            }
        }
        score -= harmony;
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Penalize tiny dead space that no item (min size 1..10) can use well:
    // residuals of 1..9 are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item nearly fits, small penalty for blocking.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let diff = pr - next_item_size;
            if diff == 0 {
                score -= 50.0;
            } else if diff < 10 {
                score -= 20.0;
            } else {
                // Larger leftover after next item: mild reward scaled by fit.
                score -= 10.0 * (1.0 - diff as f64 / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize based on how close it was.
            let miss = next_item_size - pr;
            score += (miss as f64).min(30.0);
        }
    }

    // Last-chance bin: this is the only bin that fits; avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when open bins are crowded (low mean residual).
    if bin_residual == bin_capacity {
        score += 55.0;
        if mean_residual < 20.0 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins with small residuals (tight packing pressure).
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Slight preference to balance bin count over the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size band) are heavily penalized.
    if post_residual > 0 {
        let dead_zone = 20.0; // gaps <= 20 are likely unusable dead space
        if (post_residual as f64) <= dead_zone {
            score += (dead_zone - post_residual as f64) * 12.0;
        }
        // Perfect fill is strongly rewarded.
        if post_residual == 0 {
            score -= 60.0;
        }
    } else {
        score -= 60.0;
    }

    // Reward tight fits: item consuming a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Penalize bins whose residual deviates far above the mean residual
    // (fragmented stock), mildly reward near-mean bins.
    let dev = bin_residual as f64 - mean_residual;
    score += (dev * 0.15).abs().min(15.0);

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus open-bin pressure.
        score += 45.0 + pressure;
        // Late in the stream, opening new bins is even less attractive.
        score += progress * 30.0;
    } else {
        // Existing bins get a mild bonus that grows with open-bin pressure.
        score -= pressure * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement strongly (chains well).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= 15 {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // post-residual too small for the lookahead: mild penalty.
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Near-perfect fit reward (dead space <= 10)
    if post_residual <= 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            // penalize second-step dead space
            score += leftover2 as f64 * 0.8;
            if leftover2 <= 5 {
                score -= 150.0; // tight chain fit
            }
        } else {
            // next item cannot fit here: this is a terminal placement
            score += 120.0;
        }
    }

    // Penalize large unusable residuals (dead space) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // awkward small gap
    }
    if post_residual > 50 {
        score -= 60.0; // large residual still flexible
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Early in stream: encourage packing tightly to build good bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: only open a new bin if no decent fit exists
    if bin_residual == bin_capacity {
        // default mild penalty so existing reasonable bins win
        score += 90.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 500.0; // next item needs a fresh bin anyway
        }
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that nothing can fill (min item size 1)
        score += (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0;
            // chain fit quality
            let chain = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize small leftovers
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: strongly prefer tight fit
        score -= 300.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Time horizon: later in stream, prefer filling existing bins tighter
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 60.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor best fits
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual far from item are less attractive
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        if pressure > 0.0 {
            score -= 200.0; // no alternative: open new bin
        } else if poor_fit && post_residual as f64 > mean_residual {
            score += 150.0; // small item into big residual: wasteful, prefer existing bins
        } else {
            score += 80.0; // default: prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 20.0 * norm_pr * norm_pr
        + 40.0 * norm_pr * norm_pr * norm_pr;

    // Smooth coupling of post_residual with stream progress:
    // later in the stream, waste matters more (weight grows smoothly)
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Penalize near-full bins slightly less if they leave a tiny dead zone;
    // smooth reward for small post_residual (good packing)
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Lookahead: reward bins whose post_residual can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - fit_margin) * (1.0 - fit_margin);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // Prefer bins whose residual deviates favorably from mean (tighter bins first)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate handling: empty bin gets a moderate baseline
    if bin_residual == bin_capacity {
        score = 100.0 - 40.0 * progress;
        if fitting_bins_count == 0 {
            score = -10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = match post_residual {
        0 => 0u32,                          // perfect fit — golden
        x if x <= eighth => 1,              // tiny remainder
        x if x <= quarter => 2,             // small remainder
        x if x < 2 * quarter => 3,          // half-ish remainder
        _ => 4,                             // large remainder (wasteful)
    };

    // Reward perfect and near-perfect fits strongly.
    match class {
        0 => score -= 1000.0,
        1 => score -= 200.0 + (eighth - post_residual) as f64 * 20.0,
        2 => score -= 60.0 + (quarter - post_residual) as f64 * 4.0,
        3 => score -= 10.0,
        _ => score += 30.0, // leaving > half a bin free is wasteful
    }

    // Harmonic pairing: does the next item fit exactly into the post-residual,
    // or into a harmonic fraction of it?
    if next_item_size > 0 {
        let n = next_item_size;
        if n == post_residual {
            score -= 500.0; // exact lookahead match
        } else if n <= post_residual {
            let gap = post_residual - n;
            if gap <= eighth {
                score -= 150.0;
            } else if gap <= quarter {
                score -= 40.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot follow here; penalize leaving residual it can't use
            score += (n - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin only attractive if the item leaves a bad class in existing bins
        score += match class {
            0 | 1 => 400.0,
            2 => 150.0,
            3 => 40.0,
            _ => -50.0,
        };
        // if several bins fit, opening new is rarely good
        if fitting_bins_count > 1 {
            score += 100.0;
        }
    }

    // Mean-residual coupling: when open bins are generally full, conserve them.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual < (item_size as f64) {
        score += 20.0; // bins are tight; be greedy with space
    }
    score *= 1.0 + 0.1 * progress;

    // Integer-division threshold nudge: prefer residuals divisible into
    // common item sizes (harmonic compatibility with size classes).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Very tight fits are excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bins pressure: discourage scattering across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: prefer leaving space that fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Deviation from mean residual: prefer bins close to the packable norm.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // New-bin candidate: keep it competitive only when current bin leaves bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * ((post_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: reward small post_residual relative to bin capacity
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 50.0 * tightness;

    // 2-step lookahead: reward post_residual that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward proportional closeness of the pair-fill
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 120.0 / (1.0 + pair_waste);
        } else {
            // next item does not fit; penalize dead space that blocks it
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual of open bins: prefer bins already deviating low
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: make opening a new bin only attractive when
    // no open bin offers a genuinely tight fit (post_residual small or exact pair match)
    if bin_residual == bin_capacity {
        // base attractiveness of a fresh bin: its residual is maximal (post = capacity - item)
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && (bin_capacity - item_size) <= next_item_size {
            score += 30.0; // fresh bin cannot chain the next item well
        }
        if fitting_bins_count >= 1 {
            score += 150.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 100.0; // fresh bin pairs perfectly with next item
        }
    }

    // Late-stream consolidation: prefer packing into existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residuals non-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasteful splits.
            score += 6.0;
        }
    }

    // Prefer filling bins that are already relatively full (residual small).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * fullness;

    // Global balance: prefer bins with residual below the mean (consolidate space).
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins for large items;
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling by progress and current bin count.
        let mut new_bin_score = 55.0 + 70.0 * progress + 3.0 * open_bins_count as f64;
        // Opening a new bin is more attractive if the item is large and fits poorly elsewhere.
        if item_size >= 50 {
            new_bin_score -= 15.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // forced: no open bin fits
        }
        score = score.min(new_bin_score) * 0.0 + new_bin_score;
    } else {
        // Late stream: extra reward for using existing bins.
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * 0.5;
    score += 20.0 * poly;

    // Reward tight fits, more aggressively late in the stream
    score -= (1.0 - norm_pr) * (1.0 + progress) * 8.0;

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin: reward strongly to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: favor bins whose post-residual pairs well with next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let gap = pr - n;
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 4.0 + 0.1 * (n - pr);
        }
    } else {
        score -= 5.0; // last item: just minimize residual
    }

    // New-bin candidate: neutral-ish baseline with progress-dependent penalty
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress + 0.5 * pr;
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Slight penalty for bin sprawl late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" multiples
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: strongly reward zero post_residual
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward post_residuals divisible by common item granularities (harmonic classes)
    let harmonic_bonus: f64 = if post_residual % 10 == 0 {
        40.0
    } else if post_residual % 5 == 0 {
        20.0
    } else if post_residual % 2 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize dead space: post_residual too small for any plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // only tiny items fit
    }

    // Integer-division threshold: post_residual bucket quality
    let bucket = post_residual / 25; // 0..=4
    score -= bucket as f64 * 5.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size as f64) / cap;
            score -= 100.0 * (1.0 - slack); // tighter lookahead fit is better
        } else {
            // next item won't fit here; mildly penalize wasting capacity on this bin
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate: neutral baseline; only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.85;
        // Cheaper to open a new bin when many open bins have large fragmented residuals
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 30.0 * fragmentation;
        // Early in stream, opening bins is cheaper (need inventory of bins)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If item is large, fresh bin gives full flexibility
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild preference to fill fuller bins (small residual) when alternatives exist
    score -= (1.0 - bin_residual as f64 / cap) * 15.0;

    // Spread control: many open bins -> favor consolidating into existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Dead space penalty: gaps too small to hold even the smallest plausible item
    // (or too small for the lookahead item) are "wasted" capacity.
    let min_gap = next_item_size.min(10).max(1);
    if post_residual > 0 && post_residual < min_gap {
        score += 40.0; // unusable sliver
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap can't host the next item: penalize proportionally, but less if gap still usable generally
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // favor bins whose residual is close to mean (consolidation).
    let open_pressure = open_bins_count as f64;
    score += 0.3 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins near the mean residual to keep
    // the population of gaps homogeneous and predictable for future items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream, be slightly more willing to open bins (exploration);
    // later, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; cheaper early, expensive late.
        score = bin_capacity as f64 * 0.9 - 20.0 * (1.0 - progress) + 5.0 * progress * open_pressure;
        // If no open bin fits well, opening a new bin is fine (handled by comparison).
        if post_residual == bin_capacity {
            score += 0.0;
        }
    } else {
        // Late stream: extra reward for using existing bins aggressively.
        score -= 10.0 * progress * tightness;
    }

    // Small lookahead coupling: if this placement leaves room exactly for the next item,
    // give a modest bonus (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (minimizes dead space to zero)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item chain into this bin?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chaining, prefer chains that leave minimal slack after the next item
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 40.0 + 60.0 / (1.0 + slack_after_next);
        } else {
            // Residual too small for the lookahead item: penalize unusable dead space
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Tightness relative to the mean residual across open bins:
    // penalize bins whose post-residual exceeds the average (worse-than-average leftover)
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: if this is the only open bin that fits, strongly prefer using it
    // over opening a new bin (unless it's the new-bin candidate itself)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit the item: opening a new bin is mandatory
            score -= 500.0;
        } else {
            // Prefer existing bins generally; escalate penalty when many alternatives exist
            score += 60.0 + 5.0 * fitting_bins_count as f64;
            // Late in the stream, avoid proliferating bins with leftover capacity
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 40.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 40.0;

    // Exact fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * post_residual as f64;
    }
    // Reward residual that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Penalize leaving very small unusable slivers relative to min item size (1..100, use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    // or many bins are open with high mean residual (fragmentation pressure).
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        if mean_residual > 25.0 && open_bins_count > 2 {
            score -= 10.0; // fragmentation: prefer fresh bin
        }
        // Early in the stream, slightly cheaper to open bins (build a spread).
        score -= (1.0 - t) * 8.0;
    }

    // Mild pressure to prefer bins below mean residual (balance load).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins as stream progresses.
    score -= t * (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += pr_norm * pr_norm * (1.0 + progress) * cap * 0.35;

    // Reward tight fits (high fit_ratio) with smooth saturation
    score -= (fit_ratio * fit_ratio) * (1.0 + progress) * 18.0;

    // Penalize large dead space quadratically relative to next item size
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += (gap / cap) * (gap / cap) * 12.0 * (1.0 - progress * 0.5);
        } else {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty when many open bins (encourage consolidation)
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.5;

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += ((pr - mean_residual) / cap).abs() * 3.0;

    // New-bin candidate: penalize opening new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste in fine-grained classes
    let r = post_residual;
    let class = r / 10; // integer division thresholds (0..10)
    score += (class as f64) * 3.0;

    // Perfect-fit harmonics: residuals that are multiples of small item sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if r >= m && r % m == 0 {
            score -= 8.0 + (m as f64) * 0.2;
        }
    }

    // Penalize odd/awkward residuals (non-multiples of 5) -> dead space
    if r % 5 != 0 {
        score += 6.0;
    }
    if r % 10 != 0 && r % 5 == 0 {
        score += 2.0;
    }

    // Tight fit reward: post_residual small relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= (1.0 / (1.0 + tightness)) * 10.0;

    // Lookahead coupling: does next item fit the post-residual exactly / at all?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0; // perfect chain
        } else if next_item_size <= r {
            let frac = next_item_size as f64 / r as f64;
            score -= frac * 12.0;
            if r % next_item_size == 0 {
                score -= 6.0; // harmonic divisibility
            }
        } else {
            // next item cannot use residual: penalize large leftovers less if divisible
            score += (r as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: default neutral-ish, but prefer opening new bin
    // only when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill = item_size as f64 / bin_capacity as f64;
        if fill < 0.35 && fitting_bins_count > 0 {
            score += 40.0; // don't open new bin for tiny items with fits available
        } else {
            score -= 5.0 + progress * 5.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins -> prefer existing bins
    score += open_bins_count as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest item (1) is pure waste;
    // residuals that can only fit tiny items are near-waste.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space (below min item size) -> heavy penalty.
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits proportionally: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins to avoid excessive bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item almost fits but not quite (near-miss creates pressure).
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: penalize bins whose residual is far above mean
    // (they are likely to become dead-space bins), reward below-mean bins.
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score += 0.15 * (bin_res_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_res_f);
    }

    // New-bin candidate handling: empty bin should only win when existing bins
    // would create significant dead space. Give it a mild baseline penalty so
    // reasonable fits in open bins win, but not so large that a bad fit beats it.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If open bins are few and item is large, opening fresh is less costly.
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space, super-linear for small dead space.
    score += (post_residual as f64).powf(1.35) * 0.05;

    // Aggressive 2-step lookahead: reward near-perfect match of post_residual to next item.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            // Perfect 2-step fit: huge reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits exactly into the leftover: reward proportional to tightness.
            score -= (30.0 * (1.0 - match_gap / bin_capacity as f64)).max(0.0);
        } else {
            // Next item would NOT fit: penalize, worse when gap is small (teasing fit).
            score += 10.0 + 20.0 * (1.0 - match_gap / bin_capacity as f64);
        }
    } else {
        // Last item: only care about current fill tightness.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean-residual coupling: bins below mean residual (more filled) are favored.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: discourage opening a new bin unless nothing decent fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 10.0 * progress;
        // If many bins can fit, opening a new bin is almost always worse.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If the item is large, a fresh bin is more acceptable.
        score -= item_size as f64 * 0.15;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to ever hold a plausible item
    // (dead space < 10 is nearly unusable; < next_item_size is unusable for lookahead).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0;
        } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 12.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist; scale penalty
    // with how crowded the current bin set is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = (open_bins_count as f64).ln().max(1.0);
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
        score += 15.0 + 20.0 * mean_tightness + 5.0 * crowd + 10.0 * progress;
        // If the item is large, opening a fresh bin is less bad.
        score -= item_size as f64 * 0.15;
    }

    // Slight preference to fill bins that are already below-mean residual
    // (concentrate usage rather than spreading it).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, squeeze residual harder
    score -= 12.0 * progress * (1.0 - norm_pr).powi(3);

    // Lookahead: reward if next item fits into post residual (smooth interaction)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits = if pr >= n { 1.0 } else { 0.0 };
        let slack_fit = ((pr - n).abs()) / cap;
        score -= 10.0 * fits * (1.0 - slack_fit) * (1.0 - 0.5 * progress);
        // Penalize leaving residual just slightly below next item (dead space trap)
        if fits < 1.0 && n > pr {
            let gap = (n - pr) / cap;
            score += 8.0 * (1.0 - gap) * gap.max(0.0) * 4.0;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    } else if fitting_bins_count > 1 {
        // mild dispersion preference: spread load when many bins fit
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening a bin unless residual waste would be large
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score = 40.0 + 30.0 * waste * waste - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residues divisible by 10 are
    // "clean" slots (item sizes often quantized), odd residues are dead space.
    let pr = post_residual as u32;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -6.0,
        5 => -2.0,
        2 | 4 | 6 | 8 => 1.0,
        _ => 4.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual bucketed in eighths of capacity.
    let bucket = pr * 8 / bin_capacity.max(1);
    score += match bucket {
        0 => -8.0,             // near-perfect fill
        1 => -3.0,
        2 => 0.0,
        3 => 2.0,
        _ => (bucket as f64 - 3.0) * 3.0, // large unusable remainder
    };

    // Tight-fit reward: item consumes >= 80% of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * fill_ratio;
    } else if fill_ratio < 0.3 {
        score += 6.0 * (0.3 - fill_ratio); // wasteful placement
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: penalize leftover proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless all open bins would
    // leave very bad fits. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        let bad_fits = if post_residual > 0 { 0.0 } else { 0.0 };
        let _ = bad_fits;
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        // Prefer new bin only if every existing fit would waste a lot.
        let escape_bonus = if mean_residual > 40.0 { 4.0 } else { 0.0 };
        score = 30.0 + (cap - item_size as f64) * 0.4 - escape_bonus
            + if fitting_bins_count == 0 { 0.0 } else { mean_waste * 0.1 };
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }

    // Reward near-perfect fits (very small residual left that is still usable).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward tight fits relative to the item: fill ratio bonus.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize wasting a mostly-empty bin on a small item.
    if item_size < bin_residual / 3 {
        score += 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small relative to the item.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        score = 40.0 - 50.0 * pressure + 1.5 * open_bins_count as f64;
        // Lookahead: if next item is large, opening fresh space is less useful.
        if next_item_size > item_size {
            score += 5.0;
        } else if next_item_size > 0 && post_residual >= next_item_size as u32 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: this bin's post-residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Partial reward: next item can still fit in the residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize residuals too small for any future item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Relative-to-mean adjustment: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive if no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * open_bins_count as f64;
    }

    // Mild progression scaling: tighten later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // Dead space relative to the next item.
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when many open bins have ample mean residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = mean_residual - (bin_capacity as f64 - item_size as f64);
        if waste > 0.0 {
            score += 0.3 * waste * (1.0 + progress);
        }
        // New bins are less attractive early when few bins are open.
        score += 10.0 / (1.0 + open_bins_count as f64);
    } else {
        // Prefer bins with residual closest to item (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += 0.1 * gap;
        // Favor fuller bins slightly.
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling: residual value decays with progress
    let decay = 1.0 - progress * progress;
    score -= pr * (0.5 + 0.5 * decay);
    // Penalize large post-residuals late in the stream (dead space)
    score += norm_pr * norm_pr * cap * progress;
    // Reward tight fits (small post_residual relative to item)
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= tightness * tightness * 10.0;
    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }
    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: mild penalty unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.05;
    }
    // Prefer bins below mean residual (compact bins)
    score += (mean_residual - pr) * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear waste penalty: dead space hurts more the larger it is.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Harmonic class logic: classify post_residual into decile buckets.
    // Residuals in "awkward" classes (hard-to-fill remainders) get a penalty,
    // "clean" classes (multiples of 10 / small remainders) get a mild reward.
    let class = post_residual % 10;
    score += match class {
        0 => -4.0,
        1 | 9 => 3.0,
        2 | 8 => 1.5,
        3 | 7 => 0.5,
        4 | 6 => 1.0,
        _ => 2.5,
    };

    // Integer-division threshold on post_residual: which next-item sizes
    // (harmonic classes of next_item_size) can still fit into this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin remains usable for the lookahead item: reward,
            // scaled by how "round" the leftover pairing is.
            let pair_class = (post_residual % next_item_size.max(1)) as f64;
            score -= 6.0 - pair_class * 0.2;
        } else {
            // Placement strands the bin for the next item: penalize,
            // more strongly if the miss is small (near-fit wasted).
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + miss * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it instead of opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: opening a fresh bin should only win when no open
    // bin gives a decent fit. Penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        // Less penalty late in the stream when many bins are open and
        // mean residual is high (fragmentation already present).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let penalty = 25.0 - 8.0 * progress - 10.0 * fragmentation;
        score += penalty.max(0.0);
    }

    // Mild bonus for using bins when many are open (consolidation pressure).
    score -= (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: penalize using open bins when many are open,
    // but only mildly; a new bin should win only when fit is poor
    score += (open_bins_count as f64) * 0.5;

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits, slight penalty for blocking it
    else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 5.0;
    }

    // New-bin candidate: keep it moderately attractive only when fit is bad
    if bin_residual == bin_capacity {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Progress-based tightening: later in stream, be stricter about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that become exactly full.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when the next item exactly matches the post residual.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff == 0.0 {
            score -= 400.0; // chain fit: this bin then perfectly holds next item
        } else if diff > 0.0 {
            // next item fits in the leftover; the smaller the leftover slack, the better
            score -= 200.0 / (1.0 + diff / 20.0);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += (-diff) * 0.8;
        }
    }

    // Compare post_residual against the mean residual across open bins.
    // Leaving a residual well below mean wastes capacity; being close to mean is neutral.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += mean_gap * 0.3;
    } else {
        score += mean_gap * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large unusable dead space (item nearly fills a new bin).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && post_residual as f64 <= next_item_size as f64 {
            score -= 150.0 * tightness; // new bin pairs well with next item
        }
        // Penalize opening a new bin when it is not a near-perfect fill
        score += (1.0 - tightness) * 60.0;
        // As the stream progresses, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Mild preference for filling larger-residual bins first (best-fit style),
    // scaled by how many bins are open (avoid fragmentation when many bins exist).
    score -= (bin_residual as f64 / bin_capacity as f64) * (5.0 + open_bins_count as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals (<10) — dead space
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if the next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // penalize leaving residual that wastes space for the next item
            let waste = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
            score += 0.03 * waste;
        }
    }

    // Time horizon: early in the stream, prefer keeping bins open/compact;
    // later, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * fit_ratio;

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when few fitting bins or poor fits
        let poor_fit = fit_ratio < 0.7;
        if fitting_bins_count == 0 {
            score -= 5.0; // no alternative
        } else if fitting_bins_count == 1 && poor_fit {
            score -= 2.0; // marginal: new bin slightly attractive
        } else {
            score += 10.0 + 0.5 * open_bins_count as f64; // keep using open bins
        }
    }

    // Mild preference for bins with residual close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    // Non-linear polynomial coupling: residual penalty grows superlinearly with progress
    let poly = norm_pr * norm_pr * (1.0 + progress * 2.0) * cap * 0.5;
    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = (1.0 - norm_pr) * (1.0 + progress) * 10.0;
    // Lookahead: bonus if next item fits exactly in post_residual
    let mut lookahead = 0.0;
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            lookahead = -8.0 * (1.0 - (pr - ns) / cap);
        } else {
            lookahead = 4.0 * (ns - pr) / cap;
        }
    }
    // Last-chance bin: strong reward to use it rather than open a new bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };
    // Penalize bins with residual far from mean (fragmentation control)
    let frag = ((pr - mean_residual) / cap).abs() * 3.0;
    // Mild penalty for opening new bins as stream progresses
    let new_bin_bias = if bin_residual == bin_capacity { 2.0 + 6.0 * (1.0 - progress) } else { 0.0 };

    let mut score = base + poly - tightness + lookahead + last_chance + frag + new_bin_bias;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: coarse buckets of 10 (dead-space classes)
    let post_class = post_residual / 10;
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward when next item fits into the post-residual class exactly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.5 * (post_class as f64);
        // Perfect modulo harmony: post_residual % next_item_size small
        let m = post_residual % next_item_size;
        score -= (10 - (m as f64).min(10.0)) * 0.6;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot fit here anyway; slight penalty
        score += 3.0;
    }

    // Penalize tiny unusable residuals (dead space) via harmonic threshold
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            penalty = 0.0; // must open a bin
        } else if post_residual < 30 {
            penalty -= 8.0; // great harmony in fresh bin for medium items
        }
        score += penalty;
    }

    // Prefer bins whose residual is close to item size (tight fit reward)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness * tightness;

    // Mean-residual coupling: prefer bins deviating from mean toward tightness
    score += 0.3 * (mean_residual - bin_residual as f64).abs() * 0.1;

    // Modulo-5 harmonic bonus on post_residual (multiples of 5 pair well)
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gap: mild penalty scaled by how little fits later.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // If the residual left can still fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.1;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: extra dead-space penalty.
        score += 5.0;
    }

    // Last chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open bins pressure: discourage spreading across many bins when
    // this placement creates a large dead remainder.
    if post_residual > 0 && post_residual < 10 {
        score += open_bins_count as f64 * 0.5;
    }

    // Slight preference for tighter bins overall (waste-averse).
    score += (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.05;

    // New-bin candidate: only attractive when this item would leave
    // a large useful residual or when all existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted if item is large
        // (likely to pair well with future items in fresh space).
        score += 25.0 - (item_size as f64) * 0.15;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but heavily reward exact/near-exact fills.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill_ratio = 1.0 - (post / cap);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Aggressive 2-step lookahead: reward bins where the next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let next_fit_tightness = 1.0 - (post - next_item_size as f64) / cap;
        score -= 25.0 * next_fit_tightness;
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize leaving residual that strands the lookahead
        let stranded = (next_item_size as f64 - post).min(cap);
        score += 0.15 * stranded;
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill now
    let dev = (bin_residual as f64 - mean_residual) / (cap.max(1.0));
    score += 8.0 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Avoid wasting near-empty bins on small items late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if fill_ratio < 0.3 {
        score += 10.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln().max(0.0) };
        score += 20.0 + 15.0 * desperation;
        // Opening a new bin is good if item is large and would leave a bad residual elsewhere
        if post < 20.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64) } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small to accept typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 6.0 * (1.0 - pr / 12.0);
    }

    // Lookahead (k=2): reward exact match for next item, penalize blocking it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() < 0.5 {
            score -= 14.0;
        } else if nx > pr {
            score += 2.5;
        } else {
            // next item fits but leaves another residual: mild preference for tight chains
            score += 0.03 * (pr - nx);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, unless it's the new-bin candidate.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly so it wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the fleet mean residual (consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // With many open bins, reward filling bins deeply to close them out.
    score -= 0.02 * open_bins_count as f64 * (bin_capacity as f64 - pr) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual
    score += 12.0 * pr_norm * pr_norm * cap;

    // Tight-fit reward: strongly favor small post-residual via inverse coupling
    if pr > 0.0 {
        score -= 30.0 / (1.0 + pr_norm * 8.0);
    } else {
        score -= 40.0; // perfect fill
    }

    // Smooth progress coupling: as stream advances, prefer tighter packing
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= progress_coupling * (cap - pr) * 0.05;

    // Lookahead: reward post-residual that can host next item (smooth kernel)
    if nx > 0.0 && pr > 0.0 {
        let gap = (pr - nx).abs();
        let kernel = (-gap * gap / (2.0 * 15.0 * 15.0)).exp();
        score -= 25.0 * kernel;
    }

    // Last-chance bin: penalize opening new bins when only one fits
    if fitting_bins_count == 1 && br >= it {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (compact bins)
    let dev = (br - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // Many open bins: slight penalty to opening yet another
    let open_frac = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 5.0 * open_frac * (pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (divisible by common item strides) are favored.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -10.0
    } else if pr % 2 == 0 {
        -4.0
    } else {
        6.0 // odd leftovers are hardest to fill
    };
    score += harmonic_bonus;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // If lookahead fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.35;
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // Harmonic coupling: next item aligns with residue class of post_residual
        if pr > 0 && pr % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    }

    // Tight fit reward relative to capacity fractions.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= fill * 20.0;

    // Last-chance bin: avoid forcing a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would create bad dead space (post_residual small but nonzero).
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // fresh bin residual baseline
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // new bin can host the lookahead too
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure against bin proliferation.
    score += open_bins_count as f64 * 0.05;

    // Prefer bins whose residual deviates favorably from the mean.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (>= 10, or >= next_item_size)
    // could ever use it.
    let min_item = 1u32.min(bin_capacity).max(1);
    let gap = post_residual as f64;
    if gap > 0.0 {
        if post_residual < min_item {
            score += 1000.0; // completely unusable sliver
        } else if post_residual < 20 {
            score += 60.0 * (1.0 - gap / 20.0); // hard-to-fill tiny gap
        } else {
            // Usable gap: reward proportionally (best-fit flavor)
            score -= 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Perfect fit bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 20.0;
        } else {
            // next item cannot use the gap -> penalize dead space more
            score += 25.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly awful.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones (penalize new-bin candidate implicitly via residual math,
    // but add slight extra reward for using existing bins when crowded).
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it
    // only wins when all existing fits are poor.
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.1;
    }

    // Progress: late in the stream, slightly prefer tighter fits to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else if post_residual >= next_item_size {
            // Next item fits too; reward proportionally to how snugly.
            score -= 150.0 * (next_item_size as f64 / post_residual as f64);
            // Bonus if next item then leaves near-zero residual (chain fill).
            let second_residual = post_residual - next_item_size;
            if second_residual == 0 {
                score -= 400.0;
            } else if second_residual <= 5 {
                score -= 100.0;
            }
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful (dead space for the next item).
            score += 60.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Penalize residuals far below mean residual (fragmentation) but reward
    // using bins with large residuals (tighten the loosest bins first).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless no reasonable fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for opening a new bin; grows with more open bins.
        score += 200.0 + 10.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is even worse (leftover waste).
        score += 100.0 * progress;
        // If item is large relative to capacity, a fresh bin is more acceptable.
        score -= 1.2 * item_size as f64;
        // If the next item is huge, a fresh bin may serve both better.
        if next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 50.0;
        }
    }

    // Mild penalty for leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic penalty for large post-residual (dead space).
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 6.0 * tightness * tightness * (bin_capacity as f64);

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead coupling: favor bins whose leftover could host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Leftover too small for next item: mild penalty proportional to waste.
            score += 0.05 * post_residual as f64;
        }
        // Chain fit: item + next item exactly fills bin -> excellent.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: minimize leftover strictly.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global state: penalize spreading when many bins already open (fragmentation control).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Prefer bins with below-average residual (consolidate emptier bins less; fill fuller bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate logic: empty bin gets a mild handicap so we reuse existing bins
    // unless the fit in open bins is poor (post_residual large relative to capacity).
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Handicap proportional to how bad the average open-bin fit would be.
        score += 10.0 + 0.2 * mean_residual;
        // Early in the stream, opening fresh bins is cheaper; late, discourage strongly.
        score += 20.0 * (1.0 - progress);
    }

    // Small deterministic tie-breaker based on residual parity structure.
    score += ((post_residual % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post_residual, scaled by non-linear progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Penalize large post_residual more as stream progresses (waste matters later)
    score += 0.5 * pr_norm * pr * progress;

    // Reward tight fits: subtract when post_residual small relative to item
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 4.0 * tightness * tightness;

    // Last chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: reward if next item can fit in post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            // penalize dead space that next item cannot use
            score += 0.3 * pr_norm * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins near mean (balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 1.5 * dev * dev;

    // Slight penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes on capacity.
    // Residuals that are "harmonious" with typical small items (multiples of 10)
    // are more reusable; odd/dead classes get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // perfectly harmonious residual
    } else if class <= 2 || class >= 8 {
        score += 4.0; // near-dead sliver, hard to fill
    }

    // Integer-division thresholds: residual that can host next item is valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Fraction of next item's demand covered by this residual
            let cover = next_item_size as f64 / (next_item_size as f64 + pr);
            score -= 10.0 * cover;
            // Harmonic pairing: post_residual % next_item_size small => near-perfect chain
            let chain = post_residual % next_item_size;
            score -= 5.0 * (1.0 - chain as f64 / next_item_size as f64);
        } else {
            score += 3.0; // next item cannot follow here
        }
    }

    // Tight fit reward (best-fit core with sharpening)
    let tight = 1.0 - pr / cap;
    score -= 8.0 * tight * tight;

    // Penalize creating unusable dead space: post_residual below smallest plausible item
    if post_residual < 1 {
        score -= 12.0; // perfect closure
    } else if post_residual < 10 {
        score -= 4.0; // small dead space, acceptable
    } else if post_residual < 20 && next_item_size > post_residual {
        score += 5.0; // medium dead space nothing can use
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive if current item is large (leaves harmonious residual)
    // or no real alternative exists.
    if bin_residual == bin_capacity {
        let new_post = cap - item_size as f64;
        let new_class = (bin_capacity - item_size) % 10;
        let mut new_score = new_post + 10.0; // intrinsic cost of opening a bin
        if new_class == 0 { new_score -= 6.0; }
        if next_item_size > 0 && new_post >= next_item_size as f64 { new_score -= 6.0; }
        if fitting_bins_count == 0 { new_score -= 25.0; } // forced open
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 10.0 * progress;
        if open_bins_count == 0 { new_score -= 20.0; }
        score = score.min(new_score);
        // If a real bin fits well, discourage new bin
        if fitting_bins_count > 1 {
            score += 8.0;
        }
    }

    // Mild preference to spread across bins when many open with high mean residual
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 2.0; // prefer fuller-than-average bins
        } else {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual gaps (<= 10) are nearly unusable
    // for future items (sizes >= 1 but typically >= 10), so penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward placements that leave a gap exactly matching the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when this bin is the last fitting option (avoid fragmentation).
    if bin_residual == bin_capacity {
        // New-bin candidate: mild base cost so good fits into open bins win.
        score += 25.0;
        score += 2.0 * open_bins_count as f64;
        // If few bins can fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 20.0;
    }

    // Coupling with mean residual: prefer bins whose residual is far below
    // the mean (they are the tightest fits), penalize near-mean residuals.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild reward for filling bins more completely as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (item_size as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) with a superlinear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        score -= 20.0 / (post_residual as f64).sqrt();
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0; // exact 2-chain
        } else if post_residual >= next_item_size {
            // slack proportional to how well next item fits afterward
            let after_next = post_residual as f64 - nxt;
            score -= 15.0 / (1.0 + after_next);
        } else {
            // next item cannot follow: penalize proportionally to wasted lookahead
            score += (nxt - post_residual as f64) * 0.15;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    score += 0.10 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        score -= 8.0;
        // penalize opening new bins more as stream progresses / many bins open
        score += 12.0 * (step_index as f64 / total_items.max(1) as f64);
        score += 0.5 * open_bins_count as f64;
    }

    // Mild penalty for leaving awkward medium dead space (hard to fill later).
    if post_residual >= 20 && post_residual <= 45 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit).
    let mut score = post;

    // Strongly penalize large unusable dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fit
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 8.0;
    }

    // Waste fraction coupling: penalize proportionally to wasted capacity.
    score += 3.0 * (post / cap) * (post / cap) * cap * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild preference for bins with less residual among many candidates.
        score += 0.15 * (res - mean_residual);
    }

    // Lookahead: reward if next item fits exactly in post residual (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving medium gaps.
            score += 0.05 * nxt;
        }
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage unless
    // current fit is bad or no good alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let baseline_penalty = 60.0
            - 20.0 * progress              // later in stream: waste matters less, keep bins tidy
            + 2.0 * open_bins_count as f64; // many open bins: avoid adding more
        score += baseline_penalty;
        // If the item would leave a large gap in existing bins, new bin looks better.
        if post_residual <= 5 {
            score -= 15.0;
        }
    } else {
        // Favor using existing bins more when few bins are open.
        score -= 2.0 / (1.0 + open_bins_count as f64);
    }

    // Global residual pressure: if mean residual is high, prefer consolidating into
    // bins with below-average residual (reduce fragmentation).
    if mean_residual > 0.0 {
        score += 0.1 * (mean_residual - post).abs().signum() * (mean_residual - post);
    }

    // Time horizon: early items — keep flexibility (avoid ultra-tight fits that
    // strand future items); late items — greediness is fine.
    score += 10.0 * (1.0 - progress) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress)
        - 22.0 * fill * fill * (1.0 + 0.5 * progress);

    // Reward tight fits more strongly later in the stream (cubic coupling)
    score -= 30.0 * fill * fill * fill * (0.5 + progress);

    // Penalize near-zero post residual that wastes space when mean residual is large
    let dead = (pr / cap).powi(2);
    score += 15.0 * dead * (1.0 - progress);

    // Lookahead: reward leaving room for the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).powi(2));
        } else {
            score += 6.0 * ((-gap) / cap);
        }
    }

    // Last-chance bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins as stream progresses
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize relative to its residual so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: small residuals are "dead" space.
    let pr = post_residual as u32;
    // Integer-division thresholds: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Reward tight fits via step-function bonuses on harmonic classes.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= sixteenth {
        score -= 35.0;
    } else if pr <= eighth {
        score -= 18.0;
    } else if pr <= quarter {
        score -= 6.0;
    } else if pr <= 2 * quarter {
        score += 8.0;
    } else {
        score += 20.0; // large dead space
    }

    // Modulo arithmetic: residuals that pair well with common item sizes.
    // If next item could exactly fill the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if pr >= next_item_size && (pr % next_item_size) <= sixteenth {
            score -= 12.0; // next item leaves a near-harmonic remainder
        } else if pr < next_item_size {
            score += 10.0; // residual unusable by next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer only when it beats poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; tight fits elsewhere still win.
        score += 30.0;
        // If nothing else fits, this call is effectively the only option;
        // fitting_bins_count == 1 flags that.
        if fitting_bins_count == 1 {
            score -= 55.0;
        }
    }

    // Fractional coupling: penalize when post_residual is far from mean residual
    // (fragmenting the bin population's residual distribution).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference to fill older bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap below 10 (min plausible item size) is pure waste; gaps in [10, 30)
    // are risky since few items fit them.
    if post_residual < 10 {
        score -= 60.0; // perfect fill: reward strongly
    } else if post_residual < 30 {
        score += 25.0 + (30.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits relative to item size (low waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64).max(1.0);
    score += waste_ratio * 20.0;

    // Open-bins pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize so we only open a new bin when no decent fit exists.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 1.0;
        // But if this item would leave a tight fit elsewhere unusable, allow new bin:
        // if all fitting bins would end with risky gaps, soften the penalty.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0; // chains a near-perfect follow-up placement
        } else {
            score -= 10.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // balances the pool of open bins.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in the stream, be more conservative about waste (fewer chances to recover).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact matches between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.35;                     // prefer post_residual close to next_item_size
        if post_residual == next_item_size {
            score -= 25.0;                       // perfect 2-step fit
        } else if post_residual > next_item_size {
            score -= 8.0;                        // next item still fits afterwards
        } else {
            score += 6.0;                        // next item won't fit; dead space risk
        }
    }

    // Tight packing reward: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize residuals far below mean (fragmented bin) and reward above-mean use.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        let late = (step_index as f64 / total_items.max(1) as f64) * 5.0;
        score += base_penalty + scarcity + late;
        // Opening a new bin is attractive if it would fit both current and next item snugly.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            if leftover <= 10 {
                score -= 22.0;
            }
        }
    }

    // Mild penalty for many open bins to discourage sprawl.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, allow loose packing; later, punish waste harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = 0.5 + progress; // 0.5..1.5 multiplier over time

    // Reward tight fits: scale wasted space by urgency.
    score *= urgency;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..100; residual below ~10 is nearly unusable.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward residuals that match the lookahead item (pairing).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size > 0 && post_residual > next_item_size {
            // Residual big enough for next item: mild reward.
            score -= 5.0;
        } else if next_item_size > 0 {
            // Residual too small for the lookahead: penalty proportional to gap.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones
    // rather than spreading; penalize lightly when open_bins_count is large.
    let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.1);
    score += crowding.min(20.0) * 0.3;

    // New-bin candidate handling: empty bin gets a base cost that grows over time,
    // so opening new bins is discouraged unless existing fits are really bad.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        score += 15.0 + 10.0 * progress;
        // But if no open bin fits well (large item, few fitting bins), allow new bin.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Nonlinear coupling: favor bins whose residual is close to item_size (snug fit)
    let snug = (bin_residual - item_size) as f64;
    score += (snug * snug) / (bin_capacity as f64 * bin_capacity as f64) * 10.0;

    // Small global-state term: when mean residual is low, packing is tight everywhere;
    // reward using bins that keep the mean low.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: residual cost grows super-linearly with stream progress
    let progress_coupling = 1.0 + 0.9 * t * t + 0.6 * t * norm_pr;
    score *= progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight_fit = (1.0 - norm_pr).powi(2);
    score -= 18.0 * tight_fit * (0.5 + t);

    // Penalize dead space near half-capacity (least usable residual)
    let half_waste = norm_pr * (1.0 - norm_pr);
    score += 14.0 * half_waste * (0.4 + 0.6 * t);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            score -= 12.0 * (1.0 - (next / pr).powi(2)) * (0.6 + 0.4 * t);
        } else {
            score += 6.0 * (next - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 + t);
    }

    // Many open bins: encourage filling existing ones over opening new
    score += 0.8 * (open_bins_count as f64).ln() * (0.5 + t);

    // Mean residual alignment: prefer bins whose residual is near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize slightly unless residual is very small
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * t;
        if item_size > 60 {
            score -= 15.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small" residue classes (dead space) are penalized.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Classify post_residual by integer division into harmonic buckets of 10.
    let bucket = pr / 10;
    match bucket {
        0 => score -= 12.0,                       // near-perfect fit, excellent
        1 => score -= 6.0,                        // good fit
        2 => score -= 2.0,                        // acceptable
        3 => {}                                   // neutral
        4 => score += 4.0,                        // wasteful
        _ => score += 8.0,                        // mostly-empty bin used poorly
    }

    // Modulo-arithmetic coupling: residual that is congruent to common
    // small item sizes (mod 10) is more likely reusable.
    let mod10 = pr % 10;
    if mod10 == 0 {
        score -= 3.0; // exact multiple of 10: highly reusable
    } else if mod10 >= 7 {
        score += 2.5; // awkward remainder, dead space risk
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot use this residual: penalize leftover sizes
            // that are "just above" typical item sizes.
            let gap = next_item_size - pr;
            if gap <= 10 {
                score += gap as f64 * 0.4;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate: prefer keeping items in existing bins when the
    // fit is decent; opening new bins should only win for terrible fits.
    if bin_residual == bin_capacity {
        score += 18.0 - (mean_residual / cap) * 6.0;
        // late in the stream, opening fresh bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 4.0;
    }

    // Mild load-balancing: prefer bins whose residual is below the mean
    // (fill fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    // Early stream: consolidate aggressively to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are "dead". Penalize sharply
    // when post_residual lands in the dead zone (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect closure is the best outcome: strong reward.
        score -= 40.0;
    } else {
        // Usable gap: mild preference for smaller gaps (tight fit).
        score += 0.15 * (post_residual as f64);
    }

    // Reward if the next item fits exactly into the post residual (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward for exact chaining (next item closes the bin).
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize if next item just barely misses the post residual (dead gap risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 20.0;
    }

    // Open-bins pressure: discourage scattering across many open bins
    // when this bin's fit is mediocre; encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    let fit_quality = (bin_residual as f64 - item_size as f64).max(0.0);
    score += pressure * (fit_quality / bin_capacity as f64) * 8.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when no open bin offers a good fit. Base cost of opening a new bin
    // grows with the number of already open bins.
    if bin_residual == bin_capacity {
        score = 100.0 + 2.0 * (open_bins_count as f64) + 0.5 * mean_residual;
        // If the item would leave a nice usable residual in a fresh bin,
        // slightly soften the opening cost.
        if post_residual >= 10 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Mean residual coupling: if this bin is far below average residual,
    // it is "wasted capacity" being drained — mild penalty to prefer
    // filling bins with larger residuals first? No: filling low-residual
    // bins first keeps large residuals for large future items, so reward
    // choosing the bin with the smallest residual that still fits.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: next item fills this bin perfectly
        if post_residual == next_item_size {
            score -= 1000.0 + 200.0 * (1.0 - t);
        } else if next_item_size <= post_residual {
            // Next item still fits here: reward proportionally to how close
            score -= 80.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize by the gap size
            score += 0.6 * diff as f64;
        }
    }

    // Prefer bins whose residual is already below mean (well-packed, avoid waste)
    if (post_residual as f64) < mean_residual {
        score -= 25.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Penalize unusable dead space relative to capacity
    if post_residual < 10 {
        score -= 50.0; // near-perfect fill
    } else {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Discourage opening new bins when many bins are open and item fits
    if bin_residual == bin_capacity {
        score += 120.0 + 60.0 * open_bins_count as f64 * (0.5 + t);
    } else {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Primary fit term: reward tight packing quadratically ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // ---- Dead-space penalty: residuals too small to ever be useful ----
    if post_residual < 10 {
        score += 12.0; // nearly perfect fit, great
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        // residual can't host the next item: mild dead-space penalty
        score += 4.0 + 0.05 * post_residual as f64;
    }

    // ---- Lookahead: reward bins whose leftover can host the next item ----
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // Perfect two-item pairing bonus
        score -= 10.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        if slack_after_next == 0 {
            score -= 8.0; // exact pair fill
        }
    } else if next_item_size > 0 {
        // next item won't fit here after placement: slight penalty
        score += 3.0;
    }

    // ---- Last-chance logic: if this is the only fitting bin, avoid forcing a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress; // stronger late in the stream
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high early, cheaper if many items remain
        let mut new_bin_cost = 25.0 + 20.0 * (1.0 - progress);
        // If existing bins are fragmented (high mean residual), opening fresh is more attractive
        new_bin_cost -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // If few bins fit the item, a new bin gives flexibility
        if fitting_bins_count <= 1 {
            new_bin_cost -= 8.0;
        }
        // Lookahead: an empty bin can always host the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_cost -= 5.0;
        }
        score += new_bin_cost;
    }

    // ---- Global state coupling ----
    // Prefer filling already-open bins when many are open (avoid bin proliferation)
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (more packed than average)
    score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Small late-stream consolidation pressure: minimize residual spread late
    if progress > 0.7 {
        score += 0.03 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly damped by progress
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of post-residual with stream progress
    let t = progress;
    let poly = t * t - 2.0 * t + 1.0; // (1-t)^2
    score -= 8.0 * poly * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * t;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 4.0 * (nx - pr) * (1.0 + t);
        } else {
            score -= 2.0 * (1.0 - nx / cap) * t;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Penalize spreading across many open bins when residuals are fragmented
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2);

    // New-bin candidate: keep it slightly unattractive unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward (strong).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10
    // are "reusable" classes for typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Dead-space penalty: small unusable residual (below min plausible item).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 12 {
        score += 6.0;
    }

    // Integer-division thresholds on post_residual relative to capacity fractions.
    let q = post_residual / (bin_capacity / 4); // quarters
    score += q as f64 * 3.0;

    // Lookahead coupling: reward residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits here: mild reward, scaled by how much slack remains
            let slack = post_residual - next_item_size;
            score -= 12.0 + (slack as f64).ln().max(0.0) * 4.0;
            // harmonic bonus if leftover after next item is a clean class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize small residuals more
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin logic: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or open-bin population is tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual > 0 && post_residual < 20;
        if !poor_fit || open_bins_count == 0 {
            score += 30.0 + 20.0 * (1.0 - progress);
        } else {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post / cap) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 25.0;
    }
    // Mid-range gaps that only fit tiny items are also somewhat wasteful.
    if post_residual >= min_useful && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (post_residual near zero relative to bin).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, tolerate opening a new bin for poor fits.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the fit would leave
    // large dead space or when existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        score = 55.0 + pressure;
        if post_residual == bin_capacity {
            // Fresh bin for the item: good if item is large, bad if small.
            score -= item_size as f64 * 0.6;
        }
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if next item cannot use the post residual gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < min_useful {
        score += 10.0;
    }

    // Slight stream-progression nudge toward consolidation late in the stream.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero waste is ideal
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins where the next item fits the new residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra reward for near-exact 2-step chain
        let chain_waste = post_residual - next_item_size;
        score -= (20.0 - (chain_waste as f64 * 0.4).min(20.0));
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item
        score += 25.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter packing)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && item_size <= bin_residual {
            score += 30.0;
        }
        // Opening new bin is fine early in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Small penalty for large dead space that can't fit typical items (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual > 60 {
        score += 10.0; // wasteful placement
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 5.0; // next item won't fit here; slightly deprioritize
        }
    }

    // Global state: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins with reasonable fits win.
        score += 55.0;
        // But if item is large relative to capacity and mean residual is low, opening is fine.
        score -= 40.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - mean_residual / bin_capacity as f64);
        // Late in the stream, avoid spawning bins unnecessarily.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post residual (dead space)
    let mut score = pr * pr / cap;

    // Smooth coupling: post residual weighted by stream progress —
    // late in stream, tight fits matter more; early, residual flexibility is fine
    score += pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth saturating term
    score -= cap * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.8 + 0.6 * progress);

    // Lookahead: penalize post residuals that cannot fit the next item,
    // reward those that can, with smooth interaction
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (norm_next - norm_pr).abs();
        score += gap * cap * 0.7;
        score -= fits_next * cap * (0.5 + 0.5 * progress);
        // prefer bins whose post residual matches next item size smoothly
        score += (norm_pr - norm_next) * (norm_pr - norm_next) * cap * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 1.5;
    } else {
        // mild penalty spread across many fitting bins to prefer concentrated fills
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean residual coupling: prefer bins near the mean residual (keep balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * cap * 0.4;

    // Open bins count: mildly discourage scattering when many bins are open
    score += (open_bins_count as f64) * 0.3 * (1.0 - norm_item);

    // New-bin candidate: penalize opening a new bin unless item is large
    // relative to capacity or stream is early (smooth in progress)
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.8 * progress) * (1.0 - norm_item * norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (common item sizes 1..100) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // reward post-residuals that are multiples of small common sizes
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
        // penalize awkward leftover classes (prime-ish / odd small leftovers)
        if pr % 10 != 0 && pr < 15 { score += 8.0; }
        // integer division thresholds: leftover that can host a mid-size item
        let q = pr / 25; // 0..4 quartile class
        score -= (q as f64) * 3.5;
    } else {
        // perfect fit is ideal
        score -= 25.0;
    }

    // Coupling with lookahead item: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // leftover is reusable by next item -> strong reward, scaled by snugness
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack.min(30.0) * 0.15;
            if pr == next_item_size { score -= 10.0; }
        } else {
            // leftover too small for next item: dead space penalty
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tightest fit (post_residual term dominates)
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bins when decent fits exist
        score += 30.0 + open_bins_count as f64 * 2.0;
        // but if mean residual is tiny (all bins nearly full), opening is fine
        score -= (cap - mean_residual).max(0.0) * 0.25;
        if fitting_bins_count == 0 { score -= 60.0; }
    }

    // Stream progression: early on, be conservative (keep bins open for future);
    // late in stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Tie-break toward bins already below mean residual (consolidate emptiness)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item + (post_residual % 3) {
            score += 60.0; // dead space: residual too small to be useful
        }
        if post_residual < 10 {
            score += 45.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual > 50 {
            score -= 10.0; // large residual still reusable
        }
    }

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open bin pressure: penalize opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    // Stream progression: later in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Isolated-bin urgency: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 2-step lookahead: exact match of post_residual with next item is perfect.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect two-item fill bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Small dead space unusable by next item is penalized extra.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize leaving very small unusable fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large post_residual for empty bin would otherwise lose to any fit).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if many bins are open and mean residual is large, discourage opening more.
        score += 0.2 * mean_residual;
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is huge, an empty bin is valuable.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: penalize placing item if next item would fit better in this residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item could still use this bin — mild bonus for chain packing
            score -= 6.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // this bin is the only place the next (larger) item fits; waste residual elsewhere
            score += 10.0;
        }
        // reward residual that pairs with next item exactly
        if post_residual > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap; // prefer bins with below-average residual (tighter)

    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Penalize opening a new bin, more strongly early when consolidation matters
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but allow new bin if item is large and no open bin is tight
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Discard tiny unusable dead space asymmetrically
    if post_residual > 0 && post_residual < 5 {
        score += 8.0; // fragmenting residual into unusable slivers is bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty (dead space grows super-linearly in badness)
    let mut score = norm_pr * norm_pr * cap + 0.35 * pr;

    // Smooth cubic coupling with stream progress: late in the stream,
    // residual space becomes more valuable (harder to fill later).
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * norm_pr * cap * 0.9;

    // Reward bins whose residual is below the mean (tight bins get priority),
    // smoothly via sigmoid-like tanh coupling.
    let tightness = ((mean_residual - pr) / cap).tanh();
    score -= tightness * 2.5;

    // Lookahead synergy: reward if next item fits the post residual,
    // scaled smoothly by how well it fills (fraction of post residual used).
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= (fill * (1.0 - fill) * 4.0 + 0.5) * 3.0;
    } else if next_item_size > 0 {
        // next item can't use the leftover: mild smooth penalty proportional to leftover
        score += norm_pr * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 6.0 * late;
    }

    // Penalize opening a new bin when many bins already fit the item
    // (smoothly, not piecewise): pressure grows with fitting_bins_count.
    let fb = fitting_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin, discounted when
        // no good fit exists (few fitting bins) or item is large.
        let size_frac = item_size as f64 / cap;
        score = cap * 0.6 - 8.0 * (1.0 - (fb / (fb + 2.0))) - 6.0 * size_frac - 4.0 * late;
    } else {
        // slight crowding penalty so we don't pile everything into one bin
        score += (open_bins_count as f64).ln().max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands (integer division thresholds).
    let post_class = (post_residual * 4) / bin_capacity; // 0..=3 quartile class
    match post_class {
        0 => score -= 30.0,                 // near-perfect fill
        1 => score += 5.0,                  // small dead space
        2 => score += 12.0,                 // half-ish leftover
        _ => score += 20.0,                 // large leftover
    }

    // Exact-fill reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo arithmetic on post_residual: leftover that is a clean divisor
    // of common item-size classes is more reusable.
    let pr = post_residual as u64;
    let mut reuse = 0.0;
    if pr % 10 == 0 { reuse += 6.0; }
    if pr % 20 == 0 { reuse += 4.0; }
    if pr % 25 == 0 { reuse += 3.0; }
    if pr % 50 == 0 { reuse += 3.0; }
    score -= reuse;

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt = next_item_size as f64;
        let fit_frac = nxt / (post_residual as f64);
        if fit_frac > 0.9 {
            score -= 25.0;  // next item nearly seals this bin
        } else if fit_frac > 0.5 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
        // Harmonic pair: item + next exactly divides capacity
        if (item_size + next_item_size) % bin_capacity == 0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64) / cap_f;
    score -= fill_frac * 15.0 * ((open_bins_count as f64).ln() + 1.0);

    // Mean-residual coupling: penalize bins far above mean residual
    // (they hoard space) unless the fit is tight.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Progress-based mild pressure: later in the stream, prefer tight fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.05 * progress;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = 60.0 - 20.0 * desperation - 5.0 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward tight fits (post_residual near zero is excellent).
    if post_residual == 0 {
        score -= 40.0;
    }

    // If a future item could exactly fill the leftover gap, reward it.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() <= 2.0 {
            score -= 18.0;
        } else if nxt > gap {
            // leftover gap cannot fit next item: mild penalty scaled by gap smallness
            score += (10.0 - gap).max(0.0) * 0.8;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Neutral base; penalize when many bins are open and fit exists elsewhere.
        if fitting_bins_count > 0 {
            score += 35.0;
        }
        // Late in stream, opening fresh bins is more acceptable.
        score -= 10.0 * progress;
    }

    // Slight preference for bins tighter than average (better packed).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // prefer leaving small usable slack, penalize large leftover
            score -= 20.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next < 10 {
                score -= 8.0; // near-perfect chaining
            }
        } else {
            // next item cannot use this bin's leftover: dead space risk
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: minimize leftover as much as possible
        score += 5.0;
    }

    // Tight fit reward relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Compare post_residual against mean residual across open bins:
    // favor bins that end below the mean (consolidating space)
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist, especially late in stream
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 10.0;
        }
    }

    // Mild pressure to reduce number of open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual dominates).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if next item can fit into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
        } else {
            // Penalize leaving a gap just smaller than the next item (dead space trap).
            let gap = (next_item_size as i64 - post_residual as i64).max(0) as f64;
            score += 0.6 * gap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Crowding: many open bins -> consolidate; few open bins -> opening new is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * crowd * fit_ratio * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is near/atypical
    // (keeps diversity of gap sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev * (1.0 - fit_ratio);

    // Penalize wasting large residuals on small items.
    if item_size < bin_residual / 2 {
        score += 0.8 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: opening a fresh bin should be mid-competitive —
    // attractive only when current fit is poor or few bins fit the item.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big upcoming item: fresh bin is valuable
        }
    }

    // Late stream: slight bias toward closing bins tightly.
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer minimal post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with
    // normalized post residual, amplified by stream progress (late items should
    // pack tighter since less future remains to fill gaps).
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-full placements with a smooth saturating term.
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * tightness;

    // Next-item lookahead: penalize residuals that are almost-but-not-quite
    // enough for the next item (smooth kernel around the gap size).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let kernel = (-gap * gap / 40.0).exp();
        score -= 6.0 * kernel * (pr / cap);
        // Reward residuals that comfortably fit the next item too.
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 4.0 * fits_next * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty proportional to competition, smoothed.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: score relative to the average open-bin slack; opening
    // a bin is penalized more when many bins are already open and progress is late.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + 4.0 * open_pressure * (0.4 + 0.6 * progress) + 12.0 * (it / cap);
        // But allow opening when the new bin would be very tight later (large item).
        score -= 20.0 * (it / cap) * (1.0 - progress) * (1.0 - progress);
    }

    // Mean-residual coupling: if this bin's residual deviates from the mean,
    // prefer consolidating slack (smooth quadratic term).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions.
    // Residuals divisible by 10 are "harmonic" with the item-size lattice
    // (sizes 1..100), so they are more reusable -> reward them.
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 6.0;

    // Fine-grained harmonic classes: quarter-capacity alignment (25/50/75).
    if post_residual % 25 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        // Non-harmonic dead space penalty, stronger for small unusable slivers.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= tightness * 3.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling (k=2): if next item fits exactly in post_residual,
    // strongly favor this bin; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer consolidating into many-bin states; penalize spreading when few
    // bins are open (encourages packing density early).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if open_bins_count > 0 {
        score -= (open_bins_count as f64).ln() * (1.0 - progress) * 0.5;
    }

    // Coupling with mean residual: bins far below mean residual are "emptier"
    // than average; placing there keeps well-filled bins for tight future fits.
    score += (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive
    // unless the fit into existing bins would be terrible. post_residual here
    // equals capacity - item_size, which is large, so base score already
    // discourages it; add a mild extra tax modulated by stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or < next item size)
    // are heavily penalized since nothing may ever fill them.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0; // tiny unusable sliver
        } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 25.0; // gap too small for the lookahead item
        } else {
            // mild decay: bigger leftover is better, but with diminishing returns
            score -= 0.3 * gap.sqrt();
        }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits: item occupying most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // but allow it when few bins are open (better future packing flexibility).
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above a good fit.
        score = bin_capacity as f64 * 0.75;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // early in the stream, new bins are cheap; later, avoid fragmentation
        score += 15.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // if an existing bin fits almost perfectly, never open a new one
        if fitting_bins_count >= 1 && item_size as f64 / mean_residual.max(1.0) > 0.85 {
            score += 100.0;
        }
    } else {
        // mild pressure to consolidate into fewer bins
        score += 0.5 * open_bins_count as f64;
        // prefer bins below mean residual (tighter bins first)
        score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space at all)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain completion: two items perfectly fill the bin
        } else if next_item_size < post_residual {
            // Next item fits; reward proportionally to how well it uses remaining space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
            // Extra reward for near-perfect chains
            let leftover = post_residual - next_item_size;
            if leftover <= 5 {
                score -= 100.0;
            }
        } else {
            // Next item cannot fit here: penalize dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize tiny unusable residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win
        score += 250.0;
        // But if item is large relative to capacity and few bins fit it, opening is cheaper
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item {
            score -= 200.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // Many open bins with high mean residual: opening new bin is fine
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 120.0;
        }
    }

    // Mild preference for bins with residuals below mean (tighter bins fill first)
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Reward using bins that are already fairly full
    let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 30.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Exact fit jackpot.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize small awkward leftovers that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Dead space relative to lookahead item.
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
        // Bonus: post-residual leaves a residual the next item fits snugly.
        let nxt_post = post_residual as i64 - next_item_size as i64;
        if nxt_post >= 0 && nxt_post < 10 {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover as much as possible.
        score += 0.5 * post_residual as f64;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    let pressure = mean_residual / bin_capacity as f64;
    if pressure > 0.5 && bin_residual < bin_capacity {
        score -= 20.0 * (pressure - 0.5);
    }

    // Time horizon: early in stream, be more open to new bins; late, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost plus dynamic penalty.
        let mut new_bin = 95.0;
        new_bin += 40.0 * progress;              // late stream: opening bins is costly
        new_bin += 3.0 * open_bins_count as f64; // many open bins: discourage more
        if next_item_size > 0 && bin_capacity as i64 - item_size as i64 >= next_item_size as i64 {
            new_bin -= 20.0; // fresh bin accommodates next item too
        }
        if fitting_bins_count == 0 {
            new_bin -= 120.0; // no alternative
        }
        score = new_bin;
    } else {
        // Existing bin: slight penalty growth with open bin count for spreading.
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin's residual deviates far above mean,
    // using it reduces fragmentation asymmetry.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: penalize residual more strongly as stream advances
    score += pr * (progress * progress) * 0.8;

    // Last-chance bonus: strongly reward the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 + 6.0 * (nxt / cap);
        } else {
            // dead space relative to next item: non-linear penalty
            let gap = (nxt - pr) / cap;
            score += 15.0 * gap * gap * cap * 0.1;
        }
    }

    // Prefer tight bins vs mean residual (smooth coupling)
    score += (mean_residual - pr) * 0.3;

    // Mild penalty for spreading across many bins early
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Perfect fit reward (smooth, no piecewise constant)
    score -= 10.0 * (1.0 - norm_pr).max(0.0) * (1.0 - norm_pr).max(0.0) * (1.0 - norm_pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover space is.
    // Residuals divisible by small harmonics (2,4,5,10) tend to fit future items
    // drawn from coarse-grained distributions better than odd/prime leftovers.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit — best possible outcome
    } else {
        let mut hb = 0.0;
        if pr % 10 == 0 { hb += 18.0; }
        else if pr % 5 == 0 { hb += 10.0; }
        if pr % 4 == 0 { hb += 7.0; }
        if pr % 2 == 0 { hb += 4.0; }
        if pr % 3 == 0 { hb += 3.0; }
        hb
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals too small to hold the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 45.0;
    }

    // Integer-division threshold on post_residual: classify leftover into
    // coarse capacity fractions of the bin.
    let frac = (pr * 100) / bin_capacity; // 0..=100 integer
    score += match frac / 10 { // decile class
        0 => 12.0,          // 0-9% left: nearly dead
        1 => 6.0,           // 10-19%
        2 => 0.0,           // 20-29%
        3 => -3.0,          // 30-39%
        4 => -5.0,          // 40-49%
        5 => -6.0,          // 50-59%
        6 => -5.0,
        7 => -3.0,
        8 => 0.0,
        _ => 4.0,           // 90-100% (only new-bin candidate)
    };

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact harmonic match is ideal
            if pr % next_item_size.max(1) == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are fragmented (high mean residual spread / many bins)
    // and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        // base cost of a new bin, discounted if open bins are badly fragmented
        score = bin_capacity as f64 * 0.55
            - fragmentation * 40.0
            - pressure
            - item_size as f64 * 0.2
            - progress * 5.0;
        // if next item is huge, a fresh bin is more valuable
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item (or the lookahead item) are
    // "dead space". Penalize them strongly.
    let min_future = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_future {
        score += 250.0;
    }
    // Dead space relative to the lookahead item: if the next item cannot
    // use this residual, the leftover is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 60.0;
    }
    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }

    // Tight fits are good: reward small post_residual nonlinearly.
    score -= 180.0 * (-post_residual as f64 / 15.0).exp();

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): make it attractive only when it
    // genuinely beats squeezing into a poor fit. Base penalty keeps it
    // behind decent existing fits; discount when few bins fit the item
    // or when open bins are already nearly full.
    if bin_residual == bin_capacity {
        score += 220.0;
        let avg_fill = mean_residual.max(0.0);
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
        if avg_fill < 15.0 {
            score -= 40.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * progress;
    }

    // Mild pull toward bins whose residual is close to the mean residual
    // (prefer balanced usage across bins).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain: this bin will be exactly filled by next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // smaller slack after next item is better, but keep base ordering
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: dead space penalty grows with tightness
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 * (dead / bin_capacity as f64);
        }
    }

    // Penalize very small unusable post-residuals (dead space below min item size 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual: bins with below-average residual are
    // "darker" bins; filling them first consolidates space.
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Slight preference for tighter bins overall.
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64);

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or no good fits exist
        score -= 5.0 * item_size as f64 / bin_capacity as f64;
        score += 10.0 * progress; // later in stream, prefer reusing open bins
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // fresh bin guarantees room for the large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
