pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - progress) + x * (1.0 - x) * (1.0 - x) * progress;
    score += 8.0 * poly;

    // Reward tight fits more as stream progresses (subtract)
    score -= (1.0 - x) * (1.0 - x) * (2.0 + 6.0 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
        let waste = pr / (next_item_size as f64);
        score += 6.0 * waste * (1.0 - progress) * (1.0 - x);
    }

    // Reward using next item's space well (smooth lookahead coupling)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let match_term = 1.0 - ((pr - n).abs() / cap);
        score -= 5.0 * match_term.max(0.0) * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly favor filling a nearly-unique fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - x);
    }

    // Mild dispersion penalty: discourage diverging from mean residual
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    // Slight preference to keep bin count low early, spread later
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic-class decomposition of post_residual: classify the leftover space
    // into "usable bands" using integer division thresholds and modulo structure.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Base tightness reward: exact or near-exact fits are gold. ---
    if post_residual == 0 {
        score -= 500.0; // perfect fit, always take
    } else if post_residual <= 10 {
        score -= 120.0; // near-perfect: dead space below min item size
    }

    // --- Harmonic classes: how does post_residual decompose modulo the
    //     small-size quantum (10)? Residues that align with likely future
    //     item sizes are more valuable. ---
    let quantum = 10u32;
    let r = post_residual % quantum;
    let class = post_residual / quantum; // harmonic class index

    // Low harmonic classes (small leftovers) are risky dead space unless ~0;
    // mid classes (20..50) are prime real estate for medium items.
    match class {
        0 => score += 40.0,               // 1..9: almost dead
        1 => score += 10.0,               // 10..19: only tiny items fit
        2 => score -= 15.0,               // 20..29: decent
        3 => score -= 25.0,               // 30..39: sweet spot
        4 => score -= 20.0,               // 40..49: good
        _ => score += (class as f64 - 4.0) * 8.0, // larger leftovers: mild penalty
    }

    // Residue alignment: leftover whose remainder matches a "friendly" residue
    // (multiples of 5 / 10) pairs well with typical item granularities.
    if r == 0 {
        score -= 6.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    } else {
        score += r as f64 * 0.4; // ragged remainder slightly penalized
    }

    // --- Lookahead coupling: does the next item fit into the post-residual? ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item chains into this bin: strong reward, scaled by how snugly.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 30.0 + 25.0 * snug;
            // Extra bonus if next item exactly consumes the remainder.
            if next_item_size == post_residual {
                score -= 60.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportional to
            // how close-but-failed (frustrated fit) the leftover is.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 12.0 + gap * 0.8; // tantalizing but unusable dead space
            }
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, avoid forcing a
    //     bad placement unless the fit is genuinely good. ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        if post_residual <= 10 {
            score -= 80.0; // great last-chance fit: definitely use it
        } else {
            score += 15.0; // mediocre last-chance fit: mild pressure to open new bin
        }
    }

    // --- New-bin candidate handling: an empty bin has post == capacity.
    //     Prefer it only when the current fit is poor or stream is early. ---
    if bin_residual == bin_capacity {
        // Neutral baseline; progress term makes new bins less attractive later
        // unless other terms dominate (poor fits produce high scores).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 15.0 * progress;
    }

    // --- Congestion coupling: many open bins with high mean residual ->
    //     prefer consolidating into existing bins (penalize new space). ---
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        // Reward placing into a bin whose residual is below the mean (tighter bin).
        if (bin_residual as f64) < mean_r {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // When many bins are open, tighten selection pressure.
        score += (open_bins_count as f64).sqrt() * (post / cap) * 6.0;
    }

    // --- Item-size harmonic class: big items (>= 50) want deep bins; small
    //     items should not waste large-capacity bins. ---
    if item_size >= 50 && post_residual <= 20 {
        score -= 35.0; // big item snugly placed
    }
    if item_size <= 20 && post_residual >= 60 {
        score += 18.0; // tiny item dumped in a huge leftover: wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the known next item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward gaps that exactly or nearly fit the next item (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across too many bins unless the fit is good.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 8.0 * pressure;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Dead-space relative to mean residual: penalize leaving far more waste than average.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    // New-bin candidate handling: prefer reusing an existing bin unless the fit is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would leave large waste
        // or when there are no open bins.
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // Base new-bin cost, reduced when the current best-fit would be bad.
            score += 35.0;
            if post_residual > 60 {
                score -= 10.0; // large fresh bin is flexible
            }
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead: penalize proportionally.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.6 * dead.min(40.0);
    }

    // Prefer filling bins tighter than the current mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    // Early stream: slightly favor tight fills; late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress;

    // New empty bin candidate: neutral baseline, only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: many open bins with slack -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }
    // Prefer bins with residual near the mean (balanced packing) early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // New-bin candidate handling: make empty bins unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 + 20.0 * desperation;
        // Late in stream, opening new bins is fine if residuals are fragmented.
        if progress > 0.8 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them quadratically.
    let p_weight = 0.5 + 1.5 * progress * progress;
    score += 0.6 * p_weight * (pr * pr) / cap;

    // Reward tight fits (low post residual), stronger as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * (0.4 + progress) * tightness * tightness;

    // Penalize creating dead space that cannot fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty when bin is far below mean residual (keeps balance),
    // smooth cubic coupling with open bin count.
    let diff = (mean_residual - pr) / cap;
    score += 1.5 * diff * diff * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // New-bin candidate: make it attractive only for large items with poor fits.
    if bin_residual == bin_capacity {
        score = pr + 4.0 - 10.0 * (item_size as f64 / cap) * (0.3 + progress);
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, and small leftovers) are preferred.
    let pr = post_residual;
    let class_mod = pr % 10;
    if class_mod == 0 {
        score -= 12.0; // perfectly aligned leftover, likely reusable
    } else if class_mod <= 3 {
        score += 4.0; // awkward sliver
    } else {
        score += 8.0; // dead space band
    }

    // Integer-division thresholds: reward leaving space big enough for common
    // size bands (>= 25, >= 50).
    if pr >= 50 {
        score -= 15.0;
    } else if pr >= 25 {
        score -= 6.0;
    } else if pr > 0 {
        score += 10.0;
    } else {
        score -= 20.0; // perfect closure
    }

    // Fractional fill level coupling.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 10.0 * fill * fill;

    // Lookahead: if next item fits the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0;
        // harmonic check: next item also lands on a class boundary
        if (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are fragmented and the item is large.
    if bin_residual == bin_capacity {
        let frag = (mean_residual - (post_residual as f64)).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.5;
        score = 60.0 + frag * 0.3 - progress * 10.0 + pressure;
        if item_size > 70 {
            score -= 15.0; // big items like fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pair fits nicely in a fresh bin
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * open_bins_count as f64 * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 interface, use ~10 threshold)
    // and also penalize gaps that are just above the next item size (near-miss waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny dead gap: nearly unusable forever
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0 + 0.5 * (next_item_size as f64 - post_residual);
    }

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 40.0;
    }
    let fill_ratio = (item_size as f64) / (bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Open bins pressure: discourage scattering across many bins, but allow
    // opening a new bin when all existing fits would create bad dead space.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins that are already partially
    // filled relative to the fleet average (tight packing).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // reward heavily (chained perfect packing).
    if next_item_size > 0 && post_residual == next_item_size as f64 {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when it enables
    // a clean fill; otherwise keep it slightly worse than reusing a good bin.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * fill_ratio;
    }

    // Stream progression: early on, be more tolerant of opening bins; late,
    // squeeze everything to avoid extra bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

