    }

    // Prefer bins tighter than average (good fits), discourage very loose bins
    score -= (mean_residual - post_residual as f64) * 1.5;

    // New-bin candidate: only attractive when it enables a good future chain
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 80.0 * (1.0 - progress); // early on, fresh bins with chain potential are fine
        } else {
            score += 150.0; // avoid new bins late or when no chain possible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
