    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // is decent, or the item is huge (best served by a fresh bin).
    if bin_residual == bin_capacity {
        let huge = fill_ratio > 0.5;
        let no_good_fit = fitting_bins_count <= 1 && post_residual < 10;
        if huge || no_good_fit {
            score -= 10.0;
        } else {
            score += 18.0 + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Global pressure: when many bins are open with slack, discourage new bins
    // and encourage consolidation into high-residual bins.
    score += 0.15 * mean_residual * (open_bins_count as f64).sqrt() * 0.1;

    // Late in stream: prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fill_ratio;

    // Perfect or near-perfect closure reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr * pr * (0.5 + progress) + pr * progress * progress;
    score += 12.0 * poly;

    // Penalize dead space more strongly later in the stream
    score += progress * pr * 10.0;

    // Reward tight fits smoothly
    let tight = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tight * tight * 8.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 3.0;
    } else if next_item_size > 0 {
        score += pr * 4.0;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: encourage opening fresh bins early, discourage late
    if bin_residual == bin_capacity {
        score += progress * 15.0 - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strong baseline so it only wins when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 150.0 - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        return score;
    }

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class = pr % 10; // decile residue class
    // Penalize "awkward" residues that rarely combine with items (1..=100 range).
    let awkward = matches!(class, 1 | 2 | 3 | 7 | 8 | 9);
    if awkward {
        score += 12.0;
    } else {
        score -= 4.0;
    }

    // Integer-division threshold: how many "typical" small items fit in the leftover.
    let slots = pr / 10;
    score -= slots as f64 * 2.5;

    // Lookahead coupling: reward if next item fits exactly or snugly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect harmonic pairing
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            // snug fit reward, decaying with gap; mod-5 harmonics favored
            let snug = 20.0 / (1.0 + gap as f64);
            let harmonic_bonus = if (pr % 5 == 0 && next_item_size % 5 == 0) { 6.0 } else { 0.0 };
            score -= snug + harmonic_bonus;
        } else {
            // next item cannot use this residual: penalize large residuals that strand space
            score += (pr as f64) * 0.15;
        }
    } else {
        // last item: minimize waste directly
        score -= 10.0;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    if (pr as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late in the stream: consolidate, avoid opening excess structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item (1..=9)
    // or too small for the lookahead item when the lookahead could otherwise pack here.
    if post_residual > 0 {
        if post_residual <= 9 {
            score += 60.0; // unusable sliver: strongly penalize
        } else if next_item_size > 0 && next_item_size > post_residual {
            // lookahead item cannot fit this gap: the leftover is likely dead
            score += 25.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // usable leftover: mild reward scaled by how reusable it is
            score -= 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // perfect fill: big reward
        score -= 40.0;
    }

    // Reward tight fits relative to the bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // prefer consolidation into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (1.0 - progress);

    // New-bin candidate handling: an empty bin has no dead space yet but wastes
    // mean residual already committed elsewhere; make it moderately attractive
    // only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_quality = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(2.0)
        } else {
            2.0
        };
        // If the item fits poorly in typical open bins, opening fresh is better.
        score -= 15.0 * (avg_fit_quality - 1.0).max(0.0);
        // But with lookahead, penalize opening a bin the next item can't join.
        if next_item_size > 0 && next_item_size + item_size as u32 > bin_capacity {
            score += 20.0;
        }
    }

    // Prefer bins whose residual is close to the mean (avoid extreme fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect lookahead fit (small gap that is still likely usable).
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Penalize leaving dead space below the smallest plausible item (1..10).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Penalize when the next item cannot fit here but barely fits elsewhere:
    // wasting residual capacity relative to mean residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }
    // Many fitting bins: prefer tighter fits, mildly discourage spreading.
    if fitting_bins_count > 2 {
        score += 2.0;
    }

    // Compare residual to mean residual across open bins: prefer bins that
    // keep the residual distribution balanced, but reward filling fuller bins.
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post_residual as f64) * 0.2;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // If this is the last fitting bin (or no open bin fits), opening new is fine.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for tighter bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize large dead space nonlinearly, scaled by stream progress.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward tight fits (small post residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
        // Extra reward if next item nearly fills the remaining space.
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize leaving awkward gaps.
        score += 3.0 + 0.05 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Early stream: be lenient with opening new bins to build a diverse residual pool.
    // Late stream: consolidate, penalize new bins.
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
        score += 6.0 * progress * open_pressure;
        // Opening a new bin is fine early or when no bin fits well.
        score -= 4.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Prefer bins with residuals below the mean (compact bins first keeps spread manageable).
    score += 2.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Slight preference for bins whose residual is close to a common small remainder.
    let r = post_residual as u32;
    if r == 0 { score -= 20.0; }
    else if r <= 10 { score -= 6.0; }
    else if r < 20 { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes progressively more costly.
    let dead_space_penalty = norm_post * norm_post * (1.0 + 3.0 * progress) * cap * 0.5;
    score += dead_space_penalty;

    // Cubic interaction: waste is increasingly intolerable as the stream matures.
    score += norm_post.powi(3) * cap * (0.5 + 2.0 * progress);

    // Lookahead coupling: reward residual that still fits the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - (post - nxt) / cap) * (1.0 + 2.0 * progress) * 8.0;
        } else {
            // smooth penalty proportional to shortfall
            let shortfall = (nxt - post) / cap;
            score += shortfall * shortfall * cap * (0.3 + 1.5 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening new bins when open bins exist and fit is reasonable,
    // with strength growing over the stream (smooth in progress).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += (5.0 + 20.0 * progress) * (1.0 + (openness / (1.0 + openness)).ln().max(0.0));
        // new bin is more acceptable if mean residual is small (few useful bins)
        score -= (mean_residual / cap).max(0.0) * 15.0 * (0.5 + progress);
    }

    // Mild preference for bins with residuals near the item size (smooth coupling).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += fit_gap.abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 create
    // "dead zones" where small future items (sizes 1..10) can still fit.
    let post = post_residual as i64;
    let residue_class = post % 10;

    // Reward residuals that are either perfect (0) or in the "usable band"
    // (>= 10, i.e. any integer item could still fit later).
    if post == 0 {
        score -= 30.0; // perfect closure
    } else if post < 10 {
        // Dead space: nothing (min size 1) is guaranteed, but tiny items exist.
        // Penalize proportionally to how close to 0 but non-zero we land.
        score += (10 - post) as f64 * 2.0;
    } else {
        // Usable residual: reward harmonic alignment — residual close to a
        // multiple of common item sizes (10, 20, 25, 50) is more reusable.
        let r = post as f64;
        let harmonics = [
            (r % 10.0).min(10.0 - r % 10.0),
            (r % 20.0).min(20.0 - r % 20.0),
            (r % 25.0).min(25.0 - r % 25.0),
            (r % 50.0).min(50.0 - r % 50.0),
        ];
        let avg_harmonic = harmonics.iter().sum::<f64>() / 4.0;
        score += avg_harmonic * 0.8; // small penalty for misalignment
    }

    // Integer-division threshold on post_residual: large residuals are flexible.
    let tier = post / 25; // 0..4 harmonic tier
    score -= tier as f64 * 5.0;

    // Lookahead coupling: if the next item fits the post-residual exactly,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: bonus scaled by how well it harmonizes
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 20.0;
            } else {
                score -= 10.0;
            }
            score += slack as f64 * 0.3; // prefer tight follow-up
        } else {
            // next item cannot follow in this bin: mild penalty
            score += 6.0;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is
    // the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless residual waste here
    // would be severe. An empty bin scores near capacity; open bins get
    // progressively better scores as they fill.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // Allow new bin early in the stream (plenty of future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        if progress < 0.25 {
            score -= 20.0;
        }
    }

    // Mild preference to consolidate into bins below mean residual
    // (fills the emptiest-but-fitting bins first, keeping tight bins tight).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Small tie-breaker favoring bins whose residual class matches item size
    // modulo class (harmonic pairing).
    if (bin_residual % item_size.max(1)) == 0 && item_size > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open (bin-count pressure).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 1.5;
        // But if no open bin fits well, new bin may still win naturally.
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish: strong reward
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would not fit here: penalize wasted space relative to next item
            score += 50.0 + diff * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Compare residual to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize large dead space (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score -= 30.0; // small but likely unusable gap -> fine, nearly perfect fit
    }
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.8; // large gap wasted
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only prefer it when item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening a new bin is attractive for big items or when no open bin fits well
        score += 60.0 - 80.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 20.0;
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
