    // Penalize dead space: small post-residuals are fine, mid-range waste is bad.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * (1.0 - dead) * 4.0 * dead; // peaks for mid-size leftovers
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving space that exactly blocks nothing useful.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev; // prefer bins below-average residual (fuller bins)

    // Late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, expensive late, or when few items remain.
        score += 10.0 + 40.0 * progress;
        if total_items.saturating_sub(step_index) < 10 {
            score += 30.0;
        }
        // Opening a bin is good if item is large and no open bin fits well.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for using fewer bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty for residual; late stream: harsher penalty
    // since remaining chances to fill dead space shrink.
    let g = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    score += 0.35 * g * pr;
    score += 0.15 * (pr * pr) / cap * (1.0 + g);

    // Reward tight fits (small post_residual) with a smooth cubic reward.
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item can use the post residual, reward this bin.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = pr - n;
            score -= 2.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: penalize large residual less if it's tiny
            score += 0.5 * g * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Many open bins: discourage spreading residual waste across bins.
    score += 0.05 * open_bins_count as f64 * g;

    // Mean-residual coupling: penalize bins far above the mean residual
    // (they hoard space), reward bins below the mean.
    let dev = pr - mean_residual;
    score += 0.1 * dev * (0.5 + g);

    // New-bin candidate: neutral-ish baseline with a smooth progress-dependent
    // reluctance to open new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * g;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space that no future item (1..=100)
    // can ever fill exactly is penalized. Residuals > 50 can hold half-size items;
    // residuals <= 10 are near-dead unless exactly matching small items.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows quadratically for tiny residuals
        if pr <= 10 {
            score += (11 - pr) as f64 * 3.0;
        }
        // Class boundaries at capacity fractions 1/3, 1/2
        if pr > bin_capacity / 2 {
            score -= 15.0; // roomy bin, still useful
        } else if pr > bin_capacity / 3 {
            score -= 5.0;
        } else if pr <= 20 {
            score += 8.0; // awkward leftover
        }
        // Modulo-class bonus: residual divisible by common item sizes (10, 20, 25)
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 10 {
            score -= 40.0;
        } else if next_item_size > pr {
            score += 10.0; // next item won't fit here anyway; keep bin flexible
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (score - post_residual as f64) > 0.0; // existing bins penalized
        if poor_fit || open_bins_count == 0 {
            score -= 25.0 + 20.0 * progress;
        } else {
            score += 50.0; // discourage opening new bins when fits exist
        }
    }

    // Spread-awareness: prefer bins below mean residual (tighter bins used first)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for fewer open bins early on
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_zone = 12.0; // gaps below this are hard to fill (items >= 10, small margin)
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * (8.0 + 6.0 * progress);
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit: strongly reward
    }

    // Open-bin pressure: discourage proliferating bins; favor packing into existing ones.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins from opening unless existing fits are poor.
        score += 25.0 + open_bins_count as f64 * 0.5;
        // Reward opening a new bin when the current item is large (poor fit candidates).
        if item_size > 50 {
            score -= 10.0;
        }
        // If the next item is small, an existing bin with modest residual is fine.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score -= 12.0; // this bin's post gap can't host next item anyway
        }
    } else {
        // Favor bins whose post_residual can still accommodate the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 {
            score += 4.0;
        }
    }

    // Mild tie-break toward bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let exactness = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + exactness);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize mildly
        score += 5.0;
    }

    // Penalize large dead space relative to mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.15 * dead;
    } else {
        score += 0.05 * dead;
    }

    // Last-chance bonus: avoid wasting a unique fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 25.0 * (1.0 - fragmentation);
    }

    // Tight fits are excellent: small post_residual rewarded nonlinearly
    if post_residual > 0 {
        score -= 8.0 * (-post_residual as f64 / 10.0).exp();
    } else {
        score -= 12.0; // perfect fill
    }

    // Late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Penalize waste relative to what other bins offer.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 / (1.0 + gap);
    }
    // If next item cannot fit here, slight penalty for creating dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item is large and current residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        // Penalize opening a new bin generally; ease up late in the stream.
        score += 30.0 - 10.0 * progress;
        // If item nearly fills a fresh bin, new bin becomes attractive.
        score -= 0.4 * item_size as f64;
        // If many open bins already have lots of slack, discourage new bins.
        score += 0.2 * mean_residual;
        let _ = waste;
    }

    // Mild preference for filling bins with larger residual when few bins are open.
    if open_bins_count < 4 && !is_new_bin {
        score -= 0.05 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial progress coupling: penalize residual more as stream progresses
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * prog_poly * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post_residual) more strongly late in stream
    score -= 8.0 * prog_poly * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * (nx - pr) / cap;
        } else {
            score -= 4.0 * (1.0 - nx / (pr + 1.0));
        }
    }

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr * 0.5);
    }

    // Mild preference for bins below mean residual (consolidate fullness)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin mildly, more early in stream
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - 0.5 * prog_poly);
    }

    // Slight penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable; penalize awkward classes.
    let r = post_residual;
    if r > 0 {
        let mut bonus = 0.0;
        if r % 10 == 0 { bonus -= 6.0; }
        if r % 20 == 0 { bonus -= 4.0; }
        if r % 25 == 0 { bonus -= 4.0; }
        if r % 50 == 0 { bonus -= 8.0; }
        // awkward residual classes (small odd leftovers)
        if r < 10 { bonus += 15.0; }
        score += bonus;
    } else {
        score -= 12.0; // perfect fit
    }

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 && next_item_size <= r {
        score -= 8.0 + (r - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && next_item_size > r && r > 0 {
        score += 5.0; // next item won't reuse this residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current residual is very small or
    // the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let tight = (bin_capacity - item_size) as f64;
        score += 10.0;
        if open_bins_count == 0 || fitting_bins_count == 0 {
            score -= 25.0;
        }
        if r == bin_capacity - item_size && r >= 50 {
            score -= 5.0; // fresh bin leaves a large reusable residual
        }
        if tight < 5.0 { score += 8.0; }
    }

    // Fraction-of-capacity coupling: residual as fraction of capacity
    let frac = r as f64 / bin_capacity as f64;
    score += (frac * 0.25).sin() * 3.0;

    // Stream progression: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - frac);

    // Mean residual deviation: prefer bins near the mean (balanced packing)
    score += (mean_residual - r as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harder than large ones
    if post_residual > 0 {
        if post_residual < 10 {
            // Smallest dead space: nearly perfect fit, strongly reward
            score -= 25.0;
        } else if post_residual <= 20 {
            // Small gap: potentially unusable dead space, penalize
            score += 15.0;
        } else if post_residual <= 35 {
            // Medium gap: neutral-to-slightly-poor
            score += 4.0;
        } else {
            // Large gap: still usable for future items, mild reward relative to baseline
            score -= 2.0;
        }
    } else {
        // Perfect fill: massive reward
        score -= 60.0;
    }

    // Coupling with next item lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= (slack as f64).min(30.0) * 0.2;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use
        score += 8.0;
    }

    // Open bins pressure: prefer spreading into existing bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmented bins)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New bin candidate: make empty bins moderately attractive only when few bins open
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 40.0;
        } else {
            score += 12.0 + open_bins_count as f64 * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Penalize leftover gap after hypothetically placing the next item too.
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.35;
        } else {
            // Next item cannot follow in this bin: penalize small unusable leftovers.
            let slack = (next_item_size - post_residual) as f64;
            score += slack.min(40.0) * 0.5;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    // Relative to mean residual: prefer bins deviating from mean in useful ways.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit,
    // but reward using it when the fit is good.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could still serve.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.2;
    }

    // Late in the stream, favor tighter packing to avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing small can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // awkward tiny sliver
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Prefer bins whose residual deviates from the mean (harmonization).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, tolerate more open bins / new bins;
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 40.0 * progress;
        if open_bins_count < 3 {
            score -= 15.0 * (1.0 - progress);
        }
    } else {
        // Existing bin: slightly favor fuller bins late in the stream.
        score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty for proliferating open bins when mean residual is low (bins nearly full).
    if mean_residual < 15.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = (pr / cap).clamp(0.0, 1.0);

    // Base: reward tight fits (low post residual) with a non-linear polynomial
    let mut score = 2.0 * pr + 30.0 * fit_norm * (1.0 - fit_norm) * 4.0;

    // Smooth stream-progress coupling: early on, prefer filling bins (waste penalty grows),
    // later, keep residuals flexible.
    let early = (1.0 - progress) * (1.0 - progress);
    let late = progress * progress;
    score += early * 1.5 * pr;
    score -= late * 20.0 * fit_norm;

    // Dead-space penalty: residual too small for any plausible item (min size 1, typical 10)
    let dead = ((10.0 - pr).max(0.0)) / 10.0;
    score += 25.0 * dead * dead;

    // Lookahead coupling: bonus if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = ((pr - nxt) / cap).clamp(0.0, 1.0);
        score -= 15.0 * fits;
        // penalize exact-fill that leaves nothing for a large next item
        score += 5.0 * ((nxt - pr) / cap).clamp(0.0, 1.0);
    }

    // Last-chance bin: strongly favor using it over opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild pressure against proliferating bins when mean residual is high
    score += 0.3 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: neutral-ish baseline, penalized slightly unless residuals are tight
    if bin_residual == bin_capacity {
        score += 45.0 - 60.0 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization
    // Residuals that are multiples of small item sizes (10..=20) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
        if reusable {
            score -= 6.0; // harmonic residue is attractive for future small items
        } else if pr < 10 {
            score += 12.0; // unusable dead space below min item size
        } else {
            score += 3.0; // awkward non-harmonic leftover
        }
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 25.0;
    }

    // Exact-fill of common fractions of capacity
    let filled = bin_capacity - pr;
    if filled == 50 || filled == 100 || filled == 75 || filled == 80 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current bin would be left
    // with very awkward residue or no bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits: must open new bin
        } else if mean_residual > item_size as f64 * 1.5 {
            score -= 5.0; // plenty of slack elsewhere, still mild penalty
        }
        // late in stream, keep bins consolidated
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 5.0;
        }
    }

    // Mild preference for tighter bins when many are open
    score += (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host even the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small gaps are hard to fill later; quadratic-ish penalty.
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.15;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // mildly favor filling already-open bins as open_bins_count grows.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).sqrt() * 1.5;
    }

    // Prefer bins whose residual is below average (tighter bins) when the
    // fit is tight; discourage dumping into overly loose bins.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - res) * 0.1;
    }

    // Early in the stream, be slightly more willing to open fresh bins;
    // later, consolidate to avoid bin-count blowup.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Exact-fit celebration.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // next item fits exactly-ish here: strong reward
            score -= 14.0 * (1.0 - gap / bin_capacity as f64);
            // perfect match bonus
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            score += 4.0 + 0.06 * gap;
        }
    } else {
        // last item: prefer tightest fit
        score -= 6.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize tiny dead space that nothing can use (sizes >= 1)
    if post_residual > 0 && post_residual < 4 {
        score += 8.0;
    }

    // Early in stream: be more liberal about opening new bins (keep flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline offset, cheaper early, expensive late
        score += 10.0 - 16.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 6.0; // large next item: fresh bin useful
        }
    }

    // Many open bins: discourage spreading; few open bins: encourage reuse
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.4;

    // Prefer bins with residual below the mean (use up smaller leftovers first).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Time horizon: early in stream, favor opening fresh bins for big items;
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize normally, but less when item is large
        // or progress is early and fits are plentiful.
        let size_bonus = (item_size as f64 - 50.0) * 0.4;
        score += 25.0 - size_bonus - 15.0 * (1.0 - progress) + (fitting_bins_count as f64) * 2.0;
    } else {
        // Late stream: reward using existing bins more.
        score -= 10.0 * progress;
    }

    // Slight reward for bins whose residual is close to item size (best fit).
    let slack = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += slack * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress2 = progress * progress;
    let progress3 = progress2 * progress;

    // Smooth non-linear coupling of post_residual with progress:
    // early in the stream, prefer tight fits strongly; later, weight dead space less
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let coupling = pr_norm * (1.0 + 2.0 * progress2 + 3.0 * progress3);
    score += 4.0 * coupling;

    // Smooth penalty for large unused residual relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * (1.0 + progress);

    // Reward bins that can also accommodate the lookahead item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_margin = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - fit_margin * fit_margin) * (1.0 - 0.5 * progress3);
        } else {
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins exist
    if fitting_bins_count >= 1 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 8.0 * scarcity * (1.0 - progress2);
    }

    // Mild penalty proportional to number of open bins, decaying over stream
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * progress3;

    // Smooth bonus for very tight fits (small post_residual)
    let tightness = 1.0 - pr_norm;
    score -= 3.0 * tightness * tightness * (1.0 + 2.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: 1/capacity fraction buckets
    let cap = bin_capacity as f64;
    let item_class = (item_size as f64 / cap * 8.0).floor(); // 0..8 harmonic class
    let post_class = (post_residual as f64 / cap * 8.0).floor();

    // Reward tight fits (low post_residual, especially in low harmonic classes)
    score -= (cap - post_residual as f64) * 0.15;

    // Penalize dead space: post_residual that is too small to fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo-arithmetic coupling: post_residual mod 10 thresholds
    let post_mod = post_residual % 10;
    if post_mod == 0 {
        score -= 8.0; // perfectly aligned residual, likely reusable
    } else if post_mod >= 7 {
        score += 4.0; // awkward residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; residual becomes dead space for lookahead
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // no open bin offers a decent fit or item is large (high harmonic class)
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (mean_residual / cap + 1.0);
        let base = cap * 0.55; // neutral threshold
        score = base + item_class * 6.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 * 3 / 4 {
            score -= 20.0; // large next item benefits from fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 15.0; // few alternatives: new bin is fine
        }
    }

    // Harmonic class penalty: placing large items into nearly-full bins is good,
    // placing small items into large-residual bins wastes capacity
    let residual_frac = bin_residual as f64 / cap;
    score += (item_class as f64) * (1.0 - residual_frac) * 3.0;

    // Integer-division threshold on post_residual quarters
    let quarter = post_residual / (bin_capacity / 4);
    score -= quarter as f64 * 2.0;

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    // Mean residual coupling: when mean residual is high, discourage wasting it
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 30.0;
    }

    // Reward tight fits (large fill ratio of this placement).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // If this bin is the last chance to avoid opening a new bin, reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer existing bins when many are open.
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Lookahead: if next item fits exactly into the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // post-residual too small for next item: penalize more if it's dead space.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // New-bin candidate: only attractive when it enables a good future pairing,
    // otherwise keep residual pressure on open bins.
    if bin_residual == bin_capacity {
        let base = 18.0 + 0.6 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score = base - 8.0; // new bin can host the pair
        } else {
            score = base + 10.0; // discourage opening without a plan
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (residual below minimum item size 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to tightness of chain fit
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // next item does NOT fit the leftover: penalize wasted-looking residuals
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * progress * (post_residual == 0) as i32 as f64;

    // New-bin candidate: make empty bins less attractive unless no good open bin exists
    if bin_residual == bin_capacity {
        score += 120.0;
        // late in stream, opening fresh bins is more acceptable
        score -= 60.0 * progress;
        // if few bins can fit, opening a new bin is reasonable
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 0.5 * progress) * 0.6;

    // Penalize dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 - slack.min(20.0)) * 0.8;
        } else {
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins below mean residual (fill emptier bins first keeps big gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New bin candidate: make it attractive only when existing fit is bad.
    if bin_residual == bin_capacity {
        let bad_existing = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let waste = (bin_capacity - item_size) as f64;
        score = waste - bad_existing + 10.0 * progress;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 8.0; // big item in fresh bin, next small item can follow
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), scaled by progress
    let mut score = pr * (1.0 + 0.8 * progress) + 60.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose post-residual is awkwardly small but nonzero (dead space)
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0);
    score += 15.0 * (1.0 - 4.0 * dead.abs());

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post-residual (smooth sigmoid-like term)
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        let s = 1.0 / (1.0 + (-8.0 * fits).exp());
        score -= 20.0 * s;
    }

    // Mild penalty for spreading across too many open bins, modulated by mean residual
    let mr = mean_residual / cap;
    score += 3.0 * open_bins_count as f64 * (0.5 - mr).max(0.0);

    // New-bin candidate: prefer opening a fresh bin early or when item is large
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / 100.0;
        score -= 10.0 * (1.0 - progress) + 8.0 * large_item_bonus - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 create "dead zones"
    // where leftover space is likely unusable for typical small items.
    let residue_class = post_residual % 10;
    score += match residue_class {
        1..=3 => 6.0,          // tiny slivers -> high dead-space penalty
        4..=6 => 2.0,
        7..=9 => -2.0,         // chunky leftovers -> still reusable
        _ => 0.0,
    };

    // Integer-division thresholds: bins whose post_residual falls into the
    // lowest quartile of capacity are near-perfect packs; reward them.
    let quartile = bin_capacity / 4;
    if post_residual < quartile {
        score -= 10.0;
    } else if post_residual < 2 * quartile {
        score -= 4.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 {
        // next item cannot follow here: penalize more if the leftover is a sliver
        score += (post_residual as f64) * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are
    // large (fragmented state) and the current fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = mean_residual / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64;
        // New bin score = its full residual, discounted by fragmentation pressure.
        score = bin_capacity as f64 * (1.0 - 0.35 * fragmentation)
              + poor_fit * 0.1
              + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin mandatory-ish
        }
    }

    // Late-stream tightening: as the stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.03;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer chains leaving modest, still-usable slack.
            if slack <= 10.0 {
                score -= 20.0 - slack;
            } else {
                score -= 10.0 / slack.sqrt();
            }
        } else {
            // Next item cannot fit here after placement: penalize proportionally.
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 + miss * 0.25;
        }
    }

    // Penalize wasting a large residual on a small item (bad space use vs. mean).
    let mean_res = mean_residual;
    if (post_residual as f64) > mean_res + 20.0 {
        score += (post_residual as f64 - mean_res - 20.0) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        // Opening a new bin is penalized mildly so it's chosen only for poor fits.
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0 * pressure; // fresh bin pairs well with next item
        } else {
            score += 10.0 * pressure;
        }
    }

    // Late-stream consolidation: tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Slight preference for filling fuller bins.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last chance: this is the only bin that fits -> strong bonus to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Reward leaving room exactly matching next item.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Compare against mean residual: bins with residual near mean are natural targets.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New bin candidate handling: an empty bin has large post_residual which is
    // naturally unattractive; add extra penalty scaled by how many bins fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (fitting_bins_count as f64);
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Prefer filling bins that are already fairly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress)
        - 30.0 * norm_pr * (1.0 - norm_pr) * (1.0 + progress);

    // Tight fits rewarded more as stream progresses
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild new-bin penalty scaled by open bins
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10 units.
    let post_class = (post_residual / 10) as f64;
    score += post_class * 1.5; // prefer bins leaving smaller residual class

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small dead space reward (residual < 10 is nearly unusable for items >=10... but sizes can be 1..100)
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // tiny leftover is fine, nearly full bin
    }

    // Penalize mid-range dead space (harmonic awkward class 20..50)
    if post_residual >= 20 && post_residual <= 50 {
        score += 6.0;
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward good chain fit
            score -= 10.0 + slack * 0.05;
            // harmonic class match: next item leaves residual in same class
            let next_post = post_residual - next_item_size;
            if (next_post / 10) == (post_residual / 10) {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base penalty so new bins are only chosen when clearly better
        score += 30.0 + open_bins_count as f64 * 2.0;
        // if item leaves a large usable residual in a fresh bin, that's fine (fresh bin has full room for future)
        if post_residual >= 50 {
            score -= 20.0;
        }
        // if no existing bin fits well (this is the only fitting option), neutralize penalty
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Progress-based mild pressure: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Mean residual coupling: if mean residual across bins is low, cherish remaining capacity more
    score += (mean_residual - post_residual as f64).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residual that cannot fit any plausible future item (1..100 range unknown, so weight mid-small gaps).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or the next item fits better in a fresh bin.
    if bin_residual == bin_capacity {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        let next_fits_fresh = (next_item_size as f64) <= bin_capacity as f64;
        let next_fits_here = next_item_size > 0 && next_item_size <= post_residual;
        score -= 10.0;
        score += dead * 25.0;
        if next_item_size > 0 && !next_fits_here && next_fits_fresh && post_residual < next_item_size {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: prefer bins where the next item also fits after this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Slight progress pressure: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Mean residual coupling: if mean residual is high, favor consolidating into fuller bins.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a nonlinear push
    // toward very small leftovers (dead-space avoidance).
    let pr = post_residual as f64;
    score = pr + 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: does this placement leave room for the next item?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // Next item fits here too: reward, stronger the tighter the pair fit.
            let slack = pr - nxt;
            score -= 14.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to the gap.
            let gap = nxt - pr;
            score += 6.0 + 0.25 * gap;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is below
    // average concentrates waste where it's already expected (good); placing into
    // an above-average bin spreads waste (mild penalty).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        // But if the leftover would be unusable dead space, soften the bonus.
        if pr > 0 && pr < 10 {
            score += 18.0;
        }
    }

    // New-bin candidate: only attractive late in the stream or when open bins are
    // heavily fragmented; otherwise make it costly to open a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = open_bins_count as f64 / 8.0;
        score = 60.0 - 20.0 * progress - 6.0 * fragmentation;
        // If the item is large relative to capacity, opening fresh is more natural.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead (k=2): reward bins whose post-residual still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += next_item_size as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a fresh bin when alternatives exist,
    // with penalty growing with the number of viable open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * fitting_bins_count as f64;
    }

    // Dead-space shaping: very small post-residuals are excellent (tight fit);
    // moderately small residuals are slightly wasteful.
    if post_residual < 10 {
        score -= 3.0;
    } else {
        score += post_residual as f64 * 0.02;
    }

    // Time-horizon coupling: as the stream progresses, prefer bins whose
    // residual deviates least from the global mean residual (balance load).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: strongly favor small post_residual with smooth non-linear coupling.
    let mut score = pr * (1.0 + 0.9 * progress) + 18.0 * norm_pr * norm_pr;

    // Smooth interaction: post_residual vs mean residual (avoiding outlier dead space).
    score += 0.35 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: penalize leaving residual that neither fits next item well
    // nor is useless; smooth quadratic in the gap between post_residual and next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.12 * gap * gap / cap;
        // Reward if next item fits exactly-ish after this placement.
        if next_item_size as f64 <= pr {
            score -= 6.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty for proliferating open bins, stronger late in the stream.
    score += open_bins_count as f64 * (0.8 + 1.5 * progress);

    // Smooth reward for tight fits (small normalized post-residual) via cosine-like term.
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class of post_residual (mod-10 classes): residuals near
    // class boundaries (0, 10, 20, ...) are reusable by typical items.
    let class = post_residual % 10;
    let class_penalty = if class == 0 {
        -12.0 // perfectly aligned residual: highly reusable
    } else if class <= 2 {
        6.0 // tiny sliver, nearly dead space
    } else if class <= 5 {
        2.0
    } else {
        0.0
    };
    score += class_penalty;

    // Dead space penalty: post_residual smaller than the smallest possible item
    if post_residual > 0 && post_residual < 1 {
        score += 1000.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain placement possible
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 5.0; // harmonic alignment with next item
            }
        } else {
            score += 10.0; // this bin becomes dead after placement
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (scaled by how many already open)
        score = 60.0 + 3.0 * open_bins_count as f64;
        // Large items relative to capacity benefit from a fresh bin
        let load = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * load * load;
        // If next item chains well after this one in a fresh bin, discount
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // If mean residual of open bins is large, prefer reusing them
        score += 0.4 * mean_residual;
        // If this bin is the only fitter, opening new bin is fine
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    let dead_threshold: f64 = 10.0; // minimum plausible item size region
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving gaps that are larger than needed but still awkward:
    // a residual just above the smallest item size range is "trapped" space.
    if post_residual >= 1 && post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward this bin; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 6.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 8.0; // next item leaves near-perfect chain fit
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // tight fit exists; encourage filling when bins are already numerous.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the
    // current fit would create large dead space.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) < 20.0 && post_residual > 0;
        score += if bad_fit { -5.0 } else { 30.0 };
    }

    // Mild tie-breaker: prefer bins whose residual is closest to the mean
    // (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a superlinear penalty
    // on large dead space so fragmented bins are deprioritized.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / (bin_capacity as f64);

    // 2-step lookahead: if the NEXT item exactly fits the post-residual, this is
    // a perfect chain placement -> strongly reward (subtract).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // next item fits: reward proportional to how perfectly it matches
            score -= 22.0 * (1.0 - diff / (bin_capacity as f64)) * (n / 100.0);
        }
        // if post_residual is smaller than next item but small in absolute terms,
        // the dead space is unlikely to ever be usable -> mild extra penalty
        if post_residual < next_item_size {
            score += 6.0 * (1.0 - pr / 100.0);
        }
    } else {
        // Last item: only tightness matters; reward perfect fill.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Relative-to-mean coupling: bins with residual well below the mean are
    // already "used up"; placing there concentrates waste sensibly.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 4.0 * (mean_residual - resid) / (bin_capacity as f64);
    } else {
        score += 3.0 * (resid - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the ONLY bin that fits, opening a new bin
    // wastes at least (capacity - item) space; strongly favor using it unless
    // the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        // but if post_residual is a tiny unusable sliver, soften the reward
        if pr > 0.0 && pr < 10.0 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh resource. Prefer it
    // only when no open bin offers a good fit (post_residual large relative to
    // capacity) or when many bins are open (load balancing / consolidation).
    if bin_residual == bin_capacity {
        // default mild penalty: reusing open bins is usually better
        score += 12.0;
        // if the best use of an open bin would leave big dead space, opening
        // a fresh bin becomes attractive
        if pr > 0.0 && (pr as f64) > 0.45 * (bin_capacity as f64) {
            score -= 30.0;
        }
        // early in the stream, building a pool of bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 4.0;
        }
        // with many open bins, avoid spreading further
        if open_bins_count > 8 {
            score += 10.0;
        }
    }

    // Perfect fill is always the best outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no realistic item can fill.
    if post_residual > 0 && (post_residual < 10 || post_residual > 80) {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // residual too small for next item: mild penalty scaled by waste
            score += (post_residual as f64) * 0.15;
        } else {
            // next item fits but leaves another residual: dampen reward
            let chain = (post_residual - next_item_size) as f64;
            score += chain * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor and many bins are already open with fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > mean_residual * 0.5;
        if poor_fit && open_bins_count > 2 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 50.0 + 30.0 * (1.0 - progress);
        }
    }

    // Prefer bins with residual below mean (consolidate fragmented space).
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.1;

    // Slight preference for more-filled bins as stream progresses.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, polynomially reshaped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Tight fits rewarded more strongly later in the stream.
    score -= 40.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - pr / (next_item_size as f64)) * (0.6 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Smooth reward when lookahead fits exactly well.
        let slack = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * slack * slack;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 10.0 * dev * (1.0 - norm_item);

    // New-bin candidate: penalize mildly early, allow late when current bins are fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 15.0 * progress * (open_bins_count as f64 / 8.0).min(1.5);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes define "dead space quality".
    let pr = post_residual;
    let harmonic_class = pr % 10;
    // Residuals that are multiples of 10 are more reusable (items 1..100, common sizes).
    if harmonic_class == 0 {
        score -= 6.0;
    } else if harmonic_class <= 2 {
        score += 4.0; // tiny slivers are nearly dead
    } else if harmonic_class >= 8 {
        score += 2.0; // awkward near-multiple residuals
    } else {
        score += harmonic_class as f64 * 0.3;
    }

    // Integer-division thresholds: post_residual bucketed in quarters of capacity.
    let quarter = (cap / 4.0) as u32;
    if pr >= 3 * quarter {
        score -= 5.0; // large leftover = flexible bin
    } else if pr < quarter / 2 {
        score += 6.0; // nearly full, little future use
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let next_class = (pr - next_item_size) % 10;
            score -= 8.0 - next_class as f64 * 0.5;
        } else {
            // next item won't fit here; penalize more if this was the last fitting bin
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: only one bin can fit this item -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or all open bins are poor fits (high mean residual mismatch).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        score = 20.0 + fill_frac * 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual < fill_frac * cap * 0.5 {
            score -= 10.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // penalize opening bins when many already open
        score += open_bins_count as f64 * 0.5;
    }

    // Waste-per-placement pressure: penalize high waste when few bins fit item.
    let waste = pr as f64 / cap;
    score += waste * waste * 4.0 * (fitting_bins_count as f64).recip().max(0.2);

    // Small phase coupling via step_index harmonic (mod 3 rhythm of stream).
    let phase = (step_index % 3) as f64;
    score += phase * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it cannot hold even the smallest plausible item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize leaving a residual that is just barely too small for the
    // lookahead item (likely dead space for the known future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward if the lookahead item exactly fits the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing space.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += pressure * 2.5;

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is already fragmented; penalize further fragmentation.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (post_residual would be large, i.e., a fresh full bin).
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            let best_gap = mean_residual.min(bin_capacity as f64);
            (best_gap - item_size as f64).max(0.0)
        };
        score += 25.0 - desperation * 1.5 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (< typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tightness: reward bins whose residual is mostly consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 30.0;
            // Extra reward if next item fits exactly afterwards.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else if (post_residual as i64) > 0 && (post_residual as u32) < next_item_size {
            // Dead space that the next item cannot use: penalize, scaled by
            // how close the next item is to fitting.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 15.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a poor fit for everything open.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (mean_residual + 1.0);
        // Base new-bin penalty so existing bins are preferred by default.
        score += 50.0;
        // If open bins are few and have large mean residual, keep closing them out.
        score += 20.0 * (1.0 / (1.0 + crowded));
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // If many bins already fit the item, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0 * (fitting_bins_count as f64);
        }
    }

    // Mild global pressure: when many open bins exist, prefer placements that
    // reduce mean residual dispersion (fill fuller bins).
    if bin_residual != bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    // Encourage using bins with large residual early, small residual late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - 2.0 * progress) * 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 0.6 * t * t + 0.4 * t * t * t;
    score *= poly;

    // Penalize large dead space more aggressively as stream progresses
    score += 6.0 * norm_pr * norm_pr * (0.5 + t);

    // Reward tight fits (small post_residual) with a quadratic bonus
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * t);

    // Last-chance bonus: strongly prefer this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Prefer bins with residual close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: penalize leaving post_residual that cannot fit next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (ni - pr).max(0.0) / cap;
        score += 8.0 * waste * waste;
        score -= 5.0 * if pr >= ni { 1.0 } else { 0.0 } * (1.0 - t);
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: discourage unless current fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 - 12.0 * norm_pr.min(1.0) - 20.0 * (1.0 - (post_residual as f64 / cap));
        score += 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: size classes via modulo arithmetic
    let item_class = item_size % 10;
    let post_class = post_residual % 10;

    // Reward "harmonic" post-residuals: multiples of 10 are highly reusable
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_class == 0 {
        score -= 12.0;
    } else {
        // penalize awkward dead space more when it's tiny (unusable)
        if post_residual < item_class.max(1) {
            score += 6.0;
        }
    }

    // Tight-fit reward: post_residual small relative to item
    let tightness = post_residual as f64 / (item_size as f64).max(1.0);
    score -= 8.0 / (1.0 + tightness);

    // Lookahead: reward if next item fits the post-residual (harmonic chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 / (1.0 + slack / 10.0));
        } else {
            // next item cannot use leftover: mild penalty scaled by waste fraction
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        // base cost of a fresh bin
        score += 30.0;
        // cheaper to open new bins early (more stream left to fill them)
        score -= 20.0 * (1.0 - progress);
        // if many bins are open with scattered residuals, prefer consolidation
        score += (mean_residual / cap) * 10.0;
        // large items pair well with a fresh bin (room for a complementary small item)
        if item_size >= 50 {
            score -= 8.0;
        }
        let _ = crowd;
    } else {
        // prefer fuller bins among open ones: penalize bins with large residual
        score += (bin_residual as f64 / cap) * 4.0;
        // mild preference for bins whose residual is below the mean (denser bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // modulo-threshold coupling: item class vs post class compatibility
    if post_residual > 0 && (item_class + post_class) % 10 == 0 {
        score -= 5.0; // complementary decimal classes
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small to hold any plausible future item
    // (items >= 1, but small gaps < 10 are effectively dead weight).
    let dead_threshold = 9.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward filling the bin tightly relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight bins.
    let pressure = (open_bins_count as f64) / 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            // post residual too small for next item: penalize proportional waste
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Mean-residual coupling: bins with residual far below mean are "almost full",
    // prefer closing them out.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 10.0 * dev / bin_capacity as f64;
    }

    // New-bin candidate: make it attractive only when current bin would leave
    // a bad gap and no other strong option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by item size (big items
        // deserve fresh bins).
        score = 45.0 - 20.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits, must open
        }
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: filling a bin completely is ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste_frac * waste_frac;
    }

    // 2-step lookahead: strongly reward post_residual that matches next_item_size
    // so the following item can also land here perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 / (1.0 + gap);
        if gap == 0.0 {
            score -= 80.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: potential dead space.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New empty bin candidate: penalize unless open bins are crowded or
    // the item is huge relative to what's left in typical open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / bin_capacity as f64;
        score += 55.0 - 40.0 * pressure - 15.0 * progress;
        // Opening a new bin for a big item is fine (big items are hard to place later).
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), with a nonlinear boost.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize creating small unusable gaps (< 10 can't fit anything).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can use the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack);
        } else {
            // next item cannot fit here; penalize large leftover more
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // More bins already open -> keep consolidating, penalize new bins more.
        score += 2.0 * open_bins_count as f64;
        // If mean residual of open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
        // Late in the stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Exception: huge item relative to typical residuals -> new bin may be right.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is closest to item size (best-fit flavor).
        score += 0.2 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Mild preference for filling already-open bins when many are open.
    if bin_residual != bin_capacity {
        score -= 1.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic growth of dead space penalty, modulated by stream progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (0.5 + progress));

    // Smooth coupling: residual quality vs progress (late stream punishes waste harder)
    score += 12.0 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.25);

    // Reward tight fits with smooth sigmoid-like term on post_residual
    let tight = (norm_pr * std::f64::consts::PI).cos();
    score -= 8.0 * tight.max(0.0) * (1.0 - progress * 0.5);

    // Lookahead: bonus if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = (next_item_size as f64 <= pr) as f64;
        score -= 10.0 * fit_next * (1.0 - gap / cap) * (0.5 + progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (0.6 + 0.4 * progress);
    }

    // Mean residual coupling: prefer bins near the mean (keeps pool balanced)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open
    score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 10.0)) * (1.0 - norm_pr);

    // New-bin candidate: penalize opening fresh bins unless residual would be tiny waste
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
        // Allow new bin when item is large (poor fit elsewhere)
        score -= 0.15 * item_size as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space quantization.
    // Residuals in the "useful" classes (multiples of small sizes) are less dead.
    let class = post_residual % 10;
    score += match class {
        0 => -8.0,               // perfectly reusable class
        1 | 2 | 3 | 4 => 2.0,    // narrow slivers, mildly dead
        5 => -3.0,               // half-slot style residual, re-usable by small items
        _ => 4.0,                // 6..9 awkward class
    };

    // Integer-division threshold: reward post_residual that can host common sizes.
    let fits_common = (post_residual >= 20) as f64 * 6.0 + (post_residual >= 50) as f64 * 4.0;
    score -= fits_common;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 10.0 - (waste_after_next as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize proportional gap
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating tiny dead space (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Early in stream: encourage keeping residuals large (spread), later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        let base = 25.0 + mean_residual * 0.10;
        // If the item would leave a good residual in a fresh bin, keep it moderate.
        score = base + post_residual as f64 * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight preference for bins tighter than average (waste concentration).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += 15.0 * fit_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // (avoids opening a new bin), unless dead space would be created.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 0 && post_residual <= 10 {
            score += 30.0; // still penalize dead space even at last chance
        }
    }

    // Open-bin pressure: prefer spreading load when many bins are open.
    score += open_bins_count as f64 * 0.6;

    // Lookahead: if next item fits the post residual exactly, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    }

    // Mean residual coupling: bins with residual far below mean are less attractive.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Slight late-stream tightening: as stream progresses, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    // New-bin candidate baseline: make empty bins slightly unattractive unless
    // everything else is bad (dead space / no fitting bins handled above).
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead — reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - next).abs();
        if diff == 0.0 {
            // Perfect chain: this placement enables a perfect next placement.
            score -= 60.0;
        } else if pr >= next {
            // Next item fits here afterwards; reward closeness of the match.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would NOT fit; penalize proportionally to the shortfall.
            score += 15.0 * (diff / bin_capacity as f64);
        }
    }

    // Prefer tight fits overall: small post_residual is good, but dead space
    // that can never host typical items is worse.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0; // tiny unusable sliver is fine (nearly full bin)
    } else if pr >= 10.0 && pr < 40.0 {
        score -= 5.0; // mid-range residual still usable
    } else if pr >= 60.0 {
        score += 6.0; // large waste when item was small
    }

    // Relative-to-mean coupling: filling a bin below the mean residual
    // concentrates waste favorably.
    score -= 0.3 * (mean_residual - pr);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // the lookahead suggests a big item follows that needs fresh space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_next = next_item_size >= 50;
        let poor_options = fitting_bins_count == 0;
        if poor_options || (big_next && open_bins_count > 0) {
            score -= 30.0;
        } else {
            // Penalize opening new bins when existing ones suffice,
            // more so late in the stream.
            score += 20.0 + 30.0 * progress;
        }
    }

    // Mild preference for filling bins that are already mostly full.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * 0.1;

    // Slight openness scaling: with many open bins, prefer compacting.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; mildly penalize leaving large gaps
            score += 3.0;
        }
    } else {
        // Last item: just minimize waste, reward using an existing bin fully.
        score -= 10.0 * fill;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // make it attractive only when the item is large or fits are poor elsewhere.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        let poor_fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 8.0 + 10.0 * fill };
        score += poor_fit_penalty - large_item_bonus - (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual) with smooth non-linear shaping
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, tolerate slack (favor spreading); late, squeeze hard.
    let coupling = x * x * (1.0 - progress) * 40.0 - x * progress * 30.0;
    score += coupling;

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * (0.8 + 0.6 * progress);
        } else {
            // reward residual that can still host the lookahead item
            score -= (pr - ns).min(20.0) as f64 * 0.3;
        }
    } else {
        // last item: maximize fill
        score -= 10.0 * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity (poor fit elsewhere) — smooth in item size.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let large_item = (item_size as f64 / cap - 0.5).max(0.0);
        score += 25.0 - 45.0 * large_item * large_item - 10.0 * progress;
    }

    // Slight preference for bins deviating below mean residual (balance load)
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that are "usable"
    // by common item sizes (multiples of 10, and small residuals <= 20 are dead space).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize dead space: residuals below the minimum item size are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward residuals in "harmonic" classes: divisible by 10 aligns with
    // typical item granularity; use modulo arithmetic on post_residual.
    let mod10 = post_residual % 10;
    score -= (10 - mod10) as f64 * 0.4; // near-multiples of 10 are slightly favored

    // Integer-division thresholds on post_residual: which canonical item sizes fit?
    let fits_class = post_residual / 20; // 0..5 classes of 20-capacity chunks
    score -= fits_class as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to tightness of the chain
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * tightness;
        } else {
            // next item cannot use this residual: slight penalty scaled by wasted potential
            score += 0.05 * (next_item_size - post_residual).min(40) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very poor fits (large post_residual dead space relative to item).
    if bin_residual == bin_capacity {
        // Fresh bin: score = leftover after item; add a fixed opening cost that
        // shrinks as the stream progresses (early on, opening bins is cheap).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * (1.0 - progress) + 6.0;
        // If many bins are open and mean residual is high, opening new bins is wasteful.
        score += 0.15 * open_bins_count as f64 + 0.05 * mean_residual;
    } else {
        // Existing bin: reward tight packing via fill fraction.
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill;
        // Prefer bins whose residual is close to the item (best-fit core).
        score += 0.1 * (bin_residual - item_size) as f64;
    }

    // Mild global pressure to keep the number of open bins low.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
