    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Gap that can still host a typical small item: mild reward.
        score -= 5.0;
    } else if post_residual > 60 {
        // Wasting a nearly-empty bin when tighter bins exist: mild penalty.
        score += 8.0;
    }

    // Reward filling bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: prefer compacting into existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when existing bins are fragmented.
        score = 70.0 + (open_bins_count as f64) * 2.0;
        if mean_residual < item_size as f64 * 1.2 {
            // Open bins are too full/fragmented; opening a new bin is more acceptable.
            score -= 45.0;
        }
        if fitting_bins_count == 1 {
            // Only one open bin fits: avoid stealing its role unless it's very tight.
            score += 10.0;
        }
    }

    // Late-stream compaction: toward the end, squeeze harder into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step match: ideal placement
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize slack after hypothetically placing next item
            score += slack * 0.35;
            if slack <= 10.0 {
                score -= 25.0; // near-perfect 2-step match
            }
        } else {
            // next item cannot fit in the leftover; leftover is dead space until then
            let orphan = (next_item_size - post_residual) as f64;
            score += orphan * 0.5;
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Compare post_residual against the mean residual across open bins.
    // Leaving this bin far below mean residual creates fragmented dead space.
    let resid_f = post_residual as f64;
    if resid_f < mean_residual - 20.0 {
        score += (mean_residual - resid_f - 20.0) * 0.4;
    } else if resid_f > mean_residual + 20.0 {
        score -= (resid_f - mean_residual - 20.0) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin should be penalized unless the fit
    // into existing bins is terrible. Empty bin has post_residual = capacity - item.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // relax the penalty when many bins are open and mean residual is large
        // (fragmentation suggests consolidation is failing)
        score -= (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // a fresh bin offers good room for the next item too
            score -= 15.0;
        }
        // if the item is huge relative to typical residuals, new bin is fine
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Slight preference to fill earlier bins as the stream progresses (stability).
    score += (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

