        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: scale preference by scarcity
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_score = 55.0;
        // large items early are fine in fresh bins; small items should reuse
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 45.0;
        // late in the stream, avoid opening bins with big residual waste
        new_bin_score += progress * 20.0;
        // many open bins with small residuals -> better to open fresh bin
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 2 {
            new_bin_score -= 25.0;
        }
        if fragmentation < 5.0 {
            new_bin_score += 10.0;
        }
        score += new_bin_score;
