    // Mild global pressure: when many bins are open, prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual coupling: bins far below mean residual are less attractive
    // (keep large residuals for future large items).
    let below_mean = mean_residual - bin_residual as f64;
    if below_mean > 0.0 {
        score += 0.15 * below_mean;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
