    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose residual falls into
    // "small" classes (0..=10) are near-perfectly packed; reward them heavily.
    let post_class = (post_residual / 10).min(10) as f64;
    score += post_class * 3.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residuals that no realistic item (1..=100) can
    // nicely consume are penalized super-linearly. Residuals in 1..=9 are
    // nearly dead; residuals >= 50 remain reusable.
    if post_residual >= 1 && post_residual <= 9 {
        score += 30.0;
    }

    // Modulo logic: residuals divisible by common small item sizes (5, 10, 20)
    // are more likely to be exactly consumed later; reward such harmony.
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 18.0;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty if
            // remainder becomes stranded.
            if post_residual < next_item_size && post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad harmony.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // when few bins are open (spreading load is cheap then).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 + 25.0 * progress;
        // If the item is large, a fresh bin guarantees good future harmony.
        if item_size >= bin_capacity / 2 {
            new_bin_cost -= 20.0;
        }
        // If next item is large too, a fresh bin pairs them well.
        if next_item_size >= bin_capacity / 2 {
            new_bin_cost -= 15.0;
        }
        score = new_bin_cost + post_residual as f64 * 0.1;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..=100 range, but small gaps < 20 are rarely reusable)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 + (20 - post_residual) as f64 * 2.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins would leave large dead
    // space or are scarce. Penalize opening new bins when pressure is low.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is useful.
        if next_item_size > 60 {
            score -= 20.0;
        }
        // If the current item fits poorly elsewhere (large item, tight mean residual),
        // opening a fresh bin is better.
        if item_size as f64 > mean_residual + 10.0 {
            score -= 25.0;
        }
    }

    // Lookahead: prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild open-bin pressure: fewer open bins -> keep packing existing ones.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or nearly matches the next item size (chain placements).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: strong reward
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here afterwards: reward proportional to gap smallness
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space, more so if gap is small
            // (wasted opportunity for a near-chain).
            score += 4.0 * (1.0 - gap / (next_item_size as f64 + 1.0));
        }
    } else {
        // Last item: only tightness matters
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are already
    // "dense"; penalize dumping into them unless fit is very tight.
    let rel = post_residual as f64 - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make empty
    // bin slightly unattractive by default, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 6.0 * progress;
        // If next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 3.0;
        }
    }

    // Penalize leaving large unusable fragments (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Mild preference for filling fewer bins when many are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual weighted more than linear).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Penalize dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits in post-residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // Perfect chain: post residual exactly leaves room for next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost that varies
    // with global state — cheaper to open when open bins are crowded/full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score = bin_capacity as f64 * 0.9
            + crowd * 2.0
            - progress * 15.0
            - if next_item_size > 0 && next_item_size <= bin_capacity { 8.0 } else { 0.0 };
        // If no open bin fits well, opening is more attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer bins with residual close to item (best-fit flavor) modulated by mean residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Slight preference for fuller bins relative to fleet mean.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Time horizon: early on, keep bins open/flexible; late, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap; // normalized dead space after placement
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual), stronger late in the stream.
    let mut score = pr + 60.0 * poly;

    // Lookahead: penalize if next item cannot use this bin's post_residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 12.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            // reward leaving just enough room for the next item
            let slack = (pr - ni) / cap;
            score -= 8.0 * (1.0 - slack).min(1.0) * (0.3 + progress);
        }
    } else {
        // last item: prefer any fit strongly
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else {
        // mild penalty when many alternatives exist
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Compare against mean residual: bins with unusually small residual are precious.
    if pr > mean_residual {
        score += 3.0 * (pr - mean_residual) / cap;
    } else {
        score -= 2.0 * (mean_residual - pr) / cap;
    }

    // New-bin candidate handling: fresh empty bin gets a progress-dependent penalty
    // so it is only chosen when it clearly beats fitting into an open bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "reusable" classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0f64;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0;
            }
        }
        score -= harmony * 3.0;
    } else {
        // Perfect fill: strong reward
        score -= 25.0;
    }

    // Dead-space penalty: leftover too small for the minimum item size.
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0;
        // Extra reward if leftover is an exact multiple of next item size class
        if next_item_size > 0 && pr % next_item_size == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && pr > 0 && pr < next_item_size {
        // leftover cannot host next item: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Integer-division threshold on tightness of the fit
    let tightness = (item_size * 4) / bin_capacity; // 0..=3 classes
    score -= tightness as f64 * 2.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins
    // would create bad dead space; but allow it when many bins are open and
    // this candidate is empty (residual == capacity).
    if bin_residual == bin_capacity {
        score += 15.0
            + mean_residual * 0.05
            + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins below mean residual (more packed) slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are heavily penalized.
    let dead_zone = 12.0;
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit is king
    }

    // Post-residual that still fits the lookahead item is valuable; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Post-residual cannot host the next item: mild penalty scaled by wasted fraction.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 2.0);
    if bin_residual < bin_capacity {
        score -= pressure * 2.0;
    } else {
        // New-bin candidate: penalize opening a new bin unless the fit elsewhere is terrible.
        score += 25.0 + pressure * 3.0;
        // If item nearly fills a fresh bin, opening is fine.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Prefer bins tighter than the mean residual (well-utilized bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    // Reward large fills relative to bin size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus when next item fits exactly into post_residual
        if next_item_size <= post_residual {
            score -= 60.0 - gap * 0.8; // tight chain bonus
        } else {
            // next item cannot fit here; dead space penalty scaled by gap
            score += gap * 0.35;
        }
        // soft coupling: prefer post_residual slightly above next_item_size
        score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.15;
    }

    // Relative to mean residual: bins tighter than average are more valuable
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Penalize leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fit is poor
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64) < 30.0 || (next_item_size > 0 && next_item_size == post_residual);
        score += if good_fit { 500.0 } else { 25.0 - (item_size as f64) * 0.2 };
    }

    // Mild preference for compacting fewer open bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1,
    // so any residual is technically usable, but tiny residuals waste capacity).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(2.5);
        score += 18.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it, otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward;
    // if the next item would fit better elsewhere (post_residual too tight), penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = post_residual as f64 - nx;
            // reward chain fits, prefer leaving just enough room
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to how much we block
            let block = (nx - post_residual as f64) / bin_capacity as f64;
            score += 6.0 * block.min(1.0);
        }
    } else {
        // Last item: closing a bin fully is free win.
        score -= 10.0 * tightness;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let consolidation_pressure = (open_bins_count as f64).ln1p() * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 5.0 * consolidation_pressure;
    } else {
        // New-bin candidate: penalize when open bins already carry lots of slack,
        // reward when open bins are nearly full (opening fresh capacity is good).
        score += 8.0 * (1.0 - mean_residual / bin_capacity as f64);
        score -= 4.0 * consolidation_pressure;
    }

    // Time horizon: late in the stream, be conservative (fill existing bins);
    // early on, allow exploration of new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    // Slight penalty for spreading across too many bins when item is small.
    if item_size <= bin_capacity / 4 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly late in the stream
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            score -= 2.0 * (1.0 - (pr / (nx + pr)) * (pr / (nx + pr)));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty when many bins are open and residual deviates from mean
    let dev = (pr - mean_residual) / cap;
    score += open_bins_count as f64 * 0.05 * dev * dev * cap;

    // New-bin candidate: prefer opening a fresh bin early, discourage late
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits (post==0) heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Fraction of capacity wasted; dead-space penalty grows non-linearly.
        let frac = post / cap;
        score += 18.0 * frac * frac;
        // Small residuals (<=10) are dead space for min item size 1..100 range
        if post_residual <= 10 {
            score += 12.0;
        }
    }

    // Modulo classes: residuals divisible by common item sizes are more reusable.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }
    // Integer division threshold: post_residual >= next_item_size means lookahead fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // exact harmonic match: post_residual / next_item_size small quotient
            let q = post_residual / next_item_size as f64;
            if (q - q.round()).abs() < 1e-9 && q >= 1.0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: slight penalty unless residual tiny
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer only when open bins have small residuals overall.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * mean_residual - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = 5.0;
        }
    }

    // Late stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized. Define "useful" via a dynamic threshold
    // tied to the lookahead item and the stream's typical scale.
    let lookahead_scale = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    let dead_zone = (lookahead_scale * 0.5).clamp(1.0, 40.0);

    if post_residual > 0 && (post_residual as f64) < dead_zone {
        // Dead space: gap too small for the next item to plausibly use.
        score += (dead_zone - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits proportionally: fraction of bin filled.
        let fill = (item_size as f64) / (bin_residual as f64).max(1.0);
        score -= fill * 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // Next item fits but leaves further residue: mild reward scaled by tightness.
        let tight = (next_item_size as f64) / (post_residual as f64).max(1.0);
        score -= tight * 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to gap size.
        score += (post_residual as f64) * 0.15;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it early (few bins) to build a good spread of residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate.
        let pressure = (open_bins_count as f64) * (0.6 + 0.8 * progress);
        score += 30.0 + pressure;
        // If this bin is the last chance, opening a new bin is worse.
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
        // If the next item is large and current residuals are small, a fresh
        // bin may be attractive; soften the penalty.
        if next_item_size > 60 && mean_residual < 40.0 {
            score -= 15.0;
        }
    } else {
        // Reward using existing bins, more so under open-bin pressure.
        score -= 5.0 + (open_bins_count as f64).min(20.0) * 0.5;
        // Last-chance bonus: if this is the only bin that fits, prefer it
        // strongly to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean in a
    // useful way: pick below-mean-residual bins to balance the fleet.
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match within a small tolerance.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 4.0 {
            score -= 200.0 * (5.0 - gap);
        }
        // Penalize leaving residual too small for the next item (dead space),
        // unless it's near zero (bin nearly full is fine).
        if post_residual > 0 && post_residual < next_item_size {
            score += 60.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Mild reward if next item still fits with room to spare.
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // But if no other bin fits (this is the only candidate), the base
        // residual of a new bin (100) is already low relative to tight bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Late in the stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good, amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Wasted opportunity if next item would fit better elsewhere.
            score += 3.0;
        }
        // Exact pairing bonus.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: prefer new bins only when open bins are crowded
    // or mean residual is too small to be useful.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let mean_useful = mean_residual / (bin_capacity as f64);
        // Opening a new bin is cheap early on or when open bins have small residuals.
        let discount = pressure * 0.5 + (1.0 - mean_useful) * 5.0;
        score = bin_capacity as f64 - discount;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 8.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
        }
    }

    // Time horizon: late in the stream, consolidate into fewer bins (avoid opening new ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 18.0 * norm_pr * (1.0 - norm_pr) * progress;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = (cap - pr) / cap;
    score -= 10.0 * tightness * tightness * progress;

    // Last-chance bonus: strongly favor this bin if it is the only one that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits into the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_after = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack_after * slack_after);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty when bin residual is far from mean residual (imbalance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: make it mildly unattractive unless residuals are large
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "small"
    // residue classes are tightly packed; reward those classes.
    let r = post_residual;
    let class_small = (r % 10 == 0) as f64 + (r % 5 == 0) as f64 * 0.5 + (r <= 10) as f64 * 2.0;
    score -= class_small * 3.0;

    // Penalize awkward dead space: leftover that is neither tiny nor large
    // enough to likely fit a future item (odd residues, mid-range).
    let awkward = ((r > 10) && (r < 40) && (r % 2 == 1)) as f64;
    score += awkward * 6.0;

    // Perfect fit reward (exponential decay toward zero leftover).
    if r == 0 {
        score -= 100.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 50.0;
        } else if next_item_size <= r {
            // next item fits but leaves another residue: mild reward scaled
            // by how small the second leftover is.
            let r2 = r - next_item_size;
            score -= (20.0 * (1.0 - r2 as f64 / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - r) as f64 * 0.15;
        }
    }

    // Integer-division thresholds on bin_residual: prefer bins with small
    // residual (best-fit flavor) via tiered buckets.
    let tier = bin_residual / 25; // 0..4
    score += tier as f64 * 4.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin has residual == capacity.
    // Its post_residual = capacity - item_size, typically large; add a fixed
    // opening cost so it only wins when existing fits are poor (large leftovers).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // But if item is large, opening a fresh bin is natural (big items
        // pair poorly with partially filled bins).
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 15.0;
        }
    }

    // Mean residual coupling: when open bins are generally full (small mean
    // residual), opening a new bin becomes more attractive overall.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Perfect refill: post residual exactly matches the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 10.0; // would create a sliver after the next item
    }

    // Open-bin pressure: prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 * 0.6;
    score += pressure;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize it unless current bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.15;
        // Large items relative to capacity justify a fresh bin.
        if item_size as f64 > 0.7 * cap {
            score -= 30.0;
        }
    }

    // Mild stream progression: later in the stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    // Prefer bins tighter than the average residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= 12.0 * (-post_residual as f64 / 8.0).exp();

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead;

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual - next_item_size) as f64 / 20.0;
        } else {
            // Next item won't fit here; slight penalty if we leave awkward space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Base penalty for opening a new bin.
        score += 18.0;
        // If this item leaves a very awkward residual in any bin anyway, soften.
        let tight_elsewhere = fitting_bins_count > 0 && post_residual == 0;
        if tight_elsewhere {
            score += 5.0;
        }
        // Late in the stream, prefer consolidation.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * t;
    }

    // Prefer filling bins that are already low on space (consolidation).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // If bin residual is far below mean residual, this bin is "dirtier" — slight penalty.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Many open bins: encourage closing them out by filling small residuals.
    if open_bins_count > 3 {
        score -= 0.5 * open_bins_count.min(20) as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = pr;

    // Non-linear coupling: quadratic penalty on post_residual modulated by stream progress.
    let x = pr / cap;
    score += 18.0 * x * x * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 12.0 * (1.0 - x).powi(3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fits exist, especially late in stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (pr - nx) / cap;
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates below mean (tighter bins).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 6.0 * dev * (0.5 + progress);

    // Mild preference for filling bins over many open bins.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: how "usable" is the leftover space?
    // Class residuals into buckets by integer division on 100-capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that cannot hold mid-size items are wasteful.
    // Classes: 0 (perfect), 1..=9 tiny, 10..=24 small, 25..=49 medium, 50..=99 large.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual < 25 {
        score += 5.0;  // small, only fits tiny items
    } else if post_residual < 50 {
        score += 0.0;  // medium, moderately reusable
    } else {
        score -= 6.0;  // large residual, keep flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Harmonic match quality: ratio of next item to post residual
            let ratio = next_item_size as f64 / pr;
            score -= 15.0 * ratio;
        } else {
            // next item cannot use this residual: penalize leaving big gaps slightly
            score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual would become a tiny dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Mild penalty so filling existing bins is preferred when fits are decent;
        // removed when open bins are fragmented (high mean residual spread).
        let fragmentation = (mean_residual - pr).abs();
        score += 18.0 - 8.0 * (fragmentation / cap).min(1.0);
        // Late in the stream, prefer consolidation into open bins less strictly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Prefer tighter bins generally: small residual before placement is good use.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Mean residual alignment: bins far from the mean residual are either
    // nearly full (good) or unusually empty; nudge score accordingly.
    score += 0.02 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 9) are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (low slack ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize creating a residual that is small but not tiny: hard to reuse.
    if post_residual >= 10 && post_residual < 25 {
        score += 0.35 * (25 - post_residual) as f64;
    }

    // Lookahead: strongly favor bins that can also host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening yet another bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bins are fragmented
    // (mean residual low relative to item) or open-bin count is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual < item_size as f64 * 1.5) as i32 as f64;
        score += 55.0 + 2.0 * open_bins_count as f64 - 45.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is mandatory
        }
    } else {
        // Slight preference to reuse bins with above-average residual.
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can fit the next item: good, keep slack usable
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.15; // reward closeness of the fit
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover
        let dead = next_item_size as f64 - post_residual as f64;
        score += dead * 0.8;
    }

    // Relative to mean residual: prefer bins with residuals near the mean
    score += (post_residual as f64 - mean_residual).abs() * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing bins exist
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 35.0 };
        score += pressure + open_bins_count as f64 * 0.5;
    }

    // Early in the stream, slightly prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual relative to item size.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // Penalize dead space that nothing else can use (residual < min item size 1 handled
    // via lookahead: if next item can't fit in post_residual, the leftover is likely waste).
    if next_item_size > 0 {
        if next_item_size as f64 > post_residual as f64 {
            // Leftover unusable for the immediate next item: penalize proportionally.
            score += 0.25 * post_residual as f64;
        } else {
            // Next item fits perfectly-ish: strong reward for chaining.
            let chain_fit = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 12.0 * chain_fit;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fit is poor
    // and there is slack in the stream (early steps, few open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 50.0; // large leftover in this bin otherwise
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // New bin is attractive when the item is large and fits badly elsewhere.
        score += 30.0;
        score -= 20.0 * fit_quality;
        if poor_fit {
            score -= 10.0;
        }
        // Late in the stream, consolidation matters more: discourage new bins.
        score += 25.0 * progress;
        // Many open bins already: discourage spreading.
        score += 1.5 * open_bins_count as f64;
    }

    // Global residual context: if this bin's residual is far below the mean,
    // it is a "tight" bin; using it up is good (clears bins).
    let dev = mean_residual - post_residual as f64;
    score -= 0.10 * dev;

    // Mild time-decay pressure: early on, keep flexibility (avoid tiny leftovers);
    // later, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (1.0 - progress); // tiny dead space early is costly
        score -= 5.0 * progress;          // closing bins late is good
    }

    // Prefer bins that are already fairly full.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, weighted by stream progress (later items -> tighter packing)
    let mut score = pr * (1.0 + 0.8 * progress);

    // Non-linear penalty for awkward residuals (dead space that likely stays unused)
    let awkward = norm_pr * (1.0 - norm_pr); // peaks at half-full residuals
    score += 40.0 * awkward * (0.5 + 0.5 * progress);

    // Reward tight fits with smooth exponential coupling
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness.powf(4.0) * (1.0 + progress);

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Penalize opening new bins when open bins exist, more strongly late in stream
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 20.0 * progress;
    }

    // Lookahead coupling: favor residuals that can still host the next item
    if next_item_size > 0 {
        let diff = norm_pr - (next_item_size as f64 / cap);
        // smooth reward when post_residual >= next item, penalize otherwise
        let fit_next = 1.0 / (1.0 + (-diff * 10.0).exp());
        score -= 12.0 * fit_next * (1.0 + progress);
    }

    // Mild preference toward bins below mean residual (consolidate emptier space)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // modulo / integer-division thresholds on post_residual
        if pr % 10 == 0 {
            score -= 12.0; // residual aligns with decile classes
        }
        if pr % 20 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr <= 10 {
            score += 25.0; // tiny residual = dead space
        } else if pr <= 20 {
            score += 10.0;
        }
        // harmonic class via integer division: which "band" of residual
        let band = pr / 10;
        score -= band as f64 * 2.0; // larger usable residual slightly favored
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 40.0; // sets up a perfect fit next step
            } else if gap <= 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
                if gap % 10 == 0 {
                    score -= 5.0;
                }
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it available only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // penalize new bins more when open bins still have room
        score += 20.0 + 40.0 * (1.0 - crowding) + 10.0 * progress;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0; // open bins can't host the next item either
        }
    }

    // Mild tie-break toward consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible
    // future item (min size 1..) are pure waste. Penalize tiny but nonzero
    // post_residuals super-linearly.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0 - (post_residual as f64) * 3.0; // dead gap of 1..10
        } else if post_residual <= 25 {
            score += 10.0; // hard-to-fill zone
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: residual likely becomes dead space.
        score += 15.0;
    }

    // Last chance: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or this
    // item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        // Base new-bin cost: discourage wasteful opening.
        score += 20.0;
        // Pressure from number of open bins: fewer open bins -> cheaper to open one.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large relative to mean residual, new bin is reasonable.
        if (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // Perfect fit for the lookahead item in a fresh bin.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 15.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening new ones.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 25.0 * progress;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing ones.
    score += 0.15 * open_bins_count as f64;

    // Slight preference for bins with residuals below the mean (use up scarce space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score += diff as f64 * 0.9;
        // Exact two-item chain: post_residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // post_residual can still host next item comfortably.
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space relative to next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item leaves a large,
    // reusable residual (full-capacity placements) or few fitting bins exist.
    if bin_residual == bin_capacity {
        let fullness = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - fullness); // penalize opening bins for small items
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin supports the lookahead chain
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
    }

    // Slight preference to fill bins tighter as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * (1.0 + progress);

    // Small crowding tie-breaker: with many open bins, prefer compacting.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect or near-perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Lookahead: reward if the next item fits into the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving a gap that no realistic item (min size 1..) can use,
            // scaled by how much the gap falls short of the next item.
            let gap_miss = (next_item_size - post_residual) as f64;
            score += 0.05 * gap_miss;
        }
        // If next item would fit this bin now but not after placement, mild penalty.
        if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 1 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.02 * consolidation * open_bins_count as f64;
    }

    // New-bin candidate handling: empty bin (residual == capacity) should only win
    // when no open bin offers a decent fit; penalize opening a new bin, more so
    // early in the stream and when many bins are already open.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, opening a bin is less costly (fewer future items to fill it).
        new_bin_penalty *= (1.0 - 0.5 * progress);
        // If next item is large and won't fit anywhere typical, a fresh bin is more useful.
        if next_item_size > 60 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor) via
    // relative tightness term.
    let tightness = (bin_residual - item_size) as f64;
    score += 0.08 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth non-linear shaping
    let prn = pr / cap;
    let mut score = prn * (1.0 + 0.6 * progress) - 0.25 * prn * prn;

    // Dead-space penalty: large residuals that are hard to fill later
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            // lookahead item cannot use this leftover -> dead space
            score += 0.35 * (prn - (nxt / cap)).max(0.0) * (1.0 + progress);
        } else {
            // lookahead fits: reward tight coupling with next item
            let slack_after_next = (pr - nxt) / cap;
            score -= 0.4 * (1.0 - slack_after_next).max(0.0);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 0.8;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap - 0.9 * fill + 0.5 * progress;
        if fitting_bins_count > 1 {
            score += 1.5; // discourage new bin if alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by 10 are
    // "friendly" (future items 10..80 often align), odd/dead residues are bad.
    let pr = post_residual;
    let harmonic = match pr {
        0 => -6.0,
        _ if pr % 10 == 0 => -4.0,
        _ if pr % 5 == 0 => -1.5,
        _ if pr % 2 == 0 => 0.5,
        _ => 2.0, // odd residue: dead-space penalty
    };
    score += harmonic;

    // Perfect fit bonus scaled by stream position (tighter packing late).
    if pr == 0 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 + 5.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or on a harmonic class boundary.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 8.0;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 2.0;
            } else if gap % 5 == 0 {
                score -= 1.0;
            } else {
                score += gap as f64 * 0.25;
            }
        } else {
            // next item cannot use this residual: penalize large wasted space
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins
    // are heavily fragmented (mean residual low) and this fit is poor.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let poor_fit = post_residual as f64 / cap; // = 1 - item/cap for new bin
        if fragmentation < 0.25 && fitting_bins_count >= 1 && poor_fit > 0.6 {
            score += 12.0; // discourage opening new bin when good fits exist
        } else if fragmentation < 0.15 {
            score -= 3.0; // open fresh bins when everything is tight
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score += (open_bins_count as f64) * 0.02;

    // Slight preference for fuller bins (smaller pre-residual usage).
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (or the lookahead item) are "dead".
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill
    } else if post_residual < next_item_size && next_item_size > 0 {
        // gap cannot hold the next item: strong penalty scaled by gap smallness
        let gap_waste = (next_item_size - post_residual) as f64;
        score += gap_waste * 2.5;
    } else if post_residual < 10 {
        // tiny unusable sliver: treat as effectively full
        score -= 50.0;
    } else if post_residual < 20 {
        score += 15.0; // moderately risky gap
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Open-bin pressure: when many bins are open, prefer reusing existing
    // bins over opening new ones. New-bin candidate has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64) * 3.0;
        // but if this bin is the last chance, opening a new bin is fine
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // last-chance bin: strongly favor using it to avoid waste
        score -= 45.0;
    }

    // Prefer bins whose residual is below the mean (denser bins)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Early in the stream, be slightly more willing to open bins;
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 5.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small waste left after that.
    if next_item_size > 0 && next_item_size <= post_residual {
        let two_step_waste = post_residual - next_item_size;
        score -= 25.0 - 0.5 * two_step_waste as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize proportionally to the gap.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Dead space: residual too small for the smallest possible item (1) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    // Prefer bins whose residual is already below mean (tight bins get filled).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream, prefer closing bins tightly (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to capacity
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 50.0;

    // Last-chance bin: strong preference to use it rather than open a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 200.0;
    }

    // Lookahead: penalize if post-residual can't fit next item but another bin could
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0; // bin stays useful for next item
        } else {
            score += 10.0;
        }
        // reward leaving exactly enough room for next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // New-bin candidate handling
    if is_new_bin {
        // Base penalty: prefer reusing open bins when reasonable
        score += 60.0;
        // Penalize more when many bins are open and can fit (fragmentation risk)
        if fitting_bins_count > 0 {
            score += 40.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in stream: opening bins is cheaper (more flexibility later)
        score -= 80.0 * (1.0 - progress);
        // If mean residual across open bins is small, reuse is poor -> new bin ok
        if mean_residual < item_size as f64 * 1.1 {
            score -= 70.0;
        }
        // Few fitting bins and small mean residual: new bin attractive
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // Prefer bins with smaller residuals among fitting bins (best-fit flavor)
        score += (bin_residual as f64 - item_size as f64) * 0.3;
        // Slight bonus for using bins with high mean residual relative to this bin
        if (bin_residual as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins tightly
    score -= 20.0 * progress * (1.0 - tightness);

    // Penalize creating large dead space late in stream
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // small useless leftover is fine, bin nearly closed
    }
    if post_residual >= 10 && post_residual < item_size.min(20) {
        score += 15.0; // awkward gap that likely can't fit future small items well
    }

    // Mild penalty for accumulating too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Base: prefer tight packing (small post_residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.8 * fit * fit);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize wasted space more.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 1.2 * p3) * (mean_residual / cap).clamp(0.0, 2.0);

    // Last-chance bonus: strongly reward using a bin when it's the only fit.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * (1.0 - fit);
    }

    // Lookahead: reward leaving space exactly matching the next item.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score += 0.15 * diff;
        if diff < 1.0 {
            score -= 25.0;
        }
    }

    // Slight preference for filling existing bins when many are open.
    score += 0.05 * open_bins_count as f64 * fit;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 15.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead-zone" classes (1..10) are wasted; big residual classes are reusable.
    let dead = (post_residual > 0 && post_residual < 10) as u32;
    score += dead as f64 * 60.0;

    // Modulo-class coupling: residual divisible into chunks of 10 is valuable
    // (item sizes 10..80 align with decade grid).
    let decade_alignment = (post_residual % 10 == 0) as u32;
    score -= decade_alignment as f64 * 8.0;

    // Perfect fit bonus via integer division: post_residual / item_size tells
    // how many copies of the current item would still fit; fewer = tighter fit.
    if item_size > 0 {
        let copies = post_residual / item_size;
        score += copies as f64 * 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item cannot use this residual at all -> penalize proportional dead space
            score += (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they score badly.
        score += 30.0;
        // Early in stream, opening bins is cheap; late, it's expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // Few open bins -> opening is more attractive.
        score -= (open_bins_count as f64).sqrt() * 4.0;
        // If mean residual across open bins is large, no need for a new bin.
        score += mean_residual * 0.5;
        // Perfect pairing: item + next item exactly fill a fresh bin.
        if item_size + next_item_size == bin_capacity {
            score -= 45.0;
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Harmonic threshold: residuals in [10, 20) are awkward (only tiny items fit).
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }
    // Residuals >= 50 are half-empty bins, quite reusable.
    if post_residual >= 50 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Tight fit reward: the smaller the gap relative to the item, the better.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 40.0 * fit_ratio;

    // Penalize mid-range unusable gaps that few item sizes can fill.
    if post_residual > 0 && post_residual < 35 {
        score += 0.9 * (35.0 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when current bins fit poorly or mean residual is low.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (fit_ratio < 0.6 && mean_residual < item_size as f64 * 1.3);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Slight preference for bins below mean residual (balancing across bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward residuals that exactly match the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        if pr == nxt {
            // Perfect 2-chain: this bin absorbs both items completely.
            score -= 60.0;
        } else if pr > nxt {
            // Next item fits too; reward tightness of the 2-item chain.
            let gap = pr - nxt;
            score -= 25.0 - (gap / bin_capacity as f64) * 20.0;
            // Extra bonus if the leftover after both items is tiny.
            if gap <= 10.0 { score -= 10.0; }
        } else {
            // Post residual cannot host next item -> dead space risk.
            let waste = pr;
            // Penalize more heavily if waste is in the awkward small band.
            if waste < 10.0 {
                score += 5.0; // tiny waste is fine
            } else if waste < 30.0 {
                score += (waste as f64) * 0.8; // awkward dead zone
            } else {
                score += 15.0; // large but reusable later
            }
        }
    } else {
        // Last item: simply prefer fullest packing.
        score -= 20.0;
    }

    // --- Compare against mean residual: prefer bins tighter than average ---
    let pr = post_residual as f64;
    score += (pr - mean_residual) * 0.3;

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if no open bin gives a tight fit.
        let tight_fit = (bin_capacity as f64 - item_size as f64) <= 15.0;
        if next_item_size > 0 && (post_residual as f64) == next_item_size as f64 {
            score -= 30.0; // fresh bin enables a perfect 2-chain
        } else if tight_fit || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            // Discourage spawning bins when decent placements exist.
            score += 20.0 + (open_bins_count as f64) * 0.5;
        }
    }

    // --- Stream progression: early on, be more selective; late, pack greedily ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Slight preference for bins that end up very full (fragmentation control).
    let fill = (bin_capacity as f64 - pr) / bin_capacity as f64;
    score -= fill * fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Penalize large dead space nonlinearly (post_residual is unusable space).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Lookahead: reward if next item fits into post_residual (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward for near-perfect two-item packing.
            let combined = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - (combined - 1.0).abs());
        } else {
            // Next item cannot use the leftover; mild penalty for stranding space.
            score += 5.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fullness).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // slightly); later, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * waste;
    score -= 10.0 * progress * fill_frac;

    // Many open bins: encourage filling them rather than opening more.
    score += 0.5 * open_bins_count as f64 * waste;

    // Slight penalty for very small post residuals that are hard to reuse
    // (dead space below typical minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: fraction of bin filled after placement
    let fill = 1.0 - (post_residual as f64) / cap;
    let tightness = fill * fill; // smooth quadratic coupling

    // Reward tight fits, more aggressively as stream progresses
    score -= tightness * (20.0 + 30.0 * progress);

    // Penalize large dead space non-linearly (cubic in normalized post_residual)
    let dead = (post_residual as f64) / cap;
    score += dead * dead * dead * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        let waste = (post_residual as f64) / cap;
        // Base cost of opening a new bin, reduced when item is large (good fresh-bin fill)
        score += 30.0 - (item_size as f64 / cap) * 25.0;
        // Early stream: new bins are cheap; late stream: prefer consolidation
        score += 10.0 * progress;
        // Penalize opening a new bin when many bins already have slack
        if open_bins_count > 0 {
            score += (mean_residual / cap) * 8.0;
        }
        let _ = waste;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let nd = next_item_size as f64 / cap;
        score -= (1.0 - diff / cap).max(0.0) * nd * 12.0;
        // Penalize leaving residual too small for the next item
        if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += (post_residual as f64) * 0.15;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (prefer homogenized residuals)
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot" of capacity it falls into
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // 0..10 harmonic classes

    // Small residuals are good (tight fit) -> reward
    score -= 30.0 * (1.0 - pr / c);

    // Perfect fit / tiny dead space: strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals in (10, 30) are hard to fill with items >=10
    // unless next item fits; use modulo classes on post_residual
    let m = post_residual % 20;
    if post_residual >= 10 && post_residual <= 30 {
        // can next item land in this class?
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0; // lookahead rescues the dead zone
        } else {
            score += 22.0; // true dead space
        }
        // class penalty: low modulo class = less flexible
        score += (m as f64) * 0.3;
    }

    // Mid-range residuals (30..60): moderately useful
    if post_residual > 30 && post_residual < 60 {
        score -= 6.0;
        if next_item_size > 0 && next_item_size <= post_residual && next_item_size + 10 >= post_residual {
            score -= 12.0; // next item nearly fills this class
        }
    }

    // Large residuals are fine but less urgent; slight penalty for wasting big bins on small items
    if post_residual > 60 && item_size < 30 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // early in stream, fresh bins are cheaper (more future items to co-fill)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // many open bins already: penalize opening another
        score += (open_bins_count as f64) * 2.5;
        // if mean residual is large, prefer existing bins
        if mean_residual > item_size as f64 + 15.0 {
            score += 15.0;
        }
    } else {
        // existing bin with high residual vs mean: prefer balancing? prefer draining low-residual bins
        if (bin_residual as f64) < mean_residual {
            score -= 7.0; // drain the emptiest bins first
        }
        // more competition for this bin (many fitting bins): slight de-prioritization of non-tight fits
        if fitting_bins_count > 2 && post_residual > 25 {
            score += 4.0;
        }
    }

    // Late stream: consolidation matters more, reward tight fits extra
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - pr / c);

    // Harmonic class bonus: residuals that are exact multiples of 10 pair well with typical sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space penalty: small unusable gaps (<10, min item size) are wasted.
    if post_residual < 10 {
        score -= 50.0; // perfect closure reward
    } else if post_residual < 20 {
        // Gap too small for most items: heavy dead-space penalty
        score += 15.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual < 35 {
        // Moderately risky gap
        score += 6.0;
    }

    // Lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty proportional to tightness
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is expensive.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // But if no open bin fits at all, opening is necessary: fitting_bins_count
        // counts only open fitting bins, so if it's 0 the new bin must win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the item leaves a very usable residual in a fresh bin (large leftover
        // for future items), soften the penalty slightly.
        if post_residual >= 60 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with low mean residual (nearly-full bins) to consolidate.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow more freedom.
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, tighten packing (less lookahead value).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Near-match reward: closer post_residual to next_item_size is better
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 25.0 * (-gap / 15.0).exp();
    }

    // Penalize dead space that no plausible item (>=10) can ever use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Penalize large leftover relative to mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Reward tight fits (small waste fraction)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Slight preference for filling existing bins more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Mild penalty when many bins are already open (encourage consolidation)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post_residual naturally favored).
    // Penalize creating dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // dead space below the smallest plausible item (~10) is nearly unusable
        if dead < 10.0 {
            score += 25.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
        // If the next item also fits in the leftover, extra reward
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Perfect chaining: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here; mildly penalize if we're wasting a good bin
        let wasted = post_residual as f64;
        score += 0.05 * wasted;
    }

    // New-bin candidate handling: empty bin should only win when no good
    // existing fit exists. Make the empty bin moderately expensive.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper (build a pool)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    if open_bins_count > 3 {
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
    }

    // Global residual balancing: avoid placing into bins whose residual is far
    // above mean (keeps residual distribution homogeneous for future items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.03 * dev.abs();

    // Mild time-decay of lookahead influence late in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear coupling: dead-space penalty grows quadratically with progress
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);
    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
    // Smooth interaction: post residual vs mean residual divergence
    score += 6.0 * (pr - mean_residual) / cap * (0.5 + 0.5 * progress);
    // Penalize wasting residual that could fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let wasted = (pr - ns).max(0.0);
        score += 5.0 * (wasted / cap) * (1.0 - progress);
        // Reward leaving exactly room for next item
        let gap = (pr - ns).abs();
        score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap) * 0.5;
    }
    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * (1.0 - progress));
    }
    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.8 * open_bins_count as f64 * norm_pr;
    // New-bin candidate: penalize slightly unless open bins would leave huge waste
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space analysis via capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that are too small to hold any plausible item (dead space)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }

    // Reward tight fits, but only if the leftover is still usable
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Harmonic class: post_residual divisible into nice chunks (multiples of 10)
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if next item fits in the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: leftover becomes stranded until another bin closes
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 60.0;
        // cheaper to open a new bin late in the stream? no: opening is always costly,
        // but if current open bins are very full on average, new bin is more reasonable
        score -= 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // small item in fresh bin wastes capacity
        score += 0.4 * item_size as f64;
    }

    // Progress coupling: early in stream, slightly prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    // Mild penalty when bin residual deviates far from mean residual (balance pressure)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, smallest item).
    if post_residual < 10 {
        score += 30.0;
    }

    // Penalize residuals that are too small for the lookahead item but not zero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits (small post_residual) more aggressively.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // last-chance bin gets strong priority
    }

    // New-bin candidate: make it attractive only when open bins would waste badly.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
    }

    // Progress-coupled pressure: as stream advances, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // still host the next item (chained packing), penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: dead-space penalty grows
            // with how much usable space is stranded.
            score += 10.0 + 0.15 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score -= 15.0 * tightness;
    }

    // Compare against mean residual: bins already below average residual
    // are "used up"; prefer filling them rather than fresh large bins.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward strongly unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when no open bin offers a good fit (post_residual very large
    // relative to capacity) or the stream is early with few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: waste of a full capacity slot.
        score += 55.0;
        // Early stream / many items left: fresh bins are cheaper to open.
        score -= 30.0 * (1.0 - progress);
        // If the current item leaves a huge hole in any existing bin,
        // a fresh bin may chain better with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Placing into an existing bin is generally favored; scale the
        // advantage by how much of the bin gets consumed.
        score -= 12.0 * (item_size as f64 / bin_capacity as f64);
        // Penalize leaving tiny unusable slivers (< 10 = min item size).
        if post_residual > 0 && post_residual < 10 {
            score += 18.0;
        }
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space below the minimum item size (assume min ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Residual too small for next item: mild penalty scaled by wasted potential.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty that grows with how well existing bins could fit.
        score += 20.0;
        // If many bins are open with slack, discourage new bins.
        score += 0.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is costlier.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // But if the next item is large and this bin would leave a large residual,
        // opening a fresh bin may be better (pairing logic).
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 12.0;
        }
    } else {
        // Prefer bins with residual closest above the item (classic best fit sharpening).
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * gap;
        // Slight preference for bins with below-average residual (consolidate fullness).
        score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;
    }

    // Early stream: be slightly more exploratory with new bins.
    if step_index < total_items / 10 && is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) + pr_norm * (1.0 - progress) * 0.6;
    score += poly * cap * 0.35;

    // Tight fits rewarded more strongly as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (1.0 + progress) * 8.0;

    // Lookahead: penalize if post-residual can't fit next item but could have
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && bin_residual as f64 >= nx {
            score += 6.0 + 4.0 * progress;
        }
        // Reward leaving exactly the next item's space
        if (pr - nx).abs() < 1.0 {
            score -= 10.0 * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more when many bins are open
    if bin_residual == bin_capacity {
        score += 4.0 + (open_bins_count as f64).powf(0.7) * 2.5 - 5.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins near the mean (balanced usage)
    score -= 1.5 * (-(pr - mean_residual) * (pr - mean_residual) / (cap * cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that remain
    // "usable" for typical item sizes (multiples of small divisors).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -9.0
    } else if pr >= 10 {
        -3.0
    } else {
        12.0 // dead space below 10: strongly penalize
    };
    score += class_bonus;

    // Integer-division threshold: residual bucket by quarters of capacity
    let quarter = (pr * 4) / bin_capacity.max(1);
    score += match quarter {
        0 => -6.0,           // residual <= 25% : well-packed
        1 => 0.0,
        2 => 4.0,
        _ => 8.0,            // large residual left: wasteful placement
    };

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 12.0 + (pr - next_item_size) as f64 * -0.15;
            // penalize if post residual and next item leave a tiny remainder
            let rem = pr - next_item_size;
            if rem > 0 && rem < 10 {
                score += 10.0;
            }
        } else {
            // next item can't use this bin's remainder anyway
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.9;
        if crowded || open_bins_count == 0 {
            score -= 20.0 + 15.0 * progress;
        } else {
            score += 25.0; // prefer existing bins normally
        }
    }

    // Mild preference to equalize residuals toward mean
    score += ((post_residual as f64 - mean_residual).abs()) * 0.08;

    // Late-stream urgency: pack tighter as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with a non-linear "dead zone" penalty.
    // Gaps that are too small to hold even a mid-sized item are dead space.
    let dead_threshold = 25.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Small leftover gap: heavily penalize proportionally to how useless it is.
        let uselessness = (dead_threshold - post_residual as f64) / dead_threshold;
        score += 40.0 * uselessness * uselessness;
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves another gap: mild reward scaled by fit quality.
            let nxt_left = post_residual - next_item_size;
            score -= 15.0 * (1.0 - nxt_left as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a gap that tempts but fails.
            score += 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, favor consolidating into existing bins
    // (penalize opening new bins); when few bins are open, new bins are cheaper.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with number of open bins and stream progress.
        score += 15.0 + open_pressure * 3.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If no open bin fits well (post_residual large relative), soften new-bin cost.
        if post_residual == bin_capacity && fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Placing into an existing bin relieves open-bin pressure: reward it.
        score -= 2.0 * open_pressure.min(10.0);
        // Last-chance bin: if this is the only bin that fits, strongly favor using it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin's post_residual is below the mean residual,
    // we are creating a tighter-than-average bin -> reward; above mean -> penalize.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Waste fraction penalty: penalize proportion of capacity wasted.
    score += 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

