pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible item can fill (items 1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 40 {
        score += 0.10 * (post_residual as f64 - 40.0); // large leftover is reusable, mild penalty
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot fit here; slight penalty proportional to mismatch
            score += 5.0 * ((next_item_size - post_residual) as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in the stream, be conservative (favor future flexibility);
    // late in the stream, pack aggressively (tight fits matter more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;

    // Mean residual coupling: if this bin is below-average full (high residual vs mean),
    // it's a better candidate to receive the item.
    let dev = (bin_residual as f64) - mean_residual;
    score -= 0.08 * dev;

    // Mild penalty for wasting a large bin on a small item.
    score += 0.05 * (item_size as f64).recip() * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr as f64;

    // Smooth polynomial coupling: post_residual value decays in importance
    // as stream progresses; dead space becomes costlier later.
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * 0.5;
    score += poly * cap * 0.3;

    // Penalize post_residual that cannot fit the lookahead item (dead space),
    // smoothly scaled by how close the next item is to fitting.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += gap * gap * cap * (0.5 + progress);
        // Reward bins whose post_residual still fits the next item
        if pr >= nxt && pr < nxt * 2.0 {
            score -= (pr - nxt).min(nxt) as f64 * 0.25;
        }
    }

    // Last-chance bonus: smooth in 1/fitting_bins_count
    if fitting_bins_count > 0 {
        score -= 8.0 / fitting_bins_count as f64;
    }

    // Slight preference against bins far from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Late stream: favor consolidating into few bins
    score += progress * open_bins_count as f64 * 0.05;

    // New-bin candidate: penalize mildly so open bins are preferred unless
    // all fits are poor (their scores will exceed this via poly terms).
    if bin_residual == bin_capacity {
        score += cap * (0.6 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarter
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Penalize residuals that fall in awkward harmonic classes (near quarter boundaries)
    if class == 0 {
        score -= 8.0; // perfectly divisible residual, reusable
    } else if class < 10 {
        score += 6.0; // tiny sliver = dead space
    } else {
        score += (10 - class.min(10)) as f64 * 0.4;
    }

    // Reward when post_residual can exactly fit next item (harmonic coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 10.0 - gap.min(20) as f64 * 0.4;
        if gap == 0 {
            score -= 15.0; // perfect pair
        }
    } else if next_item_size > 0 {
        score += 5.0; // next item can't follow here
    }

    // Integer-division threshold: residual usable by future small items (<= half capacity)
    let usable_units = post_residual / 10;
    score -= usable_units as f64 * 1.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer opening only when fits are tight or stream early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = fitting_bins_count <= 1;
        if tight || post_residual as f64 > mean_residual + 20.0 {
            score -= 9.0 + 10.0 * (1.0 - progress);
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for many open bins with low fill
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..=100) can use
    // are worthless; residual 0 is perfect. Penalize "almost-fitting" gaps hard.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // dead space: gap too small for any item (min size 1 -> none here), but
        // tiny gaps (1..10) are nearly unusable for typical items
        if post_residual < 10 {
            score += 25.0 * (10.0 - post_residual as f64);
        }
        // gap that exactly fits the lookahead item is valuable
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; add mild penalty scaled by open count.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // locked into open bins. Penalize the empty-bin candidate unless the item
    // is large and no good fit exists.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        score += 15.0 + 0.05 * waste;
        if item_size > 70 {
            score -= 10.0; // large items justify a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: new bin mandatory
        }
    } else {
        // reward using existing bins proportionally to locked-in residual
        score -= 0.02 * mean_residual;
    }

    // Late-stream consolidation: as the stream ends, avoid leaving many open bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match lookahead: post_residual can fit next item with little waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: next item cannot use this residual.
        score += 8.0;
    }

    // Tight fit reward relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness * tightness;

    // Penalize residuals far below mean (fragmented bin).
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score = 55.0 + 30.0 * bad_fit - 10.0 * progress;
    }

    // Prefer bins with more open competition (spread load).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize leaving dead space that no typical item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward for near-exact pairing
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is crowded state.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when open bins are already tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        score = 15.0 + 20.0 * pressure - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin preserves room for bigger upcoming item
        }
        return score;
    }

    // Prefer fuller bins overall (residual close to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio;

    // Global balance: slight penalty when bin is far from mean residual (keeps diversity of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time-varying exploration pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    // Discourage fragmenting many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = pr + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits the post residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / cap);
        } else {
            score += 8.0 * (1.0 - pr / cap) * progress;
        }
    }

    // Smooth interaction with mean residual: prefer bins near mean (balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize mildly early, allow late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap * (0.4 + 0.6 * progress) - 30.0 * fragmentation * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small remainder
    // (unusable) is penalized more than residue divisible into common sizes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post_residual > 0 {
        // residues that are multiples of 10 are "reusable" classes
        let class = post_residual % 10;
        let class_penalty = match class {
            0 => -8.0,
            1 | 9 => 6.0,
            2 | 8 => 4.0,
            3 | 7 => 2.5,
            _ => 1.0,
        };
        score += class_penalty;
        // small dead space (< 10) is pure waste
        if post_residual < 10 {
            score += 5.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 15.0;
    }

    // Integer division thresholds: fraction of capacity consumed
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.75 { score -= 4.0; }
    if fill > 0.9 { score -= 6.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // harmonic compatibility: post_residual % next_item_size small
            let r = post_residual % next_item_size.max(1);
            score -= (10 - (r as f64 * 0.5)).max(0.0);
        } else {
            // next item won't fit here: mild penalty for tight fits
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if
    // current item is large relative to capacity and no good fit exists
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * cap;
        let poor_fits = fitting_bins_count == 0 || mean_residual < item_size as f64 * 1.1;
        if large_item && poor_fits {
            score -= 6.0;
        } else {
            score += 10.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post / cap);

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly worthless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // tiny unusable slivers
        } else if post_residual <= 20 {
            score += 8.0; // hard-to-fill zone
        } else {
            // larger residuals are reusable; mild reward scaled by usability
            score -= (post_residual.min(50) as f64) * 0.15;
        }
    } else {
        score -= 40.0; // perfect fit: strongly favored
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += open_bins_count as f64 * 1.5;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 100.0);
        } else if post_residual > 0 {
            score += 6.0; // next item can't use this bin's remainder
        }
    }

    // New-bin candidate: only attractive when current bins would leave bad
    // dead space and the next item is small enough to join this item later.
    if bin_residual == bin_capacity {
        score = 30.0
            + (mean_residual - post_residual as f64).max(0.0) * 0.5
            - if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 10.0 } else { 0.0 };
        // early in the stream, opening fresh bins is cheaper
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff < 5.0 {
            score -= 20.0; // near-perfect chaining
        } else {
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual unusable by next item: penalize dead space, scaled by how dead.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * dead * dead;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (wasteful use of a roomy bin)
    // unless it's a new-bin candidate.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.05 * dev;
        }
    } else {
        // New-bin candidate: base cost of opening a bin; relax late in stream
        // or when current bin fits poorly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_cost = 30.0 - 10.0 * progress;
        // If the item would leave a large residual in any bin, new bin is attractive.
        if post_residual == 0 {
            new_cost += 100.0; // never open new bin for a perfect fit
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_cost += 10.0; // keep existing bin for chaining
        }
        score += new_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (wasted capacity).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward;
    // if next item cannot fit post-residual, penalize leaving awkward gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, pack aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * t * (100.0 - post_residual as f64) / 100.0;

    // Global state: many open bins with high mean residual -> prefer reusing bins,
    // discourage opening new ones.
    score += 0.08 * (open_bins_count as f64 - mean_residual / 10.0);

    // New-bin candidate: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 22.0 * pressure
            + 0.5 * open_bins_count as f64
            + (1.0 - t) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Stream-progress coupling: later in stream, penalize residual more strongly (consolidate)
    let progress_coupling = post * (0.8 * progress + 0.6 * progress * progress);
    score += progress_coupling;

    // Reward near-perfect fits more aggressively as stream progresses
    let perfect_bonus = (1.0 - norm_post).powf(3.0) * (6.0 + 8.0 * progress);
    score -= perfect_bonus;

    // Dead-space penalty: residual too small for typical items (below min item size 1..100 -> use item_size context)
    let dead_threshold = item_size.max(10) as f64 * 0.5;
    if post < dead_threshold {
        score += (dead_threshold - post) * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 6.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= (1.0 - gap / cap) * (4.0 + 5.0 * progress);
        } else {
            score += (nxt - post) / cap * 3.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual when many bins open (balance)
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 4.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (10,20,25,50) are reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is best
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 20 == 0 {
        -7.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr < 10 {
        15.0 // tiny dead space
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: leftover below the minimum plausible item size is wasted.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Penalize post_residual that cannot fit the lookahead item if some other bin could.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // This bin can also serve the next item: reward chain placement.
            score -= 4.0 + (next_item_size as f64 / cap) * 6.0;
        } else {
            score += 3.0;
        }
        // Harmonic coupling: post_residual exactly matches next item modulo classes.
        if pr == next_item_size {
            score -= 6.0;
        }
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty for wasting a fresh bin on a poor packing opportunity.
        score += 25.0 - 10.0 * progress;
        // If item is large, a fresh bin is more attractive (less fragmentation risk).
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
        // If existing bins are fragmented (low mean residual relative to item), new bin ok.
        if mean_residual < item_size as f64 * 1.1 {
            score -= 8.0;
        }
        // With many open bins, prefer consolidating rather than opening more.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Prefer tighter fits generally: relative fill ratio reward.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 5.0;

    // Mild penalty for leaving residual far from harmonic classes (odd fragments).
    if pr > 0 && pr % 10 != 0 && pr % 25 != 0 && pr % 20 != 0 && pr % 50 != 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: small unusable gaps (below min item size 10)
    // are wasted; penalize heavily proportional to how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Medium gaps: mildly penalize, they may still fit small future items.
        score += 5.0;
    }

    // Prefer bins whose residual matches the next item's needs (lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.5;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (handled implicitly since new bin has max post_residual), but add explicit
    // pressure against scattering residual across many bins.
    score += open_bins_count as f64 * 0.3 * (mean_residual / bin_capacity as f64);

    // Tightness preference: favor bins that were already tight before placement.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Early in stream, be slightly more willing to open bins for big items;
    // later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size > 50 && progress < 0.2 {
        score += 0.0; // neutral
    } else if item_size > 50 {
        score -= 5.0; // keep big items together late
    }

    // New-bin candidate: it has bin_residual == bin_capacity; make it only
    // attractive when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 15.0; // mild default penalty; dead-space penalties above can override
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - slack / 100.0); // good lookahead fit, tighter is better
        } else {
            // next item cannot use this residual: penalize proportional to wasted potential
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below the mean creates fragmented small leftovers.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post residual would be tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
        if pr < 10.0 {
            score += 150.0; // but avoid leaving near-useless slivers
        }
    }

    // New-bin candidate: make it moderately attractive only when this bin would
    // leave large dead space relative to the item and next item.
    if bin_residual == bin_capacity {
        score = 100.0 + item_size as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 50.0; // fresh bin can serve the next item well
        }
        // late in the stream, prefer packing into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
    }

    // Mild penalty for very small residuals that are hard to fill later.
    if pr > 0.0 && pr < 10.0 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with mild waste penalty for large dead space
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 12.0;
    } else {
        score -= 25.0; // perfect fill reward
    }

    // Lookahead: penalize if next item fits better elsewhere / reward if this bin's
    // post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // chain placement possible
            let slack = (post_residual - next_item_size) as f64;
            score += slack / bin_capacity as f64 * 4.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin now but not after placement -> mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh bin gets base competitiveness but should
    // only win when existing fits are poor (large post_residual on open bins)
    if bin_residual == bin_capacity {
        score = 8.0 + post_residual as f64;
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
        // many open bins -> discourage adding another
        score += open_bins_count as f64 * 0.8;
        // if next item is large, a fresh bin is attractive
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Global residual coupling: prefer bins below mean residual (tighter bins first)
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Slight preference to fill bins with small residuals completely
    if bin_residual <= item_size + 5 && bin_residual >= item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear penalty on mid-range dead space
    let mut score = pr as f64;
    score += 20.0 * norm_pr * (1.0 - norm_pr) * (1.0 - 2.0 * progress).abs();

    // Smooth polynomial coupling of progress with residual fill
    let fill = 1.0 - norm_pr;
    score -= 15.0 * fill * fill * (0.5 + progress);

    // Tight fit reward amplified late in stream
    let tight = 1.0 - norm_pr;
    score -= 10.0 * tight * tight * tight * (0.3 + 0.7 * progress);

    // Penalize leaving residual that fits next item awkwardly (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (norm_pr - nx).abs();
        score += 12.0 * (1.0 - gap) * gap * (1.0 - progress);
    } else {
        score -= 5.0 * norm_pr;
    }

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual slightly (smooth)
    score += 3.0 * (norm_pr - mean_residual / cap);

    // Mild new-bin penalty scaled by open bins and progress
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let pr = post_residual as f64;
    let class = (pr / 10.0).floor(); // integer division-like threshold on post_residual
    score += class * 0.5;

    // Perfect fit reward: post residual in small harmonic classes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize residuals that no plausible item (1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space class
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // next item fits; prefer leaving room proportional to waste after next placement
            let after = (post_residual - next_item_size) as f64;
            score += after * 0.3;
            // harmonic class of leftover after the lookahead pair
            let cls2 = ((after / 20.0).floor()) * 2.0;
            score += cls2;
        } else {
            // next item won't fit here; mild penalty scaled by overshoot class
            let over = (nx - pr).max(0.0);
            score += (over / 25.0).floor() * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current bin is crowded.
    if bin_residual == bin_capacity {
        // New bin baseline: prefer it when open bins are fragmented (high mean residual)
        // or few bins fit the item.
        score = cap * 0.55;
        score -= mean_residual * 0.8;
        score += (fitting_bins_count as f64) * 6.0;
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 {
            score -= 15.0; // big next item: fresh bin gives clean space
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        score += (open_bins_count as f64) * 1.5;
    } else {
        // Prefer fuller bins: reward small residual relative to capacity fraction.
        let fill_frac = (bin_residual as f64) / cap;
        score -= fill_frac * 25.0;

        // Modulo-style class of bin_residual: bins whose residual is in "nice" classes
        let rmod = bin_residual % 25;
        if rmod == 0 {
            score -= 8.0;
        }
    }

    // Mild pressure toward compacting many open bins.
    score += (open_bins_count as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (items >= 1, but practically small gaps < ~10 are dead)
    // are heavily penalized; tiny-but-nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // unusable sliver: dead space forever
            score += 40.0 + (10 - post_residual) as f64 * 3.0;
        } else if post_residual < 20 {
            // only usable by the smallest items: partial dead space
            score += 15.0;
        }
    } else {
        // perfect fill: reward strongly
        score -= 60.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; with few open bins, a fresh empty bin is acceptable.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as open bins accumulate
        score += 10.0 + 8.0 * open_pressure;
        // but if the item is huge relative to mean residual, a new bin
        // may be the only clean option
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 12.0;
        }
    } else {
        // existing bin: reward slightly more when many bins are open
        score -= 4.0 * open_pressure;
    }

    // Lookahead (k=2): favor placements whose post_residual can host the
    // next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty scaled by waste
            score += 5.0;
        }
    }

    // Late in the stream, be more conservative with new bins (fewer future
    // items to justify them); early on, allow more exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins whose residual is
    // close to the item (minimizes leftover deviation).
    score += 0.15 * (bin_residual as f64 - item_size as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect 2-step match: next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post-residual: mild reward scaled by tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * slack;
    }
    // Dead space: next item cannot use the leftover.
    else if post_residual > 0 {
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare against mean residual: bins with unusually small residual are precious.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: prefer keeping tight fits in existing bins,
    // but allow opening a new bin when the fit would leave large unusable waste.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score = bin_capacity as f64 + 10.0;
        if post_residual > 50 {
            // Opening a bin for a small item leaves lots of usable space; encourage it
            // when existing bins would be badly fragmented.
            score -= 15.0 + 0.3 * post_residual as f64;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild late-stream tightening: waste matters more as the stream progresses.
    score += 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
        // Perfect chain: item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it's early in the
    // stream or the fit into existing bins is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        let mut new_bin_penalty = 30.0 + 40.0 * progress;
        if poor_fit {
            new_bin_penalty *= 0.4;
        }
        if open_bins_count == 0 {
            new_bin_penalty = -100.0; // must open
        }
        score += new_bin_penalty;
    }

    // Mild preference for filling bins that are already mostly full relative
    // to the fleet average residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference to consolidate into fewer bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    let mut score = pr * (1.0 + 0.6 * progress) - 0.35 * cap * pr2 * (0.5 + progress) + 0.15 * cap * pr3;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr).max(0.0);
        let fit_next = (pr >= n) as i32 as f64;
        score += 0.5 * gap * (0.5 + progress);
        score -= 0.8 * fit_next * n * (1.0 - progress);
    }

    // Reward tight fits; last-chance bin bonus.
    let tightness = 1.0 - pr_norm;
    score -= 4.0 * tightness * (1.0 + 0.5 * progress);
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating into few bins.
    score += 0.05 * open_bins_count as f64 * pr_norm;
    score -= 0.3 * (mean_residual - pr) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: leave zero dead space
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead (k=2): reward if the next item also fits in the leftover space
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus, stronger the tighter the chained fit
            score -= 6.0 + (next_item_size as f64) * 0.35;
        } else {
            // leftover won't hold the next item: mild dead-space penalty
            score += 4.0;
        }
    }

    // Harmonic class logic: integer-division thresholds on post_residual.
    // Classes of width 10 (residual buckets), penalizing mid-size leftovers
    // that are neither tight nor reusable.
    let class = post_residual / 10;
    score += match class {
        0 => 0.0,
        1 => 1.5,
        2 => 3.0,
        3 => 4.5,
        4 => 5.5,
        5 => 6.0,
        _ => 6.5,
    };

    // Modulo coupling: intra-class fine structure on post_residual and next_item_size
    score += (post_residual % 10) as f64 * 0.12;
    if next_item_size > 0 {
        score += ((post_residual + next_item_size) % 7) as f64 * 0.2;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a costly new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // New-bin candidate handling
    if is_new_bin {
        // base post_residual is already large; add a modest opening cost
        score += 5.0;
        if open_bins_count == 0 {
            // must open the first bin
            score -= 30.0;
        }
        // early in the stream, opening bins is cheap and flexible
        if progress < 0.25 {
            score -= 6.0;
        }
        // if the next item is large, a fresh bin with big residual is valuable
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0;
        }
        // late in the stream, avoid fragmentation into new bins
        if progress > 0.75 {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose resulting residual sits
    // below the open-bin average (consolidating space)
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 {
        let usable_next = post_residual >= next_item_size && next_item_size > 0;
        let usable_avg = post_residual as f64 >= 0.5 * mean_residual.max(1.0);
        if !usable_next && !usable_avg {
            // Gap likely wasted forever: heavy penalty scaled by gap smallness.
            score += 30.0 + 0.5 * (post_residual as f64);
        } else if !usable_next {
            score += 10.0;
        }
    } else {
        // Perfect closure is ideal.
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.1 * post_residual as f64;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly via its large residual,
    // but also add consolidation pressure).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = bin_capacity as f64 * 0.6 + 8.0 * open_bins_count as f64;
        // If no other bin fits well and item is large, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight bonus for placing into already-open bins when many are open.
        score -= 0.05 * open_bins_count as f64;
    }

    // Early-stream mild preference for keeping residuals balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.02 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_fit_gap / bin_capacity as f64);
        // Perfect 2-step closure: post_residual == next_item_size
        if next_fit_gap == 0.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use: penalize.
        score += 15.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Compare against mean residual: prefer bins whose post_residual is near mean (balance).
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so we only open a new bin when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.3 * open_bins_count as f64;
        // Allow opening a new bin if the item is large and would leave big dead space elsewhere.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
    }

    // Early in stream, be slightly more willing to keep bins tight / open new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially fragmented dead space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny useless sliver
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 20.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; leaving a medium hole is worse.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are not opened frivolously.
        score += 25.0;
        // More open bins with slack => discourage opening another.
        score += 0.5 * open_bins_count as f64;
        // But if mean residual is high (bins are fragmented), new bin is more attractive.
        score -= 0.3 * mean_residual;
        // Early in stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    } else {
        // Prefer fuller bins among open ones (best-fit bias beyond post_residual).
        let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_frac;
    }

    // Mild global pressure: when many bins are open, consolidate into existing ones.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post residual, with smooth non-linear shaping.
    let mut score = 60.0 * x - 25.0 * x * x + 15.0 * x * x * x;

    // Stream progress coupling: later in the stream, waste is more costly.
    score += 40.0 * t * x * x;

    // Dead-space penalty: residual too small for any plausible future item.
    score += 20.0 * (1.0 - x) * (1.0 - x) * (x > 0.0 as f64) as i32 as f64;

    // Lookahead: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = (pr - next_item_size as f64) / cap;
        score += 30.0 * fits.max(-1.0) * (1.0 - t);
        score -= 15.0 * (1.0 - nx).min(1.0) * (1.0 - x);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter packs).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev;

    // New-bin candidate: penalize opening bins, more so early with few bins.
    if bin_residual == bin_capacity {
        score += 55.0 + 30.0 * (1.0 - t);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: dead-space classes via integer division.
    // Residuals < 10 are nearly unusable (min item size 1, but tiny slivers waste capacity).
    if post_residual < 10 {
        score += 15.0; // penalize creating slivers
    } else if post_residual < 25 {
        score += 5.0;
    } else {
        // Larger residuals are more reusable; mild reward proportional to class width
        score -= (post_residual / 25) as f64 * 3.0;
    }

    // Coupling with lookahead: penalize residuals that JUST miss fitting the next item
    // (wasted opportunity), reward residuals that comfortably fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 4.0 + (slack as f64).sqrt() * 2.0;
        } else {
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 10.0; // painful near-miss
            } else {
                score += (miss as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is the only choice.
            score -= 500.0;
        } else {
            // Prefer compacting into open bins; penalty grows with stream progress
            // and with how many alternatives exist.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 25.0 + 20.0 * progress + 3.0 * (fitting_bins_count as f64);
            // If mean residual is large, definitely reuse bins.
            if mean_residual > item_size as f64 {
                score += 10.0;
            }
        }
    } else {
        // Reward bins whose residual deviates favorably from the mean (tighter bins first).
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
        // Mild bonus for keeping bin count low when many bins are open.
        if open_bins_count > 8 {
            score -= 2.0;
        }
    }

    // Modulo harmonic nudge: residuals that are multiples of common item classes
    // (10/20/25) are statistically more reusable.
    if post_residual % 10 == 0 || post_residual % 25 == 0 {
        score -= 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps (< 10,
    // and especially < next item size) that can never be filled.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap);
        } else if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
            // Gap can't fit the lookahead item: it's dead space for k=2 horizon.
            score += 0.8 * ((next_item_size as f64) - gap);
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual is close to the item (tight fit ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Lookahead synergy: if the leftover gap exactly accommodates next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation; but relieve pressure on last-chance bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    if fitting_bins_count == 1 {
        score -= 15.0; // last chance: strongly prefer using this bin
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: brand-new empty bin has large post_residual;
    // add extra penalty so it's only chosen when no open bin fits well,
    // but relax it late in the stream or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0 - 0.25 * open_bins_count as f64 - 20.0 * progress;
        score += new_bin_penalty.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (waste = 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how snugly
            score -= 0.5 * (next_item_size as f64) / (post_residual as f64 + 1.0) * 50.0;
        } else {
            // next item does NOT fit: penalize leaving dead space that blocks it
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score -= 30.0; // small dead space is fine
            } else {
                score += 0.3 * gap;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Early stream: encourage consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 20.0 * (open_bins_count as f64).recip().max(0.0);

    // Penalize new-bin opening unless current fit is terrible
    if bin_residual == bin_capacity {
        // new bin candidate: base cost, discounted when item is large or fit elsewhere is bad
        score += 120.0;
        if item_size > 70 {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Penalize large unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // tiny residual is nearly a perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 30.0 + 0.5 * (slack_after_next as f64).min(50.0);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that blocks the next item badly
        score += 0.3 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the aggregate residual of open bins;
        // penalize more when many open bins have plenty of room.
        let waste = mean_residual.max(0.0);
        score += 40.0 + 0.8 * waste + 2.0 * open_bins_count as f64;
        // But if the item is huge and fits only tightly elsewhere, new bin is fine
        if item_size >= bin_capacity * 9 / 10 {
            score -= 60.0;
        }
        // Early in stream, opening bins is cheaper (builds diversity)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Mild penalty for large leftover dead space relative to smallest useful item (10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling: reward small post_residual non-linearly.
    let norm_pr = pr / cap; // 0..1
    score -= 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize large dead space with cubic term, stronger late in stream.
    score += 12.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - leftover / cap) * (1.0 - leftover / cap);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap) * (over / cap);
        }
    }

    // New-bin candidate: only attractive when no good existing fit exists.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (post_residual as f64) < 0.5 * cap;
        if tight_exists {
            score += 40.0 + 25.0 * progress;
        } else {
            score -= 8.0 * (1.0 - progress);
        }
        score += 0.5 * open_bins_count as f64;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean.
    let dev = (pr - mean_residual).abs();
    score += 2.0 * (dev / cap);

    // Tiny deterministic tie-break on residual to stabilize choices.
    score += 0.01 * (pr % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left over

    // Class boundaries via integer division thresholds (harmonic bins of 1/8 capacity).
    let class = post_residual / 12; // 0..8 harmonic class of leftover
    let class_penalty = match class {
        0 => -6.0,   // near-perfect fit: excellent closure
        1 => -4.0,   // small leftover, still useful for tiny items
        2 => -2.0,
        3 => 0.0,
        4 => 1.5,    // mid leftover: awkward zone
        5 => 0.5,
        6 => -1.0,   // ~half bin: still versatile
        7 => 1.0,
        _ => 2.5,    // large leftover wasted on a small item
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: favor residuals that are "harmonic"
    // with common item sizes (multiples of 10 and 20).
    let m10 = post_residual % 10;
    let m20 = post_residual % 20;
    if m10 == 0 {
        score -= 2.0; // residual aligns with decade-sized items
    } else if m20 <= 5 || m20 >= 15 {
        score += 1.0; // misaligned residual
    }

    // Lookahead: next item fits exactly into post_residual -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight lookahead fits, penalize large slack
            score -= 3.0 * (1.0 - slack / cap);
            // harmonic match: next item multiple of 10 aligning with residual class
            if next_item_size % 10 == 0 && m10 == 0 {
                score -= 1.5;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: only open a new bin when current open bins
    // are mostly full or the item is huge and fits nowhere tightly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64) / (mean_residual / cap + 1.0);
        // penalize new bins mildly; big penalty if many open bins with room
        score += 5.0 + open_pressure * 0.5 - 2.0 * progress;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 10.0; // must open a bin for a big item
        }
        if mean_residual < item_size as f64 {
            score -= 6.0; // no open bin can realistically hold it
        }
    }

    // Waste penalty: creating dead space below the minimum item size is pure loss.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if no plausible future item (>=1) can use it,
    // and practically dead if it's below the typical small-item size.
    if post_residual > 0 {
        // gap smaller than 10 is nearly unusable -> strong penalty
        if post_residual < 10 {
            score += 25.0 + 2.5 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            score += 6.0 + 0.8 * (20 - post_residual) as f64;
        } else {
            // mild quadratic penalty on larger gaps
            score += 0.02 * post_residual as f64 * post_residual as f64 / 10.0;
        }
    } else {
        // perfect fit: reward strongly
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item_size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: penalize opening new bins when many bins are open,
    // but also discourage over-fragmenting across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (18.0 + 10.0 * open_bins_count as f64 * (0.3 + 0.4 * progress));

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // post_residual can't hold next item: mild penalty proportional to gap
            score += 3.0 * ((next_item_size - post_residual) as f64 / 20.0);
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps balance)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Fragmentation guard: discourage leaving many bins with tiny residuals
    if bin_residual < 15 && new_bin == 0.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual closely matches item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness);

    // Aggressive 2-step lookahead: reward bins where post_residual exactly
    // accommodates the next item, penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let deficit = (next_item_size - post_residual) as f64;
            score += 15.0 * (deficit / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (denser packing).
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize large unusable post-residual (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Early in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when necessary.
        score += 20.0;
        if next_item_size > 0 && post_residual == bin_capacity {
            // A fresh bin perfectly fits both current and next item later.
            if item_size + next_item_size <= bin_capacity {
                score -= 45.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post_residual dominates).
    score *= 1.0 + (post_residual as f64) / (bin_capacity as f64) * 0.5;

    // Penalize creating dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0.0 && pr < nxt {
            // dead space blocks the next item
            score += 12.0 * (1.0 - pr / nxt);
        } else if pr >= nxt && pr - nxt < 10.0 {
            // near-perfect two-item chaining: reward
            score -= 6.0;
        }
        // If lookahead fits exactly in post_residual, big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.4 {
            score -= 10.0 + 8.0 * fit_ratio;
        }
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor or none exist.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64) > bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 || poor_fit {
            score -= 14.0 - 4.0 * progress; // early stream: open bins more freely
        } else {
            score += 20.0; // discourage wasting a fresh bin on a mediocre alternative
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into fuller bins to avoid bin sprawl.
    if open_bins_count > 2 {
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if fullness > avg_fullness {
            score -= 3.0 * (fullness - avg_fullness) * (open_bins_count as f64).ln();
        } else {
            score += 2.0 * (avg_fullness - fullness);
        }
    }

    // Late in the stream: be greedier about tight fits, penalize any waste more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling: waste penalized more strongly as stream progresses
    let waste_penalty = norm_post * norm_post * (1.0 + 3.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Tight fits rewarded, smoothly
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (item_size as f64) * 0.4;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Prefer bins below mean residual (keep big residual bins for big items)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0 - dev * 5.0;

    // Lookahead coupling: reward leaving space close to next item size
    if next_item_size > 0 {
        let gap = (post as f64 - next_item_size as f64).abs();
        score += (gap / cap) * (gap / cap) * 25.0;
        if post >= next_item_size as u32 {
            score -= 8.0;
        }
    }

    // Mild pressure to reuse open bins when many are open
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: make it moderately attractive only when progress is early
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover falls into small
    // modulo classes are more likely reusable by future small items.
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -6.0,          // perfectly divisible leftover: attractive for many sizes
        1 | 2 | 3 => -3.0,  // tiny leftover, near-perfect fill
        8 | 9 => -1.5,      // slightly ragged but small
        4 | 5 | 6 => 1.0,   // mid-range dead space risk
        _ => 2.5,           // 7: awkward gap
    };
    score += class_penalty;

    // Integer-division threshold: leftover that can still host the next item
    // is valuable; leftover that cannot is dead weight.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward proportional to how well the next item nests here
            let nest = (pr - next_item_size) as f64;
            score -= 4.0 * (1.0 - nest / cap);
        } else {
            score += 3.0 * (next_item_size - pr) as f64 / cap;
        }
    }

    // Fractional capacity coupling: reward high fill ratio quadratically.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 10.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (filling emptier bins first keeps
    // tight bins available for tight items).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.1;

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 100.0 } else { bin_capacity as f64 };
    let before = bin_residual as f64;
    let after = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let mean_res = if mean_residual.is_finite() { mean_residual.max(0.0) } else { 0.0 };
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new = bin_residual == bin_capacity;

    // Best-fit base, with a convex penalty against large leftover gaps.
    let mut score = after + 0.16 * after * after / cap;

    // Closing a bin exactly is highly desirable.
    if post_residual == 0 {
        score -= 30.0 + 12.0 * (1.0 - progress);
    }

    // Residual in other open bins, excluding the candidate bin.
    let other_mean = if !is_new && open_bins_count > 1 {
        ((mean_res * open - before) / (open - 1.0)).max(0.0)
    } else {
        0.0
    };

    let preserve_any = next > 0.0 && mean_res + 0.5 >= next;
    let preserve_other = next > 0.0 && other_mean + 0.5 >= next;

    let mut dead_penalty = 0.0;
    let mut future_bonus = 0.0;

    if next > 0.0 && post_residual > 0 {
        if after < next {
            // The leftover cannot hold the lookahead item: strict dead-space penalty.
            let severity = (1.0 - after / next).clamp(0.0, 1.0);
            dead_penalty = 40.0
                + 70.0 * severity * severity
                + 8.0 * severity
                + 0.15 * open * severity;

            // If another open bin can still absorb the next item, the dead gap is less harmful.
            if is_new {
                if preserve_any {
                    dead_penalty *= 0.25;
                }
            } else if preserve_other {
                dead_penalty *= 0.45;
            }
        } else {
            // Reward leaving enough room for the next item, especially an exact next fit.
            future_bonus = -(5.0 + 0.05 * next);
            if (after - next).abs() < 0.5 {
                future_bonus -= 10.0;
            }
        }
    }

    // Small absolute gaps are weak capacity and are penalized even without lookahead.
    if post_residual > 0 {
        let tiny_cap = (0.08 * cap).max(1.0);
        if after < tiny_cap {
            let t = 1.0 - after / tiny_cap;
            dead_penalty += 2.0 + 5.0 * t * t;
        }
    }

    score += dead_penalty + future_bonus;

    // Favor tight placements relative to the current open-bin population.
    if !is_new {
        let tightness = (mean_res - after).clamp(0.0, cap);
        score -= 0.04 * tightness;
    }

    let open_pressure = 2.0 + 2.2 * (open + 1.0).sqrt() + 0.12 * open;

    if is_new {
        let extra_fitting = if fitting_bins_count > 1 {
            (fitting_bins_count - 1).min(5) as f64
        } else {
            0.0
        };
        let fitting_penalty = if fitting_bins_count > 0 {
            24.0 + 8.0 * extra_fitting
        } else {
            0.0
        };

        // Opening a new bin is acceptable when it preserves enough existing slack for next_item.
        let preservation_bonus = if preserve_any {
            let exact_preserve = if (mean_res - next).abs() < 0.5 { 8.0 } else { 0.0 };
            18.0 + 0.45 * next + exact_preserve
        } else {
            0.0
        };

        score += 26.0
            + open_pressure
            + 0.05 * mean_res
            + 0.03 * item
            + fitting_penalty
            - preservation_bonus;
    } else {
        // Pressure to consolidate into already-open bins.
        score -= 0.8 + 0.08 * open;

        // A last-chance open bin is valuable if it still leaves a usable or exact fill.
        if fitting_bins_count == 1 {
            let future_ok = next == 0.0 || post_residual == 0 || after >= next;
            if future_ok {
                score -= 10.0 + 4.0 * (1.0 - progress);
            } else {
                score -= 1.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item exactly fills the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 100.0;
        } else {
            // next item won't fit here: penalize large dead space
            score += (post_residual as f64 - (next_item_size as f64)) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that can never fit a typical future item:
    // dead space = post_residual if smaller than the minimum plausible item (1..100 unknown),
    // approximate with lookahead: if next item can't fit in the post residual, penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (post_residual as f64);
    }
    // Reward bins that can also host the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins where competition is low but not zero.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Pull toward the mean residual: prefer bins close to the average fill state
    // to keep residual distribution balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in the stream, be more conservative (favor new bins less),
    // late in the stream, pack aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    // New-bin candidate handling: empty bin gets base cost plus a dynamic penalty
    // that shrinks as the stream progresses or when few bins fit the item.
    if bin_residual == bin_capacity {
        let open_penalty = 18.0 * (1.0 - progress);
        let scarcity = if fitting_bins_count <= 1 { 8.0 } else { 0.0 };
        score += open_penalty + scarcity;
    }

    // Slight bonus for large items consuming big residuals now (large items first logic).
    score -= 0.05 * item_size as f64;

    // Mild penalty for accumulating many open bins (encourages consolidation).
    score += 0.02 * open_bins_count as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space is exponentially worse when small but nonzero
    if post > 0.0 {
        let norm = post / cap;
        score += 12.0 * norm * (1.0 - norm) * (1.0 - norm);
    }

    // Perfect-fit reward (quadratic coupling of post_residual toward zero)
    score -= 20.0 * (1.0 - post / cap).powi(3) * (item_size as f64 / cap);

    // Lookahead coupling: reward leaving room close to next item size (smooth quadratic)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        score -= 8.0 * (-gap * gap / (cap * cap * 0.25));
    }

    // Late-stream tightness: prefer filling bins more as stream progresses
    let fill = 1.0 - post / cap;
    score -= progress * 15.0 * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.35 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: favor bins below-average residual (tighter bins)
    score += 0.5 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "friendly" residue class (divisible by common small item sizes) are
    // more reusable. Reward low residue entropy.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fill = 1.0 - post / cap; // fraction of bin used

    // Reward high fill ratio (non-linear, quadratic coupling)
    score -= 12.0 * fill * fill;

    // Harmonic classes: post_residual divisible by 10, 20, 25, 50 is valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 7.0; }
        // Dead-space penalty: residual in awkward band (1..10 or odd small)
        if pr < 10 {
            score += 8.0;
        } else if pr % 10 != 0 && pr % 5 != 0 {
            score += 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size <= pr {
            let slack_after = pr - next_item_size;
            if slack_after % 10 == 0 || slack_after == 0 {
                score -= 5.0;
            } else {
                score += slack_after as f64 * 0.15;
            }
        } else {
            // next item won't fit here; mildly penalize wasting tight space
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // nearly full or there are many open bins already (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * mean_residual / (open_bins_count.max(1) as f64 * cap);
        score += 20.0 - 10.0 * pressure - 5.0 * progress;
        // Integer-division threshold: open new bin only if mean residual < quarter capacity
        if mean_residual < cap * 0.25 {
            score -= 12.0;
        }
    }

    // Mild penalty for leaving residual far from mean (imbalance)
    score += ((post - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the leftover, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.8;

    // Strict dead-space avoidance: leftover gaps too small for any item
    // (min size 1..100 unknown, but conservatively gaps < ~20 are risky).
    if post_residual < 20 && post_residual > 0 {
        score += 60.0 + (20 - post_residual) as f64 * 3.0; // unusable sliver penalty
    }

    // Gap should ideally accommodate the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // leaves room for the lookahead item
        } else {
            score += 12.0; // forces lookahead into another bin
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open-bin pressure: discourage proliferation of open bins,
    // but only mildly so we don't force bad fits.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual below mean (consolidating fuller bins),
    // penalize dumping into very empty bins while emptier options exist.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate (empty bin) handling: opening a new bin is fine
    // early in the stream, but penalize it late when bins should be filled.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + progress * 80.0 + open_bins_count as f64 * 2.0;
        // But allow a fresh bin if the item is large and nothing fits well.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 1 {
            score -= 90.0;
        }
    }

    // Mild stream-progress term: later items should fill bins more aggressively.
    score += (step_index as f64 / total_items.max(1) as f64) * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if (post_residual as f64 - next_f).abs() < 1.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to tightness of the chain
            let chain_waste = (post_residual as f64 - next_f) / bin_capacity as f64;
            score -= 40.0 * (1.0 - chain_waste);
        } else {
            // next item does NOT fit: penalize dead space left behind
            score += 15.0 + 0.5 * (next_f - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious tight fits.
    let res_f = post_residual as f64;
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        let dev = (res_f - mean_post) / mean_post;
        if dev < 0.0 {
            score -= 10.0 * (-dev).min(1.0); // tighter than average: good
        } else {
            score += 5.0 * dev.min(2.0); // looser than average: mild penalty
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // base penalty so open bins win unless they are bad fits
        score += 30.0;
        // early stream: new bins are cheap; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins: discourage opening yet another
        score += 2.0 * open_bins_count as f64;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
        // Bonus if next item exactly fills the bin afterwards.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing bins would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score += 8.0;
        }
    }

    // Global state coupling: when many bins are open, prefer consolidation.
    if open_bins_count > 3 {
        score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be conservative (slightly favor
    // opening fresh bins); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - tightness);

    // Mild penalty proportional to waste relative to mean residual.
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer minimal post-residual (tight fit), scaled non-linearly
    let mut score = pr * (1.0 + 0.5 * (pr / cap));

    // Reward tight fits strongly: normalized fill of the used space
    let fill = it / cap;
    score -= 30.0 * fill * fill;

    // Non-linear coupling: as stream progresses, prioritize compacting residual space more
    let prog_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 20.0 * prog_coupling * (1.0 - pr / cap);

    // Lookahead: bonus if post residual exactly accommodates next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 25.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * (1.0 - pr / nx.max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation control)
    score += 0.5 * (pr - mean_residual).abs();

    // Mild penalty for many open bins when residual is large (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Slight preference to fill bins early rather than late
    score += 5.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (0..=10, 20..=30, 40..=50, ...) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Harmonic class index: divide capacity into 10 classes of 10 units.
    let class = (post_residual / 10).min(9) as f64;

    // Reward tight fits: post residual in the first class is ideal.
    score -= (10.0 - class) * 1.5;

    // Penalize residuals that are "dead" — too small for typical items
    // (items >= 10), i.e. post_residual in 1..10 is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Non-linear penalty on large residuals that are odd harmonics
    // (residuals like 15, 25, 35 pair poorly with 10-multiples).
    let odd_penalty = ((post_residual % 20) as f64 - 10.0).abs();
    score += odd_penalty * 0.4;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let nxt_fit = post_residual - next_item_size;
            // reward small double-leftover
            score -= (10.0 - (nxt_fit / 10).min(10) as f64) * 0.8;
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins; penalize
        // unless existing residuals are all poor (large mean residual is fine,
        // small mean residual means bins are nearly full).
        score = cap - mean_residual * 2.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, new bin is fine
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big item coming, fresh bin useful
        }
    }

    // Progress-aware scaling: later in the stream, tighten packing more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward residuals that can still host a typical next item (10..80 range),
    // penalize residuals that are "dead" for the known size range.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0;
        // Bonus if the lookahead item fits exactly into the post residual.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        }
        // Mild bonus if lookahead fits within post residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    } else if post_residual < 10 && post_residual > 0 {
        score += 10.0; // gap too small for any item
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate handling: an empty bin gets a moderate baseline so it
    // only wins when open bins are genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 2.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins with residuals below the mean (tighter bins first).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else {
            score -= 25.0 / gap.sqrt();
            // Penalize if next item cannot fit (dead space locked against lookahead).
            if post_residual < next_item_size {
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Prefer bins with residual below mean (tight bins get packed first), keep large residuals open.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: only attractive when it enables a near-exact 2-step match
    // or when open bins fit poorly; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) == bin_capacity {
            score -= 45.0;
        } else {
            score += 40.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight preference for tight fits overall (small post-residual squared).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space if post_residual can't fit a typical next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else if post_residual == next_item_size {
            score -= 30.0; // perfect lookahead match
        } else {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or no real alternatives.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 20.0 + 15.0 * scarcity - 10.0 * (item_size as f64 / bin_capacity as f64);
        score += 5.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already small relative to fleet average (consolidation).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference to use bins when many are open (avoid bin sprawl).
    score -= 0.05 * open_bins_count as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good,
    // reward it more aggressively as the stream progresses.
    let tight = (1.0 - post_residual as f64 / cap).max(0.0);
    score -= 24.0 * tight * tight * (0.5 + progress);

    // Penalize leaving dead space that is too small to be useful later
    // (small but nonzero post_residual is the worst outcome).
    let pr = post_residual as f64;
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 18.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward if the next item exactly fills the post-residual,
    // penalize if next item cannot fit into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 14.0 * (1.0 - gap / cap) * (0.6 + 0.4 * progress);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild pressure to prefer filling more-occupied bins when many bins are open.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= 6.0 * fill_ratio * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);

    // New-bin candidate: make it attractive only when open bins would leave
    // very poor fits; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let avg_waste = (mean_residual - item_size as f64).max(0.0);
        score = 55.0 - 0.3 * avg_waste - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 partition dead space
    // into "usable" (small residue -> near-divisible) vs "wasted" classes.
    let post = post_residual as i64;
    let residue = (post % 10) as f64;
    // Penalize awkward residues (dead space not reusable by typical items).
    let harmonic_penalty = match post % 20 {
        0 => -6.0,          // perfectly divisible residual: great
        5 | 15 => -3.0,     // half-class: still useful
        1 | 2 | 3 | 4 => 4.0, // sliver class: mostly dead
        6 | 7 | 8 | 9 => 2.0,
        10 => -1.0,
        11 | 12 | 13 | 14 => 3.0,
        16 | 17 | 18 | 19 => 1.5,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division thresholds on post_residual:
    // how many "small item slots" (size <= 10) still fit?
    let slots = post / 10;
    score -= slots as f64 * 2.5;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits, mildly penalize the near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt == post {
            score -= 12.0;
        } else if nxt > post {
            score += 5.0; // next item won't fit here anyway
        } else {
            let gap = post - nxt;
            let gap_class = gap % 10;
            if gap_class == 0 {
                score -= 5.0; // next item leaves divisible residual
            } else if gap_class >= 7 {
                score += 2.0;
            }
            score += (gap as f64) * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Capacity fraction coupling: residual as fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 10.0; // convex penalty on large leftover

    // Prefer filling existing bins as stream progresses and bins accumulate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;
    score += open_bins_count as f64 * 0.4;

    // Deviation from mean residual: prefer bins whose residual is already low.
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0; // tiny leftover is effectively a perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful later
    // are heavily penalized. Define a "useful threshold" relative to the smallest
    // plausible item (items >= 1, but typical useful gap is >= ~10).
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Waste zone: the smaller (more useless) the gap, the worse.
        score += (dead_threshold - pr) * 8.0;
    }

    // Reward tight fits (small post_residual) proportionally to how much of the
    // bin was consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: penalize spreading across many bins; encourage closing
    // out existing bins when there are already several open.
    score += (open_bins_count as f64) * 2.5;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If the item fits tightly in an existing bin, opening a new bin is bad.
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Lookahead: if the next item can exactly fill this bin's post_residual,
    // strongly favor placing the current item here.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: the gap is likely dead space.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from
    // the mean — placing into a bin with residual near item_size is efficient.
    let mean_r = mean_residual;
    if mean_r > 0.0 {
        let deviation = (bin_residual as f64 - mean_r).abs();
        score += deviation * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Penalize leaving a residual that the next item cannot use at all.
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Reward closeness to mean residual (balanced residual profile).
    score -= 2.0 * (-((post_residual as f64 - mean_residual).abs() / 20.0)).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin would leave unusable dead space.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let poor_fit = if next_item_size > 0 && waste > next_item_size as f64 { 0.0 } else { 8.0 };
        score += 55.0 + poor_fit - 0.5 * (open_bins_count as f64);
    }

    // Slight penalty for wasting large residuals early in the stream.
    score += 0.05 * post_residual as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    // Reward filling bins that are already mostly used.
    score -= 0.3 * (bin_capacity - bin_residual) as f64 / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize large dead space relative to capacity
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: bonus if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual {
            // this bin can take current but blocks a better arrangement for next item
            score += 5.0;
        }
        // if next item larger than item, prefer tighter bins (best-fit coupling)
        if next_item_size > item_size {
            score += (post_residual as f64) * 0.1;
        }
    }

    // Prefer bins with residual close to item (classic best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Time horizon: early in stream, be pickier about waste; late, pack greedily
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // Global state coupling: many open bins -> discourage spreading, favor filling
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mean residual coupling: if this bin is much tighter than average, favor it
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // base cost of opening a new bin
        score += 45.0;
        // but if existing bins would leave big waste, opening new bin is reasonable
        let avg_waste = mean_residual.max(0.0);
        if avg_waste > 60.0 {
            score -= 30.0;
        }
        // early stream: new bins cheap (future items can fill them)
        score -= 20.0 * (1.0 - progress);
        // if next item is small, a fresh bin has good future utility
        if next_item_size > 0 && next_item_size <= 40 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual (waste left behind), smoothly warped by stream progress.
    let mut score = pr * (1.0 + 0.6 * t * (1.0 - t) * 4.0);

    // Non-linear coupling: quadratic dead-space penalty that grows late in stream.
    score += 30.0 * x * x * (0.5 + t);

    // Reward tight fits: cubic term favoring small x.
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: penalize if post residual neither fits next item nor is near zero.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = pr >= nx;
        if fits_next {
            score -= 12.0 * (1.0 - (pr - nx) / cap).min(1.0);
        } else {
            // dead space that next item cannot use — penalize more as stream progresses
            score += 10.0 * (1.0 - pr / nx) * (0.4 + t);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, less so early when many bins help.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(2.0);
        score += 35.0 - 8.0 * openness - 10.0 * t;
        // opening a new bin is attractive if item is large (leaves small residual)
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Slight preference for bins with residuals near mean (balance preservation).
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of small denominators) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 25 == 0 || pr % 20 == 0 {
        -5.0
    } else if pr < 10 {
        6.0 // tiny dead space is nearly worthless
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.05;
        // extra reward if next item then fits snugly (harmonic pair)
        let npr = post_residual - next_item_size as u32;
        if npr % 10 == 0 { score -= 3.0; }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.5; // creates dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when it enables a very tight future fit
    // or existing fits are all poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = fitting_bins_count <= 1;
        let tight_new = next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && (bin_capacity - item_size - next_item_size) < 10;
        if poor_fits || tight_new {
            score -= 4.0 + 5.0 * progress;
        } else {
            score += 10.0 + mean_residual * 0.1; // prefer reusing open bins
        }
    }

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-3.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (super-linear in the "deadness" of the gap).
    let dead_zone = 20.0; // gaps below this are likely wasted
    if (post_residual as f64) < dead_zone {
        let deadness = dead_zone - post_residual as f64;
        score += 3.0 * deadness + 0.5 * deadness * deadness;
    } else {
        // Reward keeping gaps in a usable band (>= 20), mildly proportional.
        score -= 0.15 * (post_residual as f64 - dead_zone).min(60.0);
    }

    // Perfect fit bonus: leaving zero residual is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits, but not perfectly: mild bonus proportional to slack match.
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading; penalize low residuals there.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mean residual alignment: prefer bins whose residual is below average
    // (i.e., filling the emptier bins first keeps tight bins for tight items).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if large_item > 0.7 {
            score -= 10.0 * large_item; // large items start fresh bins
        } else {
            score += 20.0 * (1.0 - large_item); // discourage wasting fresh bins
        }
    }

    // Slight progression bias: early in the stream, be a bit more liberal
    // with opening bins; later, consolidate tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimal dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tight the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 100.0 - chain_waste.min(100.0);
        } else {
            // Next item cannot follow: penalize wasted residual that blocks the chain.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when existing bins could fit (new-bin candidate signal).
    if bin_residual == bin_capacity {
        // Only attractive if no open bin fits or item is large relative to capacity.
        if fitting_bins_count > 0 && item_size < bin_capacity * 3 / 4 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // Late-stream pressure: consolidate more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.2 + 0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tightest fit), with mild nonlinearity.
    score += (post_residual as f64).powf(1.15) * 0.05;

    // Reward perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that is too small to hold even a minimum item.
    if post_residual < 1 {
        score += 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.8 - (slack as f64) * 0.3;
            if slack == 0 {
                score -= 300.0; // chain of perfect fits
            }
        } else {
            // post residual cannot host next item: penalize proportionally to waste
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + (item_size as f64) * 0.3;
    }

    // New-bin candidate handling: opening a new bin is attractive when open bins
    // are mostly full or few bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64).max(1.0);
        // New bin is penalized normally, but discount penalty as bins fill up.
        let new_bin_penalty = 60.0 * (1.0 - 0.7 * avg_fill) - 20.0 * progress;
        score += new_bin_penalty.max(5.0);
        // Reserve new bins for large items that leave useful residuals.
        score -= (item_size as f64) * 0.5;
    }

    // Prefer filling bins with large mean residual (consolidate emptier bins),
    // keep emptier bins free for large future items.
    score += mean_residual * 0.05;

    // Slight preference for using bins when many are open (reduce bin count).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Time horizon: late in the stream, be greedier (tight fits matter more,
    // opening new bins is more acceptable since leftover space is wasted anyway).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - post_residual as f64) * 0.1;

    // Penalize very loose fits (large post residual) especially early on.
    if post_residual > bin_capacity / 2 {
        score += (post_residual as f64 - bin_capacity as f64 / 2.0) * (1.5 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: post residual, mildly compressed
    let mut score = r;

    // Non-linear polynomial coupling of residual with stream progress
    let poly = (1.0 - progress) * rn * rn + progress * (1.0 - rn) * (1.0 - rn);
    score += 12.0 * poly;

    // Penalize large wasted residual late in the stream
    score += 8.0 * progress * rn * rn;

    // Reward tight fits (small post residual) with smooth decay
    score -= 15.0 * (-rn * 4.0).exp() * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            score -= 6.0 * (1.0 - ((r - n) / cap)).min(1.0);
        } else {
            score += 5.0 * (n - r) / cap;
        }
    }

    // Penalty if residual is small but nonzero (dead space)
    if r > 0.0 && r < 10.0 {
        score += 10.0 * (1.0 - r / 10.0);
    }

    // Slight preference for bins below mean residual (balance)
    score += 0.5 * (mean_residual - r) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo structure of capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items (1..100 unknown, assume >=10 common)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0; // marginal dead space
    }

    // Perfect fit reward via harmonic classes (mod 25 on capacity)
    let class = post_residual % 25;
    if post_residual == 0 {
        score -= 80.0; // exact fill
    } else if class == 0 {
        score -= 25.0; // quarter-capacity aligned residual
    } else if class == 10 {
        score -= 15.0; // common small-item size aligned
    }

    // Integer division thresholds: post_residual / next_item_size
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // how many next-size items fit: harmonic quotient
            let q = post_residual / next_item_size;
            score -= 6.0 * (q as f64).min(3.0);
        } else {
            // residual can't host lookahead: penalize proportionally
            score += 8.0 * (1.0 - pr / cap);
        }
        // lookahead exactly fills residual -> strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Last-chance bin bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // New-bin candidate handling: empty bin
    if bin_residual == bin_capacity {
        // prefer new bin when current open bins are crowded with small residuals
        // (i.e., mean residual low) or late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 25.0 * (mean_residual / cap);
        score -= 20.0 * progress;
        // opening new bin is good if item is large and would leave bad residual elsewhere
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        if post_residual < 25 {
            score += 10.0; // opening bin for large item leaves decent residual
        }
    }

    // Mild preference to consolidate into fewer bins
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    // Fraction-of-capacity smoothness: penalize residuals in awkward mid-band
    let frac = pr / cap;
    if frac > 0.4 && frac < 0.6 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1, but tiny gaps are practically unusable)
    // are heavily penalized. Dead space in (0, 12) is worst.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Open bins pressure: many open bins -> prefer filling existing ones,
    // penalize candidates that leave large post_residual when bins are many.
    let ob = open_bins_count as f64;
    score += 0.35 * ob * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 12 {
                score -= 18.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Dead space that the next item cannot use.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive for large items early on,
        // less attractive late when we should consolidate.
        let large_item_bonus = if item_size >= 60 { 10.0 } else { 0.0 };
        score -= (1.0 - progress) * large_item_bonus + 2.0 * fill_ratio;
        score += progress * 5.0; // late stream: discourage new bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // next item fits exactly-ish after this placement
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 150.0;
            }
        } else {
            // next item won't fit here; penalize leaving large dead space
            score += 0.3 * diff;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Penalize small dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = score * 0.5 + (bin_capacity as f64) * (0.5 - 0.4 * pressure);
        // make new bin unattractive by default, good when no alternatives
        score += 30.0 - 200.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progression through the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual, more so as the stream matures.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * (0.5 + t);

    // Penalize dead space that is too small to be useful for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 12.0; // chainable
        } else {
            // Next item won't fit here; slight penalty if post_residual is large wasted chunk
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that keep flexibility (residual near mean).
        let flex = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * flex;
    }

    // Global state: many open bins -> encourage consolidation (fill existing bins).
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - large_item); // small items shouldn't open new bins
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Early in stream, fresh bins are cheap; late, avoid spreading.
        score -= 20.0 * (1.0 - t);
    }

    // Mild preference for filling bins with larger residual (use space while available).
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = pr * (1.0 + 0.9 * (1.0 - fit) * (1.0 - fit));

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tight fits matter more.
    let progress_coupling = t * t * (3.0 - 2.0 * t); // smoothstep
    score -= progress_coupling * (cap - pr) * 0.35;

    // Penalize large dead space quadratically (unusable gaps).
    score += 0.012 * pr * pr / cap;

    // Reward filling a bin nearly completely.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0 * (1.0 - pr / 15.0);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: mild penalty that grows with stream progress
    // and with how many open bins could fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 22.0 * progress_coupling + 3.0 * (fitting_bins_count as f64);
        // But if the item is large relative to capacity and mean residual is small,
        // opening a new bin is reasonable: soften the penalty.
        let size_frac = item_size as f64 / cap;
        score -= 14.0 * size_frac * size_frac * (1.0 - mean_residual / cap).clamp(0.0, 1.0);
    }

    // Lookahead: bonus if this placement leaves room exactly for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff <= 3.0 {
            score -= 12.0;
        } else if pr >= nxt {
            score -= 4.0 * (1.0 - diff / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses.
    score += 0.15 * (open_bins_count as f64) * progress_coupling;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "clean"
    // (more likely to be exactly filled by future items in a 10-multiple world).
    let post = post_residual;
    let class = if post == 0 { 0 } else if post % 10 == 0 { 1 } else { 2 };
    score += match class {
        0 => -40.0,                       // perfect fit
        1 => -6.0 + (post / 10) as f64 * 0.4,
        _ => {
            // awkward residue: penalize more as it drifts from a multiple of 10
            let drift = (post % 10) as f64;
            let near = drift.min(10.0 - drift);
            4.0 + (10.0 - near) * 0.9
        }
    };

    // Integer-division threshold bands on post_residual
    let band = post / 20; // 0..=5
    score += band as f64 * 1.5;

    // Lookahead coupling: if next item exactly fits post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this bin's residual at all: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: it is recognizable by bin_residual == bin_capacity.
    // Give it a baseline so we only open a new bin when the item fits existing bins badly.
    if bin_residual == bin_capacity {
        // opening a new bin wastes capacity: penalize, but less if item is large
        score = cap - item_size as f64 * 0.8 + 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large incoming stream favors fresh bin
        }
    }

    // Slight preference to consolidate into fewer bins when many are open
    score += (open_bins_count as f64) * 0.15;

    // Mild preference to fill early bins first (progress-based tiebreak)
    score += (step_index as f64 / (total_items.max(1) as f64)) * 0.5;

    // Mean-residual coupling: avoid dumping into bins whose residual is far from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // are pure waste. Penalize them heavily with a super-linear ramp.
    let dead_zone = 20.0; // conservative min item size proxy
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * (dead_zone - post_residual as f64) * 0.5;
    } else {
        // Reward leaving a gap large enough for a typical next item
        score -= 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 10.0 * (fill_ratio - 0.8);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when few bins
    // are open, cheap when many are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 40.0 - pressure.min(40.0);
        // If no open bin fits well, opening may still win via the penalty above.
    }

    // Open-bin pressure: prefer bins whose residual deviates below the mean
    // (close out small-residual bins first to reduce bin count).
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Late in the stream, weight consolidation more (fewer wasted bins overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - fill_ratio.min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact or near-exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= (bin_capacity as f64 - gap as f64).max(0.0) * 0.9;
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Dead space: leftover that can't hold the next item and is small.
        if post_residual < next_item_size && post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward tight fits (small post residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 30.0;

    // Penalize leaving residuals far below the mean (wasted potential).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize so we prefer filling existing bins,
    // unless the fit in existing bins is terrible (post_residual very large gap).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if the item is huge relative to capacity, a fresh bin is attractive.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 30.0;
        }
    }

    // Slight preference early in stream to open bins when many items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.5 {
        score -= 5.0;
    }

    // Discourage creating dead space in [1,9] range that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 30.0;

        // Penalize dead space that no plausible item can fill.
        if (post_residual as f64) < 10.0 {
            score += 200.0; // tiny unusable sliver
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 500.0;
        } else {
            score -= 60.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty if we waste a large residual.
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless the fit is bad.
    if bin_residual == bin_capacity {
        // New empty bin: neutral baseline, penalized so it's chosen only when fits are poor.
        score += 40.0 + mean_residual * 0.3;

        // Late in the stream, avoid opening bins that will leave large waste.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    } else {
        // Reward using bins whose residual is close to the item (best-fit flavor).
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += waste_ratio * 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: when mean residual is high, prefer bins below mean
    // (drain small-residual bins first), penalize bins above mean.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - (pr / cap).powf(2.0);
    let progress_boost = 1.0 + t * t;
    score -= 12.0 * tightness * progress_boost;

    // Reward using a bin whose residual closely matches the item (smooth quadratic gap).
    let gap = (br - it) / cap;
    score -= 8.0 * (1.0 - gap * gap);

    // Penalize deviating far from the mean residual across open bins (smooth coupling).
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: favor bins whose post residual can host the next item (smooth sigmoid-like term).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = (pr - n).max(0.0) / cap;
        score -= 6.0 * (1.0 - fits_next) * (1.0 - t);
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it (smooth, capped).
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - t * 0.5);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).sqrt() * (pr / cap) * 2.0;

    // New-bin candidate: penalize opening a fresh bin early, allow it late.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) - 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: which quarter of the capacity it falls in.
    let quarter = (bin_capacity / 4).max(1);
    let class = post_residual / quarter; // 0..=4
    // Penalty weights per class: tiny residuals are dead space (bad), large residuals are fine.
    let class_penalty = [8.0, 3.0, 1.0, 0.0, 0.0][class.min(4) as usize];
    score += class_penalty;

    // Reward tight fits: item filling most of the residual.
    let fill = 1.0 - post / bin_residual.max(1) as f64;
    score -= 6.0 * fill * fill;

    // Harmonic divisibility: if next item divides evenly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 5.0;
        }
        // Next item fits well here: mild reward scaled by how much it consumes.
        let next_fill = next_item_size as f64 / post as f64;
        if next_fill > 0.8 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual at all: penalize small residuals more.
        score += (quarter as f64 - post).max(0.0) * 0.15;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: neutral-ish, penalized slightly so open bins are preferred,
    // but attractive when mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / cap).min(1.0);
        score = cap * 0.55 + 10.0 * fragmentation - 5.0 * fragmentation * fragmentation;
        if next_item_size > 0 && next_item_size >= item_size * 2 {
            score -= 4.0; // big next item benefits from a fresh bin
        }
    }

    // Late in the stream, avoid opening bins; prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    // Mild penalty per open bin to discourage spreading items thin.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        // Tight-but-usable fit gets a moderate reward.
        score -= 8.0 * (15 - post_residual) as f64 / 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit in the leftover: mild penalty for fragmenting.
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // allow filling more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Prefer bins with residual close to the mean (balanced filling).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 1 {
            score += 20.0 + 30.0 * (1.0 - tightness);
        } else {
            score += 5.0 * (1.0 - tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect chain), penalize wasted space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item chain
        }
        // If next item can't fit anywhere else, prefer keeping this bin flexible
        if post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Penalize dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual < next_item_size {
            score -= 35.0; // open a fresh bin when this item would strand space
        }
    }

    // Late in stream, tighten packing (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 10.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity if open bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin (its residual is 100, so subtract the fit reward effect).
        score += 30.0;
        // If few fitting bins or item is large, opening a new bin is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += progress * 10.0;
        // Many open bins with small mean residual: consolidation pressure.
        if open_bins_count > 3 && mean_residual < 40.0 {
            score += 15.0;
        }
    }

    // Global state: spread items across bins when open bins have large residuals.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score -= 4.0;
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        score += 4.0;
    }

    // Mild bonus for filling bins completely early on.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = pr / cap;

    // Base: post residual (bigger leftover = worse bin choice)
    let mut score = pr;

    // Smooth non-linear penalty on wasted fraction, growing with stream progress
    let waste = fit_ratio * fit_ratio;
    score += 40.0 * waste * (0.5 + progress);

    // Reward tight fits: cubic decay of post-residual
    score -= 60.0 * (1.0 - fit_ratio).powi(3);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize if leftover can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            score += 0.5 * gap * (0.5 + progress);
        } else {
            score -= 5.0;
        }
    }

    // Fragmentation coupling: small residual relative to mean residual is attractive
    score += 0.3 * (mean_residual - pr);

    // Slight preference to keep many bins from proliferating early
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * fit_ratio;

    // New-bin candidate handling: neutralize raw residual, mild baseline
    if bin_residual == bin_capacity {
        score = 60.0 + 20.0 * progress - 0.05 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity-fraction buckets.
    let post = post_residual as f64;
    let class = (post_residual * 4 / bin_capacity) as f64; // 0..3 quarter-classes

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly: small leftovers (class 0) are
        // nearly useless; moderate leftovers are usable.
        score += (class * class) * 8.0;
        // Extra penalty for tiny unusable slivers (1..=9).
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > post_residual {
            // next item cannot follow here; penalize proportionally
            score += 10.0;
        } else {
            // next item fits with leftover; reward partial chaining
            let npost = post_residual - next_item_size;
            score -= 50.0 - (npost as f64) * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + post * 0.3;
    }

    // New-bin candidate handling: opening a fresh bin is good only when
    // existing residuals are large (item fits poorly everywhere) or the
    // stream is early (room to accumulate future pairings).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual / cap; // small mean_residual => open bins are full
        let base = 60.0 + post * 0.2;
        let discount = (1.0 - tight) * 40.0 * (1.0 - progress);
        score += base - discount;
        // Never open a new bin when a perfect fit exists elsewhere is
        // handled by the huge perfect-fit bonus above.
        // Discourage opening when item is small relative to capacity.
        score += (cap - item_size as f64) * 0.15;
    } else {
        // Favor bins whose residual is close to the item (tight fits).
        score -= (bin_residual as f64 - item_size as f64).abs() * -0.0;
        score -= (bin_residual - item_size) as f64 * 0.05;
        // Slight preference for bins below mean residual (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild congestion control: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score += if is_new_bin { 15.0 } else { -2.0 };
    }

    // Modulo harmonic tweak on post_residual: leftovers divisible by small
    // integers (common item sizes 10/20/25/50) are more reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // should not happen, but guard
    }
    // Unusable gap: too small for any item (items >= 1, so gap of 0 is perfect fit)
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    } else if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0; // tiny dead space penalty
    }

    // Reward tight fits: small post_residual relative to bin capacity
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 + (post_residual as f64 - next_item_size as f64).min(30.0) * 0.2;
    }
    // If next item does NOT fit, penalize slightly (wasted opportunity)
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: penalize placements into bins when many bins are open
    // unless the fit is tight; encourages consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress * 0.5);

    // Mean residual coupling: prefer bins whose residual is near mean (avoid
    // fragmenting one very empty bin while others are full)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Make it moderately expensive so it is
    // chosen only when open-bin placements have large post_residual or many bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large, a fresh bin is fine (large items fill bins well)
        score -= item_size as f64 * 0.15;
        // Late in stream with many open bins, discourage opening yet another
        score += open_bins_count as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Next item fits into the post residual: strong reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.15 * slack;
    }

    // Post residual is dead space: next item cannot use it.
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual).min(bin_capacity) as f64;
        score += 0.35 * waste;
    }

    // Penalize very small unusable remnants (dead space < typical min item).
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins that are already relatively full (small residual).
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New empty bin candidate: penalize unless current open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        let poor_fit = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 12.0 * crowded - 10.0 * (1.0 - poor_fit);
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale primary term by squared fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill * fill * (item_size as f64);

    // Penalize small dead space (unusable residuals) nonlinearly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (10.0 - dead);
        }
        // Penalize residuals too small for the smallest plausible item.
        if dead < 20.0 {
            score += 8.0 * (20.0 - dead) * 0.5;
        }
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading when many bins fit; prefer concentrating.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in the post residual, big reward;
    // if next item doesn't fit, mild penalty for blocking.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - 0.4 * slack;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= 0.3 * open_bins_count as f64 * fill;

    // Mean-residual coupling: if this bin's residual is below mean, it's tighter
    // than average — favor it (its space is scarcer).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 && residual_f < mean_residual {
        score -= 2.0 * (mean_residual - residual_f) / mean_residual;
    } else if mean_residual > 0.0 {
        score += 1.0 * (residual_f - mean_residual) / mean_residual;
    }

    // Time horizon: early in stream, be pickier about large dead space
    // (long horizon to fill it); late, prefer just closing bins out.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 {
        score += (1.0 - t) * 0.10 * post_residual as f64;
        score -= t * 0.05 * post_residual as f64;
    }

    // New-bin candidate (empty bin): open a new bin only when no open bin fits
    // well; make the empty bin costly unless fits are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else {
            // Discourage abandoning open bins unless all fits are terrible.
            score += 18.0 + 0.2 * item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (post_residual as f64 / cap);

    // Base: reward tight fits (low post_residual), with non-linear sharpening.
    let mut score = pr + 30.0 * pr * pr / (cap * cap);

    // Smooth polynomial coupling of fit quality with stream progress:
    // tight fits become more valuable as the stream advances.
    score -= 25.0 * tightness.powi(2) * (progress * (2.0 - progress));

    // Penalize dead space: residuals too small for typical future items.
    let dead = ((30.0 - pr).max(0.0)) / 30.0;
    score += 20.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual.
    score += 0.5 * ((open_bins_count as f64).ln().max(0.0)) * (pr / cap);

    // Keep new-bin candidate competitive only when residuals are badly fragmented.
    let new_bin_bias = if bin_residual == bin_capacity {
        8.0 + 10.0 * (1.0 - progress) + (mean_residual / cap) * 5.0
    } else {
        0.0
    };
    score += new_bin_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality depends on residue class mod 10
    let post_class = post_residual % 10;
    if post_residual == 0 {
        score -= 25.0; // perfect fit, ideal
    } else if post_residual < 10 {
        // unusable dead space for typical items (min size 10)
        score += 12.0 + (10 - post_residual) as f64 * 2.5;
    } else {
        // usable residual: reward divisible-by-10 classes (harmonic alignment with capacity 100)
        if post_class == 0 {
            score -= 6.0;
        } else if post_class <= 3 {
            score += 3.0;
        }
        // integer division thresholds: large usable chunks are flexible
        let chunks = post_residual / 20;
        score -= chunks as f64 * 2.0;
    }

    // Fraction of capacity filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Coupling with lookahead item: reward residuals that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + (post_residual - next_item_size).min(30) as f64 * 0.2;
        } else {
            score += 4.0; // next item cannot fit here
        }
        // harmonic pairing: item_size + next_item_size close to capacity class
        let pair = item_size + next_item_size;
        if pair <= bin_residual && (bin_residual - pair) % 10 == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strong penalty to skip it unless fit is excellent
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 10 {
            score -= 20.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill > 0.75 || open_bins_count == 0 {
            score -= 18.0 + progress * 5.0;
        } else {
            score += 30.0; // discourage opening new bins while space exists
        }
    }

    // Mild preference to balance load across many open bins
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins / favor consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 0.4 * (0.5 + progress);

    // New-bin candidate: penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.2;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 3.0;
        }
    }

    // Mild preference for bins below mean residual (balancing residuals).
    score += (post_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio;

    // 2-step lookahead: perfect match with next item is excellent
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // exact fill of remaining space by next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins more when open bins exist and item fits reasonably
        if open_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 60.0 * (1.0 - 0.3 * progress);
        } else {
            score += 10.0;
        }
    }

    // Penalize tiny dead space (<10) that is hard to fill, but reward exact fills
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let x = pr / cap; // normalized post residual

    // Smooth polynomial base: reward tight fits (small post_residual)
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more (quartic damping of residual waste)
    let prog_coupling = x * x * (1.0 - progress) + x * x * x * x * progress;
    score += 20.0 * prog_coupling * cap * 0.01;

    // Reward bins whose residual matches the next item (smooth lookahead affinity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let affinity = 1.0 - ((pr - nxt) / cap).abs();
        score -= 6.0 * affinity.max(0.0) * (1.0 - progress * 0.5);
    }

    // Penalize when many bins fit the item (less urgency to use this one)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    } else {
        // last-chance bin: strong reward to avoid opening a new bin
        score -= 8.0;
    }

    // Coupling with mean residual: prefer bins deviating favorably from the mean
    score += 3.0 * (mean_residual - pr) / cap;

    // Slight preference for using existing bins over opening new ones,
    // scaled smoothly with open bins count and progress
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    } else {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of post_residual: classify residual into capacity-fraction buckets.
    // Residuals in the "useless" class (too small for typical items) are penalized.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..8 harmonic class
    match class {
        0 => score -= 12.0, // near-perfect fit: excellent
        1 => score -= 6.0,  // small but potentially usable gap
        2 => score -= 2.0,  // quarter bin left: still flexible
        3 => score += 0.0,
        4 => score += 1.0,  // half bin: fine
        5 => score += 2.0,
        6 => score += 3.0,  // mostly empty: weak placement
        _ => score += 4.0,  // nearly untouched bin
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo coupling: if post_residual and next_item_size share a harmonic class
    // (same residue class mod 10), the next item likely fits snugly -> reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 - slack.min(5.0); // reward when next item fits
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 4.0; // harmonic alignment: exact modular fit
            }
            if (post_residual / 10) == (next_item_size / 10) {
                score -= 2.0; // same integer-division decade: near-exact fit
            }
        } else {
            score += 3.0; // next item won't fit here; this bin closes anyway
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current open bins are crowded (high mean utilization) or many bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let utilization = 1.0 - mean_residual / (bin_capacity as f64);
        let crowd = (open_bins_count as f64).sqrt() * 0.5;
        score = bin_capacity as f64 - 8.0 - utilization * 15.0 - crowd + progress * 2.0;
        // If several bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
        }
        // Small next item with crowded bins: reuse is better than opening.
        if next_item_size > 0 && next_item_size < 20 && utilization > 0.6 {
            score += 8.0;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual (emptier
    // bins absorb the item, keeping tight bins available for small items).
    if (post_residual as f64) > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Reward tight fits proportionally (small post residual relative to item).
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize if next item almost fits but would be blocked by this placement.
    if next_item_size > post_residual && next_item_size <= bin_residual && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins with residual close to the item (best-fit coupling).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // New-bin candidate: mildly penalize so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good filler; if far above, deprioritize.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect two-item fill).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (diff / 40.0).exp();
        // Slight nudge if next item fits exactly, leaving a fully closed bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize dead space too small for the next item (unusable gap).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64) * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64));
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (best-fit flavor), but soften when many bins are open.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 10.0 * rel;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 0.3 * (item_size as f64);
    }

    // Penalize the brand-new empty bin candidate mildly so it only wins
    // when open bins fit poorly (its post_residual == capacity - item_size
    // is large, already handled by base score; add explicit offset).
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Late-stream consolidation: near the end, prefer filling bins tightly
    // to avoid opening bins that will barely be used.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).powi(2) * 50.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin, scaled by how well it fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // Lookahead: if the next item fits in this bin's post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + next_item_size as f64 * 0.3;
        } else {
            // Penalize leaving residual that blocks the next item badly
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.15;
        }
    }

    // New-bin candidate handling: empty bin gets a base cost so we only
    // open a new bin when fits are poor or open bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - bin_capacity as f64).abs(); // == capacity for empty bin
        let _ = poor_fit;
        // Cost of a new bin decreases as stream progresses (fewer future
        // chances to fill it), increases with number of open bins.
        let new_bin_cost = 150.0 - 60.0 * progress + 4.0 * open_bins_count as f64;
        // If no open bin fits well, discount the new bin.
        let fit_quality = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += new_bin_cost - (1.0 - fit_quality) * 100.0;
    } else {
        // Prefer bins whose residual is close to the mean residual
        // (keeps residual distribution balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;

        // Mild penalty for spreading across many open bins when few fit.
        if fitting_bins_count > 1 {
            score += 2.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Time horizon coupling: early in the stream, be conservative with
    // residual space; late, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 + progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) - pr_norm * progress * progress;
    score += 40.0 * coupling;

    // Penalize tiny dead space more as stream advances (wasted capacity becomes costly)
    let dead = pr_norm * (1.0 - pr_norm);
    score -= 30.0 * dead * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it early or when its residual dominates mean residual
    if bin_residual == bin_capacity {
        score = pr + 15.0 * progress - 10.0 * (1.0 - progress);
        if pr_norm > (mean_residual / cap) {
            score -= 5.0 * (pr_norm - mean_residual / cap);
        }
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - pr / (cap + 1.0));
    }

    // Mild penalty for bin proliferation
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by common small
    // sizes (10, 20, 25, 50) are "usable" slots for future items.
    let r = post_residual;
    if r > 0 {
        let mut usable_bonus = 0.0;
        if r % 10 == 0 { usable_bonus += 3.0; }
        if r % 20 == 0 { usable_bonus += 2.0; }
        if r % 25 == 0 { usable_bonus += 2.0; }
        if r % 50 == 0 { usable_bonus += 3.0; }
        score -= usable_bonus;
    } else {
        score -= 50.0; // closed bin beats any open residual
    }

    // Dead-space penalty: tiny unusable leftovers.
    if r > 0 && r < 10 {
        score += 15.0;
    }

    // Lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        if r >= next_item_size {
            let slack = r - next_item_size;
            if slack == 0 {
                score -= 40.0;
            } else if slack < 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += ((next_item_size - r) as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current item is large relative to capacity and mean residual is low,
    // or when many bins are open (fragmentation control).
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when genuinely better.
        score += 20.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large item late in stream with low mean residual: new bin ok.
        if item_frac > 0.6 && mean_residual < item_frac * 50.0 {
            score -= 25.0;
        }
        // If the item fits no open bin well (post_residual would be tiny in
        // every bin), opening a new bin preserves flexibility.
        if post_residual == bin_capacity - item_size && item_frac > 0.5 {
            score -= 10.0 + 5.0 * progress;
        }
        // Many open bins: discourage further fragmentation.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Prefer filling bins whose residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 20.0;
        // Slight preference for bins below mean residual (balance spreading).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Mild global pressure to use open bins as stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small unusable gaps (1..10) are heavily penalized,
    // moderately small gaps (11..20) mildly penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Pressure from number of open bins: prefer closing out bins rather than
    // spreading items thinly; scale with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }
    // Penalize placements that leave a gap just barely too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive when current fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins are open or
        // mean residual is low (existing bins are nearly full).
        score = 45.0 + open_bins_count as f64 * 1.5 - mean_residual * 0.3;
        // Cheaper to open a new bin late in the stream.
        score -= 20.0 * progress;
        // If next item is large, a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are less attractive targets
    // when mean is low (avoid fragmenting), more attractive when mean is high.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * (if mean_residual < 25.0 { 0.4 } else { -0.2 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + next_item_size as f64 * 0.5;
    }

    // Penalize small dead space that likely can't fit future items (items >= 1)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - progress);
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Mild penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post-residuals (non-linear).
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 8.0;

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // unusable gap before next arrival
        }
        // Reward residual that exactly fits the lookahead item.
        if post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty so a fresh bin only wins when open-bin fits are bad.
        score += 14.0;
        // More open bins -> more willing to open a new one slightly.
        score -= (open_bins_count as f64).min(6.0);
        // If next item is large and current item leaves a big gap, new bin may be better.
        let gap = post_residual as f64;
        if next_item_size as f64 > gap {
            score -= 4.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += dev * 5.0;

    // Mild penalty for very large residual spread waste.
    if post_residual > bin_capacity / 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;
    let last_chance = (fitting_bins_count == 1) as f64;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr + 18.0 * pr_norm * pr_norm;

    // Late in the stream, squeeze harder into existing bins (dead space matters more).
    let progress_pressure = 10.0 * t * (1.0 - pr_norm) * pr_norm;

    // Reward near-exact fills more strongly as stream progresses.
    let fill_bonus = -(14.0 * t) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Last-chance bin: strong smooth reward to use it rather than open a new one.
    score -= 8.0 * last_chance * (1.0 + t) * (1.0 - pr_norm);

    // New empty bin: penalize mildly early, more if many bins open, less late.
    score += is_new * (6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0)) * (1.0 - 0.5 * t);

    // Lookahead: if next item could fill this bin's post-residual, reward this placement.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let fit_next = (1.0 - gap / cap).max(0.0);
        score -= 6.0 * fit_next * fit_next * (1.0 - t);
        // Penalize leaving a residual only the next item barely can't use.
        score += 4.0 * (gap / cap) * (1.0 - fit_next);
    }

    // Coupling with mean residual: avoid creating outliers far from mean.
    score += 3.0 * ((pr - mean_residual).abs() / cap);

    // Small tie-breaker noise-free smooth term on progress.
    score += 2.0 * t * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 buckets.
    let pr = post_residual;
    let harmonic = pr % 10;
    // Dead space penalty: residuals that are small but not zero are worst.
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64 / 10.0;
    } else if pr == 0 {
        score -= 30.0; // perfect closure
    } else {
        // favor residuals that are multiples of 10 (harmonic with typical sizes)
        if harmonic == 0 { score -= 8.0; }
        else if harmonic <= 3 { score += 6.0; } // awkward sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if (pr % next_item_size.max(1)) == 0 { score -= 6.0; }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 5.0; // next item won't fit here; slight penalty
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer reusing bins unless residual is fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize more when many open bins have large mean residual.
        score += 10.0 + 0.3 * mean_residual * (open_bins_count as f64).sqrt();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress; // late stream: reuse more aggressively
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual is "dead" if it's smaller than the minimum plausible item size.
    let min_item = 1.0f64;
    let dead_zone = 12.0f64; // gaps below this are rarely reusable
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 3.0;
    }
    // Perfect or near-perfect fits get a strong reward (subtract).
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as f64) <= min_item {
        score -= 30.0;
    }

    // Reward when post_residual can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 0.5 * next_item_size as f64;
    }
    // Penalize if next item fits only barely, leaving another dead gap.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size as u32) < 12 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, post_residual == capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if current bin fits would create big dead space, allow new bin.
        score -= mean_residual * 0.1;
    } else {
        // Favor bins whose residual is close to the item (tight fits).
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 10.0 * tightness;
        // Favor bins with below-mean residual (consolidate space).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight coupling: exact match strongly rewarded
        score -= 18.0 * (1.0 - gap / (bin_capacity as f64)).powi(3);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space)
        if post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score += 6.0 + 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize large unusable dead space relative to mean residual
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin unless the item is small
    // enough that a fresh bin yields a good long-term packing
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 14.0 + 30.0 * waste_ratio;
        // If no open bin fits, opening is necessary; soften the penalty
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
        // Prefer opening a new bin for big items (fewer leftovers later)
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.max(10) {
        score += 6.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Chain fit: item + next item both fit now.
        if item_size + next_item_size <= bin_residual {
            score -= 6.0;
        }
    }

    // New-bin candidate logic: only attractive when no good existing option exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred, modulated by global slack.
        let mut new_bin_penalty = 12.0;
        // If mean residual across open bins is small, opening a new bin is reasonable.
        if mean_residual < item_size as f64 {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 10.0 * progress;
        // Many open bins: discourage another one.
        new_bin_penalty += 0.5 * (open_bins_count as f64).ln().max(0.0);
        score += new_bin_penalty;
    } else {
        // Slight preference for fuller bins (best-fit flavor).
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Global state coupling: if mean residual is high, encourage consolidation into emptier bins.
    score += 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: strongly prefer tight fits (small post_residual), with a
    // non-linear quadratic/quartic shaping that punishes large leftover space.
    let mut score = post * (1.0 + 1.6 * post_norm * post_norm + 0.9 * post_norm * post_norm * post_norm * post_norm);

    // Smooth stream-progress coupling: as the stream advances, tighten the
    // preference for low post_residual (waste matters more later).
    let prog_tighten = 1.0 + 1.2 * progress * progress;
    score *= prog_tighten;

    // Interaction of post_residual with mean residual: penalize bins whose
    // post_residual deviates upward from the current mean (dead-space spread).
    let dev = post - mean_residual;
    score += 0.35 * dev * dev / cap;

    // New-bin candidate: smooth logistic-style penalty that relaxes slightly
    // with progress and with many open bins, but generally discourages opening
    // new bins unless the fit would be terrible.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (open_bins_count as f64) * 0.18);
        let base_penalty = cap * (0.55 + 0.25 * (1.0 - progress));
        score += base_penalty * (0.6 + 0.4 * openness);
        // If the next item is large, a fresh bin may be valuable: small rebate.
        if next_item_size > 0 {
            let next_norm = next_item_size as f64 / cap;
            score -= 12.0 * next_norm * next_norm;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead synergy: reward placements whose post_residual can host the
    // next item (smooth, quadratic in the slack match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - (slack / cap).min(1.0));
    }

    // Mild penalty for leaving a residual that is very small but nonzero
    // (fragmentation), expressed smoothly via sin shaping.
    if post_residual > 0 {
        score += 4.0 * (1.0 - (post_norm * std::f64::consts::PI).sin().abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10/20/25/50) are "reusable" classes; odd fragments are dead space.
    let residual = post_residual;
    let class_bonus = if residual == 0 {
        -30.0 // perfect fit is best possible
    } else if residual % 50 == 0 {
        -12.0
    } else if residual % 25 == 0 {
        -8.0
    } else if residual % 20 == 0 {
        -7.0
    } else if residual % 10 == 0 {
        -5.0
    } else if residual % 5 == 0 {
        -2.0
    } else {
        4.0 // non-aligned fragment: penalize
    };
    score += class_bonus;

    // If lookahead item fits exactly into post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= residual {
        if next_item_size == residual {
            score -= 20.0;
        } else {
            let chain = (residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain / bin_capacity as f64);
        }
    } else if next_item_size > residual {
        // Lookahead cannot use this bin's leftover: dead space penalty scaled
        score += 0.05 * residual as f64;
    }

    // Fraction-of-capacity thresholds on post-residual.
    let frac = residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 3.0; // tiny sliver, nearly unusable
    } else if frac > 0.5 {
        score -= 4.0; // bin still half-capable afterwards
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins are crowded or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 * 10.0;
        let bad_fit = (item_size as f64 / bin_capacity as f64) < 0.15;
        score = 55.0 + crowded * (1.0 - progress) - if bad_fit { 10.0 } else { 0.0 };
        if next_item_size > 0 && next_item_size > bin_capacity / 2 && item_size > bin_capacity / 2 {
            score -= 25.0; // two big items pair badly; fresh bin helps
        }
    }

    // Mild preference to fill already-opened bins as stream progresses.
    score += 0.01 * open_bins_count as f64;

    // Tie-break toward bins below mean residual (keeps residual spread balanced).
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the leftover relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (bin_capacity as f64);

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if the next item cannot fit into it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * (post_residual as f64);
    }
    // Extremely small gaps are almost surely dead for anything.
    if post_residual > 0 && post_residual < 12 {
        score += 18.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin pressure is high or the item
        // would fit reasonably elsewhere; reward when current bins are nearly full.
        score += 8.0 + 2.0 * pressure + 0.15 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin preserves a large, useful residual for the lookahead item.
            score -= 10.0;
        }
    } else {
        // Mild reward for reusing existing bins.
        score -= 0.05 * (open_bins_count as f64);
    }

    // Lookahead coupling: favor placements that leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Perfect 2-step fill: post_residual == next_item_size
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 > next {
            // Next item fits in the leftover: mild reward scaled by closeness
            score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit: dead space penalty, worse if post_residual tiny
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 18.0 * (1.0 - waste);
        }
        // Also reward residual close to mean_residual (keeps bins balanced)
        let mean_gap = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * mean_gap;
    } else {
        // Last item: pure waste minimization
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin; discount when the item fills it well
        score += 30.0 - 35.0 * fill;
        if next_item_size > 0 {
            // If next item pairs well with the leftover of a fresh bin, encourage
            let pair_gap = ((bin_capacity - item_size) as i64 - next_item_size as i64).abs() as f64;
            score -= 20.0 * (1.0 - pair_gap / bin_capacity as f64).max(0.0);
        }
    }

    // Prefer filling fuller bins overall (small post_residual relative to mean)
    if (mean_residual > 0.0) && (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late in the stream: consolidate harder, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the next item are wasteful.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        } else {
            // Reward residuals that exactly accommodate the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.5 * (-slack / 15.0).exp();
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If many bins fit the item, opening a new bin is rarely needed.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer using them.
        score += 0.15 * mean_residual;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean toward being well-used.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize remaining residual, with non-linear polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Smooth quartic dead-space penalty: tiny residuals are very bad.
    let dead = 1.0 - norm_pr;
    score += 12.0 * dead * dead * dead * dead * cap * 0.01;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Penalize bins whose residual is far below mean residual (wasteful bins).
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 6.0 * (1.0 - ((pr - n) / cap)).powi(2);
        } else {
            score += 4.0 * ((n - pr) / cap);
        }
    }

    // Mild penalty for too many open bins, decaying with progress.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bin slightly less attractive than good fits,
    // but attractive when post_residual would be tiny in existing bins.
    if bin_residual == bin_capacity {
        score += 3.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Dead-space penalty grows non-linearly for awkward leftover classes.
    // Classes: (0..5] excellent, (5..20] good, (20..50] mediocre, >50 poor.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += 8.0 + 0.15 * post_residual as f64;
    } else {
        score += 20.0 + 0.35 * post_residual as f64;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by small numbers
    // (10, 20, 25) are more likely refillable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        // Odd awkward remainders are penalized slightly.
        if post_residual % 2 == 1 && post_residual > 30 { score += 3.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0 - (gap as f64).min(40.0) * 0.2;
        } else {
            // Next item cannot use this bin's leftover; leftover risk rises.
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral baseline so it wins
    // only when all open bins have poor fits (their scores get inflated above).
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 0.1 * mean_residual.min(50.0);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        if open_bins_count == 0 { score -= 20.0; }
    }

    // Mild pressure against spreading across many open bins.
    score += 0.4 * open_bins_count as f64;

    // Tie-break: prefer bins tighter than the mean (denser bins first).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // open_bins_count pressure: the more bins are open, the stricter we get about waste
    let pressure = 1.0 + open_bins_count as f64 * 0.06;

    // --- Strict dead-space avoidance ---
    // Any leftover gap in (0, 10) is likely unusable dead space: penalize proportionally
    // to how close it is to zero, amplified by open-bin pressure.
    let dead_thresh = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_thresh {
        score += (dead_thresh - post_residual as f64) * 4.0 * pressure;
    }

    // Gap that cannot even hold the lookahead item is dead for at least one step.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit: large reward (overrides everything else).
    if post_residual == 0 {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap is immediately reusable by the next item: mild reward for chaining.
        score -= 3.0;
    }

    // Prefer the fullest bins (residual below the current mean residual): consolidation.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only open bin that fits, reward using it
    // to avoid opening a new bin (stronger later in the stream).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 7.0 + 3.0 * progress;
    }

    // New-bin candidate: penalize proliferation, scaled by open-bin pressure and
    // stream progression (late in the stream we consolidate rather than expand).
    if is_new_bin {
        let proliferation = 4.0 + open_bins_count as f64 * 0.8 + 6.0 * progress;
        if fitting_bins_count == 0 {
            // No open bin can take the item: new bin is the only option, neutralize.
            score -= proliferation;
        } else {
            score += proliferation;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (low post_residual) via non-linear shaping.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    score += 20.0 * norm_post * norm_post; // penalize large leftover space quadratically

    // 2-step lookahead: reward exact/near match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // perfect chain (post == next) strongly rewarded
        if diff == 0.0 {
            score -= 60.0;
        } else if nxt <= post {
            // next item fits into the remaining gap: reward proportional to fill ratio
            let fill = nxt / post;
            score -= 40.0 * fill * fill;
        } else {
            // next item cannot use the gap: penalize proportional to wasted potential
            score += 15.0 * ((nxt - post) / cap);
        }
    }

    // Reward placements that bring residual close to the mean residual of open bins
    // (keeps bin population balanced, preserving flexibility).
    let mean_gap = (post - mean_residual).abs();
    score += 3.0 * mean_gap / cap;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins early in the stream when plenty of open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * (1.0 - progress) * (open_bins_count.min(20) as f64) / 20.0;
        // But if nothing else fits (this call is the new-bin candidate and item is large),
        // soften the penalty.
        if item_size as f64 > 0.8 * cap {
            score -= 20.0;
        }
    }

    // Slight reward for packing into already-open bins vs. proliferation.
    score -= 5.0 * (open_bins_count as f64).ln().max(0.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Exact fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Perfect wrap: residual exactly matches next item size (lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    }
    // Penalize leaving residual that next item cannot use but is too small to be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with smaller residual among candidates (best-fit reinforcement).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Penalize spreading across too many open bins; encourage consolidation when crowded.
    if open_bins_count > 4 {
        score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in stream, be conservative (slightly prefer opening bins for large items);
    // late in stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): prefer it only for large items or when open bins are very full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 10.0
            + 25.0 * (1.0 - avg_fullness)
            - 20.0 * large_item
            - 10.0 * progress;
        // If no open bin fits, new bin is the only option anyway; soften penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized dead space, with non-linear waste penalty
    let mut score = (pr / cap).powf(2.0) * cap;

    // Tight fits are strongly favored (smooth quadratic reward for small residuals)
    score -= 25.0 * (1.0 - pr / cap).powf(3.0);

    // Stream progress coupling: early on, prefer leaving flexible space;
    // later, tolerate tight fits more (consolidation pressure rises)
    let flexibility = (1.0 - progress).powf(2.0);
    score += flexibility * pr * 0.35;
    score -= progress * pr * 0.15;

    // Lookahead: penalize if residual can't fit the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap < 0.0 {
            score += 12.0 * (-gap).powf(1.5); // residual too small for next item
        } else {
            score -= 8.0 * (1.0 - gap).max(0.0).powf(2.0); // next item fits well
        }
    }

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr / cap);
    }

    // Fragmentation pressure: many open bins with high mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap) * 6.0;

    // New-bin candidate: neutral-ish baseline, mildly penalized late in stream
    if bin_residual == bin_capacity {
        score = cap * 0.9 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // --- Perfect / near-perfect fits are highly desirable ---
    if pr == 0 {
        score -= 50.0; // exact closure of a bin
    } else if pr <= 5 {
        score -= 12.0; // tiny dead space, nearly perfect
    }

    // --- Harmonic class logic: residuals divisible by 10 align with
    //     common item-size classes (multiples of 10), keeping the bin
    //     reusable by future class-aligned items ---
    if pr > 0 && pr % 10 == 0 {
        score -= 3.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 1.5;
    }

    // --- Lookahead (k=2) coupling with next item ---
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 10.0; // next item closes this bin exactly
        } else if pr > next_item_size {
            score -= 2.0;  // next item still fits comfortably
        } else {
            // next item would NOT fit here: penalize proportionally to waste
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // --- Last-chance bonus: this is the only open bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins in general
        score += 25.0;
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Opening a bin is fine for very large items (they dominate the bin)
        if fill_frac > 0.8 {
            score -= 20.0;
        } else if fill_frac > 0.6 {
            score -= 8.0;
        }
        // If no open bin can fit the item, the new bin is mandatory
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, consolidating matters more: discourage sprawl
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // If mean residual across open bins is small, reuse is precious anyway
        if mean_residual < item_size as f64 {
            score -= 4.0;
        }
    }

    // --- Mild smoothing: penalize diverging from mean residual shape ---
    score += (mean_residual - pr as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Moderately small gap: mild penalty scaled by tightness.
        score += 0.5 * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 50.0;
        } else if diff > 0 && diff < 10 {
            score -= 10.0;
        } else if diff < 0 {
            // Next item won't fit here; slight penalty for blocking.
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (compact packing).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mild bias so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let tight_open = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalty grows with number of fitting bins; slight relief late in stream.
        let penalty = 40.0 + 25.0 * (tight_open - 1.0).min(6.0) - 15.0 * progress;
        return score + penalty.max(5.0);
    }

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: this bin then fits next item exactly
        } else if diff <= 5.0 {
            score -= 30.0 - 4.0 * diff;
        } else {
            // Penalize residuals too small for anything useful later
            score += (10.0 - post_residual as f64 / 10.0).max(0.0);
        }
        // Mild reward if next item also fits in the remaining space even if not exact
        if (next_item_size as f64) <= post_residual as f64 && diff > 5.0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Penalize very large leftover dead space relative to smallest item (10).
    if post_residual < 10 {
        score -= 8.0; // perfect fill
    } else if post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers, but scale with stream progression:
    // dead space matters more as the stream nears its end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 + 10.0 * progress;
    }

    // Lookahead: if the next item can exactly use the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste: mild penalty proportional to leftover
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; slight bonus for keeping residual flexible
            score -= 2.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with less residual among fitting bins
        score += 0.05 * bin_residual as f64 / fitting_bins_count as f64;
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidation into existing space rather than opening new bins.
    if open_bins_count > 0 {
        score += 0.03 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    // or open bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when existing fits are bad.
        score += 18.0;
        // Relax penalty if the current item is large and open bins are tight.
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 14.0 * tightness;
        // Early in the stream, opening bins is cheaper.
        score -= 6.0 * (1.0 - progress);
        // If the next item is large, having a fresh bin helps.
        if next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mild non-linear coupling of post-residual with progress: leftover space
    // is penalized more heavily later in the stream.
    score += 0.02 * (post_residual as f64).powf(1.3) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // early on, prefer tight fits less aggressively; later, penalize residual sharply
    let progress_coupling = norm_pr * norm_pr * (1.0 + progress) * cap;
    score += 0.5 * progress_coupling;

    // Reward near-perfect fits via smooth residual trough
    score -= 30.0 * (1.0 - norm_pr).powi(8) * (1.0 + progress);

    // Last-chance bin: strong bonus to use it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Many open bins: prefer reusing existing bins over opening new ones
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= 10.0 * open_norm * (1.0 - norm_pr);

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 15.0 * tight * tight;
    } else if next_item_size > 0 {
        // next item cannot use leftover: penalize large dead space
        score += 8.0 * norm_pr * norm_pr * cap * 0.1;
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmenting)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: make it moderately unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 + progress) - 5.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small dead space is good.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity wasted

    // Penalize dead space superlinearly, but only beyond a "useless" threshold.
    if post_residual > 0 && post_residual < 10 {
        // tiny sliver: almost unusable -> big reward for having filled the bin
        score -= 12.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect closure
    } else {
        // dead space penalty grows with squared fraction
        score += frac * frac * 30.0;
    }

    // Harmonic classes via integer division of post_residual into buckets of 10
    let class = post_residual / 10;
    score -= class as f64 * 1.5; // larger residual classes slightly preferred over slivers

    // Lookahead coupling: does the next item fit in the residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            // residual remains useful for the known next item -> strong reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + slack / cap * 10.0;
            // exact harmonic match (next item fills residual to a small class)
            if post_residual - next_item_size < 10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual; penalize proportionally to overshoot
            let over = (next_item_size as u32 - post_residual) as f64;
            score += (over / cap).min(1.0) * 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: an empty bin has full residual; make it attractive
    // only when the item is large or open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.5 {
            score -= 10.0 * (item_frac - 0.5) * 2.0; // big items prefer fresh bins
        } else {
            score += 8.0; // small items should fill existing bins
        }
        // if open bins are nearly full on average, opening fresh is fine
        score -= (mean_residual / cap).min(1.0) * 4.0;
    }

    // Prefer consolidating into bins below mean residual (tighter bins first)
    score += (post - mean_residual) * 0.05;

    // Early in the stream, be slightly more willing to open bins (better global packing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 3.0;
    }

    // Modulo harmonic bonus: residuals that are multiples of common item sizes (10s)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything (<= 10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual <= 20 {
        // Small usable gaps are risky: they may become dead space later.
        score += 6.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but still
    // valid), using a non-linear bonus.
    if post_residual > 0 {
        score -= 30.0 * (1.0 - (post_residual as f64 / 60.0)).powi(3).max(0.0);
    } else {
        score -= 50.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 40.0).max(0.0);
    }
    // If next item does NOT fit in post residual, mild penalty for creating
    // a gap the lookahead cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over spreading; makes opening new bins less attractive.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: it has the largest residual; make it
    // attractive only when the current item would leave a big awkward gap
    // in existing bins, i.e. when mean residual is small relative to item.
    if bin_residual == bin_capacity {
        // Baseline: new bin costs a fixed opening premium.
        score += 25.0 + open_bins_count as f64 * 1.5;
        // But if no existing bin fits well (this bin barely fits), allow it.
        if item_size as f64 > mean_residual + 5.0 {
            score -= 30.0;
        }
        // Late in the stream, prefer closing out bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild alignment with mean residual: bins whose residual deviates far
    // below the mean are more precious; penalize wasting them.
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }
    // Next item does NOT fit this bin's remainder: penalize proportionally to wasted lookahead.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 30.0 * (-post_residual as f64 / 20.0).exp();

    // Penalize leaving residuals that are likely dead space (small, unusable chunks).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins that are already below-average filled
    // (keep tight bins tight, spread usage across emptier bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 90.0 - 70.0 * poor_fit
            + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Late in the stream: consolidation matters more, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize large dead space quadratically.
    if post_residual > 0 {
        score += 0.012 * (post_residual as f64).powi(2);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but relax penalty late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 - 4.0 * progress;
        // If no open bin fits tightly, new bin is more attractive.
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward large gaps.
            if post_residual > 0 && post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (concentrate fullness) when many bins are open.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.05 * residual_diff;

    // Slight preference to fill bins that have been open a while (implicit via
    // many open bins): discourage spreading when open_bins_count is large.
    score += 0.03 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as it approaches unusable range
    let waste_frac = post / cap;
    score += 12.0 * waste_frac * waste_frac * cap;

    // Reward tight fits (small post_residual) with a smooth quadratic discount
    score -= 18.0 * (1.0 - waste_frac).powi(3);

    // Stream progress coupling: later in stream, prefer filling existing bins tightly
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 5.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            // penalize if post_residual is dead space relative to next item
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's already "settled"
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets
    let residue_class = (post_residual % 10) as f64;
    // Dead-space penalty if post_residual is small but not zero (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * residue_class;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0; // chained perfect fit
        } else if gap < 10 {
            score += 10.0; // would create a sliver next step
        } else {
            score -= 15.0 * (gap as f64 / bin_capacity as f64);
        }
    }
    // Next item slightly larger than residual: this bin is a dead end for it
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Integer-division thresholds: post_residual in [10,20) is prime reuse zone
    let class = post_residual / 10;
    score -= match class {
        0 => 25.0,
        1 => 15.0,
        2 => 5.0,
        3 => 0.0,
        4 => 5.0,
        _ => 10.0,
    };

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when few bins fit and item is large
    if bin_residual == bin_capacity {
        let frac_fit = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 1.0 };
        let pressure = item_size as f64 / bin_capacity as f64;
        score = 110.0 - 60.0 * (1.0 - frac_fit) * pressure - 20.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Mild consolidation pressure: prefer bins tighter than the mean residual
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is maximally rewarded.
        score -= 60.0;
    } else {
        // Favor tight fits: reward small positive residuals.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // Penalize residuals that cannot hold the lookahead item (potential future dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 8.0;
    }
    // Reward residuals that can exactly or nearly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= slack.max(0.0).min(20.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins discourage opening another, encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.5 * progress);
    score += pressure * 0.2;

    // New-bin candidate handling: make it unattractive unless open bins are very fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * fragmentation.min(1.0);
    }

    // Mild alignment with mean residual: prefer bins below mean (need filling more).
    score -= (mean_residual - post_residual as f64).clamp(-30.0, 30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is an excellent chaining placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves some slack: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack * 2.0;
        } else {
            // Next item cannot use this bin's remainder: penalize large dead space,
            // scaled by how large the leftover is relative to the next item.
            let waste = (post_residual as f64) - (next_item_size as f64);
            if waste > 0.0 {
                score += (waste / next_item_size as f64) * 30.0;
            }
        }
    }

    // Penalize creating small unusable residuals (dead space) that no item
    // in the typical range can exploit.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // filling a bin that is already below-average residual tightens the pool.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last chance: if this is the only bin that can fit the item, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it attractive only when the item is large (poor fit elsewhere),
    // otherwise discourage opening new bins while good fits exist.
    if bin_residual == bin_capacity {
        if item_size >= 60 {
            score -= 50.0; // large items start fresh bins readily
        } else {
            score += 80.0; // small items should prefer existing bins
        }
        // As the stream progresses, be slightly more willing to open bins
        // (residuals in existing bins become fragmented).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 40.0;
    }

    // Slight preference for keeping the number of open bins manageable:
    // with many open bins, favor consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Reward near-perfect packing when residual is small.
    if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 25 {
        score -= 6.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Penalize dead space that nothing can use (min item size 1, but typical small items).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain;
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap just smaller than the next item (wasted for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin proportionally to
    // how many open bins could fit and how much mean residual is idle.
    if bin_residual == bin_capacity {
        let idle = mean_residual.max(0.0) / bin_capacity as f64;
        score += 25.0 + 15.0 * idle + 2.0 * open_bins_count as f64;
        // But if the item is large and mean residual is small, opening is fine.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to keep residual distribution balanced: avoid bins far below mean.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.05 * dev;
        }
    }

    // Time horizon: early on, slightly prefer spreading load (keeps options open);
    // late, prefer tight packing (already rewarded above).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual;
    let next = next_item_size as f64;
    let mut score = pr;

    // Non-linear penalty for residual far from mean (fragmentation)
    let dev = pr - mean_r;
    score += 0.35 * dev * dev / cap;

    // Smooth progress coupling: later in stream, penalize large residuals more
    let p2 = progress * progress;
    score += (0.5 + 1.5 * p2) * pr * pr / cap;

    // Reward tight fits (small post_residual) with lookahead match
    if next > 0.0 {
        let gap = (pr - next).abs();
        score -= (1.0 - progress) * (cap - gap) / cap * (item_size as f64) / 10.0;
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * progress;
    }

    // Slight penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: prefer opening early, avoid late fragmentation
    if bin_residual == bin_capacity {
        score += pr - (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (post_residual == 0) strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes: residuals divisible by 10 are "usable" in classic C=100 streams.
    let harmonic_class = post_residual % 10;
    score += harmonic_class as f64 * 1.5;

    // Integer-division thresholds on post_residual: dead zones (0 < r < 10) penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Mid-range residual usable by typical items (>= 20) rewarded.
    if post_residual >= 20 {
        score -= 3.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or well here -> reward.
            let slack = post_residual - next_item_size;
            score -= 8.0 - (slack as f64) * 0.15;
            if slack == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit: mildly penalize wasting this bin's remaining space.
            score += 4.0;
        }
        // Harmonic class of next item size mod capacity fractions.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bonus: only fitting bin -> keep item out of a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer open bins unless current bin is nearly full or
    // this placement would strand too much space while open bins are plentiful.
    if bin_residual == bin_capacity {
        // New bin: baseline score = capacity - item; discourage if open bins exist with room.
        score += open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 && post_residual > 50 {
            score += 25.0;
        }
        // Early stream: opening bins is cheap-ish.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mean-residual coupling: avoid placing into bins far from mean (fragmentation control).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Prefer filling bins that are already low on residual (tight fit preference).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // General dead-space curve: quadratic penalty for small post_residual
    // (wasted potential), softened for large residuals.
    let pr = post_residual as f64;
    score += 40.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Reward tight fits strongly.
    let tightness = 1.0 - pr / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open bins pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last chance bin: strong reward if this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual < next_item_size {
        // next item cannot use this residual: penalize small leftovers more
        score += 8.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Prefer filling bins closer to mean residual (balance preservation).
    score += 0.3 * (pr - mean_residual).abs();

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly so it only wins on bad fits.
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Perfect chain: next item fits exactly into the residual.
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // exact two-item fill
            }
        } else {
            // Next item would not fit here: penalize large dead residuals that can't chain.
            let excess = (nxt - post) / bin_capacity as f64;
            score += 8.0 * excess;
        }
        // Coupling with mean residual: prefer bins that deviate favorably from the average.
        let dev = post - mean_residual;
        score -= 0.05 * dev;
    } else {
        // Last item: minimize residual as tightly as possible.
        score -= 15.0 / (1.0 + post_residual as f64);
    }

    // Penalize very small unusable residuals (dead space), non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // no open bin offers a good fit or the fit here would be wasteful.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when the item fits poorly in existing bins (high open count pressure)
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = score.max(0.0) + 30.0 - 25.0 * fit_ratio - 10.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 15.0; // opening fresh is fine if alternatives are scarce
        }
    }

    // Mild time decay: later in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into this bin.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind (wasted capacity).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * dead * (1.0 - dead);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 6.0;
            // Perfect chain: next item exactly fills the remainder.
            if next_item_size as u32 == post_residual {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; penalize small leftovers that strand the next item.
            let stranded = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 4.0 * stranded;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it only
    // when no open bin offers a decent fit (fit_ratio low) or when open bins are
    // already crowded with residual space below the item size.
    if bin_residual == bin_capacity {
        // Baseline cost of consuming a fresh bin.
        score += 5.0;
        // If existing bins are mostly full (low mean residual relative to item),
        // opening a new bin is fine.
        if mean_residual < item_size as f64 * 0.9 {
            score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // If many bins could fit the item, discourage the new bin.
        if fitting_bins_count > 2 {
            score += 6.0;
        }
    }

    // Mild preference to consolidate into bins whose residual is close to the mean,
    // keeping the bin pool balanced.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Slight bonus for using existing bins as the pool grows.
        score -= 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Penalize tiny residuals more sharply as stream progresses (dead space)
    let dead = (1.0 - norm_pr).powi(3);
    score += 40.0 * progress * dead;

    // Reward tight fits (small post_residual) with a smooth quadratic term
    score -= 12.0 * norm_pr * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - (nxt / cap));
        } else {
            score += 6.0 * (nxt / cap);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-averse unless residuals are large
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities (e.g. multiples of 10, 5, 25) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 5 == 0 { bonus += 2.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        score -= bonus;
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Dead-space penalty: residuals too small for any plausible item
    // (below the minimum plausible item size band) are wasted space.
    let small_floor = (cap_f * 0.05).floor() as u32;
    if pr > 0 && pr < small_floor.max(1) {
        score += 15.0 * (1.0 - pr as f64 / small_floor.max(1) as f64);
    }

    // Lookahead: reward if next item fits exactly into post-residual,
    // penalize if next item barely fails to fit.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            let miss = (next_item_size - pr) as f64;
            score += 5.0 * (miss / cap_f).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    let dev = (bin_residual as f64 - mean_residual) / cap_f;
    score += 8.0 * dev.max(0.0);
    score -= 3.0 * (-dev).max(0.0);

    // New-bin candidate: make it attractive only when the item is large
    // relative to capacity or open bins are all loose.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap_f;
        let tight_open = if open_bins_count > 0 {
            (mean_residual < item_size as f64 + next_item_size as f64) as f64
        } else { 1.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * item_frac * tight_open;
        score += 10.0 * (1.0 - progress); // early stream: opening bins is fine
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // fresh bin can host a companion item
        }
    }

    // Slight tie-breaker toward filling fuller bins.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: small non-zero post_residuals are hard to fill later.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // smallest item possible is 1; a gap that is very small relative to capacity is "dead"
        let deadness = 1.0 - (pr / 30.0).min(1.0);
        score += deadness * deadness * 40.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward using bins with small residuals (best-fit flavor) beyond raw post_residual.
    score += (bin_residual as f64 - post_residual as f64) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: empty bin. Prefer it when open bins have lots of residual
    // fragmentation or the fit leaves a bad gap; penalize mildly otherwise to favor packing.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        if post_residual as f64 > mean_residual {
            score += 8.0; // leftover bigger than mean residual: still reusable
        }
        // If no open bin fits well (this call only happens for the new bin when compared),
        // the base post_residual (= cap - item) already reflects remaining space.
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> allow.
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward proportional to how well next item uses the gap
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the gap -> dead space risk
        score += (1.0 - (post_residual as f64 / 30.0).min(1.0)) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let post = post_residual as u32;
        let nxt = next_item_size;

        // Perfect chain: next item exactly fills remaining space
        if post == nxt {
            score -= 60.0;
        } else if post >= nxt {
            // Next item fits: reward tightness of the follow-up placement
            let slack_after_next = post - nxt;
            score -= 40.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item does not fit in post_residual: penalize by the shortfall
            let shortfall = nxt - post;
            score += (shortfall as f64).min(50.0);
        }

        // Coupling with mean residual: bins far below mean residual are "wasted" capacity
        let dev = mean_residual - post as f64;
        if dev > 0.0 {
            score += 0.3 * dev;
        } else {
            score += 0.1 * dev; // slightly reward being tighter than average
        }
    } else {
        // No lookahead available: fall back to tight-fit preference
        score += 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling nearly-full bins over sparsely-used ones
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Early in the stream, be more willing to open fresh bins (cheap future flexibility)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus a discount that decays with stream progress
        score = bin_capacity as f64 * 0.5 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin always accommodates the lookahead item
        }
        if fitting_bins_count <= 1 {
            score -= 10.0; // no good alternative exists
        }
    }

    // Many open bins: discourage spreading across too many bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 18.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize small dead space that nothing (>=1) can use, less so late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 14.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: reward if next item fits the post residual, penalize if it nearly fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual && post_residual > 0 {
            score += 6.0 * (1.0 - post_residual as f64 / bin_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidation onto fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    let pressure = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln().max(0.0);
    score -= 8.0 * fullness * pressure;

    // Deviation from mean residual: prefer bins below mean residual (fuller than average).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // New empty bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let bad_open_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && tightness < 0.5 && next_item_size > post_residual);
        if bad_open_fit {
            score -= 10.0 + 20.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = r / cap;
    let t = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear coupling: quadratic in normalized residual, modulated by stream progress
    score += 12.0 * (1.0 - x) * (1.0 - x) * (0.5 + t);

    // Reward near-perfect fits with cubic term
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Penalize dead space relative to mean residual
    score += 0.3 * (r - mean_residual) * (1.0 - t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            let slack = (r - nx) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 5.0;
        }
    }

    // Mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 6.0 * t;
    }

    // Density of open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 5 classes of 20.
    let class = post_residual / 20;
    // Reward landing exactly on a class boundary (perfect harmonic fit).
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    // Penalize small "dead" residuals that few future items can use.
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // modulo harmony: next item divides post residual evenly
            if post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this bin's remainder -> dead space risk
            score += (next_item_size - post_residual).min(30) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-ish unless open bins look bad.
    if bin_residual == bin_capacity {
        score = 45.0 - 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 5.0; // big next item benefits from a fresh bin
        }
        if mean_residual > 40.0 && fitting_bins_count > 0 {
            score += 10.0; // plenty of room already open; discourage new bin
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose residual is a clean fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac * 10.0).fract() * 0.5;

    // Slight time decay: late in stream, squeeze harder into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 2.0 * (post_residual as f64 / 100.0);

    // Prefer filling bins with low mean residual spread (tighter packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest item (size 1..9)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Gaps too small for the next item waste lookahead opportunity.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 3.0;
        // But opening a fresh bin is attractive when mean residual is fragmented.
        score -= mean_residual * 0.4;
    } else {
        // Mild bonus for using already-open bins as pressure rises.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
