pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible future item can use.
    let min_item = 1.0f64;
    if post_residual as f64 > min_item {
        let usable = if next_item_size > 0 {
            (next_item_size as f64).min(bin_capacity as f64)
        } else {
            40.0
        };
        if (post_residual as f64) < usable {
            score += 0.35 * (usable - post_residual as f64);
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // If next item just barely misses post_residual, slight penalty for stranding space.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when alternatives exist,
    // unless the fit in existing bins would be terrible.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base_penalty = 30.0 + 40.0 * (1.0 - progress);
        score += base_penalty;
        // If the item is large and no open bin fits well, new bin is less bad.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        // Many open bins with high mean residual: prefer filling those instead.
        if open_bins_count > 0 {
            score += 0.15 * open_bins_count as f64;
            if mean_residual > item_size as f64 {
                score += 10.0;
            }
        }
    }

    // Mild preference for bins with residuals close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    // Early in stream: keep bins compact to preserve flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: dead-space cost, non-linear in post residual
    let mut score = post * (1.0 + 0.8 * x * x);

    // Smooth polynomial coupling with stream progress: late in stream, tighter packing
    let coupling = (0.6 + 1.4 * progress) * x * (1.0 - x);
    score -= 4.0 * coupling * cap;

    // Perfect fit reward (smooth, non-piecewise)
    score -= 12.0 * (-x * 8.0) * (1.0 - (-x * 8.0));

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize if post residual can't fit next item but residual could
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt && bin_residual as f64 >= nxt {
            score += 6.0 * (1.0 - post / nxt);
        } else if post >= nxt {
            score -= 4.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // Discourage opening new bins when many open bins with slack exist
    let new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        score += 0.05 * mean_residual;
    } else {
        // Prefer bins with residual close to item size (tight fit)
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
        score -= 3.0 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual in small harmonic classes)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo-class logic: residual classes that commonly pair with typical item sizes
    let pr = post_residual;
    let pr_mod_10 = (pr % 10) as f64;
    score -= (10.0 - pr_mod_10) * 1.5; // residuals just above multiples of 10 are more reusable

    // Integer-division thresholds: residual large enough for common item sizes (>=10)
    if pr >= 10 {
        score -= 15.0 + (pr / 10) as f64 * 2.0;
    } else if pr > 0 {
        // dead space: unusable for any item in [1,100] unless tiny items exist
        score += 40.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 35.0;
            // exact pairing: post_residual - next_item_size small
            let gap = pr - next_item_size;
            if gap <= 5 { score -= 25.0; }
        } else {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score -= 100.0; // only one alternative; keep new bin as viable option
        }
        // early stream: opening bins early is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
    }

    // Prefer filling bins whose residual deviates from the mean (reduce fragmentation)
    score -= (mean_residual - bin_residual as f64).abs() * 0.3;

    // Slight preference for bins with larger residual overall (consolidate)
    score -= bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 0.35 * (25.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit bonus: reward using most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins,
    // but allow opening a new bin when remaining open bins are poor fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this bin's fit is bad
    // and the next item might need the leftover space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 10.0;
        }
        if post_residual as f64 >= mean_residual {
            score -= 5.0;
        }
    }

    // Lookahead: keep gaps large enough for the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Mild deviation from mean residual: prefer bins with less residual left.
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 45.0 - 3.0 * slack;
        } else {
            score -= 10.0 / slack.sqrt();
        }
    }

    // Penalize dead space too small for the lookahead item (unusable residue)
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += (next_item_size as f64 - waste) * 0.4;
    }

    // Tight fit reward for current item
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Relative to mean residual: prefer filling bins below average residual
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Early in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when it enables a good 2-step chain
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 + 20.0 * progress;
        } else {
            score += 15.0 - 10.0 * progress;
        }
    }

    // Prefer consolidating into fewer bins when many are open
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small post-residuals that are too small for typical future items
    // (dead space), but reward exact/near-exact closures.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 25.0; // perfect closure is excellent
    } else if pr < 10.0 {
        score -= 6.0; // nearly closed, likely unusable anyway
    } else {
        // dead-space penalty grows for awkward mid-size leftovers
        let awkward = 1.0 - ((pr / cap) * 4.0 - (pr / cap).powi(2) * 4.0).abs();
        score += 4.0 * awkward;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr - ni).abs() < 0.5 {
            score -= 30.0;
        } else if ni <= pr {
            let nest = ni / pr.max(1.0);
            score -= 10.0 * nest;
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 3.0 * (ni / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer open bins unless the item is large and
    // open bins are fragmented (high mean residual with many bins).
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Early stream: opening fresh bins is cheap; late stream: consolidate.
        let new_bin_cost = 20.0 + 25.0 * t - 15.0 * fragmentation;
        let big_item_bonus = if item_size as f64 > 0.6 * cap { 8.0 } else { 0.0 };
        score += new_bin_cost - big_item_bonus;
    }

    // Global pressure: many open bins with high mean residual -> consolidate into
    // bins below mean residual (prefer emptier bins to balance load).
    let below_mean = mean_residual - pr;
    score += 0.05 * below_mean;

    // Mild preference for bins with residual close to item size (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 8.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling: wasted-space weight grows super-linearly with progress
    let waste_weight = 0.4 + 2.2 * progress * progress + 1.3 * progress * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.15;

    // Tight fit reward: strong non-linear bonus for small residuals, amplified late in stream
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Reward filling relative to current mean residual state
    if (item_size as f64) > mean_residual * 0.85 {
        score -= 3.0 + 4.0 * progress;
    }

    // Last-chance bin: strong reward, smooth polynomial ramp with progress
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress * (1.0 - progress) * 4.0 * progress;
    }

    // Lookahead coupling: favor leaving room for the next item via smooth interaction
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = (pr - nx).max(0.0) / cap;
        score += 6.0 * compat * compat * (0.5 + progress);
        if pr >= nx && pr - nx <= 5.0 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: penalize mildly early, more when open bins are scarce or fit is decent
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        let decent_fit = if fitting_bins_count > 0 { (pr / cap) } else { 1.0 };
        score += 4.0 + 10.0 * progress - 6.0 * scarcity - 5.0 * (1.0 - decent_fit) * (1.0 - decent_fit);
        if next_item_size > 0 && next_item_size as f64 >= pr * 0.9 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: residual classes near zero are valuable completions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Harmonic class of post_residual: exact division thresholds (0, 25, 50, 75)
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    let three_quarter = (bin_capacity / 4) * 3;

    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= quarter {
        score -= 25.0 * (1.0 - frac * 4.0);
    } else if post_residual <= half {
        score -= 8.0 * (1.0 - (post_f - quarter as f64) / half);
    } else if post_residual <= three_quarter {
        score += 6.0;
    } else {
        score += 12.0; // large dead space
    }

    // Modulo-based harmonic bonus: residuals that are multiples of common item sizes
    // (10/20/25/50) leave reusable space.
    let reusable = [10u32, 20, 25, 50, 100];
    for m in reusable.iter() {
        if *m > 0 && post_residual % m == 0 && post_residual > 0 {
            score -= 3.0;
            break;
        }
    }

    // Lookahead: favor bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap_f);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is an early step; otherwise penalize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_f).abs();
        if open_bins_count > 0 {
            score += 18.0 + 10.0 * fragmentation / cap_f - 15.0 * progress;
        } else {
            score -= 50.0; // must open first bin
        }
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Tie-break noise-free deterministic micro-adjustment via integer division.
    score -= (post_residual / 8) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

