    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only when it genuinely beats existing fits.
        score += 25.0 + 12.0 * pressure + 20.0 * progress;
        // If the next item would fit into the leftover of this placement, opening is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // If no open bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Existing bin: reward leaving space compatible with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 {
            score += 6.0; // placement strands the lookahead item
        }
        // Favor bins with below-average residual (keep large residuals flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero dead space is ideal.
    if post_residual == 0 {
