    // tighter fits; placing there keeps large-residual bins flexible.
    let res = post_residual as f64;
    score -= (mean_residual - res) * 0.4;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Late in the stream, tighten packing (avoid opening new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // New-bin candidate: make empty bins moderately attractive only when the
    // item would leave a very awkward residual in existing bins.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
    }

    // Small structural bonus for many open bins: encourage consolidation.
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
