    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly host future items (sizes 1..100)
    if post_residual > 0 {
        let usable = if next_item_size > 0 && (next_item_size as u32) <= post_residual { 1.0 } else { 0.35 };
        score -= 6.0 * usable * (post_residual as f64).sqrt();
    } else {
        // Perfect closure is highly desirable
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // chaining here is valuable; otherwise mild penalty.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 * (next_item_size as f64) / 100.0;
        } else {
            let gap = (next_item_size as u32 - post_residual) as f64;
            score += 0.08 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
