    // fits are poor. Penalize the fresh bin, more so when good fits exist.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { 22.0 } else { 0.0 };
        score += pressure + 0.05 * (open_bins_count as f64);
        // Early in the stream, opening bins is cheaper (build a portfolio)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    }

    // Global fragmentation pressure: if mean residual is low, conserve open-bin space
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += 0.10 * (mr - post_residual as f64).abs().min(50.0);

    // Prefer bins whose residual is close to the item (minimal waste)
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
