    // Non-linear polynomial coupling of post_residual with progress
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    score += 12.0 * prn * prn * (1.0 - progress) - 8.0 * prn * p2;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 6.0 * (1.0 - prn) * (1.0 - prn) * (0.4 + 0.6 * progress);

    // Penalize waste relative to bin's original residual (dead-space creation)
    score += 3.0 * (r - pr) / cap * (pr / cap);

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && r < cap {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: discourage spreading; prefer filling existing ones
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (r / cap));

    // Lookahead coupling: if next item fits well into the post residual, favor this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = pr - nx;
        if slack >= 0.0 {
            score -= 5.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 2.0 * (-slack / cap);
        }
    }

    // Deviation from mean residual: prefer bins below mean (denser bins) mildly
    score += 1.5 * ((r - mean_residual) / cap).clamp(-1.0, 1.0);

    // New-bin candidate: make empty bins unattractive unless residuals are all tiny
    if r >= cap - 0.5 {
        score += 25.0 - 20.0 * (mean_residual / cap).max(0.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: how well it matches typical small items (mod classes)
        let pr = post_residual;
        // Class-1: residual divisible by common small item sizes -> likely reusable
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                score -= 6.0 + (m as f64) * 0.15;
            }
        }
        // Dead-zone penalty: residuals in awkward ranges (1..9, 11..14, 16..19, 21..24)
        let awkward = match pr {
            1..=9 => 1.0,
            11..=14 => 0.7,
            16..=19 => 0.6,
            21..=24 => 0.5,
            26..=29 => 0.4,
            _ => 0.0,
        };
        score += awkward * 12.0;

        // Harmonic threshold: integer division classes of capacity
        let cap_class = bin_capacity / 4; // 25
        if pr < cap_class {
            score += (cap_class - pr) as f64 * 0.35; // small leftovers are risky
        }

        // Lookahead coupling: can next item fit exactly into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size < pr {
                let slack = pr - next_item_size;
                score += slack as f64 * 0.5;
                // harmonic bonus if slack lands on a good class
                if slack % 10 == 0 || slack % 25 == 0 {
                    score -= 8.0;
                }
            } else {
                // next item cannot fit here: residual stranded relative to lookahead
                score += (next_item_size - pr) as f64 * 0.2;
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer tighter bins generally (best-fit bias)
    score -= (bin_residual as f64 - post_residual as f64) * 0.1;

    // New-bin candidate handling: only open a new bin when open bins are poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 60.0 + open_bins_count as f64 * 2.0;
        // if current bin would leave a bad residual, new bin becomes attractive
        let pr = post_residual;
        if pr > 0 && pr < 10 {
            score -= 45.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // if next item is large, a fresh bin is useful
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild preference toward bins below mean residual (tighter packing)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong discount as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit: near-free placement.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Strict dead-space penalty: residuals too small for typical items are wasted.
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 90.0 * (dead_threshold - post_residual as f64 + 1.0);
    }

    // Penalize residuals that no plausible item (>= ~10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Bonus if the next item exactly fits the post residual (chaining fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item won't fit here; small penalty for leaving large leftovers.
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, be more tolerant.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    score += pressure * (post_residual as f64) * 0.08;

    // Prefer bins with below-average residual (fill emptier-of-space bins first,
    // keeping large residuals consolidated).
    score += 0.25 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: default moderate score; becomes attractive only when
    // this item would leave a large awkward gap in every existing bin.
    if bin_residual == bin_capacity {
        let awkward_elsewhere = if fitting_bins_count > 0 {
            // would any open bin give a good fit?
            0.0
        } else {
            -60.0
        };
        let base = 55.0 + 0.35 * (item_size as f64) + 4.0 * (open_bins_count as f64).min(20.0) as f64;
        score = base + awkward_elsewhere;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer minimal dead space after placement.
    score += (post_residual as f64 / cap) * 40.0;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can fit here: reward closeness to perfect fill.
            score -= 25.0 * (1.0 - diff / cap);
            if diff < 1.0 {
                score -= 30.0; // perfect 2-step fill
            }
        } else {
            // Next item cannot use this residual; penalize proportionally to waste.
            score += 12.0 * (1.0 - (post_residual as f64 / cap));
            // If residual is tiny and next item is large, dead space is acceptable-ish.
            if post_residual < 10 {
                score -= 5.0;
            }
        }
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Among many options, mild preference for tighter fits (already in post_residual).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity && item_size > 0 {
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else {
            // Discourage opening a new bin when an open bin can fit the item,
            // unless the item is large and best-fit residual is poor.
            score += 45.0;
            if item_size as f64 > 0.7 * cap {
                score -= 20.0; // large items fine in fresh bins
            }
            if next_item_size > 0 && (next_item_size as f64 / cap) > 0.6 {
                score -= 10.0; // large lookahead item pairs well with fresh bin
            }
        }
    }

    // Stream progression: later in the stream, be more conservative about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (post_residual as f64 / cap);

    // Too many open bins: prefer consolidating into fewer bins.
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty scaled by capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tight * tight * (bin_capacity as f64);

    // Reward filling bins that are already mostly full (small residual before placement).
    let pre_fullness = (bin_capacity as f64 - bin_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * pre_fullness * pre_fullness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        // Extra reward if the leftover would still hold the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead coupling: penalize placements whose leftover is too small for the
    // next item but "wasted" (dead space), reward leftovers that exactly fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // dead space relative to next item
            score += 0.08 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: if mean residual across open bins is large, we have plenty of
    // room — mildly discourage spreading into fresh/partial bins with poor fits.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: late in the stream, closing out bins matters more; reward
    // placements that leave near-zero residual harder.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tight * tight * (bin_capacity as f64);

    // Many open bins: prefer consolidating into existing ones rather than new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins unless no good fit exists.
        let open_pressure = open_bins_count as f64;
        let mut new_bin_score = 25.0 + 2.0 * open_pressure;
        // If the next item fits perfectly in the fresh bin, soften the penalty.
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= post_residual as f64 {
            new_bin_score -= 8.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a bin
        }
        score = new_bin_score + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, non-linearly
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack, late in stream punish it more.
    let coupling = 1.0 + 1.4 * progress * progress + 0.8 * progress * (1.0 - progress);
    score *= coupling;

    // Reward tight fits (small post_residual) with a smooth bonus.
    let tightness = (cap - pr) / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 + 8.0 * progress;
    }

    // New empty bin candidate: penalize mildly, but less if this bin's
    // residual would be unusable for the lookahead item.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let mut new_penalty = 14.0;
        if next_item_size > 0 {
            let ni = next_item_size as f64;
            if pr < ni {
                // this placement leaves no room for the next item anyway;
                // opening a fresh bin is more attractive
                new_penalty -= 6.0 + 4.0 * progress;
            } else {
                new_penalty += 4.0 * (ni / cap);
            }
        }
        if open_bins_count > 0 && fitting_bins_count > 1 {
            new_penalty += 6.0;
        }
        score += new_penalty;
    }

    // Discourage fragmenting bins whose residual deviates far from mean
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev * (0.5 + progress);

    // Lookahead synergy: reward leaving space exactly usable by next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits (small post_residual)
    let tightness = (bin_capacity as f64 / 4.0) - post_residual as f64;
    if tightness > 0.0 {
        score -= 0.35 * tightness;
    }

    // Strong bonus: perfect fit / exact fill
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic class logic: classify post_residual into dead-space classes
    // via capacity fractions and modulo arithmetic.
    let cap_quarter = bin_capacity / 4; // 25
    let cap_eighth = bin_capacity / 8; // 12
    let dead_class = post_residual % cap_eighth.max(1);
    // Small dead class (post_residual near a multiple of 8..12 is more reusable)
    score -= 0.10 * (cap_eighth.max(1) - dead_class) as f64;

    // Penalize residuals in the "useless band": too small for typical items
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score += 100.0;
    }
    // Threshold bands on post_residual: 1..10 nearly dead
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let lookahead_waste = post_residual - next_item_size;
            score -= 0.5 * (1.0 - (lookahead_waste as f64 / bin_capacity as f64));
            if lookahead_waste <= 5 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, worse if gap is small
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 0.6 * gap as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // Cheaper to open new bins early in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // More open bins => new bin is more expensive
        score += 1.5 * open_bins_count as f64;
        // If mean residual is large, prefer reusing existing bins
        score += 0.15 * mean_residual;
    } else {
        // Reusing bins: mild preference when bin is already fairly full
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // Mean-residual coupling: bins far from the mean residual get a nudge
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Modulo threshold on item_size: items in "awkward" classes (e.g. >50, odd)
    // prefer tighter bins
    if item_size % 2 == 1 && post_residual % 2 == 0 {
        score += 1.0;
    }
    if item_size > bin_capacity / 2 && post_residual < item_size / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..=100)
    // are pure waste. Anything <= 9 is unusable unless another item already
    // fits perfectly; treat small-but-nonzero gaps as heavy dead space.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += (dead_threshold - post_residual as f64 + 1.0) * 12.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing density.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // attractive when open bins are heavily fragmented or the fit here is bad.
    if bin_residual == bin_capacity {
        // Mild default penalty so existing bins with decent fits win.
        score += 15.0;
        // But relieve the penalty when many bins are open (fragmentation
        // pressure) or when this bin would leave a large unusable gap.
        let frag = open_bins_count as f64 / 8.0;
        score -= frag * 10.0;
        if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
            score -= 30.0;
        }
        // Lookahead: if the next item fits the residual of a fresh bin exactly,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 50.0;
        }
    }

    // Open-bins pressure: many open bins with scattered residuals -> prefer
    // consolidating into existing bins rather than opening more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 1.5;

    // Prefer bins whose residual is close to the item (best-fit core signal),
    // modulated by the mean residual across open bins.
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    let mean_gap = mean_residual.max(0.0);
    if mean_gap > 0.0 {
        score += (gap / mean_gap) * 3.0;
    }

    // Lookahead synergy: if the next item can exactly fill this bin's
    // post_residual, reward placing the current item here.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post_residual but would fit elsewhere,
    // slightly penalize leaving an awkward gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= bin_capacity {
        score += (post_residual as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill: perfect placement, strongly rewarded.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item,
    // scaled by how tightly the next item nests in the residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // tight nesting (slack near 0) gets the largest bonus
        score -= 3.0 - 2.0 * (slack / (1.0 + slack));
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Mildly discourage opening a brand-new bin when open bins can absorb the item.
    if bin_residual == bin_capacity {
        score += 2.0;
        // But if the new bin would leave a residual matching the next item,
        // opening it becomes attractive (chained pair in a fresh bin).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 6.0;
        }
    }

    // Coupling with mean residual: penalize leaving much more dead space
    // than the average open bin (fragmentation risk).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.4 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: raw post residual (waste minimization)
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early in stream, tolerate larger residuals; late in stream, punish them harder.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * 30.0 * norm_pr * norm_pr * (1.0 - norm_item);

    // Non-linear fit-quality term: cubic in normalized residual
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: reward residual that can still fit the next item,
    // penalize residuals that neither fit next item nor are small.
    if next_item_size > 0 {
        let fits_next = (pr >= norm_next * cap) as i32 as f64;
        score -= 15.0 * fits_next * (1.0 - (pr - norm_next * cap) / cap).abs();
        score += 10.0 * (1.0 - fits_next) * norm_pr;
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalty for opening new bins when many bins are open with usable space
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (open_bins_count as f64).ln1p() * (1.0 - progress);
        // but allow new bin if residuals across fleet are all tight
        score -= 15.0 * (1.0 - (mean_residual / cap).min(1.0));
    }

    // Mean residual alignment: prefer bins whose post residual moves fleet mean downward
    score += 5.0 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" classes (multiples of common item sizes / large chunks) are favored.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: near-perfect fit (tiny dead space) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Class B: post-residual large enough to host any future item (>= 80)
    if post_residual >= 80 {
        score -= 10.0;
    }

    // Class C: dead-zone penalty — residual too small for the smallest item (1)
    // but awkward (not a multiple of common sizes). Use modulo structure.
    let r = post_residual;
    if r > 0 && r < 10 {
        // tiny slivers: penalize more the smaller they are
        score += (10 - r) as f64 * 1.5;
    }
    // Modulo-harmonic bonus: residuals divisible by 10/20/25 pair well with
    // typical item granularities.
    if r % 10 == 0 && r > 0 {
        score -= 6.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 3.0;
    }
    if r % 25 == 0 && r > 0 {
        score -= 2.0;
    }

    // Coupling with lookahead: reward if next item fits exactly into post-residual
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size < r {
            let nxt_post = r - next_item_size;
            // prefer next placement that again leaves a harmonic residue
            if nxt_post <= 10 {
                score -= 10.0;
            } else if nxt_post % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here anyway; slight penalty for stranded space
            score += 3.0;
        }
    }

    // Last-chance bin: only one bin fits the item — strongly favor using it
    // over opening a new bin, scaled by how good the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let tightness = (bin_residual - item_size) as f64;
        score -= 20.0 + 0.2 * tightness;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are crowded (mean residual low) or many bins already open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual (full capacity) minus credits
        score -= 15.0;
        // If existing open bins have little room, a new bin is fine
        if mean_residual < 25.0 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If this bin is the last chance, new bin must lose
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild preference for tighter existing bins overall
    score -= 0.05 * (bin_residual as f64 - post_residual as f64);

    // Spread pressure: with many open bins, favor filling existing ones
    score += 0.02 * open_bins_count as f64 * (frac - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the smallest plausible item are pure waste.
    let min_item = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual == 0 {
        score -= 45.0; // perfect closure: zero waste
    } else {
        // Non-linear penalty on awkward mid-range gaps that few item sizes can use.
        let pr = post_residual as f64;
        let awkward = (pr - 50.0).abs() / 50.0; // gaps near half-capacity are flexible; extremes worse
        score += 8.0 * awkward * awkward;
    }

    // Reward tight fits (item fills most of the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // this is the only bin that fits; avoid opening a new bin
    }

    // --- Open-bin pressure ---
    // When many bins are open, prefer consolidating into them rather than spawning more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    score += 0.35 * pressure;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // New bin is attractive if no open bin offers a decent fit or all residuals are tiny.
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 1.15 {
            score -= 20.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    // --- Lookahead (k=2): favor bins whose leftover still fits the next item ---
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0; // leftover too small for the known next item
        }
    }

    // Mild tie-break toward bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            // Perfect match: next item exactly fills this bin.
            score -= 1000.0;
        } else if nxt <= post {
            // Next item fits; reward proportional closeness, penalize leftover waste.
            score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
            score += 0.15 * diff;
        } else {
            // Next item cannot fit here; penalize large unusable residuals relative to next item.
            score += 0.3 * (nxt - post).min(post);
        }
    }

    // Penalize post residual that is small but non-zero (dead space) — waste measure.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins already tighter than average are better targets.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer opening a new bin only when the item is a poor fit elsewhere.
    if bin_residual == bin_capacity {
        // Slight bias toward keeping items in open bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 - 30.0 * progress;
        if item_size > 50 {
            score += 10.0; // large items tolerate fresh bins
        }
    }

    // Prefer compacting into fewer bins when many bins are open.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual super-linearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.5) * 60.0;
    } else {
        score -= 40.0; // perfect fit bonus
    }

    // Perfect-fill potential: if next item could exactly fill post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap that the next item almost-but-not-quite fits.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let tight_exists = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual && next_item_size as f64 >= post_residual as f64 * 0.8);
        if tight_exists && fitting_bins_count > 0 {
            score += 45.0; // keep existing good fits, avoid bin proliferation
        } else {
            score -= 12.0; // poor fit elsewhere: fresh bin is fine
        }
        // Early in stream, opening bins is cheap-ish; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer filling bins below mean residual (lumpy consolidation).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    // Slight preference to use bins with many siblings open (consolidate load).
    score -= (open_bins_count.min(50) as f64) * 0.2;

    // Discardable tiny dead space threshold: residuals below 10 are near-worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Penalize large dead space quadratically, damped early in stream
    score += 8.0 * norm_pr * norm_pr * (1.0 - 0.4 * progress);

    // Reward tight fits: smooth coupling between item and residual
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 - norm_pr);

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual {
        score += 2.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild preference for consolidating into fuller bins
    score += 1.5 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize slightly unless residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "large"
    // residue classes (divisible structure) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward bins whose post_residual is a "harmonic" multiple: divisible by 10 or 20
    if pr > 0 && (pr % 10 == 0) {
        score -= 3.0;
        if pr % 20 == 0 {
            score -= 2.0;
        }
    }
    // Penalize tiny dead space classes (post_residual 1..=5) - unusable slivers
    if pr > 0 && pr <= 5 {
        score += 15.0;
    }
    // Penalize awkward mid-class residuals via integer division thresholds
    let class = pr / 10; // 0..=10
    match class {
        0 => score += 10.0,          // near-full bin, tiny leftover
        1 | 2 => score += 4.0,       // small awkward leftover
        3 | 4 | 5 => score -= 2.0,   // mid leftover, decent
        6 | 7 | 8 => score -= 4.0,   // large leftover, very reusable
        _ => {}                       // near-empty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward proportional to how snugly
        let slack = (pr - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 8.0;
        } else {
            score -= 4.0 / (1.0 + slack / 20.0);
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: mild penalty scaled by how much it overflows
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost; prefer it only
    // when no open bin offers a good harmonic fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 25.0; // huge item: fresh bin better
        }
    }

    // Spread-awareness: penalize bins far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Stream phase modulation: late in stream, prefer tighter packing
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * phase * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below min item size 10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable dead space penalty
    } else if post_residual < 20 {
        score += 25.0; // risky gap, only fits tiny items
    } else if post_residual < 35 {
        score += 8.0;  // moderately awkward gap
    } else {
        // Larger usable gaps are mildly rewarded relative to baseline
        score -= 5.0;
    }

    // Reward near-perfect fits (tight packing)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // and discourage opening new ones.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        score += 30.0 + pressure * 4.0;
        // Allow a new bin early in the stream or when nothing fits well
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing-bin reuse reward, scaled by crowding
        score -= 6.0 + pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 10.0; // leaves dead space after next item
        }
    }

    // Slight preference to fill bins with larger residuals when mean residual is high
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Stream progression: late in the stream, be more conservative about new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize unusable dead space.
    // Dead space = residual that no plausible future item (>=1) can use well.
    let dead = if post_residual > 0 && post_residual < 10 { post_residual as f64 * 4.0 } else { 0.0 };
    score += dead;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let perfect = post_residual as i64 - next_item_size as i64;
        if perfect == 0 {
            // This bin will be exactly filled by the next item: extremely desirable.
            score -= 60.0;
        } else if perfect > 0 && (perfect as u32) < 10 {
            // Next item fits leaving only small dead space.
            score -= 25.0 - perfect as f64 * 1.5;
        } else if perfect < 0 && (-perfect) <= 20 {
            // Next item almost fits: near-perfect two-item pairing.
            score -= 15.0 - (-perfect) as f64 * 0.4;
        } else if perfect > 0 {
            // Next item fits but leaves a large hole: mild penalty scaled by hole size.
            score += (perfect as f64) * 0.15;
        }
        // Bonus if next item fits at all in the post-bin.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    // (concentrate packing), penalize bins looser than the mean.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.35;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild opening penalty so we
    // prefer existing bins with decent fits, but allow opening when all open
    // bins would leave very small (dead-space) residuals.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 18.0;
        }
        // Late in the stream, avoid proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    // Slight preference to fill bins with many siblings (consolidation).
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize leaving dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // penalize leaving a residual just barely too small for next item
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // Time horizon: early in stream, be more open to opening new bins (score new bin lower);
    // late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base score, adjusted by progress and open bins
        score += 5.0 + progress * 25.0 + (open_bins_count as f64).sqrt() * 3.0;
    } else {
        // Existing bin: mild reward proportional to how full it already is
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= fullness * 10.0;
    }

    // Compare against global state: if mean residual is high, prefer bins below mean (balance)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Small bonus for using bins when many are open (avoid bin proliferation)
    if open_bins_count > 5 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening over time
    let mut score = pr * (1.0 + progress * norm_pr);

    // Non-linear coupling: penalize large residual more as stream progresses
    score += progress * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small normalized post residual) super-linearly
    score -= (1.0 - norm_pr).powi(3) * 10.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize crowded bin pools mildly, smooth in open_bins_count
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Dead-space avoidance: penalize residuals too small for typical items
    score += (norm_pr - (1.0 - norm_pr).exp()).abs() * 2.0;

    // Lookahead: reward leaving space for the next item, smooth interaction
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        let closeness = ((pr - nx) / cap).abs();
        score -= fit_next * (5.0 * (1.0 - closeness)) * (0.5 + progress);
        score += (1.0 - fit_next) * 3.0 * norm_pr;
    }

    // Mean residual context: prefer bins near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let pr = post_residual;

    // New-bin candidate: baseline cost of opening a fresh bin.
    // Slightly scaled by item size so big items lean toward new bins.
    if bin_residual == bin_capacity {
        let mut nb = cap * 0.85 + item * 0.15;
        // Late in the stream, opening new bins is relatively cheaper
        // (fewer chances to consolidate leftovers later).
        let t = step_index as f64 / (total_items.max(1) as f64);
        nb -= t * 5.0;
        return nb;
    }

    let mut score = pr as f64;

    // Dead-space penalty: leftover too small for the minimum item class
    // (harmonic class of width 10) is nearly unusable.
    if pr > 0 && pr < 10 {
        score += 18.0;
    } else if pr == 0 {
        // Perfect closure of a bin is ideal.
        score -= 20.0;
    }

    // Harmonic / modulo class logic on the leftover:
    // leftovers that are multiples of 10 align with the coarse size grid.
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the leftover?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward proportionally to how well the next item nests.
            let slack = (pr - next_item_size) as f64;
            score -= 8.0;
            if slack < 10.0 {
                score -= 6.0; // near-perfect two-item pairing
            }
        } else {
            // Leftover won't host the next item: penalize more if the
            // mismatch is severe (next item much larger than leftover).
            let gap = (next_item_size - pr) as f64;
            score += 3.0 + gap * 0.08;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Tightness reward: filling a large fraction of the current residual.
    let resid = bin_residual as f64;
    if resid > 0.0 {
        score -= (item / resid) * 12.0;
    }

    // Prefer consolidating into existing bins when many are already open.
    score += (open_bins_count as f64) * 0.15;

    // Early in the stream, be slightly more selective about imperfect fits.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 3.0;

    // Mild pull toward the mean residual: keep bin states balanced.
    score += (mean_residual - pr as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1)
    // are pure waste; penalize gaps below a "usable" threshold nonlinearly.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill * fill;
    }

    // Penalize leaving a gap that exactly excludes the next item barely,
    // but reward a gap that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing; with few,
    // allow spreading (best-fit still dominates via post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be huge) — make fresh bin score moderate.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 30.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild alignment with mean residual: bins far below mean residual
    // (already fragmented) are slightly deprioritized.
    score += 0.1 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear push
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Aggressive 2-step lookahead: reward when next item fits the post_residual exactly well
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            // gap between next item and post residual: smaller gap = better chain
            let gap = post_residual as f64 - next;
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            // perfect chain bonus
            if gap < 1.0 {
                score -= 12.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to the shortfall
            score += 6.0 + (next - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    } else {
        // last item: pure tightness matters most
        score -= 8.0;
    }

    // Relative-to-mean residual shaping: bins with residual below mean are scarce; use them wisely
    let res = post_residual as f64;
    if res < mean_residual {
        // creating below-average residual (dead space) is risky unless chain fits
        score += 0.35 * (mean_residual - res);
    } else {
        score -= 0.15 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tight_elsewhere = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (post_residual as f64 / bin_capacity as f64) < 0.15;
        if tight_elsewhere > 0.0 || poor_fit {
            score -= 20.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 500.0;
        // allow new bin when few bins fit item and mean residual is low
        if fitting_bins_count <= 1 {
            score -= 450.0;
        }
        if mean_residual < 0.25 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Prefer bins with tight residuals relative to mean residual
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 100.0;

    // Time horizon: late in stream, be more aggressive filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 50.0 * progress;
    }

    // Penalize very small unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // base: post residual, with non-linear polynomial shaping
    let mut score = pr + 60.0 * x * x - 40.0 * x * x * x;

    // stream-progress coupling: penalize residual more as stream advances
    score += 25.0 * x * progress;

    // mean residual interaction: prefer bins deviating below mean when mean is high
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // tight fit bonus (smooth)
    let tight = 1.0 - x;
    score -= 20.0 * tight * tight * item_size as f64 / cap;

    // lookahead: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 10.0 + nx / cap * 30.0;
        } else {
            score -= 15.0 * (1.0 - nx / (pr + 1.0) as f64);
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + progress);
    }

    // mild new-bin penalty so empty bins are chosen only when attractive
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // capacity fraction remaining

    // Penalize residuals that fall into "dead zones" (small unusable slivers)
    // Class A: post_residual in 1..=10 -> nearly dead space, strong penalty
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Class B: post_residual in 11..=20 -> hard to fill later
    else if post_residual <= 20 {
        score += 10.0;
    }
    // Class C: perfect-ish fit, large reward
    else if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // lookahead fits: reward, especially exact / harmonic fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0;
            if slack == 0.0 {
                score -= 30.0; // perfect two-item packing
            } else if slack <= 5.0 {
                score -= 10.0;
            }
            // modulo harmony: post_residual divisible by next_item_size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // lookahead cannot use this bin's residual: mild penalty proportional to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow / cap_f) * 15.0;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Fractional-harmonic threshold on capacity fraction
    // Quarters of capacity as integer-division classes
    let quarter = (post_residual / 25) as f64;
    score -= quarter * 3.0; // larger residual classes slightly preferred to fill

    // Prefer filling bins with below-mean residual (consolidate fullness)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Early stream: be conservative, favor spreading; late stream: pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * frac;

    // New-bin candidate bias: opening a new bin is only good when the item is
    // large relative to capacity or all existing fits are poor
    if bin_residual == bin_capacity {
        if item_size >= 50 || (fitting_bins_count == 0) {
            score -= 20.0;
        } else {
            score += 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to fit typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer fewer bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is
    // chosen only when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (open_bins_count as f64);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; dead space risk.
        score += 8.0;
    }

    // Mean residual coupling: if this bin's residual deviates far below mean,
    // it is becoming an outlier; slight penalty to prefer balanced packing.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += 0.3 * (mean_residual - residual_f);
    }

    // Late in the stream, tighten packing (less room to amortize new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to next item: penalize leftover the next item can't use.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fits relative to bin capacity (small post_residual is good generally).
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Penalize creating unusable slivers (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: bins with residual below mean are more "loaded";
    // prefer placing into below-mean residual bins to consolidate.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in stream: slightly favor opening new bins to build a diverse pool? No—
    // favor filling existing bins early; late in stream, allow new bins freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless progress is late or item is large.
        score += 80.0 - 60.0 * progress - (item_size as f64 - 50.0).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: penalize leaving residuals that next item can't use,
    // reward residuals that next item would fill well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            if slack <= 15.0 {
                score -= 4.0; // next item fits snugly
            } else {
                score += slack * 0.02;
            }
        } else if post_residual > 0 && (post_residual as f64) < nxt {
            score += 2.5; // dead space for the next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    // Deviation from mean residual: prefer bins whose residual deviates
    // from the mean in a useful way (fill below-mean-residual bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.03;

    // Time horizon: early in the stream, be more willing to leave slack
    // (future items may fit); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_fit = if post_residual as f64 > 0.0 && post_residual < 12 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 20.0 * pressure - 10.0 * bad_fit + 5.0 * (1.0 - pressure) * (1.0 - bad_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: residuals too small to be useful later
    let dead = (1.0 - norm_pr).powi(4);
    score += 40.0 * dead * norm_pr;

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 25.0 * fit_quality * (1.0 - progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 15.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mild preference to keep bins balanced early, tight packing late
    let mr = mean_residual;
    score += 0.3 * (mr - pr) * (1.0 - progress);

    // Slight penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals in "unusable" harmonic bands (too small for typical items 1..100)
    // Items are 1..100, so residual < ~10 is dead space.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Reward small post_residual (tight fit) with a non-linear bonus
    score -= 40.0 * (1.0 - frac).powi(3) * (1.0 - frac);

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 150.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (harmonic classes) are more likely to be filled later.
    let harmonic_hits = [10u32, 20, 25, 30, 40, 50, 60, 70, 80]
        .iter()
        .filter(|&&s| s <= post_residual && post_residual % s == 0)
        .count() as f64;
    score -= harmonic_hits * 8.0;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // penalize if next item leaves dead space
            if next_left < 10 {
                score += (10 - next_left) as f64 * 2.0;
            } else {
                score -= 10.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins are crowded
    if bin_residual == bin_capacity {
        // base penalty so new bins are not opened frivolously
        score += 55.0;
        // but if mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 30.0 * (0.5 + 0.5 * progress);
        // if the item is large relative to capacity, a fresh bin gives best packing
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 25.0;
        }
    }

    // Mild preference to fill bins with larger residual when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * frac * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small unusable gaps after placement.
    // A residual is dead if it's smaller than the smallest plausible item (1)
    // but practically, residuals in (0, ~10) are hard to reuse; also residuals
    // that cannot fit the lookahead item are less useful.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // If the lookahead item cannot fit into the post-residual, the leftover
        // is likely dead space for the next step.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * post_residual as f64;
        }
        // Reward residuals that exactly fit the next item (perfect chaining).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Perfect fit: strongly reward closing a bin tightly.
        score -= 60.0;
    }

    // Reward tight fits relative to the item size (waste ratio shaping).
    score += (post_residual as f64 / item_size.max(1) as f64) * 8.0;

    // Open-bins pressure: when many bins are open, discourage spreading into
    // fresh space; encourage consolidating into already-open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when existing bins fit poorly
        // (large post_residual relative to capacity) or none fit well.
        let poor_fit = post_residual as f64 > 0.55 * bin_capacity as f64;
        if poor_fit && (fitting_bins_count == 0 || mean_residual < 15.0) {
            score -= 30.0;
        } else {
            // Otherwise, prefer reusing an open bin.
            score += 45.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Mean residual coupling: when average residual is small, conserve open
    // bins by penalizing placements that leave large leftovers.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: next item exactly fills this bin -> strong reward.
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: scale reward by tightness.
            score -= 12.0 * (nxt / post_residual as f64);
        } else {
            // Next item would not fit: penalize proportionally to leftover mismatch.
            score += 6.0 * (diff / bin_capacity as f64) * 10.0;
        }
        // Small extra bonus if this bin can also host the item after next (chained fit).
        if post_residual >= next_item_size && (post_residual - next_item_size) >= item_size.min(next_item_size) {
            score -= 4.0;
        }
    } else {
        // Last item: prefer tightest possible fill.
        score -= 5.0;
    }

    // Penalize dead space: post residuals too small to host typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins tighter than average are preferred.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But allow a new bin if lookahead suggests a perfect future match chain.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, favor existing bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < item_size.max(next_item_size.max(1)) {
        score -= 8.0; // space still usable by upcoming items
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere or the item is large relative to residual.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.75;
        let many_fitting = fitting_bins_count as f64 > 1.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0;
        if poor_fit { score -= 10.0; }
        if many_fitting { score += 15.0 * (1.0 - progress); }
        // Late in stream, avoid opening bins; consolidate.
        score += 20.0 * progress;
    }

    // Lookahead: prefer bins whose post_residual accommodates next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
        // Perfect chain: item + next item exactly fills bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > (bin_capacity as f64 * 0.4) {
        score -= 5.0;
    }
    // Prefer bins with residual below mean (fill emptier bins less).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr + 0.25 * progress * progress * norm_pr * norm_pr);

    // Penalize residuals that cannot fit the next item (smooth logistic-like term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 40.0 * gap / (1.0 + gap);
        // Reward when next item fits tightly
        let tight = 1.0 - ((nxt - pr).abs() / cap);
        score -= 10.0 * tight * tight * progress;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for deviating from mean residual (fragmentation balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Penalize excessive open bins mildly, smoothed by progress
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" modular bands
    let pr = post_residual;
    let band = pr / 10; // integer division band (0..10)
    match band {
        0 => score -= 6.0,               // near-perfect fill
        1 => score -= 3.0,
        2 => score += 2.0,               // awkward ~20-29 dead space
        3 => score += 4.0,
        4 | 5 => score -= 1.0,           // half-capacity friendly
        6 => score += 2.0,
        7 => score += 3.0,
        8 | 9 => score -= 0.5,
        _ => {}                          // fresh bin
    }

    // Modulo coupling: post_residual divisible by common item sizes is reusable
    if pr > 0 {
        let mut reuse = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { reuse += 2.5; }
        }
        score -= reuse;
    }

    // Lookahead: penalize if next item can't fit post_residual
    if next_item_size > 0 {
        if next_item_size > pr {
            score += 3.0 + (next_item_size - pr) as f64 * 0.05;
        } else {
            score -= (pr - next_item_size) as f64 * 0.08;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: mildly penalize unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (mean_residual as u32 as f64)).abs();
        score = cap - 4.0 + fragmentation;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 3.0; // stream has big items coming; fresh bin is good
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && item_size <= 40 {
            score += 6.0; // don't waste a new bin on small items
        }
    }

    // Late-stream tightening: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // (min item size 1 in general case; treat tiny gaps as near-dead).
    if post_residual > 0 {
        let dead_threshold = 8.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0) * 0.05);
    if bin_residual != bin_capacity {
        score -= open_pressure * 2.0;
    } else {
        // New-bin candidate: penalize more when pressure is high,
        // unless this is the only fitting option.
        score += open_pressure * 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can exactly fill the resulting gap,
    // reward this placement; if next item cannot fit the post-residual,
    // penalize leaving a gap it might have used.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Mild preference for bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Early in the stream, allow new bins more freely to build diversity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Next item can follow in this bin: reward closeness to perfect 2-chain.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportionally to the miss.
            score += 15.0 * (diff / bin_capacity as f64);
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.25 * (pr - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // perfect 2-step chain (item + next item exactly fill it).
    if bin_residual == bin_capacity {
        let perfect_chain = next_item_size > 0
            && item_size + next_item_size == bin_capacity;
        if perfect_chain {
            score -= 45.0;
        } else {
            score += 25.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Mild time pressure: early in the stream, be pickier (higher score for waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit anywhere after placement, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it heavily
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: when many bins are open with high mean residual, prefer
    // filling existing bins rather than opening new ones.
    let mean_gap = mean_residual - (post_residual as f64);
    if mean_gap > 0.0 {
        score -= 3.0 * mean_gap / (bin_capacity as f64);
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Mild penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate guard: an empty bin has large post_residual already,
    // but add extra penalty so it only wins when no open bin fits decently.
    if bin_residual == bin_capacity {
        score += 10.0;
        // If item is large, a fresh bin is actually attractive.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening over stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Quadratic dead-space penalty, stronger as stream progresses
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (post_residual near zero) with smooth cubic term
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Penalize bins far from mean residual (smooth dispersion penalty)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * fits_next * (1.0 - gap * gap);
        score += 5.0 * (1.0 - fits_next) * progress;
    } else {
        // Last item: minimize final waste aggressively
        score += 10.0 * norm_pr;
    }

    // Mild preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer minimal post_residual (tight fit)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Harmonic class reward: post_residual divisible by common item sizes (10..=80)
    if post_residual > 0 {
        let pr = post_residual;
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 3.0; }
        if pr % 50 == 0 { harmonic_bonus += 3.0; }
        // integer-division threshold classes: small dead space bands
        let class = pr / 10; // 0..10 integer division class
        harmonic_bonus += match class {
            0 => 10.0,          // 1..9 residual: nearly perfect
            1 => 7.0,           // 10..19: fits small items
            2 => 5.0,
            3 => 3.5,
            4 => 2.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: reward if next_item_size fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0; // next item perfectly tiles the remainder
            }
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: avoid wasting it on poor fits, but reward tight fits
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 12.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when mean residual across open bins is large (fragmented).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bins generally
        score += 20.0;
        // but discount when open bins are fragmented or few
        score -= fragmentation * 15.0;
        if open_bins_count == 0 {
            score -= 30.0;
        }
        if progress < 0.2 {
            score -= 5.0;
        }
        // a new bin wastes space equal to item_size vs an existing fit
        score += item_size as f64 * 0.1;
    }

    // Mild pressure against bin proliferation late in stream
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10] are nearly unusable
    // (min item size is small but gaps < 10 waste capacity almost fully).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        // Small but potentially usable gaps: mild penalty.
        score += 8.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.6;

    // Mean-residual coupling: if open bins are already tight on average,
    // avoid draining this bin further unless the fit is excellent.
    if (mean_residual - item_size as f64) < 0.0 {
        score += 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item.
        score += 12.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin when all open bins
    // would leave bad gaps, but discourage it early when few bins are open.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 30.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead matching — reward when next item fits snugly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // tighter chain fit => bigger reward
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (miss / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal residual strongly
        score += 5.0;
    }

    // Relative-to-mean adjustment: bins below mean residual are "precious" space
    let residual_gap = post_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (dead zone < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate handling: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin; slightly worse than a snug existing fit
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening a bin is correct
        }
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild consolidation pressure as open bins accumulate
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted lookahead room
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with below-mean residual (keep large-residual bins for big items).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Time horizon: early in the stream, be pickier (penalize mediocre fits);
    // late in the stream, just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fits = (post_residual as f64 / bin_capacity as f64) > 0.6;
        if desperation > 0.0 || (poor_fits && progress < 0.7) {
            score -= 30.0 + 20.0 * desperation;
        } else {
            score += 15.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild penalty per open bin to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with a non-linear penalty on large dead space.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth interaction: dead space matters more as the stream progresses.
    score += 12.0 * norm_pr * norm_pr * progress;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize slightly so we only open new bins when fits are bad,
    // with a smooth relaxation as the stream progresses.
    if bin_residual == bin_capacity {
        score += 18.0 - 8.0 * progress;
    } else {
        // Reward tightening fit relative to mean residual (smooth coupling).
        score -= (mean_residual - pr).max(0.0) * 0.15;
    }

    // Lookahead: reward leaving room for the next item (smooth quadratic coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score += 0.08 * gap * gap / cap;
        if pr >= n {
            score -= 3.0 * (1.0 - n / cap);
        }
    }

    // Mild dispersion pressure: many open bins -> discourage spreading waste.
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals divisible by common item
    // sizes (10/20/25/50) are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Dead-space penalty: small unusable leftovers
        if pr < 10 { score += (10 - pr) as f64 * 3.0; }
    } else {
        // Perfect fit is ideal
        score -= 30.0;
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item still fits: mild reward scaled by how well it nests
            let nest = next_item_size as f64 / pr as f64;
            score -= nest * 6.0;
            if pr % next_item_size.max(1) == 0 { score -= 5.0; }
        } else {
            // next item won't fit here: penalize slightly
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: discourage unless current residual is very small
    // or the item is huge relative to remaining space.
    if bin_residual == bin_capacity {
        let tight = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // empty-bin score: baseline at residual value, plus penalty that
        // fades when open bins are crowded (mean residual low).
        score = pr as f64 + 15.0 + tight * 10.0
            - (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
    }

    // Mild pressure against bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in awkward gap 1..=15)
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Dead-space penalty scaled by how tight the fit was relative to bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * (0.5 + fill_ratio);
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly prefer using it if it fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits but not quite (wasted opportunity)
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) > next_item_size as f64 * 0.8 && (post_residual as u32) < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / 10.0;
        score += 25.0 - crowding * 10.0;
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Early stream: slightly more willing to open bins; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Usable leftover for the next item, but not exact: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + slack / 10.0);
        } else {
            // Dead space below next item size: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }

        // Two-item chain: bin could take next item too if residual fits both? (already placed)
        // Penalize opening new bins when a perfect fit exists here.
        if post_residual == next_item_size && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted late in the stream or when bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64 / 8.0).min(2.0);
        score += 45.0 - 20.0 * progress - 5.0 * crowd;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits), punish outliers.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res).min(30.0);
    } else {
        score += 0.2 * (res - mean_residual).min(30.0);
    }

    // Slight preference for fuller bins overall.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small is good, penalize large leftover.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 3.0;
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score -= 12.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time-horizon modulation: early in stream, be more selective about wasting
    // space; late in stream, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 4.0 * tightness;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> discourage adding
    // more residual to already-fragmented state; prefer bins below mean residual.
    if open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: opening a fresh bin should only win when the fit here
    // is poor or the item would leave a big hole. Make empty-bin score moderate.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * tightness;
        // but if no open bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for filling larger residual bins when item is large.
    if item_size > bin_capacity / 2 {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let t = progress;
    let poly = 1.0 + 0.6 * t * t + 0.4 * t * t * t;
    score *= poly;

    // Penalize large post_residual more as stream progresses (wasted space compounds)
    score += norm_pr * norm_pr * 20.0 * (0.5 + t);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 15.0 * (-pr / 25.0).exp();

    // Dead-space avoidance: residual too small for likely next items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let unusable = ((ni - pr) / ni).max(0.0).min(1.0);
        score += 10.0 * unusable * (1.0 - t * 0.5);
        // Reward leaving room for the next item
        score -= 8.0 * (-((pr - ni).abs() / 20.0).powi(2));
    }

    // Last-chance bin bonus: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // Smooth late-stream tightness pressure
    score -= 10.0 * t * t * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual gap: residuals divisible by 10 pair well
    // with item sizes drawn on a 10-grid; penalize "off-class" gaps.
    let gap_class = post_residual % 10;
    score += match gap_class {
        0 => -6.0,
        1 | 9 => 4.0,
        2 | 8 => 2.5,
        _ => 0.0,
    };

    // Perfect fill: ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        // Dead space at or below minimum item size is nearly a perfect fill.
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Coupling with lookahead: reward when the next item exactly fits the
    // post-residual (harmonic chaining), penalize when it overshoots badly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let class_match = (post_residual - next_item_size) % 10;
            score -= 6.0 - (class_match as f64) * 0.5;
        } else {
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a tight fit. Penalize opening fresh bins when the stream is
    // already populated and a reasonable fit exists.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            score += 15.0; // empty bin wastes more space than the average open bin
        }
        if step_index > 0 && open_bins_count > 0 {
            score += 8.0;
        }
        if fitting_bins_count <= 1 {
            score -= 12.0; // nothing else fits well; new bin is fine
        }
    }

    // Tightness ratio: favor bins where the item occupies a large fraction.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Late in the stream, consolidation matters more: prefer fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Many open bins: discourage spreading into large-residual bins.
    if open_bins_count > 4 {
        score += (post_residual as f64) * 0.1 * ((open_bins_count as f64).sqrt());
    }

    // Integer-division threshold on post_residual: gaps in [20, 34] are the
    // worst harmonic class (too big to waste, too small for mid items).
    let div_class = post_residual / 10;
    if (20..35).contains(&post_residual) {
        score += 5.0;
    } else if div_class >= 5 {
        score += 2.0; // half-empty or worse
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap below the minimum plausible item size (1..100 stream => treat <20 as near-dead).
    if post_residual > 0 {
        let dead = (20u32).saturating_sub(post_residual) as f64;
        score += 6.0 * dead * dead; // quadratic wall on tiny residuals
        // If the gap cannot fit the known next item, it is likely dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
            // Extra penalty if it cannot fit even the smallest typical item.
            if post_residual < 10 {
                score += 25.0;
            }
        }
        // Perfect fit: zero waste, reward strongly.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin content.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 0.15 * open_bins_count as f64 + 10.0 * progress;
        // But if no open bin fits well, allow opening: soften when mean residual is high.
        score -= 0.05 * mean_residual;
    } else {
        // Mild preference to use already-open bins when many are open.
        score -= 0.02 * open_bins_count as f64;
    }

    // Lookahead: if placing here leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Even better: leaves room for next item AND next item's likely follow-up.
        if post_residual >= next_item_size + 10 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // next item fits here: reward tightness of the chained pair
            let chain_waste = post_residual as f64 - n;
            score -= 60.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins with residual below mean (denser bins) to keep mean low
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 120.0 + 0.3 * open_bins_count as f64;
        // but allow new bin if current item is large and would leave awkward residue
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Late in stream: be more conservative, prefer tight fits even more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - waste / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty if it would have fit
            // had we not consumed this bin.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: prefer filling bins when many are open (consolidation).
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // Prefer bins below mean residual (balance filling across bins) mildly.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, allow looser fits (exploration);
    // late in stream, be strict about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless item is large
    // or all open bins are poor fits (high mean residual, item nearly fills bin).
    if bin_residual == bin_capacity {
        let base_penalty = 18.0;
        let large_item_bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        let poor_fits_bonus = if mean_residual < (item_size as f64) { 12.0 } else { 0.0 };
        score += base_penalty + large_item_bonus + poor_fits_bonus - (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 2.0 * x * x);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate slack (favor tight fits mildly), later penalize slack more
    let coupling = pr * (0.5 + 1.5 * progress) * (x * (1.0 - x)) * 4.0;
    score += coupling;

    // Dead-space penalty: polynomial in wasted fraction, amplified by progress
    score += (x * x * x) * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strong polynomial reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * (1.0 - progress) * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let fit_frac = (next_item_size as f64) / (pr.max(1.0) as f64);
            score -= 15.0 * fit_frac * (1.0 + progress);
        } else {
            score += 10.0 * (1.0 - progress) * (next_item_size as f64 - pr) / cap;
        }
    }

    // Mean-residual context: prefer bins deviating below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev - 6.0 * dev;

    // Mild diversity pressure when many bins are open
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small dead space" class are rewarded (lower score).
    let dead_class = post_residual % 10; // residue class mod 10
    if dead_class == 0 {
        score -= 8.0; // perfectly aligned leftover (e.g. 0,10,20,...) is reusable
    } else if dead_class <= 3 {
        score -= 3.0; // small-but-tight leftover still usable for tiny items
    } else if dead_class >= 7 {
        score += 4.0; // awkward leftover band: high dead-space risk
    }

    // Integer-division thresholds: classify post_residual into coarse buckets.
    let bucket = post_residual / 25; // 0..4
    score += bucket as f64 * 2.5; // prefer fuller bins (smaller leftover bucket)

    // Perfect fit is best possible outcome.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0; // chain fit: leave exactly what the next item needs
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item can still land here
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15; // mismatch penalty
        }
        // Harmonic compatibility: next item size divisible by leftover class
        if post_residual > 0 && next_item_size % post_residual.max(1) == 0 && post_residual > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the
    // item is huge relative to residual capacity of open bins.
    if bin_residual == bin_capacity {
        score += 20.0; // base penalty for opening a new bin
        if item_size > 60 || (mean_residual < item_size as f64 * 0.5) {
            score -= 22.0; // big item or poor mean residual: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 6.0; // next item pairs well with fresh bin
        }
    }

    // Mean-residual coupling: when open bins are already loose, discourage
    // spreading items thinly; when tight, encourage using existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.05 * (0.5 + progress);

    // Mild preference to keep bin count low late in the stream.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=9) are nearly unusable since item sizes >= 1
    // but realistically the stream carries mid/large items; punish leaving crumbs.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Large leftover space is reusable; mild reward.
        score -= 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fitting the item so the next item also fits into the leftover space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += 5.0;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // (large dead space would result) or when nothing fits well.
        // Base penalty keeps new bins as fallback; relax when stream is early
        // (build up a pool of bins) and when the current fit is bad.
        let mut new_bin_score = 25.0 + (open_bins_count as f64) * 2.0;

        // If placing here would leave a tiny unusable gap, make new bin attractive.
        if post_residual > 0 && post_residual < 10 {
            new_bin_score -= 45.0;
        }
        // If next item won't fit the leftover, slight incentive for fresh bin.
        if next_item_size > post_residual && next_item_size > 0 {
            new_bin_score -= 8.0;
        }

        // Early stream: allow more bins; late stream: be conservative.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += progress * 15.0;

        score = new_bin_score;
    }

    // Mild tie-breaking: prefer bins with below-average residual (denser bins),
    // keeping emptier bins flexible for future items.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (dead space minimization)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0 + (5 - post_residual) as f64 * 8.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0); // tighter lookahead fit -> bigger reward
        } else {
            // next item cannot fit here; penalize small leftover dead space
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(30.0) * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter (more filled) than average
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bonus: if this is the only bin that can fit, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 * 3.0 + progress * 20.0;
        // New bin is attractive only if item is large and no tight fits elsewhere
        if item_size > bin_capacity / 2 {
            score += 25.0 - pressure * 0.5;
        } else {
            score += 45.0 + pressure * 0.6;
        }
        // If next item is small, a fresh bin keeps flexibility
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 15.0;
        }
    }

    // Mild late-stream tightening: avoid scattering residue near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (post_residual as u32) < next_item_size {
            1.0
        } else {
            0.25
        };
        score += 20.0 * dead * (post_residual as f64 / cap);
    }

    // Lookahead: strongly favor bins where the next item also fits afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // bins have poor residuals or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 30.0 * pressure - 10.0 * horizon;
        // If next item is large and this item is small, opening fresh is okay.
        if next_item_size > 60 && item_size < 30 {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins among many open bins (reduce fragmentation).
    score += 0.5 * (open_bins_count as f64).ln() * (bin_residual as f64 / cap);

    // Slight time-decay on residual penalty: early on, keep bins flexible.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + 0.5 * x * x * x * progress;
    score += 40.0 * poly - 30.0 * x * progress;

    // Tight fits are good, especially early
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 15.0 * (1.0 - fits_next) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    }

    // Slight preference for bins below mean residual (balance)
    score += 0.1 * (pr - mean_residual);

    // Make fresh empty bins moderately attractive when fit is poor
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - tightness) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" (near-zero modulo 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement (capacity-fraction logic).
    let post_frac = post / cap;
    let item_frac = item_size as f64 / cap;

    // Integer-division thresholds on post_residual: classify dead space.
    let dead_class = post_residual / 10; // 0..10 harmonic bucket
    let dead_bonus = match dead_class {
        0 => -14.0,                       // perfect/near-perfect fill
        1 => -8.0,                        // residue 10..19: fits small items
        2 | 3 => -4.0,                    // mid residues
        4 | 5 => 0.0,
        6 | 7 => 3.0,                     // awkward mid gaps
        _ => 6.0,                         // large gap: wasteful unless strategic
    };
    score += dead_bonus;

    // Modulo coupling: reward residuals that are multiples of common item sizes.
    let r = post_residual % 10;
    if r == 0 {
        score -= 5.0;
    } else if r <= 2 {
        score -= 2.0;
    }

    // Lookahead coupling: can the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how snugly the next item fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 4.0 + 6.0 * snug;
        } else {
            // Next item won't fit here; penalize slightly more if this bin
            // would be left with an unusable sliver.
            if post_residual < 10 {
                score += 5.0;
            } else {
                score += 1.0;
            }
        }
    } else {
        // Last item: pure fill, reward tight packing.
        score -= 3.0 * (1.0 - post_frac);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early (amortize the new bin over many items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as more items remain.
        score = cap * 0.85 + 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= cap * 0.6; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items into a fresh bin
        }
    }

    // Mild preference for balancing load across many open bins.
    score += 0.02 * open_bins_count as f64 * item_frac;

    // Deviation from mean residual: prefer bins that keep residuals homogeneous.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward bins whose leftover can host the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual < next_item_size {
            // leftover cannot fit next item: dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity and open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing residuals are large (item fits nowhere tightly)
        score = 40.0 + fragmentation * 30.0 + (1.0 - progress) * 20.0;
        if item_size >= 60 {
            score -= 15.0; // big items pair well with a fresh bin
        }
        if next_item_size > 0 && next_item_size <= post_residual.min(bin_capacity) {
            score -= 10.0;
        }
    }

    // Mild open-bins pressure: with many open bins, favor consolidation into
    // existing bins (penalize the new-bin option implicitly via its base score).
    let _ = open_bins_count;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let exact = (post_residual as f64 - next_item_size as f64).abs();
        score -= 40.0 / (1.0 + exact);
        // Perfect chain: next item fills bin exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize proportionally to leftover dead space
        score += 10.0 + 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Penalize large unusable residuals that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny dead space
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (better fit than average)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = mean_residual - post_residual as f64;
    score += 0.3 * mean_gap * (0.5 + t);

    // New-bin candidate: open a fresh bin only when item is huge relative to residual
    if bin_residual == bin_capacity {
        let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score = 60.0 + 50.0 * waste_ratio;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // fresh bin can serve next item too
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // no real alternative, allow new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-shaped coupling
    score += poly * (pr * pr / cap) * 0.15;

    // Penalize large dead space more as stream progresses (less chance to fill it)
    let dead = pr / cap;
    score += t * dead * dead * cap * 0.3;

    // Reward tight fits (small post_residual) with mild non-linear bonus
    score -= (1.0 - dead) * (1.0 - dead) * 4.0;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * (1.0 - t);
    }

    // Lookahead: reward leaving room for the next item (quadratic interaction)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score -= 6.0 * (1.0 - gap / cap) * (gap / cap).max(0.0);
        // Penalize if post-residual barely misses next item
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Mild preference for bins with residual below mean (consolidating space)
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: keep it competitive only when current bins are poor fits
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score = cap * 0.55 + 3.0 * openness.sqrt() - 8.0 * t;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and small-dead-space classes are good.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 200.0; // perfect fill
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 25.0;
    }

    // Modulo-10 class: residual in {1..9} is near-waste; penalize odd small leftovers.
    let cls = pr % 10;
    if cls > 0 && pr < 30 {
        score += 30.0 - cls as f64 * 2.0;
    }

    // Harmonic fraction thresholds on bin fill level.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.9 { score -= 40.0; }
    else if fill > 0.75 { score -= 20.0; }
    else if fill > 0.5 { score -= 5.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (30.0 - slack.min(30.0)) * 0.8;
        } else {
            // next item cannot use this residual: residual likely dead
            if post_residual < 10 {
                score += 15.0;
            } else if post_residual < next_item_size {
                score += (post_residual as f64) * 0.2;
            }
        }
    } else {
        // last item: prefer tightest fit aggressively
        score -= 100.0;
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 { score -= 200.0; }
        if open_bins_count == 0 { score -= 100.0; }
        score += mean_residual * 0.3;
    }

    // Late in stream: consolidate more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a small unusable gap
    // (too small for the smallest plausible item) is heavily penalized.
    let min_item: f64 = 1.0;
    if (post_residual as f64) < 10.0 {
        // dead space below the smallest expected item => wasted capacity
        score += (10.0 - post_residual as f64) * 3.0;
    } else if (post_residual as f64) > 80.0 {
        // large leftover is good (still very usable) => reward
        score -= (post_residual as f64 - 80.0) * 0.5;
    }

    // Non-linear penalty on tight fits: post_residual == 0 is perfect,
    // but tiny leftovers (1..=5) create nearly-useless gaps.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 5.0 {
        score += 12.0 - pr * 1.5;
    }
    if pr == 0.0 {
        score -= 10.0; // perfect fill
    }

    // Open bins pressure: discourage spreading across many bins when
    // fewer bins suffice, especially early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).powf(1.3) * (1.2 - 0.4 * progress);
    score += bin_pressure * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the mean (keeps residuals uniform,
    // leaving large residuals for large future items).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() <= 1.0 {
            score -= 8.0;
        } else if ni > pr && ni <= bin_residual as f64 {
            // next item would need this bin's current residual, not post
            score += 2.0;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual;
    // only choose it when open bins are numerous or fit is poor.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 25.0 + (open_bins_count as f64) * 1.5;
        score += new_bin_penalty;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative => open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Partial lookahead: post_residual close to next item size is still good.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 100.0 / (1.0 + gap);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space at all.
        score += 50.0;
    }

    // Penalize tiny dead space (unusable slivers) more than moderate space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to capacity or few bins fit the item.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base penalty for opening a new bin, discounted for big items / scarcity.
        score += 150.0 - 120.0 * load_ratio - 100.0 * scarcity;
        // Late in the stream, be more conservative about opening bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Slight preference for packing larger items into existing bins
    // (large items create dead space; reward burying them in open bins).
    score -= item_size as f64 * 0.08;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Deviation from mean residual: prefer bins whose leftover is close to
    // the fleet average, keeping residual distribution balanced.
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // New empty-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin when others could fit.
        let mut nb = 18.0;
        // Early in the stream, opening bins is cheaper (more items to come
        // to fill them); late in the stream, consolidation matters more.
        nb *= 1.0 - 0.5 * progress;
        // If this item barely fits nowhere else well, opening a fresh bin
        // with room for the next item is attractive.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            nb -= 10.0;
        }
        // If it's the last chance, opening a bin is acceptable.
        if fitting_bins_count <= 1 {
            nb -= 20.0;
        }
        score += nb.max(-25.0);
    }

    // Mild late-stream consolidation pressure: favor filling existing bins
    // tightly as the stream ends.
    score += 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual polynomial modulated by stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate residual more.
    let tightness = (pr / cap).powi(2) * (1.0 - progress) * 12.0;
    score += tightness;

    // Cubic term: heavily penalize mid-range dead space, smooth over progress.
    let x = pr / cap;
    score += x * x * x * (6.0 + 10.0 * progress);

    // Last-chance bonus: strongly favor the only bin that fits, more so late in stream.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward bins whose post_residual can still host next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let margin = (pr - nx) / cap;
            score -= 8.0 * (1.0 - margin * margin);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    // or residuals across open bins are already large.
    if bin_residual == bin_capacity {
        let poor_fit = ((bin_residual - item_size) as f64 / cap).powi(2);
        score += 18.0 - 14.0 * (1.0 - poor_fit) - 10.0 * (mean_residual / cap);
        score += 10.0 * progress;
    }

    // Mild preference for filling bins closer to capacity relative to mean residual.
    score -= 3.0 * (item_size as f64 / cap) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with harmonic decay.
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64).powf(0.35);
    } else {
        score -= 60.0; // perfect fill
    }

    // Dead-space penalty: residuals too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of post_residual: residuals divisible by common sizes are reusable.
    let pr = post_residual;
    if pr >= 10 {
        let mut reusable = 0.0;
        for d in [10u32, 20, 25, 40, 50, 80] {
            if pr % d == 0 { reusable += 6.0; }
        }
        score -= reusable;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 30.0;
        } else {
            score -= 12.0 / ((post_residual - next_item_size) as f64 + 1.0).sqrt();
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this residual: penalize proportional to wasted look
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let avg_item = (bin_capacity as f64 - mean_residual.max(0.0)).max(10.0);
        // opening new bin is penalized more when many bins already open and residual classes usable
        score += 35.0 + 15.0 * progress + 0.3 * open_bins_count as f64;
        // but if mean residual is tiny (all bins nearly full), opening is fine
        score -= (mean_residual.max(0.0) - avg_item * 0.2).max(0.0) * 0.4;
    }

    // Mild pressure against leaving large residuals late in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (pr as f64) * 0.15 * progress;

    // Threshold classes on post_residual via integer division.
    let class = pr / 10;
    score -= match class {
        0 => 8.0,
        1 => 5.0,
        2 => 2.0,
        3 => 0.0,
        4 => -1.0,
        _ => -2.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to accept
    // even the minimum item size (1) are pure waste; residuals that cannot
    // hold a "typical" small item (<= 10) are near-dead. Penalize hard.
    if post_residual == 0 {
        // Perfect fit: heavily reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space for typical items: strong penalty.
        score += 40.0 + (10.0 - post_residual as f64) * 4.0;
    } else if post_residual < 20 {
        // Marginal zone: moderate penalty proportional to waste.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size as f64 {
            score -= 8.0;
        } else {
            // Post residual cannot host next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += open_bins_count as f64 * 1.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive if the
    // current item is large or no open bin fits well. Make the empty bin
    // unattractive by default (its post_residual == capacity - item_size
    // is large, giving high base score), but allow it when item is huge.
    if bin_residual == bin_capacity {
        // Empty bin: penalize unless item is large (>= 60), in which case
        // a fresh bin may be preferable to fragmenting an open bin.
        if item_size >= 60 {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Slight preference for bins tighter than the mean (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream-position coupling: as the stream progresses, tighten
    // selection (favor tighter fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: penalize small post residuals.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 40.0;
        } else if gap <= 10.0 {
            score -= 25.0 - gap * 1.5;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to next item: penalize proportionally.
        let dead = next_item_size as f64 - post_residual as f64;
        score += dead * 0.6;
    }

    // Compare post residual against mean residual: prefer bins that keep residual near mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and next item is large.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual by relative fill of the bin.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill * (item_size as f64 / bin_capacity as f64);

    // Penalize large dead space strongly (non-linear).
    if post_residual > 0 {
        score += 0.15 * (post_residual as f64).powf(1.4);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small residual that can still serve future items is valuable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Post residual can host next item: reward proportional to reuse chance.
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // Post residual becomes dead space relative to lookahead.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln() * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Global residual balance: prefer bins below mean residual (keeps spread even),
    // unless it helps packing large items.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, squeeze everything into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus early-exploration discount.
        score = 55.0 + post_residual as f64 * 0.1 - 30.0 * (1.0 - t);
        // Never open a new bin if the fit here is excellent elsewhere is unknown;
        // but penalize opening when item is tiny.
        score += 0.5 * (bin_capacity - item_size.min(bin_capacity)) as f64 * 0.2;
    } else {
        // Existing bins get progressively better scores later in the stream.
        score -= 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += poly * cap;

    // Reward tight fits more strongly as the stream progresses
    score -= 30.0 * norm_item * (1.0 - norm_post) * (1.0 + progress);

    // Penalize dead space that cannot fit a plausible future item
    let next_fits = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if post < next_fits && next_fits > 0.0 {
        score += 8.0 * (next_fits - post) / cap * (1.0 + progress);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty when bin is far from mean residual (imbalance)
    score += 0.05 * (post - mean_residual).abs();

    // Late stream: prefer filling existing bins over opening new ones
    score += progress * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and small dead space are good.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, huge reward
    } else {
        // Dead space penalty grows steeply for residuals that no plausible item can use.
        // Items are 1..=100; residual r is "usable" if some item ~ r exists.
        let r = post_residual as f64;
        // Harmonic classes via modulo: residuals in classes of 10 (decade buckets)
        let decade = post_residual / 10;
        let rem = post_residual % 10;
        // Prefer residuals that sit near common item sizes (multiples of 5/10)
        if rem == 0 {
            score -= 8.0 * (decade as f64); // round residuals are more reusable
        } else if rem == 5 {
            score -= 4.0 * (decade as f64);
        } else {
            score += 3.0 + rem as f64; // odd leftovers are dead space
        }
        // Small residuals (<10) are essentially dead unless next item matches exactly
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward when next item fits the post residual exactly or closely.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize more if we'd leave big dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= open_bins_count as f64 * 2.0;

    // Prefer bins with residual below mean (tighter bins fill first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream: encourage keeping a large residual bin available for big items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual > 60 && progress < 0.5 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A post_residual in (0, 10) is nearly guaranteed dead space (min item = 1,
    // but small gaps rarely match future items well); treat tiny gaps as waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit gets a large reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual: waste ratio penalty.
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 25.0 * waste_ratio * waste_ratio;
    }

    // If the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap < 10 {
            score -= 20.0 - 2.0 * gap as f64;
        }
    }
    // If next item cannot fit in post_residual, mildly penalize (dead space locked in).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open,
    // but keep last-chance bins attractive (fitting_bins_count == 1).
    if bin_residual != bin_capacity {
        // Not the new-bin candidate: reward using open bins.
        score -= 6.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    } else {
        // New-bin candidate: penalize so it is chosen only when fits are bad,
        // less penalty late in the stream when consolidation matters less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 1.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins below mean residual (consolidate emptier bins) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual).
    if post_residual <= 3 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly or nearly: chain placement is great.
            if gap <= 3.0 {
                score -= 30.0;
            } else if gap <= 10.0 {
                score -= 12.0;
            } else {
                score -= 6.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item would not fit here: leftover is dead space for the horizon.
            score += 10.0 + gap * 0.15;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        if post_residual <= 20 {
            score -= 25.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits tightly,
    // i.e., when the fit here is poor relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream / when many bins open.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to a typical residual, new bin is fine.
        if fit_ratio > 0.9 {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small dead space (unusable gaps) more than large leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize small post_residuals that strand capacity.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidation into existing bins (penalize new-bin pull).
    if open_bins_count > 4 {
        score -= 5.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Prefer bins with residual below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in stream, keep flexibility (favor larger post_residual);
    // late in stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (item_size as f64 / bin_residual as f64) < 0.5 && fitting_bins_count <= 1;
        if poor_alternatives {
            score -= 20.0;
        } else {
            score += 45.0 + 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual (smaller leftover = better fit)
    let mut score = post;

    // Smooth non-linear coupling of fill ratio with stream progress:
    // early on, prefer balanced leftovers; later, reward tight packing harder.
    let fill = 1.0 - post / cap;
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score -= progress_weight * (fill * fill) * cap * 0.5;

    // Perfect-fit reward, amplified as stream progresses
    if post == 0 {
        score -= 30.0 + 40.0 * progress;
    } else {
        // Penalize dead space quadratically, scaled by mean residual context
        let dead = post / cap;
        score += dead * dead * (10.0 + mean_residual * 0.2);
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - post / cap) * (0.5 + progress);
        } else {
            // post-residual too small for next item: penalize wasted potential
            score += 4.0 * (nxt - post) / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate handling: allow opening a new bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Opening fresh is attractive when mean residual is low (open bins are nearly full)
        let openness = (mean_residual / cap).clamp(0.0, 1.0);
        score = post + 15.0 - 35.0 * (1.0 - openness) * (0.5 + progress);
        // But discourage proliferation of many open bins early
        score += open_bins_count as f64 * (1.5 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse bucket via integer division
    let item_class = item_size / 20;          // 0..=5 (0 for tiny, 4 for large)
    let next_class = if next_item_size > 0 { next_item_size / 20 } else { 0 };

    // Reward tight fits: post_residual in low harmonic classes is good
    let tight = (post_residual < 10) as f64 * 40.0
        + (post_residual < 5) as f64 * 30.0;

    // Penalize dead space that no future item can plausibly fill:
    // post_residual below the minimum item size (1) is impossible, but
    // small leftovers (1..10) are only fillable by rare tiny items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - post_residual as f64; // small but nonzero gap -> penalty
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling: reward bins whose residual matches next item's class
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        // exact lookahead fit is excellent
        if gap == 0 { score -= 45.0; }
        else if gap < 10 { score -= 15.0; }
        // class match reward (same harmonic bucket)
        if (post_residual / 20) == next_class {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize proportional dead space
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        // Opening a new bin is good when many open bins are fragmented
        // or when the item is large (harmonic class 3+) and fits nowhere snugly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_capacity as f64) / bin_capacity as f64;
        // Prefer new bin when open bins are quite full on average (little room)
        let bias = 55.0
            - 30.0 * fragmentation.clamp(0.0, 1.0)
            - 20.0 * (item_class as f64 / 4.0)
            - 10.0 * progress;
        score += bias;
    } else {
        // Mild preference to fill existing bins as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Modulo-based micro-tuning on residual: residuals that are multiples
    // of 25 pair well with common item sizes; slight reward.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score - tight
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let threshold = 10.0; // below typical min item size, gap is dead space
    if (post_residual as f64) < threshold && post_residual > 0 {
        score += (threshold - post_residual as f64) * 12.0; // heavy penalty for tiny gaps
    }

    // Reward perfect / near-perfect fits superlinearly.
    if post_residual == 0 {
        score -= 150.0;
    } else {
        let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Lookahead: if next item fits into the post residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: leftover likely becomes dead space
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when a
    // tight fit exists elsewhere; encourage consolidation.
    score += open_bins_count as f64 * 0.6;

    // Slight preference for bins with residuals near the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Late in the stream, tighten up: dead space matters more as we approach the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact chaining of next item
        } else {
            score += diff * 0.8; // penalize mismatch proportionally
        }
    }

    // Prefer bins whose residual is already below mean (tight bins get closed out).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Penalize tiny unusable post residuals that are NOT the next item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        score = 40.0 + pressure * 0.5;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open a new bin when a last-chance bin exists
        }
    }

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving residual that blocks nothing
            score += 5.0;
        }
    }

    // Prefer filling bins with larger residuals less when many bins are open
    // (encourage consolidation when bin count is low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (1.0 - progress) * 10.0;
    score += consolidation * (bin_residual as f64 / bin_capacity as f64 - mean_residual / bin_capacity as f64).abs();

    // Mild preference for bins below mean residual early (balance load),
    // above mean residual late (drain bins to close them).
    if bin_residual as f64 > mean_residual {
        score -= 8.0 * progress;
    } else {
        score += 4.0 * (1.0 - progress);
    }

    // Slight bias against opening new bins when few bins exist.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear coupling: quadratic dead-space penalty scaled by stream progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic interaction between post_residual and mean residual divergence
    let mr = mean_residual / cap;
    score += 30.0 * norm_pr * (norm_pr - mr) * (1.0 - progress);

    // Last-chance bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 15.0 * (1.0 - pr / nx) * (0.5 + progress);
        } else {
            score -= 10.0 * (nx / cap) * (1.0 - norm_pr);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: discourage opening unless residuals are tight
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0 * mr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact / tight / medium / loose
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit classes (post_residual small): reward via integer division thresholds
    if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 35 {
        score -= 8.0;
    }

    // Dead-space penalty: residual that likely cannot be reused by typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Harmonic residue classes on post_residual (mod 10): "nice" residuals that
    // match common item sizes get a bonus.
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 12.0;
    } else if mod_class >= 5 {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // Lookahead coupling: can next_item_size fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.5; // good chain, decay with slack
        } else {
            // next item cannot fit here: mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin generally.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 90.0;
        // cheaper to open a new bin early in the stream (more items to come)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // if current item is huge relative to capacity, new bin is more attractive
        score -= (item_size as f64 / cap) * 15.0;
        // many open bins with high mean residual: prefer reusing them
        score += (open_bins_count as f64).sqrt() * 6.0;
        score += (mean_residual / cap).max(0.0) * 20.0;
    } else {
        // Reusing an open bin: reward when bin residual is close to mean residual
        // (balanced packing) — keeps a portfolio of usable residuals.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 10.0 / (1.0 + dev / cap);
    }

    // Mild pressure against hoarding many open bins
    score += (open_bins_count as f64) * 0.3;

    // Slight preference for larger items filling larger residuals (harmonic fraction)
    let frac = item_size as f64 / cap;
    score -= frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold even the smallest
    // item (1) are pure waste; gaps below a "half-usable" threshold are risky.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny dead space (below min plausible item) — heavily penalized.
        score += 40.0;
    } else if post_residual <= 25 {
        // Small gap: only useful for small items; penalize proportionally.
        score += 15.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead exploitation).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus if next item then fits snugly too.
            let next_post = post_residual as f64 - next_item_size as f64;
            if next_post < 10.0 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist or the stream is early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as bins accumulate and stream matures.
        score += 30.0 + pressure + 20.0 * progress;
        // If this is the only fitting bin, opening a new bin is very costly.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 25.0;
    }

    // Mild alignment with global mean residual: prefer bins close to the mean
    // to keep residual distribution balanced.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item's size (perfect 2-chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match: strong reward; near match: graded reward.
        score -= 40.0 / (1.0 + slack * 0.15);
        if slack == 0.0 {
            score -= 25.0; // exact 2-chain bonus
        }
    }

    // Penalize post_residual that is too small for the next item
    // (dead space that likely can never be used).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual means tighter packing.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate penalty: only attractive when it yields a
    // very tight fit (small post_residual) or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress; // early stream: more willing to open bins
        if next_item_size > 0 && post_residual <= next_item_size {
            score -= 15.0; // new bin enabling a good next placement
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild penalty for very large post_residual (wasteful gap).
    if pr > 50.0 {
        score += (pr - 50.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // post space is reusable by lookahead item
        } else if post_residual > 0 {
            score += 4.0 + (post_residual as f64) * 0.08; // stranded sliver
        }
        // Perfect chain: item fits and next item exactly fills the remainder
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 5.0;
    }

    // Last-chance bin: strong bonus to avoid opening a needless new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins that are already well-filled relative to the fleet average.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Encourage consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // Time-horizon modulation: early in stream, be greedy about new bins;
    // later, allow opening new bins slightly more to avoid fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less as stream progresses.
        score += 14.0 - 8.0 * progress;
        // Opening a new bin is attractive if existing bins would leave big slivers.
        if post_residual < bin_capacity as f64 * 0.2 {
            score -= 3.0;
        }
    }

    // Mild bonus for filling bins that are close to exhaustion.
    if bin_residual as f64 <= bin_capacity as f64 * 0.35 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize dead space more as stream progresses (quadratic in normalized residual)
    score += cap * progress * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with a saturating bonus
    score -= 15.0 * (1.0 - (pr / 30.0).min(1.0));

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mildly penalize early, allow late when residuals are high
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
        score += 0.1 * mean_residual;
    }

    // Lookahead: reward bins whose post_residual can still host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr) * 0.05;
    }

    // Mild preference to fill bins among many open bins (reduce bin count)
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by modulo classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Class of residual mod 10: residuals that are "harmonically compatible"
        // with common item sizes (multiples of 10, and 5) are more reusable.
        let r = post_residual;
        let class = r % 10;
        match class {
            0 => score -= 12.0,          // reusable by any multiple-of-10 item
            5 => score -= 6.0,           // reusable by half-class items
            1 | 9 => score -= 2.0,       // nearly full, small dead space anyway
            _ => score += 3.0,           // awkward class (2,3,4,6,7,8)
        }

        // Integer-division thresholds: can next_item_size fit in post_residual?
        if next_item_size > 0 {
            let fits_next = (post_residual >= next_item_size) as i32;
            let pair = (post_residual / next_item_size.max(1)) as f64;
            if fits_next == 1 {
                score -= 8.0 + 2.0 * pair.min(4.0);
            } else {
                // Dead space relative to lookahead: penalize waste proportionally
                let waste = (next_item_size as f64) - (post_residual as f64);
                score += 0.25 * waste.min(60.0);
            }
            // Exact harmonic match: post_residual is an integer multiple of next item
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        }
    }

    // Capacity-fraction classes: how full is the bin after placement?
    let fill = (bin_residual as f64) / (bin_capacity as f64);
    if fill >= 0.9 {
        score -= 6.0;   // nearly-full bin: close it out
    } else if fill <= 0.2 {
        score += 4.0;   // barely touched bin: wasteful placement
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly above good fits,
    // below bad fits. Scale with stream progress (late stream: consolidate more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 25.0 + 20.0 * progress;
        // If lookahead is large and no open bin is tight, new bin is fine.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // Mild preference to spread across fewer bins when many are open.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Tie-break: prefer bins whose residual is below mean (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space below the minimum item size: nearly worthless.
            score += 40.0;
        } else if post_residual <= 20 {
            // Only very small items can use this gap: weak residual.
            score += 15.0 * (1.0 - post_residual as f64 / 20.0);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 40 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits the post residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin would become dead space before the next item arrives.
        score += 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (1.5 + 2.5 * progress);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin: penalize by open-bin pressure plus a base cost, but
        // relax the penalty when the current bin's post fit is terrible.
        let poor_fit = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
        score += 45.0 + bin_pressure - poor_fit;
    } else {
        // Existing bin: slight reward for reusing, scaled by how full it is.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 6.0 + 6.0 * fill_ratio;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (using a larger-than-mean residual keeps small gaps pooled).
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
    } else {
        // Last item: prefer tightest fill
        score -= 20.0;
    }

    // Reward small post_residual (tight packing), nonlinear
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Penalize deviating from mean residual context (favor bins tighter than average)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great future fit
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 {
            let perfect = (bin_capacity as i64 - next_item_size as i64 - item_size as i64).abs() as f64;
            if perfect < 5.0 {
                score -= 70.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild pressure over stream progression to close bins early
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score += fit_ratio * 8.0;

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_waste = (post_residual - next_item_size) as f64;
        score -= (100.0 - combo_waste) * 0.6;
        // Perfect pair bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't follow into this bin: penalize leaving awkward gaps
        score += post_residual as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating large dead space that few items could use
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual <= 20 {
        score += 5.0; // awkward small gap zone
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when existing bins fit poorly
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let open_penalty = (open_bins_count as f64) * 1.5;
        score += 12.0 + open_penalty / pressure;
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Global residual coupling: if mean residual is high, prefer bins below mean
    if bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) * 0.05;
        score += dev;
    }

    // Prefer filling bins with large residuals early (keep many mid-size bins alive)
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Normalized post-residual, polynomially coupled with stream progress
    let x = pr / cap;
    let p = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream, 0 at ends
    let mut score = pr as f64 * (1.0 + 0.8 * p * x * x);

    // Penalize large dead space more than linearly (quadratic coupling)
    score += 0.5 * pr * pr / cap;

    // Reward tight fits (small post-residual) more strongly later in the stream
    score -= 20.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual slightly (balance residuals)
    score += 0.1 * (pr - mean_residual);

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 + 10.0 * (next_item_size as f64 / cap);
    }

    // New-bin candidate: penalize moderately so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define dead-space quality.
    let residue_class = post_residual % 10;
    // Perfect-fit classes (0) are ideal; small residues (1..10) are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0; // unusable sliver penalty
    } else if residue_class == 0 {
        score -= 12.0; // round residual, easy to fill later
    }

    // Harmonic fraction of capacity used.
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= used_frac * 20.0;

    // Lookahead coupling: does post_residual still fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward residual that leaves a harmonic (mod-10 friendly) slack.
            if slack % 10 == 0 { score -= 8.0; }
            score -= (slack.min(40)) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            let overshoot = next_item_size - post_residual;
            score += overshoot as f64 * 0.5;
        }
    } else {
        // Last item: prefer fullest bin.
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // current bins would leave bad dead space or nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0 + open_bins_count as f64 * 0.5;
        // But if mean residual is small (bins nearly full), a new bin is fine.
        if mean_residual < 15.0 {
            score -= 30.0;
        }
        // If item is large relative to typical residual, prefer fresh bin.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild stream-progression tilt: early on, keep bins tight; later, allow spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Tie-break: prefer bins with residual close to mean (balanced packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
