    }
    // If next item cannot use the post residual, penalize leaving awkward space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: make empty bin attractive only when it is genuinely better
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Leftover can still host the next item: mild reward proportional to match.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space: leftover too small for the next item. Penalize the gap,
            // but tolerate very small leftovers (they are near-useless anyway).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 {
                score += 2.0 * gap;
            }
        }
    }

    // Penalize creating unusable slivers (< 10 units assumed minimum item size),
    // scaled by how much of the bin was consumed.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin when a reasonably tight fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 100.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(1.0);
        // Exception: allow a new bin if the item is huge and would leave a bad
        // sliver in any existing bin.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 400.0;
        }
    }

    // Mild preference for consolidating: fewer open bins is better.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        score += 15.0 + 40.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits: must open
        }
    }

    // Time horizon: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    // Prefer bins below mean residual (balance), mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (larger leftover = lower priority... actually oracle minimizes,
    // so large residual should be penalized via coupling, small residual favored).
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post-residual in [0,1]
    let t = progress.clamp(0.0, 1.0);

    // Waste penalty grows non-linearly as stream progresses: dead space matters more later.
    let waste_curve = x * x * (1.0 - x) * (0.5 + 2.5 * t);
    score += waste_curve * cap;

    // Tight-fit reward: strongly favor bins where post-residual is small, amplified over time.
    score -= (1.0 - x) * (1.0 - x) * (1.0 + 2.0 * t) * 10.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete, scaled by competition count.
        score += (fitting_bins_count as f64).ln() * (1.0 + t);
    }

    // Lookahead coupling: reward if next item fits the post-residual (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 5.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit: penalize residual that is "almost but not quite" usable.
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * (1.0 - gap);
        }
    }

    // Mean-residual deviation: prefer bins deviating from mean residual to balance open bins.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev.abs();

    // Open-bin pressure: with many open bins, discourage low utilization spread.
    score += (open_bins_count as f64).ln() * x * (1.0 + t);

    // New-bin candidate handling: empty bin gets neutral-ish base but penalized unless
    // no good fit exists (post_residual == residual == capacity).
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * t) + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let pr = post_residual;
    let class = pr % 10;
    // Residuals that are "dead" (too small for typical items) get penalized
    if pr > 0 && pr < 10 {
        score += 60.0;
    }
    // Harmonic bonus: residuals divisible into useful classes (multiples of 10)
    if class == 0 {
        score -= 12.0;
    } else if class == 5 {
        score -= 6.0;
    } else if class == 2 || class == 8 {
        score -= 2.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual still fit next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
            // integer division threshold: how many more next-sized items fit
            let k = pr / next_item_size.max(1);
            score -= 4.0 * (k.min(3)) as f64;
        } else {
            // dead space for the lookahead item
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is very tight
    if bin_residual == bin_capacity {
        score += 35.0;
        // early stream: allow exploration of new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 15.0;
        }
    }

    // Prefer bins with residual close to item (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mean residual coupling: avoid leaving bins far from mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: encourage consolidation
    if open_bins_count > 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize if next item would be blocked by this placement.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin pressure: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residual is tight.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Slightly discourage opening a new bin when alternatives exist.
            score += 12.0;
        }
    }

    // Mild late-stream tightening: favor filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual near zero)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 500.0;
        } else {
            score -= 50.0 / (gap as f64 + 1.0);
        }
    } else if next_item_size > 0 {
        // next item won't fit here after placement; penalize relative to mismatch
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post_residual to mean residual: keep bins balanced
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could still fit the item
    if bin_residual == bin_capacity {
        score += 80.0;
        // but if next item is large and this item is small, new bin may be fine
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 60.0;
        }
    }

    // Progression: as stream advances, tighten tolerance for wasted space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (waste grows superlinearly).
    let dead = post_residual as f64;
    score += 0.6 * (dead / 10.0).powf(1.8);

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead coupling: reward leaving room exactly for the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 35.0; // leaves exact space for next item
        } else if gap > 0 && gap < 10 {
            score -= 12.0; // leaves near-exact space
        } else if gap < 0 {
            // next item won't fit here: mild penalty proportional to overflow
            score += 0.3 * (-gap) as f64;
        }
        // If next item can't fit anywhere else well, prefer conserving big residuals
        if next_item_size as f64 > mean_residual {
            score += 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage spreading items; prefer consolidation.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be pickier about waste (long future to regret);
    // late in stream, accept mediocre fits to avoid opening extra bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if bin is far below average residual, it's "wasted" space
    // already; using it is cheap.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad
    // and there's plenty of runway left.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_waste = mean_residual.max(0.0);
        // Opening a new bin is attractive when existing residuals are small
        // (poor fits everywhere) and we're early (long stream ahead).
        score += 40.0 + avg_waste * 0.5 - 30.0 * progress;
        // Never open a new bin if this is the last fitting bin.
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - post / cap;

    // Base: prefer small post_residual, with smooth non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * fill * fill);

    // Polynomial coupling of fill level with stream progress:
    // later in the stream, reward tight fits more aggressively.
    let progress_coupling = 2.5 * fill * (1.0 - fill) * (0.5 + progress);
    score -= progress_coupling * cap * 0.1;

    // Penalize dead space that is too small for typical future items,
    // smoothly scaled by mean residual of the system.
    let dead = post / cap;
    let dead_penalty = dead * dead * (1.0 - dead) * (10.0 + mean_residual * 0.05);
    score += dead_penalty;

    // Lookahead: reward bins whose post_residual can still host the next item,
    // penalize bins that would strand the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (post / nxt).min(3.0);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * fill;
    } else if fitting_bins_count > 2 {
        score += 0.5 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    // Mild preference for consolidating into fewer bins as the stream matures.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - fill) * 0.8;

    // New-bin candidate: only attractive when no good fit exists; make empty bin
    // less attractive early, more acceptable late with a smooth progress term.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress + 2.0 * (1.0 - fill);
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classification
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Penalize small-but-nonzero post_residual (unusable dead space)
    if post_residual > 0 {
        let class = post_residual % 10; // harmonic class mod 10
        // Residuals that can't fit typical small items (1..=10) are worst
        if post_residual < 10 {
            score += 60.0;
        } else {
            // Modulo-based dead-space penalty: awkward remainders penalized
            let awkward = match class {
                0 => 0.0,           // clean decade residual: very reusable
                1..=5 => 2.0,       // moderately awkward
                6..=9 => 5.0,       // awkward, hard to fill
                _ => 0.0,
            };
            score += awkward;

            // Integer-division threshold: residual >= 25 is a "half-class" slot
            if post_residual / 25 >= 1 {
                score -= 8.0; // reward big reusable residuals
            }
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - slack / cap);
        } else {
            // Next item can't use this residual: penalize proportional to waste
            score += 6.0 + frac * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer it only when item is huge relative
    // to residual or stream is early and mean residual is low
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score = item leaves full residual
        // Penalize slightly so it's chosen only when open bins are bad
        score += 15.0;
        if item_size >= 70 {
            score -= 20.0; // big items do well starting fresh bins
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0; // early stream: opening bins is cheap
        }
        if mean_residual < 12.0 && open_bins_count > 0 {
            score -= 12.0; // existing bins nearly full
        }
    }

    // Mild preference to consolidate: fewer open bins favored
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Small tie-breaker on tightness of fit
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // A gap is "dead" if it is too small to hold even the smallest plausible item.
        // Treat gaps below ~15 as dead space and punish them super-linearly.
        if gap < 15.0 {
            score += (15.0 - gap) * 6.0; // up to +90 for a 1-unit dead gap
        } else {
            // mild penalty for leaving any slack, scaled by how much of the bin is wasted
            score += gap * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement heavily (chained fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: moderate reward
            score -= 15.0;
        } else {
            // next item will NOT fit in the leftover: penalize proportionally
            let waste = next_item_size as f64 - post_residual as f64;
            if waste < 20.0 {
                score += waste * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so its post_residual
    // is large; the pressure term makes keeping bins tight relatively attractive).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + bin_pressure * 2.0;
    } else {
        // Existing bins get a small bonus proportional to pressure (favor consolidation).
        score -= bin_pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // filling it down toward the mean is good (it tightens the residual distribution).
    let res = bin_residual as f64;
    let dev = mean_residual - res;
    if dev > 0.0 {
        // bin is tighter than average: filling it further is fine, small reward
        score -= dev * 0.3;
    } else {
        // bin is looser than average: penalize using it unless the fit is good
        score += (-dev) * 0.1;
    }

    // Slight preference for filling larger items into tighter bins as the stream progresses.
    score += (item_size as f64 / 100.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared dead-space penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(4) * 40.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // penalize leaving space that next item can't use
            let waste = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
            score += waste * 0.3;
        }
        // chain: post_residual exactly matches next item => perfect chain
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless item is large and
    // no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let decent_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && item_size as f64 >= mean_residual * 0.8);
        if decent_fit_exists {
            score += 50.0;
        } else {
            score += 10.0 - 20.0 * fit_quality;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth waste penalty: quadratic in post_residual, amplified as stream progresses.
    let post_norm = post / cap;
    score += 2.5 * post_norm * post_norm * cap * (0.5 + t);

    // Reward tight fits (small post_residual) more strongly over time.
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 6.0 * (0.3 + 0.7 * t);

    // Exact or near-exact fill bonus (smooth exponential).
    score -= 8.0 * (-post / 8.0).exp();

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * t;
    }

    // New-bin candidate: penalize mildly early, increasingly acceptable late or when
    // open bins have large mean residual (fragmented bins are poor hosts).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 4.0 - 6.0 * t - 3.0 * fragmentation;
        // If next item fits well in a fresh bin, slightly favor opening.
        if next_item_size > 0 && next_item_size as f64 <= cap * 0.5 {
            score -= 1.5 * (1.0 - t);
        }
    } else {
        // Penalize placing into bins whose residual deviates from mean (preserve balance),
        // scaled by how many alternatives exist.
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += dev * 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 && gap < 12.0 {
            score += (12.0 - gap) * 0.6;
        }
        // Reward leaving room exactly for the next item.
        if (gap - 0.0).abs() < 1e-9 {
            score -= 4.0;
        }
    }

    // Mild penalty on total open bins to discourage needless sprawl.
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits are always excellent.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic class: how well post_residual decomposes into common small item sizes.
    // Residuals divisible into "nice" chunks (multiples of 10, or 25/50/75) are more reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr % 10 == 0 {
        40.0
    } else if pr % 5 == 0 {
        25.0
    } else if pr % 25 == 0 {
        35.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead space penalty: small awkward residuals (< 10) are nearly unusable.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // next item fits, but leaves another residual: grade the chain quality
            let chain_res = pr - next_item_size;
            score -= 80.0 - (chain_res as f64) * 0.5;
            if chain_res % 10 == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty for stranded space
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Prefer filling bins that are already relatively full (low residual before placement).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 50.0;

    // Penalize bins far below the mean residual (they are outliers; filling them
    // leaves others awkwardly open) — mild.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.05;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer a new bin when the current item is large and would leave
    // a huge residual in any open bin, or when open bins are all quite full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of opening a new bin (spreading capacity).
        score += 90.0;
        // As the stream progresses, opening new bins becomes cheaper relative to
        // fragmenting existing ones (future items unknown, keep capacity flexible).
        score -= progress * 30.0;
        // If many bins are open and mean residual is small, a new bin is fine.
        score -= (open_bins_count as f64).min(20.0) * 2.0;
        // Large items starting fresh leave modular-friendly residuals.
        if item_size % 10 == 0 {
            score -= 15.0;
        }
        // If the item nearly fills a fresh bin, opening is attractive.
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Mild exploration noise-free tie-break: favor bins with residuals in the same
    // "decade class" as the item (modulo coupling).
    if (bin_residual / 10) == ((item_size + 9) / 10) {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min size 1..100 unknown, assume worst-case small gap < 10) are dead.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this residual -> dead space risk
            score += (post_residual as f64) * 0.3;
        }
    }

    // Mild preference for bins tighter than the mean (consolidate space).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Early in stream, be more willing to fill existing bins; late, keep options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual).
    score *= 1.0;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item fits into the post residual
    // (chained perfect/near-perfect packing), penalize when it does not.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: dead-space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 5.0 * (waste / 100.0).min(1.0);
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 5.0;
    }

    // Relative residual vs mean: prefer bins with residuals close to the
    // mean (avoid fragmenting one bin while others stay usable), but give
    // a bonus to bins already below the mean (consolidating waste).
    let cap = bin_capacity as f64;
    let rel = (post_residual as f64 - mean_residual) / cap;
    score += 8.0 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large relative to capacity or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        let pressure = (open_bins_count as f64 / 10.0).min(1.0);
        score += 20.0 - 12.0 * item_frac - 6.0 * pressure - 4.0 * progress;
    }

    // Mild penalty for leaving very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Slight preference for filling larger residual bins early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual), superlinear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post-residual too small to hold any plausible item.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 50.0;
    } else if post_residual < 10 && post_residual > 0 {
        // awkward small gap that likely becomes dead space
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover waste after both
            let double_waste = post_residual - next_item_size;
            score -= 10.0;
            score += 0.15 * double_waste as f64;
        } else {
            // next item won't fit here; slightly favor leaving larger residual instead
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
        if post_residual == 0 {
            score -= 20.0; // perfect closure of the last fitting bin
        }
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // existing bins with good fits, but reward opening a new bin when all
    // open bins would leave large waste or when open-bin count is low.
    if bin_residual == bin_capacity {
        let avg_waste_if_placed_open = mean_residual - item_size as f64;
        if fitting_bins_count == 0 || avg_waste_if_placed_open > 40.0 {
            score -= 20.0;
        } else {
            score += 8.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals flexible); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer filling bins whose residual deviates below the mean (consolidate small residuals).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 0.08 * dev;
        } else {
            score += 0.05 * (-dev);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_n = post / cap;
    let item_n = item_size as f64 / cap;

    // Base: penalize wasted residual, non-linearly.
    let mut score = post * (1.0 + 0.8 * post_n * post_n);

    // Smooth coupling of waste penalty with stream progress: later in the
    // stream, dead space becomes more costly (fewer chances to fill it).
    score += post * (post_n * progress) * 1.5;

    // Reward large item fill fraction, stronger as stream progresses.
    score -= item_n * cap * (0.5 + 0.5 * progress);

    // Perfect / near-perfect fit reward (smooth exponential).
    score -= cap * (-(post / (0.05 * cap + 1.0))).exp() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - post_n) * (1.0 - post_n);
    }

    // Many open bins: discourage spreading; prefer tight bins.
    score += (open_bins_count as f64).ln() * post * 0.15;

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-(gap / 8.0)).exp();
    }

    // Mild pull toward bins with residual close to mean (regularization).
    score += ((post - mean_residual) / cap).abs() * cap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10, or exactly 0) are rewarded.
    let zero = post_residual == 0;
    let decade = post_residual % 10 == 0 && post_residual > 0;
    let half = post_residual == bin_capacity / 2;

    if zero {
        score -= 60.0; // perfect fit: ideal
    } else if half {
        score -= 25.0; // half-full bin is reusable by mid-size items
    } else if decade {
        score -= 12.0;
    } else {
        // penalize awkward leftovers more when they are small (dead space)
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0;
        }
        // odd classes get graded penalty by distance to nearest multiple of 5
        let d = (post_residual % 5) as f64;
        score += d * 3.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover is "useful": reward by tightness of that fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.3;
            // exact chain fit (post_residual == next_item_size) is gold
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // leftover cannot host next item: penalize proportional dead space
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many open bins: prefer consolidation into fuller bins
    if open_bins_count > 3 {
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * (open_bins_count.min(20) as f64) * 1.5;
    }

    // Late in the stream: tighten packing, penalize loose residuals harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: neutral-ish but discouraged early, more acceptable
    // when mean residual across open bins is high (open bins are all poor).
    if bin_residual == bin_capacity {
        let base = 55.0 - 0.4 * progress * 40.0;
        score = base + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity - 10 {
            score -= 15.0; // big next item: fresh bin is fine
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: gaps too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: neutral-ish base, but allow it when the
    // item would leave a large residual that could serve the next item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // If next item would fit into the residual this placement leaves,
        // a fresh bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        // Late in the stream, prefer reusing existing bins.
        score += 20.0 * progress;
    } else {
        // Prefer bins whose residual matches the next item's needs.
        if next_item_size > 0 {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 15.0 / (1.0 + diff);
        }
        // Favor bins below mean residual (tighter than average).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            // partial reward scaled by how much slack remains after next item
            let after_next = post_residual - next_item_size;
            score -= 30.0 - (after_next as f64) * 0.25;
        } else {
            // next item won't fit here; penalize large dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: minimize residual as usual
        score -= 5.0;
    }

    // Tight-fit bonus: small post_residual is good dead-space-wise, but only if not tiny-useless
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly perfect fit now
    } else if post_residual == 0 {
        score -= 10.0; // bin fully closed
    }

    // Relative-to-mean coupling: prefer bins whose post residual sits below mean residual
    // (concentrate waste in few bins rather than spreading it).
    score += (post_residual as f64 - mean_residual) * 0.12;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; grows slightly with number of open bins
        // and stream progression (encourage consolidation early).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // if next item is huge, an empty bin is more attractive (it can host anything)
        if next_item_size > 50 {
            score -= 12.0;
        }
    }

    // Mild penalty for wasting a big bin on a small item when other bins exist
    if bin_residual == bin_capacity && item_size <= 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a multiplicative discount.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score *= 0.5 + fit_ratio;

    // Penalize bins whose residual after placement can't fit the next item well
    // but could have fit it before (wasteful fragmentation).
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 25.0;
        }
        // Reward bins that leave room exactly for the next item.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        // Reward exact match for next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // would leave a very tight residual, or when open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 60.0
            - 40.0 * large_item
            - 20.0 * (mean_residual / bin_capacity as f64)
            + 10.0 * progress;
        // If item would leave near-perfect residual for the next item, encourage new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 10.0;
        }
        // Don't open new bins too eagerly when many bins already fit the item.
        if fitting_bins_count > 2 {
            new_bin_score += 25.0;
        }
        score = score.max(new_bin_score);
    }

    // Slight preference for filling fuller bins (larger item relative to residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 8.0;

    // Mild global pressure: fewer open bins relative to items -> prefer reusing.
    let pressure = open_bins_count as f64 / total_items.max(1) as f64;
    score += pressure * 5.0;

    // Penalize leaving residuals in the awkward 20-40 "dead zone" that few items fill.
    if post_residual >= 20 && post_residual <= 40 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty on
    // small-but-awkward residuals via quadratic coupling.
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm));

    // Smooth non-linear interaction of residual waste with stream progress:
    // early on, waste is cheaper; late in the stream, waste is heavily punished.
    let progress_weight = 0.5 + 1.5 * t * t;
    score += progress_weight * (pr * pr) / cap;

    // Penalize residuals that are far from the mean residual of open bins
    // (encourages a balanced residual profile), smoothly damped.
    score += 0.6 * (pr - mean_residual).abs();

    // Lookahead coupling: reward this bin if the next item fits the post residual,
    // punish if the post residual becomes useless for the known next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 3.0 * (ni / cap) * (1.0 - fit_norm);
        } else {
            score += 2.0 * (ni - pr) / cap * (1.0 + t);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * t;
    }

    // New-bin candidate handling: opening a fresh bin is penalized smoothly,
    // more so when other bins fit and when the stream is young.
    if bin_residual == bin_capacity {
        let fits_elsewhere = if fitting_bins_count >= 1 { 1.0 } else { 0.0 };
        score = cap * (1.0 + 0.6 * (1.0 - t)) * (1.0 + fits_elsewhere)
            + 0.3 * open_bins_count as f64;
        // But if post residual would be zero for the new bin (perfect waste anyway),
        // soften slightly so a new bin is chosen only when truly needed.
        if pr as u32 == 0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4; // 25
    let class = post_residual % quarter;
    match class {
        0 => score -= 60.0,                    // residual is an exact quarter multiple: reusable
        1..=5 => score += 25.0,                // tiny sliver: dead space
        _ => {}
    }

    // Integer-division threshold: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainability reward, stronger when the chained fit is tight
            let slack = post_residual - next_item_size;
            score -= 40.0 + (25.0 * (1.0 - slack as f64 / bin_capacity as f64));
        } else {
            // next item won't fit here: penalize leaving a hole smaller than next item
            if post_residual > 0 && post_residual < next_item_size {
                score += 30.0;
            }
        }
        // harmonic pairing: item + next summing near capacity is excellent
        let pair = item_size as u32 + next_item_size;
        if pair <= bin_residual && bin_residual - pair < quarter {
            score -= 35.0;
        }
    } else {
        // last item: minimize leftover absolutely
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when this item would leave a bad class elsewhere
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        let many_open = open_bins_count as f64;
        if bad_fit {
            score -= 45.0;
        } else {
            score += 30.0 + 2.0 * many_open;
        }
    }

    // Progress-aware gentle pressure toward consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (1.0 - progress);

    // Prefer bins with residuals in harmonically "friendly" zones (multiples of 10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it's smaller than the smallest plausible item.
    let min_item = 1u32; // interface allows sizes down to 1
    if post_residual > 0 && post_residual < min_item.max(1) + 4 {
        score += 40.0;
    }
    // Penalize gaps too small for the lookahead item (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, mildly encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 1.5 * pressure * (1.0 - tightness) * (0.5 + 0.5 * progress);

    // Prefer bins with below-mean residual (consolidate emptier space usage).
    score += 0.05 * ((mean_residual - bin_residual as f64).max(-30.0).min(30.0));

    // New-bin candidate: neutral-ish baseline; only chosen when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight super-linear penalty.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if nxt <= post {
            // partial chaining bonus decays with leftover after next item
            let after_two = post - nxt;
            score -= 25.0 - after_two * 0.35;
        } else {
            // next item cannot fit here; penalize wasted residual relative to next item
            score += (post - nxt).abs() * 0.15;
        }
        // If next item is large and this bin is a poor fit, mild penalty
        if nxt > post {
            score += 3.0;
        }
    } else {
        // Last item: minimize post residual aggressively
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (post_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is bad or no good alternatives.
    if bin_residual == bin_capacity {
        let poor_fit = post_f > 40.0;
        if poor_fit || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 25.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_f / bin_capacity as f64);

    // Prefer filling bins that are already mostly used.
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize by fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize small dead space (hard to reuse later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting a large bin on this item.
            score += 8.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score -= 15.0 * open_pressure * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (fuller than average).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Time horizon: early in stream, be more willing to open new bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 30.0 + 60.0 * progress;
        // But if item is huge relative to typical residuals, new bin is attractive.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for very small items into very large residuals (wasteful).
    if item_size < 20 && bin_residual > 80 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalize post-residual and next item
    let pr_norm = pr / cap;
    let next_norm = (next_item_size as f64) / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is more costly -> amplify convex penalty
    let quad = pr_norm * pr_norm;
    let cubic = quad * pr_norm;
    score += (2.0 + 6.0 * progress) * 100.0 * quad + 150.0 * cubic * (0.5 + progress);

    // Reward bins whose residual can host the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let diff = pr_norm - next_norm;
        let diff2 = diff * diff;
        score -= 40.0 * (1.0 - diff2) * (0.5 + progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    } else {
        // mild crowding penalty scaled by number of alternatives
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins below mean residual (consolidating fuller bins)
    let mean_norm = mean_residual / cap;
    score += 20.0 * (pr_norm - mean_norm) * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin, more so early in stream
    if bin_residual == bin_capacity {
        score += 45.0 + 55.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: size classes by modular residue / division bands
    let item_class = item_size / 10;               // 0..=10 coarse band
    let next_class = next_item_size / 10;          // 0 if no next item
    let has_next = next_item_size > 0;

    // Reward tight fits: post_residual near zero is ideal
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        // Penalize dead space that is too small for small items (unusable)
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Harmonic pairing: if next item fits exactly into post_residual, big reward
    if has_next && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 40.0 - (pair_waste as f64) * 1.5;
        // Exact harmonic completion
        if pair_waste == 0 {
            score -= 35.0;
        }
    } else if has_next && next_item_size > post_residual {
        // Next item cannot follow here; penalize proportionally to how "orphaned" the residual is
        score += (post_residual as f64) * 0.35;
    }

    // Integer-division thresholds on post_residual: residual divisible into likely classes
    if post_residual >= 10 {
        let div_class = post_residual / 10;
        // Residuals that match a common item band are more reusable
        score -= (div_class as f64) * 2.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin only if item is large and no good existing fit exists
        let pressure = (item_size as f64) / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 55.0 - pressure * 30.0 - scarcity * 25.0;
        // Late in stream, keep bins closed (fewer total bins)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // Many open bins with large mean residual => don't open new
        score += (mean_residual / cap) * 10.0 + (open_bins_count as f64) * 1.5;
    }

    // Mild penalty for very fragmented bins relative to mean residual
    if (post_residual as f64) > mean_residual + 15.0 {
        score += 6.0;
    }

    // Small harmonic tie-breaker using item class parity
    if item_class % 2 == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items (1..=12) are effectively wasted capacity.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0;
    } else if post_residual > 12 && post_residual <= 20 {
        score += 18.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score -= 6.0;
    }

    // Perfect / near-perfect fits are extremely valuable.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Reward tight relative fit.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless
    // the fit is genuinely good.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when the item is huge
    // relative to available residuals or fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fit = (mean_residual - item_size as f64) < 15.0;
        let huge_item = item_size as f64 > 0.75 * bin_capacity as f64;
        if poor_fit || huge_item {
            score -= 55.0;
        } else {
            score += 45.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual <= 12 {
        score += 10.0; // would strand a dead gap the next item can't use
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (consolidating small leftovers into tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fill (smaller post_residual) is better.
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: strongly reward if the next item fits
    // exactly into the post-residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: post residual consumed by next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decays with leftover after next placement.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * over;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are
    // "nearly full" -> good to fill them; penalize dumping into fat bins.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= 0.5 * (mean_residual - resid);
    } else {
        score += 0.5 * (resid - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a fresh bin attractive only
    // when the current placement would create large dead space that the
    // next item cannot use.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline, but if the item nearly fills a
        // bin on its own or the next item is large, opening is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = post_residual as f64 * 0.9;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can also serve next item
        }
        // Late in stream, slightly discourage proliferation of open bins.
        score += 5.0 * progress * open_bins_count as f64;
    } else if post_residual > 0 && post_residual < 10 {
        // Creating tiny unusable dead space is bad (sizes >= 1 assumed but
        // small dead space rarely reusable): penalize.
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Small dead space that no future item (min size 1) can use less severely.
    if post_residual > 0 && post_residual < 5 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item would not fit here anyway, mild penalty for wasting space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            score += 2.0;
        }
    }

    // Time horizon: later in the stream, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress;

    // Global state: penalize spreading across many open bins when mean residual is high.
    let mean_tight = mean_residual / bin_capacity as f64;
    if mean_tight < 0.2 && open_bins_count > 2 {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no open bin is a good home
    // (i.e., this bin is empty and item is large relative to capacity).
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * big;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= coupling * pr_norm * pr_norm * 30.0;

    // Reward tight fits more aggressively as stream advances
    let tightness = 1.0 - pr_norm;
    score -= progress * tightness * tightness * 10.0;

    // Penalize large dead space with cubic term in post_residual
    score += (pr_norm * pr_norm * pr_norm) * 15.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: reward bins whose post_residual matches next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 6.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Mild penalty when bin is far below mean residual (fragmentation risk)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    // New-bin candidate: penalize slightly unless post_residual is very large
    if bin_residual == bin_capacity {
        score += 5.0 - progress * 3.0 + pr_norm * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction slot does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;

    // Dead-space penalty: residuals in awkward modular classes are hard to fill.
    // Class 0: exact fit (post_residual == 0) -> best possible.
    if pr == 0 {
        score -= 60.0;
    } else if pr < eighth {
        // Tiny sliver, almost certainly dead space.
        score += 25.0;
    } else if pr < quarter {
        // Small residual: only useful for very small future items.
        score += 10.0;
    } else if pr == quarter || pr == 2 * quarter || pr == 3 * quarter {
        // Exact harmonic division points: highly reusable.
        score -= 15.0;
    } else if pr % 10 == 0 {
        // Round residuals are commonly matchable with typical item sizes.
        score -= 8.0;
    }

    // Integer-division threshold: how many "eighths" remain? Fewer eighths = tighter bin = better packing.
    let eighths_left = (pr / eighth.max(1)) as f64;
    score -= eighths_left * 3.0;

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward bins that can also host the next item, scaled by how snugly.
            let snug = 1.0 - (pr - next_item_size) as f64 / cap_f;
            score -= 12.0 + 10.0 * snug;
            // Harmonic match: next item leaves another round/harmonic residual.
            let pr2 = pr - next_item_size;
            if pr2 == 0 || pr2 % 10 == 0 || pr2 == quarter || pr2 == 2 * quarter {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: this bin becomes dead after this placement.
            score += 8.0;
        }
    } else {
        // Last item: exact closure is maximally valuable.
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // open bins would create large dead space. Penalize the empty bin mildly so
    // decent fits win, but strongly when open bins are nearly full anyway.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty keeps existing bins preferred.
        score += 30.0;
        // If mean residual across open bins is small (bins nearly full), a new
        // bin is reasonable: reduce the penalty.
        score -= (cap_f - mean_residual).min(cap_f) * 0.15;
        // Late in the stream, consolidating matters more; new bins cost more.
        score += 10.0 * progress;
        // If many bins already open and none fit well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open bins pressure: favor reusing existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull score toward mean residual: prefer bins near average fullness.
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && (post_residual as u32) > 0 {
            score += 8.0; // dead space unusable by next item
        }
    } else {
        // Last item: prefer finishing with tightest fit.
        score -= 5.0 * fill_ratio;
    }

    // New-bin candidate: prefer opening a new bin only when item is large
    // relative to residual of existing bins (avoid wasting fresh capacity).
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly or tightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted space relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
