    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Compare residual against mean residual: prefer bins with less residual (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline high; reduced only if nothing else fits well.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild progression term: early in stream, be more open to new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that no realistic future item can use.
    if post_residual > 0 {
        let usable = if next_item_size > 0 {
            (post_residual as f64 / next_item_size as f64).floor().max(0.0)
        } else {
            1.0
        };
        if usable < 1.0 {
            score += post_residual as f64 * 0.8; // pure dead space penalty
        } else {
            score -= usable * 1.5; // space reusable by lookahead item
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Next item larger than post_residual: this bin can't take it, mild penalty
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidation into fuller bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    // Global residual pressure: if mean residual is high, prefer filling emptier bins less.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Time horizon: early on, be picky (penalize mediocre fits); late, accept anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64) * 0.25;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when current bins are fragmented or item is huge.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 || item_size > bin_residual - item_size.max(0) {
            score -= 6.0 + fragmentation * 4.0;
        } else {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // fresh bin can pair item with lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr / cap;

    // Smooth coupling: residual^2 term scaled by progress — dead space penalized more as stream advances
    let norm_pr = pr / cap;
    score += (norm_pr * norm_pr) * (0.5 + progress);

    // Tight fit reward: polynomial peak near zero post-residual
    score -= (1.0 - norm_pr).powi(3) * (0.3 + 0.4 * progress);

    // Last-chance bonus: smooth sigmoid-like reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.5 + 0.5 * progress;
    }

    // Lookahead coupling: reward if next item fits smoothly in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            score -= gap * (1.0 - gap) * 2.0 * (0.5 + 0.5 * progress);
        } else {
            score += (-gap) * (1.0 + progress);
        }
    }

    // Mean residual deviation: penalize bins far from mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 0.3;

    // New-bin candidate: penalize slightly so we prefer existing bins unless very poor fit
    if bin_residual == bin_capacity {
        score += 0.25 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to lookahead: penalize unusable leftover.
        score += 6.0 * (post_residual as f64) / (next_item_size as f64).max(1.0);
    }

    // Harmonic class of post_residual: residues in (0,10] are near-waste;
    // residues that are multiples of common item classes (10,20,25,50) are reusable.
    if post_residual > 0 {
        let r = post_residual;
        let reusable = (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0);
        if reusable {
            score -= 4.0;
        } else if r < 10 {
            score += 8.0 * (1.0 - r as f64 / 10.0); // tiny dead space penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: add a fixed opening cost, discounted when the item
    // is large (better to start fresh for big items) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 10.0 + 20.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        score += open_cost - 3.0 * (open_bins_count as f64).min(10.0) - 2.0 * progress;
    } else {
        // Mild preference for fuller bins among open ones.
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space zone: gaps that cannot fit the smallest plausible item
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        }
        // Also penalize gaps too small for the lookahead item
        if next_item_size > 0 && gap < next_item_size as f64 {
            score += 15.0 * (next_item_size as f64 - gap) / next_item_size as f64;
        }
        // Non-linear dead-space coupling: quadratic penalty on tight gaps
        score += 0.05 * (100.0 - gap) * (gap / 100.0).powi(2) * 10.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many fitting candidates
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Open bins pressure: discourage opening new bins when few bins open,
    // encourage consolidation when many bins open
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (10.0 + 40.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open
        score += 10.0 + 8.0 * bin_pressure;
        // But allow new bin if all open bins would leave terrible dead space
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Reward placing into existing bins, scaled by how full they are
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill_ratio;
        // Consolidation pressure when many bins are open
        score -= 3.0 * bin_pressure.min(3.0);
    }

    // Mean residual coupling: prefer bins tighter than average
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= 0.15 * (mean_residual - residual);
    } else {
        score += 0.10 * (residual - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-waste obsession.
    score += (post_residual as f64 / bin_capacity as f64) * 60.0;

    // --- 2-step lookahead matching (archetype core) ---
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly fits next item -> huge reward.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: reward proportional to leftover-after-next tightness.
            let after_next = post_residual - next_item_size;
            score -= 40.0 * (1.0 - after_next as f64 / bin_capacity as f64);
            // Small controllable remainder after next item is fine.
            if after_next <= 10 {
                score -= 15.0;
            }
        } else {
            // Dead space: next item cannot use the remainder -> penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 + dead * 0.9;
            // Very small un-usable remainder is worse than moderate remainder.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual far above mean are "loose"; prefer balancing them when fit is loose.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / mean_residual;
        if post_residual as f64 > mean_residual {
            score += 10.0 * dev.max(0.0);
        } else {
            score -= 6.0 * (-dev).max(0.0);
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or hopeless fits.
        let tight_open = post_residual as f64 <= 10.0;
        if tight_open {
            score -= 20.0; // near-perfect pack in fresh bin
        } else {
            // Penalize new bins, less so early in stream / many open bins.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score += 45.0 + 60.0 * progress;
        }
    }

    // Mild preference for denser bins among equals.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

