    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: penalize leaving residual it could have used elsewhere poorly.
            score += 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins over new ones.
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += mean_ratio * 20.0;
    score -= (open_bins_count as f64).ln().max(0.0) * 6.0;

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and no good fit exists; make the empty bin less attractive otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item_bonus = if item_size >= 50 { 0.0 } else { 25.0 };
        score += 35.0 + big_item_bonus - fit_ratio * 20.0 + progress * 10.0;
        if fitting_bins_count == 1 {
            // There is a last-chance open bin; discourage new bin.
            score += 45.0;
        }
    }

    // Time horizon: early in the stream, keep bins flexible (favor mid-range residuals);
    // late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste-minimizing core)
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress:
    // late in the stream, tight fills matter more; early, keep flexibility.
    let tightness = 1.0 - norm_pr;
    score += 12.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for the smallest possible item
    let dead = if pr < 1.0 { 0.0 } else { (1.0 - pr / 1.0f64.max(next_item_size.max(1) as f64)).max(0.0) };
    score += 6.0 * dead * dead * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual (smooth quadratic)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).powf(2.0)) * (1.0 - progress);
        } else {
            score += 4.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: only fitting bin => strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly when open bins exist and mean residual is healthy
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 10.0 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    // Congestion: many open bins -> favor consolidation of large residuals
    score += 2.0 * (open_bins_count as f64).sqrt() * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes (mod classes) are valuable.
    let harmonic_bonus = |r: u32| -> f64 {
        if r == 0 { return 20.0; } // perfect fit is best
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if r % m == 0 { h += 6.0; }
        }
        if r <= 10 { h -= 8.0; }       // dead space: too small for typical items
        else if r <= 20 { h -= 3.0; }  // nearly dead
        h
    };
    score += harmonic_bonus(post_residual);

    // Integer-division threshold coupling: pair current leftover with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains perfectly into this bin -> strong reward.
            score -= 12.0;
            if post_residual == next_item_size { score -= 8.0; }
            // Harmonic match: next item leaves a class-nice residual too.
            let pr2 = post_residual - next_item_size;
            score += harmonic_bonus(pr2) * 0.5;
        } else {
            // Next item cannot follow: penalize proportionally to wasted chain potential.
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when all open residuals are fragmented.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 { score -= 40.0; }
        // If mean residual across open bins is large and harmonically aligned, prefer reusing.
        if mean_residual > item_size as f64 + 15.0 { score += 25.0; }
    } else {
        // Prefer bins whose residual is far from capacity (well-utilized) when fit is tight.
        let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= tightness * 5.0;
    }

    // Progression-aware: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by the post-residual gap, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: prefer existing bins as bin count grows.
    if bin_residual < bin_capacity {
        score -= 2.0 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize proportional to existing open bins.
        score += 5.0 * open_bins_count as f64;
        // But allow opening when no bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mean residual coupling: if this bin's residual is well below mean, it's a tight fit; reward.
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Slight progression bias: early on, be more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let slack = post_residual as f64 - next;
            // Perfect chaining bonus: next item exactly fills the bin.
            if slack < 0.5 {
                score -= 60.0;
            } else {
                // Reward good chaining, proportional to how well next item uses remaining space.
                score -= 40.0 * (next / post_residual as f64);
                score += slack * 0.3;
            }
        } else {
            // Next item cannot fit here: penalize leaving large unusable-ish gaps.
            let gap = next - post_residual as f64;
            score += gap.min(30.0) * 0.5;
        }
    }

    // Compare against mean residual: bins below mean residual are "tighter" — favor them.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual is huge, i.e., terrible fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // But if the fit is very loose, soften the bonus so a new bin can win.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score += 20.0;
        }
    }

    // Discourage opening new bins early in the stream when open bins can fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, a fresh bin is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item is small, an empty bin can host it later; slight discount.
        if next_item_size > 0 && (next_item_size as f64) < 0.35 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional to wasted fraction of capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 30.0;

    // Reward filling bins deeply (high utilization of residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if next item fits in the post residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Dead space risk: next item can't use leftover space.
            score += 8.0;
        }
        // If next item fits perfectly with post residual, extra bonus.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all open
    // bins are poorly filled and the item is large.
    if bin_residual == bin_capacity {
        // Mild default penalty; overcome only by very poor open-bin fits.
        score += 12.0;
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        if avg_open_fill < 30.0 && open_bins_count > 0 {
            // Open bins are mostly empty; prefer them over a new bin.
            score += 25.0;
        }
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 * 0.5 {
            // Large item, no good home: opening fresh bin is reasonable.
            score -= 18.0;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Time horizon: early in the stream, be more open to new bins (flexibility);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 8.0;
    }

    // Many open bins: discourage fragmentation, favor tight fits even more.
    if open_bins_count > 5 {
        score += post_residual as f64 * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (30.0 + 40.0 * progress);
    // penalize waste relative to mean residual
    score += 0.5 * (pr - mean_residual);
    // lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // discourage opening many bins early
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_u = bin_capacity.max(1);
    let cap = cap_u as f64;
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let next_u = next_item_size;
    let next = next_u as f64;
    let has_next = next_u > 0;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let open_pressure = (open_bins_count.min(64)) as f64 * 0.7;
    let is_new = bin_residual == bin_capacity;

    let mut score = post;

    let band_size = (cap_u / 10).max(1);
    let post_eighth = post_residual.saturating_mul(8) / cap_u;
    let next_eighth = next_u.saturating_mul(8) / cap_u;
    let post_band = post_residual / band_size;
    let next_band = next_u / band_size;

    if post_residual == 0 {
        score -= 20.0;
    } else {
        if post_residual <= cap_u / 20 {
            score -= 5.0;
        }
        if post_residual % 10 == 0 {
            score -= 1.0;
        }
        if post_residual > cap_u / 2 {
            score += (post - cap * 0.5) * 0.04;
        }

        if item_size > 1 && post_residual >= item_size {
            let slack_same = post_residual - item_size;
            score -= 3.0 * (1.0 - slack_same as f64 / cap);
            if post_residual % item_size == 0 {
                score -= 1.0;
            }
        }

        if has_next {
            if post_residual >= next_u {
                let slack = post_residual - next_u;
                score -= 14.0 * (1.0 - slack as f64 / cap);

                if slack == 0 {
                    score -= 8.0;
                }
                if next_u > 1 && post_residual % next_u == 0 {
                    score -= 4.0;
                }
                if post_eighth == next_eighth {
                    score -= 2.0;
                }
                if post_band == next_band {
                    score -= 1.0;
                }
            } else {
                let miss = (next_u - post_residual) as f64;
                score += 3.0 + miss * 0.10;

                if miss <= 5.0 {
                    score += 6.0;
                }
                if post_eighth == next_eighth {
                    score += 2.0;
                }
                if bin_residual >= next_u {
                    score += 7.0 + (bin_residual - next_u) as f64 * 0.05;
                }
            }
        }
    }

    if pre < mean_residual {
        score -= 1.0;
    } else if pre > mean_residual {
        score += 0.5;
    }

    if !is_new {
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else if fitting_bins_count == 2 {
            score -= 3.0;
        }
    } else {
        score += 24.0 + open_pressure + progress * 5.0 + mean_residual * 0.04;

        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if fitting_bins_count == 1 {
            score += 35.0;
        }

        if has_next
            && post_residual >= next_u
            && fitting_bins_count <= 2
            && item_size <= cap_u / 2
            && mean_residual < next
        {
            score -= 12.0 + next * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or < half of smallest item)
    // are heavily penalized, but a perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer reusing existing bins
    // when many bins are open; allow new bins when few are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when existing residuals are tight
        score -= (mean_residual / 10.0).min(20.0);
        score -= 5.0;
    } else {
        score += (open_bins_count as f64) * 0.5;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for next item: huge bonus.
        if diff == 0.0 {
            score -= 1000.0;
        } else {
            // Reward tight match to next item, scaled by item size (bigger next item = tighter coupling).
            score -= 60.0 * (1.0 - diff / (next_item_size as f64 + 1.0)).max(0.0);
        }
        // Penalize residuals too small for the next item (dead space for lookahead).
        if (post_residual as u64) < (next_item_size as u64) {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: reward zero post residual heavily.
        score -= 500.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize small leftover residuals that are hard to fill (unusable dead space),
    // but only if they don't match the next item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large (would leave a tight fit anyway) or the mean residual
    // of open bins is poor.
    if bin_residual == bin_capacity {
        // Baseline penalty so new bins are not opened frivolously.
        score += 30.0;
        // If the item leaves a residual that matches the next item, a fresh bin is great.
        if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
            score -= 1200.0;
        }
        // If existing bins are fragmented (high mean residual spread), opening fresh is fine.
        if mean_residual < 25.0 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins unless necessary.
        if next_item_size == 0 {
            score += 500.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight packing) relative to mean residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness);

    // Mild preference to spread load when many bins are open (avoid extreme fragmentation).
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Strong reward for near-perfect fits (dead space penalty is superlinear)
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 30.0;

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
        // extra reward if next item then leaves a small remainder too
        let chain_post = post - next_item_size as f64;
        if chain_post < cap * 0.15 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post > 0.0 {
        // dead space that the next item cannot use: penalize
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins with larger residuals
    if open_bins_count > 2 {
        let norm_res = bin_residual as f64 / cap;
        let mean_norm = mean_residual / cap;
        if norm_res > mean_norm {
            score -= 3.0 * (norm_res - mean_norm);
        } else {
            score += 3.0 * (mean_norm - norm_res);
        }
    }

    // Early stream: be more liberal, keep options open (mild new-bin tolerance)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    // New-bin candidate: penalize opening a bin unless the item is large
    // or no existing bin gives a decent fit (post_residual large anyway).
    if bin_residual == bin_capacity {
        let base = 10.0 - 8.0 * (item_size as f64 / cap);
        score += base;
        // if item is huge, a fresh bin is natural
        if item_size as f64 > cap * 0.6 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = (item_size, bin_residual, bin_capacity, step_index, total_items, open_bins_count, mean_residual, next_item_size, post_residual, fitting_bins_count);
    0.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are "nice"
    // multiples of common item sizes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are multiples of 10 (harmonic class)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    // Penalize awkward tiny residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this bin becomes a two-item chain — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr % 10 == 0 {
                score -= 8.0;
            }
            if npr < 10 {
                score += 10.0;
            }
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += pr / cap * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // are all fairly full (mean residual small) or item is large.
    if bin_residual == bin_capacity {
        let mean_r_norm = mean_residual / cap;
        let item_norm = item_size as f64 / cap;
        score += 15.0 - 20.0 * (1.0 - mean_r_norm) - 10.0 * item_norm;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits, must open
        }
    }

    // Slight preference for fuller bins (small residual) as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - pr / cap) * 4.0 * (0.5 + 0.5 * progress);

    // Tie-break with mean residual alignment
    if (pr - mean_residual).abs() < 5.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste; penalize them heavily.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        // Fully consumed bin is ideal; anything in (0, 10) is dead space.
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else {
        // Usable but tight gaps are less flexible: mild penalty.
        if post_residual < 20 {
            score += 5.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the empty new-bin candidate).
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if existing bins would leave huge dead space, new bin is fine.
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Progress-scaled tie-breaker: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: big reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward decreasing with slack; a perfect chain is best.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            let deficit = (next_item_size - post_residual) as f64;
            score += 15.0 * (deficit / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post_residual strongly.
        score -= 10.0;
    }

    // Penalize dead space that is too small for any plausible item (min size 1).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tight" —
    // filling them further is good; bins above mean waste space.
    let cap = bin_capacity as f64;
    let relative = (bin_residual as f64 - mean_residual) / cap;
    score += 12.0 * relative;

    // Slight preference for consolidating into fewer bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Mild penalty for opening a new bin early in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
        // But if no open bin fits well (large post_residual elsewhere), new bin
        // becomes attractive via the base post_residual comparison.
        if next_item_size > 0 && next_item_size == item_size {
            score -= 5.0; // same-size stream: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * chain;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        let waste = post_residual as f64 / next_item_size as f64;
        score += 8.0 * waste;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., the item would leave a lot of unusable space in existing bins).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let dead_space = (bin_capacity - item_size) as f64;
        // Opening a new bin is penalized mildly, more so late in the stream
        // and when many bins are already open (encourage closing them out).
        let mut open_penalty = dead_space * (0.5 + 0.5 * progress);
        open_penalty += 2.0 * open_bins_count as f64;
        // But if mean residual is small (existing bins are nearly full),
        // opening a new bin becomes attractive.
        open_penalty -= 1.5 * mean_residual;
        score += open_penalty.max(-10.0);
    }

    // Prefer bins whose residual deviates from the mean in a "complementary" way:
    // placing into a bin with residual close to item size keeps mean residual low.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling bins that are already partially used.
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.1 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) waste penalty
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth stream-progress coupling: later in the stream, waste is costlier
    let progress_coupling = 1.0 + 0.6 * progress * (1.0 - 0.5 * pr_norm);
    score *= progress_coupling;

    // Reward tight fits: subtract smooth function of item/capacity ratio
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill * (1.0 - pr_norm);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Lookahead: if next item fits in post_residual, reward this placement smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * fit_quality;
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space smoothly
        score += 4.0 * pr_norm * (next_item_size as f64 / cap);
    }

    // New-bin candidate handling: only attractive early or when open bins are poor fits
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score = 30.0 + 40.0 * progress - 20.0 * scarcity;
    }

    // Mild open-bins pressure to avoid bin proliferation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "large" classes (> half capacity) remain highly reusable.
    let cap = bin_capacity as f64;
    let half = cap * 0.5;
    let quarter = cap * 0.25;

    if (post_residual as f64) >= half {
        score -= 12.0; // big leftover is valuable
    } else if (post_residual as f64) >= quarter {
        score -= 4.0;
    }

    // Dead-space penalty: small unusable leftovers (harmonic class ~0..10)
    if post_residual < 10 {
        score += 15.0;
    }

    // Integer-division thresholds: leftover divisible into common item sizes
    // (mod arithmetic on post_residual for sizes 10..80 step 10)
    let pr = post_residual;
    if pr >= 10 && (pr % 10 == 0) {
        score -= 3.0; // leftover aligns with coarse harmonic grid
    }
    if pr >= 20 && (pr % 20 == 0) {
        score -= 2.0; // aligns with finer grid too
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Prefer exact/near-exact next-fit match
            let gap = pr - next_item_size;
            if gap == 0 {
                score -= 20.0;
            } else if gap < 10 {
                score -= 10.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 6.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere (large dead space) or no real fitting bin exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open new bin
        } else {
            // Opening a fresh bin is justified only if best alternative
            // would leave tiny dead space; approximate via mean residual.
            let mean_r = mean_residual;
            if mean_r < (item_size as f64) {
                score -= 8.0; // open bins too small on average -> new bin
            } else {
                score += 30.0; // keep using existing bins
            }
        }
    }

    // Mild stream-progress modulation: late in stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0 * (post_residual as f64 / cap);

    // Tie-break: prefer bins with residual close to mean (balance)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_gap = 1u32;
    if post_residual > 0 && post_residual < min_gap * 2 {
        score += 40.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        // Penalize gaps that are too small for the lookahead item but nonzero.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.3 * (next_item_size - post_residual) as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap remains usable by lookahead item
        }
    }

    // Reward tight fits relative to item size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    // Open-bin pressure: prefer reusing bins when many are open; favor new bins when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * (open_bins_count as f64).powf(1.2) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: penalize bins far below the mean residual (fragmented bins).
    score += 0.4 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: keep it neutral-ish, slightly favored when current fit is poor.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 15.0 + 0.6 * (open_bins_count as f64).powf(1.2);
        if item_size >= 70 {
            score -= 20.0; // large items start fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 30.0 - (post_residual - next_item_size) as f64;
    }
    // Dead space: next item does NOT fit in the leftover.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Tight fit reward: filling the bin almost completely.
    if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize residual far below mean residual (wasting a relatively empty bin).
    if (post_residual as f64) < mean_residual - 20.0 {
        score += ((mean_residual - 20.0) - post_residual as f64) * 0.3;
    }

    // Last-chance bin: only one bin fits the item; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is very small.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (wasted capacity).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.7) / (bin_capacity as f64).powf(0.7);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Slight penalty if next item won't fit here (may force new bin).
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, prefer tighter fits: compare residual to mean.
        score += (bin_residual as f64 - mean_residual) * 0.6;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    // (high mean residual spread / item doesn't pair well).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = (item_size as f64 / bin_capacity as f64).powf(2.0);
        // Base cost of opening a new bin decays slightly over the stream.
        let mut new_bin_cost = 55.0 - 15.0 * progress;
        // If the item is large, a fresh bin is more valuable.
        new_bin_cost -= 20.0 * tightness;
        // If no open bin fits well (post_residual would be tiny elsewhere),
        // discount the new-bin cost.
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // If next item pairs with this item in a fresh bin, discount further.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost + post_residual as f64;
    }

    // Mild regularization against bin proliferation late in stream.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: penalize large residual, but with non-linear decay so small residuals are strongly favored
    let mut score = norm_pr.powf(1.8) * cap * 0.6;

    // Smooth coupling of post_residual with stream progress: early on tolerate residual, later tighten
    score += norm_pr * (1.0 + 2.5 * progress.powf(2.0)) * 8.0;

    // Quadratic interaction: post_residual vs next item fit (smooth lookahead bonus)
    let fit_gap = (pr - nxt).abs();
    score -= 6.0 * (-fit_gap / 30.0).exp() * (1.0 + progress);

    // Penalize near-perfect fit waste only late in stream (smooth cubic coupling)
    score += norm_pr.powi(3) * (1.0 - progress) * 5.0;

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Crowding: many open bins -> prefer filling existing ones (smooth in open count)
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln() + 1.0;
    score -= crowd * item * 0.05;

    // Mean residual alignment: prefer bins whose post residual approaches mean (smooth)
    score += (pr - mean_residual).abs() * 0.03;

    // New-bin candidate: penalize opening a new bin unless it yields excellent packing
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress - 0.15 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) leave "reusable" gaps; odd/prime-ish residues are dead space.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -9.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        3.0 // awkward residue -> dead space penalty
    };
    score += harmonic_bonus;

    // Integer-division threshold classes on post_residual
    let small_gap_class = pr / 10; // 0..10
    if small_gap_class <= 1 && pr > 0 {
        score += 6.0; // tiny unusable gap (1..19)
    } else if small_gap_class >= 5 {
        score -= 2.0; // generous leftover, still reusable
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain-friendly: reward proportionally to how snugly next item fits
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 - snug * 0.08;
            // harmonic class of next item too
            if next_item_size % 10 == 0 { score -= 2.0; }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    } else {
        // last item: prefer tightest packing, no future concern
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // open bins are nearly full / fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty to prefer existing bins
        score += 20.0;
        // if mean residual across open bins is small, opening a bin is fine
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac < 0.25 {
            score -= 18.0 * (1.0 - progress * 0.5);
        }
        // large item with lookahead needing space: new bin attractive
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference to fill fuller bins first (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight tie-break noise-free deterministic jitter via step parity
    if step_index % 2 == 0 { score -= 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's smaller than the minimum plausible item size (1)
    // but more meaningfully if it's too small to be useful relative to stream scale.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = 1.0 + 9.0 * (1.0 - progress); // early stream: keep gaps >= ~10 usable
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += (min_useful - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    }

    // Nonlinear dead-space penalty: quadratic growth for awkward mid-range gaps
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 25.0 {
        score += (25.0 - pr) * (25.0 - pr) * 0.05;
    }

    // Open-bins pressure: discourage spreading across many bins when few bins fit the item
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Prefer bins tighter than the mean residual (better fit density)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make empty bins moderately attractive only when current
    // bins would leave large dead space or none fit well.
    if bin_residual == bin_capacity {
        score = 55.0 + item_size as f64 * 0.2 - (fitting_bins_count as f64) * 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space super-linearly (wasted capacity).
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 120.0;
    }

    // 2-step lookahead: if the next item fits into post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 80.0 * (1.0 - snug);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(60.0) * 0.5;
    }

    // Compare against mean residual: prefer bins with residual below average
    // (tighter bins get filled first, keeping loose bins flexible).
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: only attractive when no good fit exists
    // (i.e., item leaves large dead space in every fitting bin) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = if next_item_size > 0 {
            (post_residual < next_item_size && post_residual > 0) as f64
        } else { 0.0 };
        score += 60.0 - 40.0 * bad_fit - 20.0 * (1.0 - progress) - (open_bins_count as f64) * 2.0;
    }

    // Slight preference for fuller bins overall.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / (bin_capacity as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        let penalty = 40.0
            - 30.0 * large_item
            + 20.0 * crowding
            - 10.0 * progress
            - 2.0 * open_bonus;
        score += penalty.max(-10.0);
    }

    // Mild preference for fuller bins among equals.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping.
    let mut score = x * x * cap;

    // Smooth non-linear coupling with stream progress: later in the stream,
    // tighten fits more aggressively (dead space becomes costlier).
    let progress_coupling = (1.0 - progress) * (x * (1.0 - x) * 4.0) * cap * 0.25;
    score += progress_coupling;

    // Penalize post residual close to next item size mismatch via smooth interaction.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let nx = nxt / cap;
        // smooth interaction: reward when next item fits well into post residual
        let fit_term = (1.0 - x) * nx * (1.0 - nx) * cap;
        let gap_term = (gap / cap) * (gap / cap) * cap * 0.5;
        score += fit_term - gap_term;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= cap * (0.6 + 0.4 * progress);
    }

    // Slight penalty when many bins are open and this residual is wasteful.
    let waste = (x - mean_residual / cap).abs();
    score += open_bins_count as f64 * waste * cap * 0.02;

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += cap * (0.35 + 0.5 * (1.0 - progress) + 0.15 * (x * x));
        if fitting_bins_count == 0 {
            score -= cap * 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: small post-residuals are more "usable" by future items
    let pr = post_residual;
    let class: f64 = match pr {
        0 => -500.0,
        1..=5 => -80.0,
        6..=10 => -40.0,
        11..=20 => -15.0,
        21..=30 => 0.0,
        31..=50 => 10.0,
        _ => 20.0,
    };
    score += class;

    // Modulo-10 harmonic: residual aligned with typical item sizes (multiples of 10)
    if pr % 10 == 0 && pr > 0 {
        score -= 25.0;
    } else if pr % 10 != 0 {
        // penalize misaligned dead space more when residual is small
        score += (10 - (pr % 10)) as f64 * 0.5;
    }

    // If next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 600.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement
            let pr2 = pr - next_item_size;
            score -= 30.0;
            score += pr2 as f64 * 0.3;
            if pr2 % 10 == 0 { score -= 15.0; }
        } else {
            // next item won't fit here
            score += 20.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64).sqrt() * 5.0;
        // but if current bin fit is terrible (huge waste), new bin becomes attractive
        if item_size <= bin_capacity / 4 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Stream progression: later in stream, prefer compacting (waste matters more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        score += 25.0; // tiny dead gap: heavily penalize
    } else if post_residual < 20 {
        score += 10.0;
    } else if post_residual <= 30 {
        score -= 5.0; // usable medium gap: mild reward
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage fragmentation;
    // with few open bins, opening a new bin is cheap so prefer fresh capacity.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but attractive if the
        // item is large and would leave a bad gap in any existing bin.
        score = bin_capacity as f64 * 0.5 + pressure * 6.0;
        if item_size > 60 && post_residual < 20 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // lookahead item also fits a fresh bin
        }
    } else {
        // Existing bin: penalize when mean residual is high (fragmenting stream).
        score += (mean_residual - post_residual as f64).abs() * 0.15;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // keep room for the next item
        }
        if next_item_size > post_residual && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Late in the stream: consolidate, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            // Next item can also fit: reward proportionally to tightness.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space creation.
            score += 8.0 * diff / bin_capacity as f64;
        }
        // Extra bonus if both this item and the next exactly fill the bin.
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: pure tightness packing.
        score -= 10.0;
    }

    // Tight fits are good: small post_residual relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-average residual (consolidate emptier space usage).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly everywhere else or open-bin fits would waste a lot.
    if bin_residual == bin_capacity {
        let waste_penalty = (bin_capacity - item_size) as f64;
        let poor_fit_pressure = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        // New bin baseline: post_residual is large, so add a mild bonus
        // (subtract) that grows with how bad existing fits would be.
        score -= 5.0 + poor_fit_pressure * 0.5;
        // Penalize new bin when item is small (wasteful) or many bins open.
        score += waste_penalty * 0.4 + open_bins_count as f64 * 1.5;
        // Late in stream, prefer closing existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for fuller bins overall.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residuals that are too small to hold typical
    // future items are wasted, but exact-zero residual is perfect.
    if post_residual > 0 {
        let waste = if post_residual < 10 { 25.0 } else { 0.0 };
        score += waste;
    } else {
        score -= 30.0; // perfect fill bonus
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leave reasonable room usage
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for near-miss dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: prefer consolidation, penalize spreading.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already tight — using it is efficient.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, new bins are cheaper to open (more future to fill).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // smooth polynomial coupling of post residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // reward tight fits non-linearly
    score -= 3.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * fit_ratio;

    // penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr as f64 {
            score += 1.5 * (nx - pr as f64) / cap * (1.0 + progress);
        } else {
            score -= 0.5 * (1.0 - (nx - pr as f64).abs() / cap);
        }
    }

    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // mild penalty for spreading across many bins late in stream
    score += 0.05 * (open_bins_count as f64).ln() * progress;

    // new-bin candidate: neutral baseline with progress-aware cost
    if bin_residual == bin_capacity {
        score = 0.6 + 0.4 * progress + 0.3 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: divide capacity into 10 classes of 10.
    let class = post_residual / 10;
    // Reward landing exactly on a class boundary (clean harmonic slot).
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    // Penalize residuals in awkward classes (too small for typical items 10..80).
    match class {
        0 => score += 25.0,          // dead space
        1 => score += 12.0,
        2 => score += 4.0,
        3 | 4 => score -= 3.0,       // sweet spot: fits mid-size items
        5 | 6 => score -= 5.0,
        _ => {}
    }

    // Perfect fit bonus scaled by tightness.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // next item cannot use this sliver -> penalize
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when it's early
    // or current open bins are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_res_gap = mean_residual - post_residual as f64;
        // Early stream: fresh bins are cheap; late stream: prefer filling.
        score += 10.0 + 30.0 * (1.0 - progress);
        // If mean residual across open bins is small, opening fresh is fine.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
        // If open bins have plenty of room, discourage new bin.
        if mean_residual > 40.0 {
            score += 20.0;
        }
        let _ = mean_res_gap;
    }

    // Slight preference to pack into bins with residual close to item size
    // (minimize fragmentation relative to mean).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: mild dead-space penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, encourage filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    } else {
        // New empty bin candidate: penalize slightly unless existing bins
        // would create heavy dead space.
        score += 8.0 + pressure;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 10.0; // fresh bin can host both items
        }
        if fitting_bins_count == 1 {
            // Only one open bin fits; opening a new bin may be fine.
            score -= 5.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmented residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // chain fit quality: how well next item fills the remainder
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fill;
        } else {
            // next item won't fit: dead space penalty scaled by wasted gap
            let gap = (post_residual as f64) - (next_item_size as f64);
            score += 5.0;
            score += 0.1 * gap.min(30.0);
        }
    }

    // Compare post residual against mean residual of open bins
    // Placing into a bin whose residual is above average is better (consolidates space)
    if post_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin mid-stream when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    // Late stream: encourage closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that is too small for the smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward leaving space for the next item, penalize wasting
    // space the next item could have used elsewhere.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        if bin_residual >= next_item_size && post_residual < next_item_size
            && post_residual > 0 && post_residual < 10 {
            score += 15.0; // destroys a slot the next item could have used
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // fragmented or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Discount the penalty when the stream is late or bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for spreading across many open bins; encourage consolidation
    // when residuals are large on average.
    if open_bins_count > 2 && mean_residual > 40.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Time-varying exploration pressure: early in the stream, be slightly more
    // willing to try diverse placements; late, be conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post residual
    let x = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + progress);
    let mut score = pr - 30.0 * poly;
    // penalize dead space more as stream progresses (smooth ramp)
    score += (x * x) * cap * (0.15 + 0.45 * progress);
    // reward tight fits (small post residual) especially late
    score -= (1.0 - x).powi(3) * 10.0 * (1.0 + progress);
    // lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap)).powi(2);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }
    // last-chance bonus: avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // mild penalty for new bin when many bins already open and fit exists
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 5.0 + 10.0 * progress;
    }
    // tie-break toward bins near mean residual (smooth)
    score += ((mean_residual - pr) / cap).powi(2) * 4.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space thresholds
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit strongly rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small unusable dead space penalty (residual below min item size 1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // harmonic class match: next item leaves a "nice" residual again
            let pr2 = post_residual - next_item_size;
            if pr2 == 0 {
                score -= 250.0;
            } else if pr2 < 10 {
                score += 30.0;
            }
            score -= 40.0;
        } else {
            // next item cannot use this residual class: penalize leftover
            score += 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize slightly unless current bin would leave bad residual
    if bin_residual == bin_capacity {
        // opening fresh is fine when no good fit exists; base penalty scaled by open bins
        score += 80.0 - (open_bins_count as f64).min(50.0);
        // but if lookahead is large and current item small, fresh bin attractive
        if next_item_size >= 60 && item_size <= 30 {
            score -= 120.0;
        }
    }

    // Modulo-class coupling: residuals in multiples of 10 are "harmonic" and reusable
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    } else {
        score += 8.0;
    }

    // Integer division thresholds: penalize leaving residual in awkward band
    let band = post_residual / 20; // 0..5
    score += match band {
        0 => if post_residual > 0 { 40.0 } else { 0.0 },
        1 => 10.0,
        2 => 0.0,
        3 => -5.0,
        _ => -10.0,
    };

    // Mild pressure against hoarding many bins with high mean residual
    score += 0.05 * (mean_residual - pr).abs();

    // Progress-based tie-break: later in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * 8.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 6.0; // moderate dead zone
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: strongly reward
    }

    // Reward filling a bin nearly completely (post_residual small relative to capacity).
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and favor consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // Allow a new bin only if existing residuals are too small to be useful.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.8;
    }

    // Lookahead coupling: prefer bins whose leftover could still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // leftover can't fit next item -> dead space risk
        }
    }

    // Mild bonus for tight fit relative to item size.
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with next item is highly desirable ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Next item exactly fills this bin afterwards -> excellent chaining
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item also fits here: reward tight residual after chain
            let chain_residual = post_residual - next_item_size;
            score -= 25.0 - (chain_residual as f64).min(25.0);
        } else {
            // Next item cannot follow: penalize proportional leftover dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // --- Tight fit reward: small post_residual means efficient packing ---
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // --- Penalize unusable dead space (post_residual below minimum item size) ---
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- Relative to mean residual: prefer bins with residuals near/above mean
    // (keeps many medium bins available rather than fragmenting one) ---
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score += (mean_residual - residual) * 0.5;
    } else {
        score -= (residual - mean_residual) * 0.15;
    }

    // --- Early stream: be more conservative, keep bins balanced; later: pack tight ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;

    // --- Many open bins: discourage opening more unless fit is excellent ---
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a new bin
        score += 45.0 + (open_bins_count as f64) * 2.0;
        // But if the item is large and would leave a nice residual for the next item, ease up
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Large items early are fine to start fresh bins
        if item_size > 60 && progress < 0.5 {
            score -= 10.0;
        }
    }

    // --- Crowding: when many bins compete, prefer tighter fits more strongly ---
    if fitting_bins_count > 2 {
        score += (post_residual as f64) * 0.05 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows quadratically as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no realistic future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // post_residual too small for next item: mild penalty for stranded space.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin is badly fragmented
    // (high mean residual spread) or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - 15.0 * fragmentation / cap - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Prefer spreading load when many bins are open and mean residual is high.
    if bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 8.0 * fill_ratio;
        score += (open_bins_count as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
