pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residues divisible by common size classes
    // (multiples of 10) are "usable" dead space; odd residues are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill = (bin_residual - post_residual) as f64 / cap; // item fill fraction

    // Reward tight fits strongly.
    score -= 40.0 * (1.0 - pr / cap).powi(3);

    // Harmonic residue classes: post_residual % 10 == 0 is ideal (pairs with
    // any size-multiple-of-10 future item), %5 next best.
    let r10 = post_residual % 10;
    let r5 = post_residual % 5;
    if r10 == 0 {
        score -= 12.0;
    } else if r5 == 0 {
        score -= 6.0;
    } else {
        score += 8.0 + 2.0 * r5 as f64;
    }

    // Integer-division thresholds: leftover must be able to host next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportional to how snugly it would nest
            let nest = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - nest / cap);
            // harmonic bonus: both residuals land on same class of 10
            if (post_residual % 10) == (post_residual - next_item_size) % 10 && post_residual % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize, worse if only this bin fits
            score += 10.0 + 0.15 * next_item_size as f64;
        }
    }

    // Last-chance bin before opening a new one: strong reward to avoid waste.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Prefer filling bins below mean residual (compress variance).
    score += 0.3 * (pr - mean_residual).abs();

    // Late in the stream, consolidate: prefer existing bins over new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost + penalty that grows with progress
        score += 30.0 + 40.0 * progress + 0.2 * open_bins_count as f64;
        // but if item is huge relative to mean residual, new bin is fine
        if fill > 0.7 {
            score -= 25.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Penalize very small unusable leftovers (dead space zone < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for typical next items are risky dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space
    // or open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins by default.
        score += 25.0;
        // But if placing in this bin wastes a lot (post_residual unusable), opening fresh is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 50.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Open-bins pressure: many open bins -> favor filling existing ones (higher post_residual ok).
    score += open_bins_count as f64 * 1.5;

    // Late in stream, tighten up: waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0;

    // Slight preference for bins below mean residual (balance residuals, keep large gaps alive).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward when the next item
    // exactly fills the post residual (zero dead space across two steps).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits too: reward tight two-step packing.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the residual: penalize small dead space
            // that will be stranded (wasted below the minimum item size).
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 40.0 * (10.0 - waste);
            }
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first).
    let mr = mean_residual;
    if (bin_residual as f64) < mr {
        score -= (mr - bin_residual as f64) * 0.5;
    } else {
        score += (bin_residual as f64 - mr) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when existing bins could hold the item,
    // unless the item is large and residual is tight (new bin may be better).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = item_size as f64 / bin_capacity as f64;
        let existing_fit = if fitting_bins_count > 0 { 0.0 } else { 50.0 };
        score += 30.0 + 20.0 * (1.0 - tightness) + existing_fit - 10.0 * progress;
    }

    // Mild penalty for leaving large unusable gaps relative to capacity.
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tight_fit * tight_fit;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Exact pairing bonus
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the fullest (smallest residual) bin
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: penalize spreading across many open bins with high mean residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap * (1.0 - progress);

    // Late in stream, prefer compacting into fewer bins
    if progress > 0.5 {
        score += 0.2 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when item is large relative to residual
    // or no good fit exists; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let open_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 40.0 * fill_ratio - 50.0 * open_pressure
            + 10.0 * (1.0 - progress);
        // If next item is small, a fresh bin is useful
        if next_item_size > 0 && next_item_size < 30 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (2.0 - norm_pr);
    score += 30.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * progress;

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 4.0 * (1.0 - next_item_size as f64 / cap);
    }

    // Mild pressure against bin proliferation early on
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) * norm_pr;

    // New-bin candidate: make it attractive only for large items with poor fits
    if bin_residual == bin_capacity {
        score -= 12.0 * (item_size as f64 / cap) * (0.5 + progress);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions (1/8 buckets)
    let item_class = item_size / 13; // 0..7 coarse harmonic class
    let post_class = post_residual / 13;

    // Reward tight fits: post_residual near a "harmonic" residue class
    // Perfect fit (post_residual == 0) strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for the smallest item (<= 10),
        // but mildly reward post_residuals in reusable classes.
        if post_residual < 10 {
            score += 60.0 * (10 - post_residual) as f64;
        } else {
            // Reusability bonus: post_residual matching common item classes (10..80)
            // i.e., post_residual divisible into useful harmonic buckets.
            let reusable = post_residual >= 10 && post_residual <= 80;
            if reusable {
                score -= 12.0;
                // Extra bonus if post_residual is close to a multiple of a mid class
                let mid = post_residual % 25;
                if mid < 5 || mid > 20 {
                    score -= 6.0;
                }
            } else {
                // post_residual > 80: very large leftover, fine; > 80 only possible if item tiny
                score += 4.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
        if next_item_size == post_residual {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize leftover waste proportional
        // to how far the next item is from fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap.min(60.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty so
    // decent fits into open bins win, but terrible fits (large dead space) lose.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If item is large (harmonic class high), opening a fresh bin is natural
        if item_class >= 5 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Prefer bins with residual already below mean (consolidating small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Mild penalty per open bin to discourage keeping many bins alive
    score += 0.15 * open_bins_count as f64;

    // Harmonic modulo tiebreak on post_residual classes: prefer leftovers that
    // combine with typical small items (post_residual % 13 small => near class boundary)
    score += 0.2 * (post_class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (< 10) are unusable for typical items,
    // so heavily penalize leaving tiny gaps; large leftovers are still usable.
    let pr = post_residual as f64;
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - pr / 20.0);
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 80.0);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 6.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage proliferation of bins; encourage closing bins out.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit is poor
    // (large post_residual waste avoided by big items) or no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; offset by item size (big items benefit from fresh space)
        score += 18.0 - 0.15 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Slight preference for bins whose residual is already below mean (consolidation)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual quadratically.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // 2-step lookahead: reward exact match of next_item_size into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize wasting residual that next item could not use anyway.
        score += 5.0;
    }

    // Perfect two-item fill bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins deviating usefully.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0;
        // But if existing fits are terrible, allow new bin.
        if post_residual > bin_capacity / 4 {
            score -= 10.0;
        }
    }

    // Early stream: prefer tighter packing to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size {
            14.0
        } else {
            0.0
        };
        score += dead;
    }

    // Lookahead coupling: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 / (1.0 + diff);
        // If next item fits exactly after this placement, big bonus.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless placement
    // in open bins would create severe dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer filling existing bins.
        score += 15.0 * (1.0 - progress);
        // If many open bins already fit the item, opening a new one is wasteful.
        score += 6.0 * fitting_bins_count as f64;
        // Opening a new bin is attractive when open-bin residuals are fragmented.
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Prefer bins with residual close to the item (best-fit flavor) modulated by mean.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * gap;
        // Slightly prefer bins below mean residual (consolidate fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Mild pressure to keep the number of open bins low over time.
    score += 0.01 * open_bins_count as f64;

    // Time horizon: late in the stream, prioritize filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    // Smooth polynomial coupling of post_residual with stream progress
    let shape = prn * prn * (1.0 + progress) + prn * progress * (1.0 - progress);
    score += 8.0 * shape;
    // Reward tight fits smoothly (small post_residual), stronger later in stream
    score -= 6.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + progress);
    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0);
        score += 0.35 * waste * (1.0 + progress);
        // Smooth bonus if post_residual can still hold the lookahead item
        let fits_next = (pr / nxt).min(1.0);
        score -= 4.0 * fits_next * fits_next;
    } else {
        // End of stream: strongly prefer minimal post_residual
        score -= 6.0 * (1.0 - prn) * (1.0 - prn);
    }
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * prn);
    }
    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * prn;
    // Prefer bins below mean residual (fill emptier ones) with smooth coupling
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes mod capacity fractions
    let quarter = bin_capacity / 4; // 25
    let post = post_residual as f64;

    // Reward tight fits (small post_residual), especially into harmonic classes
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Penalize dead space that no plausible future item can use:
    // residual classes in (10, 20) are the worst "gap" band for items >= 10.
    if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Harmonic pairing: if next item exactly matches post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward partial usability of leftover space
        let usable = post_residual as f64 / next_item_size as f64;
        score -= 4.0 * (1.0 - 1.0 / usable.max(1.0));
    }

    // Modulo-class coupling: post_residual divisible by quarter => residual is
    // "harmonic" and reusable by items of size 25/50/75
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it when mean residual of open bins is already fragmented low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.15 && open_bins_count > 0 {
            score -= 10.0 + 10.0 * progress;
        } else {
            score += 6.0;
        }
    }

    // Prefer filling bins with low residual relative to fleet mean (balance)
    score -= 0.05 * (mean_residual - post);

    // Small penalty for opening many bins late in the stream
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize tiny unusable dead-space gaps (1..=9) heavily,
    // but only when the next item cannot use them.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 60.0 * (10.0 - post_residual as f64);
        }
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    }
    // Mild penalty if the leftover gap is too small for the next item anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // (tighter fits, i.e. small post_residual) over spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_capacity - post_residual) as f64 * 0.05;

    // Early in the stream, be more willing to open new bins for large items
    // that would leave big gaps in existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly less when item is large relative to residual,
        // penalize heavily when an open bin fits well (post_residual small).
        if post_residual < 20 && bin_residual != bin_capacity {
            score += 50.0;
        }
        score -= progress * 20.0;
        score += item_size as f64 * 0.1;
    }

    // Prefer bins whose residual is below the mean (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward near-zero post residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= (30.0 - diff.min(30.0)) * 0.5;
        }
        // Penalize dead space the next item cannot use (small unusable gaps).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer filling a bin as tightly as possible.
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins that end below-average residual.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless this bin would be a bad fit.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the current item is large and would leave a bad gap, opening fresh is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
        // Early in the stream, spreading out is less costly.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Slight preference to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are still too big for typical small items
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 6.0;  // awkward dead zone
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // next item won't fit here; wasted residual
        }
        // perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded and fit is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = mean_residual / bin_capacity as f64;
        // base penalty so we prefer reusing bins, scaled by how full open bins are
        score += 30.0 + 40.0 * (1.0 - crowding) - 20.0 * progress;
        // if the item is large relative to capacity, new bin more acceptable
        score -= 15.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild penalty for spreading across too many open bins when residuals are large
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual < bin_capacity {
        score += 3.0;
    }

    // Slight preference for bins with residual close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer filling bins loosely (keep flexibility); later, minimize dead space aggressively.
    let w_post = 1.0 + 2.5 * progress * progress;
    let mut score = post * w_post;

    // Penalize unusable dead space super-linearly (small post_residual that can't fit typical items).
    let dead = 1.0 - (post / cap).powf(0.5 + progress);
    score += 18.0 * dead * dead * (1.0 - post / cap);

    // Reward tight fits (post_residual near zero) with a smooth bump.
    let tightness = (-post / (0.15 * cap)).powi(2);
    score -= 10.0 * (-tightness).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let chain = 1.0 - (next_item_size as f64 / post).powi(2);
        score -= 8.0 * chain;
    } else if next_item_size > 0 {
        // Next item won't chain here; slight penalty grows with progress.
        score += 4.0 * progress;
    }

    // New-bin candidate: empty bin should lose to decent fits, but win over terrible ones.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln() + 1.0;
        score = cap * (0.6 + 0.4 * progress) / open_pressure + 6.0;
    }

    // Mild preference to balance residuals toward the mean across open bins.
    score += 0.15 * (post - mean_residual).abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions (eighths).
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1);
    score += class as f64 * 3.0; // prefer residuals landing in low (tight) classes

    // Strong reward for exact/near-exact fill (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual < eighth {
        score -= 20.0;
    }

    // Penalize residuals that are "dead zones": too small for the smallest plausible item (1..100 unknown).
    // Harmonic threshold: residual below 1/16 of capacity is nearly unusable.
    let sixteenth = (bin_capacity / 16).max(1);
    if post_residual > 0 && post_residual < sixteenth {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward leaves next_post in a good harmonic class
            let next_class = next_post / eighth.max(1);
            score -= (4 - next_class.min(4)) as f64 * 6.0;
            if next_post < sixteenth && next_post > 0 {
                score += 10.0; // would create dead space after next item
            }
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover size
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of opening a bin, discounted slightly as stream progresses
        let mut new_bin_cost = 70.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_cost = 5.0; // must open anyway
        } else if item_size > bin_capacity / 2 {
            // large item: opening a fresh bin is often fine (best-fit for big items)
            new_bin_cost -= 20.0;
        }
        // discourage new bin if mean residual across open bins is large (room available)
        new_bin_cost += mean_residual * 0.3;
        score += new_bin_cost;
    }

    // Mild tie-breaker: prefer bins with residuals in harmonically useful classes
    // (multiples of quarter capacity are easy to fill later).
    let quarter = bin_capacity / 4;
    if post_residual % quarter.max(1) == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize spreading across too many open bins when item is small.
    if item_size <= bin_capacity / 4 && open_bins_count > 3 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // plausible future item (sizes >= 1, but practically small gaps are waste).
    // Penalize hard when post_residual falls into the "unusable" zone.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones and
    // penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits well (item barely fits nowhere), allow new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins with residual near/below the mean
    // (fill the emptiest-but-fitting bins to consolidate dead space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Lookahead: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item cannot fit in the leftover, the leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    if next_item_size > 0 {
        // 2-step lookahead: reward bins whose post_residual can host the next item
        if post_residual >= next_item_size {
            // Reward proportional to how snugly next item fits into post_residual
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize dead space that cannot host the next item
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += 2.0 * waste / bin_capacity as f64 * 10.0;
        }
    } else {
        // Last item: just minimize leftover
        score += (post_residual as f64) * 0.5;
    }

    // Coupling with mean residual: prefer bins whose residual deviates below the mean
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large / no good fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // Large items are fine in fresh bins
        score -= 0.2 * item_size as f64;
    }

    // Prefer consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item can fit into the post-residual (chain placement).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for a near-perfect chain fit.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap < 10.0 {
                score -= 8.0;
            }
        } else {
            // Penalize leaving residue that the next item cannot use, scaled by how close it came.
            let miss = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += 0.10 * miss;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, tighten fits even harder since fewer future corrections remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if many bins are open with slack, discourage spreading;
    // if mean residual is low, prefer bins above the mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well (large item vs small residuals)
    // or when open bins are nearly full. Otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let spread = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // A new bin is worth it if item is big relative to mean residual or bins are scarce.
        let attraction = 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;
        score = 40.0 + spread * 0.5 - attraction * 0.3 - 30.0 * scarcity;
        // Late in the stream, opening new bins is less desirable.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post residual, with non-linear polynomial coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * progress)
        - 18.0 * (norm_pr * norm_pr) * (1.0 - progress);

    // Reward tight fits (near-zero post residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Penalize dead space: residuals too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (10.0 - pr) as f64 * (0.5 + progress);
    }

    // Lookahead: bonus if next item fits the post residual exactly-ish
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack.abs()) * (1.0 - progress);
    } else if next_item_size > 0 && (pr as u32) < next_item_size {
        score += 4.0 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: neutral-to-slightly-high baseline so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo common item sizes
    let pr = post_residual;
    let mut harmony_bonus = 0.0f64;
    if pr > 0 {
        // Check divisibility by common size classes (1..=100 stream)
        for m in [10u32, 20, 25, 30, 40, 50, 60, 70, 80, 90, 100] {
            if pr % m == 0 {
                harmony_bonus += 6.0;
            }
        }
        // Exact fit of next item into post residual is ideal
        if next_item_size > 0 && pr == next_item_size {
            harmony_bonus += 40.0;
        } else if next_item_size > 0 && pr >= next_item_size {
            // leftover after hypothetically placing next item
            let r2 = pr - next_item_size;
            if r2 % 10 == 0 { harmony_bonus += 12.0; }
            harmony_bonus += (r2 as f64) * 0.15;
        } else if next_item_size > 0 {
            // next item can't fit here; penalize dead space scaled by gap
            harmony_bonus -= ((next_item_size - pr) as f64) * 0.25;
        }
    } else {
        // Perfect closure: bin exactly filled
        harmony_bonus += 55.0;
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 10;
    match class {
        0 => harmony_bonus += 20.0,          // nearly full: excellent
        1 | 2 => harmony_bonus += 8.0,       // tight: good
        3 | 4 => harmony_bonus += 0.0,
        5 | 6 => harmony_bonus -= 5.0,       // half empty: mediocre
        _ => harmony_bonus -= 10.0,          // mostly empty: poor
    }

    // Capacity fraction coupling
    let frac = post_residual as f64 / cap;
    score += frac * frac * 30.0; // penalize large residual quadratically

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current fit is bad or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > 45.0;
        let many_open = open_bins_count as f64 > 4.0;
        if bad_fit && many_open {
            score -= 25.0 + 15.0 * (1.0 - progress);
        } else {
            score += 45.0;
        }
    }

    // Mild tie-break toward consolidating mean residual
    score -= (mean_residual - post_residual as f64).abs() * -0.05;

    score -= harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Moderate penalty for gaps that can only fit the smallest items
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect fit
    if post_residual == 0 {
        score -= 15.0;
    }

    // Dead-space penalty scaled by how "wasted" the gap is relative to typical item size
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.15 {
        score += waste_ratio * 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // Penalize if next item would leave another tiny gap
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 5.0;
    }

    // Open bins pressure: penalize placements that keep many bins open with scattered residuals
    score += open_bins_count as f64 * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only allow opening a new bin when existing residuals are mostly unusable
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when mean residual is small (dead space everywhere)
        score = 40.0 - mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in stream, prefer closing out existing bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins with below-average residual (tighter bins get priority)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact chain match is heavily rewarded.
        if gap == 0.0 {
            score -= 40.0;
        } else {
            // Reward proportional to how close the chain is; penalize
            // post residual that is too small to ever fit the next item.
            score -= 20.0 * (-gap / 12.0);
            if post_residual < next_item_size {
                // Dead space for the next item: penalize more the smaller it is.
                let dead = (next_item_size - post_residual) as f64;
                score += 0.35 * dead;
            }
        }
    } else {
        // Last item: minimize post residual aggressively.
        score *= 1.5;
    }

    // Compare post residual relative to mean residual across open bins:
    // leaving less than the mean residual indicates a tight, efficient fit.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.4 * mean_gap;

    // Last-chance bin bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin unless the current bins are all poor fits.
    if bin_residual == bin_capacity {
        // New bin bias: baseline penalty, reduced when open bins have low mean residual.
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score += 30.0 - 20.0 * pressure;
        // If next item is large, a fresh bin with room for it is attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight late-stream tightening: as the stream progresses, prefer
    // consolidating into existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.05 * item_size as f64;
    }

    // New-bin candidate handling: prefer reusing open bins early, allow fresh bins
    // late in the stream or when mean residual is already high (fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized by how many bins are already open,
        // but the penalty shrinks when existing residuals are fragmented.
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 + 0.6 * open_bins_count as f64 - 5.0 * frag - 3.0 * progress;
        // If no open bin fits at all, new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: favor leaving room for the next item.
    if next_item_size > 0 {
        let next_fits_after = (post_residual as i64 - next_item_size as i64) >= 0;
        if next_fits_after {
            score -= 5.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // residual becomes dead weight relative to lookahead
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Mild preference for bins below mean residual (balance spreading).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev;

    // Early stream: keep bins tight to preserve flexibility; late stream: pack greedily.
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    let mut score = post + 25.0 * poly;

    // Dead-space penalty: very small post_residual is wasted space; reward tight fits.
    if x < 0.1 {
        score -= 12.0 * (0.1 - x) * 10.0;
    }

    // Lookahead coupling: penalize if next item could use this residual better elsewhere.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = x - nx;
        if gap > 0.0 && gap < 0.15 {
            score += 8.0 * (0.15 - gap) / 0.15;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: mildly discourage early, encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress * (open_bins_count as f64 / 8.0).min(1.0);
    }

    // Smooth mean-residual coupling: prefer bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod small divisors
    // capture "nice" leftover sizes that pair well with future items.
    let pr = post_residual;
    let mod3 = (pr % 3) as f64;
    let mod5 = (pr % 5) as f64;
    let mod10 = (pr % 10) as f64;

    // Penalize awkward residues (dead space unlikely to be filled exactly).
    score += 0.6 * mod3 + 0.4 * mod5 + 0.8 * mod10;

    // Reward exact-fill classes: post_residual divisible by 10 or 25
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr == 0 {
        score -= 12.0; // perfect fit
    }

    // Integer-division threshold bands on post_residual
    let band = pr / 10; // 0..10 coarse band
    score += band as f64 * 0.5;

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: next item leaves a divisible residue
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 3.0; }
            if nr % 5 == 0 { score -= 1.5; }
            score += 0.3 * ((pr % next_item_size.max(1)) as f64);
        } else {
            // next item won't fit here; penalize large leftovers mildly
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when mean residual is small (bins nearly full)
        score = 20.0 + 40.0 * pressure - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items in fresh bins
        }
    } else if fitting_bins_count > 1 {
        // mild competition bonus for tighter bins
        score -= 0.02 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A gap is "dead" if it is too small to plausibly fit a future item (min size ~1,
    // but practically we treat very small gaps as wasted capacity).
    if post_residual > 0 {
        // Smooth penalty that grows sharply as post_residual shrinks.
        let pr = post_residual as f64;
        let dead = (bin_capacity as f64 - pr).max(0.0); // filler amount
        // Reward tight fits (small post_residual) nonlinearly.
        score += (1.0 - pr / bin_capacity as f64).powi(3) * 20.0;
        // Extra penalty for tiny dead gaps (1..=10 units) that likely can never be used.
        if post_residual <= 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 8.0;
        }
        let _ = dead;
    }

    // Perfect fit bonus: leave nothing behind.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste: mild penalty proportional to waste
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the gap: penalize dead space more
            score += post_residual as f64 * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (i.e., penalize the fresh-bin candidate via its large post_residual naturally,
    // but also add pressure term scaled by open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of better packing (fill bins with below-average residual first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Make it attractive only when current item is large relative to capacity
    // and no good fit exists (handled implicitly), but add a mild default penalty
    // so we prefer existing bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If item is huge, opening fresh is often better.
        if item_size > bin_capacity * 2 / 3 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: next item exactly fills this bin after placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near-perfect matches for the next item (small slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual too small for next item: penalize dead space relative to mean residual.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead.min(next_item_size as f64);
    }

    // Penalize leaving residual close to mean residual (creates many mediocre bins).
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good fitting options exist.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But a fresh bin is attractive if the item is large and no bin fits tightly.
        if next_item_size > 0 && post_residual == 0 {
            score -= 40.0; // exact fill of a brand-new bin
        }
    }

    // Progress-aware tightening: late in the stream, prefer tighter fits more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // creates stranded space relative to lookahead
        }
        // Perfect pair: current + next exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64) * 0.5;

    // Time-horizon modulation: early on, be more exploratory (favor new bins
    // slightly less penalized); late in stream, lock in tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * tightness;

    // Mean-residual coupling: if open bins are generally full, value this
    // bin's remaining space more; if residuals are large, prefer spreading.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    let mut score = pr * (1.0 + 0.8 * t * t);

    // Quadratic dead-space penalty: small residuals are useless, penalize smoothly.
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * t);

    // Cubic coupling: large post-residual is valuable early, less so late.
    score += 40.0 * norm_pr * norm_pr * norm_pr * (1.0 - t);

    // Lookahead synergy: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        if nx <= pr {
            score -= 25.0 * (1.0 - fit_gap / cap) * (1.0 + 0.5 * t);
        } else {
            score += 10.0 * (fit_gap / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + t);
    }

    // Mean-residual pressure: prefer bins deviating from mean to balance residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev * (1.0 - t);

    // New-bin candidate: penalize mildly, more when good fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - t) + (fitting_bins_count as f64) * 5.0;
    }

    // Small open-bin count preference: pack tightly when few bins are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 classes.
    let post_class = post_residual % 10;
    // Classes 1..9 (near-multiple residuals) are awkward dead space -> penalize.
    if post_residual > 0 {
        let awkward = match post_class {
            0 => -2.0,          // perfect multiple of 10: very usable
            1 | 9 => 6.0,       // nearly useless slivers
            2 | 8 => 3.0,
            3 | 7 => 1.5,
            _ => 0.0,           // 4,5,6: mid-range, decent
        };
        score += awkward;
    } else {
        score -= 5.0; // perfect fill reward
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Lookahead fit quality: how tightly does next item fill post_residual?
        let lookahead_tightness = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.15 * lookahead_tightness;
    } else if next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space unless class is good.
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Capacity fraction coupling: reward bins whose residual after placement
    // falls into a "harmonic" fraction of capacity (multiples of capacity/4).
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual is a hopeless sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 0 && post_residual < 10 {
            score += 12.0; // sliver: prefer new bin
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: neutral baseline, slightly below a bad fit.
    if bin_residual == bin_capacity {
        score = 25.0 + 0.05 * open_bins_count as f64
            - if next_item_size > 0 && next_item_size <= bin_capacity { 2.0 } else { 0.0 };
    }

    // Stream progression: early on, be pickier about dead space (more future items
    // to fill gaps); late, accept larger residuals since stream is ending.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;

    // Mean residual coupling: if open bins are already slack, avoid adding more slack.
    if mean_residual > (bin_capacity as f64) * 0.5 {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps
    if post_residual > 0 {
        // Dead space: residual too small to fit even the smallest plausible item
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        } else if post_residual <= 25 {
            score += 10.0;
        } else if post_residual <= 40 {
            score -= 5.0;
        } else {
            // Large residual is flexible, reward mildly
            score -= 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 80.0;
    }

    // Prefer exact fit with the lookahead item
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 40.0;
    }
    // Penalize if post_residual cannot fit the next item but is close to it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading; when few, opening new bins is cheap
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost grows with open bins count
        score += 15.0 + 8.0 * pressure;
    } else {
        // Reward reusing existing bins, more so when many are open
        score -= 4.0 * pressure;
    }

    // Early in stream: opening new bins is relatively cheap; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: if this bin is far below mean residual, it is a good filler target
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev;
    } else {
        score += 0.15 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover; penalize dead space scaled by waste
            score += 0.5 * post_residual as f64;
        }
    }

    // Reward using bins that are already tight relative to mean residual
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 30.0 * (mean_residual - resid_f) / bin_capacity as f64;
    } else {
        score += 10.0 * (resid_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits in open bins,
    // but allow opening when all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by fraction of bin consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Time horizon: later in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins -> penalize spreading residual.
    score += (open_bins_count as f64).ln() * (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (item much larger than mean residual).
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 - mean_residual).max(0.0);
        score = 50.0 + desperation - 10.0 * progress;
        if fitting_bins_count == 0 {
            score = 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += 60.0 * progress * norm_pr * norm_pr;

    // Reward tight fits, stronger late in the stream
    score -= 40.0 * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth sigmoid-like gate)
    let can_fit_next = if next_item_size > 0 { (pr as f64 - norm_next * cap) / cap } else { 0.0 };
    let gate = 1.0 / (1.0 + (-8.0 * can_fit_next).exp());
    score += 25.0 * (1.0 - gate) * norm_pr;

    // Last-chance bonus (smoothly weighted)
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * last_chance * (0.5 + progress);

    // Deviation from mean residual: prefer bins diverging from the average (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Slight preference for opening new bins early, reusing late (smooth interaction)
    score += 8.0 * (1.0 - progress) * norm_item * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals that are "harmonic" with common
    // item sizes (small multiples of capacity fractions) are reusable;
    // odd leftovers are dead space and get penalized.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Class 0: post_residual near zero -> excellent fill
    if pr <= tenth {
        score -= 30.0;
    } else if pr <= fifth {
        score -= 12.0;
    } else if pr <= quarter {
        // mid-range leftover: mildly penalize proportional to leftover
        score += (pr as f64) * 0.15;
    } else {
        // large leftover: heavily penalize wasted space (worse than new bin)
        score += (pr as f64) * 0.35;
    }

    // Harmonic match: does post_residual exactly accommodate the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 25.0; // perfect chaining
        } else if pr >= next_item_size {
            let ratio = pr as f64 / next_item_size as f64;
            // reward when next item is a harmonic fraction of leftover
            if (ratio - ratio.round()).abs() < 0.05 && ratio >= 2.0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // leftover too small for next item: dead space penalty scaled
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Integer-division threshold: leftover divisible by common item classes
    if pr > 0 && pr % 10 == 0 {
        score -= 5.0; // round-number residuals pack well with decimal items
    }
    if pr > 0 && pr % 25 == 0 {
        score -= 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when this bin would leave a big
    // awkward leftover or open bins are already numerous.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted when many bins are open
        // and the stream is early (more future items to amortize it).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let amort = 1.0 - 0.5 * progress;
        score = 45.0 * amort + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // next item also large: fresh bin keeps flexibility
        }
        if pr <= tenth {
            // near-perfect fit into existing bin beats new bin
            score += 40.0;
        }
    }

    // Tie-break: prefer tighter existing bins (small residual before placement)
    score += (bin_residual as f64) * 0.02;

    // Slight preference for consolidating: fewer open bins is better
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: if the fleet is loose on average, prefer
    // filling this bin rather than spreading
    if mean_residual > cap * 0.5 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward: next item still fits in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }

    // Penalize dead space that the next item cannot use, scaled by how "tight" the stream is.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Penalize post_residual far below mean residual (creating a useless tiny sliver).
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.1 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave a bad fit
    // or when many bins are already open and this is a large item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if bad_fit {
            score -= 8.0;
        } else {
            score += 30.0;
        }
        // Slightly discourage hoarding new bins late in the stream.
        score += 10.0 * progress;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual) — already in score.

    // Penalize unusable dead space: residuals too small for the minimum item (1..100 range)
    let min_item = 1.0f64.min(10.0); // use small threshold, conservative dead-space band
    let dead_zone = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - post_residual as f64).abs() < 1.0 {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (nx / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit here; slightly penalize leaving large residual that wastes capacity
            score += 3.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins when existing bins have slack; scale with open bin count
        let crowding = (mean_residual / cap).max(0.0);
        score += 15.0 + 10.0 * (1.0 - crowding) + 5.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild preference to fill bins with larger residuals when many bins open (consolidation)
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: early in stream, be more conservative about dead space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post-residual in [0,1]

    // Base: prefer small post-residual, but with smooth non-linear shaping
    let mut score = pr;

    // Polynomial coupling with stream progress:
    // early on tolerate leftover space (score damped), late in stream penalize waste more
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Smooth dead-space penalty: quadratic in normalized residual, amplified by progress
    let dead = x * x;
    score += 30.0 * dead * (0.5 + progress);

    // Reward near-perfect fits smoothly: gaussian-like term on x
    let fit_bonus = (-((x - 0.05) * (x - 0.05)) / 0.02).exp();
    score -= 25.0 * fit_bonus;

    // Lookahead coupling: if next item fits smoothly into post-residual, reward
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = 1.0 - ((pr - n) / cap).abs();
            score -= 12.0 * slack * (1.0 - progress * 0.5);
        } else {
            // next item won't fit here: mildly penalize leaving a gap it almost fits
            let gap = (n - pr) / cap;
            score += 8.0 * (1.0 - gap * gap);
        }
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x * x);
    }

    // Mean-residual coupling: placing into a bin far below mean residual is smoother
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize unless current bin would leave tiny residual
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod 10
    let class = (post_residual % 10) as f64;

    // Penalize residuals that are small-but-nonzero (unusable dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward residuals in "harmonic" classes likely to absorb future items
    // (multiples of 10, i.e. class 0, are the most reusable)
    score -= class * 0.8;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic pairing: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    }
    // If next item fits in post_residual, mild bonus scaled by leftover after next
    if next_item_size > 0 && next_item_size < post_residual {
        let next_post = post_residual - next_item_size;
        score -= 30.0 - (next_post as f64) * 0.3;
        // harmonic match of next_post class
        score -= ((next_post % 10) as f64) * 0.5;
    }
    // If next item does NOT fit post_residual, penalize wasted pairing opportunity
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Integer-division threshold on post_residual: quartile classes
    let quart = post_residual / (bin_capacity / 4).max(1);
    score -= quart as f64 * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // opening fresh is attractive for big items or late in stream with few bins
        score -= 25.0 * frac;
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // late stream: consolidation preferred over proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's tight — favor
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Perfect fit gets extra reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can still fit: mild reward.
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space for the next item: penalize proportionally.
        score += 6.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if mean residual across open bins is too small to be useful, allow new bin.
        if mean_residual < item_size as f64 {
            score -= 55.0;
        }
    }

    // Mild progression term: later in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/low post_residual fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small to ever be useful (min item = 1).
        if post_residual < 10 {
            score += 40.0;
        } else {
            // Reward residual sizes that are "useful" (large enough for typical items).
            score -= (post_residual as f64).ln() * 8.0;
        }
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0); // reward, decaying with slack
        } else {
            // Next item won't fit here; penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual above mean are "loose";
    // prefer filling them when the fit is tight.
    let res_f = bin_residual as f64;
    let diff = res_f - mean_residual;
    score += diff * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    // Late in the stream, consolidate more aggressively (fewer bins matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit term: reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post-residual, this bin
    // remains valuable, so reward it; otherwise penalize wasted space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
            // Extra penalty for large dead space that nothing likely fits.
            if post_residual < 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Early in the stream: be more willing to pack into existing bins
    // (consolidation); late: allow spreading to reduce fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;
    score += progress * 3.0;

    // Global state: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But if existing bins are nearly full (low mean residual),
        // opening a new bin is reasonable.
        score -= mean_residual * 0.3;
        // If no bin currently fits the item, new bin is a good idea.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Existing bin: reward when mean residual is high (bins are roomy)
        // and open bins are few.
        score -= mean_residual * 0.1;
        score += open_bins_count as f64 * 0.5;
    }

    // Penalize leaving residuals that are awkward (just below common sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual scaled by a smooth progress-dependent factor.
    // Later in the stream, residual dead space becomes more costly.
    let pr_norm = pr / cap;
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += 6.0 * pr_norm * pr_norm * progress_weight * cap * 0.1;

    // Reward tight fits: subtract a smooth function of item fraction of bin.
    let fill = it / cap;
    score -= 10.0 * fill * (1.0 - fill) * (1.0 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual can't fit next item but another bin could,
    // reward if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Penalize when this bin's residual deviates from mean residual (fragmentation).
    let dev = (pr - mean_residual).abs();
    score += 2.0 * dev / cap;

    // Mild penalty for having many open bins already (encourage consolidation).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Smooth sigmoid-like penalty for very small post_residuals that are still >0
    // (dead space) but reward near-zero residual.
    if pr > 0.0 {
        let tiny = (pr / cap).min(1.0);
        score += 4.0 * tiny * (1.0 - tiny) * 4.0; // parabola peaking mid-range
    } else {
        score -= 8.0; // perfect fit bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space buckets via integer division
    let class = post_residual / 10;
    score += match class {
        0 => -12.0,                     // near-perfect fit
        1 => -4.0,                      // small gap, likely reusable
        2 => 3.0,                       // 20-29 gap: awkward
        3 => 8.0,                       // 30-39: dead zone for mid items
        4 => 2.0,                       // 40-49: usable by medium items
        5 => -2.0,                      // ~half bin: flexible
        _ => 1.0,                       // large residual: bin stays generic
    };

    // Reward when next item exactly fits post_residual (harmonic match)
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 14.0;
        } else if gap < 15.0 {
            score -= 6.0;
        }
    }
    // Penalize if next item cannot use the leftover
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: make it attractive only when current bins are tight/crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        score = 40.0 + crowd * 2.0 - progress * 5.0
            - (mean_residual / bin_capacity as f64) * 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin pairs well with upcoming larger item
        }
    }

    // Mild preference for fuller bins as stream progresses
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future item
    // (min size 1..100 unknown; assume 10) are "dead" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score near mean residual,
    // so it only wins when all open bins have poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * mean_residual + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, keep consolidating: make new bins less attractive.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        return score;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones (tighter fits).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.2 * ((bin_residual - item_size) as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual as u64 >= next_item_size as u64 {
            // next item can also fit here later: small gap is good
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize proportional to gap
            score += 0.5 * gap;
        }
    }

    // Relative to mean residual: bins with larger-than-mean residual are better hosts
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer keeping many open bins filled; discourage opening new bins late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 40.0 + 60.0 * progress;
    }

    // Penalize leaving small unusable fragments (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && next_item_size > post_residual && next_item_size > 0 {
        score += 12.0;
    }
    // Reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it available but not preferred unless
    // the best existing fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Fragmentation pressure: when mean residual is high, discourage wasting
    // large residuals on small items.
    if mean_residual > item_size as f64 * 1.5 {
        score += 6.0;
    }

    // Late in stream, consolidate: favor filling existing bins over opening new.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Prefer bins with larger residual when many bins are open (balance load).
    score -= 0.05 * bin_residual as f64 / (open_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_prob = post / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically
    let mut score = post * post / cap;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, dead space becomes more costly (super-linear growth)
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth term proportional to item/capacity
    // weighted by how full the bin becomes (1 - fit_prob)
    let tightness = (item_size as f64 / cap) * (1.0 - fit_prob);
    score -= 30.0 * tightness * (1.0 + progress);

    // Penalize post residual that cannot fit the next item (smooth soft barrier)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - post;
        if gap > 0.0 {
            let severity = gap / cap;
            score += 25.0 * severity * severity * (1.0 + 0.5 * progress);
        } else {
            // small reward when next item fits exactly-ish
            score -= 8.0 * (1.0 - (post - ns) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // scaled by deviation of this bin's residual from the mean
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate (empty bin): make it attractive only when residual of
    // existing bins is small relative to item needs; otherwise discourage.
    if bin_residual == bin_capacity {
        let avg_usable = mean_residual / cap;
        score += 20.0 * (1.0 - avg_usable) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 40.0; // near-perfect dead space
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 50 {
        score += 8.0;
    } else {
        score += 18.0;
    }

    // Modulo arithmetic classes: residual divisible by common item sizes is reusable.
    if pr > 0 && pr < 100 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
        if reusable { score -= 12.0; }
    }

    // Lookahead coupling: if next item fits post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0 + 0.2 * (next_item_size as f64);
        } else {
            // wasted pair potential: penalize large leftovers next item can't use
            score += 0.15 * (pr as f64);
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bin is fine early or when item is large relative to capacity.
        let large_item_bonus = 0.5 * (item_size as f64 / cap);
        score = 55.0 - 40.0 * progress - 30.0 * large_item_bonus;
        if fitting_bins_count == 0 { score -= 50.0; }
        // discourage new bins when a fitting bin has small residual already
        if fitting_bins_count > 0 && mean_residual < 25.0 { score += 25.0; }
    } else {
        // prefer bins with residual close to item (snug fit)
        let snug = 1.0 - ((bin_residual - item_size) as f64).abs() / cap;
        score -= 10.0 * snug;
        // slight penalty for very full bins when mean residual is high (spread load)
        if (bin_residual as f64) < mean_residual - 40.0 { score += 6.0; }
    }

    // mild open-bins pressure: fewer open bins is cheaper to manage
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        // gap only usable for very small future items: partially dead
        score += 18.0;
    }

    // Reward tight fits (small waste relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        // next item would leave a dead sliver: mild penalty
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by open-bin pressure.
        score += 30.0 + 3.0 * (open_bins_count as f64).sqrt();
        // Early in the stream, opening bins is fine (builds diversity of residuals).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If the item fits poorly everywhere else (few fitting bins), new bin is attractive.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If next item is large and this item is small, prefer existing bins to keep big gaps.
        if next_item_size > 60 && item_size < 30 {
            score += 25.0;
        }
    } else {
        // Pressure from too many open bins: favor consolidating into existing bins.
        score += 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residual close to the item (best-fit flavor) via mean residual anchoring.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

