        score -= 18.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit in this bin's post-residual, penalize slightly
        if next_item_size > post_residual {
            score += 6.0;
        }
    } else {
        // Last item: pure tightest fit
        score -= 10.0;
    }

    // Penalize creating unusable dead space (residual too small for any plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Relative to mean residual: bins with larger residuals than average are more flexible targets
    score -= 0.35 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: prefer it only when it's early in the stream or current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score = 55.0 - 20.0 * (1.0 - progress);
        // Don't open new bin if this item leaves a perfect slot for the next one
        if next_item_size > 0 && post_residual == next_item_size {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < item_size {
        // residual smaller than current item: somewhat wasted
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement blocks the next item from this bin
            score += 5.0;
        }
        // perfect pairing: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / bin_capacity as f64;
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // early in stream, opening bins is cheap; later prefer consolidation
        score += 12.0 * horizon + 10.0 * (1.0 - pressure);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer fuller bins (smaller residual) among open bins.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: wasted space after placement, with mild non-linear penalty growth
    let mut score = pr + 12.0 * (pr / cap).powi(3) * cap;

    // Stream-progress coupling: later in the stream, tolerate larger residuals less
    score *= 1.0 + 0.6 * progress * (pr / cap);

    // Reward tight fits (small post_residual) with a smooth non-linear bonus
    score -= 15.0 * (1.0 - pr / cap).powi(2) * (item / cap);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize leaving a residual that barely misses next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 10.0 * gap * (1.0 - gap);
        // reward if next item fits exactly in the post residual
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Penalize spreading across too many open bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: neutral-ish baseline, penalized early, relaxed late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into modulo classes of 10 (capacity fractions).
    let class = post_residual / 10; // 0..=10 harmonic class
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-exact fits: dead space below 10 is very valuable to keep.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 40.0; // tiny dead space, essentially closed
    } else if class == 1 {
        score -= 15.0; // residual 10..19: usable by small items (10..80 range includes 10s)
    } else if class == 2 {
        score -= 5.0;
    } else if class == 3 {
        score += 5.0; // awkward zone
    } else if class == 4 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 55.0;
        } else if slack < 10 {
            score -= 30.0;
        } else {
            score -= 12.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use this bin's leftover: penalize leaving mid-size dead space
        score += 0.15 * post_residual as f64 * frac;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is fine early or when nothing fits well.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline with slight penalty so decent fits in open bins win.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open
        }
        // Late stream: prefer opening fresh bins over fragmenting? mild discount
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below mean (consolidating tighter bins).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight penalty for many open bins already (encourage filling existing ones).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (sizes >= 1, but realistically >= 10 in classic streams)
    // are pure waste. Penalize tiny gaps heavily, non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Gaps that can only fit very small items are semi-dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits: the closer post_residual is to 0 (but usable), the better.
    if post_residual > 0 {
        score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // rather than opening new ones.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: brand-new empty bin gets a baseline penalty
    // that scales with how much space would be left elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 5.0 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    }
    // If next item is slightly too big for the gap, mildly penalize this bin.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Progress: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is already close to the mean (balance).
    score += 0.2 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

