    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins whose post_residual stays near/below mean.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.1;
    }

    // Slight preference to fill existing bins rather than open new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 + 10.0 * progress;
    } else {
        // New-bin candidate: penalize slightly so only chosen when open bins are bad fits.
        score += 3.0;
    }

