}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that is too small for typical future items:
    // dead space in (0, 10) is nearly unusable if items are >=10, but sizes 1..100
    // are unknown, so weight by how "awkward" the hole is relative to mean residual.
    if post_residual > 0 {
        let hole = post_residual as f64;
        let awkward = (hole / (mean_residual.max(1.0))) .ln().abs();
        score += 3.0 * awkward * (hole / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Penalize new bins moderately, scaled by how
    // many open bins exist and stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // but if item is large, new bin gives perfect fit potential
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 6.0;
        }
    }

    // Mild preference to fill bins that are already below average residual
    // (balance consolidation): bins with residual below mean get a bonus.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 2.0 * diff / bin_capacity as f64;
        } else {
            score += 1.0 * (-diff) / bin_capacity as f64;
        }
    }

    // Slight time-horizon modulation: early in the stream, be more conservative
    // (favor tight fits more); later, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = norm_pr * norm_pr * cap;

    // Non-linear coupling: residual squared interacts with stream progress
    // Early on, tolerate loose fits; late, penalize wasted space more strongly
    score += 25.0 * norm_pr * norm_pr * (progress * progress);

    // Reward tight fits: cubic term in (1 - norm_pr)
    score -= 8.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: strongly favor this bin if it is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = (pr - ni).abs() / cap;
        score += 6.0 * compat * compat;
        if pr >= ni {
            score -= 5.0 * (pr / cap) * (ni / cap);
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Mild preference to fill existing bins when many are open
    score += 2.0 * (open_bins_count as f64).sqrt() * norm_pr;

    // New-bin candidate: penalize slightly so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10.
    // Residuals that are "useful" (multiples of 10, or >= 50) are worth keeping.
    let residue = post_residual % 10;
    score -= 8.0 * (1.0 - residue as f64 / 5.0).abs().min(1.0); // reward residue 0, penalize residue 5
    score -= 3.0 * (residue as f64 / 10.0); // slight tilt within class

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 9 {
        // Dead space: too small for any item (min size 1..100 unknown, but tiny residual is waste)
        score += 25.0;
    }

    // Fractional capacity thresholds on post_residual.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 12.0; // half-full-or-more residual left: bin stays flexible
    } else if frac <= 0.1 {
        score += 15.0; // leaving a sliver
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a good fit, better than a bad one.
        score = 50.0 + mean_residual * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can absorb the next item too
        }
        return score;
    }

    // Lookahead coupling: if post_residual can still hold the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            // Harmonic class match: post_residual and next_item_size in same decade class
            if post_residual / 10 == next_item_size / 10 {
                score -= 10.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Prefer packing into bins whose residual is already below the mean
    // (consolidating near-full bins), scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) < mean_residual {
        score -= 6.0 * (0.5 + progress);
    } else {
        score += 4.0 * (0.5 + progress);
    }

    // Mild preference to spread across bins when many are open and residual large.
    if open_bins_count > 4 && frac >= 0.6 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically gaps < ~15 are hard to fill) are penalized super-linearly.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (15.0 - post_residual as f64) / 15.0;
    }
    // Moderate gaps (15..35) get a mild penalty to prefer tight fits.
    if post_residual >= 15 && post_residual < 35 {
        score += 0.35 * post_residual as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 40.0).max(0.0);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement kills space the next item could have used elsewhere.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 4.0 * open_pressure;
    } else {
        // New-bin candidate: penalize when open bins are plentiful or mean
        // residual already large (fragmentation), reward when nothing fits well.
        score += 18.0 + 6.0 * open_pressure + 0.15 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Early in the stream, opening bins is cheaper; late, consolidation matters.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Mild preference for filling fuller bins.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits into post_residual -> reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit the leftover: penalize dead space that blocks lookahead.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    // Penalize very large leftovers (wasted capacity) nonlinearly.
    let post_frac = post_residual as f64 / bin_capacity as f64;
    score += post_frac * post_frac * 40.0;

    // Reward using bins that are already relatively full (small residual before placement).
    let pre_frac = bin_residual as f64 / bin_capacity as f64;
    score -= pre_frac * 15.0;

    // Last-chance bin: strongly favor filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: prefer placing into below-average-residual bins
    // (i.e. fuller bins), keeping large residual bins available for bigger future items.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: only prefer a fresh bin when all open bins are too
    // fragmented (high mean residual spread) or this is the only option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is forced, make it attractive.
            score -= 500.0;
        } else if fitting_bins_count == 1 {
            // One fitting bin exists; opening new bin is usually worse unless
            // the lookahead won't fit that bin's leftover anyway.
            if next_item_size > 0 && post_residual_of_fitting_unknown_proxy(mean_residual) {
                score -= 10.0;
            }
        }
        // Late in stream, prefer closing out with new bins less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

// Helper inlined logic proxy: cannot add new signature vars, so fold into a bool.
#[inline(always)]
fn post_residual_of_fitting_unknown_proxy(mean_residual: f64) -> bool {
    // If mean residual across open bins is small, open bins are nearly full and
    // unlikely to host the next item; a fresh bin then competes better.
    mean_residual < 25.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: penalize large post-residual, especially dead space below smallest plausible item.
    let dead_zone = 30.0;
    if (post_residual as f64) < dead_zone {
        score += 25.0 * (dead_zone - post_residual as f64) / dead_zone;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty scaled by wasted residual
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just dump it anywhere it fits.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a relatively better fit
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = (open_bins_count as f64).ln() + 1.0;
    score -= crowding * 3.0 * (mean_residual / bin_capacity as f64);
    score -= 10.0 * progress;

    // New-bin candidate handling: empty bin gets a mild default penalty so it's
    // chosen only when open bins would waste more space.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth base: quadratic penalty on post_residual (dead space grows quadratically)
    let mut score = pr + 0.9 * pr * pr / cap;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, large residuals are more costly (less chance to fill them)
    let late = progress * progress;
    score += 14.0 * late * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits smoothly: subtract more as post_residual shrinks
    let tightness = 1.0 - pr / cap;
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead coupling: if next item fits smoothly in post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / pr.max(1.0);
            score -= 4.0 * fill * fill;
        } else {
            // next item won't fit; penalize residuals that strand the next item
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many bins; smooth in open_bins_count
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: prefer bins below mean residual (fill emptier bins less)
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: empty bin gets a smooth opening cost that decays with progress
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction buckets
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class

    // Reward tight fits strongly: post_residual small => low score
    score -= (1.0 - post_residual as f64 / cap) * 0.0; // placeholder-free structure below
    score += match post_class {
        0 => -30.0,                       // near-perfect fit
        1 => -18.0,
        2 => -8.0,
        3 => 0.0,
        4 => 6.0,                         // half-empty: mediocre
        5 => 10.0,
        6 => 14.0,
        7 => 18.0,
        _ => 22.0,                        // bin left almost full of dead space
    };

    // Modulo-10 harmonic residue: dead space divisible by common item sizes is reusable
    let dead = post_residual;
    if dead > 0 {
        if dead % 10 == 0 { score -= 6.0; }
        else if dead % 5 == 0 { score -= 3.0; }
        if dead >= 10 && dead <= 20 { score -= 4.0; } // usable slot for small items
        if dead < 10 { score += 8.0; }                // unusable sliver
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64) * 0.3;
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize when open bins fit well
    if bin_residual == bin_capacity {
        score = cap * 0.55 + mean_residual * 0.2;
        if fitting_bins_count >= 1 {
            score += 15.0 + 5.0 * (fitting_bins_count as f64).min(4.0);
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming: fresh bin attractive
        }
    }

    // Progress coupling: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 10.0;

    // Prefer spreading across many open bins when mean residual is high
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but treat <10 as hard dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Small awkward gaps that most items can't use.
    if post_residual >= 10 && post_residual < 30 {
        score += 12.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Lookahead: bonus if the next item fits into the post residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // Penalize if next item would leave this residual dead anyway.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // New-bin candidate: penalize relative to mean residual of open bins;
    // only attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.5;
    } else {
        // Favor bins whose residual deviates favorably from the mean (tighter bins first).
        score -= 3.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        // Non-linear penalty for unusable dead space.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64);
        // Penalize residuals too small for any plausible item (min size 1, but
        // small leftovers are wasteful relative to capacity).
        if pr < 10 {
            score += 50.0;
        }
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post-residual, this placement creates a perfect two-item chain.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits here afterwards: mildly good.
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit after this placement; penalize proportionally
        // to how much it misses, encouraging leaving room for it elsewhere.
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Compare against mean residual: prefer bins that are already relatively
    // full (below-mean residual) to consolidate waste.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // But if current item nearly fills a fresh bin and next item is small,
        // a new bin can be attractive.
        if item_size >= bin_capacity * 9 / 10 {
            score -= 90.0;
        }
        // Few open bins relative to stream length: consolidation phase, keep bins open.
        if open_bins_count > 0 && (post_residual as f64) > mean_residual {
            score += 20.0;
        }
    }

    // Slight stream-progression modulation: late in the stream, be more
    // eager to close bins tightly and avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible item (>=1) can use; small residuals are gold
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste * waste;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // penalize leaving residual that only a tiny item could use
            score += 6.0 * (1.0 - (next_item_size as f64 - post_residual as f64).min(50.0) / 50.0);
        }
    }

    // Compare against mean residual: bins far below mean residual are more precious
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // Crowding: many open bins -> favor consolidation into existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate handling: empty bin gets a baseline penalty so it's chosen
    // only when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - item_size as f64; // = post_residual of fresh bin
        score += 12.0; // default penalty to prefer reusing bins
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else {
            // if existing fits are all terrible (huge post residual), new bin is fine
            if post_residual as f64 > 0.0 && (bin_residual as f64 - item_size as f64) < 10.0 {
                score -= 20.0;
            }
        }
    }

    // Mild time-horizon term: early in stream, be conservative about fragmentation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover, with non-linear (quadratic) growth of dead-space cost.
    let mut score = pr + 60.0 * norm_pr * norm_pr * (1.0 + 2.0 * progress);

    // Smooth coupling: residual cost modulated by stream progress (later => tighter packing).
    score *= 1.0 + 0.35 * progress * norm_pr;

    // Perfect fit reward (smooth, non-piecewise).
    score -= 25.0 * (-pr as f64).exp();

    // Lookahead: reward leaving space exactly usable by next item (smooth kernel).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 18.0 * (-diff / 12.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild reward for choosing bins below mean residual (balance across bins).
    score -= 0.15 * (mean_residual - pr);

    // Penalize opening a new bin when plenty of bins already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * fitting_bins_count as f64 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes relative to capacity fractions
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;

    // Reward tight fits: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Modulo-class penalty: residuals that are "harmonically useful" for common item
    // sizes (multiples/submultiples of capacity) are more reusable.
    let mod_class = post_residual % 10;
    let bonus = match mod_class {
        0 => 8.0,          // residual aligned to decade grid -> reusable
        5 => 4.0,
        _ => {
            // penalize residuals in awkward classes (1..4, 6..9) proportionally
            let m = mod_class.min(10 - mod_class);
            (m as f64) * 0.8
        }
    };
    score -= bonus;

    // Integer-division thresholds: residual that can host next_item_size is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
        // extra reward if residual can host next item plus a small harmonic remainder
        let after_next = post_residual - next_item_size;
        if after_next % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // residual can't host the lookahead item: penalize dead space
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits via fraction coupling
        score += frac * (fitting_bins_count as f64) * 2.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // base cost of opening a bin; reduced when open residuals are large/wasteful
        score = 60.0 - 25.0 * pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't open when a last-chance bin exists
        }
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // Penalize bins far below mean residual (fragmenting)
    score += 0.15 * (mean_residual - pr).abs();

    // Mild penalty for too many open bins
    score += (open_bins_count as f64) * 0.3 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize large waste relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: discourage opening new bins when open bins fit
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Slight late-stream pressure to close out bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward perfect match where next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover dead space after hypothetical next placement
            score += gap * 0.6;
        } else {
            // next item won't fit here either way; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Tight fit reward: small post_residual is good, but avoid tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead-space penalty for slivers
    }

    // Compare against mean residual: prefer bins with residual close to item (best fit)
    let diff = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += diff * 0.3;

    // Last chance: strongly favor using the only bin that fits before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if nothing fits well (large item relative to mean residual), new bin is fine
        if item_size as f64 > mean_residual * 0.9 {
            score -= 45.0;
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for fuller bins when many bins are open
    score -= (bin_capacity - bin_residual) as f64 * 0.1 / (1.0 + open_bins_count as f64 * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly reward leaving exactly zero residual
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: residual that could still fit a mid/small item
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Penalize dead space: residual too small for the smallest possible item (1..100 interface)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward leaving residual that exactly fits the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits elsewhere are bad
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win first
        score += 30.0;
        // But relax the penalty late in the stream or when many bins are open and fragmented
        score -= t * 15.0;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0; // existing bins are fragmented; new bin is attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits; must open new bin
        }
    }

    // Mild preference to fill bins that are already low-residual (consolidation)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Global state coupling: many open bins -> prefer filling existing ones
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Mean-residual coupling: penalize placing into bins far from mean residual
    // (keeps residuals homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early stream: be exploratory, slight preference for tight fits over consolidation
    if t < 0.3 {
        score -= (item_size as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear coupling: reward small post_residual quadratically, more as stream progresses.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * cap * (0.5 + 1.5 * progress);

    // Tight-fit bonus: item filling most of the residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * 20.0 * (0.5 + progress);

    // Penalize dead space that next item could not use.
    if next_item_size > 0 {
        let gap = post - norm_next * cap;
        if gap > 0.0 {
            let gap_norm = gap / cap;
            score += gap_norm * gap_norm * cap * 0.8;
        } else {
            score -= 5.0; // next item fits perfectly in the leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Slight penalty for spreading across many open bins when residuals are large.
    let mean_norm = mean_residual / cap;
    score += open_bins_count as f64 * mean_norm * mean_norm * 0.5;

    // Penalize near-empty placements into a fresh bin unless item is large.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - norm_item) * (1.0 - norm_item);
        score -= 10.0 * progress; // later in stream, reusing bins matters more
    }

    // Cubic smoothing term on post residual to break ties smoothly.
    score += norm_post * norm_post * norm_post * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets reward small, "usable" remainders.
    let pr = post_residual;
    let harmonic = pr % 10;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if harmonic == 0 {
        score -= 12.0; // round residual, easy to reuse
    } else if harmonic <= 3 {
        score += 6.0;  // thin sliver -> dead space
    } else if harmonic >= 7 {
        score -= 4.0;  // chunky remainder, likely reusable
    }

    // Integer-division thresholds: residual in [next_item_size, next_item_size+15) is ideal.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack <= 15 {
                score -= 18.0; // next item fits snugly
            } else {
                score -= (slack as f64).min(30.0) * 0.2;
            }
        } else {
            score += 8.0; // next item cannot follow here
        }
    }

    // Fractional capacity classes of the fill level.
    let fill = (bin_capacity - pr) as f64 / bin_capacity as f64;
    let quartile = (fill * 4.0).floor(); // 0..3
    score -= quartile * 3.0; // prefer fuller bins

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are nearly exhausted of useful space.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 20.0 + pressure * 8.0;
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (pr as f64) * 0.15 * progress;

    // Small coupling: reward filling a bin beyond 3/4 with exact modular harmony.
    if pr > 0 && (bin_capacity - pr) % (item_size.max(1)) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below typical min item size ~10)
    // are useless; penalize them heavily.
    if post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 3.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.2;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.5;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving awkward gap.
        score += (post_residual as f64) * 0.3;
    }

    // Prefer bins already below mean residual (consolidate fullness).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Early in stream, be slightly more willing to open new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match strongly rewarded.
        if gap == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to tightness of match.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual relative to gap.
            score += gap * 0.35;
        }
    }

    // Penalize leaving large unusable dead space (below min item size 1..100 context).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 {
        score -= 20.0;
    } else if fill_ratio < 0.4 && bin_residual < bin_capacity {
        score += 10.0 * (0.4 - fill_ratio);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer bins with residuals below mean (consolidate large residuals elsewhere).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: tighten packing, avoid opening bins unnecessarily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; slight early discount.
        score += 30.0 + 40.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    // Slight preference for bins among many open bins to reduce bin count.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer filling bins nearly full: reward small post_residual non-linearly.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward for a tight two-item chain.
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for the next item: penalize proportionally.
        score += 4.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // no open bin fits well or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 18.0 + 10.0 * open_pressure - 15.0 * (1.0 - progress);
        // If the item fits snugly into a fresh bin, soften the penalty.
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // Global residual balance: prefer bins whose residual deviates from mean
    // in a way that consolidates space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, consolidate aggressively into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual >= item_size {
        score -= 5.0 * progress;
    }

    // Slight preference for bins with larger residual when many bins are open.
    score -= 0.02 * (bin_residual as f64) * (open_bins_count as f64).min(10.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: quadratic penalty on post residual (waste grows super-linearly).
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, tight fits matter more.
    score *= 1.0 + 0.5 * progress * (pr / cap);

    // Lookahead: reward residuals that exactly accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (-slack / 20.0).exp();
    }
    // Penalize residuals that leave the next item just barely unable to fit.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 6.0 * (-gap / 15.0).exp();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Deviation from mean residual: prefer bins whose residual is small
    // relative to the fleet average (concentrate waste in few bins).
    score += 0.3 * (pr - mean_residual);

    // Many open bins: mild pressure to fill existing ones rather than spread.
    score += 0.1 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: only attractive if no bin fits well.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 1 { 0.0 } else { 15.0 };
        score = cap + fit_pressure + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on a "usable"
    // class (divisible by common small sizes) are rewarded.
    let post = post_residual as i64;
    let mut harmony = 0.0f64;
    if post > 0 {
        for k in [1u32, 2, 4, 5, 10, 20, 25, 50].iter() {
            if post % *k as i64 == 0 {
                harmony += 1.0;
            }
        }
        harmony /= 8.0;
    }
    score -= 6.0 * harmony;

    // Penalize dead space: residuals too small for any plausible item (<10)
    let small = (10u32).saturating_sub(post_residual) as f64;
    score += 3.0 * small;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - exact / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize wasting residual
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize early when many bins open already
        score = bin_capacity as f64 * 0.5 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size as f64 > bin_capacity as f64 * 0.5 {
            score -= 4.0; // big item into fresh bin is fine
        }
    }

    // Tight fit reward: filling a bin almost completely
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill * fill;

    // Mild progression coupling: prefer compacting later in stream
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * prog * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything useful
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize mid-range unusable gaps more softly
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead synergy: if the next item fits the post-residual exactly-ish,
    // reward keeping this bin tight for the follower.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot host the next item: mild penalty scaled by gap size
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, allow spreading to keep flexible residuals.
    let pressure = open_bins_count as f64 * 0.8;
    score -= pressure * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when it offers
    // a much better long-term residual profile.
    if bin_residual == bin_capacity {
        // baseline cost of opening a bin
        score += 30.0;
        // but if all open bins would leave terrible gaps, opening is fine
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 1.1 {
            score -= 20.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    } else {
        // prefer bins whose residual is close to the item (tight fit)
        score -= (bin_residual - item_size) as f64 * 0.1;
    }

    // Align with mean residual: bins below mean residual are the "fuller" ones,
    // favor them to consolidate waste.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is already favored by the base term,
    // but add an extra bonus (subtraction) that grows as post_residual approaches 0.
    let perfect_fit_bonus = 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);
    score -= perfect_fit_bonus;

    // Aggressive 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement is ideal — reward it strongly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // chain fit: next item perfectly fills leftover
        } else if diff <= 10 {
            score -= 25.0 * (1.0 - diff as f64 / 10.0);
        } else {
            // Penalize leftovers the next item cannot use well (dead space risk)
            score += 8.0 * (diff as f64 / bin_capacity as f64);
        }
        // If post_residual is too small for the next item, it becomes dead space
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Compare against mean residual: bins with residual above mean are better targets
    // for large items (keep tight bins for small items).
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= 0.15 * residual_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes capacity when a
    // reasonable fit exists. Penalize the empty-bin candidate unless the item
    // fits poorly everywhere (large item, tight open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 35.0;
        // Large items early in the stream: a fresh bin is fine (it will be filled later)
        if fill_ratio > 0.6 {
            new_bin_penalty -= 20.0 * fill_ratio * (1.0 - 0.5 * progress);
        }
        // If no other bin fits at all, opening a new bin is unavoidable — soften penalty
        if fitting_bins_count == 0 {
            new_bin_penalty -= 40.0;
        }
        // Late in the stream, prefer closing out open bins rather than opening new ones
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Mild penalty for very large post_residuals (wasteful placements)
    if post_residual > bin_capacity / 2 {
        score += 0.1 * (post_residual as f64 - bin_capacity as f64 / 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic coupling of post_residual with progress
    let pr = post_residual as f64;
    score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 20.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.5 + 2.0 * progress);
        } else {
            // reward residuals that snugly fit next item
            score -= (1.0 - (pr - nx) / bin_capacity as f64) * 6.0;
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so we prefer reuse unless fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (denser bins)
    score += (mean_residual - pr) * 0.3;

    // Smooth non-linear waste penalty
    let norm = pr / bin_capacity as f64;
    score += norm * norm * 15.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the resulting residual (capacity fractions) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Perfect / near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + (5 - post_residual) as f64 * 20.0;
    }

    // Harmonic class thresholds on post_residual:
    // residuals in (0, 1/4]C are "dead-ish"; (1/4, 1/2]C medium; > 1/2C flexible.
    if frac <= 0.25 && post_residual > 0 {
        score += 25.0 * (0.25 - frac); // penalize tiny leftovers beyond base residual
    } else if frac > 0.5 {
        score -= 15.0; // reward keeping bins flexible
    }

    // Modulo / integer-division classes: residuals divisible by common item
    // sizes (harmonic classes) are more reusable.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 {
            score -= 20.0;
        } else if pr_u % 5 == 0 {
            score -= 10.0;
        }
        // Penalize residuals in awkward classes (prime-ish leftovers like 1,2,3,7 mod 10)
        let m = pr_u % 10;
        if m == 1 || m == 2 || m == 3 || m == 7 {
            score += 12.0;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how well the next item fills the leftover.
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 40.0 * fill;
            if next_item_size == post_residual {
                score -= 60.0; // exact two-item closure
            }
        } else {
            // Leftover can't host the next item: penalize, scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += (10.0 + miss).min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or this bin would leave a bad residual anyway.
    if bin_residual == bin_capacity {
        // Base new-bin cost: discourage opening bins while fitting bins exist.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open
        } else if fitting_bins_count == 1 {
            score -= 40.0; // contested: new bin is a plausible alternative
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If mean residual across open bins is small, open bins are nearly full:
        // a fresh bin is more attractive.
        score -= (mean_residual / cap).clamp(0.0, 1.0) * 30.0;
    }

    // Congestion shaping: with many open bins, prefer tightening existing ones.
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count.min(20) as f64) * (1.0 - frac);
    }

    // Early stream: keep bins roomy (avoid fragmentation early on).
    if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
        score += 0.3 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (1..=12) are heavily penalized since few future items (>=10) can use them.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual >= 10 && post_residual <= 12 {
        score += 15.0; // marginal gap: only smallest items fit
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when it enables a tight fit for
    // the lookahead item (residual after both = 0 or tiny) or when no
    // open bin fits well. Otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let lookahead_waste = if next_item_size > 0 && next_item_size <= post_residual {
            post_residual - next_item_size
        } else {
            post_residual
        };
        if lookahead_waste == 0 {
            score -= 35.0;
        } else if lookahead_waste < 10 {
            score -= 5.0;
        } else {
            score += 20.0 + pressure * 5.0;
        }
    }

    // Coupling with mean residual: prefer bins whose post_residual lands
    // below the current mean (tightening the fleet's average slack).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item exactly fills this bin's post_residual,
    // strongly favor it.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step match)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Good reward if the next item fits into the post residual (chain continuation)
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * (post_residual as f64 - next_item_size as f64).abs();
    }
    // Penalize dead space the next item cannot use
    else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Prefer tight fits overall: reward small post_residual relative to item size
    score -= 0.8 * item_size as f64;

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin) should only win when fits are terrible:
    // penalize it mildly so only bad existing fits lose to it
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, discourage opening extra bins more strongly
        let progress = step_index as f64 / total_items as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins with residuals near the mean (keeps bin population uniform)
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = (next_item_size - post_residual) as f64;
            score += 2.5 * waste;
        } else if post_residual >= next_item_size {
            // Reward bins that remain useful for the lookahead item.
            score -= 3.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere and the stream has plenty of remaining items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
        // A new bin is more attractive when few bins are open and mean
        // residual is small (existing bins nearly full).
        score -= (open_bins_count as f64).min(10.0) * 0.8;
        score -= mean_residual * 0.15;
        // Perfect-fit items (size divides capacity) like fresh bins.
        if bin_capacity % item_size == 0 {
            score -= 12.0;
        }
    }

    // Prefer filling bins with large residual when many bins are open
    // (consolidation pressure).
    if open_bins_count > 3 {
        score += (bin_residual as f64 - mean_residual) * 0.1;
    }

    // Slight preference for bins whose residual is an exact multiple region
    // of common item sizes: reward residual divisible by small sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 1.5;
        } else if post_residual < 10 {
            score += 2.0; // tiny slivers are dead space
        }
    }

    // Mild time-horizon modulation: early in the stream, be more willing
    // to keep bins balanced (penalize very low residual mildly); late in
    // the stream, prioritize closing bins out.
    if progress > 0.8 {
        score += post_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth progress coupling: dead space becomes costlier as stream advances
    score += 8.0 * pr_norm * pr_norm * (progress * progress);

    // Reward tight fits (near-zero post-residual) with a smooth dip
    let tightness = (-4.0 * pr_norm).exp();
    score -= 12.0 * tightness;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Lookahead: penalize leaving residual too small for next item, reward exact match
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (-8.0 * diff * diff).exp();
    } else if next_item_size > 0 {
        score += 3.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Mild penalty for scattering across many open bins
    score += 0.15 * open_bins_count as f64;

    // Slight preference toward bins below mean residual (balance residuals)
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let cls = post_residual / quarter; // 0..=4 harmonic class

    // Dead-space penalty grows super-linearly for mid-size leftovers (worst class: 25..50)
    match cls {
        0 => score -= 40.0,                       // perfect / near-zero residual
        1 => score += 5.0,                        // small leftover, still usable
        2 => score += 25.0,                       // 25..50 dead zone
        3 => score -= 10.0,                       // 50..75 still flexible
        _ => score += 2.0,                        // nearly full bin anyway
    }

    // Exact-fit bonus via modular arithmetic: post_residual divisible by common chunk sizes
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward leaving a residual that exactly hosts the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item cannot fit here; penalize more if this bin was the only option
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // opening a fresh bin costs more as stream progresses and bins accumulate
        score += 55.0 + 20.0 * progress + 1.5 * open_pressure;
        // but if mean residual across open bins is small, fresh bin is fine
        if mean_residual < item_size as f64 {
            score -= 45.0;
        }
    }

    // Mild preference to fill already-open bins rather than fragment across many
    score += 0.05 * open_bins_count as f64;

    // Tightness term: prefer bins whose residual is closest to the item (best-fit sharpening)
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest item are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // overflow guard (shouldn't happen)
    }
    let dead = post_residual < 10;
    if dead {
        score += 50.0 * (10.0 - post_residual as f64); // unusable gap penalty
    } else {
        // reward leaving a gap that can still fit a plausible future item
        score -= 8.0;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover -> mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress * 0.5);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when pressure is high or fill is low
        score += 30.0 + pressure * 2.0;
        // but a big item with no good fit elsewhere may justify a new bin
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 55.0;
        }
        if dead || post_residual == 0 {
            // never happens for empty bin, kept for symmetry
        }
        // if the item is small and open bins exist, opening is wasteful
        if open_bins_count > 0 && item_size <= 30 {
            score += 40.0;
        }
    } else {
        // favor bins with residual close to item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // deviation from mean residual: prefer bins with lower residual (fuller bins)
        score += (mean_residual - bin_residual as f64).max(-50.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after this placement exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match (small slack).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff > 0.0 && diff <= 10.0 {
            score -= 25.0 * (1.0 - diff / 10.0);
        }
    }

    // Penalize dead space: post_residual too small for the minimum item (1),
    // i.e., residual wasted unless exactly consumed later.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // This bin becomes useless for the next item; penalize proportionally.
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Compare against mean residual across open bins: prefer bins with
    // below-average residual (tighter bins) to consolidate space.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for opening a new bin early in the stream when the
    // item is large and would leave a very fragmented residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate (empty bin): baseline competitive score; it wins when
    // open bins would leave very poor fits.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use
        score += 0.3 * post_residual as f64;
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when fitting bins exist, unless residuals are large
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalation with number of open bins
        score += 400.0 + 10.0 * open_bins_count as f64;
        // Slightly cheaper to open new bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
    } else {
        // Favor bins tighter than the mean residual (best-fit flavor)
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty for leaving awkward residuals (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;
    let progress_cu = progress_sq * progress;

    // Normalized residuals
    let pr = post_residual as f64 / bin_capacity as f64;
    let ir = item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, prefer leaving large residuals (weight post_residual more);
    // late in the stream, prefer tight fits (penalize residual quadratically).
    let residual_weight = 1.0 + 0.6 * progress - 0.9 * progress_sq + 0.4 * progress_cu;
    score += residual_weight * (pr * pr) * bin_capacity as f64 * 0.5;

    // Reward filling the bin well: interaction of item_size with progress
    score -= ir * (1.0 + progress) * 8.0;

    // Penalize very small post-residuals that create dead space relative to typical item sizes
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (post_residual as f64 - ns).max(0.0);
        score += (waste / bin_capacity as f64) * 6.0 * (0.5 + progress);
        // Reward leaving exactly (or nearly) the next item's size
        let exact = (post_residual as f64 - ns).abs();
        score -= (1.0 - exact / bin_capacity as f64).max(0.0) * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation pressure)
    score += (open_bins_count as f64).ln().max(0.0) * pr * 2.0;

    // Coupling with mean residual: prefer bins whose residual deviates from the mean
    // toward fullness (below-average residual is good)
    let dev = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += dev * 4.0 * (0.5 + progress_sq);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: coarse buckets via integer division
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: small post_residual is good
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    } else if post_residual > 50 {
        score += 8.0; // large dead space penalty
    }

    // Harmonic lookahead: does next item fit into the post-residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits: reward, more if the fit is tight (harmonic pairing)
            let slack = (post_residual - next_item_size) as f64;
            let tightness = 1.0 - slack / cap;
            score -= 12.0 + 10.0 * tightness;
            // exact harmonic match (next fills bin exactly)
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 5.0 + 0.1 * ni;
        }
    } else {
        // last item: strongly prefer filling a bin as much as possible
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // mild penalty so existing bins are preferred unless they fit badly
        score += 10.0;
        if next_item_size > 0 && next_item_size as f64 >= 0.5 * cap {
            score -= 5.0; // big next item: a fresh bin is more attractive
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Progress-based modulation: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post / cap);

    // Prefer bins below mean residual (fills emptier bins when sensible)
    score += 0.05 * (mean_residual - post);

    // Modulo harmonic class: penalize residuals in awkward classes (e.g., 1 mod 10)
    let rmod = post_residual % 10;
    if rmod != 0 && post_residual > 0 {
        score += 1.0 + (rmod as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below the minimum item size) are pure waste.
    if post_residual < 10 {
        score += 40.0; // dead space penalty (nothing can ever fill it)
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    } else {
        // Tighter fits are better: reward small but usable residuals.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // If lookahead item can fill the post-residual exactly or nearly, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 30.0;
        } else if gap < 10.0 {
            score -= 10.0; // next item leaves only dead space anyway
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this bin's remainder: residual becomes semi-dead
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage opening a new one
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // new bin candidate: baseline cost plus pressure from open bins
        score += 10.0 + 6.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        }
    } else {
        // Favor placing into existing bins more strongly when many bins are open
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is already below average (consolidate small remainders)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow slightly more freedom to open bins (cheap future flexibility)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Core objective: minimize wasted post_residual ---
    // Strongly reward small post_residual (tight fits), especially below a dead-space threshold.
    if post_residual > 0 {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    } else {
        // Perfect fit: heavy reward
        score -= 30.0;
    }

    // Dead space penalty: post_residual too small for the smallest plausible future item
    let min_item = 1.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < min_item * 1.0 {
        score += 10.0;
    }
    if post_residual < 10 && post_residual > 0 {
        score += 8.0; // nearly unusable sliver
    }

    // --- 2-step lookahead: reward post_residual matching next_item_size ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item is excellent
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to tightness of that fit
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize relative to how far off we are
            score += 6.0 * (gap / bin_capacity as f64);
        }
        // Coupling with mean residual: prefer bins whose residual aligns with the flow
        let mean_gap = ((post_residual as f64) - mean_residual).abs();
        score += 0.15 * mean_gap * (0.5 + progress);
    }

    // --- Relative-to-mean residual preference ---
    // Favor bins that are already fairly full (low residual) to consolidate waste.
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * residual_ratio * residual_ratio;

    // --- Last-chance bonus: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins would create big dead space
        // or when no open bin exists / all fits are poor.
        let poor_fit_existing = if next_item_size > 0 && post_residual > 0 {
            (post_residual as f64) < (next_item_size as f64) * 0.5
        } else {
            false
        };
        if open_bins_count == 0 {
            score -= 50.0; // must open
        } else if poor_fit_existing {
            score -= 5.0; // mildly favor fresh bin over fragmenting
        } else {
            score += 25.0 + 15.0 * progress; // discourage opening when decent fits exist
        }
        // Scale new-bin cost with number of open bins (bin proliferation penalty)
        score += 2.0 * open_bins_count as f64;
    }

    // --- Fragmentation pressure over time: later in stream, prefer tighter packing ---
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    // Mild tie-breaker: prefer bins with larger current residual among equals is already
    // encoded via post_residual; add tiny noise-free deterministic tie-break.
    score += 0.001 * (bin_residual as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
