    }

    // Lookahead: penalize if the next item cannot use the post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // residual stays useful for the lookahead item
        } else {
            score += 6.0 + 0.1 * (post_residual as f64); // dead space risk
        }
        // If next item exactly matches post_residual, big reward.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: strongly prefer tightest packing.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins whose residual is far below the mean residual
    // (keep heterogeneous residuals for future flexibility).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Penalize creating residuals in the "unusable zone": too small for
    // typical items (assume items >= ~10) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, allow more bins to be opened to keep flexibility;
    // later, conserve bins and prefer filling existing ones.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };
    score += (1.0 - progress) * 5.0;

    // Many open bins: discourage spreading; few open bins: encourage using them.
    score += 0.3 * (open_bins_count as f64);

    // New-bin candidate handling: only prefer a new bin when current residuals
    // are large (poor fits available) and we are early in the stream.
    if bin_residual == bin_capacity {
        score += 40.0 * progress; // later stream => opening new bins is costly
        if mean_residual > (item_size as f64) * 1.5 {
            score -= 20.0; // existing bins have big residuals anyway -> new bin ok
        }
        if next_item_size > 0 && (bin_capacity - item_size) < next_item_size {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) growth.
    let mut score = post + 40.0 * (post / cap).powi(2) + 60.0 * (post / cap).powi(3);

    // Perfect fit reward: strongly subtract when post_residual is tiny.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0 * (1.0 - post / 10.0);
    }

    // Smooth interaction: dead space hurts more as the stream progresses.
    score *= 1.0 + 0.8 * progress * (post / cap);

    // Lookahead coupling: reward leaving space exactly matching next item,
    // penalize leaving space slightly too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score -= 50.0 * (-200.0 * diff * diff).exp();      // exact-match bonus
        if post < nxt && post > 0.0 {
            score += 35.0 * (1.0 - post / nxt);            // near-miss penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0 + 30.0 * progress;
    }

    // New-bin candidate: make empty bins mildly attractive only when the
    // item fits poorly everywhere else (large post_residual on existing bins).
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.35 * post + 20.0 * progress;
        // Counter-balance last-chance reward so a real bin still wins on good fits.
        if fitting_bins_count == 1 {
            score += 40.0 + 25.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and near-fill classes are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 10 {
        score -= 22.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Modulo-class penalty: residuals that are awkward fractions of capacity
    // (e.g. in (30,40) or (60,70) bands) tend to become dead space.
    let band = (pr / 10) % 10;
    let band_penalty = match band {
        3 => 8.0,
        6 => 6.0,
        8 => 4.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Harmonic match with next item: reward residual exactly/near divisible
    // into chunks the next item can consume.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr as f64 - ni).abs();
        if gap <= 2.0 {
            score -= 18.0; // next item nests almost perfectly
        } else if (pr as u32) >= next_item_size {
            // residual can hold next item: mild reward scaled by tightness
            score -= 10.0 * (ni / (pr as f64 + 1.0));
        }
        // integer-division harmonic: residual / next_item leaves small remainder
        if next_item_size > 0 && pr >= next_item_size {
            let q = pr / next_item_size;
            let r = pr % next_item_size;
            if q >= 1 && r <= 3 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Empty new-bin candidate: penalize mildly so it only wins when fits are bad,
    // but allow it when all existing residuals are hopeless.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress-aware tightening: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Prefer bins already below mean residual (consolidating slack).
    score += 0.15 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; mild penalty for leaving awkward gap
            score += 5.0;
        }
    }

    // Open bins pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Align with mean residual: bins far from mean residual get slight penalty.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: make it moderately attractive only when it's genuinely better,
    // i.e., when no open bin offers a decent fit (this call has full residual = capacity).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when open bins are numerous
        // or the current item is large (fewer future chances to pair).
        score = 30.0 + 0.5 * post_residual as f64 - (open_bins_count as f64).ln() * 4.0 - 0.1 * item_size as f64;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            // leftover after the lookahead item; smaller leftover is better
            let after_next = (post_residual - next_item_size) as f64;
            score -= 15.0 - after_next.min(15.0);
        } else {
            // next item won't fit here; penalize wasted residual relative to mean
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating large unusable dead space (< smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 30.0; // an open bin could take it; discourage new bin
        }
    }

    // Mild early-stream conservatism: keep bins flexible early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 - 8.0 * post_residual as f64;
    }

    // Penalize large dead space, scaled by how much of the bin it wastes.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack);
        } else {
            // Next item won't fit here; mildly penalize leaving a gap that
            // is too small for typical future items.
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer closing bins as tightly as possible.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, decaying as stream progresses (sunk bins matter less).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 90.0 * (1.0 - 0.5 * progress);
        // If many bins can fit the item, discourage opening a new one.
        score += 10.0 * fitting_bins_count as f64;
        // If open bins have low mean residual (all fairly full), new bin is more reasonable.
        score -= 0.5 * mean_residual;
        // Encourage new bin when current item is large (fewer future placement options).
        score -= 0.3 * item_size as f64;
    } else {
        // Favor placing into existing bins when they are relatively empty compared to mean.
        let diff = mean_residual - bin_residual as f64;
        score += 0.2 * diff;
        // Slight preference for filling bins with more residual (consolidate emptiness).
        score -= 0.05 * bin_residual as f64;
    }

    // Dynamic time horizon: early in the stream, be conservative with tight fits
    // that could serve larger items later; late in the stream, accept them freely.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < item_size {
        // Dead space that only small items can fill; cost decreases over time.
        score += (1.0 - horizon) * 10.0;
    }

    // Mild penalty for proliferation of open bins (fragmentation control).
    score += 0.05 * open_bins_count as f64 * (1.0 - horizon);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    let nz = (next_item_size as f64 / bin_capacity as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling: post_residual polynomial weighted by stream progress
    let poly = pr * pr * (1.0 - pr) + pr * pr * pr;
    score += 8.0 * poly * (0.5 + progress);

    // Reward exact/near-exact fits smoothly
    let tightness = 1.0 - pr;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: penalize residuals that can't smoothly accommodate the next item
    let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    if next_item_size > 0 {
        let usable = 1.0 / (1.0 + (-4.0 * gap).exp());
        score -= 5.0 * usable * nz;
        score += 3.0 * (1.0 - usable) * nz * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: smooth sigmoid gating against mean residual
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(mean_residual - item_size as f64) / 10.0).exp());
        score = 110.0 - 20.0 * gate + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fills are perfect.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr <= 5 {
        score += 60.0; // tiny dead space is nearly worthless
    } else if pr < 10 {
        score += 25.0;
    }

    // Modulo-class reward: residual that is a multiple of common small item
    // sizes (harmonic divisor classes) stays usable.
    let harmonic = if pr == 0 { 0 } else {
        let mut best = 0u32;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 && d > best { best = d; }
        }
        best
    };
    score -= harmonic as f64 * 4.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward proportional to how well next item nests
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 + 20.0 * (1.0 - slack / cap);
            if (pr % next_item_size.max(1)) == 0 {
                score -= 15.0; // exact division: harmonic pair
            }
        } else {
            score += 35.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin would be left with unusable scraps.
    if bin_residual == bin_capacity {
        // fresh bin: baseline cost, penalized if existing bins fit fine
        score = 40.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score += 50.0; // forced new bin anyway, slight nudge
        }
    }

    // Fraction-of-capacity thresholds on post residual (capacity classes).
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score -= 10.0; // still roomy bin
    } else if frac > 0.25 {
        score += 5.0;
    } else {
        score += 20.0; // near-dead bin
    }

    // Mild preference for tighter bins overall as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.3 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

