    }

    // Prefer bins with below-mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for wasting a large bin on a small item when residual stays large.
    if post_residual > 50 {
        score += 5.0;
    }

    // New-bin candidate: neutral baseline; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
