        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // Base cost of a new bin; cheaper late in the stream or when residuals are fragmented.
        score = 70.0 - 30.0 * progress + 20.0 * pressure;
        if next_item_size > 0 && next_item_size > bin_residual {
