        score -= 15.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // next item can't use this gap -> dead space likely
        score += 8.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // tighter fills.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_reward = if diff == 0.0 {
            60.0
        } else if post_residual >= next_item_size {
            // next item can still fit here afterwards: partial reward decaying with gap
            30.0 * (1.0 - diff / bin_capacity as f64)
        } else {
            // next item won't fit in leftover: dead space penalty grows with gap
            -(diff * 0.35)
        };
        score -= match_reward;
    }

    // Tight fit reward: small post_residual is good, but zero residual is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize bins already looser than the mean (fragmented bins), favor tighter-than-mean bins.
    let rel_mean = post_residual as f64 - mean_residual;
    score += 0.25 * rel_mean;

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 0.8 * open_bins_count as f64;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; softened late in the stream or when bins are crowded.
        let mut new_bin_cost = 55.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin trivially "matches" lookahead; don't let that fake reward dominate
            new_bin_cost += 20.0;
        }
        if fitting_bins_count == 0 {
            new_bin_cost -= 60.0; // forced: no open bin fits
        } else if fitting_bins_count == 1 {
            new_bin_cost += 40.0; // an open bin is a last chance; keep using it
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost -= 10.0 * progress;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that likely can't be reused:
    // post_residual too small for typical future items (1..100 unknown, assume mid ~40).
    if post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64);
    } else if post_residual > 60 {
        // Large leftover is fine (reusable), slight reward scaled by time left.
        let horizon = (step_index as f64 + 1.0) / (total_items as f64).max(1.0);
        score -= 6.0 * (1.0 - horizon) * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly more if this bin becomes very dead.
            if post_residual < next_item_size && post_residual < 15 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let avg_fit_gap = (mean_residual - item_size as f64).abs();
        // If existing bins have poor fits (mean residual far from item), new bin is tempting.
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 * openness; // base cost of a new bin
        if avg_fit_gap > 30.0 {
            score -= (avg_fit_gap - 30.0) * 0.8;
        }
        // Early in stream, slightly cheaper to open bins to build diversity.
        let horizon = step_index as f64 / (total_items as f64).max(1.0);
        score -= 10.0 * (1.0 - horizon);
    } else {
        // Crowding control: many open bins -> prefer consolidating into existing ones.
        score += 0.5 * open_bins_count as f64;
        // Prefer bins whose residual is close to the item (best-fit flavor beyond post_residual).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * gap;
    }

    // Global balance: nudge toward bins below mean residual to even out leftovers.
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    // smooth non-linear coupling of post_residual with stream progress
    let tight = 1.0 - pr / cap;
    score -= tight * tight * 12.0 * (0.5 + 0.5 * progress);
    // penalize dead space that can't fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr) / cap;
        if waste > 0.0 {
            score += waste * waste * 20.0 * (1.0 - progress);
        } else {
            score -= 6.0 * (1.0 - progress);
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }
    // new-bin candidate: mildly discourage early, allow late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 3.0 * progress;
    }
    // smooth mean-residual coupling
    score += 0.05 * (pr - mean_residual) * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "usable" classes (small dead space, or exactly reusable slots).
    let classes = [0u32, 10, 20, 25, 33, 50];
    let mut best_gap = 101u32;
    for &c in classes.iter() {
        let d = (post_residual as i64 - c as i64).abs() as u32;
        if d < best_gap { best_gap = d; }
    }
    score += best_gap as f64 * 0.3;

    // Exact class match bonus: post_residual equals a harmonic divisor class
    for &c in classes.iter() {
        if post_residual == c {
            score -= 6.0;
        }
    }

    // Penalize tiny unusable slivers (post_residual in 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover < 10 { score += 4.0; } else { score -= 3.0; }
        } else {
            // next item won't fit here; residual becomes dead space
            score += post_residual as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when current bin fit is poor
    if bin_residual == bin_capacity {
        score = post_residual as f64 * 0.5 + 5.0;
        if fitting_bins_count >= 1 {
            score += 10.0; // discourage opening new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Progress-aware tightening: late in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.4;

    // Many open bins: prefer consolidating into fuller bins
    if open_bins_count > 4 {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 10) can use are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else {
        // Small but potentially usable gaps: mild penalty scaled by how tight the fit is.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * tightness;
    }

    // Penalize large leftover gaps that are likely to strand space (fragmentation risk),
    // but less harshly than dead space.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.35;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when mean residual is already low.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.4;
        // Prefer bins whose residual deviates from the mean toward tighter fits.
        score += (mean_residual - bin_residual as f64).abs() * 0.1;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Late in the stream, prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover after placement exactly fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack.min(40.0);
    } else if next_item_size > 0 {
        // Penalize leftovers that just barely miss fitting the next item.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.8;
    }

    // Reward tight fits: small post_residual is good dead-space control.
    score -= (bin_capacity - post_residual) as f64 * 0.35;

    // Penalize bins whose residual deviates above the mean (fragmented bins).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when the fit here is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A fresh bin wastes item_size worth of space immediately; make it
        // attractive only if this bin's placement would leave a large orphan gap.
        let orphan = post_residual as f64;
        if orphan > 60.0 {
            score -= 40.0; // very bad fit here -> open new bin
        } else {
            score += 55.0; // decent fit here -> keep using open bins
        }
    }

    // Late-stream consolidation: as the stream nears its end, prefer filling
    // existing bins to avoid many half-empty leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Mild pressure to use bins when many are open.
    score -= open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residuals elsewhere are large or item is big.
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 40.0;
        score -= 25.0 * (1.0 - tightness); // big items fit well in fresh bins
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits, must open
        }
        // Late in stream, prefer filling existing bins harder.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Lookahead: reward if next item exactly fills the post residual (perfect pairing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 20.0;
        } else {
            score += gap * 0.3;
        }
    }
    // Penalize leaving a residual too small for any realistic next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < 10.min(next_item_size.max(1))) {
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (bin_res_f - mean_residual) * 0.15;
    }

    // With many open bins, encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize leftover space, weighted by a smooth progress-driven polynomial
    let base = pr * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0 * progress * (1.0 - progress) + 0.8 * progress * progress);

    // Non-linear coupling: squared normalized post residual (dead space penalty)
    let dead = (pr / cap).powi(3) * cap * (0.4 + 0.6 * progress);

    // Reward tight fits: smooth function of post residual relative to capacity
    let tight = -(1.0 - pr / cap).powi(4) * 12.0;

    // Last-chance bin: strong smooth bonus when few fitting bins exist
    let last_chance = if fitting_bins_count <= 1 { -(8.0 + 6.0 * (1.0 - progress)) } else { 0.0 };

    // Lookahead: penalize if post residual can't fit the next item smoothly
    let look = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        (gap / cap).powi(2) * 10.0
    } else {
        0.0
    };

    // New-bin candidate: prefer opening a new bin when existing residuals are large
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_pen = is_new * (pr * 0.3 - mean_residual * 0.25 - 4.0 * (1.0 - progress));

    // Dispersion penalty: bins far from mean residual are less attractive
    let disp = ((pr - mean_residual) / cap).abs() * 3.0;

    let mut score = base + dead + tight + last_chance + look + new_pen + disp;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64; // 0..1
    let class = (frac * 8.0).floor() as i64; // 8 harmonic octiles of residual

    // Penalize residuals that are "awkward" — hard to fill by future items (1..100).
    // Items <= post_residual can fit; measure fillability as post_residual/100.
    let fillability = post_residual as f64 / 100.0;
    score += 12.0 * (1.0 - fillability) * (1.0 - fillability);

    // Modulo logic: residuals that are multiples of 10 are more reusable (sizes often multiples of 10).
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    } else {
        score += 3.0;
    }

    // Integer division thresholds: perfect fits (post_residual 0) strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportionally, but penalize if it leaves another awkward gap
        let gap_after_next = post_residual - next_item_size;
        score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        if gap_after_next % 10 != 0 {
            score += 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize tight-but-wasted bins less if residual large
        score += 5.0 * (post_residual as f64 / next_item_size.max(1) as f64).min(3.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer reusing
    // open bins with good fits, but a bonus when open bins would create huge dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; attractive if the item is large relative to capacity
        // and mean residual of open bins is small (open bins are nearly full anyway).
        score = 55.0 - 0.4 * item_size as f64;
        if next_item_size > 0 {
            // if next item would also need space, a fresh bin keeps flexibility
            score -= 0.25 * next_item_size as f64;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Existing bin: reward when mean residual is high (bins are loose, keep compacting)
        score -= 0.05 * mean_residual;
        // Slight preference for bins in busier phases of the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * progress * fillability;
    }

    // Harmonic tie-breaker on class: middle octiles are best (residual ~30-60 reusable)
    match class {
        0 => score += 8.0,      // nearly full already
        1 => score += 2.0,
        2 => score -= 4.0,
        3 => score -= 6.0,
        4 => score -= 5.0,
        5 => score += 1.0,
        6 => score += 5.0,
        _ => score += 10.0,     // mostly empty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
