pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to plausibly hold future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Bonus if post_residual fits next item with a tight match
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap < 10 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open new bins (exploration)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open or late in stream
        score += 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But if the item is large, a fresh bin is attractive
        score -= item_size as f64 * 0.3;
    }

    // Late in stream: discourage opening new bins, encourage filling existing ones
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits strongly; late: relax slightly but punish dead space quadratically.
    let w = 1.0 + 2.0 * (1.0 - progress) * (1.0 - progress);
    score += w * (post / cap) * (post / cap) * cap;

    // Cubic coupling: penalize mid-range residuals that are neither full nor empty (dead space).
    let r = post / cap;
    score += 8.0 * r * r * (1.0 - r) * (1.0 - r) * cap * 0.5;

    // Reward perfect or near-perfect fits.
    if post == 0 {
        score -= 50.0;
    } else if post <= 10 {
        score -= 20.0 * (1.0 - post as f64 / 10.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize blocking the next item with a small unusable remainder.
        score += 5.0 + 10.0 * (1.0 - post / cap);
    }

    // New-bin candidate: prefer it only when existing bins are crowded.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * mean_residual.min(cap) / cap * -1.0;
        score -= 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score -= 20.0 * progress;
    }

    // Mild penalty proportional to spread from mean residual: keep bin states homogeneous.
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: leftovers divisible into small chunks are reusable.
    let pr = post_residual;
    if pr > 0 {
        // class by residue modulo small harmonics
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 12.0; }        // decade-aligned leftovers are highly reusable
        else if pr % 5 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 50 == 0 { bonus += 4.0; }
        score -= bonus;

        // Integer-division thresholds: leftovers in "dead zones" are penalized.
        let dead = if pr < 10 { 30.0 }          // tiny sliver, nearly unusable
                   else if pr < 20 { 15.0 }
                   else if pr < 30 { 8.0 }
                   else { 0.0 };
        score += dead;
    }

    // Tightness reward: relative fill of the bin.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 25.0 * fill * fill;

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 60.0;
        } else {
            score -= 30.0 * (1.0 - diff as f64 / cap);
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item cannot use this leftover: leftover likely becomes dead space.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer filling bins when many bins are open (reduce fragmentation).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_residual as f64 / cap);

    // Early in the stream, allow opening bins for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when open bins fit poorly.
        let early_bonus = 18.0 * (1.0 - progress);
        score -= early_bonus;
        // Penalize new bins late in the stream.
        score += 25.0 * progress;
    } else {
        // Slight preference for existing bins whose residual is close to the mean.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is too small for the smallest plausible item (1..100 unknown,
    // so treat gaps < 10 as near-dead, gaps < next_item_size as unusable for the lookahead item).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // tiny sliver: almost certainly wasted
        } else if post_residual < 20 {
            score += 12.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 18.0; // gap cannot host the next item -> dead space
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0; // perfect two-item pairing
        }
    } else {
        score -= 30.0; // exact fill: zero waste, best outcome
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into existing ones
    // (penalize opening new bins); when few are open, new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins accumulate.
        score += 10.0 + 8.0 * pressure;
        // But late in the stream, opening a fresh bin for large items is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    } else {
        score -= 3.0 * pressure.min(6.0); // reward reusing bins under pressure
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Prefer bins whose residual is below average (they are the "fuller" ones);
    // keeps large gaps concentrated in fewer bins for future big items.
    if bin_residual < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mean residual coupling: large average slack suggests fragmentation; favor placements
    // that reduce it (i.e., low post_residual weighted by mean slack).
    score += 0.05 * mean_residual * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: place here so the next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - leftover / bin_capacity as f64);
    }
    // Next item cannot use this residual: penalize proportionally to wasted space.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with small residuals relative to the mean (tight packing).
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current bins would leave large waste.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if fitting_bins_count > 0 && mean_residual < item_size as f64 * 1.2 {
            score += 30.0; // keep using tight open bins instead
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && post_residual < 10 {
            // small dead space, mildly tolerable
            score += 5.0;
        } else {
            // stranded medium gap the next item cannot use
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Crowding effect: with many open bins, prefer consolidation into existing bins.
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= 4.0 * crowding * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global residual alignment: prefer bins close to mean residual (keeps spread uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Time horizon: early in stream, be pickier about tight fits; late, just fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well or item is large.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (post_residual as f64 > 0.5 * bin_capacity as f64 && fitting_bins_count <= 1);
        if poor_alternatives {
            score -= 30.0 + 10.0 * progress;
        } else {
            score += 25.0 + 15.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tighter residual (small post_residual) is rewarded more.
    let t = progress;
    let tight_reward = (1.0 - pr / cap).powi(2) * (0.5 + 2.0 * t * t);
    score -= 12.0 * tight_reward;

    // Smooth penalty for mid-range dead space: residual that is neither small nor large.
    let x = pr / cap;
    let mid_pen = 16.0 * x * (1.0 - x) * (1.0 - x);
    score += mid_pen;

    // Lookahead coupling: reward if next item fits smoothly in post_residual (quadratic smoothness).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 6.0 * (1.0 - slack / cap).powi(2) * (0.3 + t);
        } else {
            // next item won't fit: penalize proportionally to overflow, smoothed
            let over = (nx - pr) / cap;
            score += 8.0 * over * over * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Slight preference to fill fuller bins when many bins are open (smooth in count).
    let open_norm = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score -= 4.0 * open_norm * (it / cap);

    // Mean residual coupling: bins deviating below mean residual are more valuable to fill.
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds: 0..10 classes
    match class {
        0 => score -= 60.0,          // perfect fit
        1 => score -= 45.0,          // leftover 10-19: fits smallest items
        2 => score -= 30.0,
        3 => score -= 18.0,
        4 => score -= 10.0,
        5 => score -= 4.0,           // half-full leftovers
        6 => score += 2.0,
        7 => score += 5.0,
        8 => score += 9.0,
        9 => score += 14.0,
        _ => score += 0.0,           // near-empty bin
    }

    // Lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use leftover: penalize large leftovers slightly
            score += 0.05 * (pr as f64 - mean_residual).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, more when late in stream
    // or when open bins are already sparse.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 70.0 + 30.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Modulo-based harmonic coupling: leftover divisible by common item sizes
    // is more reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable.
    if post_residual < 10 {
        score -= 40.0; // perfect/near-perfect fit is excellent
    } else if post_residual <= 20 {
        // small gap: risky dead space unless the next item can use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 25.0;
        }
    } else if post_residual <= 35 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Reward tight fits: fraction of bin used by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, slightly discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize relative to open bins count
        score += 20.0 + 3.0 * (open_bins_count as f64).min(10.0) - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    } else {
        // existing bin: mild bonus scaled by how crowded the bin already is
        let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * used;
    }

    // Coupling with mean residual: bins far below mean residual are wasteful targets
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 60.0 + 40.0 * tightness;
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        let dead = post_residual as f64 - (next_item_size as f64).min(post_residual as f64);
        score += 0.5 * dead;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // placing into them is good if fit is tight, bad if it creates large leftovers.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless residual is large (would waste a mostly-full bin anyway).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        score += 50.0 + 10.0 * pressure - 20.0 * progress;
        // Allow new bin if item would leave huge residual elsewhere anyway.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Mild penalty for leaving residual in awkward small band (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powi(2) * 30.0;
        score += dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening new bins unless current
    // bins are quite full or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Open new bin only if existing bins are well-filled and this fit is bad.
        let open_penalty = 45.0 + 30.0 * (1.0 - avg_fill) - 20.0 * progress;
        let poor_fit = if post_residual > 0 && post_residual < 10 { 0.0 } else { 10.0 };
        score += open_penalty + poor_fit;
    } else {
        // Mild preference for reusing bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balance residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling: dead space penalized super-linearly,
    // with penalty strength growing over the stream.
    let mut score = pr * (1.0 + 0.9 * pr_norm * pr_norm);

    // Progress-modulated curvature: late in the stream, prefer tight fits more strongly.
    score += pr_norm * pr_norm * progress * 18.0;

    // Reward filling a bin almost exactly (post_residual near zero) smoothly.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (10.0 + 8.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // Lookahead: favor bins whose post-residual can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (1.0 - progress);
    }

    // Mild penalty when this bin's residual deviates far from mean residual,
    // scaled smoothly by number of open bins.
    let dev = (pr - mean_residual).abs();
    score += (dev / cap) * (2.0 + 0.15 * open_bins_count as f64);

    // New-bin candidate: penalize slightly so we only open when open bins are poor.
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it occupies.
    let item_class = (item_size * 4 / bin_capacity) as f64; // 0..=3
    let post = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent, but dead space
    // below the smallest item (harmonic floor) is worthless.
    let dead_floor = 10.0f64.min(cap * 0.05);
    if post > 0.0 && post <= dead_floor {
        score -= 25.0; // near-perfect fill
    } else if post > 0.0 {
        // Penalize dead space that is too small for typical items (unusable slivers).
        if post < 20.0 {
            score += (20.0 - post) * 0.8;
        }
        // Reward post_residual that matches a harmonic class of future items
        // (divisible into plausible sizes: multiples of 10 or the next item).
        let harm = post_residual % 10;
        if harm == 0 {
            score -= 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else if next_item_size > 0 {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Integer-division threshold on post_residual quarter-class.
    let post_class = post_residual * 4 / bin_capacity;
    score -= (3 - post_class.min(3)) as f64 * 3.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size > bin_capacity / 2;
        if desperation > 0.0 || (big_item && post_residual == 0) {
            score -= 5.0;
        } else {
            score += 40.0 + mean_residual * 0.2; // discourage opening new bins
        }
    }

    // Mild progression coupling: later in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual as f64) * 0.1;

    // Prefer bins below mean residual (tighter bins first) scaled by item class.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05 * (1.0 + item_class * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual that is too small to fit typical future items.
    let min_item = 1.0f64;
    if post > 0.0 && post < 10.0 {
        // Gap too small for anything useful: strong penalty scaled by tininess.
        score += (10.0 - post) * 4.0;
    }
    // Medium gaps (10..30) are risky too: penalize moderately.
    if post >= 10.0 && post < 30.0 {
        score += (30.0 - post) * 0.8;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post == 0.0 {
        score -= 25.0; // perfect fill
    } else if post <= 20.0 {
        score -= 8.0;  // good compact fill
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid wasted open capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or the next item fits better in a fresh bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: proportional to open bins pressure.
        score += 15.0 + open_bins_count as f64 * 1.5;
        // If placing in an existing bin would leave a small dead gap, new bin looks better.
        if post > 0.0 && post < 10.0 && bin_residual as f64 - item_size as f64 > 0.0 {
            // existing-bin calls already penalized; nudge new bin down slightly
            score -= 5.0;
        }
        // Lookahead: if next item is large and current residual barely fits current item,
        // a fresh bin preserves large space for the next item.
        if next_item_size > 0 && (next_item_size as f64) > post + 5.0 && post < 15.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward for consuming a bin that has large residual
        // (consolidation), penalized by open bin pressure.
        score -= (bin_residual as f64 - post) * 0.05;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones (lower score
    // for existing bins relative to new bins already handled); add slight global tilt.
    score += open_bins_count as f64 * 0.3;

    // Stream progression: late in the stream, prefer perfect fills even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post == 0.0 {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if mean residual is low, conserve big-residual bins.
    if (bin_residual as f64) > mean_residual + 20.0 && !is_new_bin {
        score += 3.0; // don't chip away at unusually roomy bins for small gains
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
