pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tight = post_residual as f64 / bin_capacity as f64;
    score += tight * tight * 60.0;

    // Lookahead: if the next item fits exactly in the post residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 400.0;
        } else {
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot use the leftover (dead space risk)
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize creating very small unusable residuals when many bins are open
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Time horizon: early in stream, prefer consolidating into existing bins;
    // late in stream, allow opening new bins when fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current bins have poor fit
        let poor_fit_penalty = (post_residual as f64) * 0.5;
        score += 120.0 - 80.0 * progress;
        score -= poor_fit_penalty * 0.0; // new bin residual is full capacity, keep base
        // Discourage opening new bins when mean residual across open bins is large
        score += mean_residual * 0.6;
        // Fewer open bins -> cheaper to open a new one
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins with residual close to mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
        // Prefer fuller bins (smaller residual) slightly more as stream progresses
        score -= (bin_capacity - bin_residual) as f64 * 0.2 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Base: prefer tight fits (low post residual), smoothly amplified by progress
    let mut score = pr * (1.0 + 1.5 * progress);

    // Non-linear penalty on wasted space: cubic coupling with progress
    score += 40.0 * pr_norm.powi(3) * (0.5 + progress);

    // Reward bins whose post-residual matches the next item (smooth kernel)
    let match_term = (pr_norm - next_norm).abs();
    score -= 12.0 * (1.0 - match_term).max(0.0) * (1.0 - progress) * if next_item_size > 0 { 1.0 } else { 0.0 };

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild congestion penalty scaled by number of open bins
        score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - item_norm);
    }

    // Deviation from mean residual: prefer bins below mean (consolidation)
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Slight preference against opening new bins late in the stream
    score += 6.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by 8 (capacity/12.5 harmonics) are "usable" classes.
    let r = post_residual;
    let class_penalty = match r % 8 {
        0 => -40.0,
        4 => -20.0,
        2 | 6 => 5.0,
        _ => 15.0, // odd residuals are awkward
    };
    score += class_penalty;

    // Small dead space is bad (unusable sliver): penalize residuals < 10 (min item size)
    if r > 0 && r < 10 {
        score += 60.0;
    }

    // Next-item coupling: if next item fits into post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= r {
        score -= 50.0;
        // extra reward if next item exactly fills the new residual
        if next_item_size == r {
            score -= 80.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: this residual risks becoming dead space
        score += 25.0;
    }

    // Last-chance bin: only fitting bin available -> strong preference to use it
    if fitting_bins_count == 1 {
        score -= 70.0;
    }

    // Prefer tighter bins when many bins are open (reduce fragmentation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Early in stream: be slightly more willing to open bins for good fits;
    // late in stream: consolidate to avoid opening extra bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 20.0 * (open_bins_count as f64 / 10.0).min(2.0);

    // Compare against mean residual: bins tighter than average get preference
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 50 { -30.0 } else { 40.0 };
        score += 60.0 + large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for future items (sizes >= 1 but typically larger), so punish hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Mid-range gaps (11..=30) are partially usable; mild penalty.
    else if post_residual > 10 && post_residual <= 30 {
        score += 0.6 * (post_residual as f64 - 10.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward filling bins that are already mostly full (tight packing pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost grows with number of open bins.
        score += 15.0 + 10.0 * open_pressure;
        // Late in the stream, new bins are less worthwhile.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        score -= 5.0 * open_pressure;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement; if post_residual can't hold next_item_size but another
    // gap could, slight penalty for stranding the space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mean-residual coupling: bins far below the mean residual are "wasted"
    // candidates; prefer bins near or below mean residual (they are the ones
    // with room matching the current slack profile).
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here afterwards: good chain, but keep some tightness
            score -= 30.0 + 0.5 * (next_item_size as f64);
            // extra reward if next item then leaves small remainder
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 5 {
                score -= 150.0;
            } else if chain_residual <= 15 {
                score -= 40.0;
            }
        } else {
            // dead space relative to next item: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Prefer tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening a new bin unless the item is large relative to capacity
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size as f64 > 0.5 * bin_capacity as f64 { 60.0 } else { 0.0 };
        score += 120.0 - large_item_bonus - 40.0 * progress;
        // if no open bin can fit, new bin is necessary anyway
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
