pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress) - 0.35 * x * x;

    // Non-linear interaction: tight fits rewarded more as stream advances
    let tightness = 1.0 - x;
    score -= 0.5 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev * dev.abs().max(0.01).sqrt() * (1.0 + progress);

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
