    let class = post_residual / 10; // integer-division threshold classes (0..=10)
    let class_penalty = match class {
        0 => -25.0,                       // perfect fit
        1 => -8.0,                        // residual 10-19: usable by small items
        2 => 6.0,                         // residual 20-29: awkward zone
        3 => 2.0,
        4 => -3.0,                        // residual 40-49: fits mid items well
        5 => 4.0,
        6 => -1.0,
        7 => 3.0,
        8 => 0.0,
        9 => -2.0,
        _ => 0.0,                         // near-empty / new bin
    };
    score += class_penalty;

    // Reward placements whose leftover can host the lookahead item exactly-ish.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // perfect two-step chain
        } else if gap > 0 && (gap as u32) < 10 {
            score -= 12.0; // near-chain, leaves tiny dead space
        } else if gap < 0 {
            score += 5.0; // next item won't fit here
        }
        // Harmonic compatibility: both residuals in same mod-10 class chain well
        if post_residual % 10 == 0 && next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when it truly beats packing into waste.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15 + (open_bins_count as f64) * 0.5;
    } else {
        // Mild bonus for tightening bins when many are open (consolidation).
        score -= (open_bins_count as f64) * 0.3;
        // Prefer bins tighter than the mean (pack full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Late-stream urgency: fill existing bins harder as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
