            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: residual will shrink further.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.5 * slack_after_next;
        } else {
