    }

    // Reward tight fits relative to mean residual across open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f).min(50.0) * 0.6;
    } else {
        score += (post_f - mean_residual).min(50.0) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 20.0 * progress;
        // A new bin is attractive if the next item is large and won't fit elsewhere.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Slight preference for filling bins with more residual (consolidation).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..10) can use.
    let dead_threshold = 9.0;
    if post_residual as f64 > dead_threshold {
        score += 0.35 * (post_residual as f64 - dead_threshold);
    } else if post_residual > 0 {
        score -= 6.0; // near-perfect fill bonus
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chain_fit / (bin_capacity as f64));
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover can't host next item: mild penalty scaled by leftover size
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Crowding: when many bins are open, prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowding = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 0.6 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean residual anchoring: prefer bins near the mean residual (balanced packing),
    // but late in the stream prefer below-mean residual (fill the fullest usable bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += if progress < 0.5 { 0.25 * dev } else { -0.15 * (bin_residual as f64 - mean_residual) };

    // New-bin candidate: allow opening a fresh bin when current bin fit is poor
    // or late-stream fragmentation is high; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.6;
        if poor_fit && fitting_bins_count > 0 {
            score -= 12.0; // fresh bin beats stuffing into a bad fit
        } else {
            score += 8.0 + 2.0 * (open_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: as the stream advances, tighten the preference
    // for small post_residual (dead space becomes more costly late).
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: item size vs post residual — big items into roomy bins
    // are fine early, penalized late.
    let interaction = norm_item * norm_pr;
    score += 15.0 * interaction * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
        } else {
            // penalize creating residuals that just barely miss the next item
            let miss = (nxt - pr) / cap;
            score += 4.0 * miss;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): mild penalty so it is chosen only when
    // open bins fit poorly; penalty grows with stream progress.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    // Slight preference for bins whose residual deviates from the mean,
    // consolidating dead space (smooth quadratic term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Very small residuals are near-unusable dead space: penalize smoothly.
    score += 5.0 * (-(norm_pr * 10.0)).exp() * (1.0 - norm_item);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "friendly" (divisible by small sizes or near multiples of 10)
    let residue_class = post_residual % 10;
    let friendly = match residue_class {
        0 => 8.0,
        1 | 9 => 4.0,
        2 | 5 => 3.0,
        _ => 0.0,
    };
    score -= friendly;

    // Penalize dead space: residuals too small for typical smallest item (<= 9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (post_residual small but usable)
    if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    }

    // Integer division threshold: post_residual / item_size ratio
    let ratio = pr / (item_size as f64).max(1.0);
    if ratio < 0.25 {
        score -= 4.0; // item dominates bin: good consolidation
    } else if ratio > 1.5 {
        score += 3.0; // item small relative to bin: wasteful unless last chance
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
        // extra reward if next item exactly matches residue class
        if post_residual % next_item_size.max(1) == 0 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward remainder
        score += 4.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score, only chosen
    // when open bins fit poorly
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, reduced late in stream or few bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.5 + 10.0 - 15.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
        // discourage opening new bin if current bin would be near-perfectly used
        if bin_capacity - item_size <= 10 {
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean toward tighter fill
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Modulo coupling between post_residual and capacity quarters
    let quarter = bin_capacity / 4;
    if post_residual % quarter.max(1) == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for the smallest plausible future item, ~1..12) are heavily penalized,
    // with a superlinear ramp as the gap shrinks toward zero.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 12.0 {
        let dead = (12.0 - pr) / 12.0; // 0..1, worse for tinier gaps
        score += 40.0 * dead * dead;
    }

    // Reward near-perfect fits (waste <= 3) to lock in excellent placements.
    if pr <= 3.0 {
        score -= 25.0;
    } else if pr <= 8.0 {
        score -= 10.0;
    }

    // Open-bins pressure: discourage scattering across many bins;
    // scale penalty with fraction of capacity consumed from the bin.
    let load_frac = item_size as f64 / bin_capacity as f64;
    score += 0.35 * open_bins_count as f64 * load_frac;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward;
    // if it cannot fit, mild penalty (this bin's leftover is likely dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            if (pr - nxt).abs() <= 3.0 {
                score -= 20.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller values (consolidate space into few bins).
    score += 0.10 * (pr - mean_residual);

    // New-bin candidate: make an empty bin attractive only when the current fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count >= 1 && pr <= 15.0 {
            score += 30.0; // push toward new bin only when placement creates real dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but scale by mean residual pressure.
    score -= 0.5 * mean_residual;

    // Aggressive 2-step lookahead: reward bins where the next item fits exactly
    // into the post_residual (perfect chain), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item chain
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.25 * leftover; // next item fits, mild reward, penalize excess leftover
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap; // dead space relative to lookahead item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins are reasonably full/usable.
        score += 15.0 + 60.0 * pressure;
        // Late in the stream, opening new bins is more acceptable (avoid overflow chains).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If next item is large and post_residual of this fresh bin is generous, soften.
        if next_item_size > 0 && post_residual >= next_item_size + 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for opening bins when many are already open (fragmentation control).
    if open_bins_count > 4 && bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer keeping it closed early; allow opening when
    // existing bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) / 8.0;
        let big_item = item_size as f64 / bin_capacity as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score += 35.0 - 20.0 * progress - 6.0 * crowded - 15.0 * big_item - 10.0 * mean_gap;
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight bonus for filling bins more completely as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post residual (dead space fraction)
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * (1.0 + 0.8 * progress) * (1.0 - 0.5 * pr_norm * progress);

    let mut score = pr * (1.0 + 0.3 * progress) + 20.0 * poly * poly;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize last-chance bins lightly unless fit is tight
    if fitting_bins_count == 1 {
        score -= 10.0 * tightness;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr));
    }

    // Discourage opening new bins when good fits exist, more so late in stream
    if bin_residual == bin_capacity {
        score += 12.0 * (0.4 + 0.6 * progress) * (1.0 + open_bins_count as f64 / 20.0);
    }

    // Mild coupling with mean residual: prefer bins near the mean (balance)
    score += 0.05 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 buckets penalize "awkward" residues
    let cls = (post_residual % 10) as f64;
    score += cls * 0.35;

    // Perfect-fit classes: post_residual divisible by 10 or 25 is highly usable
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        score += 15.0; // dead space below min item size
    }

    // Integer-division thresholds on post_residual: which harmonic classes of items fit
    let fits_next = next_item_size > 0 && next_item_size <= post_residual;
    if fits_next {
        // reward bins whose post_residual sits in a class matching next item's class
        let same_class = (next_item_size % 10) == (post_residual % 10);
        let bonus = if same_class { 14.0 } else { 7.0 };
        score -= bonus;
    } else if next_item_size > 0 {
        score += 6.0; // next item won't fit here
    }

    // Last-chance bin: strong penalty for wasting the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is truly bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
        if post_residual >= 20 && post_residual % 10 == 0 {
            score += 10.0; // fresh bin with clean class is acceptable but not preferred
        }
    }

    // Coupling with mean residual: prefer bins tighter than the mean
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for filling bins deeply as stream progresses
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gap too small for typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead space relative to capacity
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Pressure: with many open bins, prefer filling existing bins rather than opening new ones
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if item is large or few fitting bins
        score += 20.0 + 15.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if item_size > 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward last-chance fits
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Lookahead: if next item fits in post_residual, reward
        if next_item_size > 0 && next_item_size <= post_residual {
