        }
        // Penalize if next item would waste this bin's remaining space
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below mean (tighter bins)
    score += 0.1 * (mean_residual - post_residual as f64);

    // Slight preference to fill bins earlier in the stream order (implicit via score baseline)
    score += 0.001 * step_index as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
