        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else if fitting_bins_count > 0 {
        // Mild bonus for using existing bins late.
        score -= 10.0 * progress;
    }

    // Crowding: many open bins -> favor filling existing ones.
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 6.0 * norm_pr * norm_pr * progress;

    // Smooth interaction: post_residual^3 normalized, scaled by progress
    score += 2.0 * (norm_pr * norm_pr * norm_pr) * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize dead space that cannot fit the lookahead item (smooth softplus-like gate)
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += 12.0 * gap * gap / (1.0 + gap);
        // Reward residual that leaves room for the next item
        let fit_next = (pr - nxt).max(0.0) / cap;
        score -= 5.0 * fit_next / (1.0 + fit_next);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty coupling with number of open bins and mean residual divergence
    let mean_gap = (mean_residual - pr).abs() / cap;
    score += 3.0 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make empty bin attractive only when it's genuinely useful
    if bin_residual == bin_capacity {
        let waste = (cap - item) / cap;
        score += 20.0 * waste * waste;
        score -= 10.0 * progress * (1.0 - waste);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse when it cannot
    // accommodate typical small items. Classify via integer division
    // thresholds on post_residual.
    let pr = post_residual;
    let dead_class = pr / 10; // 0..10 harmonic class
    // Small residuals (class 0-2) are near-perfect fits: reward strongly.
    if dead_class <= 2 {
        score -= 30.0 - (dead_class as f64) * 10.0;
    } else if dead_class >= 7 {
        // Large dead space: penalize progressively (wasted capacity).
        score += (dead_class as f64) * 2.5;
    }

    // Exact fill is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= pr {
            // Partial chaining: reward proportional to how well next item uses leftover.
            let fill_frac = next_item_size as f64 / pr as f64;
            score -= 20.0 * fill_frac;
        } else {
            // Next item cannot use this bin's leftover: penalize large unusable remainder.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when no open bin offers a decent fit (mean residual small
    // relative to item) or when the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items or when open bins are too full on average.
        let open_bins_tight = mean_residual < item_size as f64 * 1.2;
        if item_frac > 0.6 || open_bins_tight {
            score -= 25.0;
        } else {
            score += 20.0; // discourage spreading into fresh bins
        }
    }

    // Modulo arithmetic on post_residual: residuals congruent to small values
    // mod common item sizes are more reusable.
    let reusability = (pr % 10 == 0) as i32 as f64
        + (pr % 20 == 0) as i32 as f64
        + (pr % 25 == 0) as i32 as f64;
    score -= 6.0 * reusability;

    // Stream progression: early on, be pickier about tight fits; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (dead_class <= 3) as i32 as f64;
    score += progress * (open_bins_count as f64) * 0.5; // late: discourage bin proliferation

    // Mean residual coupling: bins far below mean residual are "odd ones out";
    // filling them balances the pool.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // for items >= 10, so penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual near zero but not creating tiny gap).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 {
        // Residual large enough to potentially fit another item: mild reward
        // proportional to how much slack remains usable.
        score -= 0.15 * post_residual as f64;
    }

    // Open-bin pressure: prefer using existing bins when many are open,
    // penalize the new-bin candidate proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 2.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space more.
        score += 10.0;
    }

    // Deviation from mean residual: bins with residual close to item_size
    // (small waste) get slight preference.
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * waste;

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer chances to consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the remaining space.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize mismatch, scaled by how "tight" the fit would be.
            score += gap * 0.35;
        }
        // Extra reward if next item fits into post_residual (chain placement possible).
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Dead space that the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    } else {
        // Last item: prefer the fullest bin to avoid opening anything new.
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins below mean residual (already tight) are attractive.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits,
    // or when this bin would otherwise be left with tiny unusable residue.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // Discourage opening a new bin when existing bins can fit,
            // unless the item is huge (poor fit everywhere).
            let waste_penalty = (bin_capacity - item_size) as f64;
            score += 30.0 + waste_penalty * 0.4;
            if item_size >= 70 {
                score -= 45.0; // huge items: a fresh bin is often best
            }
        }
    }

    // Slight preference for filling older bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Mild load balancing: many open bins -> prefer tighter bins more strongly.
    score -= (post_residual as f64) * (open_bins_count as f64).ln().max(0.0) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that nothing can use
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward tight fits relative to bin
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 40.0 * tightness;
    }

    // Last-chance bonus: avoid opening a new bin if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // wasted space for the known next item
            score += 10.0;
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        if pressure > 0.0 {
            score -= 20.0;
        } else {
            score += 150.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Global state: many open bins with high mean residual -> prefer reusing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > item_size as f64 * 2.0 {
        score -= 15.0 * (mean_residual / bin_capacity as f64);
    }

    // Slight preference to fill bins as stream progresses
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: post-residual, mildly convex so small residuals are strongly preferred.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Non-linear coupling: as the stream progresses, tight fits matter more
    // (less opportunity to reuse dead space later).
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * progress * tightness * tightness;

    // Penalize bins far from the mean residual only mildly early, more later.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (2.0 + 8.0 * progress) * dev * dev;

    // Last-chance bonus: strong reward, decaying smoothly with progress.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_gap = pr - nxt;
            score -= 6.0 * (1.0 - (fit_gap / cap).powi(2));
        } else {
            score += 3.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only
    // when open bins are genuinely poor fits; cheaper to open early on.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are dead space.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // integer division threshold classes 0..=8

    // Penalize dead-space classes nonlinearly.
    match class {
        0 => score += 40.0,                      // nearly full: excellent
        1 => score += 10.0,
        2 => score -= 5.0,                       // quarter-ish space still usable
        3 => score += 15.0,                      // awkward 3/8 zone
        4 => score -= 8.0,                       // half bin: very reusable
        5 => score += 12.0,
        6 => score -= 4.0,
        7 => score += 6.0,
        _ => {}                                  // fresh/near-empty bin
    }

    // Reward exact modular fits (post_residual divisible into nice chunks).
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual - next_item_size <= eighth {
            score -= 8.0; // chain fit into near-full bin
        }
    } else if next_item_size > post_residual && post_residual < eighth {
        // next item won't fit and this bin is dead: heavy penalty
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good open bin exists.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            // penalize opening new bins, more so early in the stream
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 30.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild tie-break toward bins below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward last-chance bin usage
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Lookahead: reward bins that can also fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 300.0; // next item fills this bin exactly
            } else if gap <= 10 {
                score -= 60.0;
            } else {
                score -= (20.0 * (gap as f64 / bin_capacity as f64)).min(20.0);
            }
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 30.0 + 0.3 * post_residual as f64;
        }
    }

    // Compare post_residual against the mean residual: prefer bins that end
    // closer to the average (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it costly unless the item is huge and no open bin
    // fits tightly (handled implicitly since open bins get lookahead bonuses).
    if bin_residual == bin_capacity {
        score += 200.0;
        // Allow a fresh bin when the stream is early and item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size as f64 > 0.7 * bin_capacity as f64 && progress < 0.5 {
            score -= 220.0;
        }
    }

    // Mild preference for filling fuller bins (smaller pre-residual).
    score += 0.1 * bin_residual as f64;

    // Slight preference to keep the number of open bins down late in the stream.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual strongly (superlinear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual < smallest plausible item, waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here; mild penalty proportional to overflow.
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins below mean residual (fill emptier bins less, keep balanced? prefer filling fuller bins):
    // reward placing into bins with residual below mean (fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    // Time horizon: early in stream, be conservative about new bins; late, allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Discourage opening new bins early, allow later.
    if bin_residual == bin_capacity {
        let new_bin_bias = 40.0 - 30.0 * progress;
        score += new_bin_bias;
        // If no open bin fits, opening is necessary; the call for a real bin would be absent anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, keep current bins lean.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // Small exploration jitter-free coupling: reward near-exact halving fits.
    if post_residual as i64 - (item_size as i64) == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress2 = progress * progress;
    let progress3 = progress2 * progress;

    // Normalized post-residual and its non-linear couplings
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let pr2 = pr_norm * pr_norm;

    // Polynomial coupling: residual waste penalty grows quadratically with progress,
    // since late in the stream residual space is harder to fill.
    score += pr2 * (0.5 + 3.0 * progress2) * cap;

    // Smooth reward for tight fits, weighted by remaining stream length
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress3;
    }

    // Penalize bins with residual far below the mean (fragmentation pressure)
    let mean_gap = mean_residual - pr;
    score += 0.15 * mean_gap * (0.5 + progress);

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_next = if pr >= ns { 1.0 } else { 0.0 };
        let gap = (pr - ns).abs();
        score -= 8.0 * fit_next * (1.0 - gap / cap);
        score += 4.0 * (1.0 - fit_next) * progress2;
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.3 * open_bins_count as f64 * (1.0 - progress2);

    // Encourage opening a new bin when the item is large relative to capacity
    score -= 5.0 * (item_size as f64 / cap) * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * post_frac * post_frac;

    // Lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Harmonic class: how well next item subdivides the leftover
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next == 0 {
            score -= 20.0; // perfect two-item packing
        } else if leftover_after_next % 10 == 0 {
            score -= 8.0; // clean class remainder
        } else {
            score += 5.0 * (leftover_after_next % 10) as f64 / 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space that next item cannot use
        score += 12.0 * (next_item_size.saturating_sub(post_residual)) as f64 / cap;
    }

    // Harmonic class of post_residual via integer division thresholds
    let class = post_residual / 10;
    score += match class {
        0 => -15.0,               // 0: perfect fit
        1..=2 => -5.0,            // tiny slivers, likely dead
        3..=5 => 3.0,             // mid-range
        6..=9 => 6.0,             // large residual but usable
        _ => 0.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it expensive unless it's genuinely better.
    if bin_residual == bin_capacity {
        score = 55.0 + 10.0 * (item_size as f64 / cap);
        if fitting_bins_count == 0 {
            score = 0.0; // forced open
        } else if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // pair fits nicely in a fresh bin
        }
    }

    // Mild preference to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small but potentially usable gap: mild penalty scaled by tightness
        score += 8.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits (near-perfect packing).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 15.0 * fit_ratio;
    } else if fit_ratio < 0.4 {
        // Dumping a small item into a big bin wastes the bin's potential
        score += 6.0 * (0.4 - fit_ratio);
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and progress,
        // but allow it when current bin fit is poor.
        score += 12.0 + 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        if fit_ratio < 0.5 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits perfectly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        if next_fit > 0.8 {
            score -= 12.0 * next_fit;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't hold next item: dead space risk
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (consolidate space into fewer, emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: exact 2-step lookahead match.
    // If the next item can exactly fill the post residual, heavily reward this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;

        // Perfect chain: post_residual == next_item_size -> strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits snugly (small leftover after both placements).
        if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            score += chain_residual as f64 * 0.3;
            if chain_residual <= 10 {
                score -= 8.0;
            }
        }
        // Next item does NOT fit in this bin after placement: penalize
        // proportionally to how wasteful the leftover is.
        if next_item_size > post_residual {
            score += 6.0;
        }
    } else {
        // Last item: just minimize dead space.
        score += (post_residual as f64 / bin_capacity as f64) * 5.0;
    }

    // Relative-to-mean coupling: a bin with residual well below the mean
    // is "tight" — using it is efficient; a bin far above the mean is loose.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.15;
    } else {
        score += (resid - mean_residual) * 0.10;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when the current item leaves a "usable" chunk and
    // there are many open bins already (avoid bin sprawl early).
    if bin_residual == bin_capacity {
        let sprawl_penalty = open_bins_count as f64 * 1.5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += sprawl_penalty * (1.0 - 0.5 * progress);
        // Empty bin is bad if the item is small (wastes capacity).
        score += (bin_capacity - item_size) as f64 * 0.05;
        // Empty bin is good if item is huge (nearly fills a fresh bin).
        if item_size >= 80 {
            score -= 15.0;
        }
    }

    // Slight preference to fill tighter bins overall.
    score += (bin_residual - item_size) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional to how much of the bin is consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 24.0 * fill_ratio;

    // Penalize small dead space after placement (hard-to-use slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Penalize blocking the next item when the leftover is unusable for it.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large (would leave big useful residual) or no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 25.0;
        // Large items benefit from a fresh bin (perfect fit potential).
        score -= 30.0 * fill_ratio;
        // If several bins fit, discourage opening yet another one.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
        // Early in the stream, accumulating open bins is cheap; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state: when mean residual across open bins is high, prefer bins that
    // consume more of that slack (avoid accumulating many half-empty bins).
    score -= 8.0 * (item_size as f64 / 100.0) * (mean_residual / bin_capacity as f64);

    // Mild pressure to prefer already-open bins as the number of open bins grows.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Penalize creating dead space that next item cannot use.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as u32) < next_item_size {
            let gap = (nx - post_residual as f64) / cap;
            score += 25.0 * gap * (1.0 + progress);
        } else {
            // Smooth reward when leftover can host the next item.
            let usable = 1.0 - ((post_residual as f64 - nx) / cap).abs();
            score -= 10.0 * usable;
        }
    }

    // Non-linear coupling with stream progress: later in the stream,
    // consolidation into existing bins matters more.
    score += 15.0 * (post_residual as f64 / cap) * progress * progress;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly, scaled by how well open bins
    // cluster (mean residual) and stream position.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs() / cap;
        score += 20.0 + 30.0 * (1.0 - progress) - 10.0 * spread;
    }

    // Discourage opening bins when many are open with slack.
    let slack = mean_residual / cap;
    score += 8.0 * slack * slack * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into modulo buckets.
    let pr = post_residual;
    let class = pr % 10; // residual harmonic class
    // Penalize residuals that are "awkward" (small, non-zero classes that few items fit).
    if pr > 0 {
        let awkward = match class {
            0 => 0.0,                       // perfectly divisible residual
            1..=3 => 6.0,                   // nearly-full dead space
            4..=7 => 3.0,                   // moderately awkward
            _ => 1.5,                       // 8/9, still usable by small items
        };
        score += awkward;
    }

    // Reward tight fits: post_residual near zero.
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 12.0;
    } else if pr <= 10 {
        score -= 5.0;
    }

    // Reward residuals that the next item can exactly fill (perfect pairing).
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size {
            // next item still fits: mildly good, reward proportional closeness
            let slack = (pr - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize if we leave a trap
            score += 2.0 + (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Integer-division threshold on post_residual vs capacity fractions.
    let quarter = bin_capacity / 4;
    if pr > quarter && pr < bin_capacity / 2 {
        // mid-range residual: keep bins in this band attractive (classic best-fit zone)
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless
    // the current item fits terribly everywhere or the item is huge.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // A fresh bin is good for large items (they pair well later) or when
        // no other bin fits (fitting_bins_count == 0 among open bins).
        if fill_ratio > 0.7 || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            // Discourage opening new bins for small items when open bins exist.
            score += 20.0 + 10.0 * (1.0 - fill_ratio);
        }
    }

    // Prefer bins below mean residual (denser bins first) slightly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for using fewer open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // Harmonic modulo coupling between item_size and post_residual classes.
    if pr > 0 && (item_size + pr) % bin_capacity == 0 {
        score -= 8.0; // item plus residual exactly a capacity multiple
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 2.0; // quarter-capacity aligned residuals are reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Dead-space penalty: residuals too small for any plausible future item
    // (items are 1..=100, but small gaps < ~10 are nearly unusable).
    if post_residual < 10 {
        score += 500.0 * (10.0 - post_residual as f64);
    }

    // Prefer tight fits: post_residual relative to item size.
    score += 2.0 * (post_residual as f64 / item_size.max(1) as f64);

    // Dead space avoidance: penalize residual in the "awkward zone" that
    // few item sizes can use (e.g. 1..20 gap wastes capacity).
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing bins
    // over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // or mean residual is too small for the item.
        score += 80.0 + 5.0 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 200.0; // an open bin could take it; discourage new bin
        }
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer bins whose post_residual tightly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: next item fits perfectly after this placement.
            let slack_after_next = post_residual - next_item_size;
            score -= 40.0 + 60.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Penalize: next item cannot follow into this bin.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 10.0 + gap * 0.5;
        }
    }

    // Dead-space penalty: very small unusable remainders are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual far below mean are good fits.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Prefer tighter bins overall (smaller residual relative to capacity).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Penalize wasting a bin that could chain-fit both items tightly.
        if bin_residual >= item_size + next_item_size {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer good fits,
    // keep flexibility); late in the stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> prefer filling
    // existing bins over opening new ones.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.3 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize unless open bins are nearly full or item is large.
        let spread = mean_residual - post_residual as f64;
        score += 15.0 + 0.4 * spread;
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for bins with residuals near the item size (perfect wrap).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * (1.0 - progress) * 4.0);

    // Penalize residual that is too small to be useful (dead space), smoothly
    let dead = 1.0 - (x / 0.2).min(1.0);
    score += 30.0 * dead * dead * (1.0 - progress);

    // Reward tight fits mildly
    score -= 10.0 * (1.0 - x) * x;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 - progress);
    }

    // Coupling with mean residual: avoid degrading well-packed bins
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty so it's chosen only when clearly better
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common size buckets) are rewarded.
    let pr = post_residual;
    let harmonic_class = if pr == 0 { 0 } else if pr <= 10 { 1 } else if pr <= 20 { 2 } else if pr <= 30 { 3 } else { 4 };
    score -= match harmonic_class {
        0 => 40.0,               // perfect fit
        1 => 12.0,               // small dead space
        2 => 4.0,
        3 => 0.0,
        _ => -6.0,               // large leftover is still reusable: subtract
    };

    // Modulo-10 bonus: leftovers that are round numbers pair well with
    // typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect follow-up placement
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how much dead space would be stranded
            let overshoot = (next_item_size - pr) as f64;
            score += 3.0 * (overshoot / 80.0).min(1.0);
        }
    } else {
        // Last item: prefer zero residual strongly.
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize so we only open
    // a new bin when existing fits are bad; the penalty decays as the stream
    // progresses and as mean residual across bins grows (fragmentation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = ((mean_residual - 30.0) / 70.0).clamp(0.0, 1.0);
        score += 20.0 - 10.0 * progress - 12.0 * frag;
        // Large items justify opening fresh bins more readily.
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Tightness reward: item filling most of the bin is desirable.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Prefer bins with below-mean residual (compact the fragmented bins first).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap;

    // Integer-division threshold: bins whose residual / item_size quotient is
    // exactly 1 (item takes over half the bin) get a small nudge.
    if bin_residual / item_size.max(1) == 1 {
        score -= 3.0;
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: bonus if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // Residual too small for the lookahead item: mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0) * 1.5;
        } else {
            score -= 8.0;
        }
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when current bin fits are poor.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit {
            score -= 80.0; // open a fresh bin rather than create dead space
        } else {
            score += 25.0; // keep using existing bins when fit is decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match reward: next item fits snugly (small slack after both placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize proportionally to the mismatch.
        score += 8.0 + 0.3 * ((next_item_size - post_residual) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize leaving tiny unusable dead space (<= 10 is hard to fill later).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Favor bins tighter than the mean residual (good fills), penalize loose ones.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, prefer compacting into few bins; later, allow spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);

    // Empty new-bin candidate: penalize so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if nothing else fits well (many bins, large item), soften slightly.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: minimize wasted residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be reused by typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill is excellent
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 18.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here; penalize leaving awkward gap.
            score += 4.0;
        }
    }

    // Compare with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Many open bins: encourage closing bins out (prefer fuller bins).
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * post_residual as f64 * 0.05;

    // Time horizon: later in the stream, be more conservative (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: make it moderately unattractive unless residuals everywhere are bad.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual;
        if avg_waste > 40.0 {
            score -= 10.0; // open bins are all loose; a fresh bin is fine
        } else {
            score += 20.0; // prefer filling existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: late in the stream, be stricter about wasted space
    score += 25.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth interaction: post_residual vs mean residual (avoid fragmenting above-average bins)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space for the next item (smooth quadratic on gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= 12.0 * gap * (1.0 - gap);
        } else {
            score += 6.0 * gap * gap;
        }
    }

    // Mild penalty for opening new bins when many are open (encourage consolidation)
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (8.0 + 12.0 * progress + 0.5 * open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by its
    // divisibility / integer-division structure relative to capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap; // capacity fraction remaining

    // Class 1: post_residual divisible by 10 -> clean harmonic slot.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Class 2: divisible by 5 but not 10 -> still usable.
    else if pr % 5 == 0 {
        score -= 2.5;
    }
    // Class 3: awkward residue classes -> penalize dead space.
    else {
        score += 3.0 + (pr % 5) as f64;
    }

    // Integer-division thresholds on post_residual.
    let q = pr / 25; // quarter-of-capacity classes
    match q {
        0 => score += 8.0,           // nearly full bin: great, reward heavily
        1 => score -= 1.0,           // 25-49 left: usable
        2 => score -= 4.0,           // 50-74 left: good slot
        _ => score -= 6.0,           // 75-100 left: lots of room
    }

    // Coupling with next item: does the lookahead fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact fit classes for the lookahead
            let slack = pr - next_item_size;
            if slack % 10 == 0 && slack != pr {
                score -= 7.0;
            } else if slack < 10 {
                score -= 4.0;
            } else {
                score -= 2.0;
            }
        } else {
            // lookahead cannot fit here: mild penalty unless bin is nearly full
            score += (next_item_size - pr) as f64 * 0.05;
            if pr < 10 {
                score -= 3.0; // sealed bin is fine
            }
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 5.0 + 0.02 * (pr as f64);
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // gives a decent harmonic fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if item is large (>= half capacity), a fresh bin is attractive
        if item_size * 2 >= bin_capacity {
            score -= 25.0;
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // many open bins with high mean residual -> don't open more
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild penalty for spreading residual too far above mean (fragmentation).
    let dev = frac * cap - mean_residual;
    if dev > 20.0 {
        score += (dev - 20.0) * 0.05;
    }

    // Tie-break: prefer bins whose residual is a multiple of item_size
    // (allows exact repeated packing).
    if item_size > 0 && pr % item_size == 0 && pr > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // If the next item would fit exactly in the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalty scaled by lookahead.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins by penalizing existing bins mildly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residual close to the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: neutral-ish baseline so it wins only when existing
    // bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled nonlinearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score += 0.35 * slack_after_next; // penalize leftover slack after next item
            score -= 10.0 / (1.0 + slack_after_next); // modest bonus for close second fit
        } else {
            // next item cannot follow here; penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.15 * overshoot;
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are less flexible.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if item_size >= 50 && post_residual < 20 {
            score -= 30.0 * big_item * (0.5 + progress);
        } else {
            score += 35.0 + 20.0 * (1.0 - progress); // discourage opening bins early
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better, with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space that is too small to hold the next item (or typical items).
    let min_useful = if next_item_size > 0 { next_item_size.min(100) } else { 20 };
    if post_residual > 0 && (post_residual as u64) < (min_useful as u64) {
        score += 12.0 * (min_useful as f64 - post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if next item fits snugly too.
        let post2 = post_residual - next_item_size;
        score -= 3.0 * (1.0 - post2 as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize blocking the next item slightly.
        score += 2.0 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, mild penalty to prefer best-fit elsewhere.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling bins that are already relatively empty of capacity
    // (avoid spreading load across many lightly-filled bins).
    score += 2.0 * ((bin_residual as f64) / (bin_capacity as f64) - (mean_residual / bin_capacity as f64)).abs();

    // Early in stream: be more willing to open new bins (exploration);
    // late in stream: consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins as stream matures,
        // and more when many bins are already open.
        score += 10.0 * progress + 0.4 * open_bins_count as f64;
        // Allow opening new bin early or when fit would be terrible.
        if post_residual < 10 && progress < 0.7 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward consolidation late in the stream.
        score -= 4.0 * progress;
    }

    // Mild penalty proportional to overall open-bin count to encourage packing density.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: later in the stream,
    // dead space becomes more costly, so amplify quadratic post-residual term.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward filling bins deeply (item large relative to capacity).
    score -= 12.0 * norm_item * (1.0 - progress * 0.5);

    // Coupling: post residual vs mean residual — leaving residual near the
    // mean wastes capacity uniformly; penalize deviation upward smoothly.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_after = nx / cap;
            score -= 10.0 * fill_after * (1.0 - (pr - nx) / cap);
        } else {
            // Next item won't fit here; penalize leaving large residual.
            score += 4.0 * norm_pr * (nx / cap);
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate shaping: an empty bin has norm_pr == 1; make it
    // attractive only when progress is high or fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

