    let dead_class = post_residual / 10; // 0..=10 harmonic class
    score += match dead_class {
        0 => -40.0,
        1 => -20.0,
        2 => -5.0,
        3 => 5.0,
        4 => 12.0,
        5 => 18.0,
        6 => 24.0,
        7 => 30.0,
        8 => 36.0,
        9 => 42.0,
        _ => 50.0,
    };

    // Exact fit bonus (modulo arithmetic: residual divides cleanly).
    if post_residual == 0 {
        score -= 60.0;
    }
    if bin_capacity % post_residual.max(1) == 0 && post_residual > 0 {
        score -= 4.0; // divisible residual is more reusable
    }

    // Lookahead coupling: does next item fit in post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, scaled by tightness of the follow-up fit
            let follow_up = (post_residual - next_item_size) as f64;
            score -= 15.0 + 20.0 * (1.0 - follow_up / cap);
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            let overflow = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.3 * overflow;
        }
    } else {
        // last item: prefer any bin, new bin never needed
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // cost of opening a new bin grows with stream progress and open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // but if the item is large relative to capacity, a fresh bin is natural
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Mean residual context: if open bins are already loose, avoid adding to the mess.
    if post_residual as f64 > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post_residual close to zero) more aggressively.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Coupling: penalize tight fits less if the leftover gap can still host
    // the lookahead item (k=2 lookahead awareness).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0;
    }
    // Penalize leaving a gap that neither is zero nor fits the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportional to open bins count
        // and remaining stream length, but relax late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + open_pressure * (1.0 - 0.5 * progress);
    } else {
        // Slight reward for choosing bins that are already fairly full.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild mean-residual coupling: if the fleet average residual is high,
    // discourage adding more dead space beyond that average.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: subtract proportionally to how snugly the next item fits.
            let snug = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // Post-residual is dead space for the next item: penalize waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter,
    // packing there preserves slack in other bins.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.3 * (mean_residual - resid_f);
    } else {
        score += 0.15 * (resid_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, be more willing to keep bins consolidated;
    // late in the stream, allow opening new bins for better fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late.
        score += 120.0 * (1.0 - progress);
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for filling already-open bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - (gap as f64) / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.15 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer fuller bins (smaller residual)
        score += 0.05 * (fitting_bins_count as f64);
    }

    // Prefer bins already below mean residual (balancing waste concentration)
    score += 0.10 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, encourage opening new bins to keep
    // flexibility; late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late
        score += 20.0 * progress;
        // discourage new bin if many open bins already
        score += 0.5 * (open_bins_count as f64);
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild reward for very full bins after placement (waste minimization)
    score -= 0.08 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    let mut score = pr;

    // Smooth polynomial coupling: dead space penalized super-linearly, more so late in stream
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 30.0 * norm_it * (1.0 - norm_it) * (1.0 - progress);

    // Favor bins whose residual after placement matches the next item (lookahead fit)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_term = 1.0 - (norm_pr - nx).abs() * 2.0;
        score -= 25.0 * match_term.max(0.0) * (1.0 - progress);
    } else {
        // Last item: prefer tightest fit
        score += 10.0 * norm_pr;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (tighter bins) with smooth weighting
    score -= 8.0 * ((mean_residual - pr) / cap);

    // Mild preference for keeping number of open bins low early on
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a "friendly"
    // residue class (multiples of 10) are reusable by typical item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that are multiples of 10 (harmonic alignment with capacity)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        // penalize awkward dead space
        score += (post_residual % 10) as f64 * 0.4;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Fractional fill of the bin: prefer high fill ratio
    score -= 8.0 * (1.0 - pr / cap);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
            // harmonic class match between next item and post residual
            if post_residual % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // next item cannot use leftover; penalize small leftovers slightly
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let tight = mean_residual / cap;
        // opening a new bin is penalized unless existing residuals are small
        score += 30.0 * (1.0 - tight) + 2.0 * crowd.min(10.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / cap);

    // Integer-division threshold: post_residual >= half capacity is decent
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness;

    // Pressure from number of open bins: prefer consolidating into fewer bins
    // when many are open; discourage opening new bins when few are open.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless residual would remain useful for
    // upcoming items (lookahead) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow; penalize wasted potential
            score += 10.0;
        }
    }

    // Tight fit reward: minimal post residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize large post residuals relative to mean residual (dead space).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (post_residual as f64 / bin_capacity as f64) - 0.5;
        score += 55.0 - 30.0 * fragmentation.max(0.0);
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with below-average residual (fills fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits
    score -= (1.0 - post / cap) * 40.0;

    // Penalize small dead space that few future items can use
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post).abs() < 1.0 {
            score -= 35.0;
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 8.0;
        }
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, keep residuals flexible
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += t * 6.0 * (post / cap);

    // Many open bins: discourage spreading; few open bins: allow new bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / cap.max(1.0));
    score += pressure * 0.8;

    // New-bin candidate: penalize mildly unless current bin fit is bad
    if bin_residual == bin_capacity {
        let fit_quality = post / cap;
        score += 18.0 - 30.0 * (1.0 - fit_quality);
    }

    // Mean residual coupling: prefer bins below mean residual (larger bins) for big items
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Reward tight fits more strongly as the stream advances
    let tightness = (item_size as f64 / cap) * (1.0 - norm_pr);
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (1.0 - pr / nx);
        } else {
            score -= 6.0 * (nx / cap) * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - norm_pr);
    }

    // Mild pressure to consolidate across many open bins
    score += (open_bins_count as f64).ln1p() * norm_pr * 4.0;

    // Prefer bins with residuals near the mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev / (1.0 + progress);

    // New-bin candidate: keep it attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Reward small post_residual (tight fit), exponentially.
    score -= 40.0 * (-post / 12.0).exp();

    // Harmonic classes: post_residual in "sweet spots" that likely fit small items (10..=30).
    let class = post_residual % 25;
    if class >= 10 && class <= 20 {
        score -= 6.0; // residue class likely reusable by future small items
    } else {
        score += 4.0; // dead-space penalty for awkward residue
    }

    // Integer-division thresholds: post_residual in [10, 30] is highly usable.
    if post_residual / 10 == 1 {
        score -= 8.0;
    } else if post_residual / 10 >= 4 {
        score += 3.0; // large leftover: fine, but not urgent to fill
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-gap / 15.0).exp();
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0; // next item won't chain here
    }

    // Last-chance bonus: only bin that fits -> strong preference to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity unless current
    // bin would leave very poor residue or mean residual is already low.
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity; that's a "fresh" class.
        score = cap - post; // = 0 for the fresh bin itself; base comparison
        // Penalize opening new bins when plenty of open bins still have room.
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if existing bins would leave terrible residue (mean residual small
        // relative to item), opening a fresh bin is attractive.
        let would_be_waste = (bin_residual as f64 - item_size as f64) - mean_residual;
        if would_be_waste < 0.0 {
            score -= 10.0;
        }
        // Early in stream, allow more bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Tie-break: prefer bins whose residual is close to item (best-fit flavor).
    score += 0.1 * ((bin_residual - item_size) as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable dead space: small nonzero gaps that likely can't fit
    // future items (items are 1..100, but tiny gaps are wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0; // moderately awkward gap
    }

    // Reward leaving room for the lookahead item when it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // creates a gap that blocks the next item
    }

    // Open-bins pressure: prefer filling existing bins over opening new ones,
    // scaled by how many bins are already open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && !new_bin {
        score -= 50.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (tighter bins) to keep large residuals available for big items.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f).min(40.0) * 0.5;
    }

    // Early in the stream, be more tolerant of opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

