    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 1.2;

    // Last-chance bin (only fitting bin): strong incentive to use it before opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + mean_residual * 0.5 - progress * 30.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is bigger: keeping item in an existing bin is more valuable.
            score += 40.0;
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize wasted space relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (bin_residual as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= post_residual + 10 {
            // near-miss lookahead: mild penalty for creating awkward remainder
            score += 6.0;
        }
        // If next item is large and this bin's residual is small anyway, slight reward
        if next_item_size > 60 && post_residual < next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin.
        score += 30.0;
        // More expensive to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * (1.0 - progress);
        // If many open bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // If mean residual is large, existing bins have room; discourage new bin.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // If the item is small, it's cheap to place in existing bins.
        if item_size <= 30 {
            score += 10.0;
        }
        // Exception: if this is the last chance and residual can't fit well, allow new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward when it's already open (avoid fragmentation).
        score -= 5.0;
        // Prefer bins whose residual deviates favorably from the mean (use fuller bins).
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    // Dynamic horizon: late in the stream, be more conservative with dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small penalty scaling with number of open bins to encourage consolidation.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * x * x) - 0.8 * pr * (1.0 - x);

    // Smooth coupling with stream progress: penalize waste more later in the stream
    score += 40.0 * progress * x * x * (1.0 - x);

    // Dead-space penalty: residual too small for typical items
    let dead = (10.0 - x * cap).max(0.0) / 10.0;
    score += 25.0 * dead * dead * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let fit = (pr - next_item_size as f64).max(0.0);
        let tight = (next_item_size as f64 / cap).max(0.001);
        score -= 15.0 * (fit / cap) / (1.0 + tight * tight);
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x);
    }

    // Mild penalty when many bins are open relative to stream progress
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * x;

    // Prefer bins tighter than the mean residual (best-fit flavor, smooth)
    let dev = (mean_residual - pr) / cap;
    score -= 10.0 * dev / (1.0 + dev * dev);

    // Slight bias toward new bins when current bin would be left with unusable sliver
    if bin_residual == bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Class 0: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 500.0;
    }
    // Class 1: tiny unusable sliver (<= 10) -> dead space penalty
    else if post_residual <= 10 {
        score += 60.0;
    }
    // Class 2: mid-range leftovers (11..=30) are the classic waste zone
    else if post_residual <= 30 {
        score += 15.0;
    }
    // Class 3: large leftovers are reusable -> mild reward
    else {
        score -= 10.0;
    }

    // Integer-division harmonic classes on post_residual (mod 10 buckets)
    let harmonic_class = post_residual / 10;
    score -= (harmonic_class as f64) * 3.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: excellent chain placement
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + slack * 0.2;
        } else {
            // Next item won't fit here: penalize proportionally to how badly it misses
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.5;
            // But if this is the last chance bin, accept anyway
            if fitting_bins_count == 1 {
                score -= 80.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only open a new bin when current bin would
    // leave a poor harmonic class and the next item is large.
    if bin_residual == bin_capacity {
        let base = 120.0;
        let mut nb = base;
        if post_residual > 0 {
            // opening new bin: prefer it when all open bins would create slivers
            if post_residual <= 10 {
                nb -= 90.0;
            }
            if next_item_size > 0 && next_item_size > post_residual && post_residual <= 30 {
                nb -= 60.0;
            }
            // penalize opening new bins early in the stream
            let progress = step_index as f64 / total_items.max(1) as f64;
            nb += (1.0 - progress) * 40.0;
            // penalize when many bins already open
            nb += open_bins_count as f64 * 2.0;
            // if mean residual is high, reuse bins instead
            if mean_residual > frac * 100.0 + 20.0 {
                nb += 50.0;
            }
        } else {
            nb += 1000.0; // never open a bin for zero residual case
        }
        score += nb;
    }

    // Mild preference for fuller bins relative to mean residual
    score += (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance before opening a new bin: strong incentive to use this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits into the resulting residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item cannot use this residual: mild penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 8.0 * pressure;
    } else {
        // New-bin candidate: penalize opening a bin unless item is large or few bins fit.
        score += 10.0 + 6.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: if this bin is far above mean residual, it is a good filler.
    let dev = (bin_residual as f64) - mean_residual;
    if bin_residual < bin_capacity && dev > 0.0 {
        score -= 0.15 * dev;
    }

    // Early stream: keep bins open and flexible; late stream: tighten aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (-gap / 20.0).exp();
        } else {
            // Next item won't fit here; penalize by the wasted potential.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss.min(40.0);
        }
    }

    // Penalize dead space relative to mean residual: bins deviating below mean are precious.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: make it mildly unattractive unless it's early or the fit
    // into open bins is bad. Empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            // Opening fresh gives a perfect slot for the next big item.
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference to keep many open bins consolidated as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (nonlinear).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.15;
    }

    // Perfect closure bonus: bin becomes exactly full.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves residue: mild reward scaled by how snug
            let nfit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * nfit;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += 5.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0;
        // If many bins fit the item, opening a new bin is rarely worth it.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If no other bin fits well (large mean residual means poor usage), new bin ok.
        if mean_residual < 15.0 {
            score -= 12.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // New bin for a large item leaves a full fresh residual: slight bonus.
        score -= item_size as f64 * 0.05;
    }

    // Prefer bins whose residual is below the mean (consolidate fragmentation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Mild penalty per open bin to encourage consolidation into existing bins.
    score += 0.02 * open_bins_count as f64;

    // Small-item dead-space guard: avoid putting tiny items into huge residuals
    // when a snugger option may exist.
    if item_size < 30 && post_residual > 50 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space becomes more costly as the stream progresses.
    let waste_term = post / cap;
    score += 12.0 * waste_term * waste_term * (0.3 + progress);

    // Reward tight fits with smooth interaction between fill ratio and progress.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 10.0 * fill * fill * (1.0 - progress);

    // Lookahead coupling: bonus if next item fits exactly in the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs() / cap;
        score -= 8.0 * (1.0 - gap) * gap.exp();
        score += 4.0 * (nxt / cap) * (post / cap);
    }

    // Last-chance bonus: penalize opening new bins when few alternatives exist.
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 - progress);
    }

    // Crowd penalty: prefer distributing load across many open bins smoothly.
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += 3.0 * crowding * ((post - mean_residual) / cap).abs();

    // Smooth residual variance coupling.
    score += 2.0 * (post / cap).sin().abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be closed out usefully.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals below the smallest plausible item (1)
    // are fine, but residuals in [1..=10] are awkward dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }

    // Harmonic class reward: residual that is an exact divisor-fraction of
    // capacity (1/2, 1/3, 1/4 of capacity) is reusable by common item sizes.
    let quarter = bin_capacity / 4;
    let third = bin_capacity / 3;
    let half = bin_capacity / 2;
    if post_residual == half || post_residual == third || post_residual == quarter {
        score -= 20.0;
    }

    // Modulo class of post_residual mod 10: multiples of 10 pair well with
    // typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item cannot fit in post residual, this bin leaves the next item
    // to another bin; mild penalty proportional to the gap.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.3 * ((next_item_size - post_residual) as f64).min(40.0);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only prefer it when no open bin fits well.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when other bins fit.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // But favored early in the stream to build a diverse pool.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: reward bins below the mean residual
    // (they are "well used").
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight preference for using existing crowded bins as open bin count grows.
    score += 0.05 * open_bins_count as f64;

    // Small tie-break noise-free nudge toward lower post residual.
    score += 0.1 * (frac * 10.0).fract();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item are "dead". Penalize them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item {
        // exact fit -> reward strongly
        score -= 60.0;
    } else if post_residual <= 10 {
        // tiny gap likely unusable dead space
        score += (12.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits generally
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect-fit lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here; mild penalty proportional to gap waste
        score += (post_residual as f64) * 0.15;
    } else if next_item_size > 0 {
        // next item fits: reward proportional to how well it nests
        score -= (post_residual - next_item_size) as f64 * -0.0; // neutral
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening a new bin (empty candidate) harder.
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bin count
        score += 20.0 + open_bins_count as f64 * 3.0;
        // but if mean residual is small (bins nearly full), new bin is fine
        score -= mean_residual.min(20.0) * 0.8;
    } else {
        // existing bin: slight reward growing with open bin count (consolidation)
        score -= open_bins_count as f64 * 0.5;
    }

    // Stream progression: late in the stream, avoid leaving awkward gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post-residual is better, amplified for very tight fits.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item can fit into post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fill
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            // penalize residual chain waste quadratically
            score += 0.35 * chain_waste * chain_waste / (bin_capacity as f64);
            // reward moderately if next item fits reasonably well
            let chain_fit = 1.0 - chain_waste / (bin_capacity as f64);
            score -= 8.0 * chain_fit;
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving this bin far below mean residual creates a stranded small hole.
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score += 0.6 * (mean_r - post_residual as f64);
    } else {
        score -= 0.2 * ((post_residual as f64) - mean_r);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // competition among bins: prefer the one that wastes least (already captured),
        // small bonus to spread load when many bins fit
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the stream
    // or when the fit would be very poor (large dead space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64) / (bin_capacity as f64) < 0.35;
        if poor_fit && progress < 0.7 {
            score -= 6.0; // allow fresh bin for small items early
        } else {
            score += 15.0; // discourage opening new bins when decent fits exist
        }
    }

    // Mild penalty for very small dead spaces that are hard to reuse (below typical small item size)
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Slight pressure to consolidate bins as stream progresses
    score += 0.05 * (open_bins_count as f64) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: fraction of bin filled by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill * fill;

    // Penalize leaving small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last chance: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty for spreading across many candidate bins
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // Extra reward for near-exact pairing
        if post_residual == next_item_size {
            score -= 120.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here anyway; neutral
        score += 10.0;
    }

    // Global state: if mean residual is high, prefer consolidating into bins with large residuals
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 20.0 * (rel - 1.0);
        } else {
            score += 20.0 * (1.0 - rel);
        }
    }

    // Time horizon: early in the stream, be more open to new bins; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * fill;

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when open bins have poor fits
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0;
        // Late in the stream, opening new bins is cheaper than wasting residual space
        score -= 30.0 * progress;
        // Don't open a new bin if the next item is huge and current item is small
        if next_item_size > 60 && item_size < 30 {
            score += 40.0;
        }
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
