pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is valuable dead-space avoidance.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Harmonic classes: bucket post_residual into residue classes mod 10.
    // Residuals that can host common small items (10, 20, 25) are less "dead".
    let cls = post_residual % 10;
    match cls {
        0 => score -= 8.0,               // exact decade residual, reusable
        5 => score -= 4.0,               // half-decade residual
        _ => score += (10 - cls) as f64 * 0.5, // awkward remainder penalized
    }

    // Penalize residuals that are too small to host the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // dead space relative to lookahead
    }
    // Reward residual that exactly or nearly fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 3 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's only
    // chosen when open bins have genuinely poor fits.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If only one bin fits the item, discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below the mean (tighter bins
    // keep loose bins available for awkward items).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Fraction-of-capacity coupling: bins whose residual is a large fraction of
    // capacity are less attractive unless they're the only option.
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.6 && bin_residual != bin_capacity {
        score += 6.0 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are nearly unusable
    // (min item size is 10 in classic streams; small items may still appear,
    // so we apply a graded penalty rather than a hard wall).
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual > 9 && post_residual <= 20 {
        // Partially usable gap: mild penalty proportional to waste
        score += (post_residual as f64) * 0.35;
    }

    // Reward very tight fits (post_residual small but zero is perfect)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // when the stream is young; allow consolidation later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).powf(1.25) * (1.0 - 0.5 * progress);
    score += bin_pressure * 0.15;

    // If this bin is the last chance to fit the item, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh empty bin when the
    // current item would leave a large awkward gap in every open bin, or
    // when the next item pairs perfectly with the leftover space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0 + 8.0 * (1.0 - progress);

        // Discount the new bin if the lookahead item fits the post_residual
        // exactly (perfect two-item packing from scratch).
        if next_item_size > 0 && post_residual >= next_item_size {
            let pair_waste = post_residual - next_item_size;
            if pair_waste == 0 {
                score -= 45.0;
            } else if pair_waste <= 9 {
                score -= 15.0;
            }
        }
        // If mean residual across open bins is large, opening a new bin is
        // wasteful; penalize more.
        score += mean_residual * 0.10;
    } else {
        // Open-bin placement: reward if the lookahead item fits the gap left
        // behind (keeps the bin on a perfect packing trajectory).
        if next_item_size > 0 && post_residual >= next_item_size {
            let pair_waste = post_residual - next_item_size;
            if pair_waste == 0 {
                score -= 20.0;
            } else if pair_waste <= 9 {
                score -= 6.0;
            }
        }
    }

    // Slight preference for bins whose residual deviates favorably from the mean
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain
        }
        // penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer minimal residual
        score += 0.2 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs()
        } else { 0 };
        let _ = poor_fits;
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && item_size >= 60 {
            score -= 20.0; // big item: fresh bin is fine
        }
    }

    // Late-stream consolidation: fewer open bins preferred
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Penalize dead space: small post_residual is good, but mid-range
    // leftovers (too small for typical items) are especially wasteful.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 8.0; // nearly-full bin: fine, but tiny slivers are dead space
    } else if pr >= 10.0 && pr <= 25.0 {
        score += 15.0 * (1.0 - pr / 25.0); // awkward dead zone
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = post_residual - next_item_size;
        score -= 10.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here afterwards; mild penalty if we leave
        // a large unusable gap relative to the next item.
        score += 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits
    // well (many competing bins means existing bins are probably fine).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0 // no alternative: new bin must win
        } else {
            6.0 + 2.0 * (fitting_bins_count as f64).min(10.0)
        };
        score += pressure;
        // Early in the stream, opening fresh bins is cheaper (more items
        // remain to fill them); late in the stream, consolidate.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - t);
    }

    // Global balance: prefer bins whose residual deviates from the mean
    // in a way that reduces variance (pack into larger-residual bins when
    // mean residual is high, into tighter bins when mean is low).
    let dev = bin_residual as f64 - mean_residual;
    if mean_residual > 40.0 {
        score -= 3.0 * dev / 100.0;
    } else {
        score += 2.0 * dev / 100.0;
    }

    // Mild consolidation pressure as the number of open bins grows.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Late-stream urgency: as we approach the end, avoid leaving many
    // half-empty bins; favor bins that will end nearly full.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * t * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Core: quadratic coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Reward tight fits more strongly as the stream progresses.
    score -= (cap - pr) * norm_item * (0.5 + 1.5 * progress * progress);

    // Penalize dead space: cubic in normalized post residual.
    score += 30.0 * norm_pr * norm_pr * norm_pr * cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack * slack) * (0.3 + 0.7 * progress);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Slight preference for consolidating into fewer bins early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: make it mildly attractive only for large items / late stream.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 10.0 * norm_item * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with small items (1..=10)
    let pr = post_residual;
    let residue = pr % 10;
    // Residues 0 (perfect closure) heavily rewarded; residues 1..3 are "dead" for min-size items
    match residue {
        0 => score -= 12.0 + (pr as f64) * 0.05,
        1 | 2 | 3 => score += 10.0, // unusable dead space even for smallest items
        4 | 5 | 6 => score += 3.0,
        _ => {}
    }

    // Integer-division thresholds: how many minimum items (size 1) fit
    let min_fits = pr / 1;
    let small_fits = pr / 10;
    if small_fits == 0 && pr > 0 {
        score += 8.0; // cannot host even a small item
    }

    // Lookahead coupling: does post_residual exactly accommodate next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match classes
            if pr % next_item_size.max(1) == 0 {
                score -= 9.0;
            } else {
                score -= 4.0;
            }
            // leftover after next item: penalize tiny unusable remainder
            let after2 = pr - next_item_size;
            if after2 > 0 && after2 < 10 {
                score += 6.0;
            }
        } else {
            score += 7.0; // next item cannot use this bin
        }
    } else {
        // last item: prefer tight closure
        score -= pr as f64 * 0.3;
    }

    // Capacity fraction classes of the fill level
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac_class = (fill_frac * 4.0).floor() as i64; // quarters of capacity
    score -= match frac_class {
        3 => 10.0, // >75% full: excellent
        2 => 5.0,
        1 => 0.0,
        _ => 2.0,
    } as f64;

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins would create bad residue
    if bin_residual == bin_capacity {
        score = 30.0 + mean_residual * 0.1 - (open_bins_count as f64) * 0.5;
        // allow new bin if all fitting bins would leave dead residue 1..3
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference to consolidate when many bins are open
    score -= (open_bins_count as f64) * 0.05;

    // Stream progression: tighten packing toward the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small but potentially usable gap: moderate penalty scaled by tightness
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits: post_residual close to zero relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If the next item could use the post-residual exactly, reward leaving it.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item fills this bin perfectly
        } else if gap > 0 && gap < 10 {
            score += 20.0; // next item would leave a dead sliver
        }
    }

    // New-bin candidate handling: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins already open
        // and mean residual is low (existing bins are nearly full).
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        score += 12.0 - 0.15 * mean_r;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
