pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that cannot fit a plausible future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
        score += 8.0 * dead;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by gap.
            score += 6.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: prefer the tightest (already via post_residual), add small
    // tie-break favoring fuller bins overall.
    if fitting_bins_count > 1 {
        score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, consolidate; early, be flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * tight;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the item is huge and would leave awkward space.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.35 * bin_capacity as f64;
        if poor_fit && fitting_bins_count > 0 {
            score += 40.0;
        } else {
            score += 12.0;
        }
        // Late stream: opening new bins is wasteful.
        score += 20.0 * progress;
    }

    // Global state: many open bins -> discourage spreading, favor filling existing.
    score += 0.5 * open_bins_count as f64 * (1.0 - tight);

    // Mean residual coupling: if average residual is small, treasure remaining space more.
    let scarcity = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 10.0 * scarcity * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr;
    // non-linear coupling: dead-space penalty grows as stream progresses
    let dead = norm_pr * norm_pr;
    score += dead * (0.5 + 2.0 * progress);
    // tight fits rewarded, amplified late in the stream
    let tight = (1.0 - norm_pr).max(0.0);
    score -= 1.5 * tight * tight * (0.5 + progress);
    // last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    }
    // lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.6 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 0.4 * (nxt - pr) / cap;
        }
    }
    // mild pressure toward consolidating into fewer bins
    score -= 0.05 * (open_bins_count as f64 / (1.0 + mean_residual / cap));
    // keep new-bin candidate moderately attractive only when residuals are poor
    if bin_residual == bin_capacity {
        score += 0.3 * norm_pr * (1.0 - progress) + 0.2;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fit classes are heavily rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Residuals that are multiples of 10 pair well with the 10..80 granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Dead space: residuals below 10 are nearly unusable -> strong penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Integer-division threshold classes on post_residual.
    let class = post_residual / 20; // 0..5 harmonic class
    score -= (class as f64) * 6.0;

    // Coupling with the lookahead item: reward residuals that exactly fit next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot follow here: mild penalty scaled by leftover size.
            score += 0.15 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on tiny items.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if (item_size as f64) > 0.6 * cap {
            score -= 20.0;
        }
    }

    // Empty new-bin candidate: prefer using open bins unless the item is large
    // relative to typical residuals.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Open a fresh bin for big items when mean residual is tight.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 60.0;
        }
        // Late in the stream, discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Favor bins tighter than the mean (better consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Fractional capacity coupling: reward filling > 70% of capacity.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.7 {
        score -= 15.0 * (fill - 0.7);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny gaps (< 12) are almost unusable later; penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Gaps that can still fit the lookahead item are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // gap too small for next item: mild dead-space penalty
    }

    // Pressure from number of open bins: prefer consolidating when many bins are open,
    // but allow opening a new bin when few are open (empty-bin candidate has large residual,
    // so this subtraction lets it win only when bin count is low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals below the mean (tighter bins fill first).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Mild penalty for the brand-new empty bin candidate so it only wins when
    // open-bin fits are poor (its post_residual is large, plus this offset).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect chain: item then next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item cannot fit anywhere else easily -> keep space for it
        if post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Penalize dead space (small unusable residuals)
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit bonus
    }

    // Compare against mean residual: prefer bins tighter/looser appropriately
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 5.0; // filling a fuller bin keeps many bins usable
    } else {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 5.0; // pairing opportunity in fresh bin
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity as f64 - res) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't chain here; mild penalty proportional to leftover.
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the mean residual (pack tight bins first).
    score -= 3.0 * (mean_residual - post_residual as f64) / (bin_capacity as f64);

    // Time horizon: early in stream, opening new bins is cheap; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 20.0 + 40.0 * progress + 0.5 * open_bins_count as f64;
        // But early on, a fresh bin for a big item can be fine.
        if progress < 0.2 && item_size > 60 {
            score -= 15.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    // Mild penalty for leaving residuals that match common item sizes poorly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 80.0 {
        let gap_to_typical = (pr - (pr / 20.0).round() * 20.0).abs();
        score += 0.1 * gap_to_typical;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * norm_pr);

    // Reward tight fits: small post_residual gets extra discount, stronger late in stream
    let tightness = (1.0 - norm_pr).powi(3);
    let tight_reward = -40.0 * tightness * (0.5 + progress);

    // Penalize dead space that can't fit the next item
    let waste_penalty = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            (nx - pr) * (1.0 + progress)
        } else {
            -0.5 * (pr - nx).min(20.0) as f64 * 0.1
        }
    } else {
        0.0
    };

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    let last_chance = if fitting_bins_count == 1 { -15.0 } else { 0.0 };

    // Mild preference for bins below mean residual (balance across bins)
    let balance = 0.3 * (mean_residual - pr);

    // New-bin candidate: slight penalty so it's only chosen when fits are bad
    let new_bin = if bin_residual == bin_capacity {
        8.0 + 10.0 * progress
    } else {
        0.0
    };

    base + tight_reward + waste_penalty + last_chance + balance + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it falls into
    // "unfillable" residue classes modulo common item sizes (1..100 range).
    let pr = post_residual as i64;
    let mut fillable_bonus = 0.0;
    for m in 1..=100i64 {
        if m == 0 { continue; }
        if pr >= m && pr % m == 0 {
            // post residual is exactly k copies of size m -> likely reusable
            fillable_bonus += 1.0 / (m as f64).sqrt();
        }
    }
    score -= fillable_bonus * 8.0;

    // Penalize small nonzero dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Modulo-10 harmonic banding: residuals that are multiples of 10 align
    // with typical item granularity; reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here regardless; slight penalty for wasting space
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): prefer it only when existing residuals are bad.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64; // low mean residual => poor open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 200.0 * pressure;          // good open bins => new bin expensive
        score -= 150.0 * (1.0 - pressure);  // bad open bins => new bin attractive
        score -= 30.0 * progress;           // late stream: consolidate less, open freely
        if next_item_size > 0 && next_item_size > post_residual && post_residual == bin_capacity {
            // empty bin: next item can be paired later; neutral small bonus
            score -= 10.0;
        }
    }

    // Mild preference for bins tighter than the mean (waste minimization).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Many open bins: encourage closing them out (prefer bins with small residual).
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Penalize residuals that no plausible item (>=1) can use well.
    if post_residual > 0 && post_residual < min_item {
        score += 200.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Coupling with open_bins_count: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Progress-based tightening: later in stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mean residual pressure: if this bin's residual is far below mean, prefer it (consolidate).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual is already the base).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, penalize score proportionally to how well next item fills remainder.
            let chain_waste = post_residual - next_item_size;
            score -= 30.0 - (chain_waste as f64).min(30.0);
        } else {
            // Next item won't fit here: penalize dead space, more so if the gap is small-but-unusable.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 15.0; // frustrating near-miss gap
            } else {
                score += 5.0;
            }
        }
    } else {
        // Last item: prefer filling a bin completely.
        score -= 100.0;
    }

    // Relative to mean residual: prefer using bins with less residual (tighter bins first),
    // keeping large-residual bins flexible.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let base = 80.0;
        let size_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        score += base - size_bonus;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild preference for keeping the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already dominates via base term).

    // Penalize dead space that likely cannot be reused by typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny slivers are fine (near-perfect fill)
    } else if post_residual < 20 {
        score -= 5.0;
    } else {
        // Larger leftovers: penalize proportionally to how unusable they are
        let t = step_index as f64 / (total_items.max(1) as f64);
        let dead_weight = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 40.0 * dead_weight * (0.5 + 0.5 * t);
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * (next_item_size as f64);
        } else {
            // Next item won't fit here; slight penalty if post residual is
            // large enough to be tempting but useless for the next item.
            if post_residual > 20 {
                score += 6.0;
            }
        }
    } else {
        // Last item: maximize fill, ignore future reuse.
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 55.0;
        // More attractive to open a new bin when many bins are open with
        // fragmented residuals (high mean residual spread).
        if mean_residual > 40.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * t;
        // If item is large relative to residual of typical open bins, new bin ok.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Mild preference for bins with below-average residual (keeps big gaps free).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * (0.5 + 0.5 * progress);

    let mut score = pr + 12.0 * poly * cap;

    // Reward tight fits with smooth squared coupling
    let tight = fill * fill;
    score -= 18.0 * tight * cap * (0.6 + 0.4 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 10.0 + 0.5 * gap * (1.0 - progress);
    }

    // Reward when bin can also serve the next item (smooth interaction)
    if next_item_size > 0 && post_residual as u32 >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.05 * (open_bins_count as f64) * (1.0 - fill);

    // New-bin candidate: keep it neutral-to-slightly-high unless residuals are tight
    if bin_residual == bin_capacity {
        let scarcity = (mean_residual / cap).clamp(0.0, 1.0);
        score += 15.0 - 20.0 * scarcity * scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into decile residue classes.
    let rclass = (post_residual % 10) as f64;
    score -= 3.0 * (rclass / 10.0); // slight reward for round-number residuals (reusable slots)

    // Integer-division thresholds on post_residual: dead space if too small for min item (1..100, assume ~10 typical)
    if post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect / near-perfect fit reward via capacity fraction
    let frac = post_residual as f64 / cap;
    if frac < 0.02 {
        score -= 60.0; // exact fit
    } else if frac < 0.1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 80.0;
        } else if gap < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap / cap);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; residual becomes dead-ish
        score += 8.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Progress-aware pressure to close bins early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * mean_residual * (1.0 - progress) / cap;

    // New-bin candidate handling: make it attractive only when open-bin fits are bad.
    if bin_residual == bin_capacity {
        // neutral baseline: mid-range score, beats bins with big penalties, loses to decent fits
        score = 45.0 + 10.0 * (1.0 - item_size as f64 / cap);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < item_size.min(30) {
            // gap too small for typical future items relative to item size
            score += 25.0 * (1.0 - post_residual as f64 / 30.0);
        }
    } else {
        // perfect fill is excellent
        score -= 40.0;
    }

    // Reward tight fits (waste ratio).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // next item can't use this bin anyway; slight penalty for hoarding space
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones.
    score += 0.8 * open_bins_count as f64;

    // New empty bin candidate: make it attractive only when the fit would be
    // near-perfect, otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fit_ratio;
        score += 8.0; // base reluctance to open new bins
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    // Late in the stream, squeeze harder into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // Prefer bins whose residual is below mean (tighter bins get filled).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 200.0 - (slack as f64) * 10.0;
        }
    }

    // Dead space: post_residual too small for the next item (or any plausible item).
    let min_item = 1u32;
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 150.0;
    }
    if post_residual > 0 && post_residual < min_item {
        score += 100.0;
    }

    // Reward packing into tight (nearly full) bins relative to mean residual.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Penalize bins far above mean residual (wasteful bins) mildly.
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New empty bin candidate: make it unattractive unless it offers a perfect
    // lookahead combo or no open bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let perfect = next_item_size > 0 && item_size + next_item_size == bin_capacity;
        if !perfect {
            score += 250.0;
        }
        // If few fitting bins exist and this bin is a last resort, allow it.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Early in the stream, allow opening bins more freely to build good partials.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness: strongly reward small post_residual (non-linearly).
    let post = post_residual as f64;
    score += (post * post) / (bin_capacity as f64 * 4.0);

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 + (bin_capacity as f64 - slack_after_next as f64) * 0.05;
            // chain fit quality
            if slack_after_next == 0 { score -= 20.0; }
        } else {
            // dead space the next item can't use; penalize proportionally
            let dead = next_item_size - post_residual;
            score += dead as f64 * 0.6;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive if this bin's fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 40.0;
        // More open bins -> opening new bins fragments state; penalize more.
        score += open_bins_count as f64 * 2.0;
        // Early in stream, opening bins is cheaper (more items to fill them with).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 25.0;
        // If mean residual across open bins is small (poor overall fit landscape),
        // a fresh bin becomes more attractive.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
        // If next item is large and no open bin likely fits it, fresh bin helps.
        if next_item_size > post_residual.max(item_size) && next_item_size > 50 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, especially those below mean residual (tighter bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Small preference for filling larger-residual bins when many bins are open,
    // to consolidate load.
    score += (bin_residual as f64) * 0.05 * (open_bins_count as f64).min(10.0) / 10.0;

    // Time-horizon scaling: late in stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= post * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear penalty on wasted residual, amplified as stream progresses.
    let waste = norm_post * norm_post;
    score += 60.0 * waste * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual relative to item).
    score -= 25.0 * (norm_item / (norm_item + norm_post + 0.05)) * (1.0 - progress);

    // Dead-space coupling: penalize residuals too small for likely next item.
    if next_item_size > 0 {
        let fits_next = if post >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = ((next_item_size as f64 - post).max(0.0)) / cap;
        score += 30.0 * (1.0 - fits_next) * gap * gap;
        score -= 10.0 * fits_next * norm_next * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure from many open bins: prefer filling existing ones.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // Smooth new-bin discouragement: empty candidate gets a progress-dependent surcharge.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress * progress) + 8.0 * (mean_residual / cap);
    }

    // Interaction: large item into small residual is risky.
    score += 15.0 * norm_item * norm_post * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead zones"
    let residue = post_residual % 10;
    score += match residue {
        0 => -20.0,                    // perfectly reusable residual
        1..=4 => (4 - residue) as f64, // near-aligned, mild reward
        _ => (residue - 4) as f64 * 2.0, // awkward dead space, penalize
    };

    // Integer-division thresholds on post_residual (capacity fractions)
    if post_residual <= bin_capacity / 10 {
        score -= 15.0; // bin nearly full, excellent
    } else if post_residual <= bin_capacity / 4 {
        score -= 5.0;
    } else if post_residual > bin_capacity / 2 {
        score += 8.0; // wasteful placement leaving > half empty
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // penalize if post residual is a "trap": just below next item
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score += gap as f64 * 1.5;
            }
        }
    } else {
        // last item: minimize leftover only
        score = post_residual as f64;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless it's a genuinely better deal
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bin only if existing bins are crowded or late in stream
        let crowd = (mean_residual / cap).min(1.0);
        score = cap * 0.9 + crowd * 20.0 - progress * 10.0 + open_bins_count as f64 * 0.5;
        if item_size >= 60 {
            score -= 10.0; // big items pair better in fresh bins
        }
    }

    // Coupling: mean residual pressure
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below ~10) are heavily penalized,
    // with penalty ramping as the gap shrinks toward being completely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fill gets a strong reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into existing bins
    // rather than spreading items out.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: reward exact fit for the next item in the remaining gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Gap too small for the next item: mildly penalize unless gap is tiny/dead anyway.
        if post_residual >= 10 {
            score += 4.0;
        }
    }

    // Last-chance bin (only open bin that can fit this item): strongly prefer using it
    // over opening a new bin, since rejecting it forces bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base aversion to opening a new bin when existing bins could fit.
        score += 35.0;
        if fitting_bins_count >= 1 {
            score += 45.0; // some open bin fits: new bin is almost never preferable
        }
        // If this new bin is the only option AND the lookahead item is large enough
        // that the post gap would be reusable, allow opening it more readily.
        if fitting_bins_count == 1 {
            if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
                score -= 20.0;
            }
            // If the alternative bin would leave a dead gap, opening fresh is fine.
            if post_residual > 0 && post_residual < 10 {
                score -= 15.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Reward if next item leaves a good residual after it too.
            let pr2 = post_residual - next_item_size;
            score -= 100.0 - (pr2 as f64 * 0.5);
        } else {
            // Next item won't fit here after this placement: penalize mildly.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: avoid making bin far worse than average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's a very tight option
    // (e.g., item large enough that a fresh bin yields a small residual later).
    if bin_residual == bin_capacity {
        score += 250.0;
        // Encourage opening a new bin only for large items late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size >= 70 && progress > 0.5 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (< 10 is dead space for any item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large and
        // existing bins would leave big dead space, or when open bins are very full on average.
        let avg_fullness = bin_capacity as f64 - mean_residual;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (item_size as f64 / bin_capacity as f64) * 0.5
            + (avg_fullness / bin_capacity as f64) * 0.3
            + time_frac * 0.2;
        // Base penalty for opening a new bin, reduced by pressure.
        score += 45.0 - 40.0 * pressure.min(1.0);
    } else {
        // Slight preference to keep many bins balanced vs. piling on one bin.
        let balance = (bin_residual as f64 - mean_residual).abs();
        score += 0.5 * balance;
    }

    // Mild global packing pressure: more open bins -> prefer filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 30.0 * norm_pr * norm_pr * norm_pr;

    // Smooth progress coupling: penalize waste more late in the stream
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 20.0 * progress * norm_pr;
    score -= 15.0 * progress_coupling * norm_pr * (1.0 - norm_pr);

    // Tight fit reward: near-zero post residual strongly favored
    let tightness = (1.0 - norm_pr).powi(2);
    score -= 25.0 * tightness * (1.0 - progress);

    // Lookahead: penalize if post residual cannot fit next item (smooth)
    if next_item_size > 0 {
        let next_fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 12.0 * (1.0 - next_fits) * (1.0 - gap.powf(0.5));
        score -= 10.0 * next_fits * (pr - next_item_size as f64) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - progress * 0.5);
    }

    // Mean residual context: prefer bins near mean waste (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: keep neutral-ish, penalize slightly unless residuals are tiny
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
        if mean_residual < 15.0 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes
    let pr = post_residual;
    let class = (pr / 10) as f64; // integer division thresholds

    // Penalize unusable dead space: post_residual smaller than min item is pure waste
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // reward small (but usable) residual mildly
        score -= 0.5 * class;
    }

    // Modulo-10 harmonic alignment: item size divisible by 10 packs better with
    // residuals that are multiples of 10
    if item_size % 10 == 0 && bin_residual % 10 == 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // extra reward if next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space that the next item cannot use
        score += 0.3 * (post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            // other bins can fit; new bin only attractive for large items with no good fit
            let fit_quality = (bin_residual - item_size) as f64;
            if fit_quality < 15.0 {
                score -= 40.0;
            }
        }
    }

    // Prefer bins with low residual relative to mean (fill nearly-full bins first)
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Early stream: encourage packing density; late stream: prefer closing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Mid-range dead space (10..25) is mildly penalized since few item sizes fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 6.0;
    }

    // Reward very tight fits (post_residual == 0 is a perfect fill).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin if existing residuals are poor.
    if bin_residual == bin_capacity {
        // New bin is penalized by current congestion and by how much usable space
        // existing bins already have; it wins only when fits are scattered/fragmented.
        score += 25.0 + mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is mandatory
        }
    } else {
        // Existing bin: reward using bins whose residual is close to item size.
        let tightness = (bin_residual - item_size) as f64;
        score -= (bin_capacity as f64 - tightness) * 0.05;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
        score -= 20.0;
    }
    // Penalize if post residual is just barely too small for the next item (dead zone).
    if next_item_size > post_residual as u32 && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // Stream progression: later in the stream, be slightly more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: if the next item fits exactly into the post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize leaving post_residual that no plausible item (>=1) can use well:
    // dead space smaller than the smallest possible next item is wasted unless 0.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e. fuller bins) so we consolidate.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when the stream is early
    // and open bins exist; encourage it late when consolidation is done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * (1.0 - progress);
        score += open_bins_count as f64 * 2.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in the stream, be conservative; later, exploit tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead reward: if the leftover space exactly accommodates the next item,
    // this placement is highly desirable (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0 + 30.0 * progress;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: potential dead space.
            let waste = post_residual as f64;
            score += 0.5 * waste * (1.0 - progress);
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins below mean residual (fill the emptiest useful bins).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Penalize creating small unusable slivers (< 10, the min item size historically).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (many competing bins) or the item is large and fits would leave big waste.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 {
            -100.0 // no alternative: new bin is fine
        } else if fitting_bins_count == 1 {
            -10.0 // weak alternative
        } else {
            60.0 + 10.0 * open_bins_count as f64 // prefer existing bins
        };
        score += penalty;
        // Late in stream with many open bins, avoid spawning extra bins.
        score += 30.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = post / cap;

    // Smooth fit-quality term: reward tight fits via quadratic trough at 0.
    let fit_quality = -8.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - 0.5 * fit_norm);

    // Dead-space penalty grows non-linearly with residual, stronger late in stream.
    let dead_space = (fit_norm * fit_norm) * (10.0 + 15.0 * progress);

    // Lookahead coupling: reward if post_residual can host next item, penalize near-miss.
    let look = if next_item_size > 0 {
        let n = next_item_size as f64;
        let ratio = post / n.max(1.0);
        if ratio >= 1.0 { -3.0 * (1.0 - (1.0 / ratio)) } else { 4.0 * (1.0 - ratio) * (1.0 - ratio) }
    } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity { -12.0 } else { 0.0 };

    // New-bin candidate: penalize opening a new bin unless stream is early or open bins are crowded.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        6.0 + 14.0 * crowd * (0.4 + 0.6 * progress)
    } else { 0.0 };

    // Mean-residual divergence: bins far from mean residual get slight penalty (prefer homogeneous fill).
    let div = ((post - mean_residual) / cap).abs();
    let homog = 3.0 * div * div * (1.0 + progress);

    let mut score = post + fit_quality + dead_space + look + last_chance + new_bin_penalty + homog;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows non-linearly for small unusable gaps.
        let pr = post_residual as f64;
        score += 40.0 / pr; // small residual => big penalty added
        // Harmonic class: bins whose residual is "usable" for common sizes get a bonus.
        let usable = (10..=80).step_by(10).any(|s| s <= post_residual);
        if usable {
            score -= 8.0;
        } else {
            score += 12.0; // dead space nobody can fill
        }
        // Modulo-class logic: residual in a favorable residue class (multiples of 10) fits integer items better.
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // Perfect fit of next item into post_residual: strong reward (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Next item still fits after this placement: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward remainder.
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when current bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases late in stream when future items are many.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 15.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        score += 5.0 * fitting_bins_count as f64;
        // If no bins fit (fitting_bins_count==0 case only happens for new bin), it's forced; that's fine.
    }

    // Prefer filling bins with large residuals relative to mean (balance avoidance of many half-empty bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev; // prefer below-average residual bins (tighter bins)
    }

    // Slight preference for high bin utilization early (keep few open bins).
    let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * utilization;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 40.0;
    } else {
        // Larger gaps are less wasteful per unit; mild superlinear decay.
        score -= 0.15 * (post_residual as f64).sqrt();
    }

    // Dead space is worse if the lookahead item can't use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && next_item_size >= post_residual.saturating_sub(10) {
        // Gap is perfectly sized for the next item.
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += 0.4 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline neutral score; penalize slightly when good fits exist,
        // reward when this is the only option or mean residual is very low.
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 20.0 + 0.5 * mean_residual;
        }
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    // Mean residual coupling: if open bins are generally full, avoid wasting
    // their last space; if they are loose, prefer using them.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is already favored by the base term,
    // but give a non-linear bonus when the bin is filled nearly exactly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fill is extremely desirable
    } else if post_residual as f64 <= 0.05 * bin_capacity as f64 {
        score -= 15.0;
    } else {
        // Penalize creating awkward dead space (small unusable slivers)
        if post_residual < 10 {
            score += 12.0 * (1.0 - fill_ratio);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 25.0 * fit_quality;
        } else {
            score -= 8.0 * fit_quality;
        }
    }

    // Lookahead: avoid blocking the next item. If the next item would no longer
    // fit after this placement (and it's not a perfect fill), penalize.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // next item can't use the leftover -> dead space penalty, scaled by sliver size
            score += 6.0 + 0.5 * post_residual as f64;
        }
        // If placing here leaves room exactly for next item, that's a great chain
        if post_residual == next_item_size {
            score -= 18.0;
        }
        // If placing here still leaves room for next item comfortably, mild reward
        if post_residual >= next_item_size * 2 {
            score -= 3.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residual space is fragmented or the stream is early.
    if bin_residual == bin_capacity {
        // Fragmentation pressure: many open bins with high mean residual suggests
        // poor packing so far -> allow new bins more readily early on.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let openness = (1.0 - progress).clamp(0.0, 1.0);
        // Base cost of a new bin (waste of a fresh 100 capacity)
        score += 30.0;
        // But discount new bins when fragmentation is high or stream is early
        score -= 20.0 * fragmentation * openness;
        // If no existing bin fits well, new bin becomes relatively better:
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        if progress > 0.7 {
            score += 15.0 * progress;
        }
    }

    // Mild penalty for spreading across too many bins when few fit
    if fitting_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0; // slight preference to use existing crowded bins
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    // to keep large residuals available for large future items.
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (waste minimization)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post residual); Late: tolerate larger residuals less.
    let prn = pr / cap; // normalized post residual in [0,1]
    let coupling = 1.0 + 2.0 * progress * progress;
    score += coupling * prn * prn * cap * 0.5;

    // Smooth reward for near-perfect fit: post_residual close to 0 gets strong discount
    let tight = (1.0 - prn).powi(3);
    score -= 12.0 * tight;

    // Penalize residuals that cannot fit the lookahead item (dead space), smooth polynomial
    if next_item_size > 0 && (next_item_size as f64) > pr {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * (1.0 + progress);
    } else if next_item_size > 0 {
        // reward bins that can still host the next item, scaled by fit quality
        let fit_q = pr / (next_item_size as f64 + 1.0);
        score -= 4.0 * (fit_q / (1.0 + fit_q));
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 - prn);
    }

    // Mild penalty when bin residual is far below mean residual (fragmented bin)
    let dev = (mean_residual - pr) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline so it's only chosen when open bins score poorly
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class logic: classify post_residual by capacity fraction classes
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty grows super-linearly for small residuals (wasted slivers)
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    } else if post_residual > 5 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo arithmetic on post_residual: residuals that are "harmonically aligned"
    // with capacity (multiples of 8 or 16) are more reusable later.
    let align8 = post_residual % 8 == 0;
    let align16 = post_residual % 16 == 0;
    if align16 && post_residual > 0 {
        score -= 12.0;
    } else if align8 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Lookahead: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic threshold classes on slack
            if slack as u32 <= eighth {
                score -= 60.0;
            } else if slack as u32 <= quarter {
                score -= 25.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; residual must be harvested later
            score += pr / cap_f * 20.0;
        }
    }

    // Integer-division threshold on residual: big residuals are flexible
    let big_residual = post_residual / 2 >= item_size.max(1);
    if big_residual {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 150.0;
        // worth it if fitting bins are scarce or residuals are fragmented
        if fitting_bins_count == 0 {
            score -= 400.0;
        } else if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // early in stream, prefer consolidating; late, allow spreading
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += (1.0 - progress) * 30.0;
        // penalize new bin if mean residual across open bins is large (waste)
        score += (mean_residual / cap_f).max(0.0) * 50.0;
    }

    // Mild penalty for very large post_residual when many bins are open (fragmentation)
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful are heavily penalized.
    // Anything below ~10 is nearly guaranteed waste; 10..20 is risky.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver
    } else if post_residual < 20 {
        score += 18.0; // risky small gap
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward tight fits proportionally (fill ratio of the placement).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Dead-space avoidance coupled with lookahead: if the next item fits
    // exactly into the post residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: penalize more if gap is tiny.
        score += 10.0 + (10.0 - post_residual as f64).max(0.0);
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but encourage consolidating into bins when only few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if this is a last-chance fit
        // elsewhere failing, or the item is large and would leave a bad gap.
        let would_waste = post_residual > 0 && post_residual < 20;
        if fitting_bins_count > 0 && !would_waste {
            score += 30.0; // prefer an existing fitting bin
        } else if fitting_bins_count == 0 {
            score -= 15.0; // no alternative: new bin is fine
        }
        // Late in the stream, be more conservative about opening bins.
        score += 10.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild mean-residual coupling: prefer bins with residual near the mean
    // (keeps bin states balanced), slight deviation penalty.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward exact match of post_residual with next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0;
        }
        // penalize dead space too small for the next item
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // small residuals are wasteful; big residuals are fine
        score += (post_residual as f64).powf(1.3) * 0.05;
    }

    // relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // new-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        score = if poor_fit { 50.0 } else { 100000.0 };
        // opening new bin is good if next item pairs with a fresh bin
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // early stream: be slightly conservative about opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are dead space (too small for typical items,
    // yet not zero): dead space is residual in (0, 10).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Moderately usable leftover: mild reward.
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: good chaining.
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: slight penalty proportional to how much we "wasted" the chain.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity (it would fragment any open bin)
    // or when all open bins are nearly full (mean residual low).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows over the stream (encourage consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0 + 25.0 * progress;

        // If item is huge, a fresh bin is natural.
        if item_size > bin_capacity * 3 / 4 {
            new_bin_score -= 30.0;
        }
        // If mean residual across open bins can't comfortably host the item, new bin is fine.
        if (mean_residual as u32) < item_size + 5 {
            new_bin_score -= 20.0;
        }
        // If next item is large too, a fresh bin keeps room.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_score += 15.0;
        }
        // Few open bins and lots of stream left -> cheaper to open.
        if open_bins_count <= 2 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score + post_residual as f64 * 0.5;
    }

    // Slight preference for using bins with larger residuals when all else equal
    // (keeps small bins tight for small items).
    score -= 0.02 * bin_residual as f64;

    // Mild global pressure: many open bins -> favor packing into existing ones.
    if bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base fit quality: prefer tight fits via quadratic coupling with normalized residual
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (1.0 + progress);

    // Non-linear interaction: residual gap relative to mean residual across open bins
    let gap = post - mean_residual;
    score += 0.35 * gap + 0.012 * gap * gap;

    // Lookahead coupling: reward residuals that leave room for the next item,
    // penalize residuals that are uselessly large or awkwardly just-too-small
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let diff = post - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (diff / cap) * (1.0 - (diff / cap));
        } else {
            score += 6.0 + 0.05 * (-diff);
        }
    }

    // Stream-progress polynomial: late in the stream, tighten bins more aggressively
    score += 8.0 * progress * progress * (post / cap) * 10.0;

    // Last-chance bin: strongly reward using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless the fit is truly bad elsewhere
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty for bin fragmentation (many open bins with large residuals)
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: tiny unusable residuals (harmonic class 1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of residual: coarser classes slightly penalized
    // (residual / 10 gives class index; larger leftover classes are worse)
    let cls = (post_residual / 10) as f64;
    score += cls * 2.0;

    // Lookahead coupling: if the next item fits into the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty for fragmenting
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer existing bins unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no open bin can fit the item (this new bin is the only option), make it attractive
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // Late in the stream, opening a new bin is less costly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer filling fuller bins: subtract based on used capacity
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Mild global pressure: many open bins with high mean residual -> consolidate
    score += mean_residual * 0.05;
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small positive gaps (1..=15) are likely unusable.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16 - post_residual) as f64;
    } else if post_residual > 15 && post_residual <= 35 {
        // Medium dead space: mild penalty proportional to waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize mildly, scaled by how many bins already fit
    // the item and by open bin pressure, so new bins open only to escape dead space.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 45.0 + 8.0 * (fit_pressure - 1.0) + 0.3 * open_bins_count as f64;
        // But if this item would leave a big usable chunk in a new bin while all
        // existing fits create tiny dead gaps, the base comparison already handles it.
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
