    }

    // 2-step lookahead: reward when post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild bonus proportional to slack quality
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space creation
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual against mean residual of open bins
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 100.0; // nothing fits next item anywhere, new bin useful
        } else {
            score += 150.0;
        }
    }

    // Late stream: prefer tight packing of existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * post_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny useless sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening new bins when open bins fit well,
    // encourage when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Opening a new bin is attractive when existing residuals are large & unusable,
        // but unattractive early in the stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - fragmentation) - 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual < next_item_size {
            score -= 10.0; // fresh bin helps chain large items
        }
    }

    // Global state coupling: with many open bins, favor consolidating into bins
    // whose residual is near the mean (keeps residuals uniform).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Time horizon: late in the stream, be more conservative (avoid waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;
    // non-linear polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 + 3.0 * progress) - fit_norm * (1.0 - progress);
    let mut score = pr * (1.0 + poly);
    // penalize last-chance bins less strongly when post residual is small
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - fit_norm) * (1.0 - progress);
    }
    // lookahead: reward leaving space that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }
    // mild pressure toward consolidating into existing bins
    score += 0.05 * open_bins_count as f64 * fit_norm;
    score += 0.3 * (fit_norm - mean_residual / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "wasted" the leftover is
    // relative to typical item granularity. Classify post_residual into
    // dead-space bands via integer division thresholds.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < eighth {
        // Tiny unusable sliver: penalize heavily (dead space).
        score += 25.0;
    } else if post_residual <= quarter {
        // Small but potentially usable remainder: mild reward for tight fit.
        score -= 8.0;
    } else if post_residual < bin_capacity / 2 {
        // Mid leftover: neutral-ish, slight penalty.
        score += 5.0;
    }

    // Coupling with lookahead: if the next item fits the post residual,
    // reward leaving exactly that much room.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leftover that the next item cannot use.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity / 2 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize opening a new bin when open bins
    // exist and could fit the item reasonably well.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && item_size <= bin_capacity / 2 {
            score += 45.0 + 2.0 * open_bins_count as f64;
        } else if open_bins_count == 0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a "tight" way.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be greedier about packing tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin_residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open bins pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let gap = (mean_residual - item_size as f64).max(0.0);
        score += 30.0 - gap * 0.5;
        // Early in stream, opening bins is cheaper; later, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * -10.0 + progress * 15.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + diff);
        // Perfect chain: next item fills bin exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Two-item chain: item + next item fill bin exactly
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 15.0;
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.4 * (pr - mean_residual);
    }

    // Small residual waste penalty (non-linear): tiny leftovers are hard to use.
    if pr > 0 {
        score += 30.0 / pr;
    } else {
        score -= 10.0; // perfect fill
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if current item is large
        // (large items fit anywhere, so opening fresh bins is cheap).
        let mut new_bin_cost = 20.0;
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 8.0;
        }
        // Early in stream, opening bins is safer (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost *= 1.0 - 0.3 * progress;
        score += new_bin_cost;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post residual (tight fit).
    let mut score = post_residual as f64;

    // Progress ratio in [0,1].
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward high fill non-linearly: strongly favor bins that become nearly full.
    score -= 40.0 * fill * fill;

    // Lookahead: if the next item cannot fit into the post residual, the leftover
    // is likely dead space; penalize proportionally to how far off it is.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(bin_capacity as f64);
        } else {
            // Reward leaving exactly enough room for the next item (perfect chaining).
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.4 * slack.min(30.0);
        }
    } else {
        // Last item: only tightness matters, extra reward for using leftover space.
        score -= 10.0 * fill;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible, handled by post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when this
    // item would leave a very poor fit everywhere (large post_residual relative
    // to capacity) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: it has full residual, so post_residual is
        // large; add a mild penalty that decays as the stream progresses (early on,
        // opening bins is fine; late, prefer packing into existing bins).
        score += 15.0 * (1.0 - progress);
        // If many bins already fit the item, discourage opening another.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count.min(5) as f64);
        }
        // If the item is large relative to a fresh bin's usable space and the
        // average open residual is small, a new bin is reasonable.
        if (item_size as f64) > mean_residual + 0.5 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Small penalty for proliferating bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    // Tie-breaker: prefer bins whose residual is close to the mean (balanced use),
    // slightly favoring below-mean residuals to keep large holes available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Small bonus for placing larger items earlier (big items are harder to place).
    score -= 0.05 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize wasted residual more as stream progresses
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Dead-space penalty: residual too small for lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let dead = (nxt - pr).max(0.0);
        if dead > 0.0 {
            // unusable gap; penalize smoothly, stronger later in stream
            score += dead * (1.0 + progress) * (1.0 - (pr / nxt).min(1.0));
        }
    }

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * item_size as f64 * 0.5;

    // Last-chance bin: strongly reward using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // New-bin candidate: neutral baseline, mildly discouraged early, encouraged when
    // open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        score = cap * 0.5;
        score -= open_bins_count as f64 * 0.5;
        score += mean_residual * 0.3;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0; // fragmentation suggests fresh bin is useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted after placement

    // Penalize residuals in "dead zones": small unusable leftovers (< smallest item ~10)
    if post_residual < 10 {
        score += 60.0; // perfectly full bin is fine actually — reward instead
        score -= 120.0;
    } else if post_residual <= 20 {
        score += 8.0; // small dead space
    }

    // Reward tight fits: post_residual close to a harmonic divisor class (25, 33, 50)
    for h in [25u32, 33, 50, 100] {
        let d = (post_residual as i64 - h as i64).abs() as f64;
        if d < 6.0 {
            score -= 10.0; // residual near a harmonic class is reusable by common items
        }
    }

    // Modulo-10 structure: residuals divisible by 10 pair well with decimal item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; penalize small leftovers more strongly
        score += (10.0 - frac * 10.0).max(0.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets baseline; discourage opening new bins
    // unless current fit is very poor (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // baseline neutral score; slightly above decent fits
        score = cap * 0.55 + mean_residual * 0.2;
        // late in the stream, opening new bins is more acceptable if mean residual is low
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Congestion: many open bins with high mean residual -> prefer filling existing ones
    if open_bins_count > 4 && mean_residual > cap * 0.4 && bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual below the minimum item size (1) can never occur, but
    // gaps too small for typical items are dead space. Penalize gaps that
    // cannot accommodate the lookahead item either.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && post_residual < next_item_size {
            3.0
        } else if post_residual < 10 {
            1.5
        } else {
            0.0
        };
        score += dead * (post_residual as f64);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving exactly room for the next item (chained fit)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open bins pressure: penalize using bins when many are open,
    // favoring consolidation into fewer bins.
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // fits poorly everywhere else (high post_residual elsewhere) or when
    // open-bin residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - score.abs()).abs();
        score -= 5.0;
        // Prefer new bin late in the stream when mean residual is low (bins nearly full)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 2.0;
        // If mean residual is small, open bins are nearly full -> new bin is good
        score += mean_residual * 0.1;
        let _ = fragmentation;
    }

    // Slight preference for tight fits relative to bin capacity
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/next-item matching of post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward tight fits for the next item, decaying with gap.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit in the leftover; penalize by shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 15.0 * (shortfall / bin_capacity as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 10.0;
    }

    // Compare post_residual relative to mean residual: avoid wasteful bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 8.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 8.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty for very tight fits that create dead space (< 10 leftover)
    // unless the next item can use it (already rewarded above).
    if pr > 0.0 && pr < 10.0 {
        score += 12.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Early in stream: be slightly conservative, prefer new bins less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount when progress is high.
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be very wasteful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_residual - item_size) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 + waste * 0.8 - crowded * 2.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (exactness reward).
    let gap = (bin_residual - item_size) as f64;
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual, smoothly warped: tight fits strongly preferred.
    let norm_pr = pr / cap;
    let tightness = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Dead-space penalty: residuals too small for likely future items are costly.
    // Smooth coupling of post_residual with lookahead item size.
    let lookahead = next_item_size as f64;
    let waste = if lookahead > 0.0 {
        let gap = (lookahead - pr).max(0.0) / cap;
        gap * gap * 50.0
    } else {
        0.0
    };

    // Perfect-fill reward (smooth exponential decay of residual).
    let fill_bonus = -30.0 * (-pr / 10.0).exp();

    // New-bin candidate handling: opening a new bin wastes existing residual space.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    let new_bin_penalty = if is_new_bin {
        // Early in stream, prefer reusing; late, more willing to open.
        let reuse_value = mean_residual * 0.3 + (open_bins_count as f64) * 2.0;
        40.0 + reuse_value * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    let last_chance = if fitting_bins_count == 1 && !is_new_bin { -15.0 } else { 0.0 };

    // Crowd penalty: many open bins with large mean residual -> encourage consolidation.
    let consolidation = if !is_new_bin {
        ((mean_residual - pr).max(0.0) / cap) * 5.0
    } else {
        0.0
    };

    // Smooth progress-coupled urgency: late in stream, tighten more aggressively.
    let urgency = tightness * (1.0 + progress * 2.0);

    let mut score = pr + urgency * 10.0 + waste + new_bin_penalty + consolidation + fill_bonus + last_chance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction bands. Leftovers in the "tiny" band are near-dead
    // space and should be penalized heavily; mid-band leftovers are usable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes at C/8)
    let class = post_residual / (bin_capacity / 8).max(1); // 0..=8
    match class {
        0 => score += 30.0,               // dead space: 0..12
        1 => score += 12.0,               // 12..25
        2 => score += 2.0,                // 25..37
        3 => score -= 4.0,                // 37..50 sweet spot
        4 => score -= 6.0,                // ~half full residual
        5 => score -= 3.0,
        6 => score += 1.0,
        7 => score += 4.0,
        _ => {}                           // nearly empty bin, fine
    }

    // Modular arithmetic on post_residual: leftovers that are exact multiples
    // of common item sizes (10, 20, 25, 50) are "reusable" classes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // how snugly the next item fits this leftover
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if post_residual == next_item_size { score -= 6.0; } // perfect follow-up
        } else {
            score += 6.0; // leftover can't host the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if this bin is empty-ish
    // and the stream is early, or current bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post as f64).abs();
        score += 20.0
            - 18.0 * (1.0 - progress)                       // cheap to open early
            - 0.6 * open_bins_count as f64                   // too many open bins
            + 0.15 * fragmentation;                          // penalize fragmented state
        if next_item_size > 0 && bin_capacity as u32 >= item_size + next_item_size {
            score -= 10.0; // fresh bin can host a nice pair
        }
    } else {
        // Mild preference for tighter existing bins (small residual before placement)
        score += 0.05 * (bin_residual as f64) - 0.05 * (mean_residual);
    }

    // Exact-fill reward
    if post_residual == 0 { score -= 25.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to be
    // useful are heavily penalized. A gap is "dead" if it cannot hold even the
    // smallest plausible follow-up item (or the known next item).
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 30 };
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 * (min_useful - post_residual) as f64;
    }

    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fits that leave a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if next item can no longer fit in this bin but fit elsewhere before.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Reward large residual bins being filled (consolidate fullness).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than opening new bins.
    score += 2.0 * open_bins_count as f64;

    // Mean-residual coupling: if the fleet of open bins is already slack,
    // penalize adding more slack to an already loose bin.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // unattractive unless the current fit is truly terrible (large dead space).
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if placing here would waste most of a partially-filled bin,
        // the fresh bin becomes relatively attractive.
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 70.0;
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // tight fits since fewer future opportunities remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 40.0 * (1.0 - diff as f64 / (bin_capacity as f64)).powi(8);
        // Next item fits with some slack but still tight (post < next*1.5)
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 15.0;
        }
        // Penalize leaving post_residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Penalize post_residual that is small and unlikely usable (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward filling bins tighter than the current mean residual
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when no tight lookahead match exists
    if bin_residual == bin_capacity {
        let has_tight = next_item_size > 0 && post_residual == next_item_size;
        if !has_tight {
            score += 18.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference to keep fewer open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for zero waste.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits relative to capacity (non-linear).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space quadratically (unusable slivers).
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead = if pr < 10.0 { (10.0 - pr) * 8.0 } else { 0.0 };
        score += dead;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses leftover
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * nxt_fill * nxt_fill;
        } else {
            // next item won't fit here: penalize leaving large residuals that lure bad fits
            score += 25.0;
        }
    } else {
        // Last item: prefer filling existing bins over opening new ones.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins exist with decent mean residual and few fitting options.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 120.0 + 15.0 * open_f.sqrt() + 100.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity {
            // next item needs a fresh bin anyway; soften penalty
            new_bin_penalty *= 0.3;
        }
        if mean_residual > item_size as f64 + next_item_size as f64 {
            // open bins could likely accommodate both; keep penalty high
            new_bin_penalty += 60.0;
        }
        score += new_bin_penalty;
    } else {
        // Slight preference for bins whose residual is below the mean (consolidate waste).
        let diff = mean_residual - bin_residual as f64;
        score -= 10.0 * (diff / bin_capacity as f64);
    }

    // Mild scaling of everything by stream position: early on, be conservative
    // (favor tight fits more); late, just close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: quadratic penalty on wasted space, slightly softened by progress
    // (later in the stream, tight fills matter more, so weight grows).
    let mut score = post * post / cap * (0.5 + 1.5 * progress) + post;

    // Reward perfect/near-perfect fits super-linearly.
    if post == 0 {
        score -= 60.0 + 40.0 * progress;
    }

    // Penalize residuals that are unusable relative to the lookahead item:
    // if next item cannot fit here, residual is dead space.
    if next > 0.0 && post < next {
        let deadness = (next - post) / cap;
        score += 30.0 * deadness * deadness * cap + 10.0 * progress;
    } else if next > 0.0 && post >= next {
        // Reward leaving exactly enough room for the next item (chaining).
        let tightness = 1.0 - (post - next) / cap;
        score -= 8.0 * tightness * tightness;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        score += 0.15 * post as f64;
    }

    // Mildly discourage scattering across many bins when this bin is roomy.
    score += (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Deviation from mean residual: prefer bins whose fill differs from average
    // (keeps a diversity of residual sizes for future items).
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate (empty bin): neutral-ish baseline so it wins only
    // when all open bins give bad fits.
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + 0.05 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect, reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic classes of post_residual: small dead space classes are bad
    // (wasted), large residuals are reusable. Use integer division thresholds.
    let pr = post_residual;
    if pr < 10 {
        // tiny sliver: dead space penalty scaled by class
        score += 40.0 * (11 - pr) as f64;
    } else if pr < 25 {
        // awkward class: can only fit small future items
        score += 10.0;
    } else if pr < 50 {
        // half-bin class: moderately useful
        score -= 5.0;
    } else {
        // large residual: very reusable
        score -= 15.0;
    }

    // Modulo-10 harmony: residual divisible by 10 pairs with common item sizes.
    if pr % 10 == 0 {
        score -= 8.0;
    }
    // Residual matching a "harmonic" fraction of capacity (25/50/75)
    if pr == 25 || pr == 50 || pr == 75 {
        score -= 10.0;
    }

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainable: reward proportionally to tightness of the chain
            let tight = (pr - next_item_size) as f64;
            score -= 20.0 - tight * 0.3;
        } else {
            // next item won't fit here: mild penalty, worse if we're the only fitting bin
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if mean residual is tiny and stream is early, opening fresh is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && progress < 0.7 {
            score -= 35.0;
        }
    }

    // Prefer bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in stream: consolidate, avoid sprawl.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10).
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Reward near-perfect fits (post_residual close to 0 but usable).
        score -= 25.0 * (1.0 - post_residual as f64 / 40.0).max(0.0);
    }

    // Reward perfect closure of the bin.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally to wasted space.
        score += 15.0;
    }

    // Open-bins pressure: penalize selecting bins when many are open (encourage consolidation).
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference to fill tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // New-bin candidate: make it attractive only when current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        let bad_gap = if post_residual < 10 { 40.0 } else { 0.0 };
        score += 30.0 - bad_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * residual_frac * residual_frac;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item fill
        } else if next_item_size < post_residual {
            let next_leftover = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * (1.0 - next_leftover);
            score += 5.0 * next_leftover;
        } else {
            // next item won't fit here: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Relative to mean residual: bins with residual below mean are scarcer; prefer
    // filling them tightly, penalize wasting them on loose fits.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.05 * open_bins_count as f64 * residual_frac;

    // Early stream: slightly prefer opening fresh bins to keep flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if this is a big item leaving large dead
        // space everywhere else, or stream is early
        score -= 3.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 5.0; // next item is large; a fresh bin helps
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small but nonzero.
    if post_residual > 0 {
        score += (post_residual as f64).powf(0.35) * 2.0;
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward filling bins nearly full (post_residual small relative to capacity).
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 8.0;

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item nearly fills the remaining space.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else {
            // Penalize leaving space the next item can't use.
            let waste = (post_residual as f64).min(next_item_size as f64);
            score += waste * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for bins with fewer alternatives (scarcer fits).
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // New-bin candidate logic: opening a new bin wastes potential of existing space.
    if bin_residual == bin_capacity {
        let avg_open_fill = (bin_capacity as f64) - mean_residual.max(0.0);
        // Favor new bin only when existing bins are quite full on average and
        // the item is small relative to capacity.
        let openness = mean_residual / (bin_capacity as f64);
        if openness > 0.25 && (item_size as f64) / (bin_capacity as f64) < 0.5 {
            score += 40.0;
        } else {
            score += 10.0 + avg_open_fill * 0.1;
        }
    }

    // Prefer bins whose residual is close to the item size (best-fit shaping).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.3;

    // Mild preference toward bins with larger residuals when many bins are open
    // (consolidate space usage, reduce bin count pressure).
    if open_bins_count > 3 {
        score -= (bin_residual as f64) * 0.05 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Time horizon: early in stream, be more exploratory (favor tight fits less,
    // keep flexibility); later, pack aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score *= 1.0 - 0.15 * progress;

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let coupling = pr * (1.0 + 2.0 * progress * (1.0 - progress));

    let mut score = coupling - 60.0 * poly * (0.5 + progress);

    // Reward tight fits, more aggressively as stream progresses
    let tightness = (item_size as f64) / cap;
    score -= 30.0 * tightness * tightness * (0.4 + progress);

    // Penalize last-chance bins slightly less when post_residual is small
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (1.0 - (nx - pr).abs() / cap);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Penalize deviating far from mean residual (waste balance)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: smooth sigmoidal gate based on progress and residual
    let gate = 1.0 / (1.0 + (-(8.0 * (pr_norm - 0.5))).exp());
    score += 10.0 * gate * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residuals divisible by 10 are
    // "clean" slots that future items (10..80 grid) can fill exactly.
    let pr_mod = post_residual % 10;
    if pr_mod == 0 {
        score -= 12.0;
    } else {
        score += 3.0 * pr_mod as f64;
    }

    // Harmonic class of next_item_size: if the lookahead item exactly fills
    // the post residual, this is a perfect pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // lookahead cannot use this residual: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
        // integer-division harmonic: next item divides post_residual cleanly
        if post_residual > 0 && next_item_size % (post_residual.max(1)) == 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if post_residual > 0 && next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // or late in the stream with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5;
        if poor_fit || (progress > 0.8 && open_bins_count == 0) {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Penalize tiny dead space that nothing (>=1) can ever use.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins below the mean residual (tight fits).
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Early stream: be greedy about consolidation; late stream: keep bins tidy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize residuals that are too small to be
    // usable by typical future items (min item size 1, but practically small gaps).
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space penalty grows super-linearly as gap shrinks below ~15
        if gap < 15.0 {
            score += (15.0 - gap) * (15.0 - gap) * 0.8;
        }
        // Perfect fit: strong reward
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin residual (fill fraction of the gap being used)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (avoid opening new bins / spreading items); with few open bins, be lenient.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 6.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if next
    // item is larger than post residual but this bin is not the only option,
    // slight penalty for wasting a bin that could serve next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Encourage opening a new bin only when existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        let new_bin_post = bin_capacity - item_size;
        if new_bin_post > 0 && (new_bin_post as f64) < 15.0 {
            score += (15.0 - new_bin_post as f64).powi(2) * 0.8;
        }
        // Slight inherent cost to opening a new bin when others are open
        if open_bins_count > 0 {
            score += 10.0 + pressure * 4.0;
        }
    }

    // Mean residual coupling: when mean residual across open bins is low (bins nearly
    // full), prefer consolidating into this bin even more.
    score -= (mean_residual / bin_capacity as f64) * 5.0;

    // Stream progression: late in the stream, be more conservative about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && (post_residual as f64) < 15.0 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 90.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it matches.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_ratio;
        } else {
            // Next item cannot fit here: penalize leaving a gap the next item misses.
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (1.0 - (gap / bin_capacity as f64).min(1.0));
        }
    }

    // Relative to mean residual: prefer bins that are already committed (below-mean residual)
    // so large empty bins stay available for future big items.
    if (post_residual as f64) > mean_residual {
        score += 20.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    } else {
        score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit (already via post_residual), slight bonus.
        score -= 5.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good fit exists,
    // i.e., when all residuals are large relative to the item.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin grows with how many bins are already open.
        score = (bin_capacity as f64) + 25.0 * (open_bins_count as f64).sqrt();
        // If this bin is the only fitting option (or fits are scarce), opening is justified.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer closing out existing bins over opening new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Mild preference to fill bins more completely as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual to punish wasted space harder.
    score += (post_residual as f64) * (post_residual as f64) / cap * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + item_size as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 15.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 25.0; }
        } else {
            // Next item won't fit here; penalize leaving fragmented space.
            score += 6.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        let open_fits_good = fitting_bins_count > 0
            && (mean_residual - item_size as f64).abs() < 20.0;
        if open_fits_good {
            score += 60.0; // discourage new bin
        } else {
            // Favor new bin late in stream or when open bins are fragmented.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 10.0 * progress;
        }
    }

    // Global state coupling: penalize spreading across many open bins when
    // mean residual is high (fragmentation), reward consolidation.
    if open_bins_count > 1 {
        score += (mean_residual / cap) * (open_bins_count as f64).ln() * 3.0;
    }

    // Mild time-horizon scaling: early in stream, be more selective (higher score
    // variance); later, prioritize just filling anything.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: penalize wasted post-residual, with smooth non-linear growth.
    let mut score = post + 0.35 * (post * post) / cap;

    // Tightness reward: smooth quadratic coupling of fill ratio.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 + progress);

    // Near-exact fit bonus: smooth bump around post_residual ~ 0.
    score -= 8.0 * (-post / 12.0).exp();

    // Dead-space penalty: residuals too small for typical items are worthless.
    let dead = (12.0 - post).max(0.0);
    score += 0.5 * dead * dead / 12.0;

    // Stream progress: early on, be flexible; later, consolidate aggressively.
    score += 3.0 * (1.0 - progress) * post / cap * 10.0;
    score += 5.0 * progress * (post / cap);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits the post-residual exactly, reward it.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= 4.0 * (-diff / 10.0).exp();
        // Penalize leaving a residual that just barely misses next item.
        let miss = (next_item_size as f64 - post).max(0.0);
        score += 0.15 * miss.min(20.0);
    }

    // New-bin candidate: mildly penalize opening new bins unless residual is very tight.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 10.0 + 4.0 * (1.0 - progress) - 0.05 * open_bins_count as f64;
        // But allow new bin when item nearly fills a fresh bin.
        score -= 6.0 * (-post / 8.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    score += (pr / cap).powi(3) * 40.0;

    // Harmonic thresholds: post_residual in (0,10] is excellent (near-perfect fill).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    }

    // Modulo arithmetic classes on post_residual: small residue classes relative
    // to common item sizes hint at future fit potential.
    let fit_next = next_item_size > 0 && next_item_size <= post_residual;
    if fit_next {
        // Lookahead: if the next item fits exactly in the leftover, big reward.
        let gap = post_residual - next_item_size;
        score -= if gap == 0 { 60.0 } else { 30.0 - (gap.min(30) as f64) };
    } else if next_item_size > 0 {
        // Penalize leaving space the known next item cannot use.
        score += (next_item_size as f64 - pr).max(0.0) * 0.3;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (fragmented state) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 35.0 - 10.0 * progress;
        if open_bins_count > 8 {
            open_cost -= 5.0;
        }
        // If this is the only fitting option, new bin is fine.
        if fitting_bins_count == 0 {
            open_cost -= 40.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 {
            open_cost -= 8.0;
        }
        score += open_cost;
    }

    // Last-chance bin: strongly favor using it to avoid waste.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins already below mean residual (filling emptier bins first
    // keeps larger residuals available).
    score += (pr - mean_residual) * 0.15;

    // Harmonic-class penalty: dead space in awkward class 40..60 is worst
    // since most items (10..80) partially fit but waste remains.
    if post_residual > 40 && post_residual < 60 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it's too small for typical future items (below ~20% capacity).
    let dead_threshold = (bin_capacity as f64 * 0.2) as u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward tight fits relative to the item size (fill ratio of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when needed.
        score += 30.0;
        // But if the current item is large and would leave a big residual in any
        // existing bin, opening fresh is more acceptable.
        score -= fill_ratio * 15.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the next item could exactly use the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 15.0;
        }
    }
    // If next item would NOT fit in the post residual, mild penalty for fragmenting.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual).min(dead_threshold) as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the mean (avoid extreme fragmentation outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward close matches to next item (tight lookahead fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / (bin_capacity as f64 * 0.5)).max(0.0);
    } else if next_item_size > 0 {
        // Penalize overshooting past the next item (dead space vs lookahead)
        let miss = (next_item_size - post_residual) as f64;
        score += 0.35 * miss;
    }

    // Penalize small post residuals that are hard to reuse (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last fitting bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is hopeless
    if bin_residual == bin_capacity {
        score += 55.0;
        // Still allow new bin if lookahead would be wasted here
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 45.0;
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize large dead space, scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * (100.0 + 150.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // If next item would leave this bin awkwardly unusable, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Prefer filling bins when many are open (bin consolidation pressure).
    score -= open_bins_count.min(20) as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large and no good fit exists; otherwise discourage it.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || item_size >= 70 {
            score -= 30.0;
        } else {
            score += 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with non-linear (quartic) coupling
    let mut score = post + 12.0 * post_norm * post_norm * post_norm * post_norm * cap;

    // Reward tight fits (high fill fraction) via smooth polynomial interaction
    let fill = fit_ratio * (1.0 - post_norm);
    score -= 25.0 * fill * fill * (1.0 + progress);

    // Penalize bins that leave residual too small to be useful later
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste = (post - next).max(0.0) / cap;
        score += 8.0 * waste * waste;
        // Bonus if post residual exactly accommodates lookahead item
        if post >= next {
            score -= 6.0 * (1.0 - (post - next) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening bins, more so early when bins are few
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 + 10.0 * (1.0 - progress) + 5.0 * pressure.sqrt();
    }

    // Mild preference for bins below mean residual (balance load smoothly)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residues that are hard to fill later are penalized.
    let pr = post_residual as f64;
    let phase = pr % 20.0;
    score += 0.35 * (phase - 10.0).abs(); // dead-space classes near multiples of 20 hurt

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: reward leaving exactly or at least enough space for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr - nx).abs() < 0.5 {
            score -= 45.0; // post_residual == next_item_size is ideal
        } else if pr >= nx {
            score -= 8.0; // still reusable by lookahead
        } else {
            score += 12.0 + 0.5 * (nx - pr); // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit would be poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = if bin_residual > item_size { (bin_residual - item_size) as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        // Penalize new bin when some open bin would leave less dead space.
        score += 40.0 * pressure + 1.2 * mean_fit;
        // Allow new bin when all fits would leave tiny unusable gaps (10..20) or nothing fits well.
        if fitting_bins_count == 0 {
            score -= 90.0;
        } else if mean_fit < 6.0 {
            score -= 25.0;
        }
        // Late in stream, discourage hoarding new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        let _ = cap;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    if !is_new_bin && mean_residual > 40.0 {
        score += 0.2 * (mean_residual - 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Gaps that are too small for typical items are "dead": penalize them super-linearly.
    // Treat post_residual below a small threshold as wasted space.
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr < dead_threshold {
        // The smaller the leftover, the worse (it can likely never be reused).
        score += (dead_threshold - pr) * 6.0;
        // Perfect fit (zero waste) gets a strong bonus.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Penalize creating a gap that cannot fit the lookahead item when it could have fit otherwise.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 5.0 + 0.1 * next_item_size as f64;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // --- Open bins count pressure ---
    // When many bins are open, discourage opening a new bin (candidate empty bin has
    // bin_residual == bin_capacity) and encourage consolidation into existing bins.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 10.0 + ob * 4.0;
        // But if this bin is the only fitting option, opening a new bin is necessary;
        // relieve the penalty so we do not force a terrible fit.
        if fitting_bins_count == 0 {
            score -= 8.0 + ob * 3.5;
        }
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 2.0 + ob * 0.5;
        // Last-chance bin: strongly prefer filling it rather than leaving it behind.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    }

    // --- Fit quality coupling ---
    // Tightness of fit: reward small post_residual relative to item size (efficient packing).
    let isz = item_size as f64;
    if isz > 0.0 {
        let tightness = pr / isz;
        score += tightness * 3.0;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor, non-linear).
    let gap = (bin_residual as f64 - isz).abs();
    score += (gap * gap) / (bin_capacity as f64);

    // --- Stream progression ---
    // Late in the stream, be more conservative: avoid opening bins, fill existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    } else {
        score -= progress * 5.0;
    }

    // Mean residual context: if this bin is far below mean residual, it is a good filler target.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step fill
        } else if next_item_size <= post_residual {
            score -= 10.0; // lookahead item still fits here
        } else {
            score += 15.0; // next item won't fit after this placement
        }
    }

    // Prefer bins whose residual is below mean (tight bins get used first)
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize tiny dead space that can never be used (waste)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // fresh bin can host current + next item
        } else {
            score += 30.0; // discourage opening bins when fits exist
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
