        } else if next_item_size as u32 <= post_residual {
            // penalize leaving residual that next item only partially uses
            let waste = post_residual as f64 - nxt;
            score += 0.3 * waste;
        }
        // if next item cannot fit here anyway, mild preference for using this bin now
        if next_item_size as u32 > post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // late in stream, prefer closing out open bins
        score += 20.0 + 30.0 * progress;
        if item_size as f64 > 0.8 * cap {
            score -= 15.0; // big item fits cleanly in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Prefer bins with residual below mean (tighter bins first).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Mild penalty for very many open bins to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth quartic penalty on wasted space, weighted by stream progress
    let mut score = post.powi(2) / cap * (1.0 + 2.0 * progress);

    // Non-linear coupling: small post-residuals are valuable late in the stream
    let tightness = (-norm_post * 4.0).exp();
    score -= 12.0 * tightness * (0.5 + progress);

    // Lookahead synergy: reward post_residual that can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0) / cap;
        let synergy = (1.0 - fits_next).max(0.0);
        score -= 6.0 * synergy * synergy;
    } else {
        score -= 8.0; // last item: just fill bins
    }

    // Scarcity bonus: if this is nearly the only fitting bin, strongly favor it
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild dispersion penalty: prefer bins deviating below mean residual
    score += 0.05 * (mean_residual - post).max(0.0);

    // New-bin candidate handling: empty bin should only win when fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 + 25.0 * progress - 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors
    // classify "usable" leftover sizes. Leftovers divisible by 10 or 20
    // are more likely to be reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr % 20 == 0 {
        score -= 18.0;
    } else if pr % 10 == 0 {
        score -= 10.0;
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else if pr < 10 {
        score += 25.0; // tiny dead space: unusable fragment
    }

    // Integer-division threshold classes on post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr > half {
        score -= 6.0; // plenty of room left, bin stays flexible
    } else if pr > quarter {
        score += 2.0;
    } else {
        score += 8.0; // approaching saturation but may strand space
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 22.0; // chain placement enabled
            // Harmonic bonus: next item exactly consumes a residue class
            let rem = pr % next_item_size.max(1);
            if rem == 0 {
                score -= 12.0;
            } else if rem <= 5 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += (next_item_size - pr) as f64 * 0.35;
        }
        // modulo-class match between next item and post residual
        if pr >= next_item_size && (pr % 10) == (next_item_size % 10) {
            score -= 6.0;
        }
    } else {
        // last item: only waste matters
        score -= 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual < 10 && post_residual > 0 {
            score += 20.0; // but avoid stranding a fragment
        }
    } else if fitting_bins_count > 2 {
        score += 4.0; // many alternatives: less urgency, keep spread
    }

    // New-bin candidate handling: neutral-ish baseline so it wins only
    // when every open bin would create bad residue classes.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 3.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming: fresh bin is fine
        }
        if mean_residual > 40.0 {
            score += 15.0; // open bins already have room; don't proliferate
        }
        if step_index + 1 == total_items {
            score = 200.0; // never open a bin for the final item
        }
    }

    // Stream progression: late in the stream, tighten up and avoid
    // opening extra capacity; reward reusing nearly-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    // Deviation from mean residual: prefer bins that are either very
    // full (small residual) or harmonically aligned with mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Small tie-breaking jitter-free deterministic coupling
    score += ((item_size % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    }

    // Penalize mid-range dead space that likely can't fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward filling bins that are the last chance for this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // New empty bin: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let waste_here = post_residual as f64;
        let best_existing_waste = mean_residual - item_size as f64;
        if waste_here > best_existing_waste + 15.0 {
            // Opening a new bin wastes more space than existing bins -> penalize.
            score += 40.0 + waste_here;
        } else {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residuals already below average
    // (target the fullest bins first, classic best-fit behavior).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement is ideal (chains two items into one bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more dead space afterward: mild reward scaled
            // by how little slack remains after the hypothetical second placement.
            let second_post = post_residual - next_item_size;
            score -= 400.0 - second_post as f64 * 2.0;
        } else {
            // Next item does NOT fit after this placement: penalize leaving a residual
            // that is too small to be useful (dead space trap), scaled by how close
            // the miss is (near-miss is worse than far-miss).
            let miss = next_item_size - post_residual;
            score += miss as f64 * 1.5;
        }
    }

    // Compare post_residual against mean residual: leaving residuals far below the
    // mean creates fragmented outliers; leaving residuals well above mean keeps
    // flexibility. Mild coupling.
    let mean_diff = post_residual as f64 - mean_residual;
    score += mean_diff * 0.15;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity or many bins are open (load balancing late in stream).
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        // Base penalty for new bin, reduced when item is large or stream is late.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 120.0 - item_frac * 100.0 - early * 40.0 - pressure * 200.0;
        // If next item is huge and current bin is new, opening may still be fine.
        if next_item_size > 60 && item_size > 60 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins in general (small residual before placement = fuller bin).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (best-fit baseline sharpened).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical items (wasted slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            score += 5.0; // bin becomes useless for the known next item
        }
        // If this bin is the only one that can take the next item too, protect it.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.05 * (open_bins_count as f64);
    }

    // Many open bins: prefer consolidating into already-open bins over spreading.
    score += 0.03 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Global residual pressure: if mean residual is high, tolerate looser fits
    // to drain existing bins; if mean residual is low, be picky.
    let mean_gap = (post_residual as f64) - mean_residual;
    score += 0.10 * mean_gap;

    // Time horizon: early in the stream be conservative (keep bins flexible),
    // late in the stream accept tight fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 8.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (fresh bin gets a neutral-but-not-winning baseline).
    if bin_residual == bin_capacity {
        score = 45.0 + 0.5 * (open_bins_count as f64) - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // room to pair current and next item in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, moderate waste is tolerable; late, waste is heavily penalized.
    let progress_coupling = pr * pr / cap * (0.5 + 1.5 * progress * progress);
    score += 0.9 * progress_coupling;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = (cap - pr) / cap;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if the next item fits in the post-residual, reward leaving it here;
    // otherwise penalize residual that is large but too small for the next item.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / cap);
        } else {
            let dead = pr / cap;
            score += 4.0 * dead * (1.0 - dead);
        }
    }

    // New empty bin candidate: penalize mildly early, more when good alternatives exist.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins with residuals near the mean (balanced packing).
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 and integer-division thresholds
    let pr = post_residual;
    let harmonic_class = pr % 10;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward tight fits: post_residual in low harmonic classes is good
    score -= (10 - harmonic_class.min(10)) as f64 * 1.5;

    // Dead-space penalty: residual that no plausible item (1..=100) can use well
    if pr > 0 && pr < 10 {
        score += 12.0; // tiny unusable sliver
    }

    // Fractional capacity thresholds
    if post_residual > half {
        score -= 3.0; // bin still half usable, mild reward
    } else if post_residual > quarter {
        score += 1.0; // awkward middle zone
    } else if post_residual == 0 {
        score -= 8.0; // perfect closure
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= 4.0 * (pr as f64 - next_item_size as f64) / cap;
        } else {
            // next item won't fit here; penalize leaving moderately-sized gaps
            let gap_class = (pr / 10) % 3;
            score += gap_class as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0
            - 10.0 * progress
            + (open_bins_count as f64).sqrt() * 2.0
            - mean_residual * 0.15;
        if item_size > half {
            score -= 10.0; // big items pair well with fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 5.0; // next item can't share a fresh bin with this one
        }
    }

    // Spread pressure: when many bins are open, favor filling existing ones
    score += (open_bins_count as f64) * 0.3;

    // Mean residual alignment: prefer bins whose residual is near the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with slight super-linear pressure.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Strict dead-space avoidance: if post_residual is a "unusable gap"
    // (smaller than the smallest plausible item, or smaller than the lookahead item),
    // penalize heavily.
    let min_item = 1u32;
    if post_residual < next_item_size && next_item_size > 0 {
        // The gap cannot hold the next item: dead space for the lookahead horizon.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    if post_residual < min_item {
        // Perfect fill: ideal, reward strongly.
        score -= 50.0;
    } else if post_residual <= 10 {
        // Nearly-perfect fill: small unusable remainder is fine, reward.
        score -= 15.0;
    } else if post_residual < 20 {
        // Small gap likely unusable for typical items: penalize as dead space.
        score += 10.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
        if post_residual < next_item_size && next_item_size > 0 {
            // Last chance but creates dead space: soften the penalty of the new bin.
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure,
        // and to how much residual capacity already exists across open bins.
        score += 30.0 + 8.0 * open_pressure + 0.3 * mean_residual;
        // If no bin currently fits (this call is the only candidate anyway),
        // opening is inevitable; make its score competitive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bin: reward using it, more so when many bins are open.
        score -= 4.0 * open_pressure;
    }

    // Mean-residual coupling: if this bin is emptier than average, mildly prefer
    // filling it to balance residuals; if it's below average residual (fuller),
    // slight penalty to preserve flexibility elsewhere.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 0.15 * (residual_f - mean_residual);
    } else {
        score += 0.15 * (mean_residual - residual_f);
    }

    // Lookahead synergy: reward if post_residual exactly or closely matches
    // the next item size (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff <= 5 {
            score -= 12.0 - diff as f64;
        }
    }

    // Stream progression: early in the stream, be more selective (keep bins flexible);
    // late in the stream, just pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    // Reward when the next item fits exactly into the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect two-item packing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64); // partial chain bonus
        } else {
            // next item cannot follow here: penalize proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / bin_capacity as f64).min(1.0);
        }
    }

    // Compare post residual against mean residual: avoid leaving more slack than average.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize large dead space (post residual too small for any future item).
    if post_residual < 10 {
        score -= 8.0; // nearly full bin is good, close it out
    } else if post_residual < next_item_size.max(1) && next_item_size > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // current fit is poor or no good chain exists.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.7 * bin_capacity as f64
            || (next_item_size > 0 && next_item_size > post_residual);
        if poor_fit {
            score -= 12.0;
        } else {
            score += 10.0; // prefer existing bins when they fit reasonably
        }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: squared post-residual pressure.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 2.5 * tight * tight * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if post_residual cannot host next item but bin could have.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // leaves room for lookahead
        } else if bin_residual >= item_size + next_item_size {
            score += 15.0; // wastes space that could fit the next item
        }
        // reward residual that matches next item exactly-ish
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If few fitting bins or item is large, opening a new bin is less bad.
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Penalize new bins when many open bins already exist.
        score += (open_bins_count as f64).min(10.0) * 1.5;
    }

    // Favor bins whose residual deviates favorably from mean (more filled bins first).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for very large leftover dead space relative to smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // small useless slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 18.0 * (x - 0.35) * (x - 0.35) * (1.0 + p2);
    score -= 22.0 * x * (1.0 - x) * (1.0 - p3);
    score += 12.0 * p3 * x;

    // Penalize large dead space relative to mean residual
    score += 0.35 * (pr as f64 - mean_residual).abs() * (0.5 + p2);

    // Reward tight fits, especially late in the stream
    score -= 9.0 * (1.0 - x) * (1.0 - x) * (0.6 + p2);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 14.0 * (1.0 - p2);
    } else if next_item_size > 0 {
        score += 6.0 * (0.5 + p2);
    }

    // Mild penalty for spreading across many bins early
    score += 0.4 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity divided into 10 classes.
    let class = post_residual / 10;
    score -= (10 - class) as f64 * 2.0; // reward smaller post-residual classes

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0; // chainable bin
            // exact chain: post-residual equals next item size class
            if post_residual == next_item_size {
                score -= 50.0;
            }
        } else {
            // dead space for the lookahead: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 60.0;
        // open a new bin early when open bins are already tight/fragmented
        if mean_residual < 15.0 {
            score -= 90.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 20.0; // reserve empty bins for large upcoming items
        }
    }

    // Penalize tiny dead space (harmonic class 1-3) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mid-stream pressure: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Spread penalty: prefer bins below mean residual (tighter bins) slightly.
    score += ((post_residual as f64 - mean_residual) * 0.1).clamp(-10.0, 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are already handled, but gaps that cannot fit the
    // lookahead item are likely to become permanent waste.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward leaving room for the next item.
            score -= 2.0;
        }
    }

    // Harsh penalty for very small unusable gaps (classic dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: fraction of the bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (the new-bin candidate has bin_residual == bin_capacity and
    // typically poor tightness, but add explicit pressure).
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is acceptable late in the stream when open
        // bins are nearly full on average.
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if mean_fullness > 0.85 {
            score -= 25.0;
        }
    } else {
        // Mild reward for consolidating into existing bins when few are open.
        if open_bins_count > 4 {
            score -= 3.0;
        }
    }

    // Progress-aware adjustment: early in the stream, slightly favor
    // spreading items (keeps flexibility); late, favor tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if new_bin {
        score += (1.0 - progress) * 5.0;
    } else {
        score -= progress * 3.0;
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are nearly full; save them unless the fit is very tight).
    if !new_bin && (post_residual as f64) < mean_residual * 0.25 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        // Perfect match: this bin's leftover exactly hosts the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item still fits here; reward tightness of the two-step packing.
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 - slack * 0.25;
        } else {
            // Next item won't fit: penalize proportionally to how far off we are,
            // but less harsh if residual is small anyway (dead space unavoidable).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
        // Extra bonus if next item exactly fills the bin after two placements.
        if post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 15.0;
        }
    } else {
        // Last item: just prefer minimal leftover.
        score += 0.0;
    }

    // --- Relative fill quality vs mean residual ---
    // Favor bins whose post-residual is below the current mean residual (tight packing).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.15;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid forcing a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin fits well:
        // penalize new bins when other bins fit, reward when nothing fits decently.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else {
            // Mild penalty so existing decent fits are preferred over a fresh bin.
            score += 10.0 + (fitting_bins_count as f64) * 2.0;
        }
        // A fresh bin is more attractive early in the stream (room to plan ahead).
        score -= (1.0 - progress) * 8.0;
    }

    // --- Dead-space penalty: residuals too small for the minimum item (1..100 range) ---
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference to keep number of open bins low early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize tiny dead space that is hard to reuse (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.3 * chain;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin's leftover is too small for the next item: mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when other bins fit, scaled by stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut penalty = 30.0 + 40.0 * progress;
        // If the item is large and mean residual is low, opening a bin is more acceptable
        if item_size as f64 > mean_residual {
            penalty -= 15.0;
        }
        // Avoid opening a new bin for tiny items
        if item_size < 30 {
            penalty += 20.0;
        }
        score += penalty;
    }

    // Prefer filling bins with larger residuals when many bins are open (reduce spread)
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Mild pressure to use fewer bins overall
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Tight-fit reward: strongly favor small post_residual via quadratic coupling
    let tight = 1.0 - (post / cap);
    score -= 60.0 * tight * tight * tight;

    // Non-linear stream progress coupling: as stream advances, penalize leftover space more
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 25.0 * prog_term * tight * tight;

    // Dead-space penalty: residual too small for typical future items
    let dead = (post / cap).powi(3);
    score += 40.0 * dead * (1.0 - prog_term);

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 30.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else {
        // mild preference for bins with more alternatives? penalize crowded choice slightly
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: make empty bin unattractive unless residuals are bad
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post) / cap;
        // new bin attractive only if mean residual of open bins is large (they are fragmented)
        score = cap * (0.5 - 0.5 * (mean_residual / cap).tanh()) + 10.0;
        if open_bins_count == 0 {
            score = -1000.0; // must open first bin
        }
    }

    // Slight penalty for opening many bins relative to progress
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in (0,10) is nearly unusable
    // for the smallest items; classify by integer division thresholds.
    let dead_class = post_residual / 10; // 0 => dead zone (<10), 1..9 => usable bands
    if dead_class == 0 && post_residual > 0 {
        score += 25.0; // severe penalty: creates unusable sliver
    }

    // Lookahead harmony: reward if next item fits exactly into post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = post_residual - next_item_size;
        if fit_gap == 0 {
            score -= 40.0; // perfect pairing
        } else if fit_gap / 10 == 0 {
            score -= 5.0; // near-perfect pairing
        } else {
            score -= 12.0; // next item still fits comfortably
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use leftover; leftover likely becomes dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer fuller bins overall: pull toward the mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Modulo-class coupling: residuals divisible by large chunk sizes (25/50)
    // remain reusable for big items; reward them mildly.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Late in the stream, packing tightness matters more; scale residual penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    // New-bin candidate: make it moderately unattractive unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (11.0 - post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 15.0 * (25.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tightness reward: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_frac;

    // Open-bin pressure: prefer using existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New empty bin candidate: penalize unless current bins are very tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 70.0 - 60.0 * (1.0 - pressure).min(1.0);
        score += 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leftover that is too small to be useful
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // last item: just minimize post residual
        score -= 5.0;
    }

    // Penalize creating dead space below the minimum item size (1..100 unknown, assume ~10)
    let min_useful = 10.0f64;
    if (post_residual as f64) < min_useful {
        score += 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are poor fits
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin chains well with next item
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Lookahead: reward residuals that can still host the next item, punish
    // residuals that are just barely too small (dead space trap).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space that blocks the next item: penalize proportionally
            score += 6.0 * (post_residual as f64 / next_item_size.max(1) as f64);
        }
        // perfect chaining: item + next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: minimize wasted space aggressively
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > bin_capacity / 3 {
            score += 20.0; // poor fit, allow new bin to win
        }
    }

    // New-bin candidate handling: neutral baseline with mild penalty so only
    // genuinely bad fits of open bins lose to it.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in the stream, opening bins is cheap; late, prefer filling
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with large mean residual -> encourage
    // consolidating into existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * mean_residual / 100.0;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.15 * (slack - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: reward tight fits via non-linear decay of post residual
    let mut score = post;

    // Smooth polynomial coupling: moderate residuals penalized as stream progresses
    let poly = norm_post * (1.0 - norm_post); // peaks at half-full residual
    score += 40.0 * poly * (0.5 + progress);

    // Dead-space penalty grows super-linearly for tiny residuals
    score += 25.0 * norm_post * norm_post * (1.0 + progress);

    // Reward filling bin well when it's the only fitting bin (last chance)
    if fitting_bins_count <= 1 {
