    }

    // Lookahead: penalize leaving residual just below next item size
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 && gap < 20.0 {
            score += 12.0 * (1.0 - gap / 20.0);
        } else if gap < 0.0 {
            score -= 6.0 * (gap.abs() / cap);
        }
    }

    // Crowd control: many open bins -> prefer using existing bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post);

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: make empty bin mildly unattractive unless residual is hopeless
    if bin_residual == bin_capacity {
        score += 18.0 - 20.0 * progress;
        if post >= 0.9 * cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual: classify dead space ---
    // Classes: (0,10): nearly perfect, (10,25): usable for small items,
    // (25,50): half-bin class, (50,100): wasteful large leftover.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fill: strongest reward.
        score -= 60.0;
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 25 {
        score -= 15.0;
    } else if pr <= 50 {
        score -= 4.0;
    } else {
        // Large leftover: waste unless the next item exploits it.
        score += 10.0;
    }

    // --- Coupling with lookahead item: residual that fits next item is gold ---
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 25.0 - 0.2 * slack;
    } else if next_item_size > 0 {
        // Residual too small for next item: penalize proportionally to how dead it is.
        let deadness = (next_item_size - pr) as f64;
        score += 0.25 * deadness.min(50.0);
    }

    // --- Harmonic / modulo structure on item size classes ---
    // Items in "nice" divisor classes of 100 (10,20,25,50) pair well; prefer
    // bins whose residual stays in a divisor-compatible class.
    let nice = |x: u32| x % 10 == 0 || x % 25 == 0;
    if nice(item_size) && nice(pr) {
        score -= 8.0;
    }
    // Integer-division threshold: residual in [1..=9] is a classic dead zone.
    if pr >= 1 && pr <= 9 {
        score += 12.0;
    }
    // Half-bin class: residual == 50 exactly is a highly reusable harmonic point.
    if pr == 50 {
        score -= 12.0;
    } else if pr > 50 && pr < 90 {
        score += 6.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: push toward the tightest (post_residual already does that),
        // extra tie-break by fit ratio.
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fit_ratio;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin costs ~1 bin; only attractive when:
        //  - item is large relative to capacity, or
        //  - existing fits would leave very dead residuals.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 55.0 - 40.0 * item_frac;
        // If other bins fit but would waste badly (post_residual large), new bin competes.
        if pr > 45 {
            new_bin_score -= (pr - 45) as f64 * 0.5;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        // Many open bins with low mean residual: new bin is fine.
        if open_bins_count as f64 * mean_residual < 50.0 {
            new_bin_score -= 5.0;
        }
        // Next item small: a fresh bin has room for it.
        if next_item_size > 0 && next_item_size <= 30 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // --- Mild stream-phase adaptation ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: if the next item fits the post-residual exactly,
    // heavily reward this bin; if it cannot fit, penalize dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; penalize small unusable leftovers.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += (next_item_size as f64 - dead) * 0.8;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., fuller bins), keeping emptier bins flexible.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to mean residual or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 || fitting_bins_count == 0 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness * tightness;
    }

    // Penalize dead space that can never fit a typical small item.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are congested
    // and mean residual is small relative to item size.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        let mean_gap = mean_residual - item_size as f64;
        let new_bin_bonus = 15.0 - 25.0 * congestion - 0.3 * mean_gap;
        score += new_bin_bonus.max(-20.0).min(20.0);
    }

    // Time horizon: late in the stream, be more conservative (avoid opening bins),
    // early on, allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins already (consolidate).
    score += 0.05 * open_bins_count as f64;

    // Fragmentation penalty: residual much larger than item but leaving awkward remainder.
    let awkward = (post_residual as f64 - next_item_size as f64).abs();
    score += 0.1 * awkward;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap; // normalized fill after placement
    let x = fill.clamp(0.0, 1.0);

    // Smooth non-linear polynomial coupling: reward high fill quadratically, amplified late in stream
    let mut score = pr;
    score -= 18.0 * x * x * (0.6 + 0.8 * t);
    score -= 10.0 * x * x * x;

    // Penalize dead space relative to mean residual (smooth quadratic deviation)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap;

    // Lookahead coupling: smooth reward if next item likely fits the post residual
    if next_item_size > 0 {
        let fits = (next_item_size as f64 / cap).clamp(0.0, 1.0);
        let slack = pr / cap;
        let compat = 1.0 - (fits - slack).abs();
        score -= 8.0 * compat.max(0.0) * compat.max(0.0);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Mild pressure to close bins when many are open
    score += 0.15 * open_bins_count as f64 * (1.0 - x);

    // New-bin candidate penalty: opening a bin should only win if it avoids severe fragmentation
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 4.0 + 6.0 * (1.0 - t) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "dead zones"
    // (too small for typical items) should be penalized when created.
    let dead_threshold = (bin_capacity / 5).max(10) as f64; // leftover < ~20 is likely dead
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += dead_threshold - post_residual as f64;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    }

    // If the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // leftover after also placing next item: prefer small chain remainder
        let chain_left = post_residual - next_item_size;
        score -= 50.0 - (chain_left as f64).min(50.0);
    } else if next_item_size > post_residual {
        // next item won't fit here: penalize proportional to wasted lookahead potential
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Modulo arithmetic on capacity fractions: classify post_residual into
    // capacity/4 buckets; odd "middle" buckets are less useful.
    let quarter = bin_capacity / 4;
    let bucket = post_residual / quarter.max(1);
    let bucket_penalty = match bucket {
        0 => -20.0,          // near-full bin, great
        1 => 10.0,           // 25-50 residual, mediocre
        2 => 0.0,            // 50-75 residual, fine
        _ => -5.0,           // nearly empty bin
    };
    score += bucket_penalty;

    // Integer-division harmonic classes: residuals divisible by common item
    // sizes (10, 20, 25, 50) are more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible
    // or many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 30.0;
        if open_bins_count > 0 {
            score += 10.0 * (open_bins_count as f64).sqrt();
        }
        // If mean residual is large, opening new bins wastes capacity.
        score += 0.3 * mean_residual;
    }

    // Slight preference to fill bins with larger residual early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual as f64 - mean_residual) * 0.1;

    // Prefer bins tighter than average.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible item are "dead space" — penalize them super-linearly.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else {
        // Favor tight fits: reward small residuals, mildly.
        score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Penalize leaving a gap that exactly matches the next item only if it
    // would waste this bin otherwise — lookahead coupling.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // this bin remains usable for the next item
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0; // gap likely unusable for the lookahead item
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current open bins are crowded
    // or this bin's fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.05;
        if fitting_bins_count == 1 {
            score += 10.0; // opening a new bin is fine if the only fitting bin is bad
        }
    }

    // Slight progression bias: late in the stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Small leftover after also fitting the next item is good.
            score -= 12.0 - slack.min(12.0);
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap * 0.25;
        }
    }

    // Reward tight fits relative to the mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless it is genuinely better than a poor fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the next item fits perfectly after this placement, opening is attractive.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste dominates the objective.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into the resulting residual,
    // penalize if the placement leaves a gap just smaller than the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    // (post_residual would be large dead space). Penalize default new bins.
    if bin_residual == bin_capacity {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 35.0 - 25.0 * waste_ratio;
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Many open bins with small mean residual -> prefer consolidation.
        score += 0.4 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates below the mean (consolidate small gaps).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins as the stream progresses.
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * (step_index as f64 + 1.0) / (total_items as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Polynomial coupling of residual with stream progress:
    // early on, tolerate large residuals less; late, residual waste matters more.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize if post residual cannot fit the lookahead item
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 15.0 + 10.0 * progress;
        } else {
            let slack = (post_residual as f64 - next_item_size as f64) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    let mean_norm = mean_residual / cap;
    score += 3.0 * (open_bins_count as f64).ln() * mean_norm * (1.0 - progress);

    // Discard the new-bin candidate unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 act as dead-space classes.
    // Small residues (< 10, minimum item size) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect packing reward.
        score -= 80.0;
    }

    // Modulo-10 harmonic classes: residues 1..9 are only usable by small items.
    let r = post_residual % 10;
    if post_residual >= 10 {
        score -= 0.5 * (9 - r as i32).abs() as f64; // slight reward for "round" classes
    }

    // Lookahead coupling: penalize if next item cannot fit the post residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            score -= 4.0;
            // Harmonic integer-division: can next item leave another clean class?
            let q = post_residual / next_item_size.max(1);
            if q >= 2 {
                score -= 3.0;
            }
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score += 0.0;
        score -= 10.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalate with number of open bins.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if current bin would leave a terrible residue, new bin becomes attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
    } else {
        // Reward using open bins, scaled by how full they already are.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fill;
    }

    // Progress-aware: early in stream, tolerate opening bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below mean, it is scarce space.
    let diff = mean_residual - post_residual as f64;
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps that are too small to ever hold a future item (>= 1..=100 range)
    // are pure waste; weight them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Small-but-usable gaps: mild penalty proportional to tightness.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening new bins is cheap so prefer tight fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // New-bin candidate: make it moderately attractive only when the
    // current bin would leave a large awkward residual relative to mean.
    if bin_residual == bin_capacity {
        // Baseline neutral score; slightly below typical bad fits.
        score = bin_capacity as f64 * 0.5 + 3.0 * pressure;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
        // If next item is large and this item leaves little room elsewhere,
        // opening fresh bin is fine.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // Coupling with mean residual: prefer bins whose post_residual
        // stays close to the open-bin average (keeps residuals uniform).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by post residual (dead space for it),
    // penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a squared penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill the bin exactly
        } else if next_item_size <= post_residual {
            // reward proportionally to how well the next item fills the remainder
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill_ratio;
        } else {
            // next item won't fit here; penalize leaving awkward gap
            let gap = (post_residual as f64) - (next_item_size as f64);
            if post_residual < next_item_size && post_residual > 0 {
                score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
            let _ = gap;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably from the mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins
    // over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        // New-bin candidate: penalize opening new bins unless it's a great fit
        // (post_residual == 0 impossible for empty bin; so new bins get a mild penalty
        // that tight fits in existing bins can overcome).
        score += 15.0 + 25.0 * progress;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly via non-linear squashing.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to plausibly hold a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses leftover space
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * usage;
        } else {
            // next item cannot use this leftover space: mild penalty scaled by waste
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 4.0 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer existing bins,
    // unless the item fits very poorly in all open bins (large post_residual everywhere).
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
        // If mean residual across open bins is small (bins nearly full), opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Time horizon: early in the stream, be slightly more willing to open new bins
    // (long future amortizes); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below the mean (consolidate the emptier space elsewhere).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.03 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / capacity;

    // Base: penalize residual, but non-linearly (dead space hurts super-linearly).
    let mut score = post * (1.0 + 0.35 * post / capacity);

    // Smooth coupling of residual penalty with stream progress:
    // late in the stream, tighter packing matters more.
    let progress_coupling = post * (progress * progress) * 1.5;
    score += progress_coupling;

    // Reward large fill fraction (small post_residual) with a smooth saturating term.
    let fill = 1.0 - post / capacity;
    score -= (fill * fill) * 20.0;

    // Lookahead: reward bins whose post-residual can accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / capacity);
    } else if next_item_size > 0 {
        // Smooth penalty for wasted residual relative to lookahead need.
        let gap = (post - next_item_size as f64).max(0.0).min(capacity);
        score += 0.05 * gap * gap / capacity;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + fit_ratio);
    }

    // Many open bins: encourage consolidation into already-open bins.
    score += 0.4 * open_bins_count as f64 * (post / capacity);

    // Mean residual context: prefer bins whose residual is below mean (tighter bins).
    score += 0.5 * (post - mean_residual);

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits (small post_residual) non-linearly
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= eighth {
        score -= 60.0;
    } else if post_residual <= quarter {
        score -= 25.0;
    } else if post_residual < half {
        score -= 5.0;
    } else {
        // post_residual >= half: large dead space, penalize
        score += 20.0;
    }

    // Lookahead coupling: does next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: bonus scaled by how well it pairs
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.3;
            if next_item_size == post_residual {
                score -= 50.0; // perfect pair
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here: mild penalty proportional to wasted pairing potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Harmonic class match: next item in same quarter-class as item_size
        let cls = |x: u32| x / 25;
        if cls(next_item_size) == cls(item_size) {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 150.0;
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5 {
            score -= 120.0;
        }
    }

    // Prefer fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild pressure to close bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // plausible future item are pure waste. Penalize unusable gaps quadratically.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Penalize large leftover gaps that no realistic item can fill well
    // (gap slightly above typical small items is awkward dead space).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing
    // bins rather than spreading; when few bins, mild preference to fill.
    let bin_pressure = (open_bins_count as f64).ln() + 1.0;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Lookahead coupling: if the next item fits the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post residual too small for the next item: mild penalty
        score += 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large relative to capacity (poor fit elsewhere).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Large items in a fresh bin are fine; small items should go into open bins.
        score = 60.0 - fill_ratio * 55.0;
        if fitting_bins_count <= 2 {
            score += 30.0; // prefer existing bins when few options exist
        }
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild progression term: late in the stream, be more conservative about
    // leaving large residuals (fewer chances to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // 2-step lookahead: reward when post_residual matches next item size,
    // penalize when next item cannot fit into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item fits; the smaller the leftover afterwards, the better
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 25.0 - chain_left * 0.4;
        } else {
            // next item will not fit here -> dead space likely
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap * 0.5;
        }
    }

    // Compare post_residual against mean residual: leaving residuals far below
    // the mean wastes bin space; leaving residuals near mean is fine.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // relative to residual of existing bins (i.e., poor fits elsewhere).
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If open bins are already quite full, opening a new bin is reasonable.
        score = 70.0 - item_size as f64 * 0.3 - open_pressure * 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin can also host the next item
        }
    }

    // Slight progression-based damping: early in stream, be more willing
    // to open bins; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is wasted space
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // otherwise penalize leaving a gap just under next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            let gap_waste = (next_item_size - post_residual) as f64;
            score += 0.15 * gap_waste;
        }
    }

    // Global state: many open bins with large mean residual -> prefer reusing
    // existing capacity rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 4.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    // Penalize spreading across too many open bins when mean residual is low
    // (fragmentation pressure): favor bins above-average in residual.
    if (bin_residual as f64) >= mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing bins are fragmented and the item is large.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 8.0 * fragmentation - 5.0 * big_item * (1.0 - progress);
        // Late in the stream, discourage opening new bins.
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = item_size as f64 / cap;

    // Smooth non-linear coupling of residual waste with stream progress
    let poly = x * x * (1.0 + 1.5 * t) - 0.8 * x * t * (1.0 - t);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (5.0 + 15.0 * t) * fit;

    // Penalize leaving residuals that match neither current mean nor lookahead
    let nxt = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let gap = (x - nxt).abs();
        score += 3.0 * gap * gap;
    }

    // Last-chance bin bonus: strongly favor when only this bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight pressure to consolidate when many bins are open
    score += 0.3 * (open_bins_count as f64).ln() * x;

    // New-bin candidate: mildly penalize early, allow late when open bins are crowded
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if new_bin {
        score += 12.0 * (1.0 - t) - 6.0 * t * (mean_residual / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10, 20, 25, 50) is more reusable than odd dead space.
    let dead = post_residual as f64;
    if post_residual > 0 {
        let mut div_bonus = 0.0;
        if post_residual % 10 == 0 { div_bonus += 8.0; }
        if post_residual % 20 == 0 { div_bonus += 6.0; }
        if post_residual % 25 == 0 { div_bonus += 6.0; }
        if post_residual % 50 == 0 { div_bonus += 8.0; }
        score -= div_bonus;
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Penalize large awkward dead space in harmonic "bad" classes
    // (residuals in (0,10) mod weird offsets are nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver = dead space
    }

    // Lookahead coupling: does post_residual fit next item exactly or well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 30.0;
        } else if next_post % 10 == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty unless dead space is small
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer tight fits overall: reward small post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 10.0;

    // Brand-new bin candidate: base cost of opening a bin, but becomes more
    // attractive late in the stream or when many bins are open with messy residuals.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 35.0 + 25.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // New bin is good if current item is large (harmonic class: big items
        // deserve fresh space so small items can fill leftovers).
        if item_size > 50 { score -= 12.0; }
        if item_size % 10 == 0 && item_size >= 40 { score -= 6.0; }
        // If no bin fits at all, new bin must win.
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or gaps that
    // cannot hold the next item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // gap becomes dead space for the lookahead item
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose residual still fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin opening unless the stream is early or the fit is perfect.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Mean-residual alignment: prefer bins near the mean residual state.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild time decay: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual) relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 100.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space
            score += (post_residual as f64 / bin_capacity as f64) * 40.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // wasting their space is costly.
    let rel = (bin_residual as f64) / (mean_residual.max(1.0));
    if rel < 0.5 {
        score += (0.5 - rel) * 30.0;
    } else if rel > 1.5 {
        score -= (rel - 1.5) * 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very full
    // or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let good_fit_elsewhere = post_residual == 0
            || (next_item_size > 0 && post_residual >= next_item_size);
        if good_fit_elsewhere {
            score += 150.0; // keep using open bins when fit is decent
        } else {
            score += 25.0; // mild penalty; new bin may be justified
        }
    }

    // Progression: as stream advances, prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64 / 20.0).min(1.0);

    // Tiny bonus for exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot fit a plausible future item.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 30.0 * dead;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Perfect chain: this item + next item fills bin nearly exactly.
        let chain_gap = (bin_residual as i64 - item_size as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 10.0 / (1.0 + chain_gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Crowded competition: many fitting bins -> prefer the tightest; mild bonus for scarcity.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: only attractive when current bins are badly fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Base penalty so tight existing fits win; relax late in stream or when bins are full-ish.
        let mut nb = 45.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        nb -= 15.0 * progress;
        // If mean residual across open bins is small (bins nearly full), new bin is good.
        nb -= (mean_residual / cap) * 20.0;
        // Large item relative to capacity: new bin avoids creating tiny slivers.
        if item_size as f64 > 0.7 * cap {
            nb -= 12.0;
        }
        // Lookahead pairing: fresh bin can host item + next item comfortably.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            nb -= 6.0;
        }
        score += nb.max(0.0);
    } else {
        // Prefer bins with residuals close to the mean (balance load) mildly.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Time horizon: early on, be conservative about fragmentation; later, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress * (post_residual as f64 / cap);

    // Slight preference for keeping the number of open bins stable when many are open.
    if open_bins_count > 8 && !is_new_bin {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness reward: strongly favor small post_residual.
    let tight = 1.0 - post / cap;
    score -= 30.0 * tight * tight * tight;

    // Perfect fit bonus (smooth, amplified with progress).
    if post_residual == 0 {
        score -= 25.0 + 20.0 * progress;
    }

    // Last-chance bin: avoid opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead coupling: reward residual that still fits the next item,
    // penalize residuals that waste space relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        // smooth version of fit_next
        let smooth_fit = (post / (post + nxt)).max(0.0);
        score -= 10.0 * smooth_fit * smooth_fit;
        if fit_next > 0.0 {
            score -= 8.0;
        }
        // Penalize leaving a residual slightly below next item (dead zone)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.15 * (nxt - post);
        }
    }

    // Penalize bins whose residual deviates from mean residual (fragmentation),
    // with non-linear (quadratic) coupling.
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Mild penalty for opening new bins when many are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        // but late in stream, new bins are cheaper than fragmentation
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fit_ratio;

    // Harmonic class of post_residual: residual classes mod 10 / mod 20
    let r = post_residual as i64;
    let mod10 = r % 10;
    let mod20 = r % 20;

    // Dead-space penalties: residuals that few common item sizes (1..100) can fill
    // Items <= r are useful; residual in "awkward" bands get penalized.
    if r > 0 {
        // harmonic class via integer division thresholds
        let class = r / 10; // 0..10
        score += match class {
            0 => -15.0,                       // near-perfect fill
            1 => -5.0,                        // small but usable
            2 => 2.0,
            3 => 5.0,
            4 => 4.0,
            5 => 0.0,
            6 => -3.0,
            7 => -2.0,
            _ => 0.0,
        };
        // Modulo coupling: residual divisible by 10 or 20 aligns with typical sizes
        if mod10 == 0 { score -= 3.0; }
        if mod20 == 0 { score -= 2.0; }
        if mod10 == 1 || mod10 == 9 { score += 2.5; } // awkward off-by-one residual
    } else {
        score -= 25.0; // exact fill is ideal
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, stronger if residual closely matches next item
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
            // harmonic match: next item leaves a good class again
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 4.0; }
        } else {
            // next item won't chain here; penalize slightly less if this bin was tight anyway
            score += 3.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if existing bins fit poorly
        // (large item relative to mean residual, or many awkward open bins)
        let waste_estimate = mean_residual - item_size as f64;
        if waste_estimate > 0.0 {
            score += 60.0 + 2.0 * open_bins_count as f64; // keep using open bins
        } else {
            score += 20.0; // mild preference for fresh bin on poor fits
        }
        // early stream: don't proliferate bins
        if open_bins_count < 3 {
            score += 50.0;
        }
        // penalize new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            score += 10.0 * fitting_bins_count as f64;
        }
    }

    // Progress coupling: as stream advances, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    // Mild penalty for many open bins when this bin is far from mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual is "dead" if it's smaller than the smallest plausible item (1..100 => treat <20 as dead).
    if post_residual < 20 && post_residual > 0 {
        score += 60.0 * (1.0 - (post_residual as f64) / 20.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap < 20 {
            score += 10.0; // next item would create dead space here
        } else {
            score -= 15.0;
        }
    }

    // Open bins pressure: penalize using bins when many are open (encourage consolidation),
    // but reward filling bins when few are open.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins get priority).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Progress: later in the stream, be more aggressive about avoiding new dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        // If no open bin fits well, allow the new bin (relax penalty).
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    score -= 40.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(4);

    // Aggressive 2-step lookahead: reward if next item can fill this bin's post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: bin closed after two items
        } else if next_item_size < post_residual {
            // next item fits here; reward tighter residual after the pair
            let pair_resid = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_resid / bin_capacity as f64).powi(2);
        } else {
            // next item cannot use the leftover; penalize dead space relative to mean residual
            score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);
            if post_residual < next_item_size {
                score += 5.0; // leftover too small for the known next item
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin if no other bin fits well
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // early stream: opening bins is cheaper
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild preference for bins with residuals near the mean (balanced packing).
    score -= 0.1 * (post_residual as f64 - mean_residual).abs().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already dominates).

    // Exact / near-exact fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose residual after placement matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 3.0 {
            score -= 18.0; // next item exactly fills this bin afterwards
        } else if post_residual as f64 >= next_item_size as f64 {
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // dead space relative to next item: mild penalty scaled by gap
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless all open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        // If few fitting bins or item is large relative to mean residual, opening is less bad.
        if fitting_bins_count == 0 {
            penalty -= 70.0; // no open bin fits: new bin is necessary
        } else if fitting_bins_count == 1 {
            penalty -= 20.0;
        }
        // Large items waste less when placed in fresh bins.
        penalty -= 0.25 * (item_size as f64 - 10.0);
        // Early in stream: opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 30.0 * progress;
        score += penalty;
    }

    // Penalize leaving residuals that are hard to reuse (small odd gaps) relative to mean residual.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio < 0.15 {
            score += 6.0; // tiny slivers are usually dead space
        }
    }

    // Global pressure: when many bins are open, encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins below mean residual (balance load, keep big gaps alive).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is increasingly penalized (quadratic growth).
    let dead_space_penalty = (post / cap).powi(2) * (1.0 + 3.0 * progress) * cap * 0.5;
    score += dead_space_penalty;

    // Reward near-perfect fits with a smooth saturating term.
    let tightness = 1.0 - (post / cap);
    score -= (tightness.powi(3)) * cap * 0.8;

    // Penalize bins whose residual deviates strongly from the mean (fragmentation).
    score += ((post - mean_residual) / cap).abs() * cap * 0.3;

    // Lookahead: penalize if the next item cannot fit in the post residual (smooth ramp).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += gap.powi(2) * cap * 0.6;
        // Reward leaving exactly enough room for the next item.
        let fit_quality = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= fit_quality.max(0.0) * cap * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 1.5;
    }

    // New-bin candidate (empty bin): penalize so it is only chosen when all fits are terrible.
    if bin_residual == bin_capacity {
        score += cap * 2.0;
        // Late in the stream, opening a fresh bin is less attractive.
        score += progress * cap * 1.0;
    }

    // Mild penalty for many open bins to discourage bin proliferation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residues are golden
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo classes: residues that pair with common small items (multiples of 10/20)
    let pr_mod10 = post_residual % 10;
    if pr_mod10 == 0 {
        score -= 30.0;
    } else if pr_mod10 == 5 {
        score -= 10.0;
    } else {
        score += 5.0 * pr_mod10 as f64;
    }

    // Lookahead coupling: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits here too; reward proportional to leftover after both
            let both = post_residual - next_item_size;
            score -= 40.0 + (both as f64).min(50.0);
            if both % 10 == 0 { score -= 15.0; }
        } else {
            // next item cannot use this residue: penalize proportionally to wasted potential
            let gap = next_item_size - post_residual;
            if gap <= 10 { score += 25.0; } else { score += 10.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when all fits are terrible
    if bin_residual == bin_capacity {
        score = 60.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 { score -= 100.0; }
        return score;
    }

    // Tight-fit reward: fraction of bin used by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 50.0 * fill_frac;

    // Discourage leaving mean residual far above this bin's post residual (imbalance)
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Late-stream consolidation: as stream ends, prefer filling existing bins densely
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Penalty for high post_residual in mid-stream (dead space)
    if post_residual > 50 {
        score += 0.5 * (post_residual - 50) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item.
