    }

    // Coupling with open bins pressure: penalize bins when many bins are open,
    // favoring consolidation into fewer bins.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Penalize bins whose residual deviates from the mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bin: strongly reward using the only bin that fits,
    // unless the fit creates dead space.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty proportional to wasted gap.
        score += 5.0;
    }

    // New-bin candidate: an empty bin is only preferred when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progression
        // and how many bins already fit the item.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            new_bin_score += 10.0; // discourage abandoning the last-chance bin
        }
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= bin_capacity as u32 {
            new_bin_score -= 50.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: minimize post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // Next item cannot follow here: penalize proportionally to wasted residual.
            score += 10.0 + 0.25 * (post_residual as f64);
        }
    }

    // Perfect closure bonus: residual becomes zero (or next item exactly fills it).
    if post_residual == 0 || (next_item_size > 0 && post_residual == next_item_size) {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (denser bins).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        // Allow new bin only when the item leaves a very large residual in open bins anyway.
        score += 20.0 + 40.0 * fit_quality;
    }

    // Late in stream: consolidate harder, avoid spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64) * (post_residual as f64) / cap;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // next item can't fit here anyway: mild penalty for wasting big residual
            score += (post_residual as f64) * 0.05;
        } else {
            // next fits with slack; favor bins leaving residual close to next item
            let slack = (post_residual as f64 - nxt).abs();
            score += slack * 0.3;
        }
        // If next item is small, avoid leaving medium dead space
        if nxt < 20.0 && post_residual >= 20 {
            score += 5.0;
        }
    } else {
        // Last item: strongly prefer filling existing bins completely.
        score -= 20.0 + (bin_residual as f64) * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, keep item here.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let mean_res = mean_residual;
    if (bin_residual as f64) < mean_res {
        score -= 3.0; // smaller-than-average residual = tighter bin, prefer it
    } else {
        score += (bin_residual as f64 - mean_res) * 0.2;
    }

    // New-bin candidate logic: opening a new bin only attractive when item is large
    // relative to capacity or all fits are poor.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let poor_fit = (post_residual as f64) > cap * 0.5 && fitting_bins_count >= 1;
        // Penalize new bins early, more when open bins are loose.
        score += 10.0 + progress * 20.0 + open_bins_count as f64 * 0.5;
        if poor_fit {
            score -= 25.0; // allow opening new bin when fits would waste > half
        }
        if fill_ratio > 0.8 {
            score -= 20.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            score -= 10.0; // room to pair with next item in fresh bin
        }
    }

    // Mild time-horizon shaping: later in stream, be more aggressive about filling.
    score -= progress * (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic waste penalty on leftover space (tight fits strongly favored).
    let mut score = (post * post) / cap;

    // Mild cubic term: extra penalty for very loose fits, smoothed by progress
    // (late in the stream, loose fits are even worse since fewer chances remain).
    score += (post.powi(3) / (cap * cap)) * (0.25 + 0.5 * progress);

    // Lookahead coupling: reward if the next item fits into the resulting residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack = (post - next_item_size as f64) / cap;
        score -= 2.0 * (1.0 - slack * slack) * (1.0 + 0.5 * progress);
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin, scaled by how well the item actually fills the bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill = item_size as f64 / cap;
        score -= 8.0 + 12.0 * fill;
    }

    // New-bin candidate (pristine bin): heavily penalize unless no open bin fits
    // (fitting_bins_count == 0) or the item is huge and would leave tiny waste.
    if bin_residual == bin_capacity {
        let waste = post / cap;
        let item_frac = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 5.0; // forced open: make it win
        } else if item_frac > 0.8 && waste < 0.2 {
            score -= 4.0; // near-perfect single-item bin is acceptable
        } else {
            score += 10.0 + 10.0 * progress;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // prefer placements that consolidate (reduce mean residual later).
    score += 0.05 * mean_residual / (open_bins_count.max(1) as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize residuals that fall into "dead" harmonic classes —
    // residues that few item sizes can ever use.
    // Item sizes are 1..100; a residual r is usable if some future item <= r.
    // Weight by how "wasted" the residual is relative to typical items.
    if post_residual > 0 {
        // Harmonic class via integer division thresholds: class k = post_residual / 10
        let class = post_residual / 10;
        // Small classes (1..=5) are highly usable; large classes are dead space.
        let dead_penalty = match class {
            0 => 0.0,
            1..=3 => 0.0,
            4 => 2.0,
            5 => 4.0,
            6 => 8.0,
            7 => 12.0,
            8 => 18.0,
            9 => 26.0,
            _ => 35.0,
        };
        score += dead_penalty;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Modulo arithmetic coupling: residual that is congruent to common item
    // sizes mod capacity-fraction blocks is more likely to be filled later.
    let m = (post_residual % 25) as f64;
    score -= 0.3 * m; // residual close to a multiple of 25 leaves cleaner slots

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement
    // (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * (next_item_size as f64);
        // Extra reward if next item nearly fills the remainder too.
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty for stranded space.
        score += 0.2 * (next_item_size as f64 - post_residual as f64);
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer the new bin when all open bins fit poorly (large post_residual)
    // or the stream is early with few open bins.
    if bin_residual == bin_capacity {
        // Default: new bin is moderately unattractive.
        score = cap * 0.75;
        if fitting_bins_count == 0 {
            score = cap * 0.4; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score = cap * 0.9; // last chance bin exists: keep it
        }
        // Late in the stream, consolidate more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual coupling: if open bins are already loose on average,
    // penalize adding more loose space; prefer filling this bin.
    score += 0.1 * (mean_residual - frac * cap).abs();

    // Many open bins: discourage spreading into new bins, encourage tightening.
    score -= 0.5 * open_bins_count as f64 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps (1..=9) are nearly unusable
    // for future items (sizes >= 1 but typical items are larger), so punish
    // them hard; large residuals remain reusable.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 9 && post_residual < 20 {
        score += 8.0;
    }

    // Reward exact/tight fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = 1.0 - pr / bin_capacity as f64;
        score -= 25.0 * tightness * tightness;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening yet another bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize so it is
    // chosen only when no open bin gives an acceptable fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is close to the mean (balanced usage),
        // mildly.
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement; if next item cannot use the gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += 0.1 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 150.0;
            // partial chaining reward scaled by how well next fits
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / bin_capacity as f64) * 100.0;
        } else {
            // next item won't fit here: penalize large dead space mildly
            score += 50.0;
        }
    }

    // Penalize post_residual that is small but unusable (dead space) relative to mean residual
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare against mean residual: prefer bins with lower residual (tighter packing)
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 300.0;
        // discourage opening new bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 200.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 50 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows as post_residual shrinks.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible future item
    // (dead space < ~10 is nearly unusable), but only mildly for exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // wasted relative to lookahead
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive when existing
    // bins fit reasonably well; cheap when the fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open a new bin late in the stream (fewer future items
        // to fill it) and when many bins are already open (consolidation risk low).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += (mean_residual / bin_capacity as f64) * 10.0;
        // If the item is huge relative to capacity, a fresh bin guarantees fit.
        if item_size as f64 > bin_capacity as f64 * 0.8 {
            score -= 10.0;
        }
    }

    // Mild penalty for leaving residual far from mean (fragmentation diversity),
    // encouraging residual homogenization for future pairing.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste is penalized more heavily later in the stream.
    let progress_coupling = norm_pr * norm_pr * (1.0 + progress) * (1.0 + progress);
    score += 12.0 * progress_coupling;

    // Cubic dead-space penalty that grows with residual fragmentation relative to mean residual.
    let spread = (pr - mean_residual).abs() / cap;
    score += 8.0 * spread * spread * spread;

    // Lookahead: reward if the next item fits exactly into the post-residual,
    // reward scaled by smooth progress interaction.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            // perfect-fit reward, strongest when gap is small and progress is high
            let exact = 1.0 - (fit_gap / cap);
            score -= 10.0 * exact * exact * (0.5 + progress);
        } else {
            // next item cannot fit here: mild penalty on tight fills late in stream
            score += 3.0 * (-fit_gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Penalize spreading across many open bins (encourages consolidation),
    // with a smooth saturating term.
    let oc = open_bins_count as f64;
    score += 2.0 * (oc / (oc + 4.0)) * norm_pr;

    // Slight preference for fuller placements overall (low post_residual),
    // non-linear in item fill fraction.
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small dead-space penalty via harmonic classes (mod 10)
    let class = post_residual % 10;
    score += match class {
        0 => -20.0,
        1..=3 => 15.0,
        4..=6 => 5.0,
        _ => 0.0,
    } as f64;

    // Fractional capacity usage: reward high fill ratio
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 30.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving moderate waste
            score += pr * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only prefer when no good fit exists
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Late in stream: consolidate, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    // Penalize bins far from mean residual (fragmentation)
    score += (pr - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

