    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced early in the stream and
        // when the current bin would leave a large dead gap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + progress * 6.0;
        // If the item fits poorly in existing bins, opening fresh is cheaper.
        if fitting_bins_count > 0 {
            let worst_gap = (bin_residual - item_size).min(bin_capacity);
            if post_residual < 10 {
