            }
        }
        score += new_bin_cost;
        // Empty-bin residual baseline: its post_residual equals capacity - item,
        // which is naturally large, so add mild bonus to keep it competitive
        // when item is large.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), scaled non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits into post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * chain_waste;
        } else {
            // Next item won't fit here; penalize leaving a残 gap that is unusable.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(30.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0 * tightness;
    }

    // Relative to mean residual: bins with less residual than average are precious;
    // filling them is good, but avoid dumping into already-sparse bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.3 * rel.max(0.0);
    score -= 0.15 * (-rel).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: default cost; only attractive when no open bin fits well
    // or many bins are open already (bin consolidation pressure).
    if bin_residual == bin_capacity {
        score = 70.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Early stream: be slightly conservative, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.4; // tighter follow-up fit => bigger reward
            if post_residual == next_item_size {
                score -= 20.0; // perfect chaining
            }
        } else if next_item_size > bin_residual {
            // This bin can't host next item anyway; mild bonus for keeping big
            // residual bins intact for the next item.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize wasting a large-residual bin on a tiny item (poor density).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.3 && bin_residual != bin_capacity {
        score += (0.3 - fill_ratio) * 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly. Penalize new bins mildly by default, more so
    // when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 18.0 + open_bins_count as f64 * 1.5;
        // If no open bin fits well, allow opening: when this bin is the only
        // "fitting" candidate (itself), fitting_bins_count == 1.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // Late in the stream, prefer closing out residual space.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 15.0;
        // If mean residual across open bins is large, opening wastes capacity.
        new_bin_score += (mean_residual / bin_capacity as f64) * 10.0;
        score += new_bin_score;
    } else {
        // Reward using open bins proportionally to how "average" their
        // residual is (balance residual spread across bins).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    // Global pressure: with many open bins, favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tight_reward = tightness * tightness * (1.0 + 3.0 * progress) * cap;
    score -= tight_reward;

    // Penalize post-residuals that are awkward (near small-item sizes) via smooth bump
    let bump = (-((pr - 20.0) * (pr - 20.0)) / 200.0).exp();
    score += 15.0 * bump * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let d = (pr as f64 - next_item_size as f64).abs();
        score -= 12.0 * (-d * d / 400.0).exp();
    }

    // Mild penalty for spreading across many open bins, growing with progress
    score += (open_bins_count as f64).ln() * 2.0 * (0.3 + 0.7 * progress);

    // Prefer bins with below-mean residual (denser bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless item is large and no tight fit exists
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * fit_ratio - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it decomposes into
    // small-item-friendly chunks. Residuals in low classes (near multiples
    // of common item sizes) are more reusable.
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;

    // Reward tight fits: post_residual small relative to capacity.
    score -= 40.0 * fill_ratio * fill_ratio;

    // Harmonic class bonus: post_residual divisible by small harmonics
    // (e.g. 10, 20, 25, 50) is reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.0; }
        // Class of pr via integer division thresholds: very small dead
        // space is worse than medium dead space.
        let class = pr / 10; // 0..10
        match class {
            0 => score += 25.0,          // 1..9: nearly dead space
            1 | 2 => score += 8.0,       // 10..29: awkward
            3 | 4 => score += 0.0,       // 30..49: usable by mid items
            5 | 6 => score -= 3.0,       // 50..69: quite reusable
            _ => score -= 5.0,           // 70+: plenty of room left
        }
    } else {
        score -= 30.0; // perfect closure of the bin
    }

    // Lookahead coupling: if next item fits into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // Harmonic match: next item leaves another harmonic residual.
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize slightly less if this bin
            // is nearly full anyway (chain closure).
            if pr < 10 {
                score -= 4.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (this call has bin_residual == capacity).
    if bin_residual == bin_capacity {
        // Base cost of a new bin: keep it competitive only for poor fits.
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Many open bins with slack: discourage new bins.
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    } else {
        // Mild preference for filling existing bins when many are open.
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Mean residual anchoring: prefer bins whose residual deviates favorably
    // from the mean (below mean residual => tighter than average bin).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold future items (min item size 1, but typical items are larger)
    // are heavily penalized as unusable gaps.
    if post_residual > 0 {
        // Treat tiny gaps (< 10) as dead space: strong penalty.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        } else {
            // Larger usable residuals are mildly rewarded.
            score -= 5.0;
        }
    } else {
        // Perfect fit: big reward.
        score -= 100.0;
    }

    // Reward tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Pressure from number of open bins: prefer filling existing bins
    // over spreading out when many bins are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here: penalize leaving a gap it can't use.
            score += 8.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; discourage
    // it unless the current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if no good fit exists elsewhere (large mean residual spread),
        // soften the penalty so a fresh bin can win.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild stream-progression term: as the stream progresses, be slightly
    // more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // 2-step lookahead: reward post_residual that exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect match for next item => strong reward.
        if gap < 0.5 {
            score -= 45.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item fits here: reward proportionally to how snugly.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space: next item cannot follow; penalize dead space relative to next size.
            score += 0.35 * (post_residual as f64 - nxt).max(0.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // placing here concentrates waste; reward filling tight bins, penalize
    // filling loose bins (which leaves many medium residuals).
    let resid_f = bin_residual as f64;
    let mean_gap = resid_f - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or no good existing fit exists.
    if bin_residual == bin_capacity {
        // New empty bin: post_residual = capacity - item_size.
        // Penalize opening a new bin mildly; let lookahead rewards decide.
        score += 12.0;
        // If item is huge, a fresh bin is fine (post_residual small already).
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        // If next item also fits in the fresh bin alongside, encourage it.
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward keeping bins open instead of proliferating.
        score -= 5.0;
        // More open bins => mild extra pressure to fill existing ones.
        score -= 0.3 * open_bins_count as f64;
    }

    // Stream progression: early on, be more willing to open bins / spread;
    // late in stream, pack tightly to close bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * (0.5 - progress); // early: +, late: -
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if post_residual >= 10 {
        // Lookahead coupling: reward if next item fits into the post residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > post_residual {
            score += 0.08 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by number of alternatives.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual context: penalize placing into bins already far below mean residual
    // (keeps a portfolio of usable large residuals).
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate logic: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced late in the stream or when
        // the item is large (hard to place later).
        let mut new_bin_cost = 20.0 + 0.5 * open_bins_count as f64;
        if item_size > 70 {
            new_bin_cost -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_cost -= 5.0; // large items keep coming; fresh capacity useful
        }
        // Waste measure for the new bin: capacity minus item.
        score = new_bin_cost + (bin_capacity - item_size) as f64 * 0.3;
    }

    // Small deterministic tie-breaker based on residual structure.
    score += 0.01 * ((bin_residual as f64 * 7.0 + item_size as f64 * 13.0) % 4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = post / cap;
    let poly = p * p * (1.0 - progress) - p * progress;
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * (0.5 + progress);

    // Last-chance bonus: penalize opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        if diff >= 0.0 {
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            score += 5.0 * (-diff / cap);
        }
    }

    // Slight preference for filling bins with low mean residual (consolidation)
    score += 0.05 * (mean_residual - post).abs();

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are "dead space" classes
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Penalize residues in "unusable" harmonic classes (small leftover slivers)
    // classes: 0 (great), 1..=5 (dead slivers), 6..=20 (awkward), >20 (usable)
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0; // tiny slivers are nearly worthless
    } else if post_residual <= 20 {
        score += 20.0;
    } else {
        score -= 10.0; // usable residue is fine
    }

    // Reward tight fits (post_residual small relative to item)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 50.0 / (1.0 + tightness);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize more if post_residual is large (waste)
            score += 0.5 * frac * 100.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 40.0;
        // but if existing bins would leave big waste, new bin becomes attractive
        if post_residual == bin_residual {
            // this is the empty-bin call; estimate waste of using open bins
            if fitting_bins_count == 0 {
                score -= 500.0; // must open new bin anyway
            } else if fitting_bins_count == 1 {
                score -= 80.0; // weak alternative
            }
            // if many open bins fit, prefer them
            if fitting_bins_count > 2 {
                score += 100.0;
            }
        }
    }

    // Progress-based gentle pressure to consolidate into fewer bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (mean_residual / cap).min(1.0);

    // Mild penalty proportional to number of open bins to discourage sprawl
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score -= 60.0; // perfect packing, strongly reward
    } else if post_residual <= 20 {
        // small unusable-ish gap: penalize quadratically
        score += (21 - post_residual) as f64 * 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // leftover can't serve next item -> mild penalty scaled by wasted space
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer tighter fills.
    let open_pressure = open_bins_count as f64 / 20.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Prefer bins already below mean residual (tighter bins fill first).
    score += (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 40.0 + open_pressure * 10.0;
        }
    }

    // Mild stream progression: late in the stream, prefer consolidating.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // penalize proportional to mismatch, scaled by how close it is
            score -= 40.0 / (1.0 + lookahead_gap / 10.0);
        }
        // If next item cannot fit in post_residual, mild penalty for wasted slot
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual) which base score does
        score -= 5.0;
    }

    // Compare post_residual relative to mean residual across open bins
    let mean_gap = post_residual as f64 - mean_residual;
    // Leaving less than average residual is good (denser packing)
    score += 0.5 * mean_gap;

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when plenty of open bins exist with room
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of opening a bin
        score += 55.0;
        // If next item could pair with current item in this fresh bin, soften the cost
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // Fewer open bins -> opening a new one is more acceptable
        score -= 4.0 * open_bins_count as f64;
    } else {
        // Reward using already-open bins, more so when many are open
        score -= 2.0 * open_bins_count as f64;
    }

    // Small penalty for creating awkward dead space (residual too small to be useful)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: post_residual zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space relative to capacity, with non-linear amplification
        // for very small post-residuals that only tiny items could use.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 30.0;
        if post_residual < 10 {
            score += 25.0; // unusable sliver
        }
    }

    // Tightness of current fit: prefer bins where item occupies large share of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slight penalty if we waste a lot
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins -> consolidate into existing bins.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.5);
    score += pressure * 2.0;

    // Time horizon: early in stream, allow more bins; later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += (1.0 - progress) * (mean_residual - post_residual as f64).abs() * 0.1;

    // New-bin candidate handling: empty bin gets baseline slightly above good fits,
    // but below bad fits, so poor placements don't ruin existing bins.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.05 - progress * 5.0;
        // If no existing bin fits, new bin should win clearly.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Quadratic penalty on wasted residual, growing over the stream.
    score += 0.9 * (pr / cap) * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly late in stream.
    score -= (1.0 - pr / cap) * item_size as f64 * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward if next item can use post_residual exactly or closely.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = pr - nx;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins below mean residual (more filled bins get priority).
        score += 0.3 * (mean_residual - bin_residual as f64).abs() / cap;
        score -= 0.4 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: modulo classes on capacity fractions.
    let class = post_residual % (bin_capacity / 10).max(1);
    let class_penalty = match class {
        0 => -6.0,                 // perfectly divisible: clean slot
        1 | 2 => 3.0,              // near-dead slivers
        3 | 4 | 5 => -1.5,         // mid-band, still usable
        6 | 7 => 1.0,
        _ => 2.5,
    };
    score += class_penalty;

    // Dead-space threshold: residuals below ~10% of capacity are nearly unusable.
    let dead_threshold = cap_f * 0.1;
    if post < dead_threshold {
        score += (dead_threshold - post) * 0.8 + 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here: penalize leaving mid-size gaps
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 { score += gap * 0.3; }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let base = cap_f * 0.45; // fresh bin keeps a healthy residual
        let mut nb = base;
        if fitting_bins_count == 0 { nb -= 10.0; }
        if next_item_size > 0 && next_item_size <= post_residual.max(0) { nb -= 2.0; }
        if open_bins_count == 0 { nb -= 5.0; }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += progress * 6.0;
        score = score.max(nb) + (nb - score).abs().min(0.0); // blend conservatively
        score = nb + (score - nb) * 0.5;
    }

    // Mild preference for bins tighter than the mean residual (good fits).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold on item size: large items prefer tight bins.
    let big = item_size / 20; // classes 0..4
    score -= big as f64 * (cap_f - bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward tight fits proportionally.
        score -= 40.0 * (item_size as f64 / bin_residual as f64);
    }

    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 15.0;
    }
    // Reward leaving a gap exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: mild penalty scaling with number of open bins.
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        // If the only alternative is a bad fit, make new bin more appealing.
        if post_residual == bin_capacity - item_size {
            score -= 25.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        }
    }

    // Slight progress-based tightening: later in stream, prefer compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fills the
    // remaining residual (a perfect pair), penalize if next item cannot fit.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 400.0; // perfect pair: this bin absorbs two items exactly
        } else if next_item_size <= post_residual {
            // next fits: reward proportionally to how tightly it packs
            score -= 150.0 * (next / post);
        } else {
            // next won't fit here: penalize small leftover dead space
            score += 80.0 * (1.0 - post / (bin_capacity as f64)) * (post / next);
        }
    }

    // Tightness relative to capacity: prefer bins where the item fills a
    // large fraction of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 120.0 * tightness;

    // Relative-to-mean coupling: bins with residuals far below the mean
    // residual are "almost full" — placing here is efficient.
    let rel_mean = post_residual as f64 - mean_residual;
    score += 0.4 * rel_mean;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate penalty: opening a new bin wastes capacity unless
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 60.0 + 0.5 * waste;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative: new bin is fine
        }
    }

    // Mild stream-phase adjustment: early on, keep bins flexible; late,
    // consolidate aggressively.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 30.0 * (1.0 - phase) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space)
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize leaving a gap just under the next item (dead space trap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening bins, more so when good fits exist or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // Slightly less penalized if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Prefer bins with residual far from mean (consolidate space usage)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Mild bonus for bins already partially filled
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Penalize very small unusable residuals harder as stream progresses
    if post_residual < 10 {
        score += 20.0 * (0.5 + step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.5 * progress * (1.0 - progress) * 4.0);
    score += 6.0 * (poly - norm_pr);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let gate = 1.0 / (1.0 + (-gap / 8.0).exp());
        score += 5.0 * gate * (1.0 - progress * 0.5);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Mild penalty for spreading across many bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Favor bins whose residual is near mean residual (smooth attraction)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction buckets. Small residuals (<= cap/8) are "perfect
    // closure" and heavily rewarded; large residuals are penalized
    // super-linearly via integer-division classes.
    let cls = post_residual / (bin_capacity / 8).max(1); // 0..=8 harmonic class
    match cls {
        0 => score -= 40.0,
        1 => score -= 18.0,
        2 => score -= 6.0,
        3 => score -= 0.0,
        4 => score += 8.0,
        5 => score += 16.0,
        6 => score += 26.0,
        7 => score += 38.0,
        _ => score += 55.0,
    }

    // Exact-fill bonus: item consumes the bin entirely.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // reward chaining; if next item is larger than post-residual,
    // this bin would strand the stream — penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward when next item closes the bin after placement
            if post_residual - next_item_size <= bin_capacity / 8 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.1 * post_residual as f64;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins that fit reasonably well; only open a new
        // bin when no open bin offers a decent fit (post_residual would be
        // small dead space... but here post_residual == cap - item).
        // Penalize new bin mildly; escalate when many bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // Exception: large items leave huge residuals elsewhere anyway;
        // opening a fresh bin for very large items is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 30.0;
        }
        // If mean residual across open bins is too small to hold the next
        // item, opening a fresh bin is more attractive.
        if (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    } else {
        // Slight preference for bins with residual close to item (tight fit)
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= 10.0 * tightness;
        // Diversify: discourage dumping into bins whose residual deviates
        // far from the mean (keeps a spread of useful residual sizes).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0; // fully dead gap (cannot hold anything)
        }
        // Gap too small for the *next* item is dead space with respect to lookahead.
        if next_item_size > 0 && post_residual < next_item_size {
            let dead = (next_item_size - post_residual) as f64;
            score += 6.0 * dead;
        }
        // Gap that could fit the next item is valuable: reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * slack.sqrt();
        }
    }

    // Penalize large leftover residuals only mildly (they remain reusable);
    // penalize tiny residuals more per unit since they are near-dead.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // New-bin candidate handling: opening a bin is justified only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: modest, so it beats terrible fits but not decent ones.
        score = 20.0 + 0.1 * (bin_capacity as f64);
        // If this item fits nowhere else (last chance), opening is cheap.
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: prefer it unless its post-fit residual is hopeless.
            score += 15.0;
        } else {
            // Several options exist: make new bin clearly worse than reasonable fits.
            score += 40.0;
        }
        // Early in the stream, opening bins is more acceptable (build diversity).
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, avoid opening a new bin.
        score += 0.3 * mean_residual;
        // Lookahead: if next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin,
    // unless it would create dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 800.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            // hopeless gap: allow new bin to compete
            score += 5.0;
        } else {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) slightly.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (post_residual near 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 50.0 / post_residual as f64;
    }

    // 2-step lookahead: if the next item fits perfectly into the post-residual,
    // this is an ideal chained placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            score -= 200.0 / (1.0 + leftover_after_next as f64);
        } else {
            // Next item cannot use the remaining space: penalize dead space,
            // scaled by how dead it is relative to typical item sizes.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates
    // favorably (tighter than average) after placement.
    let mean_post = mean_residual - item_size as f64;
    score += (post_residual as f64 - mean_post) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (high post_residual waste elsewhere) — discourage needless bin opening.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bins early in the stream when few bins are open.
        score -= (open_bins_count as f64).min(10.0) * 5.0;
    }

    // Mild pressure to fill existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap too small for the lookahead item
        }
        if post_residual < 10 {
            score += 15.0; // unusable sliver
        }
    }

    // Reward bins that can also host the lookahead item afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: when many bins are open, prefer filling existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (moderate residual);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * tightness;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps the pool homogeneous) unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - tightness);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let escape_cost = 55.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else {
            score += escape_cost; // discourage wasteful opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Smooth non-linear coupling: post_residual penalty grows super-linearly,
    // amplified as the stream progresses (dead space matters more later).
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + 2.0 * norm_post);
    let mut score = post * (1.0 + progress * poly * 3.0);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = (-norm_post * 4.0).exp();
    score -= 12.0 * tightness;

    // Lookahead coupling: reward residuals that leave room for the next item,
    // penalize residuals that are almost-but-not-quite usable by it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (-slack * 8.0).exp();
        } else {
            let gap = (nxt - post) / cap;
            score += 8.0 * (-gap * 6.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: opening a bin early is cheap, later is costly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap * (0.6 + 0.8 * progress) + 0.05 * open_bins_count as f64;
        // Prefer a new bin over a very poor fit into an existing bin.
        if norm_post > 0.5 && fitting_bins_count > 1 {
            score -= 10.0 * (norm_post - 0.5);
        }
    } else {
        // Mild penalty for scattering across many open bins.
        score += 0.3 * open_bins_count as f64 * (0.5 + progress);
        // Nudge toward bins with residuals close to the mean (balance).
        score += 0.5 * (post - mean_residual).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item (capacity fractions: 1/2, 1/3, 1/4 of capacity)
    let cap = bin_capacity as u32;
    let item_class = if item_size * 2 <= cap { 0 } else if item_size * 3 <= cap { 1 } else { 2 };
    let next_class = if next_item_size == 0 { 9 } else if next_item_size * 2 <= cap { 0 } else if next_item_size * 3 <= cap { 1 } else { 2 };

    // Perfect / near-perfect lookahead fit reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 60.0;
        } else if slack <= cap / 10 {
            score -= 30.0;
        } else {
            score -= (slack as f64) * 0.4;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving a large unusable remainder
        score += (post_residual as f64) * 0.6;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Reward tight fits (small post_residual) non-linearly
    score -= 40.0 / (1.0 + post_residual as f64);

    // Harmonic-class pairing: small item into a bin whose residual matches a class boundary
    if post_residual == cap / 2 || post_residual == cap / 3 || post_residual == cap / 4 {
        score -= 8.0;
    }
    // Penalize dead space below the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: reward heavily.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: residuals too small for the minimum item size
    // (or too small for the lookahead item) are wasted capacity.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap unusable by the next item: penalize proportionally to how close
        // the next item is to fitting (near-miss waste hurts most)
        let miss = (next_item_size - post_residual) as f64;
        score += 25.0 * (1.0 - miss / 40.0).max(0.0);
    }

    // Reward using bins whose residual is tightly matched to the item
    // (small post_residual relative to capacity = good packing).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when the item fits poorly everywhere:
        // few fitting bins, or this placement would strand a tiny gap.
        let pressure = if fitting_bins_count <= 1 { 80.0 } else { 0.0 };
        let spread = if (mean_residual - item_size as f64).abs() > 30.0 { 40.0 } else { 0.0 };
        score -= 30.0 + pressure + spread;
        // Late in the stream, consolidating beats opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 * progress;
    }

    // Open-bin pressure: discourage scattering items across many open bins
    // unless the fit is genuinely good.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Favor bins whose residual is close to the item (minimize leftover).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Slight bonus if the leftover after placement can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fits the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit: mild reward proportional to leftover after next item
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // dead space for the next item: penalize proportionally to the gap
            score += 2.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize residual that is small but nonzero (hard-to-fill sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins tighter than average (best-fit flavor relative to mean residual)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference to fill existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + 30.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if the next item fits in the post residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a residual that just barely fails the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 0.4 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many fitting bins; prefer consolidation.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when open bins already have ample mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 40.0 + 25.0 * progress;
        new_bin_score += (mean_residual / 10.0).min(20.0);
        // If no open bin truly fits, opening is inevitable — soften.
        if fitting_bins_count == 0 {
            new_bin_score -= 45.0;
        }
        score += new_bin_score;
    }

    // Prefer filling bins that are already mostly used (consolidation pressure).
    let used_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * used_frac * used_frac;

    // Slight penalty when many bins are open: encourage closing them out.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate residual; late, penalize waste more strongly.
    let waste_penalty = pr * pr / cap * (0.5 + 2.0 * progress * progress);
    score += waste_penalty;

    // Reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * item_size as f64 * 0.3;

    // Penalize bins with low residual relative to mean (fragmentation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    // Last-chance bin: strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= (1.0 - diff / cap) * 15.0;
        } else {
            score += diff * 0.1;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score -= (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // New-bin candidate: make it slightly unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits: small post_residual is good, but avoid useless slivers (< 5)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class: post_residual in residue classes mod 10.
    // Residuals that are common item sizes (10..80 multiples/fractions) stay reusable.
    let class = post_residual % 10;
    match class {
        0 => score -= 12.0,           // multiple of 10: highly reusable
        5 => score -= 6.0,            // half-class: moderately reusable
        1 | 9 => score += 4.0,        // edge slivers: awkward
        2 | 8 => score += 2.0,
        _ => {}
    }

    // Integer-division thresholds: can next item fit in post_residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // bonus if next item exactly fills what remains after it
        let pr2 = post_residual - next_item_size;
        if pr2 == 0 {
            score -= 15.0;
        } else if pr2 % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // this placement kills the chance for next item in this bin
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of a fresh bin
        score += 55.0;
        // early stream: bins are cheap-ish to open; late stream: conserve
        score -= 20.0 * (1.0 - progress);
        // if many bins already open and mean residual is fragmented, opening fresh is fine
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
    } else {
        // Prefer bins whose residual is close to item (best-fit flavor beyond post_residual)
        let slack = (bin_residual - item_size) as f64;
        score += slack * 0.05;
        // Prefer fuller bins (small residual) slightly
        score += bin_residual as f64 * 0.02;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's a straggler; use it
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavy penalty
    } else if post_residual <= 20 {
        // small gap: penalize proportionally to how unlikely it is to be reused
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    } else {
        // larger residual: reward keeping big usable space, mildly
        score -= 0.35 * post_residual as f64;
    }

    // Reward tight fits (post_residual small but usable)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * tightness * tightness;

    // Open-bin pressure: discourage spreading items across many bins
    // unless the fit is genuinely good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness) * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good candidate to absorb the item (concentrate waste).
    let dev = mean_residual - post_residual as f64;
    score -= 0.4 * dev.max(0.0);
    score += 0.25 * (-dev).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward; if post_residual barely misses the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual >= next_item_size.saturating_sub(10) {
            score += 8.0; // near-miss dead space for the lookahead item
        }
    }

    // New-bin candidate: neutral baseline with mild attractiveness,
    // so a new bin is chosen only when all open bins score poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // late in the stream, prefer closing out open bins
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match bonus ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Reward exact or near-exact match with the next item.
        score -= 60.0 / (1.0 + diff * diff * 0.05);
        // Extra bonus for exact match (zero dead space after next item too).
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals too small for the next item (dead space locked in).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste tightly.
        score -= 10.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual far above mean are "loose"; prefer tightening them,
    // but avoid bins already far below mean (fragmented).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        if rel > 0.0 {
            score += 4.0 * rel; // penalize leaving more than average space
        } else {
            score -= 2.0 * rel.abs().min(1.0); // mild reward for tight bins
        }
    }

    // --- Dead-space penalty for very small residuals ---
    if pr > 0.0 && pr < 10.0 {
        score += 30.0 * (1.0 - pr / 10.0);
    }

    // --- Last-chance bin: strong reward to avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    } else if fitting_bins_count > 1 {
        // With many options, prefer the tightest fit (already via post_residual),
        // small penalty to break ties toward well-filled bins.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Opening a new bin is only attractive when the item fits poorly everywhere.
        // Base penalty keeps existing bins preferred; relax with progress.
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 45.0 - 15.0 * progress - 20.0 * poor_fit;
        // Empty bin has perfect lookahead potential for the NEXT item: mild discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // --- Mild pressure to consolidate when many bins are open ---
    score += 0.02 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual relative to capacity is good,
    // but a post_residual that is tiny-but-nonzero is wasted unless it matches the next item.
    if post_residual > 0 {
        let lookahead_fit = if next_item_size > 0 && next_item_size <= post_residual {
            1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64
        } else {
            0.0
        };
        // If the next item fits the leftover, reward; otherwise penalize leftovers that
        // are too small to be useful (below the minimum plausible item size band).
        if lookahead_fit > 0.0 {
            score -= 6.0 * lookahead_fit;
        } else {
            let useless = (post_residual as f64) / bin_capacity as f64;
            score += 4.0 * useless * useless;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early on when
    // open bins exist; discourage unless residual space in the system is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Prefer new bin when existing mean residual is low (fragmented small gaps)
        // and when few bins are open; penalize when many bins have plenty of room.
        score = bin_capacity as f64 * 0.5
            + 10.0 * (1.0 - fragmentation)
            + 5.0 * (open_bins_count as f64).sqrt()
            - 4.0 * progress;
        // If the item is large, a fresh bin gives a perfect fit anyway.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 5.0;
        }
    }

    // Mild global pressure: as more bins accumulate, prefer consolidating into
    // existing bins to curb bin proliferation.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon coupling: late in the stream, waste matters more (no future
    // items to fill gaps), so penalize residual more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 + 2.0 * progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;
    // smooth polynomial coupling of post_residual with stream progress
    let pn = post / cap;
    score += 8.0 * pn * pn * (1.0 - progress) - 4.0 * pn * progress;
    // penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += (next_item_size as f64 - post) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score -= 3.0 * (next_item_size as f64 / cap);
    }
    // reward tight fits
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 5.0;
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }
    // new-bin candidate: penalize mildly unless open bins have small residuals
    if bin_residual == bin_capacity {
        score += 12.0 + 4.0 * (mean_residual / cap) - 3.0 * progress;
    }
    // small smooth preference toward bins below mean residual
    score += 2.0 * ((post - mean_residual) / cap).tanh();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common item
    // sizes (10,20,25,50) are more reusable than odd dead space.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0
    } else if pr % 50 == 0 {
        -30.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 20 == 0 {
        -14.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr < 10 {
        25.0 // tiny unusable dead space
    } else {
        0.0
    };
    score += class_bonus;

    // Perfect-fit lookahead: if next item exactly fills post_residual, reward hard.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            // next item fits too: mild reward proportional to how snugly
            let slack_after_next = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack_after_next / cap);
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += 0.15 * pr as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave very awkward residues and the stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        score = cap * 0.9 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 80.0; // no alternative anyway
        }
    }

    // Prefer tighter fits overall: reward small post_residual relative to bin.
    score += 0.05 * (post_residual as f64 - mean_residual.abs());

    // Slight preference for keeping the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    // Integer-division threshold: leftover in [1..9] is worst; [10..19] ok.
    if pr >= 1 && pr / 10 == 0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals too small for typical future items are wasted.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residual that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the chance to fit the next item here.
            score += 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual > next_item_size {
            score -= 25.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // dead space relative to lookahead item
            score += 0.6 * (nxt - pr);
        }
    }

    // Penalize large unusable dead space (below min plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: discourage hoarding many bins; later: prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 && progress < 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space that is hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // If leftover is smaller than next item but close to zero, penalize.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 15.0 {
                score += 6.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure.min(10.0);
    }

    // Brand-new bin candidate: make it attractive only when no good fit exists
    // (i.e., this item leaves a large, awkward remainder in any open bin) or
    // the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let awkward = (post_residual as f64) < 20.0 && fitting_bins_count > 0;
        if awkward {
            score -= 20.0;
        } else {
            score += 18.0 + 0.05 * open_bins_count as f64;
        }
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild bonus for bins whose residual is near mean residual (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: small residuals are valuable dead space later in the stream
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (1.0 - progress);

    // Tight fit reward (non-linear in fill ratio)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill * fill;

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            score -= 5.0 * (diff / cap);
        } else {
            score += 3.0 * (-diff / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins below mean residual (more usable leftovers elsewhere)
    score += 0.05 * (pr - mean_residual);

    // Slight preference to keep fewer bins open
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes of post_residual (0 = perfect, 10 = great)
    match post_residual {
        0 => score -= 200.0,
        1..=5 => score -= 120.0,
        6..=10 => score -= 60.0,
        11..=20 => score -= 20.0,
        _ => {}
    }

    // Penalize large dead space relative to capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 50.0 * frac * frac;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty grows with number of open bins that could still be used
        score += 40.0 + 5.0 * open_bins_count as f64;
        // If current fit is poor (big residual left), opening a fresh bin becomes better
        if post_residual > 30 {
            score -= 60.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    } else {
        // Favor bins whose residual is below mean residual (denser bins)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if next item could fill the leftover exactly-ish, reward
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 45.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // leftover unusable by next item: mild penalty
            score += 8.0;
        }
    }

    // Harmonic modulo class on post_residual: multiples of 10 are "clean" leftovers
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // A post_residual that is too small to fit the smallest plausible item is waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Penalize tight fits that leave near-zero space only mildly; large dead space is worse.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny unusable slivers
    } else if pr >= 10.0 && pr < 25.0 {
        score += 8.0; // moderately awkward gap
    } else if pr == 0.0 {
        score -= 30.0; // perfect fit: strongly reward
    }

    // Reward filling bins deeply (low residual relative to capacity).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // rather than opening new ones; when few bins are open, new-bin cost is lower.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 10.0 * pressure * (0.5 + progress);
    } else {
        // Existing bin: reward slightly more when many bins are open.
        score -= 5.0 * pressure.min(3.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr).abs() < f64::EPSILON {
            score -= 50.0;
        } else if pr >= n && pr - n < 10.0 {
            score += 12.0; // would leave a sliver for the next item
        } else if pr >= n {
            score -= 10.0; // next item fits comfortably
        }
        // If next item cannot fit anywhere in post_residual, slight penalty for hoarding space.
        if pr < n && pr > 0.0 {
            score += 4.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins),
    // so we close out bins that are nearly full rather than spreading items.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= (100.0 - post_residual as f64) * 2.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - gap / 100.0);
            if post_residual == next_item_size {
                score -= 200.0; // chainable exact fit
            }
        } else {
            // next item cannot fit here; penalize proportionally to wasted lookahead
            score += 40.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins with residuals below average
    // (filling fuller bins first, keeping loose space for future items).
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // or the next item pairs better with a fresh bin.
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin can host a perfect pairing of item + next item
            if item_size + next_item_size == bin_capacity {
                score -= 500.0;
            }
        }
        if post_residual <= 20 {
            score -= 100.0; // tight fit in fresh bin is good
        }
    }

    // Slight preference to consolidate across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Early in the stream, be more liberal about opening bins (better packing later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 30.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space, normalized.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 20.0; // chain of perfect fits
            } else if gap < 10 {
                score -= 8.0;
            } else {
                score += gap as f64 * 0.15; // leaving awkward space for next item
            }
        } else {
            // post-residual too small for next item: dead space unless tiny
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score -= open_pressure * (bin_residual - post_residual) as f64 * 0.05;

    // Prefer bins below mean residual (more filled than average) when open pressure high.
    score += (bin_residual as f64 - mean_residual) * 0.10 * open_pressure;

    // Time horizon: early in stream, be conservative about tight fits (keep space flexible);
    // late in stream, exploit tight fits harder.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let tightness = 1.0 - waste_frac;
    score -= tightness * 20.0 * t;
    score += waste_frac * 10.0 * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 30.0;
        // but if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        // early stream: new bin cheap; late stream: expensive
        score -= 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, weighted more as stream progresses
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let gap = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        score += 0.15 * gap * (1.0 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Favor bins with residuals below the mean (consolidation)
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // New-bin candidate: penalize slightly unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = tightness < 0.85;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space
    let pr = post_residual;
    let harmonic_class = pr % 10;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward near-perfect fits (post_residual in small harmonic classes)
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= quarter {
        score -= 8.0;
    }

    // Penalize dead space in awkward harmonic bands (residuals that few items can use)
    if pr > quarter && pr < half {
        score += 10.0 + (harmonic_class as f64) * 0.5;
    }

    // Integer division thresholds: usable residual classes
    let usable = pr / 10; // how many "10-sized" slots remain
    if usable >= 3 {
        score -= 5.0;
    } else if usable == 0 && pr > 0 {
        score += 15.0; // tiny unusable sliver
    }

    // Coupling with next item: reward leaving exactly enough room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt && (post_residual as f64 - nxt) <= 10.0 {
            score -= 30.0; // chains the next item perfectly
        } else if post_residual < next_item_size {
            score += 12.0; // next item won't fit here
        }
        // harmonic match: post_residual mod 10 == next_item_size mod 10
        if pr % 10 == (next_item_size as u32) % 10 && pr >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no decent fit exists
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < item_size as f64;
        if fitting_bins_count == 0 || tight_exists {
            score -= 35.0;
        } else {
            score += cap * 0.5; // prefer filling existing bins
        }
    }

    // Progress-based mild tightening: late in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Mean residual coupling: penalize bins far below mean residual (fragmented)
    score += ((mean_residual - bin_residual as f64).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Near-dead gap: penalize extra.
        score += 15.0;
    }

    // Reward tight fits proportionally: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins / spreading items).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward this placement (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 8.0;
        } else if (next_item_size as f64) > post_residual as f64 {
            // Next item won't fit here anyway; slightly prefer keeping larger gaps.
            score += 5.0;
        }
    }

    // Prefer bins with residual below mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make opening a new bin costly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening may be fine.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins where next item fits the post residual exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 250.0; // chain-perfect fit
        }
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize wasted residual relative to next item
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize dead space that is too small for the minimum item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins with residual near/below mean (tight packing)
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: open a new bin only when current fits are poor
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; reduced when item is large relative to capacity
        score = bin_capacity as f64 * 0.55 - 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0; // fresh bin can also host next item
        }
        if fitting_bins_count <= 1 {
            score -= 80.0; // no good alternative exists
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward bins that leave room for the next item (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item fits almost perfectly after this one
        let chain_residual = post_residual - next_item_size;
        score -= 20.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residual too small for the next item (dead space)
        let waste = post_residual as f64 / (next_item_size as f64).max(1.0);
        score += 15.0 * (1.0 - waste.min(1.0));
    }

    // Penalize spreading across too many open bins; prefer consolidation
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates from the mean residual (diversity of gaps)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bin fits are poor
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        // Late in stream, opening new bins is less costly
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty -= 20.0 * progress;
        // If item is large, a fresh bin is attractive
        penalty -= 0.4 * item_size as f64;
        // If many bins fit the item, no need for a new one
        penalty += 6.0 * fitting_bins_count as f64;
        // If mean residual is large, existing bins have plenty of room
        penalty += 0.5 * mean_residual;
        score += penalty.max(0.0);
    }

    // Mild early-stream preference for filling bins aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Penalize small dead space non-linearly (wasted capacity)
    let dead = post / cap;
    score += 30.0 * (1.0 - dead) * (1.0 - dead) * dead;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - dead;
    score -= (10.0 + 40.0 * progress) * tightness * tightness;

    // Lookahead: reward leaving room for the next item, penalize near-misses
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 12.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Prefer consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;

    // New-bin candidate: make it attractive only when current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post - item) / cap;
        score += 8.0 + 20.0 * (1.0 - poor_fit.abs()) * (1.0 - progress);
    }

    // Smooth coupling with mean residual across open bins
    score += 0.15 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "useful" classes
    // (residuals >= 50 can host a typical item; tiny residuals are dead space).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit, ideal
    } else {
        let class = post / 10; // harmonic class 0..=9
        // Penalize dead-space classes more than mid classes
        let class_penalty = match class {
            0 => 25.0,           // 1..9 : nearly dead
            1 => 18.0,           // 10..19
            2 => 12.0,           // 20..29
            3 => 8.0,            // 30..39
            4 => 5.0,            // 40..49
            5 => 0.0,            // 50..59 : prime hosting class
            6 => 1.0,
            7 => 2.0,
            8 => 3.0,
            _ => 4.0,
        };
        score += class_penalty;

        // Lookahead: reward residuals that can host the next item exactly or well
        if next_item_size > 0 {
            if next_item_size <= post {
                // next item fits here: strong reward, exact fit best
                if next_item_size == post {
                    score -= 45.0;
                } else {
                    let slack = (post - next_item_size) as f64;
                    score -= 30.0 - slack.min(30.0) * 0.4;
                }
            } else {
                // next item won't fit: penalize proportionally to overshoot
                let over = (next_item_size - post) as f64;
                score += over.min(50.0) * 0.6;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: baseline score = full capacity; encourage opening a new bin
    // only when no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 25.0;
        // If many open bins already, mildly discourage proliferation
        score += open_bins_count as f64 * 1.5;
        // If next item is large, keep a fresh bin attractive
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Prefer bins tighter than average (good fit relative to fleet)
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64).min(30.0) * 0.5;
        }
    }

    // Late in the stream, consolidate: favor closing bins out (low post_residual)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 1..=100,
    // anything < ~10 is dead) get a steep nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium awkward gaps (cannot pair with typical items) get moderate penalty.
    else if post_residual >= 10 && post_residual < 25 {
        score += 2.5 * (25.0 - post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tight fit relative to residual: prefer bins where item fills most of the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is close to the item (avoid wasting large residual bins on small items).
    score += 0.25 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = post_residual as f64 > 0.5 * bin_capacity as f64;
        if big_item || poor_fit {
            score -= 10.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item barely misses, slight penalty for stranding space.
    if next_item_size > post_residual && next_item_size - post_residual <= 3 && post_residual > 0 {
        score += 5.0;
    }

    // Mild attraction to bins below mean residual (consolidate emptier bins).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the lookahead item (k=2).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        }
    }

    // Penalize unusable dead space (residual too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits relative to the current bin's residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Coupling with mean residual: prefer bins that keep the fleet balanced,
    // penalize bins whose post-residual deviates strongly from the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 70.0 + 10.0 * pressure;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 20.0; // fresh bin still serves the lookahead item
        }
    }

    // Late-stream consolidation: prefer compacting into fewer bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 40.0;

    // Penalize creating dead space that can't hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual == next_item_size {
            score -= 25.0; // perfect lookahead fit
        } else {
            score -= 5.0;
        }
    } else {
        // Last item: strongly prefer filling bins as much as possible.
        score -= item_size as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Time horizon: early on, keep bins open (penalize new-bin tendency less as stream ends).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more when many bins are open early;
        // less penalized late when consolidation matters less.
        score += 20.0 + open_bins_count as f64 * 2.0 * (1.0 - progress);
        // But if no existing bin fits well, allow opening.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large and mean residual is small, new bin is attractive.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight bonus for using bins with small residuals (consolidation).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Mild preference for bins whose residual is an exact multiple relationship with item.
    if bin_residual == item_size {
        score -= 35.0; // perfect fill
    }

    // Penalize very small unusable residuals unless it's the last item.
    if post_residual > 0 && post_residual < 10 && next_item_size > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = (1.0 - norm_post).powi(3);
    score -= 12.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize mid-range dead space (quadratic bowl in post_residual)
    let dead = norm_post * (1.0 - norm_post);
    score += 8.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward leaving room for next item (smooth interaction)
    let next_norm = next_item_size as f64 / bin_capacity as f64;
    if next_item_size > 0 {
        let gap = (norm_post - next_norm).abs();
        score -= 6.0 * (1.0 - gap).max(0.0) * (1.0 - gap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, more when many bins open or item fits well elsewhere
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 + 20.0 * norm_item;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidation)
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 4.0 * (norm_post - mean_norm) * (norm_post - mean_norm).signum() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands in "reusable"
    // classes (multiples of 10, or large enough halves) are favored.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect closure
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        4.0 // awkward dead space
    };
    score += class_bonus;

    // Integer-division thresholds: small leftovers (< smallest plausible item)
    // are dead weight.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr >= 50 {
        score -= 8.0; // roomy bin stays flexible
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: penalize bins whose leftover can't host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
        // Harmonic pairing: leftover divisible by next item size is ideal.
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate logic: empty bin gets baseline cost; open it only when
    // no open bin offers a good (tight) fit.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.25 * mean_residual + 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // stacking large items together is fine
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild stream-phase drift: early on, prefer consolidation.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - phase);

    // Nudge toward bins near the mean residual (balanced packing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Gaps too small for the smallest possible item are pure waste.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with open-bin pressure: when many bins are open,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item is large and would not fit anywhere after this placement,
    // slightly penalize creating a bin that blocks it.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        score += 10.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // fits well (residual waste would be large) or few bins are open.
    if bin_residual == bin_capacity {
        let avg_waste_if_existing = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count > 0 && avg_waste_if_existing < 15.0 {
            // Existing bins fit decently: discourage opening a new bin.
            score += 120.0 + 20.0 * (open_bins_count as f64).ln().max(0.0);
        } else {
            // Poor fits elsewhere: mildly favor a fresh bin, less so late in stream.
            score = 10.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score -= 40.0 / post_residual as f64;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * next_item_size as f64;
        // Perfect chaining: next item leaves a small remainder too.
        let chain_residual = post_residual - next_item_size;
        score -= 6.0 / (1.0 + chain_residual as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.08 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Relative-to-mean coupling: prefer bins whose residual after placement
    // sits below the mean residual (tight packing of fuller bins).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits badly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is cheaper (less fragmentation risk).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly or well in the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 60.0 - slack_after_next as f64 * 3.0;
            } else {
                score -= 10.0 / slack_after_next as f64;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap that is just below next size (dead space).
            let gap = post_residual as i64 - next_item_size as i64;
            if gap > -10 && gap < 0 {
                score += (10 + gap) as f64 * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual > 40 {
            score += 30.0; // poor fit but last chance: still mild penalty for wasted space
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 60.0 + mean_residual * 0.5;
        score = base
            + if fitting_bins_count == 0 { -100.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size > bin_capacity as u32 - item_size { 0.0 } else { 20.0 };
        // Late in the stream, opening new bins is less desirable (leftover bins get wasted).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Slight preference to keep number of open bins low early on.
    score += open_bins_count as f64 * 0.3 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, minimize leftover (tight packing); later, tolerate slack.
    let progress_weight = 0.6 + 0.8 * progress;
    let mut score = post * progress_weight + 0.004 * post * post;

    // Reward filling bins tightly (small post_residual relative to capacity).
    let fill_ratio = post / cap;
    score -= 18.0 * (1.0 - fill_ratio) * (1.0 - fill_ratio);

    // Smooth interaction: residual vs. mean residual across open bins.
    // Placing into a bin whose residual deviates low from the mean is good.
    score += 0.35 * (post - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Cubic smooth penalty for dead space that can't fit typical items.
    let dead = if post > 0.0 { post * post * post / (cap * cap) } else { 0.0 };
    score += 0.02 * dead;

    // Lookahead coupling: if next item fits perfectly into post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving a residual just barely too small for next item.
        if post < nxt && post > 0.0 {
            score += 6.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when few fitting bins
    // or the item is huge relative to capacity (smooth sigmoid gate).
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    let big_item = (item / cap - 0.5).max(0.0) * 2.0;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - scarcity) * (1.0 - 0.5 * big_item);
        score -= 10.0 * scarcity;
        // Late in stream, prefer reusing open bins to limit bin count.
        score += 15.0 * progress * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
    }

    // Mild penalty for opening many bins early.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction bucket it falls in.
    // Classes: q = post_residual * 4 / capacity  -> 0..3 (quarter classes)
    let q = (post_residual * 4) / bin_capacity; // integer division threshold class
    let class_penalty: f64 = match q {
        0 => 0.0,          // nearly perfect fit
        1 => 6.0,          // small dead space
        2 => 14.0,         // medium gap
        _ => 22.0,         // large gap
    };

    let mut score = post;

    // Non-linear reward for tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness;

    // Harmonic-class penalty.
    score += class_penalty;

    // If the next item would fit in the post residual, this bin is a good
    // two-item carrier; reward proportionally to how snugly next item fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * snug;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: dead space likely.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            // Penalize opening a new bin when alternatives exist,
            // scaled by how much capacity is being abandoned elsewhere.
            (mean_residual / cap).clamp(0.0, 1.0) * 40.0
        };
        score = cap as f64 * 0.9 + desperation;
        // Early in the stream, opening bins is cheaper (builds a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Medium dead space (11..=20) is also risky since items are >= 1 but often larger.
    if post_residual > 10 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (perfect packing).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Exact match with lookahead: strongly favor bins where the next item fits the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize leaving a residual that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // New-bin candidate: baseline cost, cheaper only when mean residual across open bins is low
    // (open bins are nearly full, so a fresh bin is justified).
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.6;
    } else {
        // Slight preference for bins whose residual is close to the item (best-fit flavor).
        score -= (bin_residual as f64 - item_size as f64).abs() * -0.0;
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (small dead space) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Perfect chaining: next item exactly consumes post_residual.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize residual that the next item cannot use (likely dead space).
            let waste = (next_item_size as u32 - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual.max(1.0);
        score += 10.0 * rel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 45.0
            + 0.2 * (open_bins_count as f64)
            + 0.3 * item_size as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }
    // Penalize leaving residual that is too small for any plausible item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bins are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.5;
        score += if tight { 40.0 } else { 120.0 };
        // Early in stream, opening bins is cheaper; late, prefer filling existing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item size (best-fit refinement)
    score += 0.3 * ((bin_residual - item_size) as f64).powi(2) / bin_capacity as f64;

    // Slight preference for bins below mean residual (consolidating slack)
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    // Reward using bins with many open bins (reduce bin count pressure)
    score -= 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted space, amplified over stream progress.
    let mut score = post * (1.0 + 1.5 * progress) + 0.35 * post * post / cap;

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: bonus if the next item fits well into the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 6.0 * (1.0 - slack / cap) * (1.0 - progress * 0.5);
        } else {
            // Penalize residuals that are too small for the next item (dead space).
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: make it unattractive unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            (mean_residual - item_size as f64).max(0.0) / cap
        };
        score = cap + 25.0 - 20.0 * poor_fit_pressure - 8.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins below-mean residual (denser bins).
    score += 0.08 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: reward residuals in "useful" classes
    // (multiples of common item sizes / small remainders), penalize awkward ones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 40.0; // near-perfect fit, dead space negligible
    } else if pr % 10 == 0 {
        score -= 12.0; // harmonic with the 10-grid
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else {
        score += (pr % 5) as f64 * 2.5; // awkward remainder penalty
    }

    // Penalize leaving residual that no plausible next item can use well:
    // if next item exactly fits, big reward; if next item can't fit at all, penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr && pr - next_item_size <= 5 {
            score -= 25.0;
        } else if next_item_size > pr {
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = (fitting_bins_count as f64).recip();
        score = 0.5 * cap + fit_pressure * 20.0 + progress * 10.0
            - (mean_residual / cap) * 15.0;
        // Opening new bins early is expensive when few bins are open.
        score += (open_bins_count as f64).ln() * 4.0;
    }

    // Slight preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Coupling: penalize waste relative to mean residual state of the fleet.
    score -= (mean_residual - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: gaps too small to hold the next item (or any plausible item).
    let min_gap = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && post_residual < min_gap {
        score += 25.0 + (min_gap - post_residual) as f64;
    }

    // Reward leaving room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize wasting space larger than next item but close to it.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 8.0;
    }

    // Last chance: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening existing bins;
    // when few bins are open, tolerate spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: only attractive when current item is large relative to capacity
    // and existing residuals are small; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 12.0 - 10.0 * large_item + (mean_residual * 0.05);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild non-linear penalty
    // on very small residuals that become dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Aggressive 2-step lookahead: reward a perfect or near-perfect match of the
    // NEXT item into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            // Perfect chaining: post_residual exactly fits next item -> strong reward.
            score -= 12.0 * (1.0 - slack / cap);
            // Extra bonus for exact match.
            if slack == 0.0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit here: mild penalty proportional to overshoot,
            // so bins whose leftover is "just barely too small" are deprioritized
            // (wasted capacity the lookahead could have used elsewhere).
            score += 0.10 * (nxt - pr);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are already
    // well-filled; placing here keeps fragmentation concentrated.
    let rel = pr - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the fit is
    // truly poor in existing bins. Scaled down as stream progresses and when many
    // bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0;
        new_bin_score -= 20.0 * progress;
        new_bin_score += 2.0 * open_bins_count as f64;
        // If next item is large and would pair well with a fresh bin, soften penalty.
        if next_item_size > 0 && (next_item_size as f64) >= 0.6 * cap {
            new_bin_score -= 10.0;
        }
        score += new_bin_score;
    }

    // Late-stream tightening: as we approach the end, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize small dead space that nothing can use (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    if post_residual >= 10 && post_residual <= 20 {
        score -= 4.0; // usable pocket for small items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist; prefer best fit among them.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let lookahead_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= lookahead_fit * 10.0;
        } else {
            // post_residual too small for next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prefer closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.2;
    score -= progress * 5.0;

    // Global state coupling: if mean residual is high, prefer bins below mean
    // (consolidate), otherwise spread.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Many open bins: encourage filling existing ones rather than opening new.
    if open_bins_count > 3 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate bias: empty bin should only win when fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 15.0 + post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / c;
    let norm_pr = pr / c;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = norm_pr * (1.0 + 0.9 * norm_pr);

    // Smooth progress coupling: late in stream, waste is more costly
    let late = progress * progress;
    score += 2.5 * late * norm_pr;
    score -= 0.8 * progress * fit_ratio;

    // Perfect fit reward (smooth gaussian-like bump)
    let perfect = (-norm_pr * norm_pr * 40.0);
    score += perfect - 1.0;

    // Penalize post-residual that next item can't use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / c;
        score += 1.6 * gap * gap;
        let usable = (pr - next_item_size as f64).max(0.0) / c;
        score -= 0.9 * usable;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.5 * late;
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.3 * ((pr - mean_residual) / c);

    // New-bin candidate: penalize slightly unless current fit is bad
    let new_bin = (bin_residual as f64 - c).abs() < 0.5;
    if new_bin {
        score += 0.6 - 1.4 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / (bin_capacity / 4).max(1)) as f64; // 0..4 harmonic class
    score += class * 3.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Modulo coupling: post_residual matching next item's class is valuable.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 15.0 + 0.5 * (pr - n);
        } else {
            score += 0.3 * (n - pr); // dead space unusable by next item
        }
        // Harmonic residue match: post_residual % next_item_size small
        if post_residual % (next_item_size.max(1)) <= 2 {
            score -= 8.0;
        }
    }

    // New-bin candidate: only prefer when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        if pressure == 1 {
            score -= 40.0;
        } else {
            // penalize opening new bin; scale with how wasteful open bins are
            score += 25.0 + 0.4 * mean_residual + (open_bins_count as f64) * 2.0;
            // late in stream, reuse bins more aggressively
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 10.0 * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins already below mean residual (consolidate slack).
    score += 0.2 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are worthless.
    if post_residual < 10 {
        score += 40.0; // creating a dead gap is bad
    } else {
        // Reward tight fits: smaller post_residual relative to item size is better.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 25.0 * tightness;
    }

    // Penalize mid-range unusable gaps (too small for most items, too big to ignore)
    if post_residual >= 10 && post_residual < 30 {
        score += 0.35 * (30 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    let bin_pressure = open_bins_count as f64 * 1.5;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin wastes capacity equal to residual,
    // so make it attractive only when this bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral baseline, slightly penalized to prefer reusing bins with tight fits.
        score = post_residual as f64 + 5.0;
        // If the current item would leave a dead gap in any open bin, prefer a fresh bin.
        if fitting_bins_count > 0 {
            let worst_gap_bonus = 0.0;
            score -= worst_gap_bonus;
        }
        // Encourage new bin when many bins are open but none fit tightly.
        if fitting_bins_count == 1 {
            // still prefer last-chance reuse
            score += 20.0;
        }
    }

    // Lookahead: if next item fits perfectly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial lookahead reward proportional to how well next item uses the gap
        let usage = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 12.0 * usage;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if mean residual is low, bins are nearly full; reward using them.
    score += 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits — penalize large post_residual nonlinearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if diff < 1.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if nx <= pr {
            // next item fits here: reward proportional to how well it chains
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving space that strands the next item
            score += 12.0 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Compare against mean residual: bins with residual below mean are "tighter" — prefer using them.
    score -= 8.0 * (mean_residual - pr) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make fresh bins moderately attractive only when item is large
    // relative to residual spread, otherwise discourage wasting a fresh bin.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 20.0 * fill_ratio;
        } else {
            score += 15.0 * (1.0 - fill_ratio);
        }
    }

    // Late in the stream: be greedier about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * pr / bin_capacity as f64;

    // Prefer bins that leave residuals unlikely to be wasted (multiples of common sizes).
    let pr_int = post_residual;
    if pr_int >= 1 && pr_int <= 5 {
        score -= 5.0; // tiny leftover is near-perfect usage
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that cannot fit the smallest plausible item (1..100 unknown dist).
    let dead = (post_residual as f64 / 10.0).floor();
    if dead < 1.0 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0;

    // When many bins are open, discourage spreading; favor filling existing ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make it unattractive unless the item barely fits any open bin.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 55.0 - 45.0 * desperation + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Quadratic/cubic shaping: small residuals strongly favored, large ones penalized more late in stream
    score += 0.35 * pr_norm * pr_norm * cap * (0.5 + progress);
    score -= 0.25 * (1.0 - pr_norm) * (1.0 - pr_norm) * cap * (0.3 + 0.7 * progress);

    // Tight fit reward (smooth cubic on wasted space)
    let waste = pr / cap;
    score -= 12.0 * (1.0 - waste).powi(3);

    // Last-chance bin bonus (avoid opening new bins when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 10.0 * fit_quality * (1.0 - fit_quality) * 4.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize creating dead space that next item cannot use
        score += 4.0 + 6.0 * (post_residual as f64 / cap) * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are large
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 18.0 * avg_fullness * avg_fullness + 10.0 * progress;
    }

    // Mild preference for fuller bins relative to mean residual
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (post_residual small)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic class: how well post_residual matches a "reusable" size class
    // Small residuals (< 10) are dead space; residuals in [10..=80] are reusable.
    if post_residual < 10 {
        score += 60.0; // dead-space penalty
    } else if post_residual >= 10 && post_residual <= 80 {
        score -= 40.0; // reusable for typical items
    }

    // Modulo-10 granularity: residuals that are multiples of 10 align with
    // common item sizes (items often quantized), favor them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += 25.0; // next item can't use this residual
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: opening a new bin is generally wasteful unless
    // the current fit is terrible. Penalize new bins by default.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if item is huge relative to capacity, a fresh bin may be fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 100.0;
        }
    }

    // Prefer bins with lower residual overall (pack fuller bins first),
    // scaled mildly by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * (0.3 + 0.2 * progress);

    // Prefer reusing bins over accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps (below typical minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Penalize gaps that cannot fit the lookahead item (wasted for k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item.
        score -= 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 15.0 + 2.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Reward filling existing bins more when many bins are open.
        score -= 0.3 * open_bins_count as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer bins with residual below mean (tighter bins get filled first).
    score += 0.4 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_tightness;
        } else {
            // Post-residual is dead space for the next item.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 18.0 * waste;
        }
        // Perfect chain: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (consolidating fullness) unless the fit is poor.
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Penalize leaving large unusable gaps relative to typical item scale.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny dead space is fine (near-perfect fill)
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 60.0;
        // Attractive to open a new bin when item is huge and current open bins
        // would be left with fragmented residuals.
        if item_size >= 70 {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If the item fits perfectly in a fresh bin and no open bin chains well,
        // allow opening (offset base penalty partially).
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && post_residual == bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Slight penalty per open bin to encourage consolidation when many are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Perfect-fill bonus (post_residual == 0).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post residual too small for the smallest plausible item (1..100 unknown, use 10 as conservative floor only if stream seems bounded; use item_size-relative measure instead).
    let dead_zone = (post_residual as f64) / cap;
    if dead_zone > 0.0 && dead_zone < 0.12 {
        score += 18.0 * (0.12 - dead_zone) / 0.12;
    }

    // Lookahead: reward if next item fits exactly/well into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 30.0 * next_tight * next_tight;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover waste.
            score += 6.0 * (next_item_size as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= crowd * 2.0 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is below mean (it's "dying"), prefer filling it.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        if rel < 1.0 {
            score -= 10.0 * (1.0 - rel);
        } else {
            score += 4.0 * (rel - 1.0);
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if next item is huge and this item is small, a fresh bin may be attractive later; slight relief.
        if next_item_size > 60 {
            score -= 12.0;
        }
        // Late in stream, opening a bin is less costly (no future to amortize).
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - pr / cap; // how full the bin becomes (0..1)

    let mut score = pr;

    // Reward tight fits, amplified as the stream progresses (smooth polynomial coupling)
    score -= fit_ratio * fit_ratio * (40.0 + 60.0 * progress);

    // Penalize dead space that likely becomes unusable: small post_residual is good,
    // but very small residuals (< typical min item) are wasted — smooth quadratic term
    let waste = if pr < 10.0 { 10.0 - pr } else { 0.0 };
    score += waste * waste * 0.05;

    // Lookahead coupling: favor leaving room for the next item when it fits well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let nxt_fit = 1.0 - (pr - nxt) / cap;
            score -= nxt_fit * nxt_fit * 30.0;
        } else {
            // next item won't fit here: slight penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so early on
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { cap };
        score += 30.0 + 40.0 * (1.0 - progress) + 0.1 * avg_open;
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 4.0).floor(); // 0: <=25%, 1: <=50%, 2: <=75%, 3: <=100%

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 200.0 - (post_residual as f64) * 5.0;
    }

    // Penalize leaving awkward mid-range dead space (class 1 leftovers are least reusable).
    match class as u32 {
        0 => score -= 30.0,                       // tiny leftover: nearly full bin, good
        1 => score += 60.0,                       // 25-50% leftover: awkward zone
        2 => score += 10.0,                       // 50-75% leftover: moderately reusable
        _ => {}                                   // mostly empty bin
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Reward chains where leftover accommodates the next item exactly-ish.
            let chain_waste = post_residual - next_item_size;
            score -= 80.0 - (chain_waste as f64).min(80.0);
        } else {
            // Penalize leftovers that strand the next item.
            score += 40.0 + 0.5 * (nxt - pr).min(60.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize mildly, but more when many bins are open
    // and mean residual is large (fragmentation pressure).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score += 120.0 + 40.0 * (open_bins_count as f64).ln().max(0.0) - 60.0 * frag;
        // Opening a new bin is fine if item is large and would badly fragment an open bin.
        if item_size as f64 > 0.7 * cap {
            score -= 50.0;
        }
    }

    // Prefer filling bins whose residual is far below the mean (reduce variance).
    score -= 0.3 * (mean_residual - pr).max(0.0);

    // Slight time pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100) are dead.
    // The minimum future item size is 1, but realistically small gaps (< ~10) are dead.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0; // heavy penalty for unusable slivers
    }

    // Reward near-perfect fits super-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * tightness * 40.0;

    // Penalize moderate leftover gaps that likely waste space, but reward gaps that
    // can still host plausible future items.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < item_size as f64 {
            // gap smaller than the item that just came: harder to reuse
            score += gap * 0.35;
        } else {
            score -= gap * 0.15;
        }
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / cap) * 15.0;
    } else if next_item_size > 0 {
        // next item cannot use this bin's remainder: mild penalty scaled to gap uselessness
        let gap = post_residual as f64;
        if gap < next_item_size as f64 {
            score += (next_item_size as f64 - gap).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only if existing bins fit poorly or few are open.
        score = cap * 0.6
            + open_bins_count as f64 * 2.0
            + progress * 20.0
            - (mean_residual / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    } else {
        // Prefer filling already-open bins; slight bias toward bins below mean residual
        // (i.e., fuller bins) to consolidate space.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 / (1.0 + gap);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize if next item cannot fit here anyway and we waste space.
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when all open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If item would leave a large unusable residual in existing bins, new bin is fine.
        let worst_waste = (mean_residual - item_size as f64).max(0.0);
        score -= 0.4 * worst_waste;
        // Fewer open bins -> opening new bins is cheaper early on.
        score -= 2.0 * (open_bins_count as f64).min(10.0);
        // Perfect fit in fresh bin (item exactly fills capacity).
        if item_size == bin_capacity {
            score -= 60.0;
        }
    }

    // Mild stream-progression pressure: later in stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward placements that leave little usable-but-awkward space.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: small post-residuals that are unusable relative to
    // the minimum plausible next item are fine; mid-range residuals are wasteful.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 6.0; // near-perfect fill
        } else if next_item_size > 0 && (next_item_size as f64) > pr {
            // residual cannot fit the lookahead item: potential dead space
            score += 0.35 * (pr / 10.0).ln().max(0.0) * 10.0;
        }
    }

    // Lookahead synergy: reward if the lookahead item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else or global residuals are high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        // penalize opening new bins mildly when existing bins are roomy
        score += 18.0
            - 0.5 * crowd
            - 10.0 * progress
            - (mean_residual / bin_capacity as f64) * 8.0;
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: must open
        }
        if item_size >= 80 {
            score -= 5.0; // large items pair well with fresh bins
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (balance-seeking).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Late-stream consolidation: as the stream progresses, fill existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling: post_residual normalized by capacity, shaped by progress
    let post_norm = post / cap;
    let coupling = post_norm * post_norm * (1.0 + progress) * 50.0;
    score += coupling;

    // Reward tight fits more strongly as the stream progresses
    let tightness = (item_size as f64 / bin_residual.max(1) as f64).powi(2);
    score -= 30.0 * tightness * (0.5 + progress);

    // Penalize dead space below smallest plausible item threshold smoothly
    let dead = ((15.0 - post).max(0.0)) / 15.0;
    score += 25.0 * dead * dead * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - post_norm);
    }

    // Lookahead: bonus if the next item can use the post residual
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let reuse = 1.0 - (gap / cap).min(1.0);
        score -= 20.0 * reuse * reuse;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when open bins exist with mean residual
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).sqrt();
        score += 15.0 + 2.0 * crowd + 0.2 * mean_residual;
    }

    // Mild penalty for many open bins relative to progress (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: sizes near multiples of 10 form "harmonic classes".
    // Class 0 items (multiples of 10) pack cleanly; oddball sizes create dead space.
    let item_class = item_size % 10;
    let class_penalty: f64 = match item_class {
        0 => 0.0,
        1..=2 => 2.0,
        3..=4 => 5.0,
        5 => 4.0,
        6..=7 => 7.0,
        _ => 10.0,
    };

    // Harmonic class of the residual: residuals that are multiples of 10 are
    // reusable by future class-0 items; odd residuals are likely dead space.
    let resid_class = post_residual % 10;
    let resid_penalty: f64 = match resid_class {
        0 => 0.0,
        1..=2 => 3.0,
        3..=4 => 6.0,
        5 => 5.0,
        6..=7 => 8.0,
        _ => 12.0,
    };
    score += resid_penalty * (post_residual as f64 / bin_capacity as f64);

    // Reward perfect or near-perfect fits via integer-division thresholds.
    let fit_quotient = post_residual / 10;
    let fit_bonus: f64 = match fit_quotient {
        0 => 30.0, // post_residual < 10: bin essentially sealed, excellent
        1 => 20.0,
        2 => 10.0,
        _ => 0.0,
    };
    score -= fit_bonus;

    // If the next item would exactly fill this bin's post-residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial harmony: next item leaves a class-0 residual too.
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 8.0;
        }
        if next_post < 10 {
            score -= 12.0;
        }
    } else {
        // Next item cannot use this residual: penalize proportionally.
        score += 6.0 + class_penalty;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good harmonic fit (post_residual small or harmonious).
    if bin_residual == bin_capacity {
        // Base cost of a new bin: high unless item is class-0 (packs predictably)
        // and the stream is early (many future items to fill the new bin).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 + 30.0 * progress;
        if item_class == 0 {
            new_bin_cost -= 10.0;
        }
        if next_item_size > 0 && next_item_size % 10 == 0 && next_item_size <= bin_capacity - item_size {
            new_bin_cost -= 5.0;
        }
        // If many open bins fit the item, opening a new bin is wasteful.
        new_bin_cost += 8.0 * (fitting_bins_count as f64).min(4.0);
        score = score.max(0.0) + new_bin_cost;
        return score;
    }

    // Penalize leaving residual far from mean (wasted spread across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest item (1..100 range, but typical min ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins are open
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit but would fit a fresh bin, penalize less if post_residual is tiny
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate baseline: make empty bins moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score += diff * 2.0;                    // penalize mismatch magnitude
        if post_residual == next_item_size {
            score -= 60.0;                      // strong reward for exact chain fit
        }
        // Small leftover that next item cannot use is dead space
        if post_residual > 0 && (post_residual as f64) < nxt {
            score += (nxt - post_residual as f64) * 1.5;
        }
    }

    // Penalize very small unusable leftovers (dead space) nonlinearly
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 4.0;
    }

    // Favor tight fits relative to mean residual across open bins
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (mean_residual - post_residual as f64) * (0.5 + 0.5 * t);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score = waste - 20.0 + 30.0 * (1.0 - t);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // chain-friendly fresh bin
        }
    }

    // Slight preference to fill existing bins as stream progresses
    score += open_bins_count as f64 * 0.5 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (quadratic waste penalty).
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Reward bins whose residual closely matches the item (exactness bonus).
    let fit_gap = (bin_residual as i64 - item_size as i64) as f64;
    score -= (bin_capacity as f64 - fit_gap.abs() * 2.0).max(0.0) * 0.15;

    // Lookahead: if the next item fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Post-residual too small for next item: penalize proportionally to dead space.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 4.0 * dead;
        }
    } else {
        // Last item: minimize waste only.
        score += 0.2 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        // More competitors: mild penalty to spread load when many bins fit.
        score += 0.3 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: prefer filling bins below mean residual
    // (consolidate emptier bins, keep uniform residuals for future items).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be greedier about filling bins tightly
    // and more reluctant to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - waste / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized late, and when few open bins.
        score += 3.0 + 12.0 * progress + 0.4 * open_bins_count as f64;
        // But if item is large and would leave almost no waste elsewhere, allow it.
        score -= 0.02 * item_size as f64;
    }

    // Many open bins: encourage closing them out (favor bins with small residual).
    if open_bins_count > 4 {
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let fit_fraction = it / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Non-linear polynomial coupling: tight fits are rewarded more as stream progresses
    let tightness = 1.0 - (pr / cap);
    let tightness_sq = tightness * tightness;
    score -= 12.0 * tightness_sq * (0.4 + 0.6 * progress);

    // Penalize residual that cannot fit a typical future item (non-linear dead-space term)
    let dead = if pr < 10.0 { (10.0 - pr) * 0.0 } else { 0.0 };
    let _ = dead;
    let unusable = (cap - pr) / cap; // fraction used
    score -= 8.0 * unusable * unusable * (1.0 - progress);

    // Lookahead: reward if post_residual accommodates next item, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: baseline slightly above good fits, cheaper early, costlier late
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.45 * progress) + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.9 {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes on post_residual.
    let cls = post_residual % 10;
    // Penalize "bad" leftover classes that are hard to fill (just above common small sizes).
    let bad_class = matches!(cls, 1 | 2 | 3 | 9);
    if bad_class {
        score += 6.0;
    } else if cls == 0 {
        // Perfectly round leftover is highly reusable.
        score -= 8.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 12.0 / (1.0 + tightness);

    // Integer-division thresholds on post_residual: dead-space zones.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // nearly unusable dead space
    } else if post_residual >= 50 {
        score += (post_residual as f64 - 50.0) * 0.4; // wasteful large leftover
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize if this bin would be left stranded
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // existing bins would create bad classes or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = bin_capacity as f64 - 5.0 * (1.0 - progress) + desperation;
        // If all fits are bad-class, opening fresh is fine.
        if bad_class && fitting_bins_count > 0 {
            score -= 4.0;
        }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Open-bin pressure: penalize placements when many bins are open,
    // unless the fit is very tight.
    let bin_pressure = open_bins_count as f64 * 0.5;
    score += bin_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.2;
    }

    // Lookahead coupling: if the next item fits in the post_residual,
    // reward this placement (keeps bins useful for the future).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.4;
    }

    // Stream progression: late in the stream, be more conservative
    // about leaving large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual is already low,
    // add extra subtraction proportional to tightness).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin is ideal for the next item
        } else if next_item_size < post_residual {
            // next item fits but leaves more waste: partial reward decaying with gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + gap);
        } else {
            // next item cannot use this bin's leftover: penalize relative to waste
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.15 * unusable;
        }
    }

    // Compare post_residual against mean residual: leaving much more space than
    // average is fine (keep big bins flexible); leaving much less than average
    // while not being a tight fit is wasteful fragmentation.
    if post_residual as f64 > mean_residual + 10.0 {
        score -= 5.0; // preserves flexibility relative to fleet average
    } else if (post_residual as f64) < mean_residual - 10.0 {
        score += 5.0; // over-fragmenting relative to the fleet
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // But if item is large relative to capacity or many bins are open with
        // high mean residual, opening fresh can be better.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0; // big items pair poorly; fresh bin helps
        }
        if mean_residual > 0.0 && (mean_residual < item_size as f64) {
            score -= 10.0; // existing residuals can't even fit item well
        }
        if open_bins_count > 8 && progress < 0.9 {
            score -= 5.0; // too many open bins: consolidation pressure
        }
        // Never open a new bin for a tiny item.
        if item_size <= 20 {
            score += 40.0;
        }
    }

    // Small bonus for using bins that are already fairly full (reduce bin count).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if (next_item_size as u32) > post_residual {
            // Lookahead cannot use the leftover: penalize proportional to waste.
            score += (post_residual as f64) * 0.8;
            // If the lookahead would fit a fresh empty bin better, discourage blocking here.
            if next_item_size as f64 > mean_residual {
                score += 15.0;
            }
        } else {
            // Lookahead fits in the leftover: reward this bin.
            score -= (next_item_size as f64).min(post_residual as f64) * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid fragmentation).
    let bin_pressure = open_bins_count as f64 / 10.0;
    score += bin_pressure * (post_residual as f64) * 0.3;

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin — slightly prefer filling it down toward the mean.
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score -= diff * 0.25;
    } else {
        score += (-diff) * 0.15;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good for large items or late in the stream,
        // bad when the item is small and existing bins are roomy.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let open_bonus = if item_frac > 0.5 { 25.0 } else { -10.0 };
        score += 60.0 - open_bonus - progress * 30.0;
        // If no open bin fits except this new one, opening is natural.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: as the stream ends, squeeze into open bins.
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: waste after placement, with non-linear curvature (small residuals matter more)
    let mut score = post * (1.0 + 0.015 * post / cap) + 4.0 * (post / cap).powi(2) * cap;

    // Smooth coupling of waste with stream progress: later in stream, waste is costlier
    score *= 1.0 + 0.6 * progress * (post / cap);

    // Perfect fit reward (smooth, non-piecewise)
    score -= 12.0 * (-post as f64).exp() * (1.0 + progress);

    // Lookahead: reward residual that exactly fits next item, penalize blocking it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (-gap / cap).exp() * (1.0 - 0.5 * progress);
        score += 0.02 * post.max(nxt - post).max(0.0);
    }

    // Penalize opening a new bin when existing bins can fit
    if is_new_bin {
        score += 18.0 + 6.0 * (fitting_bins_count as f64).powf(0.5);
        score *= 1.0 + 0.3 * progress;
    } else {
        // Last-chance bin gets a strong reward to avoid opening new bins
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward packing into bins with residual below mean (consolidation)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 12.0; // perfect closure
    } else {
        // Modulo classes: residuals that match common item sizes are reusable.
        let r = post_residual;
        if r % 10 == 0 {
            score -= 5.0;
        } else if r % 5 == 0 {
            score -= 2.5;
        }
        // residual in "awkward" classes 1..4 mod 10 is hard to fill
        if r % 10 >= 1 && r % 10 <= 4 && r < 40 {
            score += 4.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 3.0 * frac;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / bin_capacity as f64);
        let bad_fit = (item_size as f64 / bin_capacity as f64) < 0.5 && frac > 0.0;
        // Empty bin score = its own baseline; make it unattractive by default
        score += 25.0;
        if pressure > 3.0 || bad_fit {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 5.0;
        }
    }

    // Mild stream-progress adaptation: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress) * frac;
    score += 6.0 * progress * frac;

    // Prefer bins below mean residual (consolidating emptier bins keeps big residuals together).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min size 1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small usable post_residual) quadratically.
    if post_residual > 0 {
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here later; mildly reward leaving compatible space.
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).min(1.0);
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when no open bin fits well
    // (empty bin starts with score = capacity; adjust by context).
    if bin_residual == bin_capacity {
        score -= 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, opening fresh bins is less wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins below-average filled
    // (keep balance so many bins stay usable).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but not zero residual (dead space of 0 is great only if truly used).
    // Penalize residual that is too small to ever be useful (below typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < f64::EPSILON {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 30.0 * (1.0 - slack); // next item fits well here
        } else {
            // next item does NOT fit after this placement -> penalize proportionally
            let miss = (next - post_residual as f64) / bin_capacity as f64;
            score += 40.0 * miss;
        }
        // Coupling: if next item is huge, prefer bins that will be nearly emptied
        if next_item_size >= 60 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: just minimize residual
        score += 0.0;
    }

    // Relative to mean residual: bins with residual far below mean are "tight" -> good to fill.
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance: if this is the only bin that fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; lookahead decides: if next item is large, new bin is fine.
        score = 50.0 + post_residual as f64;
        if next_item_size >= 70 {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            // an existing bin is the last chance -> new bin should lose
            score += 70.0;
        }
    }

    // Late-stream consolidation: as stream progresses, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), especially relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // residual remains useful for next item
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap; // dead space penalty
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless residuals are large.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln_1p();
        let mean_useful = mean_residual / (bin_capacity as f64);
        score += 15.0 + 5.0 * pressure - 10.0 * mean_useful;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 6.0; // new bin useful for upcoming bigger item
        }
    }

    // Late in the stream, prefer closing out bins (waste minimization).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is near the mean (balanced packing), slightly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for very fragmented residuals (post_residual small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize residual strongly). Late: residual less costly,
    // but dead space still matters — hence smooth sign-alternating interaction.
    let t = pr / cap; // normalized post residual in [0,1]
    let poly = t * t * (1.0 - progress) * 40.0 + t * progress * 10.0;
    score += poly;

    // Reward near-perfect fits (small post residual) with a smooth quadratic bonus.
    score -= (1.0 - t) * (1.0 - t) * item_size as f64 * 0.5;

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == 0 {
            score -= 15.0;
        } else if (next_item_size as u32) <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // Next item won't fit here; penalize mildly proportional to wasted potential.
            let gap = (next_item_size as u32 - post_residual) as f64 / cap;
            score += 6.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: encourage consolidation into existing bins, discourage new bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // Opening a new bin is fine if the item is large relative to capacity.
        score -= item_size as f64 * 0.05;
    } else {
        // Prefer bins with residual close to mean residual (balance load smoothly).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 4.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of 10, small remainders) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: small post_residual is good, but zero-waste is best.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Penalize dead space: leftover that no typical item (1..=100) can use well.
    // Harmonic classes via modulo 10 of post_residual.
    let class = post_residual % 10;
    match class {
        0 => score -= 6.0,          // clean multiple of 10: highly reusable
        1 | 2 | 3 => score += 2.0,  // nearly-full sliver: mildly bad
        9 => score += 1.0,          // awkward single-unit-off class
        _ => {}
    }

    // Fraction-of-capacity coupling: leftover as fraction of capacity.
    let frac = post / cap;
    if frac > 0.5 {
        // Bin still more than half empty after placement: this placement was
        // wasteful unless the bin is fresh (new-bin candidate).
        if bin_residual != bin_capacity {
            score += 10.0 * frac;
        }
    } else if frac > 0.25 {
        score -= 3.0;
    }

    // Lookahead harmony: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.1 * slack;
            // Extra bonus if post - next is a clean harmonic class (mult of 10).
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow size.
            let over = (next_item_size - post_residual) as f64;
            score += 0.08 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: fresh bin should only win when it's early
    // in the stream or all alternatives are poor. Give it a mild baseline
    // penalty that shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 12.0 * (1.0 - progress);
        // But if the item is huge relative to mean residual of open bins,
        // opening fresh may be right: relax penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins far from the mean residual
    // (concentrate waste in few bins, keep others flexible).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: bins where item fills >= half the residual
    // are good fits (harmonic halving rule).
    if item_size * 2 >= bin_residual && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild preference to fill older/scarce bins when many bins are open.
    if open_bins_count > 4 && post_residual < 20 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 range, but typical items >= 10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < item_size.min(20) {
        score += 15.0; // gap likely unusable for near-future items
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement chains perfectly; penalize if next item barely misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            score += 8.0; // next item won't fit here -> residual likely dead
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    // rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residual close to the mean (balanced packing),
    // slight pull toward using larger-residual bins first.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression through the stream (0..1), mild discounting late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact / near match of post_residual to next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            // Perfect chaining: post_residual exactly fits the next item.
            score -= 60.0;
        } else if pr >= nxt {
            // Next item still fits: reward proportional to tightness of fit.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize dead space that blocks chaining.
            score += 10.0 + 0.5 * diff;
        }

        // Coupling with mean residual: if this bin's post-residual is far below
        // the fleet mean, it's a good tight placement; if far above, it's wasteful.
        let mean_gap = pr - mean_residual;
        score += 0.3 * mean_gap;
    }

    // --- Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the item is large
        // (poor fit candidates elsewhere) or no other bin fits well.
        let large_item = item_size as f64 > 0.5 * bin_capacity as f64;
        let no_fits = fitting_bins_count == 0;
        if large_item || no_fits {
            score -= 15.0;
        } else {
            // Prefer filling existing bins; penalize opening a new one.
            score += 45.0 + 0.2 * open_bins_count as f64;
        }
        // Late in the stream, opening fresh bins is slightly less costly
        // (fewer future chances to consolidate).
        score -= 10.0 * progress;
    }

    // --- Penalize tiny unusable residuals (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for bins with more open bins already active
    // (encourages consolidation into existing fleet).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let post_norm = post / cap;
    let poly = post_norm * post_norm * (1.0 - post_norm) * (1.0 - post_norm);
    score -= poly * cap * (0.5 + 0.5 * progress);

    // Penalize large post-residual more aggressively late in the stream.
    score += post_norm * post_norm * cap * 0.3 * progress;

    // Reward tight fits (small post residual) especially when bin is a last resort.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - post_norm);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * (post_norm) * (1.0 - progress);
    }

    // Mild preference to keep mean residual balanced: avoid outlier bins.
    let dev = (mean_residual - post).abs() / cap;
    score += dev * dev * 5.0;

    // Encourage filling bins rather than opening new ones as bins accumulate.
    score += (open_bins_count as f64).ln().max(0.0) * post_norm * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class of zero residual
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: capacity fractions 100, 50, 25, 20, 10
    let harmonic_divisors: [u32; 5] = [100, 50, 25, 20, 10];
    for (k, &d) in harmonic_divisors.iter().enumerate() {
        if post_residual % d == 0 && post_residual > 0 {
            score -= (5 - k) as f64 * 8.0;
            break;
        }
    }

    // Penalize residuals that cannot accommodate any plausible future item
    // (items >= 1, so any residual >= 1 is usable, but small residuals are dead space)
    if post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 300.0;
            } else {
                // reward leaving room for next item, scaled by tightness
                score -= (post2 as f64).min(50.0) * 0.5;
            }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // big residual score by default; discount when many bins are well-filled
        score += 250.0 - crowded * 20.0 - progress * 30.0;
        // still allow opening if current item is large and would leave bad residue
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Mild preference for larger residual bins early (spread load), tighter later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any future
    // item (assume minimum plausible item size ~ 10% of capacity) are "dead".
    let dead_threshold = (bin_capacity as f64 * 0.10).max(1.0);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Dead space is a total waste: heavily penalize.
        score += 2.5 * (dead_threshold - post_residual as f64) + 20.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    } else {
        // Tight-but-usable fit: reward closeness to zero residual.
        score -= 10.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // If the residual left exactly accommodates the lookahead item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item
    // (near-miss creates a stranded gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, mild bonus but keep differentiation.
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already well-filled; slight reward for continuing to fill it.
    score -= 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: opening a new bin should only win when no existing
    // bin offers a decent fit. Penalize the fresh bin mildly; the empty-bin
    // call has post_residual == bin_capacity, so its base score is already
    // high; add pressure that grows with the number of open bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is
        // actually fine (less fragmentation risk later).
        if (item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 18.0;
        }
    }

    // Early in the stream, allow slightly more liberal bin opening to build
    // a diverse pool of residuals; late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tightest packing is best.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual == 1 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after the next item also fits: chain potential.
            let chain_slack = post_residual - next_item_size;
            score -= 40.0 + (chain_slack as f64).min(30.0) * 0.5;
            // Exact chain match is excellent.
            if post_residual == next_item_size {
                score -= 80.0;
            }
        } else {
            // Placement leaves a dead gap the next item cannot use.
            let gap = (post_residual - 0).max(0) as f64;
            score += gap * 0.6;
            // Penalize more when next item nearly fits (wasted opportunity).
            let near = next_item_size as f64 - post_residual as f64;
            if near <= 10.0 {
                score += (10.0 - near) * 2.0;
            }
        }
    }

    // Compare post_residual to mean residual: prefer bins pushed toward the mean
    // (balanced packing), penalize leaving far-below-mean slivers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fits poorly.
    if bin_residual == bin_capacity {
        let base = 30.0;
        let waste = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 20.0 };
        score += base + waste
            - (item_size as f64) * 0.3; // large items are fine to start fresh
        if fitting_bins_count > 1 {
            score += 25.0; // other options exist; avoid proliferation
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements leaving little dead space.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving awkward residuals that few item sizes can use.
    if post_residual > 0 {
        let awkward = (post_residual as f64 / 10.0).fract();
        score += 8.0 * awkward;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Perfect chained fit is even better.
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Penalize blocking the next item slightly.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(50.0);
        }
    }

    // Prefer filling bins that are already mostly used (consolidation).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Time horizon: early in the stream, be more willing to open new bins
    // (flexibility preserved); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // Many open bins: encourage packing into existing ones to limit bin count.
    score += 0.8 * (open_bins_count as f64);

    // Mean residual coupling: if open bins are on average roomy, opening
    // another bin is less harmful; if they are tight, avoid fragmenting them.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when no existing bin fits well.
    if bin_residual == bin_capacity {
        let base = 45.0 + 20.0 * progress - 3.0 * (open_bins_count as f64);
        // If the current item is large, opening a fresh bin is reasonable.
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score = base + large_item_bonus + (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) coupling to stream progress.
    let mut score = pr
        + 0.8 * (pr / cap).powi(2) * cap
        + 0.35 * (pr / cap).powi(3) * cap * (1.0 + progress);

    // Reward bins whose residual is close to the item size (smooth Gaussian-like tightness term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * (-(1.0 - fit_ratio) * (1.0 - fit_ratio) / 0.18).exp();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: if the next item fits perfectly in the post-residual, reward this placement.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if nr <= pr {
            let gap = pr - nr;
            score -= 5.0 * (-(gap / cap).powi(2) / 0.02).exp();
        } else {
            // Penalize leaving a residual slightly too small for the next item (dead space).
            score += 2.5 * (1.0 - (-(pr / cap).powi(2) / 0.05).exp());
        }
    }

    // Mild penalty for scattering across many bins when mean residual is high.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: penalize opening a new bin, more so early and when item fits elsewhere.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 15.0 + 10.0 * (1.0 - progress) + 0.15 * waste;
        if fitting_bins_count > 0 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (divisible by common small item sizes) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward if post_residual is divisible by 10 or 25 (harmonic slots).
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    } else {
        score += 3.0; // odd leftover is dead space
    }

    // Dead-space penalty: leftover too small for the minimum item size (1..100 range,
    // but small items are common) — anything < 10 is nearly unusable.
    if post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (harmonic fraction of capacity).
    let fill_frac = item_size as f64 / cap;
    if fill_frac > 0.9 {
        score -= 12.0;
    } else if fill_frac > 0.7 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 4.0;
        }
        // Harmonic: next item is multiple of 10 and post_residual accommodates it
        if next_item_size % 10 == 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing bins are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // Early in stream, new bins are cheap; late, prefer packing existing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (keep mean spread balanced).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild penalty per open bin to discourage bin proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the next item (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0;
    }
    // Reward gaps that exactly fit the next item
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 30.0;
    }
    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for tightest bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize bins that leave moderately small leftovers.
            let pr = post_residual as f64;
            if pr < 10.0 {
                score += 5.0 * (10.0 - pr); // unusable dead space for typical items
            }
        }
    }

    // Relative to mean residual: prefer bins with residual close to item need.
    let res_diff = (bin_residual as f64) - (item_size as f64);
    score += 0.15 * (res_diff - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let opening_bonus = if fitting_bins_count == 0 { 0.0 } else { 8.0 };
        score += opening_bonus + 0.05 * (open_bins_count as f64);
        // If next item is large and current fit is loose, opening a new bin is fine.
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness).powi(6) * 12.0;

    // Penalize dead space relative to the smallest plausible future item (1..100 unknown).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless no decent fit exists.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.1;
        // Late in the stream, opening new bins wastes capacity; discourage more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual as f64;
        score -= next_fit * next_fit * 15.0;
    } else if next_item_size > post_residual {
        // Post-residual unusable by next item: mild penalty scaled by dead space.
        score += (post_residual as f64) * 0.05;
    }

    // Prefer filling bins when many are open (reduce fragmentation).
    score += open_bins_count as f64 * 0.5;

    // Global state: prefer bins below mean residual (consolidate emptier space usage).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early on, be picky (penalize loose fits more); later, accept.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - progress) * pr_norm * pr_norm + progress * pr_norm;
    score += 30.0 * poly * cap * 0.1;

    // Reward tight fits, especially late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let gap = pr_norm - next_norm;
    if next_item_size > 0 {
        let waste = gap.max(0.0);
        let usable = if gap < 0.0 { 1.0 } else { 0.0 };
        score -= 8.0 * usable * (pr_norm - next_norm).abs() * (1.0 - progress);
        score += 6.0 * waste * waste * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty proportional to open bins to discourage bin proliferation
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Coupling with mean residual: prefer bins deviating favorably from mean
    score += 0.5 * (pr - mean_residual).abs() * (1.0 - progress);

    // Smooth penalty for very large post residual early (wasted space)
    score += 10.0 * pr_norm * pr_norm * pr_norm * (1.0 - progress);

    // Reward placing large items into bins with matching residual (smooth)
    let fit_quality = 1.0 - (bin_residual as f64 - item_size as f64 - pr).abs() / cap;
    score -= 5.0 * fit_quality * item_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Harmonic class of post_residual: dead space that cannot hold
    // even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver -> strong penalty
    }

    // Integer-division thresholds on post_residual (harmonic classes):
    // classify leftover space by which future item classes it can absorb.
    let class = match post_residual {
        0 => 0,           // perfect fit
        1..=10 => 1,      // dead
        11..=25 => 2,     // small items only
        26..=50 => 3,     // medium items
        _ => 4,           // half-full or more
    };
    score -= match class {
        0 => 25.0,
        1 => 0.0,
        2 => 5.0,
        3 => 10.0,
        _ => 15.0,
    };

    // Lookahead: reward if next item fits the post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit here; leftover likely dead
            score += 4.0;
        }
        // modulo coupling: next item in same "decile class" as post residual
        if next_item_size > 0 && post_residual / (next_item_size.max(1)) >= 2 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 {
            -1000.0 // must open a new bin
        } else {
            // opening a new bin wastes mean_residual of open bins
            15.0 + mean_residual * 0.3 + (open_bins_count as f64) * 0.5
        };
        score += pressure;
        // a fresh bin always has post_residual = capacity - item_size,
        // which is large; dampen that structural advantage slightly
        score -= item_size as f64 * 0.1;
    }

    // Progress coupling: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual.saturating_sub(item_size)) as f64 * 0.02;

    // Prefer bins whose residual is close to the mean (balance).
    score += (mean_residual - post).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: heavily favor bins whose post_residual is small.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Strict dead-space avoidance: penalize residuals that are too small
        // to be useful for typical future items (1..=100 range).
        let r = post_residual as f64;
        if r < 10.0 {
            // Unusable sliver of dead space — strong penalty.
            score += 60.0 * (10.0 - r);
        } else if r < 20.0 {
            // Marginal gap: only usable for tiny items; penalize proportionally.
            score += 25.0 * (20.0 - r) / 10.0;
        } else {
            // Usable gap: mild reward scaled by how much usable space remains.
            score -= 8.0 * (r / bin_capacity as f64);
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 50.0; // chained perfect fit
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty unless residual is 0.
        if post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // rather than spreading; penalize placements that leave large residuals
    // when bin count is high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // New-bin candidate decision: a fresh empty bin should only win when
    // existing fits are poor. Give the empty bin a moderate baseline score;
    // good fits in open bins (small post_residual) will beat it, while
    // wasteful placements (large dead space) will lose to it.
    if bin_residual == bin_capacity {
        score = 55.0 + pressure * 5.0;
        // Late in the stream, slightly prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 25.0 * progress;
        }
        // If no open bin can even fit (fitting count refers only to open bins
        // but the empty bin call also arrives), keep baseline.
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        return score;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (keeps open bins balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit for the NEXT item is the strongest reward: this bin will be
    // exactly refilled, leaving no dead space across a 2-step horizon.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress;
        } else if post_residual > next_item_size {
            // Bin can still host the next item: reward proportional to how
            // tightly the next item nests into the new residual.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * tightness * tightness;
        } else {
            // Bin becomes unusable for the next item: penalize dead space
            // more strongly when the leftover is small and awkward.
            let dead = post_residual as f64;
            score += 12.0 * (1.0 - dead / bin_capacity as f64);
        }
    } else {
        // Last item: pure waste minimization.
        score += 5.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving a residual well below average creates an outlier dead bin.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.5 {
            score += 8.0 * (0.5 - ratio); // creates a low-residual straggler
        } else if ratio > 1.5 {
            score += 4.0 * (ratio - 1.5); // hoards space, starves other bins
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current
    // item is large relative to capacity or we are early and many bins will
    // be needed anyway. Empty-bin call has bin_residual == bin_capacity so
    // post_residual == capacity - item_size there.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Opening a new bin is only attractive for large items or when the
        // stream is long and item likely wastes space elsewhere.
        score += 45.0 - 40.0 * item_frac - 15.0 * progress;
        // If next item is small it could have shared an existing bin: extra penalty.
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score += 10.0;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    // Small bonus for filling bins densely (low post residual overall).
    score -= 10.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect fit leaves unusable sliver but that's fine
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for blocking a better pairing.
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize bins whose residual is far below the mean (they're already fragmented)
    // and reward bins with residual near or above the mean (consolidating space).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_diff * -1.0;

    // If many bins are open, prefer filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score += 15.0 * (bin_residual == bin_capacity) as i32 as f64;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin; decreases late in the stream.
        let mut new_bin_cost = 35.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0; // no alternative
        }
        // If item is large relative to capacity, opening fresh is more reasonable.
        new_bin_cost -= 20.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_cost;
    }

    // Mild time-horizon modulation: early on, be picky (keep space flexible);
    // late, be greedy (fill whatever fits).
    score *= 1.0 + 0.5 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + t);
    score -= 8.0 * norm_pr * (1.0 - t) * (1.0 - t);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.4 + 0.6 * t);

    // Penalize dead space relative to mean residual of open bins
    score += 0.05 * (pr - mean_residual).abs();

    // Lookahead: reward leaving space for the next item (smooth quadratic in gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.03 * gap * gap / cap;
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * t;

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit core), scaled super-linearly.
    score += (post_residual as f64 / cap).powi(3) * 60.0;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual: classify residual into "dead space" buckets.
    // Residuals < 10 are dead (min item size assumption broken by unknown distribution, so use small thresholds).
    if post_residual > 0 && post_residual <= 5 {
        score -= 150.0; // near-perfect fill, excellent
    } else if post_residual <= 15 {
        score += 30.0; // small but possibly usable residual
    } else if post_residual <= 30 {
        score += 10.0;
    } else {
        // Large residual: check if next item can fill it (harmonic pairing).
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Next item fits exactly or nearly into leftover: reward.
            let gap = post_residual as i64 - next_item_size as i64;
            if gap == 0 {
                score -= 400.0;
            } else if gap <= 10 {
                score -= 120.0;
            } else {
                score -= 40.0;
            }
        } else {
            // Dead space relative to lookahead: penalize modulo structure.
            let r = post_residual as i64;
            let dead = if next_item_size > 0 { (r - (next_item_size as i64)) } else { r };
            score += (dead as f64).powi(2) / cap * 2.5;
        }
    }

    // Integer-division threshold classes on post_residual vs typical item sizes.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > half {
        score += 25.0; // leaving more than half empty is wasteful unless new bin
    } else if post_residual > quarter && post_residual <= half {
        score -= 15.0; // sweet spot: room for a mid-size item
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when current bins are crowded or fit is poor here.
        let crowded = open_bins_count as f64 * 8.0;
        let poor_fits = if post_residual == 0 { 0.0 } else { (item_size as f64 / cap) * 50.0 };
        // Base cost of a fresh bin, offset by crowding and poor alternatives.
        let fresh_cost = 90.0 - crowded - poor_fits;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = fresh_cost - progress * 30.0;
        // If lookahead item is large, a fresh bin preserves flexibility.
        if next_item_size as u32 >= half {
            score -= 40.0;
        }
        return score;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled) when many bins open.
    if open_bins_count > 1 {
        let dev = mean_residual - post_residual as f64;
        score += dev * 0.3;
    }

    // Progress-aware tightening: as stream advances, demand tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * progress * 40.0;

    // Modulo-class bonus: residual that is a small multiple of common item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (< 10) are almost unusable
    // for future items, so punish them hard beyond their raw value.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.15;

    // Pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if item is large relative to capacity
    // or no open bin fits well; otherwise penalize spreading.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 60 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // fresh bin can also host the next item
        }
    }

    // Lookahead: if next item exactly fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // dead space for the known next item
    }

    // Late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact 2-step lookahead match.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Perfect chain: item fits, then next item fills bin exactly.
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize leaving residual that neither fits next item nor is tiny.
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score -= 20.0; // small dead space is acceptable
        }
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual >= 10 {
            score += 15.0; // stranded mid-sized gap
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (tighter bins get filled first), penalize opening gaps in loose bins.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only when
    // no open bin offers a decent fit, but keep it competitive for big items.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If nothing else fits well, empty bin looks better.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: opening a new bin is attractive if next item is large.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Progress-based pressure: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Discard fraction: penalize wasted fraction of the bin.
    score += 20.0 * (post_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
