pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized residual fill efficiency
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness;

    // Smooth stream-progress coupling: later in stream, penalize loose fits more
    score += 6.0 * (1.0 - tightness) * (1.0 - tightness) * progress;

    // Lookahead synergy: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let snug = 1.0 - (post - next_item_size as f64) / cap;
        score -= 10.0 + 14.0 * snug * snug;
    } else if next_item_size > 0 {
        // penalize residual that wastes the lookahead opportunity
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: make it mildly unattractive unless the fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress;
        if item_size < bin_capacity / 2 {
            score += 12.0;
        }
    }

    // Coupling with mean residual: prefer bins deviating below the mean (consolidating)
    score -= 3.0 * ((mean_residual - post) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, scaled
    score += (post_residual as f64 / cap_f) * 10.0;

    // Harmonic class of post_residual: quantize into capacity fifths
    let fifth = bin_capacity / 5;
    let class = post_residual / fifth;
    score += match class {
        0 => -15.0,             // nearly full bin: excellent
        1 => -6.0,
        2 => 0.0,
        3 => 6.0,
        _ => 12.0,              // large dead space
    };

    // Modulo-3 / modulo-7 harmonic coupling of post_residual and next_item_size
    let m3 = post_residual % 3;
    let m7 = (next_item_size % 7) as f64;
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportional to leftover harmony
            let nxt_left = post_residual - next_item_size;
            score -= 8.0 + (nxt_left as f64 / cap_f) * 20.0;
            if nxt_left % 3 == 0 { score -= 2.0; }
        } else {
            score += 5.0 + m7 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual > 0 {
            // item placed into fresh bin
            score -= (item_size as f64 / cap_f) * 10.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        if open_bins_count == 0 { score -= 40.0; }
    }

    // Mean-residual coupling: discourage bins far from the mean residual (wasted space asymmetry)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold: post_residual below half capacity is a good sink
    if post_residual < bin_capacity / 2 {
        score -= 4.0;
    }

    // Progress-aware mild tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving residuals that can host the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / 100.0);
