    }

    // Tight fit relative to residual: reward filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: penalize opening/spreading into many bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are crowded or fit is poor.
        let pressure = (open_bins_count as f64) * 3.0 + mean_residual * 0.4;
        let fit_is_bad = if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size { 15.0 } else { 0.0 };
        score += 10.0 - pressure - fit_is_bad;
    } else {
        score += (open_bins_count as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild late-stream tightening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward zero leftover space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chaining perfect fit
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
            // Reward closeness of post_residual to next item size (tight lookahead match).
            score -= 60.0 / (1.0 + diff / 10.0);
            // Penalize if next item cannot fit in post_residual (dead space for lookahead).
            if next_item_size > post_residual {
                score += 0.35 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Penalize small unusable leftovers (dead space) relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is below mean (tighter bins),
    // penalize wasting space in already-loose bins.
    score += 0.20 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make opening a new bin moderately attractive only when
    // current bin fit is poor (large post_residual waste or lookahead mismatch).
    if bin_residual == bin_capacity {
        // Base cost of a new bin; lookahead can justify it.
        score = 55.0;
        if next_item_size > 0 {
            let diff = (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs();
            score -= 50.0 / (1.0 + diff as f64 / 8.0);
        }
        // Late in the stream, discourage opening new bins with small items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress * (item_size as f64 / 100.0);
    }

    // Mild preference for fewer open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
