    }

    // New-bin candidate handling: prefer open bins unless fit is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // More attractive when few bins fit or open bins are crowded
        score -= 10.0 * (fitting_bins_count as f64).recip();
        score += 0.3 * (open_bins_count as f64);
        // Late in the stream, consolidation matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
