    }

    // Mild penalty when many bins are open, encouraging consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev - 12.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor,
    // with smooth dependence on progress.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (multiples of common item sizes / small residuals are dead space).
    let pr = post_residual;
    if pr > 0 {
        // dead-space penalty grows superlinearly for tiny residuals
        if pr <= 10 {
            score += 25.0 * (11.0 - pr as f64);
        }
        // harmonic class: residuals divisible by 10 or 25 are more reusable
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 25 == 0 {
            score -= 6.0;
        }
        if pr % 5 != 0 {
            score += 4.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; mild penalty proportional to wasted potential
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline cost unless current fit is bad
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 0.5;
        if post_residual == 0 { score -= 60.0; }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        if fitting_bins_count == 1 && post_residual > 0 {
            score += 40.0; // don't open new bin when a last-chance fit exists
        }
    }

    // Slight preference to fill bins below mean residual (balance toward fuller bins)
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Mild pressure to prefer fewer open bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: gaps too small to hold even the smallest plausible item are wasted.
    // Penalize residuals in (0, 10) extremely hard; mildly penalize small gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver -> total dead space
        } else if post_residual < 20 {
            score += 15.0;
        } else if post_residual < 35 {
            score += 4.0;
        }
    }

    // Reward tight fits (post_residual near zero but not dead).
    if post_residual <= 5 && post_residual > 0 {
        score -= 30.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, this placement chains well.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slightly prefer leaving larger residual
        score += (post_residual as f64 - next_item_size as f64).abs() * 0.05;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are small.
    let ob = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += ob * 0.8 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // (keeps bin states balanced), unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: attractive when all open bins would leave large dead space
    // or when few bins are open. Penalize new bins when existing bins fit well.
    if bin_residual == bin_capacity {
        let best_possible_waste = if fitting_bins_count > 0 {
            // waste if we used an open bin: unknown exact, approximate via mean residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            (bin_capacity - item_size) as f64
        };
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        } else if best_possible_waste > 30.0 {
            score -= 40.0; // open bins would waste a lot
        } else {
            score += 30.0 + fitting_bins_count as f64 * 5.0; // prefer existing bins
        }
        // late in stream, consolidate
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly match next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Perfect chain match: post_residual == next_item_size is ideal
        score -= 18.0 * (1.0 - gap / bin_capacity as f64).powi(3);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize if next item can't fit after this placement (dead end)
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer minimal residual
        score += 5.0;
    }

    // Prefer tight fits: large item fraction relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins with below-mean residual are "tighter",
    // prefer placing into them to consolidate space
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Penalize leaving large residuals on nearly-empty bins unless item is small
    if post_residual > 50 && item_size < 40 {
        score += 6.0;
    }

    // Mild preference for reusing existing bins over opening new ones as stream grows
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Reward near-perfect packing (residual < 10 is excellent)
    if post_residual < 10 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead space penalty: residual that is small but unusable for typical items
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Chain fit: post_residual fits next item and its own leftover fits again
        if post_residual >= next_item_size && (post_residual - next_item_size) >= item_size.min(next_item_size) {
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins among open bins (mean residual coupling)
    if bin_residual < bin_capacity {
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive early in stream or when no good fit exists
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64;
        // Penalize new bins more as stream progresses and many bins are open
        score += 30.0 + 45.0 * progress + 2.0 * open_pressure;
        // But relax penalty when open bins are all poorly filled / item is large
        if item_size > 60 {
            score -= 20.0;
        }
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild time-horizon modulation: late in the stream, consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let x = pr / capacity;

    // Base: quadratic penalty on leftover space (waste grows super-linearly).
    let mut score = x * x * capacity;

    // Smooth cubic coupling: mid-range leftovers are the worst dead space,
    // penalize the hump around x ~ 0.5 more than extremes.
    score += 12.0 * x * (1.0 - x) * (x - 0.5) * (x - 0.5) * capacity;

    // Stream-progress coupling: early on, keep bins flexible (favor larger
    // residuals); late, squeeze tight fits (favor smaller residuals).
    let flex = 1.0 - progress;
    score += 10.0 * flex * x * capacity;
    score -= 8.0 * progress * (1.0 - x) * (1.0 - x) * capacity;

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let tight = 1.0 - ((post_residual - next_item_size) as f64 / capacity);
        score -= 6.0 * tight;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly reward using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // unless the item is a perfect fit for a fresh bin.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = capacity * 0.9 + waste * 0.5 - 20.0 * progress * (waste / capacity);
        if item_size as f64 >= 0.9 * capacity {
            score -= 100.0; // big item: fresh bin is great
        }
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual
    // in the direction that consolidates space.
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "dead"
    // (too small for the minimum item) so they don't get over-penalized.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual < dead_threshold {
        score -= 8.0; // unusable sliver: essentially perfect fit, reward strongly
    } else {
        // Classify post_residual into harmonic buckets via integer division.
        let class = post_residual / 10; // 0..=9 classes
        // Penalize mid-class residuals more than extreme ones (harmonic weighting)
        let harmonic_penalty = match class {
            0 => 0.0,
            1 => 2.0,
            2 => 4.0,
            3 => 6.5,
            4 => 8.0,
            5 => 7.0,
            6 => 5.5,
            7 => 4.0,
            8 => 2.5,
            _ => 1.0,
        };
        score += harmonic_penalty;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap < dead_threshold {
            score -= 10.0;
        } else {
            // fractional coupling of gap to next item size
            score -= 6.0 * (1.0 - gap as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // next item cannot use this residual: mild penalty scaled by waste fraction
        score += 3.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // best existing fit would leave a large, awkward residual.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 25.0;
        // but if many open bins are nearly full, new bin is cheap-ish
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score -= 4.0 * pressure.min(5.0);
        // if the item is huge relative to capacity, new bin is natural
        score -= 10.0 * (item_size as f64 / cap);
        // late in the stream, avoid spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
        // if next item is large and this bin (new) would hold both, encourage
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 5.0; // don't pair big items unnecessarily... actually penalize pairing
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Tight fit reward: small absolute waste relative to item size
    let waste_frac = post_residual as f64 / cap;
    score += 20.0 * waste_frac * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Larger leftover gaps: mild quadratic penalty scaled by bin capacity.
        let r = post_residual as f64 / bin_capacity as f64;
        score += 5.0 * r * r * (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves another gap: mild reward proportional to tightness.
        let tight = 1.0 - ((post_residual - next_item_size) as f64) / (post_residual.max(1) as f64);
        score -= 20.0 * tight;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.8 * (0.5 + progress);

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or with many bins.
        score += 30.0 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is fine
        }
        // If mean residual across open bins is small, open bins are nearly full;
        // opening fresh space is more acceptable.
        score -= (mean_residual / 10.0).min(15.0);
    } else {
        // Reward using bins that are already partially filled relative to the mean.
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item exactly fills the post-residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 30.0; // perfect two-item packing
        }
        // penalize residuals too small for anything useful (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += post_residual as f64 * 0.5;
    }

    // relative to mean residual: prefer bins with less residual than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // new-bin candidate: neutral-ish score, discourage unless current fits are poor
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // with lookahead, opening fresh is more attractive if next item is large
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Penalize dead space quadratically, normalized by capacity.
    let post_f = post_residual as f64;
    score += 0.6 * (post_f * post_f) / cap;

    // Strongly reward near-perfect fits (post_residual small relative to item).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_f < item_size as f64 {
        score -= 8.0 * (1.0 - post_f / item_size as f64);
    }

    // Lookahead: reward if next item can use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_f {
            score -= 6.0 * (nxt / cap);
        } else {
            score += 3.0 * (nxt - post_f) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, but less when fits elsewhere are bad
    // (large post_residual among open bins) or many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.05 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Early in stream, prefer consolidating; later, spreading is fine.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * t;
    }

    // Compare against mean residual: bins with residual far from mean are
    // either outliers to fill up or fresh bins to preserve.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins that are already small-residual (tight packing).
    score += 0.1 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Reward tight fits via a smooth quartic decay on normalized post-residual.
    score -= cap * 1.5 * (1.0 - norm_post).powi(4);

    // Penalize mid-range dead space quadratically (awkward residuals ~ half capacity).
    let dead = norm_post - 0.5;
    score += cap * 0.9 * dead * dead;

    // Lookahead coupling: reward residuals that still admit the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if post >= nx { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (1.0 - (post - nx) / cap);
        score += 6.0 * (nx / cap) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for spreading across many bins early on.
    score += 0.6 * open_bins_count as f64 * progress;

    // Prefer bins whose residual deviates from the mean (consolidation pressure).
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate: keep it slightly unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += cap * (0.55 + 0.35 * progress) - 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 and 25
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class25 = (pr % 25) as f64;
    // Penalize awkward residues (non-zero, small remainders create dead space)
    if pr > 0 {
        score += 3.0 * (class10 / 10.0) + 2.0 * (class25 / 25.0);
        // Perfect zero-residual or exact-halving fits are golden
        if pr == 0 { score -= 60.0; }
    } else {
        score -= 60.0;
    }

    // Integer-division thresholds: favor post_residual divisible into likely item sizes
    if pr > 0 {
        let div_bonus = (10..=80).filter(|&s| pr % s == 0).count() as f64;
        score -= 4.0 * div_bonus;
    }

    // Tightness: fraction of bin consumed
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tight * tight;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item won't fit here; penalize wasting large residual
            score += 5.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist and fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost plus pressure from open bins count
        score = cap * 0.8 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
        // early in stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // prefer bins with residual near mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (1..=100) are pure waste. Penalize small
    // non-zero post_residuals aggressively; residuals that can still hold
    // medium/large items are less harmful.
    let dead_threshold = 9.0; // gaps <= 9 cannot hold items >= 10 in classic regime
    if post_residual > 0 && (post_residual as f64) <= dead_threshold {
        score += 40.0 + 3.0 * (dead_threshold - post_residual as f64);
    }

    // Continuous dead-space pressure: quadratic penalty on unusable fraction
    // of the bin. Small gaps are the worst use of capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * post * post / cap;

    // Reward tight fits (small post_residual relative to item size).
    let item = item_size as f64;
    if item > 0.0 {
        score -= 25.0 * (item / (item + post + 1.0));
    }

    // Open-bin pressure: many open bins spread residuals thin; discourage
    // leaving many half-empty bins around unless the fit is excellent.
    let ob = open_bins_count as f64;
    score += 1.2 * ob * (post / cap);

    // Mean residual coupling: if the fleet average residual is high, prefer
    // placements that reduce variance (post_residual near mean is fine,
    // far-from-mean gaps are penalized).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement strongly (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how snugly.
        score -= 8.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover gap: mild penalty scaled by gap.
        score += 6.0 * (post_residual as f64 / cap);
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (fewer items left to fill them).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from existing bins.
        score = 55.0 + 4.0 * ob - 10.0 * progress;
        // If no open bin can fit, new bin is necessary (fitting_bins_count==0
        // won't occur here since new bin always fits, but keep score low
        // when many bins exist but none fit).
        if fitting_bins_count == 1 && open_bins_count > 0 {
            // Only the new bin "fits" among candidates that fit? This call
            // means open bins could fit too; penalize slightly more.
            score += 5.0;
        }
        // If next item is large and current item is small, opening a fresh
        // bin may be wasteful; if current item is large, fresh bin is good.
        score -= 0.1 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: heavy reward
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // penalize distance from perfect lookahead match, scaled by next item size
            score += diff * (0.5 + 0.5 * next_item_size as f64 / 100.0);
        }
        // If next item cannot fit in post-residual, mild penalty unless post residual tiny
        if (post_residual as u64) < (next_item_size as u64) {
            score += 5.0;
        }
        // Bonus if this placement leaves room for next item in a tight way
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 8.0;
        }
    }

    // Dead-space penalty: post_residual too small to ever fit typical items (1..100 min item = 1,
    // but penalize very small residuals relative to mean residual structure)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Favor bins with residual already below mean (consolidating fragmentation)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.15 * (mean_residual - res);
    } else {
        score += 0.10 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins can fit, unless current fits are terrible
    if bin_residual == bin_capacity {
        // new bin: base cost = capacity, reward if no fitting bins or fits leave huge waste
        score = bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        } else {
            // only open new bin if best alternative would leave large dead space;
            // approximate by penalizing less when item is large
            let large_item_bonus = (item_size as f64 / 100.0) * 30.0;
            score -= large_item_bonus;
            if next_item_size > 0 && next_item_size >= bin_capacity {
                score -= 20.0;
            }
        }
    }

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (res / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to item size)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Reward using nearly-full bins: waste of small residual is fine
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when other bins fit well
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residuals across open bins are large
        score += 20.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        // Early stream: prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
        // Perfect chain: next item exactly fills remainder
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space that next item cannot use: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Prefer filling bins with large residual spread vs mean (balance awareness)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Slight preference for bins with more open bins competing (keep options open)
    if open_bins_count > 3 {
        score += 2.0;
    }

    // Discourage leaving residual in (10..20) "awkward zone" unless unavoidable
    if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, normalized
    let mut score = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are tolerable; late, they become costly (dead space).
    let prn = pr / cap; // normalized post residual
    let coupling = prn * prn * (0.5 + progress) + prn * progress * progress;
    score += 1.5 * coupling;

    // Reward tight fits (post_residual small relative to item size) with smooth decay
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 0.8 * tightness * tightness;

    // Penalize residuals that cannot fit the lookahead item (dead space), smooth ramp
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let gapn = gap / cap;
        score += 1.2 * gapn * (1.0 + progress);
        // Reward when post_residual exactly accommodates next item (chaining)
        if post_residual == next_item_size {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // New-bin candidate: discourage early opening, allow late when open bins are cluttered
    if bin_residual == bin_capacity {
        let clutter = mean_residual / cap;
        score += 1.5 - 1.0 * progress - 0.5 * clutter.min(1.0);
    }

    // Mild preference for bins with residuals below the mean (consolidation)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).max(-1.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues in (0..10) are "dead space"
    // since min item size is 10 (interface allows 1..100, so use graded penalty).
    let dead = if post_residual == 0 {
        0.0
    } else if post_residual < 10 {
        (10 - post_residual) as f64 * 3.0
    } else {
        0.0
    };
    score += dead;

    // Reward perfect / near-perfect packing (post_residual in a harmonic class).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Integer-division thresholds: post_residual divisible by common item
    // granularity classes (10, 20, 25, 50) are reusable slots.
    if post_residual > 0 {
        let reusability = (post_residual % 10 == 0) as i32 as f64 * 6.0
            + (post_residual % 20 == 0) as i32 as f64 * 4.0
            + (post_residual % 25 == 0) as i32 as f64 * 3.0
            + (post_residual % 50 == 0) as i32 as f64 * 3.0;
        score -= reusability;
    }

    // Lookahead coupling: strongly prefer bins whose post_residual can
    // host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
        // Bonus if post_residual == next_item_size exactly (perfect chain).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: penalize proportionally.
        let waste_frac = post_residual as f64 / next_item_size as f64;
        score += 8.0 * (1.0 - waste_frac).max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more strongly when
    // good fitting bins exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * (open_bins_count as f64);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Prefer fuller bins: reward low bin_residual (tight fit).
        score += 0.15 * (bin_capacity - bin_residual) as f64;
    }

    // Progress coupling: early in the stream, be slightly more willing to
    // spread items (keep flexibility); late, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 - progress * 2.0;

    // Mean-residual coupling: if this bin is much emptier than average,
    // slightly prefer filling it (balance residuals).
    score -= 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post_residual gaps are almost unusable.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 40.0 } else if post_residual < 20 { 18.0 } else if post_residual < 30 { 6.0 } else { 0.0 };
        score += dead;
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Tightness bonus: fraction of bin used by this placement
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill;

    // Reward when this bin's residual exactly matches the next item (lookahead synergy)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / cap;
        }
    }

    // Open-bin pressure: prefer consolidating when many bins are open
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bin attractive only if it avoids bad fits
    if bin_residual == bin_capacity {
        // fresh bin: baseline cost of opening a new bin, softened when stream is early
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.5 * cap + 20.0 * (1.0 - progress) - 15.0 * (1.0 - fill);
        // if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // penalize existing bins whose residual deviates badly from mean
        score += 0.2 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + lookahead_gap);
        // Perfect chain: item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual > 0 && post_residual < next_item_size.min(bin_capacity) {
            score += 10.0;
        }
    } else {
        // Last item: only exact fills matter.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward bins already below mean residual (consolidating space).
    let dev = mean_residual - post_residual as f64;
    score -= 0.5 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless few bins open
    // or residual spread suggests fragmentation.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64) / (open_bins_count.max(1) as f64 + 1.0)).abs();
        score += 15.0 + 0.3 * open_bins_count as f64 - 0.2 * fragmentation;
        // But open a new bin if no open bin gives a tight fit.
        if post_residual == 0 && item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Mild late-stream pressure to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let waste_frac = post_residual as f64 / cap;
        score += 8.0 * waste_frac * waste_frac;
    }

    // Exact-fit lookahead: if the next item exactly fills the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: mildly favorable, scaled by how snugly.
        let snug = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * snug;
    } else if next_item_size > post_residual {
        // Next item won't fit after this placement: penalize leaving little room.
        score += 6.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: competition high, prefer the tightest (already via post_residual),
    // but add small penalty proportional to crowding to spread load.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state: penalize placements into bins whose residual deviates from mean,
    // encouraging residual homogenization for future pairing.
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Time horizon: early in stream, be picky about waste; late, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate logic: opening a fresh bin is attractive only when the item
    // is large or the current fit is terrible.
    if bin_residual == bin_capacity {
        let base = 20.0 + 0.5 * (open_bins_count as f64);
        let bad_fit_bonus = if post_residual > 0 { (post_residual as f64 / cap) * 15.0 } else { 0.0 };
        score = base + bad_fit_bonus - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted residual (dead space grows quadratically in usefulness loss)
    let mut score = norm_pr * norm_pr * cap + pr * 0.35;

    // Smooth stream-progress coupling: tolerate residual early, punish late
    score += (1.0 - progress) * pr * 0.25;
    score += progress * pr * pr / cap * 0.8;

    // Lookahead synergy: reward if next item fits snugly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let snug = 1.0 - ((pr - nxt) / cap);
            score -= snug * 12.0;
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += (nxt - pr) / cap * 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + (1.0 - progress) * 10.0;
    }

    // New-bin candidate: penalize unless current bin would leave large unusable residual
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let waste_if_used = (bin_residual - item_size) as f64;
        score = cap * 0.9 + waste_if_used * 0.3 - scarcity * (waste_if_used / cap) * 20.0;
        // late in stream, prefer squeezing into open bins
        score += progress * 10.0;
    }

    // Crowding: many open bins with high mean residual -> prefer consolidation
    score += (open_bins_count as f64).ln() * mean_residual / cap * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Perfect / near-perfect fits strongly rewarded
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic classes: post_residual divisible classes reveal reusability
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0; // residual aligns with common item granularity
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    // Dead zones: residuals that few item sizes (1..100) can use
    if pr > 0 && pr < 10 {
        score += 20.0; // nearly unusable sliver
    }
    if pr >= 10 && pr < 20 && next_item_size > pr {
        score += 10.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chain placement possible
            // bonus if next item exactly fills what remains
            if next_item_size == pr {
                score -= 25.0;
            }
        } else {
            score += 6.0; // next item won't fit here
        }
        // Harmonic compatibility: next_item_size and post_residual share divisors
        let n = next_item_size;
        if pr % 5 == 0 && n % 5 == 0 && n <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (already via post_residual)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        // penalty grows with number of open bins and mean slack
        score += 35.0 + 3.0 * open_pressure + 0.5 * mean_residual;
        // but if item is large and mean residual is low, opening is reasonable
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 40.0;
        }
        // late in the stream, avoid scattering
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with below-average residual (consolidate emptier bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (item_size as f64);

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; opening a
    // new bin is penalized via the new-bin candidate's naturally high score.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // If the next item would fit perfectly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for next item: mild penalty if gap is unusable for lookahead
        if post_residual < next_item_size.min(10) {
            score += 6.0;
        }
    }

    // Slight preference for bins with residual already below the mean (well-utilized bins).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Penalize the brand-new empty bin candidate unless current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score += 15.0 + poor_fit + 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff >= 0.0 {
            // next item fits exactly into the leftover: strong reward
            score -= (1.0 - (diff / bin_capacity as f64).powi(2)) * 25.0;
        } else {
            // leftover too small for next item: penalize dead space
            score += (-diff / bin_capacity as f64).powi(2) * 20.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing fits are bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // but if next item is large and no tight fits exist, opening is fine
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize tiny dead space that likely becomes unusable (< ~20).
    if post_residual < 20 {
        score -= 18.0;
    } else if post_residual > 60 {
        // Large leftover is fine only if the bin was nearly empty (good for big items).
        score += 4.0;
    }

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // Dead space the next item cannot use; penalize proportional to waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Progress-based time horizon: later in the stream, prefer consolidating
    // into fewer bins (avoid leaving many half-full bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0;

    // Global state coupling: many open bins with high mean residual -> reward
    // filling existing bins; few open bins -> allow spreading.
    if open_bins_count > 3 {
        score -= 0.05 * mean_residual;
    } else {
        score += 0.03 * mean_residual;
    }

    // New-bin candidate (empty bin): discourage unless it's genuinely better,
    // e.g., current item is large and open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_penalty = 20.0 + 15.0 * fragmentation;
        // Allow new bin late in stream if item is large and won't fit well anyway.
        let large_item_relief = if item_size > 60 { 12.0 } else { 0.0 };
        score += new_bin_penalty - large_item_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    let mut score = pr;

    // Tight fit reward: quadratic in post_residual, scaled by progress
    let tight = 1.0 - pr / cap;
    score -= 60.0 * tight * tight * (0.5 + 0.5 * progress);

    // Penalize large dead space non-linearly (cubic growth)
    let dead = pr / cap;
    score += 40.0 * dead * dead * dead * cap * 0.01;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - (gap / cap).abs()) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Mean residual coupling: prefer bins deviating from mean residual
    score += 0.3 * (pr - mean_residual).abs() * (1.0 - progress);

    // Non-linear interaction: post_residual x progress polynomial
    score += 0.05 * pr * pr * progress * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that pair well with common item sizes
    // are rewarded; awkward residues are penalized.
    let pr = post_residual;
    if pr > 0 {
        // post_residual divisible by 10 (typical item quantum) -> good pairing potential
        if pr % 10 == 0 {
