        if pr <= 5 {
            score -= 12.0;
        }
        // Medium-dead-zone: residue too small for the smallest plausible follow-up
        if pr > 5 && pr < 12 {
            score += 8.0;
        }
    } else {
        score -= 20.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward;
    // if next item cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; residue becomes a stranding risk
            score += 0.03 * (next_item_size - pr) as f64;
        }
        // Harmonic: next_item_size and post_residual share a common divisor 5/10
        if pr > 0 && next_item_size % 10 == pr % 10 && next_item_size <= pr {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits tightly
    // (large post_residual means poor fit elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_capacity - item_size) >= 0
            && mean_residual < item_size as f64 + 8.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 55.0
            - 0.5 * open_bins_count as f64
            + 10.0 * progress;
        if tight_exists { nb += 40.0; }
        if post_residual as f64 > mean_residual + 10.0 { nb -= 20.0; }
        score = score.min(nb).max(nb * 0.0 + score) ; // keep base, then compare via nb
        // Effective new-bin score: choose whichever the bin comparison should see
        score = nb + (post_residual as f64 - mean_residual) * 0.1;
    }

    // Mild tie-break: prefer bins whose residual is close to the mean (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
