        score += 35.0 - 45.0 * pressure;
        score += 0.5 * open_f;
        // if mean residual across open bins is large, reusing is attractive
        score += 0.3 * mean_r;
        // early in the stream, opening bins is cheap; late, avoid sprawl
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Reward using existing bins generally
        score -= 5.0;
        // Slight preference for fuller bins (best-fit flavor)
        let used = (bin_capacity - bin_residual) as f64 / cap_f;
        score -= 10.0 * used;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: small unusable gaps are heavily penalized.
        let pr = post_residual as f64;
        // Treat residual below the minimum plausible item size as pure dead space.
        let dead_threshold = 10.0_f64.min(cap * 0.1);
        if pr < dead_threshold {
            score += 500.0 * (dead_threshold - pr) / dead_threshold;
        }
        // Non-linear penalty: squared residual scaled by bin fill fraction.
        let fill = (bin_capacity - post_residual) as f64 / cap;
        score += 0.8 * pr * pr / cap * (1.0 - fill);

        // Reward if next item fits into the post residual (lookahead synergy).
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - slack_after_next / cap);
        } else if next_item_size > 0 {
            // Next item cannot follow here: penalize proportional to mismatch.
            let mismatch = (next_item_size as f64 - pr).min(cap);
            score += 0.3 * mismatch;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 * (open_bins_count as f64);
        // But a new bin is fine if it can also host the next item after this one.
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(item_size) >= next_item_size {
            score -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    } else {
        // Favor bins whose residual is close to the mean (keep residuals balanced).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.2 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits perfectly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot follow here: penalize proportionally to leftover waste
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Penalize creating dead space below the minimum item size (unusable).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Compare against mean residual: prefer bins that keep residuals balanced,
    // but slightly favor bins with more residual when they still fit well.
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 0.05 * (res - mean_residual);
    } else {
        score += 0.05 * (mean_residual - res);
    }

    // Last-chance bin: strongly reward using the only bin that fits,
    // unless the fit is very poor (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the fresh bin mildly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If many bins fit the item, opening a new one is worse.
        if fitting_bins_count > 0 {
            score += 8.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Slight penalty for accumulating too many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    } else if post_residual < item_size.min(40) {
        score += post_residual as f64 * 0.35; // unusable sliver penalty
    }

    // Lookahead: if the next item fits in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to waste.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer bins where this item is a better relative fit.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).max(0.0);
        score -= 0.15 * consolidation;
        score += 0.4 * open_bins_count as f64;
    }

    // Time horizon: early in stream, be picky (penalize loose fits more);
    // late in stream, prioritize just closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * tightness * 20.0;
    score -= progress * 3.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if current fit is poor and
        // remaining bins are scarce; otherwise discourage slightly.
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 6.0 + 10.0 * fit_quality;
        if fitting_bins_count <= 1 && post_residual < item_size.min(35) {
            score -= 20.0; // last chance handled elsewhere; don't open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Base: quadratic penalty on leftover space (waste grows super-linearly).
    let mut score = norm_post * norm_post * bin_capacity as f64;

    // Non-linear coupling: leftover value changes with stream progress.
    // Early on, large leftovers are fine (bins can still be filled);
    // late in the stream, leftover space becomes dead weight.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += tightness * norm_post * norm_post * 40.0;

    // Reward tight fits: item filling most of the bin.
    let fill_ratio = norm_item / (norm_item + norm_post + 1e-6);
    score -= fill_ratio * fill_ratio * 25.0;

    // Lookahead: reward leaving room for the next item, penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post_residual as f64 - nxt;
        if gap >= 0.0 {
            // Bonus decays smoothly as gap exceeds the next item size.
            let closeness = (-gap / (bin_capacity as f64 * 0.25)).exp();
            score -= 12.0 * closeness;
        } else {
            // Smooth penalty proportional to how much the next item misses.
            score += 6.0 * (-gap / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize bins with residual far from the mean (keeps bin pool homogeneous).
    let dev = (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += dev * dev * 15.0;

    // Slight preference for consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: reserve it for cases where no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 30.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual strongly (non-linear)
    score -= (cap - pr) / cap * 8.0;
    score += (pr * pr) / (cap * cap) * 10.0;

    // Modulo classes: residuals divisible by common item granularity are reusable
    let gran = 10u32;
    if post_residual % gran == 0 && post_residual > 0 {
        score -= 3.0; // perfectly reusable residual class
    }
    // Harmonic residue: post_residual mod 5 classes
    let r5 = (post_residual % 5) as f64;
    score += r5 * 0.4;

    // If next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // leftover after hypothetically placing next item: prefer tight two-item packing
        let l2 = post_residual - next_item_size;
        score -= (1.0 - (l2 as f64) / cap) * 4.0;
        // harmonic coupling: next item completes a decile class
        if (item_size + next_item_size) % gran == 0 {
            score -= 2.5;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space that next item cannot use
        score += 2.0 + r5;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin good for pairing with upcoming item
        }
    }

    // Progress-based pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - pr / cap);

    // Prefer bins below mean residual (keep balanced set of large residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    // Penalize many open bins slightly to discourage fragmentation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item are unusable "dead space" -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 100.0;
    } else {
        // Reward tight fits (small relative waste), superlinear.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste * waste;
    }

    // If lookahead item can use the post residual, reward leaving exactly
    // that much space (near-perfect two-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else {
            // post_residual smaller than next item: penalize if it's dead space.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below mean (denser bins) to level residuals.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral-to-slightly-high base so it is chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to how well it matches.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item will not fit here: penalize dead space created.
        score += 15.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Penalize residuals far from the mean (fragmentation risk).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and lookahead does not match.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > mean_residual + 10.0;
        let lookahead_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !poor_fit || lookahead_ok {
            score += 35.0;
        } else {
            score += 5.0;
        }
    }

    // Late in the stream: prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize wasted space relative to the current item: a small item in a big bin wastes potential.
    let item_ratio = item_size as f64 / bin_capacity as f64;
    score -= item_ratio * 10.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to leftover dead space.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // If few bins fit the item, a new bin becomes more acceptable.
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // Early in the stream, opening bins is cheaper; late in the stream, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If mean residual across open bins is small, open bins are nearly full anyway.
        score += mean_residual * 0.1;
        // Lookahead pairing with a fresh bin: if next item is large, a fresh bin is useful.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins -> encourage filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Deviation from mean residual: bins far from the mean residual are either outliers
    // (nearly empty -> deprioritize slightly, nearly full -> reward).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic penalty on post residual,
    // modulated by stream progress (later => prefer tight fits more strongly).
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic dead-space term: heavily penalize tiny unusable remainders.
    score += 60.0 * norm_pr.powi(3);

    // Reward bins whose residual closely matches the item (smooth fit kernel).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 25.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * norm_item;

    // Lookahead coupling: if next item fits smoothly into post_residual, reward.
    if next_item_size > 0 {
        let next_gap = (pr - norm_next * cap).abs() / cap;
        score -= 15.0 * (1.0 - next_gap) * (1.0 - next_gap);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (prefer balance).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening new bins early, less so late.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 + norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class by integer division thresholds on capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    if post == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else {
        // Modulo-10 harmonic class: small post residuals divisible by 10
        // pair well with the 10..80 item grid.
        let class = post % 10;
        if class == 0 {
            score -= 30.0;
        } else if class <= 3 {
            score += 15.0; // awkward sliver
        }
        // Threshold classes: tiny residuals are dead space.
        if post < quarter / 2 {
            score += 40.0;
        } else if post < quarter {
            score += 10.0;
        } else if post >= half {
            // large leftover is valuable, keep bins flexible
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 200.0;
        } else if next_item_size <= post {
            // next item fits: residual is reusable
            let slack = (post - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
        } else {
            // next item cannot use this residual
            score += (next_item_size - post).min(50) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would leave terrible residuals and we don't have too many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize opening new bins mildly, more when many bins are open
        score += 60.0 + 5.0 * open_bins_count as f64 + 30.0 * progress;
        // but if the item is huge, a fresh bin is fine
        if item_size > half {
            score -= 40.0;
        }
    }

    // Tight fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Slight preference for bins with below-mean residual (consolidate emptier bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically, gaps below ~15 rarely get filled; penalize non-linearly.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space coupling: penalize if the gap cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.5;

    // Penalize leaving a gap far below the mean residual (fragmentation signal).
    if post_residual as f64 > mean_residual * 1.5 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins are tight.
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 0.2 - mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item could fit here afterwards; reward tightness of that future fit.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would not fit; penalize dead space relative to next item.
            score += 0.5 * diff;
        }
    }

    // Reward tight fits now (small post_residual).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: prefer bins with below-average residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless residual is very fragmented.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Late in stream, be more conservative: keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to capacity (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable residual is fine actually -> invert
    }
    // Actually: small residual (<10) is GOOD (bin nearly full). Reward it.
    if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should lose unless the
    // current fit is poor or lookahead suggests a better use of this bin.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 15.0; // base cost of opening a new bin
        // If many open bins exist with slack, opening more is wasteful.
        new_bin_score += open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 20.0 * progress;
        // If next item is large and this residual would be tiny, opening a new
        // bin may preserve a big slot elsewhere — mild discount.
        if next_item_size > 0 && (next_item_size as f64) > post_residual as f64 {
            new_bin_score -= 8.0;
        }
        score = score.max(0.0) + new_bin_score;
        return score;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty if this bin was a good
            // host for the next item instead.
            if next_item_size <= bin_residual && next_item_size > item_size {
                score += 6.0;
            }
        }
    }

    // Global state coupling: prefer bins with residuals near the mean
    // (keeps residual distribution balanced), and mildly prefer fewer bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;
    score += 0.5 * open_bins_count as f64;

    // Early stream: be greedy about filling bins tightly; late stream: keep
    // flexibility for large arrivals by penalizing leaving big residuals in
    // many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && post_residual > 50 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: normalized post-residual (dead space penalty), non-linearly amplified.
    let x = post / cap; // in [0,1]
    let mut score = 100.0 * x * x * (3.0 - 2.0 * x); // smoothstep: small residuals cheap, mid residuals costly

    // Cubic coupling with stream progress: late in the stream, dead space hurts more.
    score += 40.0 * x.powi(3) * (0.5 + progress);

    // Interaction between post_residual and mean residual: prefer bins whose
    // leftover is comparable to (or below) the average residual — a tight fit signal.
    let dev = (mean_residual - post) / cap;
    score += 15.0 * dev * dev - 10.0 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Slight penalty when many bins compete: encourage consolidation.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward if the next item can fit the post-residual
    // (smooth logistic-style term instead of hard threshold).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = post / nxt.max(1.0);
        let k = (2.0 * (fits_next - 1.0)).clamp(-6.0, 6.0);
        let p = 1.0 / (1.0 + (-k).exp());
        score -= 20.0 * p;             // reward chains of compatible placements
        // Penalize residual just barely blocking the next item (near-miss dead space).
        let near_miss = (-k).exp() * p;
        score += 8.0 * near_miss * progress;
    } else {
        // Last item: minimize leftover outright.
        score += 30.0 * x;
    }

    // Mild pressure against excessive bin sprawl, scaled by progress.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is very bad.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement
    score += 0.6 * (pr / cap) * (pr / cap) * cap;

    // Harmonic classes: post_residual mod 10 buckets penalize awkward residues
    let class = post_residual % 10;
    if class != 0 {
        score += 2.0 + 0.15 * class as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
            // harmonic bonus: next item leaves a divisible residue
            if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize small leftover
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin would leave large dead space
    if bin_residual == bin_capacity {
        // opening fresh is penalized mildly; scaled by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 5.0 * progress;
        if item_size >= 50 {
            score -= 6.0; // big items like a fresh bin
        }
    } else {
        // prefer denser bins (small residual before placement)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins already below mean residual (tight packing)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure toward fewer open bins.
    score += open_bins_count as f64 * 0.15;

    // Lookahead: reward leaving room for the next item if it fits this residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // dead space that the next item cannot use
    }

    // New-bin candidate: prefer it only when this bin would leave large waste
    // relative to a fresh bin, or when the item fits a fresh bin perfectly.
    if bin_residual == bin_capacity {
        let waste_here = post_residual as f64;
        let avg_waste_elsewhere = mean_residual - item_size as f64;
        if avg_waste_elsewhere < 0.0 || waste_here <= avg_waste_elsewhere {
            score -= 10.0; // fresh bin is competitive
        } else {
            score += 5.0; // prefer reusing an open bin
        }
        // Early stream: opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post_residual relative to capacity (tight fit)
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;

        // 2-step lookahead: if next item fits exactly into post_residual, big reward
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 300.0;
            } else if post_residual >= next_item_size {
                // next item fits, but penalize leftover slack after that hypothetical placement
                let slack_after_next = post_residual - next_item_size;
                score -= 20.0;
                score += 0.3 * slack_after_next as f64;
            } else {
                // post_residual is dead space for the next item: penalize proportionally
                let dead = (next_item_size - post_residual) as f64;
                score += 0.5 * dead;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // base penalty; reduced if the item is large relative to capacity
        let mut new_bin_penalty = 120.0;
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            new_bin_penalty -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            new_bin_penalty += 30.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins with residuals below mean (concentrate waste)
    score += 0.2 * (mean_residual - bin_residual as f64).abs().signum() * (mean_residual - bin_residual as f64);

    // Mild stream-progression scaling: later in the stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Tight fit reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item / resid.max(1.0);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize small unusable post-residuals (dead space) more than moderately useful ones.
    if post > 0.0 && post < 10.0 {
        score += 15.0 * (10.0 - post) / 10.0;
    }

    // Lookahead: bonus if the next item can use the post-residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let nxt_fit = 1.0 - (post - nxt) / cap;
            score -= 8.0 * nxt_fit;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when few fitting bins or huge item relative to residual.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (fitting_bins_count as f64).recip();
        let tight = item / cap;
        // Open new bin when item is large, many bins already open, or no good fits exist.
        score += 25.0 - 18.0 * tight - 10.0 * pressure - 6.0 * progress;
        // If open bins are mostly full (low mean residual), opening is fine.
        score -= 4.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Prefer fuller bins overall: reward low residual relative to capacity.
    score += 6.0 * (1.0 - resid / cap);

    // Mild penalty for spreading across many bins when mean residual is high (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: normalized post residual with stream progress
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 + progress) * 10.0;
    score += coupling;

    // Penalize small post residuals more strongly as stream progresses
    let dead = (1.0 - pr_norm).powi(3);
    score -= dead * (2.0 + 6.0 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward residual that can fit next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    // Mean residual alignment
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (fits small items well) are rewarded.
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), but punish leaving
    // residuals that are dead space relative to the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus proportional to how snugly the NEXT item would fit here.
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - snug / cap);
        } else {
            // Dead space for the lookahead item: penalize by the gap size.
            score += 8.0 + 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: purely minimize waste.
        score += 0.0;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    let q = post_residual / 10; // class buckets of width 10
    match q {
        0 => score -= 15.0,           // 0..=9: near-perfect fill
        1 => score -= 6.0,            // 10..=19: still good
        2 | 3 => score += 2.0,        // 20..=39: mediocre
        4 | 5 => score += 6.0,        // 40..=59: half-full leftover
        _ => score += 10.0,           // 60+: mostly empty bin being "used"
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (10, 20, 25) are more likely to be filled exactly later.
    if post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 {
        score -= 2.0;
    }

    // Capacity fraction coupling: if post_residual is a large fraction of the
    // capacity, this bin was barely touched; discourage unless it's the only fit.
    let frac = post_residual as f64 / cap;
    if frac > 0.7 && fitting_bins_count > 1 {
        score += 14.0 * (frac - 0.7);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): mildly discourage when decent fits exist,
    // but encourage early in the stream or when mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 + 10.0 * progress - 4.0 * (1.0 - mean_residual / cap);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big lookahead item: a fresh bin is valuable
        }
    }

    // Slight preference to keep bin count low when many bins are open.
    score += 0.15 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (1..=10) are almost unusable
    // for future items (sizes >= 1 but typically large), so penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual as i32) as f64 * 4.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    // or the item leaves a large useful gap elsewhere anyway.
    if bin_residual == bin_capacity {
        // Base penalty: prefer filling existing bins when reasonable.
        score += 30.0;
        // Pressure from many open bins: discourage more bins.
        score += open_bins_count as f64 * 3.0;
        // If mean residual across open bins is small, existing bins are full-ish;
        // opening a new bin becomes more reasonable.
        score -= mean_residual * 0.6;
        // If the item is large relative to capacity, opening fresh is fine.
        score -= item_size as f64 * 0.3;
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 25.0;
        }
    } else {
        // Filling existing bins: reward when leftover can host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // Reward using bins with low residual (consolidate fullness).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;
    }

    // Mild global pressure: as the stream progresses, avoid waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // If the next item exactly fills this bin's post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after two items
        } else if next_item_size < post_residual {
            // Next item fits too: reward proportional to how tightly it nests,
            // and extra reward if the pair leaves a "nice" residual (small or large).
            let two_step = post_residual - next_item_size;
            let tight = 1.0 - (two_step as f64 / bin_capacity as f64);
            score -= 12.0 + 25.0 * tight;
            // Bonus if the two-step leftover is a commonly usable size (>= 10)
            if two_step >= 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how isolated this bin is among fitting options.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully.
    let mean_r = mean_residual;
    if (bin_residual as f64) < mean_r {
        // Tighter than average bin: placing here consolidates fullness.
        score -= 6.0 * (mean_r - bin_residual as f64).min(30.0) / 30.0;
    } else {
        // Looser than average: mild penalty to avoid fragmenting many bins.
        score += 3.0 * ((bin_residual as f64) - mean_r).min(30.0) / 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: brand-new empty bin should only win when
    // the item is huge relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / (1.0 + total_items as f64));
        // Large items prefer fresh bins (near-perfect packing); small items prefer reuse.
        score += 55.0 * (1.0 - frac) - 10.0 * pressure.min(5.0);
        // If the next item is small and would pair well in a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight stream-position adaptation: early on, be more willing to open bins
    // (keep flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good, but avoid tiny dead space).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if fit_ratio < 0.10 {
        score -= 15.0 * (0.10 - fit_ratio) * bin_capacity as f64;
    } else if fit_ratio > 0.60 {
        score += 10.0 * (fit_ratio - 0.60); // penalize wasteful placements
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score -= 15.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    }
    // Penalize blocking the next item when this bin is the only option.
    if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count == 1 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits or are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = open_bins_count as f64 / 20.0;
        let poor_pool = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        let pressure = 0.5 * crowded + 1.2 * poor_pool + 0.3 * time_frac;
        score = score + 45.0 - 55.0 * pressure.min(1.0);
        // Never open a new bin for a small item when residual capacity is plentiful.
        if item_size < 30 && mean_residual > 60.0 {
            score += 50.0;
        }
    }

    // Mild preference for filling bins that are already more depleted than average.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = base * base * (1.0 + 2.0 * progress) + base * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let mut score = poly * cap;

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (0.5 + progress);
        } else {
            score -= (pr - nxt) * 0.4;
        }
    }

    // Last chance bin: strongly reward using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 10.0 * progress;
    }

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 0.05 * open_bins_count as f64;
    } else {
        // Reward using existing bins relative to mean residual
        score -= (mean_residual - pr).clamp(-cap, cap) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter-band of capacity does it fall in
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let band = if post_residual == 0 { 0 }
        else if post_residual <= quarter { 1 }
        else if post_residual <= half { 2 }
        else if post_residual <= 3 * quarter { 3 }
        else { 4 };

    // Reward near-perfect fills heavily; penalize large dead space non-linearly
    match band {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 5.0,
        3 => score += 10.0,
        _ => score += 25.0,
    }

    // Harmonic compatibility: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward, scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 20.0 + 20.0 * tight;
        } else {
            // next item cannot use this residual: penalize by leftover gap size
            let gap = next_item_size - post_residual;
            score += (gap as f64).sqrt() * 4.0;
        }
        // modular resonance: next item leaves a small residue again
        if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= quarter { score -= 15.0; }
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // but early in the stream, or when open bins are crowded, fresh bin is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        if mean_residual < cap * 0.25 { score -= 15.0; }
    }

    // Prefer fuller bins when many bins are open (bin-count pressure)
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= fill_ratio * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Mean-residual coupling: if this bin is much emptier than average, deprioritize
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space that cannot fit even the smallest possible item is pure waste.
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.1;

    // Last-chance bin: strongly favor filling it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidation into existing bins
    // and discourage opening new ones.
    let pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 20.0 * pressure;
    } else {
        score -= pressure;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Late in the stream, tighten up to avoid wasted bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual == 0) as i32 as f64;
    score += 5.0 * progress * ((post_residual > 0 && post_residual < 10)) as i32 as f64;

    // Prefer bins with below-mean residual (filling emptier bins first keeps big gaps available).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is quadratic in waste).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: strongly favor bins where the next item
    // also fits into the remaining space (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = post_residual - next_item_size;
        score -= 20.0 + 0.5 * (next_item_size as f64);
        if chain_waste == 0 {
            score -= 30.0; // perfect 2-item chain
        } else if chain_waste <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize leaving medium dead space.
        if post_residual >= 10 && post_residual < next_item_size {
            score += 0.3 * (post_residual as f64);
        }
    }

    // Penalize creating dead space below the minimum item size (unusable gap),
    // assuming minimum plausible item ~10; smaller gaps are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits
    // poorly everywhere else (large post_residual waste avoided by fresh space).
    if bin_residual == bin_capacity {
        // New bin baseline: slight penalty so open bins with good fits win,
        // but competitive when open bins would leave big unusable gaps.
        score += 8.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // Fresh bin supports the next item too; make it attractive when
            // mean residual across open bins is already fragmented.
            if mean_residual < 25.0 && open_bins_count > 0 {
                score -= 20.0;
            }
        }
    }

    // Mild pressure to consolidate: prefer bins whose residual is already
    // below mean (tighter bins get filled first).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
    }

    // Late-stream urgency: as the stream ends, waste matters less than
    // avoiding new bins; tighten consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score -= 12.0;
    } else {
        // penalize dead space quadratically, normalized by capacity
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; if next item
    // would fit better elsewhere, mild penalty for consuming this bin.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here blocks next item from using this bin
            score += 4.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residual space flexible); late in the stream, consolidate.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 8.0 * progress;

    // New-bin candidate handling: empty bin gets a base penalty so we prefer
    // existing bins unless their fit is poor; penalty shrinks when open bins
    // are crowded (high mean residual, many bins with low average space).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // If mean residual across open bins is small, open bins are crowded:
        // opening a new bin is more attractive.
        new_bin_penalty -= 0.15 * mean_residual;
        // If many open bins can fit, definitely prefer them.
        new_bin_penalty += 2.0 * fitting_bins_count as f64;
        // Late in stream, avoid spawning bins unnecessarily.
        new_bin_penalty += 10.0 * progress;
        // Large items relative to capacity prefer fresh bins.
        new_bin_penalty -= 0.1 * item_size as f64;
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for bins with residual much larger than item (wasteful pairing).
    if bin_residual > item_size * 2 && bin_residual != bin_capacity {
        score += 0.05 * (bin_residual - item_size * 2) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let mut score = pr * (1.0 + 0.35 * progress);

    // Smooth polynomial coupling of post_residual with stream progress
    score -= 8.0 * (1.0 - prn) * (1.0 - prn) * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item (smooth ramp)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 1.5 * gap * (0.5 + progress);
    }

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - prn);
    }

    // New-bin candidate: penalize mildly unless residuals are tight
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - progress) - 0.05 * mean_residual;
    }

    // Mild penalty for spreading across many open bins when residual is small
    score += 0.02 * open_bins_count as f64 * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Penalize dead space in awkward harmonic bands (odd eighths are hard to fill).
    let band = post_residual / eighth.max(1);
    if band % 2 == 1 && post_residual < item_size.max(1) {
        score += 12.0;
    }
    if post_residual < quarter && post_residual > 0 {
        score += 8.0; // small unusable sliver
    }

    // Reward near-perfect fits (residual in low harmonic classes).
    if post_residual <= eighth {
        score -= 15.0;
    } else if post_residual <= quarter {
        score -= 7.0;
    }

    // Lookahead coupling: does post_residual fit next item nicely?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Harmonic residue classes of next item vs post_residual.
            let r = post_residual % next_item_size.max(1);
            if r == 0 {
                score -= 18.0; // exact divisor: perfect chain
            } else if r <= eighth {
                score -= 10.0;
            } else {
                score += 4.0 * (r as f64) / cap;
            }
            score -= 6.0 * (nx / cap);
        } else {
            // next item won't fit here; penalize wasting space
            score += 5.0 + 10.0 * (pr / cap);
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild preference to fill existing bins when many are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Stream progression: early on, be picky; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (pr / cap);

    // Mean residual anchoring: bins far from the mean residual get normalized.
    score += 0.15 * ((pr - mean_residual).abs());

    // New-bin candidate: make it unattractive unless residual logic says otherwise.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is huge relative to mean residual of open bins, new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10) are nearly unusable
    // dead space, penalize them heavily (superlinear in how "dead" they are).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 {
        // Usable leftover: reward proportionally, but taper for large gaps
        // that any future item could still fill anyway.
        score -= 8.0 * (post_residual as f64).ln().max(0.0);
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, favor tight fills
    // (small post_residual) even more; when few bins are open, allow slack.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, reward it; if the residual is just barely too small for the
    // next item, penalize the "almost useful" gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        } else if post_residual - next_item_size < 10 {
            score += 15.0; // leaves fresh dead space after next item
        }
    }

    // Slight preference for filling emptier-than-average bins early on,
    // keeping large residuals available later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (bin_residual as f64) > mean_residual {
        score += 5.0 * (1.0 - progress);
    }

    // New-bin candidate: only open a new bin when the current item fits
    // badly everywhere (large waste) or no usable alternative exists.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 35.0 + waste * 0.6 - 20.0 * (fitting_bins_count == 1) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;

        // Exact match for the next item: strong reward
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Next item fits snugly with room to spare
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 50.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Penalize tiny unusable dead space (but reward exact/near-exact fits handled above)
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 60.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
    }

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 14.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mild penalty proportional to gap.
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (keep large-residual bins flexible).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 8.0 + 20.0 * progress + 0.4 * open_bins_count as f64;
    } else {
        score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for filling more of the bin overall.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: reward tight fits (low post_residual), smoothed polynomial
    let mut score = 2.5 * x * x - 0.5 * x;

    // Non-linear coupling of post_residual with stream progress:
    // early stream -> tolerate slack; late stream -> penalize residual waste more
    let progress_coupling = (x * x) * (0.6 + 2.4 * progress * progress);
    score += progress_coupling * cap * 0.05;

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.4 + 0.8 * progress);
        } else {
            // smooth reward when next item fits into the leftover
            let fit_smooth = (pr - nx) / cap;
            score -= 0.6 * (1.0 - fit_smooth * 2.0).max(0.0);
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.5 + 1.5 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.05 * x;

    // Encourage using bins below mean residual (balancing)
    score -= 0.1 * (mean_residual - pr) / cap;

    // New-bin candidate: neutral-ish baseline, penalized unless item is large
    if bin_residual == bin_capacity {
        score += 1.2 - 0.008 * item_size as f64 + 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    // Penalize leftovers that are "awkward" — not multiples of common item sizes.
    // Harmonic classes: leftover mod 10, mod 25, mod 50 (typical item granularity).
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    let mod50 = post_residual % 50;
    // Perfect harmonic leftover (0 mod 50, or 0) is highly reusable.
    let harmonic_bonus: f64 = if post_residual == 0 {
        -40.0
    } else if mod50 == 0 {
        -25.0
    } else if mod25 == 0 {
        -15.0
    } else if mod10 == 0 {
        -8.0
    } else {
        // Non-harmonic: penalize proportionally to how far from a multiple of 10.
        4.0 + (mod10 as f64) * 0.8
    };
    score += harmonic_bonus;

    // Non-linear waste term: squared fraction penalizes large dead space.
    score += 12.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Harmonic match on integer division thresholds.
            let q = post_residual / next_item_size.max(1);
            score -= 6.0 * (q as f64).min(3.0);
        } else {
            // Next item won't fit here; small penalty scaled by overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over.min(30.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current fit is terrible or
    // open-bin pool is saturated with small residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.85;
        // Attractive if the item is large (leaves small residue) — harmonic class of item.
        let imod = item_size % 25;
        if item_size >= 75 || imod == 0 {
            score -= 20.0;
        }
        // If no bin fits (this is the only option), the caller must open anyway;
        // make score consistent by subtracting fitting pressure.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in stream, slightly cheaper to open bins (builds pool diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Prefer tighter fits: reward small bin_residual relative to item.
        let tight = (bin_residual - item_size) as f64 / cap;
        score += 10.0 * tight;
        // Prefer bins whose residual is below mean (consolidation of fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild preference to spread across many bins late in stream is wrong for
    // minimization; instead reward using existing bins when pool is large.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fill, treat as perfect (shouldn't happen, but safe)
        score -= 500.0;
    }

    // Unusable dead space: post_residual too small to hold the next item
    // (when known) is wasted capacity unless it is near zero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }
    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, discourage spreading further;
    // favor packing into existing bins (lower post_residual already helps).
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin costly unless the item is
    // large and would leave a well-usable residual, or no open bin fits.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 45.0;
        // Large items leave large residuals in a fresh bin: acceptable.
        if item_size as f64 >= 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If no open bin fits at all, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild bonus for bins below mean residual (balancing residual spread
    // reduces fragmentation across the fleet).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near match of leftover to the next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect match: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += 20.0;
    }

    // Penalize dead space that no plausible item (>=1) can use well: tiny residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer filling bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        let pressure = open_bins_count as f64 / (step_index as f64 / total_items.max(1) as f64).max(1.0);
        if poor_fit && next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0 + pressure * 0.5;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for tighter bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit * fit;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still fit here: reward.
            score -= 6.0;
        } else if post_residual > 0 {
            // Dead space: penalize proportionally to wasted chunk.
            score += 0.5 * (post_residual as f64);
        }
    } else {
        // Last item: waste minimization only.
        score += 0.1 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits everywhere)
    // or when many bins exist but none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // Base penalty so new bins are not opened frivolously.
        score += 30.0;
        // Relax penalty when open bins are poor hosts.
        score -= 0.4 * avg_fit_gap;
        // Late in the stream, avoid spawning bins for small leftovers.
        if item_size <= 20 && progress > 0.5 {
            score += 15.0;
        }
        // If next item is large and current bin is full-ish, new bin is fine.
        if next_item_size >= 60 && mean_residual < 40.0 {
            score -= 10.0;
        }
    } else {
        // Slight preference for filling more-occupied bins first.
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Prefer bins that leave room compatible with average residual demand.
        if post_residual as f64 > mean_residual {
            score += 3.0;
        }
    }

    // Mild global pressure: when many bins are open, discourage fragmentation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear penalty for small post residuals (dead space), smoothed polynomial
    let pr_norm = pr / cap;
    score += 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm * 4.0;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * progress * tightness * tightness;

    // Lookahead coupling: reward bins whose post residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / pr).powi(2));
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with below-mean residual (consolidate large gaps)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference to reuse existing bins over opening new ones
    if bin_residual as f64 == cap {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: mod-10 classes capture typical
    // item-size granularity; small post_residuals are dead space.
    let pr = post_residual as i64;
    let class = pr % 10;
    match class {
        0 => score -= 12.0,          // perfectly divisible residual, reusable
        1 | 2 => score -= 4.0,       // near-perfect, small items fit
        8 | 9 => score += 6.0,       // awkward residual, likely dead
        _ => score += 1.0,
    }

    // Integer-division thresholds: residual in [1..10] is nearly dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Lookahead harmonic: does next_item_size divide / fit into post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let prf = post_residual as f64;
            let ratio = nxt / prf;
            // reward when next item consumes most of the residual
            score -= 14.0 * ratio * ratio;
            // harmonic class of leftover after next item
            let after = post_residual - next_item_size;
            if after % 10 == 0 { score -= 8.0; }
            if after > 0 && after < 10 { score += 10.0; }
        } else {
            score += 5.0; // next item can't use this bin's residual
        }
    }

    // Last chance: only fitting bin — strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when fitting bins exist,
    // unless mean residual is very small (all bins nearly full).
    if bin_residual == bin_capacity {
        let frac = mean_residual / cap;
        score += 18.0 - 30.0 * frac;
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
    }

    // Prefer fuller bins overall: reward low residual relative to mean.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 6.0 * (1.0 - res_f / mean_residual.max(1.0));
    }

    // Small item into large residual: fine; large item into tight fit: good.
    let tight = (bin_residual - item_size) as f64 / cap;
    score += 10.0 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (assume ~10) are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Penalize "awkward" residuals: gaps in the classic hard-to-fill zone.
    if post_residual > 0 && post_residual <= 25 {
        score += 15.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when
    // many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline at capacity, adjusted by open-bin load.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Mild reward for using an existing bin relative to mean residual:
        // prefer bins tighter than average.
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect 2-chain match: strong reward
        if diff < 0.5 {
            score -= 40.0;
        } else if post_residual as f64 >= look {
            // residual can host next item: reward proportional to tightness
            score -= 20.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // dead space that cannot host next item: penalize
            score += 8.0 * (1.0 - (post_residual as f64) / 100.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless the current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a new bin is fine if next item is huge and this bin would be left fragmented
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Small perfect fits (item nearly fills bin) are excellent
    if post_residual < 10 && post_residual > 0 {
        score -= 12.0;
    }

    // Late in stream: consolidate, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0 is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that likely cannot be used later.
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += 0.35 * (waste / 10.0).powi(2) * (1.0 - tightness);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 + 0.1 * item_size as f64;
    }

    // Many fitting bins: this bin is less critical; mild penalty to prefer
    // exploring alternatives unless the fit is very tight.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(6.0) * (1.0 - tightness);
    }

    // Global state coupling: prefer filling bins with large residuals when
    // mean residual is high (consolidate space); prefer tight bins when low.
    let mr = mean_residual.max(0.0);
    let residual_gap = bin_residual as f64 - mr;
    score += 0.08 * residual_gap * (1.0 - tightness);
    score -= 0.05 * residual_gap * tightness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    score += (1.0 - progress) * 6.0 * (1.0 - tightness);
    score -= progress * 4.0 * tightness;

    // New-bin candidate: baseline cost of opening a bin, modulated by how
    // badly the item fits existing bins and stream position.
    if bin_residual == bin_capacity {
        score += 20.0
            - 14.0 * progress
            + (fitting_bins_count as f64).recip() * 5.0
            - 0.1 * item_size as f64;
        // If next item is huge, opening a fresh bin may be wise.
        if next_item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild penalty on opening too many bins relative to stream length.
    let density = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 40.0 * density * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smoothly growing penalty for large dead space as stream progresses
    score += 12.0 * prn * prn * (prn - 1.0).abs() * (1.0 + progress);

    // Perfect fit reward, stronger later in the stream
    if pr == 0 {
        score -= 50.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = next_item_size as f64 / pr.max(1.0);
        score -= 10.0 * tight * (1.0 + progress);
    } else if next_item_size > post_residual {
        score += 5.0 * progress;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual - cap * 0.5).abs() / cap;
        score += 8.0 + 6.0 * progress + 4.0 * frag;
    }

    // Mild preference for tighter-than-average bins
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    if post_residual > 0 {
        score += 30.0 / post_residual as f64;
    } else {
        score -= 25.0; // perfect fill bonus
    }

    // Harmonic class: classify post_residual by integer division thresholds
    // (dead-space classes). Penalize residuals in "hard to fill" bands.
    let pr = post_residual as u32;
    let class = pr / 10; // decade class
    match class {
        0 => score -= 5.0,          // 0-9: nearly full, good
        1 => score += 2.0,          // 10-19: awkward small gap
        2 => score -= 1.0,          // 20-29: fits mid items
        3 => score += 4.0,          // 30-39: awkward
        4 => score += 6.0,          // 40-49
        _ => score += 1.0,          // large residual: near-empty bin
    }

    // Modulo arithmetic on capacity fractions: penalize residuals that are
    // "odd" w.r.t. common item sizes (waste that rarely pairs).
    if pr > 0 && pr < 10 {
        score += 8.0; // sliver waste
    }
    if pr % 2 == 1 && pr < 20 {
        score += 3.0; // odd small residual pairs poorly
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // partial reward scaled by how well next item uses the gap
        let usage = next_item_size as f64 / pr as f64;
        score -= 10.0 * usage;
    } else if next_item_size > pr {
        // next item won't fit here; penalize leaving gap it could have used elsewhere
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets moderate score so it wins
    // only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a "junk" bin; using it cleans up the pool.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a good lookahead fit
    // or open bins are congested; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 15.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 20.0; // new bin can also host the next item
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            nb -= 5.0;
        }
        nb -= progress * 5.0; // late in stream, consolidate
        score += nb;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score += 8.0; // would leave another dead gap
    }

    // Mild pressure from many open bins: prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins tighter than average residual (best-fit coupling).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches with lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - diff / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post residual smaller than next item: dead space unless tiny
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Penalize large post_residual relative to mean residual (wasteful placement)
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless nothing fits (handled by fitting_bins_count==0 case implicitly via competition)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 30.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 1000.0; // nothing fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit a typical future item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect pair packing
        if post_residual > 0 && (post_residual == next_item_size) {
            score -= 15.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        let base = 18.0 + 30.0 * (1.0 - fit_ratio);
        score += base - 25.0 * progress;
        // Avoid bin proliferation when many bins already open
        score += 0.6 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (balance / spread usage)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for fuller bins
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Prefer tight fits: reward small post_residual quadratically.
    score -= (1.0 - post / cap).powi(3) * 40.0;

    // Dead-space penalty: mid-range residuals are least usable.
    let post_norm = post / cap;
    score += 15.0 * post_norm * (1.0 - post_norm) * (1.0 - post_norm);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: smooth logistic gate that opens more readily early in stream
    // or when the item fits poorly everywhere.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        let openness = 1.0 / (1.0 + (-(progress - 0.5) * 4.0).exp());
        let poor_fit = 1.0 / (1.0 + (-(post_norm - 0.4) * 8.0).exp());
        let next_waste = if next_item_size > 0 {
            1.0 / (1.0 + (-(next_item_size as f64 - post).abs() / 20.0).exp())
        } else { 0.0 };
        score -= 30.0 * openness + 45.0 * poor_fit + 10.0 * next_waste;
    }

    // Lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < 1e-6 {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size as u32 <= post_residual {
        score -= 8.0 * (1.0 - (next_item_size as f64 - post).abs() / cap);
    }

    // Mean residual coupling: bins deviating from mean residual get mild penalty
    // to keep bin pool homogeneous (easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * (1.0 + progress);

    // Mild congestion pressure: more open bins -> favor filling existing ones.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: penalize residuals that are
    // "dead zones" — too small to fit typical items (1..=100 range).
    if post_residual > 0 {
        // Residual below the smallest item class is pure waste.
        if post_residual < 10 {
            score += 60.0;
        }
        // Modulo-classes: residuals near half-capacity multiples are flexible.
        let half = bin_capacity / 2;
        let quarter = bin_capacity / 4;
        if post_residual == half || post_residual == quarter || post_residual == 3 * quarter {
            score -= 25.0;
        }
        // Penalize residuals in awkward bands (just below common item sizes)
        for t in [20u32, 30, 40, 50, 60, 70, 80, 90] {
            if post_residual % 10 != 0 && post_residual < t && post_residual + 5 > t {
                score += 15.0;
            }
        }
        // Integer-division harmonic: reward residuals divisible into
        // likely future item sizes (divisible by 10).
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 20.0; // next item can't use this leftover
    }

    // Last-chance bonus: only bin that fits; avoid opening a new bin
    // unless fit is really bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when
    // current fit is poor (large post_residual waste) or few open bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // item placed in fresh bin
        // Default moderate penalty so existing decent fits win.
        score = 0.5 * cap + waste * 0.3;
        if fitting_bins_count == 0 {
            score -= 2000.0; // must open a new bin
        }
        // Prefer fresh bin late in stream when open bins are fragmented.
        if open_bins_count > 0 && mean_residual < item_size as f64 {
            score -= 100.0;
        }
        // If the only fitting bin leaves a tiny dead residual, open new bin.
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
            score -= 150.0;
        }
    }

    // Mild progression term: early on, keep bins balanced.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64).abs() * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize unusable dead space: gaps too small for the minimum plausible item.
    // Treat post_residual in (0, 10) as pure waste; scale harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 40.0;
    } else {
        // Mild reward for small-but-usable residuals, decaying with size.
        score -= 8.0 * (1.0 - post / cap) * (1.0 - post / cap);
    }

    // Reward bins whose residual matches the next item size (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't fit next item: penalize proportionally.
        score += 6.0 * (1.0 - post / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize base cost plus pressure from open bins.
        score += 30.0 + 8.0 * (open_bins_count as f64) + 10.0 * (1.0 - progress);
        // But if no open bin fits well, allow opening (handled by relative scoring).
        if post_residual == 0.0 {
            score += 0.0;
        }
    } else {
        // Mild preference for tighter (more filled) existing bins.
        score += 4.0 * (mean_residual - post).abs() / cap;
    }

    // Penalize leaving residuals that are awkward multiples near mid-range.
    if post_residual >= 10 && post_residual <= 20 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: reward proportional to closeness
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            // bonus if next item then leaves small residual (tight chain)
            let chain_res = post_residual - next_item_size;
            if chain_res <= 10 {
                score -= 15.0;
            }
        } else {
            // next item won't fit: penalize leftover dead space
            score += 10.0 + 0.3 * (post_residual as f64 - next_item_size as f64).abs();
        }
    } else {
        // Last item: just minimize residual
        score -= 5.0;
    }

    // Penalize large dead space that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny leftover is fine (near-perfect fit)
    }
    if post_residual > 50 {
        score += 8.0; // wasteful large leftover
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    if (post_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if no open bin can fit at all, allow it
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early stream: be slightly conservative, keep bins flexible
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer tightening existing ones
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste by relative fill.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill * fill;

    // Penalize small dead space that nothing can use later (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual - item_size as f64;
        if avg_waste > 0.0 {
            score -= 15.0 * (avg_waste / bin_capacity as f64).min(1.0);
        }
        // Slightly discourage new bins when many bins are open and usable.
        score += 0.3 * open_bins_count as f64;
    }

    // Time horizon: early in stream, keep bins flexible (mild penalty for
    // very tight fills); late in stream, aggressively close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 8.0 * progress * fill;
    } else {
        score += 4.0 * (1.0 - progress) * (1.0 - fill);
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (i.e., more filled than typical) to consolidate waste.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item_frac = item_size as f64 / cap;
    let post_frac = post / cap;
    let mean_frac = mean_residual / cap;
    let next_frac = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear waste penalty: dead space below typical item sizes is costly.
    let waste_curve = post_frac * post_frac * (1.0 - post_frac) * (1.0 - post_frac);
    score += 60.0 * waste_curve * (0.5 + t);

    // Smooth interaction: progress x fit quality coupling.
    let fit_quality = 1.0 - (item_size as f64 / bin_residual as f64);
    score += 40.0 * t * fit_quality * fit_quality;

    // Divergence from mean residual (smooth quadratic coupling).
    score += 15.0 * (post_frac - mean_frac) * (post_frac - mean_frac) * cap * 0.01;

    // Lookahead: penalize if post-residual cannot host the next item (smooth).
    if next_item_size > 0 {
        let gap = next_frac - post_frac;
        let incompat = gap.max(0.0) / (gap.max(0.0) + 0.05);
        score += 25.0 * incompat * (1.0 - t * 0.5);
        // Reward residual that smoothly matches next item.
        let match_term = 1.0 - ((post_frac - next_frac).abs() / (post_frac + next_frac + 0.01));
        score -= 20.0 * match_term * match_term * post_frac;
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 * (1.0 - t * 0.3);
    }

    // New-bin candidate adjustment: prefer opening a fresh bin when the item
    // would leave a large unusable remainder in an existing bin.
    if bin_residual == bin_capacity {
        let new_bin_bonus = post_frac * (1.0 - post_frac);
        score -= 35.0 * new_bin_bonus * (0.4 + 0.6 * t);
        score -= 10.0 * item_frac * item_frac;
    } else {
        // Slight penalty for consuming a well-filled bin with a small item.
        let tightness = 1.0 - post_frac;
        score += 12.0 * item_frac * (1.0 - item_frac) * (1.0 - tightness);
    }

    // Mild pressure against bin proliferation early in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" classes (0, or small values that pair well with typical items)
    // are preferred. Penalize dead space that is hard to fill.
    let cap = bin_capacity as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual modulo common item-size classes.
    // Items 1..100, so classes of 10 and 5 are natural harmonic buckets.
    let pr = post_residual;
    let class10 = pr % 10;
    let class5 = pr % 5;

    // Leftovers that are small but non-zero are nearly dead space: penalize.
    if pr > 0 && pr < 10 {
        score += 30.0 * (10 - pr) as f64;
    }

    // Leftovers that are multiples of 10 are reusable by many item classes.
    if class10 == 0 && pr > 0 {
        score -= 12.0;
    } else if class5 == 0 && pr > 0 {
        score -= 6.0;
    } else {
        // Off-class leftover: penalize proportional to distance from nearest
        // multiple of 5.
        score += 4.0 * (class5.min(5 - class5) as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            // Next item fits: leftover after next placement, same harmonic logic.
            let pr2 = pr - next_item_size;
            if pr2 == 0 {
                score -= 150.0;
            } else if pr2 < 10 {
                score += 8.0;
            } else if pr2 % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this leftover: leftover is likely dead.
            score += 10.0 + 0.15 * pr as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if pr < 5 {
            score += 20.0; // nearly dead space anyway
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Base its score on mean residual of open bins.
    if bin_residual == bin_capacity {
        // Neutral base for empty bin; becomes attractive if open bins are messy.
        score = 55.0 + mean_residual * 0.4;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // new bin can host the next item too
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild tie-break toward tighter bins relative to the mean residual.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Small preference for fewer open bins (encourage consolidation early).
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Small nonzero post_residuals are "unusable gaps": penalize them hard.
    // A perfect fit (post_residual == 0) gets a strong reward.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 25 {
        // The smaller (but nonzero) the gap, the worse the dead space.
        score += (25 - post_residual) as f64 * 1.8;
    }

    // Coupling with mean residual: bins already tighter than average are
    // natural continuation targets; loose bins (above mean) are wasteful.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // --- open_bins_count pressure ---
    // Opening a new bin is penalized proportionally to how many bins are
    // already open, so consolidation is preferred unless fits are terrible.
    if is_new_bin {
        score += 30.0 + open_bins_count as f64 * 1.2 + progress * 10.0;
    } else {
        // Mild reward for reusing an existing bin.
        score -= 4.0;
    }

    // Last-chance bin: if this is the only open bin that fits the item,
    // strongly prefer it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    }

    // --- Lookahead (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Leaving room for the next item is valuable: reward.
            score -= 10.0;
        } else if post_residual > 0 {
            // The leftover gap cannot host the next item: penalize dead space.
            score += (next_item_size.min(bin_capacity) - post_residual.min(next_item_size)) as f64 * 0.5;
        }
        // A new bin whose residual accommodates the lookahead item is decent.
        if is_new_bin && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Late in the stream, favor squeezing into existing bins even harder.
    if !is_new_bin {
        score -= progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact pairing with the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.5;
        // Perfect chain: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits snugly but not perfectly.
        else if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - diff as f64 / 100.0);
        }
        // Next item cannot use this residual at all: residual is likely dead space.
        else {
            score += 10.0;
        }
    }

    // Penalize leaving small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin for a decent fit.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 as u32 {
        score -= 20.0;
    }

    // Late in the stream, prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large and few bins fit it.
        score += 30.0 - 40.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it when existing residuals are large and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 - 10.0 * progress - 0.05 * fragmentation - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (fill the emptier-feeling bins less,
    // keep balanced residuals): slight pull toward mean.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let tightness = 1.0 - (fit / cap); // 0 = perfect fit, larger = looser

    // Base: prefer small post_residual, with smooth polynomial coupling to progress.
    let mut score = post * (1.0 + 0.6 * progress * post / cap);

    // Penalize wasted space quadratically (dead space grows worse over time).
    score += 0.35 * (post / cap).powi(2) * cap * (0.5 + progress);

    // Reward tight fits (small tightness) with smooth interaction.
    score -= 12.0 * (1.0 - tightness).powi(2) * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = (post - next_item_size as f64) / cap;
        score -= 18.0 * (1.0 - gap).powi(2);
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: mild penalty scaled by how close it was.
        let miss = ((next_item_size as f64 - post) / cap).min(1.0);
        score += 8.0 * (1.0 - miss).powi(2);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Prefer bins whose residual deviates from the mean in a "completable" way:
    // favor bins with residual close to (but >=) item_size relative to mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev * (1.0 - progress);

    // New-bin candidate: make it attractive only when current fits are loose,
    // so an empty bin wins over poor fits; otherwise discourage it.
    if bin_residual == bin_capacity {
        let empty_penalty = 30.0 + 40.0 * (1.0 - tightness);
        score += empty_penalty * (1.0 - 0.5 * progress);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open.
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Leftovers in "dead" classes (very small)
    // are penalized; leftovers that match common small-item sizes are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: tiny leftover (< 10) is nearly unusable.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Harmonic class reward: leftover divisible into nice fractions of capacity
    // (post_residual in {0, 25, 33, 50, 66, 75} region or multiples of 10)
    // is more likely to be filled later.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly into this bin: strong reward,
            // scaled by how snugly it fits (small gap better).
            let gap = (post_residual - next_item_size) as f64;
            score -= 14.0 - (gap / cap) * 8.0;
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this leftover: mild penalty proportional
            // to how far off it is, unless leftover is large anyway.
            let miss = (next_item_size - post_residual) as f64;
            if pr < cap * 0.5 {
                score += miss * 0.15;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // even a dead-space fit beats opening a bin here
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it when the item fits poorly everywhere (large item, many bins)
    // and the stream is early (more future items to fill the fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // Base reluctance to open new bins: keeps open-bin usage preferred.
        score += 15.0;
        // Open a new bin for big items or when few bins can fit the item.
        if item_frac > 0.6 {
            score -= 22.0 * item_frac;
        }
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
        // Early in the stream, a fresh bin is cheap insurance.
        score -= (1.0 - progress) * 8.0;
        // Many open bins with high mean residual: reuse instead.
        score += open_bins_count as f64 * 0.6;
        if mean_residual > cap * 0.5 {
            score += 6.0;
        }
    }

    // Prefer tighter fits generally: residual tightness coupling.
    score += (pr / cap) * 4.0;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else {
        // Reward tight fits: scale down score when fill ratio is high.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * fill;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity && item_size > 0;
    if new_bin {
        score += (open_bins_count as f64) * 8.0;
        // Late in stream, opening new bins is extra costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the dead space we create, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // Prefer bins below mean residual (use up emptier space less; prefer tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact-ish fits (small dead space)
    score -= 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6) * bin_capacity as f64 * 0.5;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 40.0; // perfect chain
        } else if post_residual >= next_item_size {
            // next item fits: penalize leftover after chain
            let chain_left = post_residual as f64 - nr;
            score -= 15.0 * (1.0 - chain_left / bin_capacity as f64).powi(4);
        } else {
            // next item won't fit: penalize large post residual that becomes dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: make it attractive only when open bins would be badly fragmented
    if bin_residual == bin_capacity {
        let bad_open = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // penalize new bin generally, but allow it when open bins are highly fragmented
        score += 30.0 - 45.0 * bad_open.max(0.0);
    }

    // Mild penalty for proliferating bins over stream progression
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the smallest possible item (1..100 range, be conservative at 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
