            score += 6.0;
        }
    }

    // New-bin candidate handling: make opening a new bin costly unless current fits are all poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, slightly cheaper to consolidate into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Prefer bins below mean residual (balancing), but only mildly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer fuller bins among many open bins (encourage consolidation).
    score += 0.05 * (open_bins_count as f64 - 1.0).max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
