    // Non-linear coupling: tight fits rewarded, scaled by stream progress.
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness.powf(2.0) * (1.0 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let wasted = (nxt - pr).max(0.0);
        score += 0.8 * wasted * (0.5 + 0.5 * progress);
        // Reward residuals that exactly accommodate the next item.
        let gap = (pr - nxt).abs();
        score -= 12.0 * (1.0 - gap / cap).max(0.0).powf(3.0);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference to keep residuals near the mean (balance across bins).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: slightly penalize early, tolerate late when fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits. Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class logic: bucket post_residual by capacity fractions.
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac <= 0.05 {
            score -= 200.0;
        } else if frac <= 0.10 {
            score -= 100.0;
        } else if frac <= 0.20 {
            score -= 30.0;
        } else if frac <= 0.35 {
            score -= 5.0;
        } else {
            // Large dead space: penalize proportionally beyond base residual.
            score += frac * 150.0;
        }

        // Integer-division threshold: residual divisible into small chunks is reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 5 == 0 {
            score -= 4.0;
        }

        // Lookahead: if the next item fits the post residual exactly, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size < post_residual {
                let next_waste = post_residual - next_item_size;
                if next_waste <= 10 {
                    score -= 60.0;
                } else if next_waste > 40 {
                    score += 20.0;
                }
            } else {
                // Next item won't fit here; residual becomes dead space.
                score += (post_residual as f64) * 0.5;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 80.0; // inherent cost of opening a bin
        // Early in the stream, opening fresh bins is cheaper (more future items to fill).
        new_bin_score -= (1.0 - progress) * 40.0;
        // If many bins are open with large mean residual, prefer reusing them.
        new_bin_score += open_bins_count as f64 * 3.0;
        new_bin_score += mean_residual * 0.3;
        // If this is the only fitting option, new bin is competitive.
        if fitting_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for very tight bins when many bins compete (keep flexibility).
    if fitting_bins_count > 3 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large residual remains usable
        }
    } else {
        score -= 80.0; // perfect fill
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Lookahead: bonus if next item fits into post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size as u32 == post_residual {
            score -= 70.0;
        } else if (next_item_size as u32) < post_residual {
            score -= 12.0;
        } else {
            score += 15.0; // next item won't fit here -> residual likely dead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new-bin consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (1.0 - progress);

    // Mean residual coupling: prefer bins deviating below mean (fill fuller bins first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: attractive when no open bin gives a decent fit,
    // unattractive when a good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 1 || (fitting_bins_count == 1 && post_residual < 15 && bin_residual != bin_capacity);
        if good_fit_exists {
            score += 120.0;
        } else {
            score -= 20.0;
        }
        // Slight early-stream preference for keeping options open with fresh bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big bonus (subtract).
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild bonus proportional to closeness.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted potential.
            score += 8.0 + diff * 0.1;
        }
    }

    // Reward tight packing relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize very small unusable dead space (< 10) slightly less than mid gaps,
    // but penalize leaving moderately small gaps that fit nothing.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Prefer filling nearly-full bins.
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Early in stream: slightly discourage opening too many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, reduced early, raised late.
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score -= 14.0 * (1.0 - residual_frac).powi(3);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that is too small for typical items (wasted gap).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward if the next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 12.0;
            let leftover = post_residual as f64 - next_item_size as f64;
            if leftover == 0.0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 0.06 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style refinement).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 20.0 * (1.0 - progress);
        // If few bins can fit the item, opening a new bin is less costly.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Large upcoming item: keep open bins' space free for it.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Slight preference for fewer open bins when fits are otherwise equal.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, small residuals are forgiven; later, dead space is penalized harder.
    let progress_penalty = norm_pr * norm_pr * (progress * progress * (1.0 - progress) * 4.0);
    score += progress_penalty * cap * 0.35;

    // Reward tight fits (small post_residual) more strongly as the stream advances.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= tightness * (6.0 + 10.0 * progress);

    // Penalize bins that leave a residual too small for the lookahead item
    // (smoothly, scaled by how "close" the next item would be to fitting).
    if next_item_size > 0 {
        let nx = next_item_size.min(bin_capacity) as f64;
        let shortfall = ((nx - pr) / cap).max(0.0);
        let wasted = 1.0 - (-shortfall * 6.0).exp();
        score += wasted * 4.0;
        // Reward if post_residual can still hold the next item (chain packing).
        let chain = 1.0 - ((pr - nx).abs() / cap).min(1.0);
        score -= chain * 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (smooth sigmoid on fitting_bins_count).
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).powi(2));
    score -= last_chance * 8.0;

    // Mild penalty for accumulating many open bins with scattered residuals.
    let scatter = (mean_residual - pr).abs() / cap;
    score += scatter * 1.5;

    // New-bin candidate (residual == capacity) gets a smooth opening cost that
    // shrinks as the stream progresses (late in the stream, prefer filling bins).
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits are gold.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows when leftover is too small for typical items.
        let min_item = 1u32;
        if post_residual < min_item {
            score += 500.0;
        }
        // Modulo-class penalty: leftovers that are awkward fractions of capacity
        // (e.g. tiny slivers) are unlikely to be reusable.
        let cap_frac = bin_capacity / 4; // quarter-capacity harmonic
        if post_residual < cap_frac / 4 {
            score += 60.0;
        }
    }

    // Reward tight fits: leftover much smaller than the item.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        if next_left == 0 {
            score -= 400.0;
        } else if next_left < bin_capacity / 10 {
            score += 20.0; // next placement would create a sliver
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize small leftovers more.
        if post_residual < bin_capacity / 10 {
            score += 35.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual; make it
    // attractive only when the current fit is poor or no good reuse exists.
    if bin_residual == bin_capacity {
        // Neutral baseline: slightly worse than a perfect fit, better than slivers.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count <= 1 {
            score -= 120.0; // prefer fresh bin over a forced bad fit
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Slight drift with stream progress: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Nudge toward bins with residuals close to the current fit (harmonic matching
    // via integer division of residual by item size class).
    let class_match = (bin_residual / item_size.max(1)) % 4;
    score -= match class_match {
        0 => 8.0,
        1 => 4.0,
        2 => 2.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future item are dead.
    // Progressive dead-space penalty: gaps in (0, 10) are worthless, larger gaps scale.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else {
        // Convex penalty on wasted space, strongest for medium-small gaps.
        let pr = post_residual as f64;
        score += 0.35 * (pr * (bin_capacity as f64 - pr) / bin_capacity as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 8.0 * pressure;
        // But allow a new bin if all open bins would leave bad dead space.
        if fitting_bins_count > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Existing bin: small reward for using it, growing with pressure.
        score -= 5.0 + 3.0 * pressure.min(3.0);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item can't use this residual: mild penalty proportional to gap mismatch.
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.10 * mismatch.min(50.0);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (keep bin
    // profile balanced), avoid extreme outliers unless it's a perfect fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late-stream consolidation: near the end, avoid leaving many small residuals.
    if progress > 0.8 && post_residual > 0 && post_residual < item_size.min(20) as u32 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post residual is good, but dead space
    // that is too small to ever be useful should be punished extra.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 5.0 {
            score -= 30.0; // excellent fill, almost exact
        } else if pr <= 10.0 {
            score -= 18.0; // still very tight
        } else if pr <= 20.0 {
            score -= 8.0; // decent
        } else {
            // large leftover: penalize proportionally to unusability
            score += (pr - 20.0) * 0.35;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Aggressive 2-step lookahead: strongly reward bins whose residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = pr - n;
            if slack == 0.0 {
                score -= 55.0; // chain: next item fills this bin perfectly
            } else if slack <= 10.0 {
                score -= 30.0;
            } else if slack <= 25.0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot fit here: penalize more the bigger the gap
            let gap = n - pr;
            score += gap * 0.6;
        }
    } else {
        // last item: just prefer tightest fit
        score += pr * 0.5;
    }

    // Compare against mean residual: bins with residual far below the mean
    // (already tight) are good targets; bins above mean are wasteful targets.
    score += (pr - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a reasonable fit, or the item is huge relative to
    // typical residuals. Otherwise push new bins to be unattractive.
    if bin_residual == bin_capacity {
        let tight_open = (mean_residual < item_size as f64 * 1.1) || fitting_bins_count == 0;
        if tight_open {
            score -= 20.0; // allow opening a fresh bin
        } else {
            score += 60.0 + (open_bins_count as f64) * 1.5; // prefer existing bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    // Slight stream-progress adaptation: later in the stream, be greedier
    // about tight fits (less room for experimentation).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= (1.0 - pr / bin_capacity as f64) * 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = pr
        - 12.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * cap * 0.25
        + 20.0 * fit_norm * fit_norm * fit_norm * cap * 0.5;

    // Smooth interaction of post_residual with stream progress:
    // early on, tolerate waste; late in the stream, penalize it harder.
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score += pr * 0.35 * (progress_coupling - 1.0);

    // Penalize bins whose residual deviates strongly from the mean residual
    // (encourages residual homogenization for future pairing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * 0.1;

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let gap_norm = gap / cap;
        score -= 15.0 * (1.0 - gap_norm) * gap_norm.max(0.0);
        // Penalize if post residual just barely misses the next item.
        let miss = (next_item_size as f64 - pr).max(0.0);
        score += 0.4 * miss;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress) * (1.0 - progress) + 10.0;
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.15 * open_bins_count as f64 * fit_norm;

    // New-bin candidate: make empty bins attractive only for large items
    // or when post_residual would be very small (excellent tight fit elsewhere is better).
    if bin_residual == bin_capacity {
        let item_norm = item_size as f64 / cap;
        score = cap * 0.9 - 25.0 * item_norm * item_norm - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual buckets via integer division
    let class = post_residual / 10;
    let phase = (post_residual % 10) as f64;

    // Reward tight fits strongly (small post_residual)
    score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic penalty: residuals that are "dead space" classes (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; // dead space class
    }
    if class == 1 { score += 12.0; }   // 10..19 residual mostly unusable
    if class == 2 { score += 5.0; }
    if class >= 5 && class <= 6 { score -= 8.0; } // sweet spot ~50-69

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0; // chainable
            // exact complement bonus (harmonic pairing)
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current fits are poor
    if bin_residual == bin_capacity {
        score += 55.0
            - 10.0 * mean_residual.min(100.0) / 10.0
            - (open_bins_count as f64).ln() * 5.0;
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Phase tie-breaker: prefer leaving residual on multiples of 5
    score += phase * 0.15;

    // Prefer bins with residual below mean (pack tight bins first)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< smallest plausible item) are pure waste.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += 40.0 * (dead_zone - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 25.0;
    }

    // Non-linear tightness reward: the closer the fill to capacity, the better.
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Penalize bins whose residual is barely above the item (awkward near-fit).
    if bin_residual > item_size && (bin_residual - item_size) <= 5 {
        score += 12.0;
    }

    // Open bins pressure: discourage proliferating bins mildly.
    score += open_bins_count as f64 * 0.4;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Reward opening a new bin when item is large relative to typical residuals,
        // or when next item is large (preserve space strategy).
        let large_next = next_item_size as f64 / bin_capacity as f64;
        score -= 8.0 + 15.0 * large_next;
        // Penalize opening new bins early in the stream when many bins fit the item.
        score += fitting_bins_count as f64 * 6.0;
        // Penalize new bin if mean residual across open bins is large (existing space wasted).
        score += mean_residual * 0.25;
    } else {
        // Prefer bins whose residual is closest to item size (best-fit coupling).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - next_tight / bin_capacity as f64);
        }
    }

    // Stream progression: later in stream, be greedier about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0; // near-perfect fit, minimal dead space
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0; // chain fit: next item closes this bin
        } else if post_residual > next_item_size {
            score -= 0.5 * (next_item_size as f64).min(post_residual as f64 * 0.5);
        } else {
            // next item won't fit here; penalize proportional to wasted potential
            score += 0.8 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    } else {
        // last item: prefer tightest fit
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize leaving residuals that are hard to fill (small odd gaps)
    if post_residual > 0 && post_residual < item_size.min(30) {
        score += 10.0;
    }

    // Relative to mean residual: prefer bins that are already fuller than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor;
    // but attractive early in the stream or when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 30.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 8.0;

    // Penalize creating dead space below the smallest possible item (1 here),
    // but especially dead space that no small item could usefully fill.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let nxt_waste = post_residual - next_item_size;
            score -= 10.0 - (nxt_waste as f64).min(10.0);
        } else {
            // Next item won't fit here; penalize slightly less if post_residual is large.
            score += (next_item_size as f64 - post_residual as f64) * 0.2;
        }
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score -= (bin_residual as f64 / bin_capacity as f64) * 0.0; // baseline neutral
    score += open_pressure * (1.0 - fit_ratio) * 4.0;

    // Global state coupling: if mean residual is high, encourage using fuller bins.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05 * (1.0 + progress);

    // New-bin candidate handling: an empty bin is attractive only when fits are poor
    // or no good open bin exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        let open_cost = 30.0 - 15.0 * (1.0 - progress);
        score = item_size as f64 * 0.5 + open_cost;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else if fitting_bins_count == 1 {
            // Existing last-chance bin is usually better than a new bin.
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize wasted residual, normalized
    let mut score = post / cap;

    // Smooth non-linear coupling: waste penalty grows super-linearly with progress
    // (later in the stream, dead space matters more)
    let waste_term = (post / cap).powi(2) * (0.5 + progress);
    score += waste_term;

    // Reward tight fits: perfect-fit bonus decaying smoothly with residual
    let tightness = 1.0 - (post / cap).powf(1.5);
    score -= 0.6 * tightness * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 0.5 * (1.0 - slack).max(0.0);
        } else {
            // next item won't fit: penalize leaving a large unusable remainder
            score += 0.3 * (post / cap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Many open bins: encourage consolidation; few open bins: opening is cheaper
    let open_norm = open_bins_count as f64;
    score += 0.05 * (post / cap) * (open_norm / (1.0 + open_norm));

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), smooth quadratic coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.1 * dev * dev * (0.5 + 0.5 * progress);

    // Mild bias against opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 0.15 + 0.35 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in a "dead zone"
    // (small unusable slivers) are penalized; useful leftovers are rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 45.0; // perfect fit is best
    } else if pr < 10 {
        // tiny sliver: likely dead space unless it equals a small item class
        score += 30.0;
    } else if pr <= 25 {
        score -= 12.0; // sweet spot: fits small items
    } else if pr <= 50 {
        score -= 6.0;
    }

    // Modulo-10 class of post_residual: leftovers that are multiples of common
    // item sizes (10,20,25,50) are more reusable.
    let reusable = pr % 10 == 0 || pr % 25 == 0 || pr == 50;
    if reusable && pr > 0 {
        score -= 8.0;
    }

    // Integer-division threshold: leftover divided by typical small item (10)
    // indicates how many small items could still fit.
    let small_slots = pr / 10;
    score -= 1.5 * small_slots as f64;

    // Lookahead: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 14.0;
        // extra reward if next item exactly consumes leftover class
        if next_item_size == pr {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > pr && pr > 0 {
        // next item won't fit here: leftover likely becomes waste
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when current bin fit is bad.
    if bin_residual == bin_capacity {
        // penalize opening new bins generally, more when many bins open
        score += 60.0 + 2.0 * open_bins_count as f64;
        // but if the current item is large and would leave a bad residual in
        // any existing bin, opening fresh is relatively better
        if item_size > 50 {
            score -= 30.0;
        }
    }

    // Progress scaling: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight tie-break toward tighter (lower-residual) bins via mean residual.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements where the next item also fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post residual cannot fit the lookahead item but is large-ish.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: many open bins -> favor filling existing bins over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(10.0);
    } else {
        // New-bin candidate: only attractive when mean residual is small and bins are tight.
        score += mean_residual * 0.5 + pressure * 0.4;
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact two-item fill
        } else if post_residual > next_item_size {
            // leftover after next item; penalize small unusable remainders
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 25.0; // creates dead space
            } else {
                score -= (after_next as f64).min(40.0) * 0.3;
            }
        } else {
            // next item cannot fit in this bin's leftover
            score += 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.5;

    // Penalize opening a new bin when open bins are underutilized.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + mean_residual * 0.4 - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is fine for large upcoming items
        }
    }

    // Mild penalty for very large post residual waste.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small to ever be useful (item min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 10.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting large residual.
            score += 0.05 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Global state: with many open bins, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large for future items); later, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor or
    // residuals are fragmented (high mean residual with many bins).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let incentive = 20.0 * poor_fits + 15.0 * fragmentation * progress;
        // Base new-bin cost so it's not chosen for trivially good fits.
        score = 35.0 - incentive + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize post residual (tight fits preferred)
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, leave flexible space; late, prioritize tight packing harder.
    let coupling = post * (1.0 + 2.0 * progress * progress) / cap;
    score += 30.0 * coupling;

    // Penalize dead space that no plausible next item can use (smooth interaction
    // between post_residual and lookahead size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post).max(0.0);
        score += 10.0 * (gap / cap) * (1.0 + progress);
        // Reward bins that can also fit the next item (smooth quadratic bonus)
        let fits_next = (post - nxt).max(0.0);
        score -= 8.0 * (fits_next / cap) * (1.0 - 0.5 * progress);
    } else {
        // Last item: pure tightness
        score -= 5.0 * (post / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Slight penalty when this bin is far above mean residual (keep bins balanced,
    // smooth in mean_residual)
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral-ish score; becomes attractive only when all open
    // bins would waste a lot (large post residual relative to capacity).
    if bin_residual == bin_capacity {
        score = post + 0.5 * cap * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: rewards residuals that fall into
    // "usable" classes (multiples of common small item sizes), penalizes
    // awkward dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_frac = 1.0 - (post_residual as f64) / cap;

    // Reward high fill fraction (tight packing) non-linearly.
    score -= 30.0 * fill_frac * fill_frac;

    // Harmonic class bonus: post_residual divisible by small sizes (10, 20, 25, 50)
    // leaves room for future items of those classes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    } else {
        // Perfect fit: strongest reward.
        score -= 40.0;
    }

    // Penalize residuals in dead zones: too small to hold the minimum item (1..100
    // interface, but small items are common); treat < 10 as near-dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly prefer this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // Next item fits: prefer post_residual close to next_item_size.
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here: mild penalty scaled by how much it overflows.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented or the
    // current fit is poor. Compare against mean residual.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the pooled residual of existing bins.
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // Penalize new bins early in the stream; relax later when fragmentation grows.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 25.0 * (1.0 - progress) - 18.0 * fragmentation;
        // Big items relative to capacity favor a fresh bin.
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Mild penalty for spreading across many open bins when this bin is already loose.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    // Small noise-free tie-breaker via integer division thresholds on post_residual.
    let class = post_residual / 10;
    score += class as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < item_size.min(20) as f64 {
        // gap too small for typical future items
        score += 25.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 15.0; // dead space blocks the known next item
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 2.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost grows with number of open bins.
        score += 40.0 + bin_pressure;
        // If this is the last chance, opening a bin is acceptable.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    } else {
        // Existing bin: reward being a scarce fitting option (avoid wasting last chance).
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Slight preference for bins below mean residual (consolidate loose space).
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // dead space relative to next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize tight-but-wasteful fits (small post_residual that isn't 0)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current bin fits are poor
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 60.0;
        // open it if existing bins would leave lots of dead space
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 >= 0 {
            // a fresh bin fits both current and next item nicely
            score -= 40.0;
        }
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early in stream, be slightly more willing to open bins (spread risk)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness term (non-linear: heavily reward very small leftover)
    let pr = post_residual as f64;
    score -= 60.0 * (-pr / 20.0).exp();

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: leftover too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chained packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 45.0;
            // extra reward for near-exact chain fit
            let chain_slack = post_residual - next_item_size;
            score -= 30.0 * (-chain_slack as f64 / 15.0).exp();
        } else {
            // penalize if leftover is just barely too small for next item
            let gap = next_item_size - post_residual;
            if gap <= 15 {
                score += gap as f64 * 1.5;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0; // base cost of opening a new bin
        // if mean residual across open bins is large (lots of slack), opening new bin is wasteful
        score += 0.8 * mean_residual;
        // late in stream, avoid opening new bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
        // many open bins already: discourage spreading
        score += 2.0 * open_bins_count as f64;
        // large item with no good home: allow new bin more readily
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 90.0;
        }
    } else {
        // prefer bins whose residual is close to item size (snug fit)
        let snug = (bin_residual - item_size) as f64;
        score += 0.3 * (snug - mean_residual).abs();
    }

    // Mild preference for fuller bins overall
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: waste after placement, normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling: waste penalized more as stream progresses
    let coupling = pr / cap * (0.5 + 1.5 * progress * progress);
    score += 0.8 * coupling;

    // Tight-fit reward: smooth quadratic in fill fraction
    let fill = 1.0 - pr / cap;
    score -= 0.6 * fill * fill;

    // Lookahead: if next item fits into post_residual, reward; else penalize
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            score -= 0.5 * (1.0 - slack / cap) * (1.0 - progress);
        } else {
            let miss = (ni - pr) / cap;
            score += 0.4 * miss * miss;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 + 0.8 * progress;
    }

    // Dead-space penalty: tiny residuals are hard to reuse; smooth sigmoid-ish term
    if pr > 0.0 {
        let tiny = (cap * 0.15 - pr).max(0.0) / (cap * 0.15);
        score += 0.5 * tiny * tiny;
    }

    // Mild preference for fuller bins vs. mean residual (fragmentation control)
    score += 0.2 * ((pr / cap) - (mean_residual / cap)).abs();

    // New-bin candidate: neutral-ish, penalize opening bins when many fit
    if bin_residual == bin_capacity {
        score += 0.3 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit via tightness reward (subtracted), scaled non-linearly.
    let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * tight * tight;

    // Harmonic classes: penalize post_residuals that are "dead" — too small to
    // plausibly fit future items. Class items into bands via integer division.
    let class = post_residual / 10; // 0..=10 harmonic classes of residual
    match class {
        0 => score += 60.0,               // unusable sliver
        1 => score += 25.0,               // nearly dead
        2 => score += 10.0,
        3 | 4 => score += 2.0,            // sweet spot: fits mid items
        _ => {}
    }
    // Modulo-20 harmonic ripple: residuals just above a small-item threshold are fine,
    // just below one are wasteful.
    let m = post_residual % 20;
    if post_residual > 0 && m < 4 && class >= 3 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / 20.0).max(0.0);
            // penalize if next item leaves another dead sliver
            if (post_residual - next_item_size) < 5 {
                score += 8.0;
            }
        } else {
            // next item won't fit here: mildly penalize leaving large residual anyway
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        // Opening a new bin is cheap early / when few bins, expensive when many are open.
        score += 25.0 + 2.0 * crowded.ln().max(0.0);
        // But if the item is large and no tight fit exists elsewhere, new bin is good:
        // detect via mean residual mismatch.
        let need = item_size as f64;
        if mean_residual < need {
            score -= 45.0;
        }
        // Large items leave big residuals in fresh bins — fine for future items.
        if item_size >= 50 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (perfect fit reward).
        let diff = (bin_residual as f64 - item_size as f64);
        score -= 10.0 / (1.0 + diff);
    }

    // Stream progression: later in the stream, waste is costlier — tighten up.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be useful
    // again are heavily penalized (dead space threshold around min item size ~ 10,
    // scaled slightly with stream position).
    let dead_threshold = 12.0 + 4.0 * (step_index as f64 / total_items.max(1) as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward: exact fill leaves no waste at all.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Penalize leaving a gap that neither fits the next item (wasted lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap usable by the lookahead item: reward.
        score -= 8.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins; more open bins
    // means reusing an existing bin becomes more attractive.
    score -= (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Deviation from mean residual: bins with residual close to item_size are
    // ideal; being far above mean residual suggests this bin is a poor match.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize it by default, more so when other bins fit the item.
        let base_penalty = 30.0 + 5.0 * (open_bins_count as f64);
        // If the item is large relative to capacity, opening a fresh bin is
        // somewhat more acceptable (less fragmentation risk).
        let large_item_relief = (item_size as f64 / bin_capacity as f64) * 20.0;
        // If next item is large and current post_residual would be tiny, fresh
        // bin gains a bit of appeal.
        let lookahead_relief = if next_item_size > 0 && post_residual < next_item_size {
            10.0
        } else {
            0.0
        };
        score += base_penalty - large_item_relief - lookahead_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the NEXT item is the ideal outcome: strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Residual left over after the next item could fit: mild penalty
            // scaled by how much usable space remains wasted.
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Next item does NOT fit in the leftover: dead-space penalty,
            // quadratic in the shortfall to discourage stranding large gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap * gap.sqrt() + 0.1 * gap;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.2 * post_residual as f64;
    }

    // Reward bins that are tighter than the current mean residual (good packing),
    // penalize bins looser than the mean.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when a fresh empty bin
    // is competitive: keep pressure toward consolidation.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, allow opening new bins slightly more freely (keeps
    // flexibility for future large items).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Small tie-break noise-free nudge toward larger residuals (keeps big gaps
    // available for big future items) when post_residual is large.
    if post_residual > 50 {
        score += 0.05 * (post_residual - 50) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty scaled down.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening a new bin, but less when
    // the current item leaves a large awkward residual or lookahead is big.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 25.0;
        // If next item is large and this item is small, new bin may be useful.
        if next_item_size > 0 {
            let combined = item_size + next_item_size;
            if combined > bin_capacity {
                // Chain likely: placing item alone in a fresh bin may be good
                new_bin_penalty -= 10.0;
            }
            // If item alone wastes a lot of space, discourage new bin less when
            // post_residual would be small anyway (handled by base score).
        }
        // Late in the stream, avoid spreading items across bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Favor bins whose residual deviates from the mean in a useful way:
    // a bin with residual slightly above item_size is a near-perfect fit.
    let fit_slack = bin_residual as f64 - item_size as f64;
    score += 0.15 * fit_slack;

    // Coupling with mean residual: prefer bins tighter than average.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap <= 10 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * coupling;

    // Reward exact-ish fits superlinearly
    if post_residual <= 5 {
        score -= 12.0 + 2.0 * (6 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty relative to mean residual: avoid leaving this bin far above average waste
    score += 0.3 * (pr - mean_residual).abs();

    // Slight preference for filling existing bins over opening new ones late
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward tight fits: bins with small post residual get strong subtraction.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if frac <= 0.10 {
        score -= 40.0;
    } else if frac <= 0.20 {
        score -= 15.0;
    } else if frac <= 0.30 {
        score -= 4.0;
    } else if frac <= 0.50 {
        score += 8.0;
    } else {
        score += 20.0; // large dead space penalty
    }

    // Harmonic-class coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // exact chaining of harmonic classes
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / cap;
            // Favor bins whose residual class complements the next item's class
            score -= 10.0 * (1.0 - (pr - next_item_size as f64) / cap);
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 6.0; // divisible residual: future items tile nicely
            }
            let _ = nxt_frac;
        } else {
            // next item cannot use this residual: mild penalty proportional to wasted potential
            score += 5.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    // or the item is huge relative to typical residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_openness = mean_residual / cap;
        score += 45.0;              // base cost of a fresh bin
        score -= 35.0 * avg_openness; // more attractive when open bins are congested
        score -= 10.0 * progress;     // slightly more willing late in the stream
        if item_size >= 70 {
            score -= 15.0; // big items deserve fresh bins to avoid fragmentation
        }
        if fitting_bins_count > 0 {
            score += 20.0; // don't open new bin when alternatives exist
        }
    }

    // Mild tie-breaking toward fuller bins across the fleet.
    score -= 0.05 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (post_residual near zero is already low via base term).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 8.0; // chaining a good fit
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 2.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 10.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) + 10.0 * progress;
        score += new_bin_penalty;
        // But if this bin is a perfect fit for a large item, allow it.
        if item_size >= bin_capacity - 5 {
            score -= 25.0;
        }
    }

    // Slight preference for bins below mean residual (balancing load).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), slightly super-linear.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual,
    // penalize if post_residual is just barely too small for the next item (dead space).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as i64 - next_item_size as i64).abs() <= 4 {
            // Perfect chain: this bin will be exactly consumed by the next item.
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward proportional to how well it chains.
            score -= 6.0 * (next / (post_residual as f64 + 1.0));
        } else {
            // Next item won't fit: penalize more when post_residual is barely too small
            // (wasted sliver) relative to mean residual.
            let gap = next - post_residual as f64;
            if gap <= 8.0 {
                score += 8.0 + gap;
            }
            // Penalize leaving residuals below the minimum item size (unusable dead space).
            if post_residual < 10 && post_residual > 0 {
                score += 12.0;
            }
        }
    } else {
        // Last item: only tightness matters.
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual below average are scarcer; using them
    // for a good fit is valuable. Penalize wasting a large-residual bin on a small item.
    if (bin_residual as f64) > mean_residual + 15.0 && post_residual > 20 {
        score += 5.0;
    } else if (bin_residual as f64) < mean_residual - 10.0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    // (large dead space) and the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let bad_fit = item_size < 40 && waste > 55.0;
        if bad_fit && next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0; // open a new bin instead of fragmenting an open one
        } else {
            score += 25.0; // default: strongly prefer existing bins
        }
    }

    // Late in the stream, consolidate: discourage spreading across many bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.7 && open_bins_count > 3 && post_residual > 30 {
            score += 3.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 18.0 * tightness;

    // Penalize dead space: post_residual too small to fit a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits in the post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item won't fit here; penalize leaving awkward gap.
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // More competition: mild scaling so spread-out bins lose.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Time horizon: early in stream, favor consolidating into existing bins less
    // (keep flexibility); late in stream, fill existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let open_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score -= 2.5 * open_pressure.min(20.0);

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is fine early or when the item is large relative to residual
        // of typical open bins, but costly when open bins already have good space.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut nb = 45.0;
        // Large items justify new bins.
        nb -= 35.0 * item_frac;
        // Early stream: new bins are cheap to open.
        nb -= 25.0 * (1.0 - progress);
        // If open bins are mostly full (low mean residual), new bin is more attractive.
        nb += 20.0 * (mean_residual / bin_capacity as f64);
        // If this bin is the last chance anyway, opening new bin loses its advantage.
        if fitting_bins_count == 1 {
            nb += 30.0;
        }
        score += nb.max(0.0);
    }

    // Prefer bins whose residual is close to item size (exact-fit shaping).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Smooth non-linear coupling: reward tight fits more aggressively as stream progresses.
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * cap * (0.6 + 0.8 * progress);

    // Penalize dead space relative to the mean residual across open bins.
    let dead = (post - mean_residual) / cap;
    score += dead * dead * cap * 2.0;

    // Smooth penalty for leaving residual that neither the next item nor typical items fit.
    let next_gap = if next_item_size > 0 {
        let d = post - next_item_size as f64;
        d * d / cap
    } else {
        0.0
    };
    score += next_gap * 1.5;

    // Last-chance bonus: strongly prefer using the only fitting bin (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= cap * (1.5 + progress);
    } else if fitting_bins_count > 1 {
        // Mild scarcity reward scaling inversely with number of fitting bins.
        score -= cap * 0.3 / (fitting_bins_count as f64);
    }

    // Encourage opening a new bin when the fit is poor and alternatives are plentiful.
    let poor_fit = post / cap;
    score += poor_fit * poor_fit * cap * (0.5 * (1.0 - progress)) * (open_bins_count as f64).ln().max(1.0);

    // Small bonus for perfect fills.
    if post == 0 {
        score -= cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets via modulo arithmetic.
    // Residuals that are multiples of small harmonics (5,10,20) are more reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is ideal
    } else if pr % 20 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: small unusable residuals are bad, especially if the
    // next item cannot fit into them.
    if next_item_size > 0 {
        if next_item_size > pr {
            // next item won't fit here; residual is likely dead space
            let dead = pr as f64;
            score += 8.0 * (dead / cap) * (dead / cap).sqrt() * 10.0;
        } else {
            // next item fits: reward keeping room for it, tighter is better
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // unless the fit is terrible (huge post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // new bins when fits into existing bins are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.65 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: opening a bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing potential with next item
        }
    }

    // Prefer filling bins that are already relatively full (low residual),
    // best-fit style, with a mild coupling to mean residual.
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Slight preference for bins whose residual class matches item size class
    // (both rounded to nearest 10).
    if (bin_residual / 10) == ((item_size + 9) / 10) {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the minimum plausible item footprint) are
    // treated as pure waste and heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, ideal
    } else if post_residual <= 10 {
        score += 40.0; // near-perfect fill, strongly favored
    } else if post_residual <= 20 {
        // awkward dead zone: too small for typical items later
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    }

    // Reward exact / tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty scaled by how unusable the gap is for the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as f64) > post_residual as f64 {
            // leftover gap cannot host the next item -> likely stranded space
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else {
            // gap can chain the next item: reward
            score -= 8.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // into existing bins over opening new ones.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a fresh bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless residual pressure is high
    // or the fit into existing bins is terrible.
    if bin_residual == bin_capacity {
        score += 60.0 + 3.0 * open_bins_count as f64;
        // allow opening a new bin late in the stream when mean residual is large
        score -= 0.2 * mean_residual;
    }

    // Mild preference for filling fuller bins (mean residual anchoring).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual relative to item size is better.
    let item_f = item_size as f64;
    let post_f = post_residual as f64;
    score -= 2.5 * (item_f / bin_capacity as f64) * (1.0 - post_f / bin_capacity as f64);

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let diff = (post_f - next_f).abs();
        if next_f <= post_f {
            // Next item fits in this bin's leftover: reward closeness to exact match.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: leftover likely becomes dead space,
            // penalize proportionally to how unusable it is.
            score += 0.4 * (post_f - next_f);
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual deviates favorably (smaller residual = tighter bin).
    score -= 0.15 * (mean_residual - post_f);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize new-bin candidates unless open bins would leave very poor fits.
    if bin_residual == bin_capacity {
        // A new bin is attractive only if the item is large and no tight option exists.
        score += 10.0 + 0.3 * item_f;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_f / bin_capacity as f64);

    // Late-stream bias: prefer tighter packing as the stream nears its end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100 range, use ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 3.0 * ((next_item_size as f64 - post_residual as f64) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins below mean residual (more full than average).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many bins are open or late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * progress;
    }

    // Fragmentation shaping: prefer residuals that are "nice" sizes (multiples of 10 or >= 50).
    if post_residual >= 50 {
        score -= 5.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, but with non-linear (quadratic/cubic) shaping:
    // moderate leftovers are mildly bad, tiny leftovers are great, large ones bad.
    let mut score = pr as f64;
    score += 30.0 * x * (1.0 - x) * (1.0 - 2.0 * x); // cubic tilt: favors very tight fits
    score -= 20.0 * x * x * (1.0 - progress);        // early stream: waste matters less
    score += 25.0 * x * x * progress;                // late stream: strongly punish waste

    // Exact fit reward (smooth spike near zero residual)
    if post_residual == 0 {
        score -= 40.0;
    } else if pr < 5.0 {
        score -= (5.0 - pr) * 4.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let tightness = 1.0 - (pr - n) / cap;
            score -= 15.0 * tightness * tightness;
        } else {
            score += 10.0 * ((n - pr) / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate adjustment: opening a bin is fine early, costly late;
    // also discouraged when several bins already fit the item.
    if bin_residual == bin_capacity {
        score += 18.0 * progress + 3.0 * (fitting_bins_count as f64);
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Dead-space penalty relative to mean residual: bins far below mean residual
    // (fragmented) get penalized for large leftovers.
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: capacity divided into
    // octave-like classes. Residuals in the lowest class (tiny scraps)
    // are nearly dead space -> penalize heavily.
    let class = |r: u32| -> u32 {
        let frac = (r as f64 / bin_capacity as f64 * 4.0) as u32; // 0..4 classes
        frac.min(4)
    };
    let post_class = class(post_residual);
    let pre_class = class(bin_residual);

    // Reward keeping residual inside a "usable" class (> 25% of capacity):
    // tiny post_residuals waste the bin.
    match post_class {
        0 => score += 45.0,                 // dead space (<25% left)
        1 => score += 12.0,                 // marginal
        2 => score -= 6.0,                  // decent
        _ => score -= 14.0,                 // roomy bin preserved
    }

    // Exact / near-exact fills are golden.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 60.0;
    }

    // Modulo arithmetic: item_size that divides capacity cleanly
    // (100 % item_size == 0) leaves tiles that future items of the
    // same class can reuse.
    if bin_capacity % item_size == 0 && post_residual == bin_capacity - item_size {
        score -= 8.0;
    }

    // Integer-division threshold coupling with lookahead item:
    // if the next item fits the post residual exactly, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 55.0;
        } else if gap <= 5 {
            score -= 25.0;
        } else {
            score -= gap as f64 * 0.3;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // current placements are poor. Give it a mild baseline cost that
    // scales with how many bins are already open.
    if bin_residual == bin_capacity {
        score = 20.0 + 2.0 * (open_bins_count as f64).sqrt() + mean_residual * 0.15;
        // allow new bin if the stream is early and mean residual is small
        if (step_index as f64) / (total_items.max(1) as f64) < 0.1 {
            score -= 10.0;
        }
    }

    // Tie-break: prefer tighter bins (smaller pre-residual) mildly.
    score += bin_residual as f64 * 0.05;

    // Mean-residual coupling: when open bins are generally roomy,
    // discourage wasting space here.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Items are >= 1; treat gaps below a "usable threshold" as dead space.
        // A gap is usable if it can hold at least a mid-small item; scale by stream position.
        let min_item = 1.0f64;
        let usable_floor = (min_item * 10.0).min(bin_capacity as f64 * 0.1);
        if pr < usable_floor {
            // Dead space: quadratic penalty, stronger late in the stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (usable_floor - pr) * (usable_floor - pr) * (2.0 + 3.0 * progress);
        } else {
            // Larger leftover space is mildly useful; reward proportionally.
            score -= (pr / bin_capacity as f64) * 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin_residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bins pressure: discourage spreading across many bins when few fitting bins exist.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    // (below-mean residual = tighter bin, prefer it).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits in the post_residual, bonus; if it barely misses, penalty.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        } else if post_residual > 0 && (next_item_size as f64) - post_residual as f64 <= 5.0 {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual < bin_capacity as f64 * 0.25) || (fitting_bins_count == 0);
        if crowded {
            score -= 30.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
            // bonus when next item leaves small dead space too
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here: penalize small post_residuals (dead space)
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving tiny unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Favor reusing bins (many open bins) over opening new ones early in stream
    if open_bins_count > 0 && bin_residual == bin_capacity {
        // new-bin candidate: penalize unless item is large and fits poorly elsewhere
        score += 100.0;
        if item_size >= 70 {
            score -= 40.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is huge relative to mean residual
    // or few bins can fit it.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64 / mean_residual.max(1.0)).min(2.0);
        score += 35.0 - 20.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        score += 0.02 * open_bins_count as f64;
    }

    // Time horizon: early on, be frugal with new bins; late, prefer tight packing.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 3.0 * (open_bins_count as f64).sqrt();

    // Prefer bins with residual close to item (minimal waste).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * slack;

    // Mild preference for bins below mean residual (balance).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer spreading load (large post_residual is fine);
    // later, prefer tight packing (small post_residual heavily rewarded).
    let poly = post / cap;
    let coupling = poly * poly * (1.0 - progress) - poly * progress;
    score += 40.0 * coupling;

    // Tight-fit reward: squared fill ratio, scaled by progress.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (0.5 + progress);

    // Penalize dead space that nothing realistic can use.
    if post > 0.0 {
        let usable = post >= next_item_size as f64;
        if next_item_size > 0 && !usable {
            score += 12.0 * (1.0 - progress);
        }
        // Small residuals below half of mean item size are near-waste.
        if post < 0.5 * (cap - mean_residual.max(0.0)).max(1.0) {
            score += 6.0 * progress;
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening a new bin when open bins exist and fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    // Lookahead synergy: reward leaving exactly the space the next item needs.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small unusable" classes get rewarded (tight packing).
    let cap_f = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward small post_residual (good fit) with non-linear bonus.
    if post_residual <= eighth {
        score -= 12.0;
    } else if post_residual <= quarter {
        score -= 5.0;
    } else {
        // Penalize large leftover, modulate by harmonic class.
        let class = post_residual / quarter.max(1);
        score += 3.0 * class as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly
    // into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 18.0;
        } else {
            let gap = post_residual - next_item_size;
            if gap <= eighth {
                score -= 7.0;
            }
        }
    } else if next_item_size > 0 {
        // Next item cannot use leftover: penalize dead space more.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / cap_f).min(1.0);
        let pressure = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(2.0)
        } else {
            2.0
        };
        // Base cost of opening a new bin.
        score = cap_f * 0.35 + tightness * 5.0;
        // Open new bin if no open bin can fit or fit is very poor.
        if fitting_bins_count == 0 || pressure > 1.4 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference to balance residuals over time.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual).abs() * 0.05 * (1.0 - progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Define "unusable" relative to the smallest possible item (1..100 interface,
    // but treat gaps below a conservative threshold as dead space).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is well matched to the item (tight fit),
    // penalize loose fits that leave large but awkward residuals.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.8 {
        score -= 12.0 * (fit_ratio - 0.8) * 5.0;
    } else if fit_ratio < 0.4 {
        score += 8.0 * (0.4 - fit_ratio) * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open-bin pressure is low. Penalize opening new bins when a decent
    // fit exists and open count is already high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin costs ~one bin; make it unattractive unless
        // post_residual in a new bin (capacity - item) is large and useful.
        score += 55.0 - 0.35 * open_bins_count as f64 - 20.0 * progress;
        // If next item is large, a fresh bin with room is more valuable.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 10.0;
        }
        // If next item cannot fit anywhere else well, new bin gains value.
        if next_item_size > post_residual && next_item_size > 0 {
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins (penalize choices that don't reduce fragmentation).
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if the mean residual is small (bins nearly full),
    // be extra frugal — penalize wasting any residual.
    if mean_residual < 25.0 && !is_new_bin {
        score += (25.0 - mean_residual) * 0.3;
    }

    // Lookahead: if the next item exactly fills the post_residual, big reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 20.0;
    }
    // If next item cannot fit in post_residual, mild penalty for creating
    // a stranded gap (unless gap is large enough to be generally useful).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

