    }
    // Actually prefer placing into bins with residual below mean (consolidate large holes):
    score -= 3.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64 * 10.0;

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 {
