    // Lookahead coupling: if next item could use the post residual, reward leaving that space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 10.0 * (nr / 100.0);
        } else if (post_residual as f64) > 0.0 {
            // post residual too small for next item: penalize wasted space slightly more.
            score += 6.0 * (1.0 - post_residual as f64 / nr);
