    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into fuller bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    score += 4.0 * spread_pressure * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins that are notably fuller than average.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 15.0 * dev;

    // Mild bias against opening new bins as stream progresses.
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * progress;
        // But allow new bin if current open bins have terrible fit (large item, small residuals).
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
