    // Penalize dead space quadratically, scaled by mean residual imbalance.
    let dead = post_residual as f64 / cap;
    score += 8.0 * dead * dead * (1.0 + (mean_residual / cap).abs());

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
