    // New-bin candidate: penalize mildly early, allow late when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to the item (smooth coupling).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

