    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: harmonic classes mod 10
    // Residuals that are multiples of 10 are "harmonic" — likely to host future items (sizes 10..80)
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 8.0;
    } else {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Coupling with next_item_size: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let after = post_residual - next_item_size;
            // reward smooth chaining, penalize creating another sliver
            if after == 0 {
                score -= 30.0;
            } else if after < 10 {
                score += 10.0;
            } else {
                score -= (after / 10) as f64 * 2.0;
            }
        } else {
            // next item won't fit here: this bin becomes dead after placement
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad,
    // but relax when many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 20.0;
        // If open bins are fragmented (high mean residual but none fit well), opening is OK
        new_bin_score -= (mean_residual / cap) * 10.0;
        // Late in stream, slightly prefer consolidating
        new_bin_score += progress * 5.0;
        // Many open bins: encourage opening fresh ones to keep options
        new_bin_score -= (open_bins_count.min(20) as f64) * 0.5;
        score = score.min(new_bin_score) + if bin_residual == bin_capacity { new_bin_score * 0.0 } else { 0.0 };
        score = new_bin_score;
    }

    // Global waste pressure: bins far below mean residual usage get slight penalty
    score += ((pr - mean_residual) / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
