    // Open-bin pressure: penalize creating more bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the mean (balance residuals).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: make it unattractive unless it is a genuinely better option.
    if bin_residual == bin_capacity {
        score += 35.0 + 1.5 * open_bins_count as f64;
        // Allow new bin early in stream to build good structure.
        score -= 30.0 * (1.0 - progress);
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact 2-item match bonus
            if post_residual == next_item_size {
                score -= 300.0;
            } else {
                // tighter leftover after hosting next item is better
                score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            }
        } else {
            // penalize dead space that next item cannot use
            score += 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins with residual below mean (tight bins first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let good_fit = post_residual as f64 <= mean_residual * 0.5;
        score += if good_fit { 0.0 } else { 400.0 };
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 {
        let waste = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.6 * waste;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 1.5 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 6.0 * (open_bins_count as f64).sqrt() };
        let residual_pull = if open_bins_count > 0 { (mean_residual - item_size as f64).abs() } else { 0.0 };
        score += fit_penalty - 0.05 * progress * (bin_capacity as f64) + 0.3 * residual_pull;
    }

    // Mild penalty for spreading across many bins when mean residual is already large.
    score += 0.15 * (mean_residual / (bin_capacity as f64)) * (open_bins_count as f64);

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.4 * ((bin_residual as f64 - item_size as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 12.0
                 - pr_norm * pr_norm * pr_norm * progress * 8.0;
    score += coupling * cap;

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tight = (1.0 - pr_norm).powi(4);
    score -= tight * 10.0 * (0.5 + progress);

    // Penalize post_residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += gap * gap * 25.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        // Reward reserving space for the lookahead item
        score -= 4.0 + progress * 4.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins,
    // relaxing late in the stream when fragmentation matters
    if bin_residual == bin_capacity {
        let relax = 1.0 - progress;
        score += 8.0 * relax + 2.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below mean (more filled)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 6.0 + dev * dev * 10.0;

    // Slight penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity fraction slot we land in.
    let quarter = bin_capacity / 4; // 25 units
    let eighth = bin_capacity / 8;  // ~12 units

    // Penalize residuals that are "almost full but unusable" — dead space
    // in (0, eighth) is the worst outcome for future packing.
    if post_residual > 0 && post_residual < eighth {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 30.0;
    } else {
        // Reward residuals that land on harmonic grid points (divisible by 25 or 10),
        // since future items of common sizes can re-fill them.
        if post_residual % quarter == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement is excellent (chained perfect fill).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves another gap; mild reward scaled by tightness.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers.
            if post_residual >= next_item_size + eighth {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Give the empty bin a baseline cost that grows with how
    // many bins are already open (discourage bin proliferation), but shrink it
    // when the current item is large relative to capacity (big items fit well
    // in fresh bins anyway).
    if bin_residual == bin_capacity {
        let open_penalty = 6.0 * (open_bins_count as f64).sqrt();
        let size_relief = 10.0 * (item_size as f64 / bin_capacity as f64);
        score = bin_capacity as f64 - size_relief + open_penalty;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild pressure to prefer bins with lower residual relative to the mean
    // (best-fit style), keeping scores comparable across bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual is "dead" if it's too small for even the smallest plausible item (1..100 range,
    // assume min item ~1, but statistically small items are rare; treat < 10 as near-dead).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // near-dead sliver: bad fragmentation
        } else {
            // Usable gap: reward it, more so if it can host the lookahead item.
            let gap_util = post_residual as f64 / bin_capacity as f64;
            score -= 15.0 * gap_util;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 10.0; // gap chains with next item: excellent
            } else if next_item_size > 0 {
                score += 5.0; // next item won't fit here
            }
        }
    } else {
        // Perfect fill: strongly reward closing the bin.
        score -= 50.0;
    }

    // Tightness reward: small post_residual relative to item size is good.
    score += 0.5 * (item_size as f64 / (post_residual as f64 + 1.0));

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage scattering across many bins when residuals are plentiful.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing residuals are poor fits.
        let fit_deficit = (item_size as f64 - mean_residual).max(0.0);
        score += 25.0 - 2.0 * fit_deficit - 0.5 * open_bins_count as f64;
    } else {
        score += 0.1 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open bins (build good structure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space nonlinearly (waste fragility).
        let pr = post_residual as f64;
        score += (bin_capacity as f64 / pr).ln() * 30.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // heavily reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        if lookahead_waste == 0 {
            score -= 800.0;
        } else {
            score -= 200.0 - (lookahead_waste as f64).min(200.0);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize proportionally to the gap.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 120.0 + item_size as f64 * 0.5;
    }

    // Late in the stream, tighten packing (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight * (item_size as f64);

    // Penalize dead space that cannot hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 0.2 * item_size as f64;
    } else if fitting_bins_count > 1 {
        // Prefer bins among many candidates that are already fairly full.
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open; relax slightly when residuals are large/wasteful.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let waste = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 + 5.0 * (1.0 - progress) + 0.5 * open_bins_count as f64 - 8.0 * waste;
    }

    // Mild preference for bins below mean residual (consolidate emptier space usage).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) * (1.0 - progress);
    score -= 20.0 * poly;
    // Penalize small unusable residuals, more so late in the stream
    let small = (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 8.0 * small * progress;
    // Reward tight fits especially when this is the last fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (1.0 - progress);
    }
    // Lookahead: penalize wasting residual when next item could use it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 5.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (1.0 - progress) * (1.0 - norm_pr);
        }
    }
    // Mild bias toward keeping mean residual balanced
    score += 0.5 * (mean_residual - pr) / cap;
    // New-bin candidate penalty: prefer existing bins early, allow later
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are perfect
    // "small-item friendly" classes (multiples of 10, 25, 50) are less
    // wasteful than awkward ones. Penalize awkward classes.
    let class10 = (post_residual % 10) as f64;
    let class25 = (post_residual % 25) as f64;
    if post_residual > 0 {
        score += 0.6 * class10 + 0.4 * class25;
    }

    // Integer-division thresholds: a post-residual in the "dead zone"
    // (1..10) is nearly unusable for typical items -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit: residual that exactly matches a plausible next item class.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // lookahead item cannot fit here -> dead space likely
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large (would leave a good class in an old bin) or no bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate into few bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Favor bins below mean residual (keeps residuals balanced).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 interface).
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // tiny dead space: strong penalty, quadratic in tightness
        score += (11.0 - post_residual as f64) * (11.0 - post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Penalize leaving a gap that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor tighter bins
    // (small residual) when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild preference for bins tighter than the mean residual (good fits).
    score += (post_residual as f64 - mean_residual) * 0.3 * (0.5 + progress);

    // New-bin candidate handling: make a fresh bin mildly unattractive by default,
    // but attractive when no open bin fits well (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        let base = 45.0 + pressure * 3.0;
        // If the only alternative would leave big dead space, allow opening.
        if fitting_bins_count == 0 {
            score = base - 100.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but relative to capacity.
    score = score * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Aggressive 2-step lookahead: strongly reward when next item fits perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_gap / bin_capacity as f64);
        } else {
            // Next item can't follow here: penalize proportional to overflow.
            let overflow = (next_item_size - post_residual) as f64;
            score += 10.0 * (overflow / bin_capacity as f64);
        }
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Compare against mean residual across open bins: placing in a bin
    // with residual far below mean wastes the "richer" bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score += 0.3 * (mean_residual - res_f);
    } else {
        score -= 0.15 * (res_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 { 0.0 } else { 0.0 };
        let _ = poor_fit;
        // Penalize new bin if item is small (wastes capacity), reward if large.
        score += 20.0 - 0.2 * item_size as f64;
        // More attractive late in the stream or when many bins already open.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for leaving many bins open (fragmentation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
        // Perfect chain: post residual equals next item exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // When many bins can fit, prefer the tightest (already via fit_ratio);
    // add mild pressure proportional to open bins to consolidate.
    score += 0.6 * open_bins_count as f64;

    // Global residual balance: penalize bins far above mean residual
    // (keeps residuals homogeneous, easier future packing).
    score += 0.25 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in stream, more willing to open new bins
    // (fresh empty bin gets a discount later as stream matures).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty that shrinks with progress.
        score += 35.0 * (1.0 - 0.7 * progress);
        // If current bin would leave big awkward residual, new bin is fine.
        if post_residual > 0 && post_residual < 15 {
            score -= 20.0;
        }
    }

    // Slight preference for bins with larger residual when fit is loose.
    score += 0.05 * bin_residual as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 12.0 * poly;

    // Penalize mid-range residuals (dead space) smoothly
    score += 8.0 * (2.0 * x - 1.0) * (2.0 * x - 1.0) * (0.5 + 0.5 * t);

    // Reward tight fits more strongly later in the stream
    let tight = 1.0 - x;
    score -= 6.0 * tight * tight * (0.3 + 0.7 * t);

    // Lookahead coupling: if next item fits in post-residual, reward smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit = (x - nx).max(0.0);
        score -= 5.0 * (fit * (1.0 - (x - nx).abs())) * (1.0 - t * 0.5);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - 0.5 * t);
    }

    // Prefer bins below mean residual mildly (balance load)
    score += 0.05 * (pr - mean_residual) * (1.0 - t);

    // New-bin candidate: penalize opening a bin unless residuals are low
    if bin_residual == bin_capacity {
        score += 15.0 * (mean_residual / cap).max(0.0) * (0.5 + 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
