pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Items are 1..=100, so any residual is technically usable, but tiny residuals relative
    // to capacity are hard to fill. Penalize small post_residual sharply (non-linearly).
    let pr = post_residual as f64;
    if post_residual > 0 {
        let usable_frac = pr / bin_capacity as f64;
        // Dead-space penalty: quadratic surge for residuals below ~20% of capacity.
        if usable_frac < 0.20 {
            score += (0.20 - usable_frac) * (0.20 - usable_frac) * 400.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; leftover becomes dead space unless tiny.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new bins (new-bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 25.0 + open_bins_count as f64 * 6.0 + progress * 20.0;
        // But if existing fits are all terrible (this item would leave a bad gap),
        // opening a new bin is fine: soften the penalty when item is large.
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward for keeping bin count low.
        score -= 3.0;
    }

    // Prefer bins whose residual is already below mean (compact tight bins),
    // spreading load away from loose bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.15;
    } else {
        score += (res_f - mean_residual) * 0.10;
    }

    // Tight-fit bonus: reward when item fills most of the bin's residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills the leftover space.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += diff * 0.35;
        }
        // If next item can still fit after placement, mild bonus.
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 6.0;
        }
        // Penalize leaving a sliver smaller than the smallest plausible item.
        if post_residual < next_item_size && post_residual < 10 {
            score += 12.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Compare against mean residual: placing into a bin with large residual
    // relative to the mean keeps fragmentation concentrated.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New-bin candidate: only attractive if existing fits are poor.
        score += 8.0 + (mean_residual * 0.1);
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0; // room for a 2-step chain in a fresh bin
        }
    }

    // Prefer filling bins tightly overall.
    score += (item_size as f64 / bin_capacity as f64) * 3.0;

    // Mild progression term: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let mut penalty = 20.0;
        if fitting_bins_count > 0 {
            penalty += 15.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
        // Early in the stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty *= 0.5 + progress;
        // Many open bins with high mean residual: discourage new bins.
        if mean_residual > item_size as f64 {
            penalty += 8.0;
        }
        score += penalty;
    }

    // Mild penalty for creating residuals that are awkward (too small for typical items but not tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // dead space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Favor bins whose residual is close to the mean (keeps spread balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for fewer open bins when stream is late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual penalized more as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: reward leaving space for the next item, penalize dead space otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) as f64;
            score -= 15.0 * (1.0 - gap / cap) * (0.5 + progress);
        } else {
            score += 10.0 + 20.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize scattering across many open bins relative to mean residual
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual - pr).abs() / cap;

    // Mild penalty for new bins late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes (multiples of 10)
    // are highly reusable; penalize residues in "dead" classes.
    let post_class = post_residual % 10;
    let dead_penalty = match post_class {
        0 => -12.0,                       // perfect harmonic slot
        1 | 9 => 6.0,
        2 | 8 => 4.0,
        3 | 7 => 2.0,
        4 | 6 => 1.0,
        _ => 0.0,                         // class 5: half-capacity harmonic
    };
    score += dead_penalty;

    // Exact fill: extremely rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post residual that is unusable by typical items: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot follow here; mild penalty proportional to overshoot
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_residual - item_size).min(40) as f64 * 0.2;
    }

    // New-bin candidate: prefer keeping residual capacity aggregated in open
    // bins when the mean residual comfortably covers the item.
    if bin_residual == bin_capacity {
        if mean_residual >= item_size as f64 {
            score += 25.0 + mean_residual * 0.1;
        } else {
            score -= 8.0;
        }
        // early stream: opening bins is fine; late stream: consolidate
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Tightness reward: the tighter the fit, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Mild pressure to use bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Harmonic quarter-classes on post_residual relative to capacity.
    let quarter = (post_residual * 4) / bin_capacity.max(1);
    score -= match quarter {
        0 => 10.0,
        1 => 4.0,
        2 => 2.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual > 50 {
        score += 8.0; // large leftover is wasteful too
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize bins whose post-residual cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 15.0;
    } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        score -= 10.0;
    }

    // Last-chance bin reward: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 1.5;

    // Mild normalization by mean residual
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Exact match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward closeness of the
            // resulting gap (smaller leftover gap is better).
            let gap = post - nxt;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize wasted residual
            // proportionally to how much of it is dead space.
            score += 0.5 * post;
        }

        // Bonus if BOTH current and next item nearly fill the bin.
        if item_size as f64 + nxt + post_residual as f64 >= bin_capacity as f64
            && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than the mean residual is good (tight packing).
    let post = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (post - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // would leave a very poor fit in existing bins; otherwise discourage.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post > 0.0 && post < 10.0);
        if poor_fit {
            score -= 15.0;
        } else {
            score += 20.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Slight preference early in the stream to consolidate into fewer bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * (1.0 - progress) * (post as f64 / bin_capacity as f64);
    }

    // Penalize tiny unusable dead space hard (fragmentation).
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual by fit ratio.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score *= 1.0 - 0.35 * fit_ratio;

    // Penalize small dead space that nothing else can use (post_residual < 10 unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.4 * gap;
        // Bonus if next item fits exactly into the post residual.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // If next item cannot fit anywhere else small, avoid leaving awkward residuals.
        if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base on remaining stream and current congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        // Allow new bin late in stream if residuals are fragmented.
        if mean_residual < 15.0 && progress > 0.7 {
            score -= 25.0;
        }
    } else {
        // Prefer fuller bins slightly as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mild penalty proportional to deviation from mean residual (prefer balanced packing).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic waste penalty: dead space grows super-linearly in badness.
    score += 0.035 * pr * pr / cap;

    // Cubic coupling with stream progress: late in the stream, waste is costlier.
    let g = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream
    score += (0.02 + 0.05 * progress) * pr * pr * pr / (cap * cap);
    score -= 1.5 * g * pr; // mid-stream smoothing term

    // Reward tight fits relative to mean residual of open bins.
    if mean_residual > 0.0 {
        let tight = 1.0 - (pr / mean_residual).min(2.0);
        score -= 3.0 * tight * (item_size as f64 / cap);
    }

    // Lookahead: bonus if the next item fits the post-residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 2.5 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across many bins when residuals are already large.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Slight preference for filling existing bins over opening new ones late.
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-band classification (1..=100 capacity fractions)
    let item_class = (item_size + bin_capacity / 4 - 1) / (bin_capacity / 4); // 1..=4
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size + bin_capacity / 4 - 1) / (bin_capacity / 4) };

    // Exact-fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small to fit anything (below min item size 1)
    if post_residual > 0 {
        score += 30.0;
    }

    // Harmonic pairing: reward if post_residual can host the next item exactly or as a complementary class
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_fit = post_residual - next_item_size;
        score -= 40.0 + 0.5 * pair_fit as f64;
        // Complementary class bonus (classes summing to 5, e.g. big + small)
        if item_class + next_class == 5 {
            score -= 25.0;
        }
        // Modulo harmony: post_residual % next_item_size == 0 -> tiles perfectly
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize wasting the residual
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    let band = post_residual / (bin_capacity / 4);
    match band {
        0 => { if post_residual > 0 { score += 10.0; } }          // tiny sliver
        1 => { score += 5.0; }                                     // small leftover
        2 => { score -= 10.0; }                                    // half-ish space, useful
        _ => { score -= 15.0; }                                    // large residual, keep flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current fit is bad and stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if bad_fit && open_bins_count > 0 {
            score -= 20.0 + 30.0 * (1.0 - progress);
        } else {
            score += 50.0;
        }
    }

    // Prefer bins below mean residual (tighter bins first keeps big gaps open)
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Exact-match lookahead: favor bins whose residual after placement matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (20.0 * post_residual as f64) / (next_item_size as f64 + 5.0);
    }

    // Open-bin pressure: discourage opening new bins when decent fits exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 12.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 8.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins tighter than the fleet average (best-fit coupling).
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            // next item fits here: reward proportionally to how much slack remains after chaining
            let chained = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chained / bin_capacity as f64);
        } else {
            // next item cannot use the residual: penalize dead space, worse if residual small
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare residual against mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin; slight penalty so decent fits beat it,
        // but large residuals in existing bins will lose to it.
        score = post_residual as f64 + 5.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize placing a small item into a large residual (wasteful).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the post_residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-exact chaining of residuals.
            score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Penalize leaving a residual too small for the next item (dead space).
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Prefer consolidating into fewer bins when many are open with slack.
    if bin_residual != bin_capacity {
        score -= 3.0 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && item_size < 30;
        let many_open = open_bins_count as f64;
        if fitting_bins_count == 0 || (poor_fit && mean_residual < 15.0) {
            score -= 25.0;
        } else {
            score += 35.0 + 2.0 * many_open;
        }
    }

    // Time horizon: early on, be slightly conservative (favor future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear coupling: squared residual penalty grows with stream progress
    // (late in stream, dead space matters more since fewer chances to fill it).
    score += norm_post * norm_post * cap * (0.25 + 1.75 * progress);

    // Reward tight fits: subtract for small post_residual, smoothly.
    score -= (1.0 - norm_post).powi(3) * item_size as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= cap * (0.5 + 0.5 * progress);
    }

    // Penalize spreading across too many open bins relative to mean residual.
    score += (open_bins_count as f64).sqrt() * (norm_post - mean_residual / cap).abs() * 8.0;

    // Lookahead coupling: penalize if post_residual can't fit next item,
    // reward if it matches next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - ((post - nxt) / cap).abs()) * 10.0;
        } else {
            score += (nxt - post) * 0.3;
        }
    }

    // New-bin candidate: baseline ~ cap; add mild penalty so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += cap * (0.35 + 0.25 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and integer-division thresholds
    let pr = post_residual;
    let residue = pr % 10;
    let div10 = pr / 10;

    // Dead-space penalty: small post_residual is great (tight fit), moderate waste is bad.
    if pr == 0 {
        score -= 1000.0; // perfect fill
    } else if pr < 10 {
        score -= 60.0 - (pr as f64) * 4.0; // near-perfect fill
    } else {
        // Penalize unusable "dead zone": residual too small for the smallest plausible item
        if pr < 20 {
            score += 25.0;
        }
        // Harmonic residue penalty: residues far from 0 create awkward classes
        score += (10 - residue) as f64 * 0.8;
        // Integer-division threshold: reward residuals in "useful" bands (>=20)
        if div10 >= 2 {
            score -= (div10.min(8) as f64) * 2.0;
        }
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 40.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; residual becomes dead space until later
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin
        score = cap * 0.9 + 80.0;
        // If this is the only option (no fitting bins), make new bin the natural fallback
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // Many open bins: discourage opening more
        score += open_bins_count as f64 * 5.0;
    } else {
        // Prefer fuller bins: reward closeness of item to bin_residual (high fill ratio)
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill * 30.0;
        // Slight preference for bins below mean residual (tighter bins)
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Harmonic class of item_size: large items should go into tightest fits
    if item_size > 60 {
        score -= 15.0; // encourage big items into any fitting bin quickly
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Medium gaps are reusable for typical small items.
        score -= 8.0;
    }

    // Reward bins that are already fairly full (low residual before placement).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the only fitting option, soften the new-bin penalty.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: when open bins are loose, discourage spreading.
    score += 0.15 * mean_residual;

    // Late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space proportionally to how unusable it is
        let dead = post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64) > dead {
            score += dead * 1.5; // residual can't host next item: dead space
        } else {
            score -= dead * 0.8; // residual can host next item: reward tight coupling
        }
    }

    // 2-step lookahead: perfect match if post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    let res_f = bin_residual as f64;
    score += (res_f - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 40.0;

    // Slight preference for fewer open bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize mildly unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.8;

    // Penalize dead space: post_residual too small to ever fit typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 12.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and many bins are already open with low mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.6 * bin_capacity as f64;
        let crowded = open_bins_count as f64 > 2.0 && mean_residual < 15.0;
        if poor_fit && !crowded {
            score += 60.0;
        } else {
            score += 20.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.1 {
            score -= 10.0;
        }
    }

    // Prefer filling bins that deviate below the mean residual (consolidating waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild penalty for many open bins (encourage closing bins out).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: penalize wasted residual, with non-linear (quadratic/cubic) shaping.
    let mut score = x * (1.0 + 2.0 * x * (1.0 - x)) * cap;

    // Smooth polynomial coupling with stream progress: mid-stream, prefer tighter packing.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks at 0.5
    score += 6.0 * prog_term * x * x * cap;

    // Reward bins whose residual matches the next item (lookahead fit), smooth quadratic gap.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - gap * gap).max(0.0);
    }

    // Last-chance bin: strongly favor using it (smooth reward).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Slight penalty when many bins open and this bin is far from mean residual (dispersion).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (open_bins_count as f64).sqrt();

    // Discard the new-bin candidate mildly unless residual would be huge waste elsewhere.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the gap?
    // Class gaps into bands of 10 (typical small-item scale) and 25.
    let band10 = post_residual / 10;
    let band25 = post_residual / 25;
    // Penalize leftovers that are just above common item sizes (dead zones).
    // E.g. residual 11..19 is nearly useless (items >= 10 mostly, but 11 wastes 1-9).
    let dead10 = (post_residual % 10) as f64;
    score += 0.35 * dead10;

    // Reward exact/near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.15 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit here: slightly penalize leaving a mid-sized gap
        // that neither helps nor closes the bin.
        if post_residual >= 10 && post_residual < 30 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive.
    if bin_residual == bin_capacity {
        // Base penalty for consuming a fresh bin.
        score += 45.0;
        // But if the item is huge relative to capacity and would leave a big
        // awkward gap in any existing bin, opening fresh is fine: the score
        // is just post_residual + 45, which competes naturally.
        // If existing bins would be left with tiny unusable gaps, the low
        // post_residual of those bins already wins, so no extra tweak needed.
        // Small discount early in the stream when few bins are open.
        if open_bins_count <= 2 {
            score -= 10.0;
        }
    }

    // Mild preference for keeping bins balanced: prefer bins whose residual
    // is below the mean residual (more filled bins get priority).
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.05 * mean_gap;

    // Stream progression: later in the stream, tighten up — favor closing
    // bins out (small post_residual weighted more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (or next item) are wasted capacity -> heavy penalty.
    let min_size = 1u32;
    if post_residual < min_size {
        score += 50.0; // unreachable given item sizes >= 1, kept as guard
    } else if post_residual < 10 {
        // Small dead gap: the smaller the gap, the more "used" the bin is,
        // but a gap that cannot fit ANY future item is pure loss.
        score += 30.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward very tight fits (post_residual near zero) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead (k=2): if the next item fits exactly in the post residual,
    // strongly favor this bin; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64) / 100.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into
    // existing bins rather than spreading; also penalize when this bin's
    // residual is far above the mean (keeps a "big hole" bin available).
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate handling: an empty bin starts with a moderate
    // baseline; it should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to capacity, opening fresh is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a good residual portfolio; late, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste < 10).
    if post_residual < 10 {
        score -= 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead match: residual left after next item would be small.
        let chain_waste = post_residual as f64 - next_item_size as f64;
        if chain_waste < 10.0 {
            score -= 25.0 * (1.0 - chain_waste / 10.0);
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover; penalize dead space.
        score += 8.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or
    // the best existing fit would leave large waste.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && next_item_size <= bin_capacity {
            (bin_capacity - next_item_size) as f64
        } else {
            0.0
        };
        score += 30.0;                 // base cost of opening a new bin
        score -= 2.0 * fitting_bins_count as f64; // cheaper if many bins fit already
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 20.0;             // fresh bin pairs well with next item
        }
        let _ = waste_penalty;
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: favor tight fits (small post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Lookahead: penalize leaving a residual that cannot host the next item
    // (dead space), reward residuals that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // Dead space relative to next item; worse the larger the wasted chunk.
            score += (post_residual as f64) * 0.35
                * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
        // If next item fits almost exactly in the remaining space, strong reward.
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> discourage opening new bins,
    // encourage consolidation into existing ones.
    let open_pressure = (open_bins_count as f64) / ((total_items as f64).max(1.0)).sqrt();
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure and mean residual.
        score += 30.0 + 5.0 * open_pressure + 0.15 * mean_residual;
        // Early stream: opening bins is cheaper; late stream: consolidate.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 20.0 * progress;
    } else {
        // Existing bin with large residual relative to mean: slightly favored.
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Mild bonus for using bins that already have content (avoid bin sprawl).
    if bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: normalized post-residual with smooth quadratic dead-space penalty
    let norm_post = post / cap;
    let mut score = norm_post * (1.0 + 1.7 * norm_post) * cap;

    // Cubic coupling of post_residual with stream progress: tighten packing later
    score += 4.0 * norm_post.powi(3) * cap * (0.5 + progress);

    // Lookahead: reward residual that can host the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if post >= nx { 1.0 } else { 0.0 };
        // smooth ramp via overlap fraction
        let overlap = ((post / nx.max(1.0)).min(1.0)).powi(2);
        score -= 6.0 * fits_next * overlap * (nx / cap);
        score += 2.5 * (1.0 - fits_next) * (nx / cap) * norm_post;
    }

    // Last-chance bin: strongly reward using it (avoid opening a bin for one item)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - norm_post);
    }

    // New-bin candidate handling: penalize opening a bin when open bins fit well
    let is_new = bin_residual == bin_capacity && post < bin_residual as f64;
    if is_new {
        let crowd = open_bins_count as f64;
        let gap = mean_residual - item;
        // smooth penalty: worse when mean residual is comfortably above item size
        score += 3.0 + 4.0 * ((gap / cap).max(0.0)).sqrt() + 0.05 * crowd;
        // late in stream, opening fresh bins is less costly (future unknown)
        score -= 2.0 * progress;
    }

    // Mild reward for bins tighter than the mean residual (good fits first)
    score -= 1.5 * ((mean_residual - post) / cap).tanh();

    // Smooth progress-driven consolidation pressure
    score += (1.0 - progress) * 0.5 * norm_post * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by integer division bands.
    let band = post_residual / 10; // 0..=10 bands on capacity 100
    let harmonic_penalty: f64 = match band {
        0 => -12.0,                       // perfect fit: nearly zero waste
        1 => -6.0,                        // tiny residue, still attractive
        2 | 3 => 2.0,                     // residue 20..39: awkward mid-band
        4 | 5 => 0.0,                     // residue 40..59: could host next mid item
        6 | 7 => 3.0,                     // residue 60..79: large but often fragmented
        _ => -3.0,                        // residue 80..99: near-empty bin, keep flexible
    };
    score += harmonic_penalty;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward bins that can chain the next item (harmonic pairing).
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 8.0 - 0.08 * pair_waste;
        } else {
            // Penalize leaving residue that cannot host the lookahead item,
            // scaled by how badly it misses (modulo-style gap).
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap.min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        // Opening a new bin is good for large items or when open bins are crowded.
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score = 60.0 - 30.0 * tightness - 2.0 * crowd;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // next big item benefits from a fresh bin
        }
    }

    // Mild preference to fill bins below mean residual (balance avoidance).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early-stream exploration: keep more bins open early, consolidate later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item (1..100)
    // are wasted space; penalize them super-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Favor small post_residual that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: mild penalty to avoid stranding space
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading items; new-bin candidate gets penalized.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if few open bins or huge dead-space risk.
        score += 10.0 + pressure * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // pairing lookahead fits nicely in fresh bin
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 5.0;

    // Mean residual coupling: if mean residual is low, conserve remaining space
    // (penalize large post_residual more); if high, allow looser fits.
    score += post_residual as f64 * (mean_residual / bin_capacity as f64) * 0.5;

    // Early in stream, be slightly more willing to open bins for structure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item + next item fills bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead coupling: next item fits comfortably in the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.35 * (post_residual as f64 - next_item_size as f64).min(30.0);
    }
    // Penalize dead space that neither the next item nor typical items can use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.6 * (post_residual as f64);
    }
    // Very small unusable slivers are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Relative-to-mean coupling: prefer bins that stay near the mean residual.
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    // (i.e., item would leave a large awkward residual in an open bin).
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if post_residual > 0 && post_residual < 15 { 20.0 } else { 0.0 };
        score = 45.0 + poor_fit_penalty - (post_residual as f64 * 0.1);
    }

    // Slight preference early in stream to open bins, later to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly penalize when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size {
            score -= 0.3 * (next_item_size as f64);
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin unless the item is large (good use of fresh space).
    if bin_residual == bin_capacity {
        let load_ratio = (item_size as f64) / (bin_capacity as f64);
        // New bin is attractive only for large items, less so late in the stream
        // when many bins are already open (prefer filling them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 30.0 * load_ratio * load_ratio - 10.0 * progress - 0.5 * (open_bins_count as f64);
        score -= new_bin_bonus;
    }

    // Slight preference for bins below mean residual (keep residuals balanced),
    // but reward concentrating space into fewer usable chunks.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress:
    // late in the stream, large residuals are penalized more aggressively
    // (less future opportunity to fill them), early on they are tolerated.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress) * bin_capacity as f64;
    score += coupling * 0.5;

    // Smooth non-linear fit-quality term: reward tight fits (small post_residual)
    // with a saturating polynomial in item_size / bin_residual ratio.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * (1.0 - 0.5 * fit_ratio);

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly;
    // smooth polynomial reward decaying with mismatch.
    if next_item_size > 0 {
        let mismatch = (post_residual as f64 - next_item_size as f64).abs();
        let mm_norm = (mismatch / bin_capacity as f64).min(1.0);
        score -= 10.0 * (1.0 - mm_norm) * (1.0 - mm_norm) * (1.0 - mm_norm);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage scattering across many bins when mean residual is low:
    // if this bin's residual is far below the mean, it is a poor keeper.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev * dev * bin_capacity as f64 * 0.1;

    // New-bin candidate: penalize opening a new bin smoothly, more so late in stream
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 10.0 * progress + 3.0 * open_factor;
        if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward exact/near-exact fits.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else {
        // Dead-space class: post_residual that can never be filled by typical items
        // is penalized more than smooth residual.
        let pr = post_residual as f64;
        // modulo classes on capacity fractions
        let quarter = bin_capacity / 4;
        let eighth = bin_capacity / 8;
        if post_residual < 10 {
            score -= 100.0; // nearly perfect
        } else if post_residual <= eighth {
            score -= 30.0; // small dead zone, acceptable
        } else if post_residual <= quarter {
            score += 10.0; // awkward mid zone
        } else {
            score -= 20.0; // large residual still usable
        }

        // Lookahead coupling: reward if next item fits into post_residual exactly well.
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if next_item_size == post_residual {
                score -= 150.0; // chain exact fit
            } else if next_item_size < post_residual {
                let slack = (post_residual - next_item_size) as f64;
                // harmonic decay of reward with slack
                score -= 40.0 / (1.0 + slack / 10.0);
            } else {
                // next item won't fit here; penalize proportionally to overshoot
                score += 0.3 * (next_item_size - post_residual) as f64;
            }
        } else {
            // last item: only perfect fit matters
            score -= 0.5 * (cap - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many open bins with high mean residual: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.1 * consolidation;
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer tighter fits relative to item size.
    score += 0.5 * (item_size as f64 / cap);

    // New-bin candidate: keep it attractive only when residual would be large and item small.
    if bin_residual == bin_capacity {
        // opening new bin: base score = post_residual (= cap - item) already large;
        // discount slightly if current item is small and stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are highly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Prefer filling bins with low residual relative to mean (pack fullest first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If this is the only fitting bin, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // If next item is large, a fresh bin is more acceptable.
        score -= 0.1 * next_item_size as f64;
    } else {
        // Reward using existing bins, more so when few bins fit.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 20.0; // last chance: strongly prefer this bin
        }
        // If next item fits into the post-residual, bonus (keeps chain going).
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        // Penalize leaving a gap that the next item cannot use.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    }

    // Late in the stream, slightly favor consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 150.0 - slack.min(150.0); // tighter chain fit => larger bonus
        if slack <= 5.0 {
            score -= 100.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += (post_residual as f64).min(next_item_size as f64) * 0.8;
    }

    // Relative to mean residual: prefer bins that will end below average residual
    // (consolidating space), penalize bins already tight relative to mean.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 1.5;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual <= 10 {
            score -= 60.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it if this bin would otherwise be a bad host.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= item_size && item_size >= bin_capacity / 2 {
            score -= 100.0; // big item followed by big item: fresh bin is fine
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mild penalty for spreading across many bins.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (0.5 + 2.0 * progress * (1.0 - progress));
    score += 40.0 * poly;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 30.0 * progress);
    // penalize dead space relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);
    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }
    // lookahead: bonus if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 10.0 * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }
    // mild penalty for spreading across many open bins
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);
    // new-bin candidate: penalize slightly unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (mean_residual / cap) * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual in small harmonic classes).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class penalty: dead space buckets by modulo of post_residual.
    let pr = post_residual;
    if pr > 0 {
        let dead = match pr {
            0..=10 => 0.0,
            11..=20 => 5.0,
            21..=35 => 10.0,
            36..=50 => 15.0,
            _ => 20.0,
        };
        score += dead;
        // Dead space that cannot host the next item is worse.
        if next_item_size > 0 && pr < next_item_size {
            score += 8.0;
        } else if next_item_size > 0 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Prefer bins with residual far from mean (better packing diversity).
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for tighter bins early when many bins open.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more harshly than large residuals.
    // Residuals below 10 can never be filled by any future item (min size 1..100 unknown,
    // but small gaps are statistically hard to fill).
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward tight fits: the smaller post_residual relative to item_size, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Next item cannot use this dead space: penalize.
        score += 15.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 4.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 55.0 - tightness * 10.0;
        // With few open bins, opening new is less costly.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good filler.
    let residual_gap = mean_residual - bin_residual as f64;
    score += residual_gap * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact match between post_residual and next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residual that next item can't use at all
        if post_residual > 0 && (post_residual < next_item_size) {
            score += 3.0;
        }
    } else {
        // Last item: minimize leftover as usual
        score += 0.0;
    }

    // Reward residuals close to the mean residual (balanced packing)
    score -= 2.0 * (1.0 - ((post_residual as f64 - mean_residual).abs() / (bin_capacity as f64)));

    // Last-chance bin: heavy bonus to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly unless current fit is very poor
    if bin_residual == bin_capacity {
        let fit_waste = (bin_residual - item_size) as f64;
        score += 8.0 + 0.5 * fit_waste;
        if next_item_size > 0 && fit_waste >= next_item_size as f64 {
            score -= 6.0; // new bin can also host the next item
        }
    }

    // Slight preference to fill bins as stream progresses
    score += 2.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit preference: penalize large post residuals non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Tight fit reward (nearly perfect packing).
    if post_residual < 5 {
        score -= 25.0;
    } else if post_residual < 12 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // Extra reward for a chained perfect fit.
            if post_residual - next_item_size < 5 {
                score -= 10.0;
            }
        } else {
            // Dead space: next item can't use the leftover — penalize proportionally.
            score += (post_residual as f64 - next_item_size as f64) * 0.5;
        }
    }

    // Avoid fragmenting bins whose residual is a "useful" size for typical items
    // (i.e., residual >= next typical item) unless the fit is tight.
    if post_residual > 30 && post_residual < item_size as u32 {
        score += 8.0; // residual becomes unusable for similar items
    }

    // Prefer filling bins that are already relatively empty (consolidation),
    // scaled by the number of open bins — more bins open, more pressure to fill.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 2.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0;

    // Global mean residual coupling: if mean residual across open bins is high,
    // discourage opening new bins / favor placing into this bin.
    if bin_residual < bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // New-bin candidate: mildly penalize so we only open when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 1.5;
        // But if the item is large relative to capacity and mean residual is low,
        // opening a new bin is reasonable — reduce penalty.
        if item_size as f64 > bin_capacity as f64 * 0.6 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_ratio = post / cap;

    // Tight fits are strongly favored; non-linear reward for small post_residual
    score -= 30.0 * (1.0 - post_ratio) * (1.0 - post_ratio) * (1.0 + fit_ratio);

    // Penalize dead space: post_residual too small for any plausible item (below min size 1)
    if post_residual == 0 {
        score -= 25.0; // perfect fill is excellent
    } else {
        score += 8.0 * post_ratio * post_ratio * (1.0 + progress);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, but reduce penalty when open bins have large residuals
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 - 5.0 * open_pressure + 10.0 * progress;
        // If next item fits well into residual left by current item, opening is fine
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair <= cap {
                score -= 20.0;
            }
        }
    }

    // Lookahead: reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    let dev = post - mean_residual;
    score += 0.05 * dev * dev * 0.01 - 0.02 * dev;

    // Stream progress: late in stream, be greedier about tight packing
    score -= 10.0 * progress * (1.0 - post_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight-fit reward: post_residual small relative to capacity
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    if pr <= 10.0 {
        score -= 60.0;
    } else if pr <= 20.0 {
        score -= 30.0;
    }

    // Harmonic classes: partition post_residual into residue classes mod 10.
    // Residuals that are multiples of 10 (or near) are more reusable by typical items.
    let class = post_residual % 10;
    match class {
        0 => score -= 25.0,
        1 | 9 => score -= 8.0,
        2 | 8 => score += 4.0,
        3 | 7 => score += 8.0,
        4 | 6 => score += 12.0,
        _ => score += 15.0,
    }

    // Integer-division thresholds: dead space bands
    let band = post_residual / 10;
    if band >= 5 {
        // large residual: fine, bin stays flexible
        score -= 5.0;
    } else if band == 0 && post_residual > 0 {
        // tiny unusable sliver
        score += 10.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.3 * (next_item_size as f64);
        } else {
            // penalize leaving residual just below next item size (worst case)
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 5.0 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless stream is early
    // or current bin fit is bad (large post_residual vs mean_residual)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = pr / cap;
        let penalty = 120.0 - 40.0 * (1.0 - progress) - 60.0 * fit_quality;
        score += penalty.max(0.0);
    }

    // Prefer bins with residual below mean (consolidate waste)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild pressure to close out bins as stream progresses
    score += 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the item (good ratio fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Open-bins pressure: discourage spreading across many open bins,
    // but ease pressure when few bins can fit the item.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    let scarcity_bonus = if fitting_bins_count <= 1 { 30.0 } else if fitting_bins_count == 2 { 12.0 } else { 0.0 };
    score += pressure - scarcity_bonus;

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // New-bin candidate: opening a fresh bin is attractive when mean residual
    // across open bins is small (poor overall fit landscape) or bin is crowded.
    if bin_residual == bin_capacity {
        let new_bin_score = 18.0 + 0.3 * mean_residual - 2.0 * open_bins_count as f64;
        if new_bin_score < score {
            score = new_bin_score;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (mildly dampens late-game risk-taking).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Perfect 2-step lookahead match: post_residual == next_item_size ---
    if next_item_size > 0 && post_residual == next_item_size {
        // Ideal: this bin's leftover exactly fits the next item.
        score -= 60.0 + 25.0 * (1.0 - progress);
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leftover can still host the next item: reward closeness of the match.
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the next item: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // --- Tight fit reward: small post_residual is good in general ---
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * tightness * tightness;

    // --- Compare against mean residual across open bins ---
    // Bins with residual well above mean are "wasteful" targets unless the fit is tight.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // --- Last-chance bin: only one bin can fit this item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Strongly favor using the sole fitting bin over opening a new bin.
        score -= 40.0;
    }

    // --- New-bin candidate (brand-new empty bin) ---
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; scaled by how many bins are open.
        let mut new_bin_score = 45.0 + 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        new_bin_score -= 0.2 * item_size as f64;
        // If no open bin fits this item well, opening new is less painful.
        if fitting_bins_count == 0 {
            new_bin_score -= 30.0;
        }
        // Late in the stream, avoid scattering items across many bins.
        new_bin_score += 10.0 * progress;
        score = new_bin_score;
    }

    score
}
